    'timesheet_id', v_current_ts.timesheet_id,
    'current_timesheet_id', v_current_ts.timesheet_id,
    'current_timesheet_version', v_current_ts.version,
    'was_stale', v_was_stale,
    'created_now', v_created_now,
    'previous_contract_week_status', v_previous_contract_week_status,
    'new_contract_week_status', v_week.status::text,
    'previous_processing_status', v_previous_processing_status,
    'processing_status', v_current_tsfin.processing_status::text,
    'new_processing_status', v_current_tsfin.processing_status::text,
    'timesheet_financials_id', v_current_tsfin.id,
    'backend_row_signature', v_after_row_signature,
    'row_signature', v_after_row_signature,
    'expected_row_signature', v_after_row_signature,
    'lifecycle_signature_stable', v_after_row_signature IS NOT NULL,
    'lifecycle_signature_pending_reason', CASE WHEN v_after_row_signature IS NULL THEN 'POST_SAVE_ROW_SIGNATURE_UNAVAILABLE' ELSE NULL::text END,
    'requires_authorise_preflight', v_after_row_signature IS NULL,
    'requires_affected_row_refresh', v_after_row_signature IS NULL,
    'refresh_required', v_after_row_signature IS NULL,
    'permission_state_patch_complete', v_after_row_signature IS NOT NULL,
    'priority_badges_patch_complete', v_after_row_signature IS NOT NULL,
    'immediate_lifecycle_patch_available', v_after_row_signature IS NOT NULL,
    'lifecycle_patch', jsonb_strip_nulls(jsonb_build_object(
      'timesheet_id', v_current_ts.timesheet_id,
      'current_timesheet_id', v_current_ts.timesheet_id,
      'contract_week_id', v_week.id,
      'booking_id', v_current_ts.booking_id,
      'timesheet_status', v_current_ts.status::text,
      'status', v_current_ts.status::text,
      'contract_week_status', v_week.status::text,
      'processing_status', v_current_tsfin.processing_status::text,
      'tsfin_processing_status', v_current_tsfin.processing_status::text,
      'timesheet_financials_id', v_current_tsfin.id,
      'is_current', v_current_ts.is_current,
      'tsfin_is_current', v_current_tsfin.is_current,
      'authorised_at_server', v_current_ts.authorised_at_server,
      'revoked_at', v_current_ts.revoked_at,
      'row_signature', v_after_row_signature,
      'backend_row_signature', v_after_row_signature,
      'expected_row_signature', v_after_row_signature,
      'lifecycle_signature_stable', v_after_row_signature IS NOT NULL,
      'lifecycle_signature_pending_reason', CASE WHEN v_after_row_signature IS NULL THEN 'POST_SAVE_ROW_SIGNATURE_UNAVAILABLE' ELSE NULL::text END,
      'permission_state_patch_complete', v_after_row_signature IS NOT NULL,
      'priority_badges_patch_complete', v_after_row_signature IS NOT NULL,
      'immediate_lifecycle_patch_available', v_after_row_signature IS NOT NULL,
      'requires_network_before_authorise', v_after_row_signature IS NULL,
      'refresh_required', v_after_row_signature IS NULL,
      'row_stale', v_after_row_signature IS NULL,
      'lifecycle_refresh_failed', v_after_row_signature IS NULL
    )),
    'timesheet', jsonb_strip_nulls(jsonb_build_object(
      'timesheet_id', v_current_ts.timesheet_id,
      'contract_week_id', v_week.id,
      'booking_id', v_current_ts.booking_id,
      'status', v_current_ts.status::text,
      'is_current', v_current_ts.is_current,
      'authorised_at_server', v_current_ts.authorised_at_server,
      'revoked_at', v_current_ts.revoked_at,
      'row_signature', v_after_row_signature,
      'backend_row_signature', v_after_row_signature
    )),
    'tsfin', jsonb_strip_nulls(jsonb_build_object(
      'id', v_current_tsfin.id,
      'timesheet_id', v_current_tsfin.timesheet_id,
      'is_current', v_current_tsfin.is_current,
      'processing_status', v_current_tsfin.processing_status::text,
      'total_hours', v_current_tsfin.total_hours,
      'total_pay_ex_vat', v_current_tsfin.total_pay_ex_vat,
      'total_charge_ex_vat', v_current_tsfin.total_charge_ex_vat,
      'margin_ex_vat', v_current_tsfin.margin_ex_vat,
      'computed_at_utc', v_current_tsfin.computed_at_utc,
      'updated_at', v_current_tsfin.updated_at
    )),
    'summary_pay_state_refresh', COALESCE(v_summary_refresh_result, '{}'::jsonb),
    'evidence_summary', jsonb_build_object(
      'attached_evidence_count', v_attached_evidence_count,
      'attached_queue_count', v_attached_queue_count,
      'duplicate_queue_count', v_duplicate_queue_count,
      'primary_timesheet_storage_key', v_primary_timesheet_storage_key,
      'primary_timesheet_rotation_degrees', v_primary_timesheet_rotation_deg,
      'selected_queue_timesheet_queue_id', v_selected_queue_id,
      'selected_queue_timesheet_storage_key', v_selected_queue_storage_key
    ),
    'affected_rows', jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'timesheet_id', v_current_ts.timesheet_id,
      'current_timesheet_id', v_current_ts.timesheet_id,
      'contract_week_id', v_week.id,
      'booking_id', v_current_ts.booking_id,
      'timesheet_status', v_current_ts.status::text,
      'contract_week_status', v_week.status::text,
      'processing_status', v_current_tsfin.processing_status::text,
      'tsfin_processing_status', v_current_tsfin.processing_status::text,
      'row_signature', v_after_row_signature,
      'backend_row_signature', v_after_row_signature,
      'expected_row_signature', v_after_row_signature,
      'permission_state_patch_complete', v_after_row_signature IS NOT NULL,
      'priority_badges_patch_complete', v_after_row_signature IS NOT NULL,
      'immediate_lifecycle_patch_available', v_after_row_signature IS NOT NULL,
      'requires_network_before_authorise', v_after_row_signature IS NULL,
      'row_key', 'timesheet:' || v_current_ts.timesheet_id::text
    ))),
    'cache_invalidation_hints', jsonb_build_object(
      'changed_domains', jsonb_build_array('timesheets', 'timesheets_financials', 'timesheet_summary_pay_state_cache', 'timesheet_pay_state', 'contract_weeks', 'timesheet_evidence', 'manual_timesheet_queue'),
      'contract_week_id', v_week.id,
      'timesheet_id', v_current_ts.timesheet_id,
      'booking_id', v_current_ts.booking_id
    )
  ) || CASE
    WHEN private._candidate_feature_enabled_current_v1('candidate_record_role_capabilities') THEN
      jsonb_build_object(
        'candidate_record_role',v_candidate_final_state_guard->>'record_role',
        'candidate_expected_line_type',v_candidate_final_state_guard->>'expected_line_type',
        'candidate_final_state_guard',v_candidate_final_state_guard)
    ELSE '{}'::jsonb END;
EXCEPTION
  WHEN unique_violation THEN
    GET STACKED DIAGNOSTICS v_error_constraint = CONSTRAINT_NAME;

    IF COALESCE(v_temp_log_enabled, false) THEN
      v_diag_step_index := v_diag_step_index + 1;
      v_diag_elapsed_ms := ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 3);
      v_diag_duration_ms := ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_stage_started_at)) * 1000)::numeric, 3);
      PERFORM public._temp_diag_log(
        'TEMP_CONTRACT_WEEK_MANUAL_UPSERT_STAGE',
        'TEMP_TIMESHEET_LIFECYCLE',
        COALESCE(CASE WHEN v_current_ts.timesheet_id IS NULL THEN NULL ELSE v_current_ts.timesheet_id::text END, CASE WHEN v_pointer_ts.timesheet_id IS NULL THEN NULL ELSE v_pointer_ts.timesheet_id::text END, p_expected_timesheet_id::text, p_week_id::text),
        jsonb_strip_nulls(jsonb_build_object(
          'tag', 'TEMP_CONTRACT_WEEK_MANUAL_UPSERT_STAGE',
          'function_name', 'contract_week_manual_upsert_atomic',
          'stage', 'exception_unique_violation',
          'action', 'manual_upsert',
          'route_family', 'contract_week_manual_upsert',
          'step_index', v_diag_step_index,
          'elapsed_ms', v_diag_elapsed_ms,
          'duration_ms', v_diag_duration_ms,
          'contract_week_id', p_week_id,
          'timesheet_id', CASE WHEN v_current_ts.timesheet_id IS NULL THEN p_expected_timesheet_id ELSE v_current_ts.timesheet_id END,
          'constraint_name', v_error_constraint
        ))
      );
      v_diag_stage_started_at := clock_timestamp();
    END IF;
    IF v_error_constraint = 'uq_manual_timesheet_queue_one_active_staged_timesheet_per_contr' THEN
      RAISE EXCEPTION USING MESSAGE = 'STAGED_TIMESHEET_CONFLICT', DETAIL = jsonb_build_object('contract_week_id', p_week_id, 'constraint_name', v_error_constraint)::text;
    END IF;
    RAISE;
  WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_error_state = RETURNED_SQLSTATE, v_error_message = MESSAGE_TEXT;

    IF COALESCE(v_temp_log_enabled, false) THEN
      v_diag_step_index := v_diag_step_index + 1;
      v_diag_elapsed_ms := ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 3);
      v_diag_duration_ms := ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_stage_started_at)) * 1000)::numeric, 3);
      PERFORM public._temp_diag_log(
        'TEMP_CONTRACT_WEEK_MANUAL_UPSERT_STAGE',
        'TEMP_TIMESHEET_LIFECYCLE',
        COALESCE(CASE WHEN v_current_ts.timesheet_id IS NULL THEN NULL ELSE v_current_ts.timesheet_id::text END, CASE WHEN v_pointer_ts.timesheet_id IS NULL THEN NULL ELSE v_pointer_ts.timesheet_id::text END, p_expected_timesheet_id::text, p_week_id::text),
        jsonb_strip_nulls(jsonb_build_object(
          'tag', 'TEMP_CONTRACT_WEEK_MANUAL_UPSERT_STAGE',
          'function_name', 'contract_week_manual_upsert_atomic',
          'stage', 'exception_others',
          'action', 'manual_upsert',
          'route_family', 'contract_week_manual_upsert',
          'step_index', v_diag_step_index,
          'elapsed_ms', v_diag_elapsed_ms,
          'duration_ms', v_diag_duration_ms,
          'contract_week_id', p_week_id,
          'timesheet_id', CASE WHEN v_current_ts.timesheet_id IS NULL THEN p_expected_timesheet_id ELSE v_current_ts.timesheet_id END,
          'error_state', v_error_state,
          'error_message', v_error_message
        ))
      );
      v_diag_stage_started_at := clock_timestamp();
    END IF;
    IF v_error_state = '55P03' THEN
      RAISE EXCEPTION USING MESSAGE = 'LOCK_TIMEOUT', DETAIL = jsonb_build_object('contract_week_id', p_week_id, 'error_state', v_error_state)::text;
    END IF;
    RAISE;
END;
$function$;

-- public.pay_workbench_session_set_selected_rows from supabase/repeatable/04092026_2355_banking_pay_workbench_selection_owner_reassert_v1.sql; definition SHA-256 80b94a17dace174a7d42a8bafd12b0f6e178961bf9fea7a711fa3c4f7f99ee59.
CREATE OR REPLACE FUNCTION public.pay_workbench_session_set_selected_rows(p_session_id uuid, p_selected_preview_row_ids jsonb, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_input jsonb := COALESCE(p_selected_preview_row_ids, '[]'::jsonb);
  v_input_type text := COALESCE(jsonb_typeof(COALESCE(p_selected_preview_row_ids, '[]'::jsonb)), 'null');
  v_select_ids_source jsonb := '[]'::jsonb;
  v_deselect_ids_source jsonb := '[]'::jsonb;
  v_selected_ids jsonb := '[]'::jsonb;
  v_deselected_ids jsonb := '[]'::jsonb;
  v_missing_ids jsonb := '[]'::jsonb;
  v_stale_selection_ids jsonb := '[]'::jsonb;
  v_non_draftable_ids jsonb := '[]'::jsonb;
  v_conflicting_ids jsonb := '[]'::jsonb;
  v_server_selected_ids jsonb := '[]'::jsonb;
  v_current_selected_count integer := 0;
  v_selected_delta integer := 0;
  v_deselected_delta integer := 0;
  v_updated_count integer := 0;
  v_rejected_non_draftable_count integer := 0;
  v_forced_synthetic_cleanup_count integer := 0;
  v_replace_omitted_count integer := 0;
  v_replace_mode boolean := false;
  v_selection_mode text := 'ROW_PATCH_CAPPED_CONTRACT_GUARDED';
  v_global_selection_action text := '';
  v_requested_section text := 'canonical_preview_lines';
  v_resolved_selection_section text := 'canonical_preview_lines';
  v_audit_after_json jsonb := '{}'::jsonb;
  v_existing_selection_intent_mode text := '';
  v_next_selection_intent_mode text := '';
  v_next_server_selected_ids_provided boolean := false;
  v_expected_session_version bigint := NULL::bigint;
  v_expected_progress_counter_version bigint := NULL::bigint;
  v_expected_session_version_text text := '';
  v_expected_progress_counter_version_text text := '';
  v_next_progress_counter_version bigint := NULL::bigint;
  v_session_ready boolean := false;
  v_draft_blocker_codes jsonb := '[]'::jsonb;
  v_revalidation_candidate_id uuid := NULL::uuid;
  v_revalidation_result jsonb := '{}'::jsonb;
  v_selected_economic_identities jsonb := '[]'::jsonb;
BEGIN
  -- BEGIN BANKING_PAY_MODAL_CANDIDATE_DISPATCH_V2
  IF jsonb_typeof(p_selected_preview_row_ids)='object' AND (
    p_selected_preview_row_ids ? 'modal_candidate_intent_v2' OR p_selected_preview_row_ids ? 'modal_global_intent_v2'
    OR p_selected_preview_row_ids ? 'modal_group_intent_v2') THEN
    RETURN private.pay_workbench_modal_candidate_selection_apply_v2(p_session_id,p_selected_preview_row_ids,p_actor_user_id);
  END IF;
  -- END BANKING_PAY_MODAL_CANDIDATE_DISPATCH_V2
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  PERFORM 1
  FROM public.tms_users AS user_row
  WHERE user_row.id = p_actor_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not OPEN', p_session_id;
  END IF;

  IF v_input_type <> 'object' THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_CONTEXT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SESSION_CONTEXT_REQUIRED',
              'session_id', p_session_id::text,
              'message', 'The Banking Pay selection update must include the current workbench session and progress context.'
            )::text;
  END IF;

  IF v_input_type = 'object' THEN
    v_expected_session_version_text := NULLIF(BTRIM(COALESCE(
      v_input->>'expected_session_version',
      v_input->>'expectedSessionVersion',
      v_input->>'session_version',
      v_input->>'sessionVersion',
      ''
    )), '');
    v_expected_progress_counter_version_text := NULLIF(BTRIM(COALESCE(
      v_input->>'expected_progress_counter_version',
      v_input->>'expectedProgressCounterVersion',
      v_input->>'progress_counter_version',
      v_input->>'progressCounterVersion',
      ''
    )), '');

    IF v_expected_session_version_text IS NOT NULL THEN
      IF v_expected_session_version_text !~ '^[0-9]{1,18}$' THEN
        RAISE EXCEPTION 'WORKBENCH_SESSION_VERSION_CONTEXT_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'WORKBENCH_SESSION_VERSION_CONTEXT_INVALID',
                  'session_id', p_session_id::text,
                  'provided_session_version', v_expected_session_version_text
                )::text;
      END IF;
      v_expected_session_version := v_expected_session_version_text::bigint;
    END IF;

    IF v_expected_progress_counter_version_text IS NOT NULL THEN
      IF v_expected_progress_counter_version_text !~ '^[0-9]{1,18}$' THEN
        RAISE EXCEPTION 'WORKBENCH_SESSION_PROGRESS_CONTEXT_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'WORKBENCH_SESSION_PROGRESS_CONTEXT_INVALID',
                  'session_id', p_session_id::text,
                  'provided_progress_counter_version', v_expected_progress_counter_version_text
                )::text;
      END IF;
      v_expected_progress_counter_version := v_expected_progress_counter_version_text::bigint;
    END IF;
  END IF;

  IF v_expected_session_version IS NULL THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_VERSION_CONTEXT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SESSION_VERSION_CONTEXT_REQUIRED',
              'session_id', p_session_id::text,
              'current_session_version', COALESCE(v_session_row.version, 0),
              'message', 'The Banking Pay selection update was missing the current session version. Refresh the preview before changing the selection.'
            )::text;
  END IF;

  IF v_expected_progress_counter_version IS NULL THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_PROGRESS_CONTEXT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SESSION_PROGRESS_CONTEXT_REQUIRED',
              'session_id', p_session_id::text,
              'current_progress_counter_version', COALESCE(v_session_row.progress_counter_version, 0),
              'message', 'The Banking Pay selection update was missing the current progress version. Refresh the preview before changing the selection.'
            )::text;
  END IF;

  IF COALESCE(v_session_row.version, 0) IS DISTINCT FROM v_expected_session_version THEN
    RAISE EXCEPTION 'STALE_SESSION'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'STALE_SESSION',
              'session_id', p_session_id::text,
              'expected_session_version', v_expected_session_version,
              'current_session_version', COALESCE(v_session_row.version, 0)
            )::text;
  END IF;

  IF COALESCE(v_session_row.progress_counter_version, 0) IS DISTINCT FROM v_expected_progress_counter_version THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_PROGRESS_CHANGED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SESSION_PROGRESS_CHANGED',
              'session_id', p_session_id::text,
              'expected_progress_counter_version', v_expected_progress_counter_version,
              'current_progress_counter_version', COALESCE(v_session_row.progress_counter_version, 0),
              'message', 'The Banking Pay workbench changed in another window. Refresh the preview before changing the selection.'
            )::text;
  END IF;

  v_existing_selection_intent_mode := UPPER(BTRIM(COALESCE(
    v_session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
    ''
  )));
  IF v_existing_selection_intent_mode NOT IN ('IMPLICIT_ALL', 'EXPLICIT_INCLUDE') THEN
    v_existing_selection_intent_mode := '';
  END IF;

  IF v_input_type = 'array' THEN
    v_replace_mode := true;
    v_select_ids_source := v_input;
    v_deselect_ids_source := '[]'::jsonb;
  ELSIF v_input_type = 'object' THEN
    v_select_ids_source := CASE
      WHEN jsonb_typeof(v_input->'select_preview_row_ids') = 'array' THEN COALESCE(v_input->'select_preview_row_ids', '[]'::jsonb)
      WHEN jsonb_typeof(v_input->'selected_preview_row_ids') = 'array' THEN COALESCE(v_input->'selected_preview_row_ids', '[]'::jsonb)
      WHEN jsonb_typeof(v_input->'select_row_ids') = 'array' THEN COALESCE(v_input->'select_row_ids', '[]'::jsonb)
      ELSE '[]'::jsonb
    END;
    v_deselect_ids_source := CASE
      WHEN jsonb_typeof(v_input->'deselect_preview_row_ids') = 'array' THEN COALESCE(v_input->'deselect_preview_row_ids', '[]'::jsonb)
      WHEN jsonb_typeof(v_input->'deselected_preview_row_ids') = 'array' THEN COALESCE(v_input->'deselected_preview_row_ids', '[]'::jsonb)
      WHEN jsonb_typeof(v_input->'deselect_row_ids') = 'array' THEN COALESCE(v_input->'deselect_row_ids', '[]'::jsonb)
      ELSE '[]'::jsonb
    END;
    v_replace_mode :=
      LOWER(BTRIM(COALESCE(
        v_input->>'replace_selected_preview_row_ids',
        v_input->>'replaceSelectedPreviewRowIds',
        v_input->>'replace_selected_rows',
        v_input->>'replaceSelectedRows',
        v_input->>'replace',
        'false'
      ))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR LOWER(BTRIM(COALESCE(
        v_input->>'selected_preview_row_ids_provided',
        v_input->>'selectedPreviewRowIdsProvided',
        v_input->>'server_selected_preview_row_ids_provided',
        v_input->>'serverSelectedPreviewRowIdsProvided',
        v_input->>'selected_rows_provided',
        v_input->>'selectedRowsProvided',
        'false'
      ))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(
        v_input->>'selection_mode',
        v_input->>'selectionMode',
        v_input->>'mode',
        ''
      ))) IN (
        'EXPLICIT_REPLACE',
        'AUTHORITATIVE_REPLACE',
        'REPLACE',
        'REPLACE_SELECTED_ROWS',
        'REPLACE_SELECTED_PREVIEW_ROW_IDS',
        'SET',
        'SET_SELECTED_ROWS',
        'SET_SELECTED_PREVIEW_ROW_IDS'
      );

    v_requested_section := LOWER(BTRIM(COALESCE(
      v_input->>'section',
      v_input->>'section_key',
      v_input->>'sectionKey',
      v_input->>'selection_section',
      v_input->>'selectionSection',
      'canonical_preview_lines'
    )));
    v_requested_section := REGEXP_REPLACE(v_requested_section, '[^a-z0-9_]+', '_', 'g');
    v_requested_section := BTRIM(v_requested_section, '_');
    v_resolved_selection_section := CASE
      WHEN v_requested_section IN ('', 'ready', 'ready_to_pay', 'ready_preview_lines', 'preview_rows', 'canonical_preview_lines') THEN 'canonical_preview_lines'
      WHEN v_requested_section IN ('cases', 'case_resolutions', 'case_resolution_states', 'cases_resolutions') THEN 'cases_resolutions'
      WHEN v_requested_section IN ('blocked', 'blocked_now', 'blocked_preview_lines', 'blocked_items', 'blocked_for_pay') THEN 'blocked_for_pay'
      ELSE v_requested_section
    END;

    v_global_selection_action := UPPER(BTRIM(COALESCE(
      v_input->>'selection_action',
      v_input->>'selectionAction',
      v_input->>'global_selection_action',
      v_input->>'globalSelectionAction',
      v_input->>'action',
      ''
    )));
    v_global_selection_action := REGEXP_REPLACE(v_global_selection_action, '[^A-Z0-9_]+', '_', 'g');
    v_global_selection_action := BTRIM(v_global_selection_action, '_');

    IF v_global_selection_action = '' THEN
      v_global_selection_action := CASE
        WHEN UPPER(BTRIM(COALESCE(v_input->>'selection_mode', v_input->>'selectionMode', v_input->>'mode', ''))) IN (
          'IMPLICIT_ALL', 'SELECT_ALL', 'SELECT_ALL_SECTION', 'SELECT_SECTION', 'SELECT_ALL_READY_TO_PAY'
        ) THEN 'SELECT_ALL_SECTION'
        WHEN UPPER(BTRIM(COALESCE(v_input->>'selection_mode', v_input->>'selectionMode', v_input->>'mode', ''))) IN (
          'EXPLICIT_NONE', 'CLEAR_ALL', 'CLEAR_SECTION', 'DESELECT_ALL', 'DESELECT_ALL_SECTION', 'CLEAR_SELECTED_ROWS'
        ) THEN 'CLEAR_SECTION'
        ELSE ''
      END;
    END IF;

    IF v_global_selection_action IN ('SELECT_ALL', 'SELECT_SECTION', 'SELECT_ALL_READY_TO_PAY') THEN
      v_global_selection_action := 'SELECT_ALL_SECTION';
    ELSIF v_global_selection_action IN ('CLEAR_ALL', 'DESELECT_ALL', 'DESELECT_ALL_SECTION', 'CLEAR_SELECTED_ROWS') THEN
      v_global_selection_action := 'CLEAR_SECTION';
    END IF;

    IF v_global_selection_action <> '' THEN
      v_replace_mode := false;
      v_select_ids_source := '[]'::jsonb;
      v_deselect_ids_source := '[]'::jsonb;
    END IF;
  ELSE
    RAISE EXCEPTION 'selected_preview_row_ids must be a JSON array or object';
  END IF;

  v_selection_mode := CASE
    WHEN v_replace_mode THEN 'REPLACE_CAPPED_CONTRACT_GUARDED'
    ELSE 'ROW_PATCH_CAPPED_CONTRACT_GUARDED'
  END;

  IF jsonb_array_length(v_select_ids_source) > 100 OR jsonb_array_length(v_deselect_ids_source) > 100 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SESSION_SET_SELECTED_ROWS_INPUT_TOO_LARGE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SESSION_SET_SELECTED_ROWS_INPUT_TOO_LARGE',
              'session_id', p_session_id::text,
              'select_count', jsonb_array_length(v_select_ids_source),
              'deselect_count', jsonb_array_length(v_deselect_ids_source),
              'max_per_call', 100
            )::text;
  END IF;


  IF v_global_selection_action <> '' THEN
    IF v_global_selection_action NOT IN ('SELECT_ALL_SECTION', 'CLEAR_SECTION') THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SESSION_SET_SELECTED_ROWS_UNSUPPORTED_GLOBAL_ACTION'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_SESSION_SET_SELECTED_ROWS_UNSUPPORTED_GLOBAL_ACTION',
                'session_id', p_session_id::text,
                'selection_action', v_global_selection_action
              )::text;
    END IF;

    IF v_resolved_selection_section <> 'canonical_preview_lines' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SESSION_SET_SELECTED_ROWS_SECTION_NOT_SELECTABLE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_SESSION_SET_SELECTED_ROWS_SECTION_NOT_SELECTABLE',
                'session_id', p_session_id::text,
                'requested_section', v_requested_section,
                'resolved_section', v_resolved_selection_section,
                'message', 'Only Ready to Pay canonical preview rows are draft-selectable.'
              )::text;
    END IF;

    v_selection_mode := CASE
      WHEN v_global_selection_action = 'SELECT_ALL_SECTION' THEN 'SECTION_SELECT_ALL_CONTRACT_GUARDED'
      ELSE 'SECTION_CLEAR_CONTRACT_GUARDED'
    END;
    v_next_selection_intent_mode := CASE
      WHEN v_global_selection_action IN ('SELECT_ALL_SECTION', 'CLEAR_SECTION') THEN 'IMPLICIT_ALL'
      ELSE 'EXPLICIT_INCLUDE'
    END;

    DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_global_selection_candidates;
    CREATE TEMP TABLE _tmp_pay_wb_global_selection_candidates ON COMMIT DROP AS
    SELECT DISTINCT preview_row.candidate_id
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = p_session_id
      AND preview_row.session_version = v_session_row.version
      AND lower(private.pay_workbench_preview_effective_section_v1(preview_row.section, preview_row.row_json)) = 'canonical_preview_lines'
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
      AND preview_row.candidate_id IS NOT NULL;

    IF v_global_selection_action = 'SELECT_ALL_SECTION' THEN
      DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_global_selection_rows;
      CREATE TEMP TABLE _tmp_pay_wb_global_selection_rows ON COMMIT DROP AS
      SELECT preview_row.id,
             preview_row.row_ordinal,
             preview_row.row_key,
             COALESCE(preview_row.selected, false) AS was_selected,
             contract_check.contract_json,
             synthetic_check.is_synthetic_resolved_total,
             (
               LOWER(BTRIM(COALESCE(contract_check.contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
               AND LOWER(BTRIM(COALESCE(contract_check.contract_json->>'materialisable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
               AND LOWER(BTRIM(COALESCE(contract_check.contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
               AND COALESCE(contract_check.contract_json->>'target_section', '') = 'canonical_preview_lines'
               AND UPPER(BTRIM(COALESCE(contract_check.contract_json->>'presentation_section', ''))) = 'READY_TO_PAY'
               AND LOWER(BTRIM(COALESCE(contract_check.contract_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
               AND LOWER(BTRIM(COALESCE(contract_check.contract_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
               AND COALESCE(contract_check.contract_json->>'key_type', '') <> ''
               AND COALESCE(contract_check.contract_json->>'key_value', '') <> ''
               AND (
                 UPPER(BTRIM(COALESCE(contract_check.contract_json->>'key_type', ''))) <> 'TS_DAY'
                 OR COALESCE(contract_check.contract_json->>'key_value', '') ~ '^\d{4}-\d{2}-\d{2}$'
               )
               AND UPPER(BTRIM(COALESCE(contract_check.contract_json->>'source_kind', ''))) NOT IN (
                 'TIMESHEET_SNAPSHOT',
                 'TIMESHEET_SNAPSHOT_EVIDENCE',
                 'RAW_TIMESHEET_SNAPSHOT',
                 'INTERNAL_ONLY',
                 'NO_DELTA',
                 'EXCLUDED'
               )
               AND preview_row.row_key NOT LIKE 'timesheet_snapshot:%'
               AND synthetic_check.is_synthetic_resolved_total IS NOT TRUE
             ) AS is_selectable
      FROM public.banking_pay_workbench_preview_rows AS preview_row
      CROSS JOIN LATERAL (
        SELECT public.pay_workbench_preview_line_contract_ok(
          p_line_json => COALESCE(preview_row.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'line_key', preview_row.row_key,
              'row_key', preview_row.row_key,
              'section', private.pay_workbench_preview_effective_section_v1(preview_row.section, preview_row.row_json),
              'target_section', private.pay_workbench_preview_effective_section_v1(preview_row.section, preview_row.row_json),
              'key_type', preview_row.key_type,
              'key_value', preview_row.key_value
            ),
          p_economic_key_json => jsonb_build_object(
            'key_type', preview_row.key_type,
            'key_value', preview_row.key_value
          ),
          p_target_section => private.pay_workbench_preview_effective_section_v1(preview_row.section, preview_row.row_json)
        ) AS contract_json
      ) AS contract_check
      CROSS JOIN LATERAL (
        SELECT (
          preview_row.timesheet_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(
            preview_row.key_type,
            preview_row.row_json#>>'{economic_key,key_type}',
            preview_row.row_json->>'component_key_type',
            preview_row.row_json->>'key_type',
            ''
          ))) = 'TS_TOTAL'
          AND UPPER(BTRIM(COALESCE(
            preview_row.key_value,
            preview_row.row_json#>>'{economic_key,key_value}',
            preview_row.row_json->>'component_key_value',
            preview_row.row_json->>'key_value',
            ''
          ))) = 'TOTAL'
          AND LOWER(BTRIM(COALESCE(
            preview_row.row_key,
            preview_row.row_json->>'row_key',
            preview_row.row_json->>'line_key',
            preview_row.row_json->>'source_ref',
            preview_row.row_json#>>'{source_basis,row_key}',
            preview_row.row_json#>>'{source_basis,line_key}',
            preview_row.row_json#>>'{source_basis,source_ref}',
            preview_row.row_json#>>'{source_basis_json,row_key}',
            preview_row.row_json#>>'{source_basis_json,line_key}',
            preview_row.row_json#>>'{source_basis_json,source_ref}',
            ''
          ))) LIKE '%:non_segment:total%'
          AND EXISTS (
            SELECT 1
            FROM public.banking_pay_workbench_preview_rows AS sibling_row
            WHERE sibling_row.session_id = preview_row.session_id
              AND sibling_row.session_version = preview_row.session_version
              AND sibling_row.id <> preview_row.id
              AND sibling_row.timesheet_id = preview_row.timesheet_id
              AND lower(private.pay_workbench_preview_effective_section_v1(sibling_row.section, sibling_row.row_json)) = 'canonical_preview_lines'
              AND UPPER(BTRIM(COALESCE(sibling_row.status, ''))) = 'READY'
              AND UPPER(BTRIM(COALESCE(
                sibling_row.key_type,
                sibling_row.row_json#>>'{economic_key,key_type}',
                sibling_row.row_json->>'component_key_type',
                sibling_row.row_json->>'key_type',
                ''
              ))) = 'TS_DAY'
              AND COALESCE(
                sibling_row.key_value,
                sibling_row.row_json#>>'{economic_key,key_value}',
                sibling_row.row_json->>'component_key_value',
                sibling_row.row_json->>'key_value',
                ''
              ) ~ '^\d{4}-\d{2}-\d{2}$'
          )
        ) AS is_synthetic_resolved_total
      ) AS synthetic_check
      WHERE preview_row.session_id = p_session_id
        AND preview_row.session_version = v_session_row.version
        AND lower(private.pay_workbench_preview_effective_section_v1(preview_row.section, preview_row.row_json)) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY';

      WITH updated_rows AS (
        UPDATE public.banking_pay_workbench_preview_rows AS preview_row
        SET selected = true,
            selection_state = 'SELECTED',
            row_json = COALESCE(preview_row.row_json, '{}'::jsonb)
              || jsonb_build_object(
                'selected', true,
                'selection_state', 'SELECTED',
                'selection_user_override', 'SELECTED',
                'selection_origin', 'USER_GLOBAL_SELECT_ALL',
                'selection_user_override_at_utc', v_now::text
              ),
            updated_at_utc = v_now
        FROM pg_temp._tmp_pay_wb_global_selection_rows AS global_rows
        WHERE preview_row.id = global_rows.id
          AND global_rows.is_selectable IS TRUE
          AND (
            COALESCE(preview_row.selected, false) IS DISTINCT FROM true
            OR UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) <> 'SELECTED'
          )
        RETURNING preview_row.id,
                  global_rows.was_selected,
                  global_rows.row_ordinal
      )
      SELECT COALESCE(jsonb_agg(to_jsonb(updated_rows.id::text) ORDER BY updated_rows.row_ordinal, updated_rows.id), '[]'::jsonb),
             COUNT(*)::integer,
             COUNT(*)::integer
      INTO v_selected_ids, v_selected_delta, v_updated_count
      FROM updated_rows;

      WITH cleanup_rows AS (
        UPDATE public.banking_pay_workbench_preview_rows AS preview_row
        SET selected = false,
            selection_state = 'UNSELECTED',
            row_json = COALESCE(preview_row.row_json, '{}'::jsonb)
              || jsonb_build_object(
                'selected', false,
                'selection_state', 'UNSELECTED',
                'selection_user_override', 'UNSELECTED',
                'selection_origin', 'USER_GLOBAL_CLEAR',
                'selection_user_override_at_utc', v_now::text
              ),
            updated_at_utc = v_now
        FROM pg_temp._tmp_pay_wb_global_selection_rows AS global_rows
        WHERE preview_row.id = global_rows.id
          AND global_rows.is_synthetic_resolved_total IS TRUE
          AND COALESCE(preview_row.selected, false) = true
        RETURNING preview_row.id
      )
      SELECT COUNT(*)::integer
      INTO v_forced_synthetic_cleanup_count
      FROM cleanup_rows;

      v_deselected_delta := COALESCE(v_forced_synthetic_cleanup_count, 0);
      v_updated_count := COALESCE(v_updated_count, 0) + COALESCE(v_forced_synthetic_cleanup_count, 0);
    ELSE
      WITH updated_rows AS (
        UPDATE public.banking_pay_workbench_preview_rows AS preview_row
        SET selected = false,
            selection_state = 'UNSELECTED',
            row_json = COALESCE(preview_row.row_json, '{}'::jsonb)
              || jsonb_build_object(
                'selected', false,
                'selection_state', 'UNSELECTED'
              ),
            updated_at_utc = v_now
        WHERE preview_row.session_id = p_session_id
          AND preview_row.session_version = v_session_row.version
          AND lower(private.pay_workbench_preview_effective_section_v1(preview_row.section, preview_row.row_json)) = 'canonical_preview_lines'
          AND COALESCE(preview_row.selected, false) = true
        RETURNING preview_row.id, preview_row.row_ordinal
      )
      SELECT COALESCE(jsonb_agg(to_jsonb(updated_rows.id::text) ORDER BY updated_rows.row_ordinal, updated_rows.id), '[]'::jsonb),
             COUNT(*)::integer,
             COUNT(*)::integer
      INTO v_deselected_ids, v_deselected_delta, v_updated_count
      FROM updated_rows;
    END IF;

    DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_current_selected_rows;
    CREATE TEMP TABLE _tmp_pay_wb_current_selected_rows ON COMMIT DROP AS
    SELECT selected_count_row.id,
           selected_count_row.candidate_id,
           selected_count_row.row_ordinal,
           selected_count_row.row_key,
           selected_count_row.row_json,
           selected_count_row.timesheet_id,
           selected_count_row.key_type,
           selected_count_row.key_value,
           selected_contract.contract_json,
           synthetic_check.is_synthetic_resolved_total
    FROM public.banking_pay_workbench_preview_rows AS selected_count_row
    CROSS JOIN LATERAL (
      SELECT public.pay_workbench_preview_line_contract_ok(
        p_line_json => COALESCE(selected_count_row.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'line_key', selected_count_row.row_key,
            'row_key', selected_count_row.row_key,
            'section', private.pay_workbench_preview_effective_section_v1(selected_count_row.section, selected_count_row.row_json),
            'target_section', private.pay_workbench_preview_effective_section_v1(selected_count_row.section, selected_count_row.row_json),
            'key_type', selected_count_row.key_type,
            'key_value', selected_count_row.key_value
          ),
        p_economic_key_json => jsonb_build_object(
          'key_type', selected_count_row.key_type,
          'key_value', selected_count_row.key_value
        ),
        p_target_section => private.pay_workbench_preview_effective_section_v1(selected_count_row.section, selected_count_row.row_json)
      ) AS contract_json
    ) AS selected_contract
    CROSS JOIN LATERAL (
      SELECT (
        selected_count_row.timesheet_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(
          selected_count_row.key_type,
          selected_count_row.row_json#>>'{economic_key,key_type}',
          selected_count_row.row_json->>'component_key_type',
          selected_count_row.row_json->>'key_type',
          ''
        ))) = 'TS_TOTAL'
        AND UPPER(BTRIM(COALESCE(
          selected_count_row.key_value,
          selected_count_row.row_json#>>'{economic_key,key_value}',
          selected_count_row.row_json->>'component_key_value',
          selected_count_row.row_json->>'key_value',
          ''
        ))) = 'TOTAL'
        AND LOWER(BTRIM(COALESCE(
          selected_count_row.row_key,
          selected_count_row.row_json->>'row_key',
          selected_count_row.row_json->>'line_key',
          selected_count_row.row_json->>'source_ref',
          selected_count_row.row_json#>>'{source_basis,row_key}',
          selected_count_row.row_json#>>'{source_basis,line_key}',
          selected_count_row.row_json#>>'{source_basis,source_ref}',
          selected_count_row.row_json#>>'{source_basis_json,row_key}',
          selected_count_row.row_json#>>'{source_basis_json,line_key}',
          selected_count_row.row_json#>>'{source_basis_json,source_ref}',
          ''
        ))) LIKE '%:non_segment:total%'
        AND EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_preview_rows AS sibling_row
          WHERE sibling_row.session_id = selected_count_row.session_id
            AND sibling_row.session_version = selected_count_row.session_version
            AND sibling_row.id <> selected_count_row.id
            AND sibling_row.timesheet_id = selected_count_row.timesheet_id
            AND lower(private.pay_workbench_preview_effective_section_v1(sibling_row.section, sibling_row.row_json)) = 'canonical_preview_lines'
            AND UPPER(BTRIM(COALESCE(sibling_row.status, ''))) = 'READY'
            AND UPPER(BTRIM(COALESCE(
              sibling_row.key_type,
              sibling_row.row_json#>>'{economic_key,key_type}',
              sibling_row.row_json->>'component_key_type',
              sibling_row.row_json->>'key_type',
              ''
            ))) = 'TS_DAY'
            AND COALESCE(
              sibling_row.key_value,
              sibling_row.row_json#>>'{economic_key,key_value}',
              sibling_row.row_json->>'component_key_value',
              sibling_row.row_json->>'key_value',
              ''
            ) ~ '^\d{4}-\d{2}-\d{2}$'
        )
      ) AS is_synthetic_resolved_total
    ) AS synthetic_check
    WHERE selected_count_row.session_id = p_session_id
      AND selected_count_row.session_version = v_session_row.version
      AND lower(private.pay_workbench_preview_effective_section_v1(selected_count_row.section, selected_count_row.row_json)) = 'canonical_preview_lines'
      AND UPPER(BTRIM(COALESCE(selected_count_row.status, ''))) = 'READY'
      AND COALESCE(selected_count_row.selected, false) = true
      AND UPPER(BTRIM(COALESCE(selected_count_row.selection_state, ''))) = 'SELECTED';

    SELECT COALESCE(jsonb_agg(to_jsonb(current_selected.id::text) ORDER BY current_selected.row_ordinal, current_selected.id), '[]'::jsonb),
           COUNT(*)::integer
    INTO v_selected_ids, v_current_selected_count
    FROM pg_temp._tmp_pay_wb_current_selected_rows AS current_selected
    WHERE LOWER(BTRIM(COALESCE(current_selected.contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(current_selected.contract_json->>'materialisable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(current_selected.contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND COALESCE(current_selected.contract_json->>'target_section', '') = 'canonical_preview_lines'
      AND UPPER(BTRIM(COALESCE(current_selected.contract_json->>'presentation_section', ''))) = 'READY_TO_PAY'
      AND LOWER(BTRIM(COALESCE(current_selected.contract_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(current_selected.contract_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND COALESCE(current_selected.contract_json->>'key_type', '') <> ''
      AND COALESCE(current_selected.contract_json->>'key_value', '') <> ''
      AND (
        UPPER(BTRIM(COALESCE(current_selected.contract_json->>'key_type', ''))) <> 'TS_DAY'
        OR COALESCE(current_selected.contract_json->>'key_value', '') ~ '^\d{4}-\d{2}-\d{2}$'
      )
      AND UPPER(BTRIM(COALESCE(current_selected.contract_json->>'source_kind', ''))) NOT IN (
        'TIMESHEET_SNAPSHOT',
        'TIMESHEET_SNAPSHOT_EVIDENCE',
        'RAW_TIMESHEET_SNAPSHOT',
        'INTERNAL_ONLY',
        'NO_DELTA',
        'EXCLUDED'
      )
      AND current_selected.row_key NOT LIKE 'timesheet_snapshot:%'
      AND current_selected.is_synthetic_resolved_total IS NOT TRUE;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'candidate_id',current_selected.candidate_id,
      'row_key',current_selected.row_key,
      'timesheet_id',current_selected.timesheet_id,
      'key_type',current_selected.key_type,
      'key_value',current_selected.key_value
    ) ORDER BY current_selected.candidate_id,current_selected.row_key,current_selected.id),'[]'::jsonb)
    INTO v_selected_economic_identities
    FROM pg_temp._tmp_pay_wb_current_selected_rows AS current_selected
    WHERE current_selected.id IN (
      SELECT selected_id.value::uuid
      FROM jsonb_array_elements_text(COALESCE(v_selected_ids,'[]'::jsonb)) AS selected_id(value)
    );

    v_server_selected_ids := COALESCE(v_selected_ids, '[]'::jsonb);
    v_session_ready := LOWER(BTRIM(COALESCE(
      v_session_row.progress_json->>'ready',
      v_session_row.progress_json->>'session_ready',
      v_session_row.progress_json->>'ready_flag',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on');

    SELECT COALESCE(jsonb_agg(to_jsonb(blocker_code.value) ORDER BY blocker_code.ordinality), '[]'::jsonb)
    INTO v_draft_blocker_codes
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_session_row.progress_json->'draft_blocker_codes') = 'array'
          THEN v_session_row.progress_json->'draft_blocker_codes'
        ELSE '[]'::jsonb
      END
    ) WITH ORDINALITY AS blocker_code(value, ordinality)
    WHERE UPPER(BTRIM(blocker_code.value)) <> 'NO_SELECTED_ROWS';

    IF v_session_ready AND COALESCE(v_current_selected_count, 0) = 0 THEN
      v_draft_blocker_codes := COALESCE(v_draft_blocker_codes, '[]'::jsonb)
        || jsonb_build_array('NO_SELECTED_ROWS');
    END IF;

    UPDATE public.banking_pay_workbench_sessions AS session_row
    SET selected_row_count = COALESCE(v_current_selected_count, 0),
        server_selected_preview_row_ids = COALESCE(v_server_selected_ids, '[]'::jsonb),
        server_selected_preview_row_ids_provided = true,
        progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'last_selection_update_at_utc', v_now::text,
            'last_selection_selected_delta', COALESCE(v_selected_delta, 0),
            'last_selection_deselected_delta', COALESCE(v_deselected_delta, 0),
            'last_selection_rejected_non_draftable_count', COALESCE(v_rejected_non_draftable_count, 0),
            'last_selection_mode', v_selection_mode,
            'last_selection_action', v_global_selection_action,
            'last_selection_section', v_resolved_selection_section,
            'last_selection_forced_synthetic_cleanup_count', COALESCE(v_forced_synthetic_cleanup_count, 0),
            'last_selection_replace_omitted_count', COALESCE(v_replace_omitted_count, 0),
            'selected_row_count', COALESCE(v_current_selected_count, 0),
            'selected_eligible_ready_row_count', COALESCE(v_current_selected_count, 0),
            'selected_rows_available', COALESCE(v_current_selected_count, 0) > 0,
            'ready_for_draft', v_session_ready AND COALESCE(v_current_selected_count, 0) > 0,
            'can_create_draft', v_session_ready AND COALESCE(v_current_selected_count, 0) > 0,
            'draft_blocker_codes', COALESCE(v_draft_blocker_codes, '[]'::jsonb),
            'blocker_codes', COALESCE(v_draft_blocker_codes, '[]'::jsonb),
            'selection_intent_v1', COALESCE(session_row.progress_json->'selection_intent_v1', '{}'::jsonb)
              || jsonb_build_object(
                'canonical_preview_lines', jsonb_build_object(
                  'mode', COALESCE(v_next_selection_intent_mode, 'IMPLICIT_ALL'),
                  'section', 'canonical_preview_lines',
                  'identity', 'preview_row_id_with_session_section_candidate_row_key_conflict_identity',
                  'updated_at_utc', v_now::text,
                  'updated_by_user_id', p_actor_user_id::text,
                  'source_selection_mode', v_selection_mode,
                  'source_selection_action', v_global_selection_action,
                  'server_selected_preview_row_ids_provided', true,
                  'selected_row_count', COALESCE(v_current_selected_count, 0),
                  'selected_economic_identities',COALESCE(v_selected_economic_identities,'[]'::jsonb),
                  'identity_contract_version',2
                )
              )
          ),
        progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    WHERE session_row.id = p_session_id
    RETURNING session_row.progress_counter_version
    INTO v_next_progress_counter_version;

    FOR v_revalidation_candidate_id IN
      SELECT changed_candidate.candidate_id
      FROM pg_temp._tmp_pay_wb_global_selection_candidates AS changed_candidate
    LOOP
      v_revalidation_result := public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(
        p_session_id,
        v_revalidation_candidate_id
      );
    END LOOP;

    SELECT session_row.progress_counter_version
    INTO v_next_progress_counter_version
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = p_session_id;

    SELECT COALESCE(jsonb_agg(to_jsonb(selected_row.id::text) ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb),
           COUNT(*)::integer
    INTO v_selected_ids,
         v_current_selected_count
    FROM public.banking_pay_workbench_preview_rows AS selected_row
    WHERE selected_row.session_id = p_session_id
      AND selected_row.session_version = v_session_row.version
      AND LOWER(private.pay_workbench_preview_effective_section_v1(selected_row.section, selected_row.row_json)) = 'canonical_preview_lines'
      AND UPPER(BTRIM(COALESCE(selected_row.status, ''))) = 'READY'
      AND COALESCE(selected_row.selected, false) IS TRUE
      AND UPPER(BTRIM(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

    v_server_selected_ids := COALESCE(v_selected_ids, '[]'::jsonb);

    v_audit_after_json := jsonb_build_object(
      'id', p_session_id::text,
      'selection_mode', v_selection_mode,
      'selection_action', v_global_selection_action,
      'selection_section', v_resolved_selection_section,
      'selection_intent_mode', COALESCE(v_next_selection_intent_mode, 'IMPLICIT_ALL'),
      'selected_preview_row_ids', COALESCE(v_selected_ids, '[]'::jsonb),
      'deselected_preview_row_ids', COALESCE(v_deselected_ids, '[]'::jsonb),
      'updated_preview_row_count', COALESCE(v_updated_count, 0),
      'selected_delta', COALESCE(v_selected_delta, 0),
      'deselected_delta', COALESCE(v_deselected_delta, 0),
      'forced_synthetic_cleanup_count', COALESCE(v_forced_synthetic_cleanup_count, 0),
      'server_selected_preview_row_ids_provided', true,
      'updated_at_utc', v_now
    );

    PERFORM public._audit_insert(
      'banking_pay_workbench_session',
      p_session_id::text,
      CASE WHEN v_global_selection_action = 'SELECT_ALL_SECTION' THEN 'SESSION_SELECTED_ROWS_SECTION_SELECTED' ELSE 'SESSION_SELECTED_ROWS_SECTION_CLEARED' END,
      NULL::jsonb,
      v_audit_after_json,
      CASE WHEN v_global_selection_action = 'SELECT_ALL_SECTION' THEN 'SESSION_SELECTED_ROWS_SECTION_SELECTED' ELSE 'SESSION_SELECTED_ROWS_SECTION_CLEARED' END,
      p_actor_user_id
    );

    RETURN jsonb_build_object(
      'ok', true,
      'session_id', p_session_id::text,
      'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
      'session_version', v_session_row.version,
      'progress_counter_version', COALESCE(v_next_progress_counter_version, COALESCE(v_session_row.progress_counter_version, 0) + 1),
      'expected_session_version', v_expected_session_version,
      'expected_progress_counter_version', v_expected_progress_counter_version,
      'selection_action', v_global_selection_action,
      'selection_section', v_resolved_selection_section,
      'selection_intent_mode', COALESCE(v_next_selection_intent_mode, 'IMPLICIT_ALL'),
      'selected_preview_row_ids', COALESCE(v_selected_ids, '[]'::jsonb),
      'deselected_preview_row_ids', COALESCE(v_deselected_ids, '[]'::jsonb),
      'selected_preview_row_ids_provided', true,
      'server_selected_preview_row_ids', COALESCE(v_server_selected_ids, '[]'::jsonb),
      'server_selected_preview_row_ids_provided', true,
      'selected_delta', COALESCE(v_selected_delta, 0),
      'deselected_delta', COALESCE(v_deselected_delta, 0),
      'updated_preview_row_count', COALESCE(v_updated_count, 0),
      'dropped_non_draftable_preview_row_ids', COALESCE(v_non_draftable_ids, '[]'::jsonb),
      'rejected_non_draftable_preview_row_ids', COALESCE(v_non_draftable_ids, '[]'::jsonb),
      'rejected_non_draftable_preview_row_count', COALESCE(v_rejected_non_draftable_count, 0),
      'forced_synthetic_cleanup_count', COALESCE(v_forced_synthetic_cleanup_count, 0),
      'replace_omitted_count', COALESCE(v_replace_omitted_count, 0),
      'selected_row_count', COALESCE(v_current_selected_count, 0),
      'selection_mode', v_selection_mode,
      'state_changed', true
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_selection_input_raw;
  CREATE TEMP TABLE _tmp_pay_wb_selection_input_raw ON COMMIT DROP AS
  SELECT BTRIM(select_id.value) AS supplied_id,
         'SELECT'::text AS action,
         select_id.ordinality::bigint AS first_ordinality
  FROM jsonb_array_elements_text(v_select_ids_source) WITH ORDINALITY AS select_id(value, ordinality)
  WHERE BTRIM(select_id.value) <> ''
  UNION ALL
  SELECT BTRIM(deselect_id.value) AS supplied_id,
         'DESELECT'::text AS action,
         deselect_id.ordinality::bigint AS first_ordinality
  FROM jsonb_array_elements_text(v_deselect_ids_source) WITH ORDINALITY AS deselect_id(value, ordinality)
  WHERE BTRIM(deselect_id.value) <> '';

  SELECT COALESCE(jsonb_agg(to_jsonb(conflicting_ids.supplied_id) ORDER BY conflicting_ids.supplied_id), '[]'::jsonb)
  INTO v_conflicting_ids
  FROM (
    SELECT input_raw.supplied_id
    FROM pg_temp._tmp_pay_wb_selection_input_raw AS input_raw
    GROUP BY input_raw.supplied_id
    HAVING COUNT(DISTINCT input_raw.action) > 1
  ) AS conflicting_ids;

  IF jsonb_array_length(COALESCE(v_conflicting_ids, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SESSION_SET_SELECTED_ROWS_CONFLICTING_ACTIONS'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SESSION_SET_SELECTED_ROWS_CONFLICTING_ACTIONS',
              'session_id', p_session_id::text,
              'conflicting_preview_row_ids', COALESCE(v_conflicting_ids, '[]'::jsonb)
            )::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_selection_ids;
  CREATE TEMP TABLE _tmp_pay_wb_selection_ids ON COMMIT DROP AS
  SELECT input_raw.supplied_id,
         input_raw.action,
         MIN(input_raw.first_ordinality)::bigint AS first_ordinality
  FROM pg_temp._tmp_pay_wb_selection_input_raw AS input_raw
  GROUP BY input_raw.supplied_id, input_raw.action;

  SELECT COALESCE(jsonb_agg(to_jsonb(selection_ids.supplied_id) ORDER BY selection_ids.action, selection_ids.first_ordinality), '[]'::jsonb)
  INTO v_stale_selection_ids
  FROM pg_temp._tmp_pay_wb_selection_ids AS selection_ids
  WHERE EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_preview_rows AS any_preview_row
    WHERE any_preview_row.session_id = p_session_id
      AND (any_preview_row.id::text = selection_ids.supplied_id OR any_preview_row.row_key = selection_ids.supplied_id)
  )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_preview_rows AS current_preview_row
      WHERE current_preview_row.session_id = p_session_id
        AND current_preview_row.session_version = v_session_row.version
        AND (current_preview_row.id::text = selection_ids.supplied_id OR current_preview_row.row_key = selection_ids.supplied_id)
        AND (
          selection_ids.action = 'DESELECT'
          OR UPPER(BTRIM(COALESCE(current_preview_row.status, ''))) = 'READY'
        )
    );

  IF jsonb_array_length(COALESCE(v_stale_selection_ids, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'WORKBENCH_STALE_SELECTION'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_STALE_SELECTION',
              'session_id', p_session_id::text,
              'session_version', v_session_row.version,
              'rejected_preview_row_ids', COALESCE(v_stale_selection_ids, '[]'::jsonb),
              'message', 'Selected preview rows are not part of the current workbench session version. Refresh the preview page and try again.'
            )::text;
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(selection_ids.supplied_id) ORDER BY selection_ids.action, selection_ids.first_ordinality), '[]'::jsonb)
  INTO v_missing_ids
  FROM pg_temp._tmp_pay_wb_selection_ids AS selection_ids
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = p_session_id
      AND (preview_row.id::text = selection_ids.supplied_id OR preview_row.row_key = selection_ids.supplied_id)
  );

  IF jsonb_array_length(COALESCE(v_missing_ids, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'selected preview row ids are not present in current session scope: %', v_missing_ids::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_selection_matched_rows;
  CREATE TEMP TABLE _tmp_pay_wb_selection_matched_rows ON COMMIT DROP AS
  SELECT DISTINCT ON (preview_row.id)
         preview_row.id,
         selection_ids.supplied_id,
         selection_ids.action,
         selection_ids.first_ordinality,
         preview_row.row_ordinal,
         COALESCE(preview_row.selected, false) AS was_selected,
         preview_row.selected AS previous_selected,
         preview_row.selection_state AS previous_selection_state,
         contract_check.contract_json,
         synthetic_check.is_synthetic_resolved_total,
         CASE
           WHEN selection_ids.action = 'DESELECT' THEN false
           ELSE LOWER(BTRIM(COALESCE(contract_check.contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             AND LOWER(BTRIM(COALESCE(contract_check.contract_json->>'materialisable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             AND LOWER(BTRIM(COALESCE(contract_check.contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             AND COALESCE(contract_check.contract_json->>'target_section', '') = 'canonical_preview_lines'
             AND UPPER(BTRIM(COALESCE(contract_check.contract_json->>'presentation_section', ''))) = 'READY_TO_PAY'
             AND LOWER(BTRIM(COALESCE(contract_check.contract_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             AND LOWER(BTRIM(COALESCE(contract_check.contract_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             AND COALESCE(contract_check.contract_json->>'key_type', '') <> ''
             AND COALESCE(contract_check.contract_json->>'key_value', '') <> ''
             AND (
               UPPER(BTRIM(COALESCE(contract_check.contract_json->>'key_type', ''))) <> 'TS_DAY'
               OR COALESCE(contract_check.contract_json->>'key_value', '') ~ '^\d{4}-\d{2}-\d{2}$'
             )
             AND UPPER(BTRIM(COALESCE(contract_check.contract_json->>'source_kind', ''))) NOT IN (
               'TIMESHEET_SNAPSHOT',
               'TIMESHEET_SNAPSHOT_EVIDENCE',
               'RAW_TIMESHEET_SNAPSHOT',
               'INTERNAL_ONLY',
               'NO_DELTA',
               'EXCLUDED'
             )
             AND preview_row.row_key NOT LIKE 'timesheet_snapshot:%'
             AND synthetic_check.is_synthetic_resolved_total IS NOT TRUE
         END AS is_selectable
  FROM pg_temp._tmp_pay_wb_selection_ids AS selection_ids
  JOIN public.banking_pay_workbench_preview_rows AS preview_row
    ON preview_row.session_id = p_session_id
   AND preview_row.session_version = v_session_row.version
   AND (preview_row.id::text = selection_ids.supplied_id OR preview_row.row_key = selection_ids.supplied_id)
   AND (
     selection_ids.action = 'DESELECT'
     OR UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
   )
  CROSS JOIN LATERAL (
    SELECT public.pay_workbench_preview_line_contract_ok(
      p_line_json => COALESCE(preview_row.row_json, '{}'::jsonb)
        || jsonb_build_object(
          'line_key', preview_row.row_key,
          'row_key', preview_row.row_key,
          'section', private.pay_workbench_preview_effective_section_v1(preview_row.section, preview_row.row_json),
          'target_section', private.pay_workbench_preview_effective_section_v1(preview_row.section, preview_row.row_json),
          'key_type', preview_row.key_type,
          'key_value', preview_row.key_value
        ),
      p_economic_key_json => jsonb_build_object(
        'key_type', preview_row.key_type,
        'key_value', preview_row.key_value
      ),
      p_target_section => private.pay_workbench_preview_effective_section_v1(preview_row.section, preview_row.row_json)
    ) AS contract_json
  ) AS contract_check
  CROSS JOIN LATERAL (
    SELECT (
      preview_row.timesheet_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(
        preview_row.key_type,
        preview_row.row_json#>>'{economic_key,key_type}',
        preview_row.row_json->>'component_key_type',
        preview_row.row_json->>'key_type',
        ''
      ))) = 'TS_TOTAL'
      AND UPPER(BTRIM(COALESCE(
        preview_row.key_value,
        preview_row.row_json#>>'{economic_key,key_value}',
        preview_row.row_json->>'component_key_value',
        preview_row.row_json->>'key_value',
        ''
      ))) = 'TOTAL'
      AND LOWER(BTRIM(COALESCE(
        preview_row.row_key,
        preview_row.row_json->>'row_key',
        preview_row.row_json->>'line_key',
        preview_row.row_json->>'source_ref',
        preview_row.row_json#>>'{source_basis,row_key}',
        preview_row.row_json#>>'{source_basis,line_key}',
        preview_row.row_json#>>'{source_basis,source_ref}',
        preview_row.row_json#>>'{source_basis_json,row_key}',
        preview_row.row_json#>>'{source_basis_json,line_key}',
        preview_row.row_json#>>'{source_basis_json,source_ref}',
        ''
      ))) LIKE '%:non_segment:total%'
      AND EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_preview_rows AS sibling_row
        WHERE sibling_row.session_id = preview_row.session_id
          AND sibling_row.session_version = preview_row.session_version
          AND sibling_row.id <> preview_row.id
          AND sibling_row.timesheet_id = preview_row.timesheet_id
          AND lower(private.pay_workbench_preview_effective_section_v1(sibling_row.section, sibling_row.row_json)) = 'canonical_preview_lines'
          AND UPPER(BTRIM(COALESCE(sibling_row.status, ''))) = 'READY'
          AND UPPER(BTRIM(COALESCE(
            sibling_row.key_type,
            sibling_row.row_json#>>'{economic_key,key_type}',
            sibling_row.row_json->>'component_key_type',
            sibling_row.row_json->>'key_type',
            ''
          ))) = 'TS_DAY'
          AND COALESCE(
            sibling_row.key_value,
            sibling_row.row_json#>>'{economic_key,key_value}',
            sibling_row.row_json->>'component_key_value',
            sibling_row.row_json->>'key_value',
            ''
          ) ~ '^\d{4}-\d{2}-\d{2}$'
      )
    ) AS is_synthetic_resolved_total
  ) AS synthetic_check
  ORDER BY preview_row.id, selection_ids.first_ordinality;

  SELECT COALESCE(jsonb_agg(to_jsonb(non_draftable.preview_row_id) ORDER BY non_draftable.first_ordinality, non_draftable.preview_row_id), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_non_draftable_ids, v_rejected_non_draftable_count
  FROM (
    SELECT DISTINCT matched_rows.id::text AS preview_row_id,
           matched_rows.first_ordinality
    FROM pg_temp._tmp_pay_wb_selection_matched_rows AS matched_rows
    WHERE matched_rows.action = 'SELECT'
      AND matched_rows.is_selectable IS NOT TRUE
  ) AS non_draftable;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_replace_omitted_rows;
  CREATE TEMP TABLE _tmp_pay_wb_replace_omitted_rows ON COMMIT DROP AS
  SELECT preview_row.id,
         COALESCE(preview_row.selected, false) AS was_selected,
         (1000000000::bigint + ROW_NUMBER() OVER (ORDER BY preview_row.row_ordinal, preview_row.id))::bigint AS first_ordinality
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE v_replace_mode
    AND preview_row.session_id = p_session_id
    AND preview_row.session_version = v_session_row.version
    AND lower(private.pay_workbench_preview_effective_section_v1(preview_row.section, preview_row.row_json)) = 'canonical_preview_lines'
    AND COALESCE(preview_row.selected, false) = true
    AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
    AND NOT EXISTS (
      SELECT 1
      FROM pg_temp._tmp_pay_wb_selection_matched_rows AS matched_rows
      WHERE matched_rows.id = preview_row.id
        AND matched_rows.action = 'SELECT'
    );

  SELECT COUNT(*)::integer
  INTO v_replace_omitted_count
  FROM pg_temp._tmp_pay_wb_replace_omitted_rows AS omitted_rows;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_synthetic_cleanup_rows;
  CREATE TEMP TABLE _tmp_pay_wb_synthetic_cleanup_rows ON COMMIT DROP AS
  SELECT preview_row.id,
         COALESCE(preview_row.selected, false) AS was_selected,
         (2000000000::bigint + ROW_NUMBER() OVER (ORDER BY preview_row.row_ordinal, preview_row.id))::bigint AS first_ordinality
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  CROSS JOIN LATERAL (
    SELECT (
      preview_row.timesheet_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(
        preview_row.key_type,
        preview_row.row_json#>>'{economic_key,key_type}',
        preview_row.row_json->>'component_key_type',
        preview_row.row_json->>'key_type',
        ''
      ))) = 'TS_TOTAL'
      AND UPPER(BTRIM(COALESCE(
        preview_row.key_value,
        preview_row.row_json#>>'{economic_key,key_value}',
        preview_row.row_json->>'component_key_value',
        preview_row.row_json->>'key_value',
        ''
      ))) = 'TOTAL'
      AND LOWER(BTRIM(COALESCE(
        preview_row.row_key,
        preview_row.row_json->>'row_key',
        preview_row.row_json->>'line_key',
        preview_row.row_json->>'source_ref',
        preview_row.row_json#>>'{source_basis,row_key}',
        preview_row.row_json#>>'{source_basis,line_key}',
        preview_row.row_json#>>'{source_basis,source_ref}',
        preview_row.row_json#>>'{source_basis_json,row_key}',
        preview_row.row_json#>>'{source_basis_json,line_key}',
        preview_row.row_json#>>'{source_basis_json,source_ref}',
        ''
      ))) LIKE '%:non_segment:total%'
      AND EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_preview_rows AS sibling_row
        WHERE sibling_row.session_id = preview_row.session_id
          AND sibling_row.session_version = preview_row.session_version
          AND sibling_row.id <> preview_row.id
          AND sibling_row.timesheet_id = preview_row.timesheet_id
          AND lower(private.pay_workbench_preview_effective_section_v1(sibling_row.section, sibling_row.row_json)) = 'canonical_preview_lines'
          AND UPPER(BTRIM(COALESCE(sibling_row.status, ''))) = 'READY'
          AND UPPER(BTRIM(COALESCE(
            sibling_row.key_type,
            sibling_row.row_json#>>'{economic_key,key_type}',
            sibling_row.row_json->>'component_key_type',
            sibling_row.row_json->>'key_type',
            ''
          ))) = 'TS_DAY'
          AND COALESCE(
            sibling_row.key_value,
            sibling_row.row_json#>>'{economic_key,key_value}',
            sibling_row.row_json->>'component_key_value',
            sibling_row.row_json->>'key_value',
            ''
          ) ~ '^\d{4}-\d{2}-\d{2}$'
      )
    ) AS is_synthetic_resolved_total
  ) AS synthetic_check
  WHERE preview_row.session_id = p_session_id
    AND preview_row.session_version = v_session_row.version
    AND lower(private.pay_workbench_preview_effective_section_v1(preview_row.section, preview_row.row_json)) = 'canonical_preview_lines'
    AND COALESCE(preview_row.selected, false) = true
    AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
    AND synthetic_check.is_synthetic_resolved_total;

  SELECT COUNT(*)::integer
  INTO v_forced_synthetic_cleanup_count
  FROM pg_temp._tmp_pay_wb_synthetic_cleanup_rows AS cleanup_rows;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_update_actions;
  CREATE TEMP TABLE _tmp_pay_wb_update_actions ON COMMIT DROP AS
  WITH raw_actions AS (
    SELECT matched_rows.id,
           CASE
             WHEN matched_rows.action = 'SELECT' AND matched_rows.is_selectable THEN 'SELECT'::text
             WHEN matched_rows.action = 'SELECT' THEN 'REJECT_SELECT'::text
             ELSE 'DESELECT'::text
           END AS action,
           matched_rows.was_selected,
           matched_rows.first_ordinality
    FROM pg_temp._tmp_pay_wb_selection_matched_rows AS matched_rows
    UNION ALL
    SELECT omitted_rows.id,
           'DESELECT'::text AS action,
           omitted_rows.was_selected,
           omitted_rows.first_ordinality
    FROM pg_temp._tmp_pay_wb_replace_omitted_rows AS omitted_rows
    UNION ALL
    SELECT cleanup_rows.id,
           'DESELECT'::text AS action,
           cleanup_rows.was_selected,
           cleanup_rows.first_ordinality
    FROM pg_temp._tmp_pay_wb_synthetic_cleanup_rows AS cleanup_rows
  )
  SELECT DISTINCT ON (raw_actions.id)
         raw_actions.id,
         raw_actions.action,
         raw_actions.was_selected,
         raw_actions.first_ordinality
  FROM raw_actions
  ORDER BY raw_actions.id,
           CASE raw_actions.action
             WHEN 'DESELECT' THEN 1
             WHEN 'REJECT_SELECT' THEN 2
             WHEN 'SELECT' THEN 3
             ELSE 4
           END,
           raw_actions.first_ordinality;

  WITH updated_rows AS (
    UPDATE public.banking_pay_workbench_preview_rows AS preview_row
    SET selected = CASE
          WHEN update_actions.action = 'SELECT' THEN true
          ELSE false
        END,
        selection_state = CASE
          WHEN update_actions.action = 'SELECT' THEN 'SELECTED'
          WHEN update_actions.action = 'REJECT_SELECT' THEN 'NOT_SELECTABLE'
          ELSE 'UNSELECTED'
        END,
        row_json = COALESCE(preview_row.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'selected', update_actions.action = 'SELECT',
            'selection_state', CASE
              WHEN update_actions.action = 'SELECT' THEN 'SELECTED'
              WHEN update_actions.action = 'REJECT_SELECT' THEN 'NOT_SELECTABLE'
              ELSE 'UNSELECTED'
            END,
            'selection_user_override', CASE
              WHEN update_actions.action = 'SELECT' THEN 'SELECTED'
              WHEN update_actions.action = 'DESELECT' THEN 'UNSELECTED'
              ELSE NULL
            END,
            'selection_origin', CASE
              WHEN update_actions.action = 'SELECT' THEN 'USER_EXPLICIT_SELECT'
              WHEN update_actions.action = 'DESELECT' THEN 'USER_EXPLICIT_DESELECT'
              ELSE NULL
            END,
            'selection_user_override_at_utc', CASE
              WHEN update_actions.action IN ('SELECT', 'DESELECT') THEN v_now::text
              ELSE NULL
            END
          ),
        updated_at_utc = v_now
    FROM pg_temp._tmp_pay_wb_update_actions AS update_actions
    WHERE preview_row.id = update_actions.id
    RETURNING preview_row.id,
              update_actions.action,
              update_actions.was_selected,
              preview_row.selected,
              update_actions.first_ordinality
  )
  SELECT
    COALESCE((SELECT jsonb_agg(to_jsonb(updated_rows.id::text) ORDER BY updated_rows.first_ordinality, updated_rows.id) FROM updated_rows WHERE updated_rows.action = 'DESELECT'), '[]'::jsonb),
    COALESCE((SELECT COUNT(*)::integer FROM updated_rows WHERE updated_rows.action = 'SELECT' AND updated_rows.was_selected IS NOT TRUE AND updated_rows.selected), 0),
    COALESCE((SELECT COUNT(*)::integer FROM updated_rows WHERE updated_rows.action = 'DESELECT' AND updated_rows.was_selected), 0),
    COALESCE((SELECT COUNT(*)::integer FROM updated_rows), 0)
  INTO v_deselected_ids, v_selected_delta, v_deselected_delta, v_updated_count;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_current_selected_rows;
  CREATE TEMP TABLE _tmp_pay_wb_current_selected_rows ON COMMIT DROP AS
  SELECT selected_count_row.id,
         selected_count_row.candidate_id,
         selected_count_row.row_ordinal,
         selected_count_row.row_key,
         selected_count_row.row_json,
         selected_count_row.timesheet_id,
         selected_count_row.key_type,
         selected_count_row.key_value,
         selected_contract.contract_json,
         synthetic_check.is_synthetic_resolved_total
  FROM public.banking_pay_workbench_preview_rows AS selected_count_row
  CROSS JOIN LATERAL (
    SELECT public.pay_workbench_preview_line_contract_ok(
      p_line_json => COALESCE(selected_count_row.row_json, '{}'::jsonb)
        || jsonb_build_object(
          'line_key', selected_count_row.row_key,
          'row_key', selected_count_row.row_key,
          'section', private.pay_workbench_preview_effective_section_v1(selected_count_row.section, selected_count_row.row_json),
          'target_section', private.pay_workbench_preview_effective_section_v1(selected_count_row.section, selected_count_row.row_json),
          'key_type', selected_count_row.key_type,
          'key_value', selected_count_row.key_value
        ),
      p_economic_key_json => jsonb_build_object(
        'key_type', selected_count_row.key_type,
        'key_value', selected_count_row.key_value
      ),
      p_target_section => private.pay_workbench_preview_effective_section_v1(selected_count_row.section, selected_count_row.row_json)
    ) AS contract_json
  ) AS selected_contract
  CROSS JOIN LATERAL (
    SELECT (
      selected_count_row.timesheet_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(
        selected_count_row.key_type,
        selected_count_row.row_json#>>'{economic_key,key_type}',
        selected_count_row.row_json->>'component_key_type',
        selected_count_row.row_json->>'key_type',
        ''
      ))) = 'TS_TOTAL'
      AND UPPER(BTRIM(COALESCE(
        selected_count_row.key_value,
        selected_count_row.row_json#>>'{economic_key,key_value}',
        selected_count_row.row_json->>'component_key_value',
        selected_count_row.row_json->>'key_value',
        ''
      ))) = 'TOTAL'
      AND LOWER(BTRIM(COALESCE(
        selected_count_row.row_key,
        selected_count_row.row_json->>'row_key',
        selected_count_row.row_json->>'line_key',
        selected_count_row.row_json->>'source_ref',
        selected_count_row.row_json#>>'{source_basis,row_key}',
        selected_count_row.row_json#>>'{source_basis,line_key}',
        selected_count_row.row_json#>>'{source_basis,source_ref}',
        selected_count_row.row_json#>>'{source_basis_json,row_key}',
        selected_count_row.row_json#>>'{source_basis_json,line_key}',
        selected_count_row.row_json#>>'{source_basis_json,source_ref}',
        ''
      ))) LIKE '%:non_segment:total%'
      AND EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_preview_rows AS sibling_row
        WHERE sibling_row.session_id = selected_count_row.session_id
          AND sibling_row.session_version = selected_count_row.session_version
          AND sibling_row.id <> selected_count_row.id
          AND sibling_row.timesheet_id = selected_count_row.timesheet_id
          AND lower(private.pay_workbench_preview_effective_section_v1(sibling_row.section, sibling_row.row_json)) = 'canonical_preview_lines'
          AND UPPER(BTRIM(COALESCE(sibling_row.status, ''))) = 'READY'
          AND UPPER(BTRIM(COALESCE(
            sibling_row.key_type,
            sibling_row.row_json#>>'{economic_key,key_type}',
            sibling_row.row_json->>'component_key_type',
            sibling_row.row_json->>'key_type',
            ''
          ))) = 'TS_DAY'
          AND COALESCE(
            sibling_row.key_value,
            sibling_row.row_json#>>'{economic_key,key_value}',
            sibling_row.row_json->>'component_key_value',
            sibling_row.row_json->>'key_value',
            ''
          ) ~ '^\d{4}-\d{2}-\d{2}$'
      )
    ) AS is_synthetic_resolved_total
  ) AS synthetic_check
  WHERE selected_count_row.session_id = p_session_id
    AND selected_count_row.session_version = v_session_row.version
    AND lower(private.pay_workbench_preview_effective_section_v1(selected_count_row.section, selected_count_row.row_json)) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(selected_count_row.status, ''))) = 'READY'
    AND COALESCE(selected_count_row.selected, false) = true
    AND UPPER(BTRIM(COALESCE(selected_count_row.selection_state, ''))) = 'SELECTED';

  SELECT COALESCE(jsonb_agg(to_jsonb(current_selected.id::text) ORDER BY current_selected.row_ordinal, current_selected.id), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_selected_ids, v_current_selected_count
  FROM pg_temp._tmp_pay_wb_current_selected_rows AS current_selected
  WHERE LOWER(BTRIM(COALESCE(current_selected.contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND LOWER(BTRIM(COALESCE(current_selected.contract_json->>'materialisable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND LOWER(BTRIM(COALESCE(current_selected.contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND COALESCE(current_selected.contract_json->>'target_section', '') = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(current_selected.contract_json->>'presentation_section', ''))) = 'READY_TO_PAY'
    AND LOWER(BTRIM(COALESCE(current_selected.contract_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND LOWER(BTRIM(COALESCE(current_selected.contract_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND COALESCE(current_selected.contract_json->>'key_type', '') <> ''
    AND COALESCE(current_selected.contract_json->>'key_value', '') <> ''
    AND (
      UPPER(BTRIM(COALESCE(current_selected.contract_json->>'key_type', ''))) <> 'TS_DAY'
      OR COALESCE(current_selected.contract_json->>'key_value', '') ~ '^\d{4}-\d{2}-\d{2}$'
    )
    AND UPPER(BTRIM(COALESCE(current_selected.contract_json->>'source_kind', ''))) NOT IN (
      'TIMESHEET_SNAPSHOT',
      'TIMESHEET_SNAPSHOT_EVIDENCE',
      'RAW_TIMESHEET_SNAPSHOT',
      'INTERNAL_ONLY',
      'NO_DELTA',
      'EXCLUDED'
    )
    AND current_selected.row_key NOT LIKE 'timesheet_snapshot:%'
    AND current_selected.is_synthetic_resolved_total IS NOT TRUE;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'candidate_id',current_selected.candidate_id,
    'row_key',current_selected.row_key,
    'timesheet_id',current_selected.timesheet_id,
    'key_type',current_selected.key_type,
    'key_value',current_selected.key_value
  ) ORDER BY current_selected.candidate_id,current_selected.row_key,current_selected.id),'[]'::jsonb)
  INTO v_selected_economic_identities
  FROM pg_temp._tmp_pay_wb_current_selected_rows AS current_selected
  WHERE current_selected.id IN (
    SELECT selected_id.value::uuid
    FROM jsonb_array_elements_text(COALESCE(v_selected_ids,'[]'::jsonb)) AS selected_id(value)
  );

  v_next_selection_intent_mode := CASE
    WHEN v_replace_mode THEN 'EXPLICIT_INCLUDE'
    ELSE 'IMPLICIT_ALL'
  END;
  v_next_server_selected_ids_provided := (v_next_selection_intent_mode = 'EXPLICIT_INCLUDE');
  v_server_selected_ids := CASE
    WHEN v_next_server_selected_ids_provided THEN COALESCE(v_selected_ids, '[]'::jsonb)
    ELSE '[]'::jsonb
  END;
  v_session_ready := LOWER(BTRIM(COALESCE(
    v_session_row.progress_json->>'ready',
    v_session_row.progress_json->>'session_ready',
    v_session_row.progress_json->>'ready_flag',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  SELECT COALESCE(jsonb_agg(to_jsonb(blocker_code.value) ORDER BY blocker_code.ordinality), '[]'::jsonb)
  INTO v_draft_blocker_codes
  FROM jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(v_session_row.progress_json->'draft_blocker_codes') = 'array'
        THEN v_session_row.progress_json->'draft_blocker_codes'
      ELSE '[]'::jsonb
    END
  ) WITH ORDINALITY AS blocker_code(value, ordinality)
  WHERE UPPER(BTRIM(blocker_code.value)) <> 'NO_SELECTED_ROWS';

  IF v_session_ready AND COALESCE(v_current_selected_count, 0) = 0 THEN
    v_draft_blocker_codes := COALESCE(v_draft_blocker_codes, '[]'::jsonb)
      || jsonb_build_array('NO_SELECTED_ROWS');
  END IF;

  UPDATE public.banking_pay_workbench_sessions AS session_row
  SET selected_row_count = COALESCE(v_current_selected_count, 0),
      server_selected_preview_row_ids = COALESCE(v_server_selected_ids, '[]'::jsonb),
      server_selected_preview_row_ids_provided = COALESCE(v_next_server_selected_ids_provided, false),
      progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_selection_update_at_utc', v_now::text,
          'last_selection_selected_delta', COALESCE(v_selected_delta, 0),
          'last_selection_deselected_delta', COALESCE(v_deselected_delta, 0),
          'last_selection_rejected_non_draftable_count', COALESCE(v_rejected_non_draftable_count, 0),
          'last_selection_mode', v_selection_mode,
          'last_selection_forced_synthetic_cleanup_count', COALESCE(v_forced_synthetic_cleanup_count, 0),
          'last_selection_replace_omitted_count', COALESCE(v_replace_omitted_count, 0),
          'selected_row_count', COALESCE(v_current_selected_count, 0),
          'selected_eligible_ready_row_count', COALESCE(v_current_selected_count, 0),
          'selected_rows_available', COALESCE(v_current_selected_count, 0) > 0,
          'ready_for_draft', v_session_ready AND COALESCE(v_current_selected_count, 0) > 0,
          'can_create_draft', v_session_ready AND COALESCE(v_current_selected_count, 0) > 0,
          'draft_blocker_codes', COALESCE(v_draft_blocker_codes, '[]'::jsonb),
          'blocker_codes', COALESCE(v_draft_blocker_codes, '[]'::jsonb),
          'selection_intent_v1', COALESCE(session_row.progress_json->'selection_intent_v1', '{}'::jsonb)
            || jsonb_build_object(
              'canonical_preview_lines', jsonb_build_object(
                'mode', COALESCE(v_next_selection_intent_mode, 'IMPLICIT_ALL'),
                'section', 'canonical_preview_lines',
                'identity', 'preview_row_id_with_session_section_candidate_row_key_conflict_identity',
                'updated_at_utc', v_now::text,
                'updated_by_user_id', p_actor_user_id::text,
                'source_selection_mode', v_selection_mode,
                'source_selection_action', CASE WHEN v_replace_mode THEN 'REPLACE_SELECTED_ROWS' ELSE 'ROW_PATCH' END,
                'server_selected_preview_row_ids_provided', COALESCE(v_next_server_selected_ids_provided, false),
                'selected_row_count', COALESCE(v_current_selected_count, 0),
                'selected_economic_identities',COALESCE(v_selected_economic_identities,'[]'::jsonb),
                'identity_contract_version',2
              )
            )
        ),
      progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE session_row.id = p_session_id
  RETURNING session_row.progress_counter_version
  INTO v_next_progress_counter_version;

  FOR v_revalidation_candidate_id IN
    SELECT DISTINCT preview_row.candidate_id
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    JOIN pg_temp._tmp_pay_wb_update_actions AS changed_row
      ON changed_row.id = preview_row.id
    WHERE preview_row.session_id = p_session_id
      AND preview_row.session_version = v_session_row.version
      AND preview_row.candidate_id IS NOT NULL
  LOOP
    v_revalidation_result := public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(
      p_session_id,
      v_revalidation_candidate_id
    );
  END LOOP;

  SELECT session_row.progress_counter_version
  INTO v_next_progress_counter_version
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_row.id::text) ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_selected_ids,
       v_current_selected_count
  FROM public.banking_pay_workbench_preview_rows AS selected_row
  WHERE selected_row.session_id = p_session_id
    AND selected_row.session_version = v_session_row.version
    AND LOWER(private.pay_workbench_preview_effective_section_v1(selected_row.section, selected_row.row_json)) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(selected_row.status, ''))) = 'READY'
    AND COALESCE(selected_row.selected, false) IS TRUE
    AND UPPER(BTRIM(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

  v_server_selected_ids := CASE
    WHEN v_next_server_selected_ids_provided THEN COALESCE(v_selected_ids, '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_audit_after_json := jsonb_build_object(
    'id', p_session_id::text,
    'selection_mode', v_selection_mode,
    'selected_preview_row_ids', COALESCE(v_selected_ids, '[]'::jsonb),
    'deselected_preview_row_ids', COALESCE(v_deselected_ids, '[]'::jsonb),
    'rejected_non_draftable_preview_row_ids', COALESCE(v_non_draftable_ids, '[]'::jsonb),
    'rejected_non_draftable_preview_row_count', COALESCE(v_rejected_non_draftable_count, 0),
    'updated_preview_row_count', COALESCE(v_updated_count, 0),
    'selected_delta', COALESCE(v_selected_delta, 0),
    'deselected_delta', COALESCE(v_deselected_delta, 0),
    'forced_synthetic_cleanup_count', COALESCE(v_forced_synthetic_cleanup_count, 0),
    'replace_omitted_count', COALESCE(v_replace_omitted_count, 0),
    'selection_intent_mode', COALESCE(v_next_selection_intent_mode, 'IMPLICIT_ALL'),
    'server_selected_preview_row_ids_provided', COALESCE(v_next_server_selected_ids_provided, false),
    'updated_at_utc', v_now
  );

  PERFORM public._audit_insert(
    'banking_pay_workbench_session',
    p_session_id::text,
    CASE WHEN v_replace_mode THEN 'SESSION_SELECTED_ROWS_REPLACED' ELSE 'SESSION_SELECTED_ROWS_PATCHED' END,
    NULL::jsonb,
    v_audit_after_json,
    CASE WHEN v_replace_mode THEN 'SESSION_SELECTED_ROWS_REPLACED' ELSE 'SESSION_SELECTED_ROWS_PATCHED' END,
    p_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'session_version', v_session_row.version,
    'progress_counter_version', COALESCE(v_next_progress_counter_version, COALESCE(v_session_row.progress_counter_version, 0) + 1),
    'expected_session_version', v_expected_session_version,
    'expected_progress_counter_version', v_expected_progress_counter_version,
    'selected_preview_row_ids', COALESCE(v_selected_ids, '[]'::jsonb),
    'deselected_preview_row_ids', COALESCE(v_deselected_ids, '[]'::jsonb),
    'selected_preview_row_ids_provided', COALESCE(v_next_server_selected_ids_provided, false),
    'server_selected_preview_row_ids', COALESCE(v_server_selected_ids, '[]'::jsonb),
    'server_selected_preview_row_ids_provided', COALESCE(v_next_server_selected_ids_provided, false),
    'selected_delta', COALESCE(v_selected_delta, 0),
    'deselected_delta', COALESCE(v_deselected_delta, 0),
    'updated_preview_row_count', COALESCE(v_updated_count, 0),
    'dropped_non_draftable_preview_row_ids', COALESCE(v_non_draftable_ids, '[]'::jsonb),
    'rejected_non_draftable_preview_row_ids', COALESCE(v_non_draftable_ids, '[]'::jsonb),
    'rejected_non_draftable_preview_row_count', COALESCE(v_rejected_non_draftable_count, 0),
    'forced_synthetic_cleanup_count', COALESCE(v_forced_synthetic_cleanup_count, 0),
    'replace_omitted_count', COALESCE(v_replace_omitted_count, 0),
    'selected_row_count', COALESCE(v_current_selected_count, 0),
    'ready_for_draft', v_session_ready AND COALESCE(v_current_selected_count, 0) > 0,
    'can_create_draft', v_session_ready AND COALESCE(v_current_selected_count, 0) > 0,
    'draft_blocker_codes', COALESCE(v_draft_blocker_codes, '[]'::jsonb),
    'blocker_codes', COALESCE(v_draft_blocker_codes, '[]'::jsonb),
    'selection_mode', v_selection_mode,
    'selection_intent_mode', COALESCE(v_next_selection_intent_mode, 'IMPLICIT_ALL')
  );
END;
$function$;

-- private.pay_workbench_candidate_dirty_cohort_stage_v1 from supabase/repeatable/08092026_0518_banking_pay_candidate_dirty_cohort_authority_v1.sql; definition SHA-256 e783757ebbc88995113e25961991f9d196746662f24cbf19cf3b4f34f75b7a89.
CREATE OR REPLACE FUNCTION private.pay_workbench_candidate_dirty_cohort_stage_v1(
  p_job_id uuid,
  p_candidate_id uuid,
  p_now_utc timestamptz DEFAULT NULL::timestamptz
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
PARALLEL UNSAFE
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
  v_now timestamptz := COALESCE(p_now_utc, pg_catalog.clock_timestamp());
  v_deferral_enabled boolean := false;
  v_member record;
  v_context jsonb := '{}'::jsonb;
  v_context_digest text := NULL::text;
  v_member_deferred boolean := false;
  v_member_ids uuid[] := ARRAY[]::uuid[];
  v_admitted_member_ids uuid[] := ARRAY[]::uuid[];
  v_excluded_member_ids uuid[] := ARRAY[]::uuid[];
  v_member_count integer := 0;
  v_excluded_count integer := 0;
  v_contains_full_scope boolean := false;
  v_timesheet_root_count integer := 0;
  v_finance_case_root_count integer := 0;
  v_effective_timesheet_count integer := 0;
  v_timesheet_root_ids uuid[] := ARRAY[]::uuid[];
  v_finance_case_root_ids uuid[] := ARRAY[]::uuid[];
  v_effective_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_dependency_closure jsonb := '{}'::jsonb;
  v_family_scope jsonb := '{}'::jsonb;
  v_authority_scope text := 'TARGETED_UNION';
  v_full_fallback_reason text := NULL::text;
  v_registry_generation bigint := NULL::bigint;
  v_registry_source_seq bigint := 0;
  v_registry_pending_token uuid := NULL::uuid;
  v_live_generation bigint := NULL::bigint;
  v_live_source_seq bigint := 0;
  v_counter_pending_token uuid := NULL::uuid;
  v_common_token uuid := NULL::uuid;
  v_common_generation bigint := NULL::bigint;
  v_transaction_state text := NULL::text;
  v_transaction_generation bigint := NULL::bigint;
  v_all_members_match boolean := false;
  v_all_states_match boolean := false;
  v_all_full_markers_match boolean := false;
  v_authority_reusable boolean := false;
  v_pending_replay boolean := false;
  v_stage_token uuid := NULL::uuid;
  v_common_source_seq bigint := 0;
  v_invalidation_result jsonb := '{}'::jsonb;
  v_invalidation_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_invalidation_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_snapshot_max_updated_at timestamptz := NULL::timestamptz;
  v_snapshot_max_latest_event text := NULL::text;
BEGIN
  IF p_job_id IS NULL OR p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_COHORT_CURRENT_MEMBER_INVALID'
      USING ERRCODE = '22023', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PAY_WORKBENCH_DIRTY_COHORT_CURRENT_MEMBER_INVALID',
        'job_id', p_job_id,
        'candidate_id', p_candidate_id
      )::text;
  END IF;

  -- The public processor already owns this lock. Reacquiring it is harmless
  -- and makes direct/internal misuse fail closed instead of creating a second
  -- Candidate queue authority.
  IF NOT pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtextextended(
      public._pay_workbench_candidate_serial_key(p_candidate_id),
      24062027
    )
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_COHORT_CANDIDATE_LOCK_REQUIRED'
      USING ERRCODE = '55000', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PAY_WORKBENCH_DIRTY_COHORT_CANDIDATE_LOCK_REQUIRED',
        'job_id', p_job_id,
        'candidate_id', p_candidate_id
      )::text;
  END IF;

  -- Keep the two branches separate so each partial index remains usable. The
  -- snapshot is deliberately finite-in-time, but not cardinality-capped. UUID
  -- arrays avoid every caller-controlled temporary namespace: the public entry
  -- point is SECURITY DEFINER, so even fixed-name DROP is unsafe when a caller
  -- owns a same-name temporary relation.
  SELECT COALESCE(
           pg_catalog.array_agg(snapshot_job.id ORDER BY snapshot_job.id),
           ARRAY[]::uuid[]
         )
  INTO v_member_ids
  FROM (
    SELECT candidate_job.id
    FROM public.banking_pay_workbench_jobs AS candidate_job
    WHERE candidate_job.candidate_id = p_candidate_id
      AND candidate_job.job_type = 'WORKBENCH_CANDIDATE_DIRTY_APPLY'
      AND candidate_job.status IN ('QUEUED', 'RUNNING')
    UNION
    SELECT legacy_job.id
    FROM public.banking_pay_workbench_jobs AS legacy_job
    WHERE legacy_job.candidate_id IS NULL
      AND legacy_job.job_type = 'WORKBENCH_CANDIDATE_DIRTY_APPLY'
      AND legacy_job.status IN ('QUEUED', 'RUNNING')
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(
            legacy_job.payload_json->>'candidate_id', ''
          ))) = p_candidate_id::text
  ) AS snapshot_job;

  -- A deterministic row-lock pass converts the index snapshot into the exact
  -- admitted cohort. A row inserted after this ID snapshot is a late arrival
  -- and intentionally belongs to the next cohort.
  PERFORM 1
  FROM pg_catalog.unnest(v_member_ids) AS snapshot_member(id)
  JOIN public.banking_pay_workbench_jobs AS locked_job
    ON locked_job.id = snapshot_member.id
  ORDER BY locked_job.id
  FOR UPDATE OF locked_job;

  -- Rows can change while the deterministic lock pass waits. Recheck the
  -- finite ID snapshot under lock and carry only still-active exact members.
  SELECT COALESCE(
           pg_catalog.array_agg(current_job.id ORDER BY current_job.id),
           ARRAY[]::uuid[]
         )
  INTO v_member_ids
  FROM pg_catalog.unnest(v_member_ids) AS snapshot_member(id)
  JOIN public.banking_pay_workbench_jobs AS current_job
    ON current_job.id = snapshot_member.id
  WHERE current_job.job_type = 'WORKBENCH_CANDIDATE_DIRTY_APPLY'
    AND current_job.status IN ('QUEUED', 'RUNNING')
    AND (
      current_job.candidate_id = p_candidate_id
      OR (
        current_job.candidate_id IS NULL
        AND pg_catalog.lower(pg_catalog.btrim(COALESCE(
              current_job.payload_json->>'candidate_id', ''
            ))) = p_candidate_id::text
      )
    );

  v_admitted_member_ids := v_member_ids;

  IF NOT EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_jobs AS current_job
    WHERE current_job.id = p_job_id
      AND current_job.id = ANY(v_member_ids)
      AND current_job.status = 'RUNNING'
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_COHORT_CURRENT_MEMBER_INVALID'
      USING ERRCODE = '22023', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PAY_WORKBENCH_DIRTY_COHORT_CURRENT_MEMBER_INVALID',
        'job_id', p_job_id,
        'candidate_id', p_candidate_id
      )::text;
  END IF;

  SELECT COALESCE(
    (pg_catalog.to_jsonb(settings_row)
      ->>'banking_pay_correction_request_dirty_deferral_v1_enabled')::boolean,
    false
  )
  INTO v_deferral_enabled
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  -- Preserve the installed correction boundary exactly. The current row has
  -- already passed this gate in the public processor; only unfinished sibling
  -- authorities are excluded. Historical/terminal correction metadata alone
  -- never makes a row permanently ineligible for a later cohort.
  FOR v_member IN
    SELECT candidate_job.id,
           candidate_job.created_at_utc,
           candidate_job.updated_at_utc,
           candidate_job.scope_change_tx_token,
           COALESCE(candidate_job.payload_json, '{}'::jsonb) AS payload_json
    FROM pg_catalog.unnest(v_member_ids) AS snapshot_member(id)
    JOIN public.banking_pay_workbench_jobs AS candidate_job
      ON candidate_job.id = snapshot_member.id
    WHERE candidate_job.id <> p_job_id
    ORDER BY candidate_job.id
  LOOP
    v_member_deferred := false;
    v_context := CASE
      WHEN pg_catalog.jsonb_typeof(
             v_member.payload_json->'correction_dirty_contexts'
           ) = 'object'
       AND pg_catalog.jsonb_typeof(
             v_member.payload_json->'correction_dirty_contexts'
               ->p_candidate_id::text
           ) = 'object'
        THEN v_member.payload_json->'correction_dirty_contexts'
               ->p_candidate_id::text
      ELSE '{}'::jsonb
    END;

    IF COALESCE(v_deferral_enabled, false)
       AND COALESCE(v_context->>'contract_version', '') =
             'CORRECTION_OWNED_DIRTY_CAUSAL_V1'
       AND COALESCE(v_context->>'candidate_id', '') = p_candidate_id::text
       AND COALESCE(v_context->>'correction_request_id', '')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND COALESCE(v_context->>'pay_batch_id', '')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND COALESCE(v_context->>'lifecycle_phase', '') IN (
         'REQUEST_PREPARE', 'REQUEST_START', 'FINANCIAL_PAGE_START',
         'FINANCIAL_PAGE_APPLIED', 'FINANCIAL_TERMINAL'
       )
       AND COALESCE(v_context->>'policy_x_boundary', '') IN (
         'POST_DRAFT_FROZEN_EVIDENCE', 'PRE_DRAFT_LIVE_TRUTH'
       )
       AND COALESCE(v_context->>'pre_request_source_change_seq', '')
             ~ '^[0-9]{1,18}$'
       AND COALESCE(v_context->>'pre_request_dirty_generation', '')
             ~ '^[0-9]{1,18}$'
       AND COALESCE(v_member.payload_json
             ->>'request_owned_scope_change_tx_token', '')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND COALESCE(v_member.payload_json->>'scope_change_tx_token', '') =
             COALESCE(v_member.payload_json
               ->>'request_owned_scope_change_tx_token', '')
       AND (
         v_member.scope_change_tx_token IS NULL
         OR v_member.scope_change_tx_token::text = COALESCE(
           v_member.payload_json->>'request_owned_scope_change_tx_token', ''
         )
       )
       AND pg_catalog.lower(pg_catalog.btrim(COALESCE(
             v_member.payload_json->>'policy_x_dirtying_only', 'false'
           ))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND pg_catalog.lower(pg_catalog.btrim(COALESCE(
             v_member.payload_json->>'economic_truth_mutation_allowed', 'false'
           ))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_context_digest := pg_catalog.encode(extensions.digest(
        pg_catalog.convert_to(
          'CORRECTION_OWNED_DIRTY_CAUSAL_V1' || '|' ||
          COALESCE(v_context->>'correction_request_id', '') || '|' ||
          COALESCE(v_context->>'correction_operation_id', '') || '|' ||
          COALESCE(v_context->>'correction_work_item_id', '') || '|' ||
          COALESCE(v_context->>'pay_batch_id', '') || '|' ||
          p_candidate_id::text || '|' ||
          COALESCE(v_context->>'lifecycle_phase', '') || '|' ||
          COALESCE(v_context->>'policy_x_boundary', '') || '|' ||
          COALESCE(v_context->>'pre_request_source_change_seq', '') || '|' ||
          COALESCE(v_context->>'pre_request_dirty_generation', '') || '|' ||
          COALESCE(v_context->>'pre_request_fence_digest', ''),
          'UTF8'
        ),
        'sha256'
      ), 'hex');

      IF v_context_digest = COALESCE(v_context->>'context_digest', '') THEN
        SELECT EXISTS (
          SELECT 1
          FROM public.pay_payment_correction_requests AS request_row
          JOIN public.banking_pay_operations AS correction_operation
            ON correction_operation.operation_type = 'PAYMENT_CORRECTION'
           AND correction_operation.input_json->>'correction_request_id' =
                 request_row.id::text
          JOIN public.pay_batch_candidates AS batch_candidate
            ON batch_candidate.pay_batch_id = request_row.pay_batch_id
           AND batch_candidate.candidate_id = p_candidate_id
          WHERE request_row.id =
                  (v_context->>'correction_request_id')::uuid
            AND request_row.pay_batch_id = (v_context->>'pay_batch_id')::uuid
            AND correction_operation.status IN (
              'QUEUED', 'RUNNING', 'WAITING_AUTHORISATION'
            )
            AND correction_operation.phase <> 'COMPLETE'
            AND request_row.status NOT IN ('CANCELLED', 'FAILED', 'REJECTED')
            AND request_row.created_at_utc <= GREATEST(
              v_member.created_at_utc,
              COALESCE(v_member.updated_at_utc, v_member.created_at_utc)
            )
            AND (
              COALESCE(v_context->>'correction_operation_id', '') = ''
              OR correction_operation.id::text =
                    v_context->>'correction_operation_id'
            )
        ) INTO v_member_deferred;
      END IF;
    ELSIF NOT COALESCE(v_deferral_enabled, false)
       AND pg_catalog.lower(pg_catalog.btrim(COALESCE(
             v_member.payload_json->>'trigger_table', ''
           ))) = 'pay_payment_correction_requests'
       AND pg_catalog.lower(pg_catalog.btrim(COALESCE(
             v_member.payload_json->>'policy_x_dirtying_only', 'false'
           ))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND pg_catalog.lower(pg_catalog.btrim(COALESCE(
             v_member.payload_json->>'economic_truth_mutation_allowed', 'false'
           ))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       AND (
         (
           pg_catalog.jsonb_typeof(v_member.payload_json->'reasons') = 'array'
           AND pg_catalog.jsonb_array_length(
                 v_member.payload_json->'reasons'
               ) > 0
           AND NOT EXISTS (
             SELECT 1
             FROM pg_catalog.jsonb_array_elements_text(
                    v_member.payload_json->'reasons'
                  ) AS dirty_reason(reason_text)
             WHERE pg_catalog.upper(pg_catalog.btrim(dirty_reason.reason_text))
                   NOT IN (
                     'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:INSERT',
                     'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:UPDATE'
                   )
           )
         )
         OR (
           pg_catalog.jsonb_typeof(v_member.payload_json->'reasons')
                 IS DISTINCT FROM 'array'
           AND pg_catalog.upper(pg_catalog.btrim(COALESCE(
                 v_member.payload_json->>'reason_latest',
                 v_member.payload_json->>'reason',
                 ''
               ))) IN (
                 'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:INSERT',
                 'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:UPDATE'
               )
         )
       ) THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.banking_pay_operations AS correction_operation
        JOIN public.pay_payment_correction_requests AS request_row
          ON request_row.id = CASE
            WHEN COALESCE(
                   correction_operation.input_json->>'correction_request_id',
                   ''
                 ) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN (correction_operation.input_json
                      ->>'correction_request_id')::uuid
            ELSE NULL::uuid
          END
        JOIN public.pay_payment_correction_request_candidates AS request_candidate
          ON request_candidate.correction_request_id = request_row.id
        JOIN public.pay_batch_candidates AS batch_candidate
          ON batch_candidate.id = request_candidate.pay_batch_candidate_id
         AND batch_candidate.candidate_id = p_candidate_id
        WHERE correction_operation.operation_type = 'PAYMENT_CORRECTION'
          AND correction_operation.status IN ('QUEUED', 'RUNNING')
          AND correction_operation.phase NOT IN ('REFRESH_WORKBENCH', 'COMPLETE')
          AND correction_operation.input_json
                ->'draft_overlay_fast_start_authorities'
                ->p_candidate_id::text->>'request_owned_dirty_job_id' =
                v_member.id::text
          AND request_row.status IN (
            'REQUESTED', 'AWAITING_AUTHORISATION', 'AUTHORISED',
            'EXPANDED', 'PROCESSING'
          )
          AND request_row.created_at_utc <= GREATEST(
            v_member.created_at_utc,
            COALESCE(v_member.updated_at_utc, v_member.created_at_utc)
          )
      ) INTO v_member_deferred;
    END IF;

    IF v_member_deferred THEN
      -- REQUEST_OWNED_CORRECTION_UNFINISHED remains outside this finite cohort.
      v_admitted_member_ids := pg_catalog.array_remove(
        v_admitted_member_ids,
        v_member.id
      );
      v_excluded_member_ids := pg_catalog.array_append(
        v_excluded_member_ids,
        v_member.id
      );
    END IF;
  END LOOP;

  -- The current job passed the same boundary immediately before this helper.
  IF NOT p_job_id = ANY(v_admitted_member_ids) THEN
    v_admitted_member_ids := pg_catalog.array_append(
      v_admitted_member_ids,
      p_job_id
    );
    v_excluded_member_ids := pg_catalog.array_remove(
      v_excluded_member_ids,
      p_job_id
    );
  END IF;

  v_member_count := pg_catalog.cardinality(v_admitted_member_ids);
  v_excluded_count := pg_catalog.cardinality(v_excluded_member_ids);

  SELECT max(candidate_job.updated_at_utc),
         max(candidate_job.payload_json->>'latest_event_at_utc')
  INTO v_snapshot_max_updated_at,
       v_snapshot_max_latest_event
  FROM pg_catalog.unnest(v_admitted_member_ids) AS cohort_member(id)
  JOIN public.banking_pay_workbench_jobs AS candidate_job
    ON candidate_job.id = cohort_member.id;

  IF COALESCE(v_member_count, 0) = 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_COHORT_CURRENT_MEMBER_INVALID'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(
           pg_catalog.array_agg(
             DISTINCT raw_scope.value_text::uuid
             ORDER BY raw_scope.value_text::uuid
           ),
           ARRAY[]::uuid[]
         )
  INTO v_timesheet_root_ids
  FROM (
    SELECT raw_target.value_text
    FROM pg_catalog.unnest(v_admitted_member_ids) AS cohort_member(id)
    JOIN public.banking_pay_workbench_jobs AS candidate_job
      ON candidate_job.id = cohort_member.id
    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements_text(
      CASE WHEN pg_catalog.jsonb_typeof(
                  candidate_job.payload_json->'targeted_timesheet_ids'
                ) = 'array'
        THEN candidate_job.payload_json->'targeted_timesheet_ids'
        ELSE '[]'::jsonb END
    ) AS raw_target(value_text)
    UNION ALL
    SELECT raw_linked.value_text
    FROM pg_catalog.unnest(v_admitted_member_ids) AS cohort_member(id)
    JOIN public.banking_pay_workbench_jobs AS candidate_job
      ON candidate_job.id = cohort_member.id
    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements_text(
      CASE WHEN pg_catalog.jsonb_typeof(
                  candidate_job.payload_json->'linked_timesheet_ids'
                ) = 'array'
        THEN candidate_job.payload_json->'linked_timesheet_ids'
        ELSE '[]'::jsonb END
    ) AS raw_linked(value_text)
  ) AS raw_scope(value_text)
  WHERE raw_scope.value_text
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  SELECT COALESCE(
           pg_catalog.array_agg(
             DISTINCT raw_case.value_text::uuid
             ORDER BY raw_case.value_text::uuid
           ),
           ARRAY[]::uuid[]
         )
  INTO v_finance_case_root_ids
  FROM pg_catalog.unnest(v_admitted_member_ids) AS cohort_member(id)
  JOIN public.banking_pay_workbench_jobs AS candidate_job
    ON candidate_job.id = cohort_member.id
  CROSS JOIN LATERAL pg_catalog.jsonb_array_elements_text(
    CASE WHEN pg_catalog.jsonb_typeof(
                candidate_job.payload_json->'finance_case_ids'
              ) = 'array'
      THEN candidate_job.payload_json->'finance_case_ids'
      ELSE '[]'::jsonb END
  ) AS raw_case(value_text)
  WHERE raw_case.value_text
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  SELECT EXISTS (
    SELECT 1
    FROM pg_catalog.unnest(v_admitted_member_ids) AS cohort_member(id)
    JOIN public.banking_pay_workbench_jobs AS candidate_job
      ON candidate_job.id = cohort_member.id
    WHERE NOT EXISTS (
        SELECT 1
        FROM (
          SELECT raw_target.value_text
          FROM pg_catalog.jsonb_array_elements_text(
            CASE WHEN pg_catalog.jsonb_typeof(
                        candidate_job.payload_json->'targeted_timesheet_ids'
                      ) = 'array'
              THEN candidate_job.payload_json->'targeted_timesheet_ids'
              ELSE '[]'::jsonb END
          ) AS raw_target(value_text)
          UNION ALL
          SELECT raw_linked.value_text
          FROM pg_catalog.jsonb_array_elements_text(
            CASE WHEN pg_catalog.jsonb_typeof(
                        candidate_job.payload_json->'linked_timesheet_ids'
                      ) = 'array'
              THEN candidate_job.payload_json->'linked_timesheet_ids'
              ELSE '[]'::jsonb END
          ) AS raw_linked(value_text)
          UNION ALL
          SELECT raw_case.value_text
          FROM pg_catalog.jsonb_array_elements_text(
            CASE WHEN pg_catalog.jsonb_typeof(
                        candidate_job.payload_json->'finance_case_ids'
                      ) = 'array'
              THEN candidate_job.payload_json->'finance_case_ids'
              ELSE '[]'::jsonb END
          ) AS raw_case(value_text)
        ) AS raw_scope
        WHERE raw_scope.value_text
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      )
  ) INTO v_contains_full_scope;

  v_timesheet_root_count := pg_catalog.cardinality(v_timesheet_root_ids);
  v_finance_case_root_count := pg_catalog.cardinality(v_finance_case_root_ids);

  IF v_contains_full_scope THEN
    v_authority_scope := 'CANDIDATE_FULL_LIVE';
    v_full_fallback_reason := 'COHORT_MEMBER_FULL_SCOPE';
  END IF;

  IF v_timesheet_root_count > 250 THEN
    v_authority_scope := 'CANDIDATE_FULL_LIVE';
    v_full_fallback_reason := 'COHORT_TIMESHEET_ROOT_CAP_EXCEEDED';
  ELSIF v_finance_case_root_count > 100 THEN
    v_authority_scope := 'CANDIDATE_FULL_LIVE';
    v_full_fallback_reason := 'COHORT_FINANCE_CASE_ROOT_CAP_EXCEEDED';
  ELSIF v_timesheet_root_count > 0 OR v_finance_case_root_count > 0 THEN
    IF pg_catalog.to_regprocedure(
         'public._pay_workbench_refresh_dependency_closure_v1(uuid,uuid[],uuid[],uuid[],integer,integer)'
       ) IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_REFRESH_DEPENDENCY_CLOSURE_UNAVAILABLE'
        USING ERRCODE = 'P0001';
    END IF;

    v_dependency_closure := public._pay_workbench_refresh_dependency_closure_v1(
      p_candidate_id,
      v_timesheet_root_ids,
      ARRAY[]::uuid[],
      v_finance_case_root_ids,
      250,
      100
    );

    IF pg_catalog.lower(pg_catalog.btrim(COALESCE(
         v_dependency_closure->>'requires_full_candidate', 'true'
       ))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR pg_catalog.lower(pg_catalog.btrim(COALESCE(
         v_dependency_closure->>'coverage_complete', 'false'
       ))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_authority_scope := 'CANDIDATE_FULL_LIVE';
      v_full_fallback_reason := COALESCE(
        NULLIF(pg_catalog.btrim(COALESCE(
          v_dependency_closure->>'fallback_reason', ''
        )), ''),
        'COHORT_DEPENDENCY_CLOSURE_INCOMPLETE'
      );
    ELSE
      SELECT COALESCE(pg_catalog.array_agg(
               DISTINCT raw_id.value_text::uuid
               ORDER BY raw_id.value_text::uuid
             ), ARRAY[]::uuid[])
      INTO v_effective_timesheet_ids
      FROM pg_catalog.jsonb_array_elements_text(COALESCE(
        v_dependency_closure->'effective_targeted_timesheet_ids',
        '[]'::jsonb
      )) AS raw_id(value_text)
      WHERE raw_id.value_text
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

      v_family_scope := public._pay_workbench_normalise_timesheet_rotation_scope_payload(
        v_effective_timesheet_ids,
        ARRAY[]::uuid[]
      );

      SELECT COALESCE(pg_catalog.array_agg(
               DISTINCT family_id.value_text::uuid
               ORDER BY family_id.value_text::uuid
             ), ARRAY[]::uuid[])
      INTO v_effective_timesheet_ids
      FROM (
        SELECT value_text
        FROM pg_catalog.jsonb_array_elements_text(COALESCE(
          v_family_scope->'targeted_timesheet_ids', '[]'::jsonb
        )) AS targeted_family(value_text)
        UNION ALL
        SELECT value_text
        FROM pg_catalog.jsonb_array_elements_text(COALESCE(
          v_family_scope->'linked_timesheet_ids', '[]'::jsonb
        )) AS linked_family(value_text)
      ) AS family_id(value_text)
      WHERE family_id.value_text
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

      IF pg_catalog.cardinality(v_effective_timesheet_ids) > 250 THEN
        v_authority_scope := 'CANDIDATE_FULL_LIVE';
        v_full_fallback_reason := 'COHORT_NORMALISED_TIMESHEET_CAP_EXCEEDED';
        v_effective_timesheet_ids := ARRAY[]::uuid[];
      ELSIF pg_catalog.cardinality(v_effective_timesheet_ids) = 0 THEN
        -- A finance-case root can legitimately resolve to no currently owned
        -- Timesheet. The existing processor treats that shape as Candidate
        -- full; preserve that fail-closed behavior instead of invoking the
        -- invalidator with an empty targeted pair set.
        v_authority_scope := 'CANDIDATE_FULL_LIVE';
        v_full_fallback_reason := 'COHORT_EMPTY_EFFECTIVE_TIMESHEET_SCOPE';
      END IF;
    END IF;
  END IF;

  IF v_authority_scope = 'CANDIDATE_FULL_LIVE'
     AND v_full_fallback_reason <> 'COHORT_MEMBER_FULL_SCOPE' THEN
    -- An incomplete/unbounded closure is represented by one stronger
    -- Candidate-full authority, never by a partial bounded subset.
    v_effective_timesheet_ids := ARRAY[]::uuid[];
  END IF;

  v_effective_timesheet_count := pg_catalog.cardinality(
    COALESCE(v_effective_timesheet_ids, ARRAY[]::uuid[])
  );

  -- Candidate registry/counter first, then bounded Timesheet state. This is
  -- the same metadata order used by the deferred finaliser after the jobs are
  -- already locked above.
  SELECT registry.dirty_generation,
         registry.current_source_change_seq,
         registry.last_scope_change_tx_token
  INTO v_registry_generation,
       v_registry_source_seq,
       v_registry_pending_token
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry
  WHERE registry.candidate_id = p_candidate_id
  FOR UPDATE;

  SELECT change_counter.scope_change_generation,
         change_counter.seq,
         change_counter.scope_change_tx_token
  INTO v_live_generation,
       v_live_source_seq,
       v_counter_pending_token
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text
  FOR UPDATE;

  IF v_effective_timesheet_count > 0 THEN
    PERFORM 1
    FROM private.banking_pay_workbench_timesheet_scope_state AS scope_state
    WHERE scope_state.timesheet_id = ANY(v_effective_timesheet_ids)
    ORDER BY scope_state.candidate_id, scope_state.timesheet_id
    FOR UPDATE;
  END IF;

  SELECT CASE
    WHEN COALESCE(current_job.payload_json->>'scope_change_tx_token', '')
           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN (current_job.payload_json->>'scope_change_tx_token')::uuid
    ELSE NULL::uuid
  END
  INTO v_common_token
  FROM public.banking_pay_workbench_jobs AS current_job
  WHERE current_job.id = p_job_id;

  SELECT scope_tx.state, scope_tx.allocated_generation
  INTO v_transaction_state, v_transaction_generation
  FROM public.banking_pay_scope_change_transactions AS scope_tx
  WHERE scope_tx.tx_token = v_common_token;

  v_common_generation := CASE
    WHEN v_registry_generation IS NOT NULL
     AND v_registry_generation = v_live_generation
      THEN v_registry_generation
    ELSE NULL::bigint
  END;

  SELECT NOT EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_jobs AS candidate_job
    WHERE candidate_job.id = ANY(v_admitted_member_ids)
      AND (
        v_common_token IS NULL
        OR candidate_job.scope_change_generation IS DISTINCT FROM
             v_common_generation
        OR COALESCE(candidate_job.payload_json->>'scope_change_generation', '')
             !~ '^[0-9]{1,18}$'
        OR (candidate_job.payload_json
              ->>'scope_change_generation')::bigint IS DISTINCT FROM
             v_common_generation
        OR COALESCE(candidate_job.payload_json->>'scope_change_tx_token', '')
             <> v_common_token::text
      )
  ) INTO v_all_members_match;

  SELECT NOT EXISTS (
    SELECT 1
    FROM unnest(COALESCE(
           v_effective_timesheet_ids, ARRAY[]::uuid[]
         )) AS required_scope(timesheet_id)
    LEFT JOIN private.banking_pay_workbench_timesheet_scope_state AS scope_state
      ON scope_state.timesheet_id = required_scope.timesheet_id
     AND scope_state.candidate_id = p_candidate_id
     AND scope_state.dirty_generation = v_common_generation
    WHERE scope_state.timesheet_id IS NULL
  ) INTO v_all_states_match;

  SELECT NOT EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_jobs AS candidate_job
    WHERE candidate_job.id = ANY(v_admitted_member_ids)
      AND (
        COALESCE(candidate_job.payload_json
          ->>'dirty_apply_cohort_contract_version', '') <>
            'DIRTY_APPLY_COHORT_AUTHORITY_V1'
        OR COALESCE(candidate_job.payload_json
          ->>'dirty_apply_cohort_candidate_id', '') <> p_candidate_id::text
        OR COALESCE(candidate_job.payload_json
          ->>'dirty_apply_cohort_tx_token', '') <> v_common_token::text
        OR COALESCE(candidate_job.payload_json
          ->>'dirty_apply_cohort_authority_scope', '') <>
            'CANDIDATE_FULL_LIVE'
      )
  ) INTO v_all_full_markers_match;

  v_authority_reusable :=
    v_common_token IS NOT NULL
    AND COALESCE(v_common_generation, 0) > 0
    AND v_transaction_state = 'FINALIZED'
    AND v_transaction_generation = v_common_generation
    AND v_all_members_match
    AND (
      (
        v_authority_scope = 'TARGETED_UNION'
        AND v_all_states_match
      )
      OR (
        v_authority_scope = 'CANDIDATE_FULL_LIVE'
        AND v_all_full_markers_match
      )
    );

  IF v_authority_reusable THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'REUSE_FINALIZED_AUTHORITY',
      'authority_reusable', true,
      'candidate_id', p_candidate_id,
      'scope_change_tx_token', v_common_token,
      'scope_change_generation', v_common_generation,
      'authority_scope', v_authority_scope,
      'member_count', v_member_count,
      'excluded_request_owned_count', v_excluded_count,
      'effective_timesheet_count', v_effective_timesheet_count,
      'source_change_seq', GREATEST(
        COALESCE(v_live_source_seq, 0),
        COALESCE(v_registry_source_seq, 0)
      )
    );
  END IF;

  -- A repeated call inside the same top-level worker transaction must wait for
  -- the deferred finaliser; it must not bump the source sequence again.
  SELECT
    v_common_token IS NOT NULL
    AND v_transaction_state = 'PENDING'
    AND v_registry_pending_token = v_common_token
    AND v_counter_pending_token = v_common_token
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_jobs AS candidate_job
      WHERE candidate_job.id = ANY(v_admitted_member_ids)
        AND (
          candidate_job.scope_change_tx_token IS DISTINCT FROM v_common_token
          OR candidate_job.scope_change_generation IS NOT NULL
          OR COALESCE(candidate_job.payload_json
               ->>'scope_change_tx_token', '') <> v_common_token::text
          OR COALESCE(candidate_job.payload_json
               ->>'dirty_apply_cohort_contract_version', '') <>
                 'DIRTY_APPLY_COHORT_AUTHORITY_V1'
          OR COALESCE(candidate_job.payload_json
               ->>'dirty_apply_cohort_candidate_id', '') <>
                 p_candidate_id::text
          OR COALESCE(candidate_job.payload_json
               ->>'dirty_apply_cohort_tx_token', '') <> v_common_token::text
        )
    )
  INTO v_pending_replay;

  IF v_pending_replay THEN
    UPDATE public.banking_pay_workbench_jobs AS current_job
    SET status = 'QUEUED',
        attempt_count = GREATEST(
          COALESCE(current_job.attempt_count, 0) - 1,
          0
        ),
        run_at_utc = v_now,
        started_at_utc = NULL,
        completed_at_utc = NULL,
        failed_at_utc = NULL,
        last_error_json = NULL,
        updated_at_utc = v_now
    WHERE current_job.id = p_job_id;

    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'WAITING_FOR_COHORT_FINALIZATION',
      'authority_reusable', false,
      'pending_finalization', true,
      'candidate_id', p_candidate_id,
      'scope_change_tx_token', v_common_token,
      'scope_change_generation', NULL,
      'authority_scope', v_authority_scope,
      'member_count', v_member_count,
      'excluded_request_owned_count', v_excluded_count,
      'effective_timesheet_count', v_effective_timesheet_count
    );
  END IF;

  v_stage_token := public.pay_workbench_scope_change_tx_token_v1();

  IF v_stage_token IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.banking_pay_scope_change_transactions AS scope_tx
    WHERE scope_tx.tx_token = v_stage_token
      AND scope_tx.state = 'PENDING'
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_COHORT_TOKEN_NOT_PENDING'
      USING ERRCODE = '40001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PAY_WORKBENCH_DIRTY_COHORT_TOKEN_NOT_PENDING',
        'job_id', p_job_id,
        'candidate_id', p_candidate_id,
        'scope_change_tx_token', v_stage_token
      )::text;
  END IF;

  -- One Candidate source bump per admitted cohort. If this same transaction
  -- already staged the Candidate counter under the token, reuse it.
  IF NOT EXISTS (
    SELECT 1
    FROM public.app_change_counters AS change_counter
    WHERE change_counter.entity_key =
            'pay_candidate:' || p_candidate_id::text
      AND change_counter.scope_change_tx_token = v_stage_token
  ) THEN
    PERFORM public._change_bump('pay_candidate:' || p_candidate_id::text);
  END IF;

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_live_source_seq
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  SELECT GREATEST(
    COALESCE(v_live_source_seq, 0),
    COALESCE(v_registry_source_seq, 0),
    COALESCE(max(GREATEST(
      COALESCE(CASE
        WHEN COALESCE(candidate_job.payload_json
               ->>'latest_source_change_seq', '') ~ '^[0-9]+$'
          THEN (candidate_job.payload_json
                  ->>'latest_source_change_seq')::bigint
        ELSE 0 END, 0),
      COALESCE(CASE
        WHEN COALESCE(candidate_job.payload_json
               ->>'source_change_seq', '') ~ '^[0-9]+$'
          THEN (candidate_job.payload_json->>'source_change_seq')::bigint
        ELSE 0 END, 0),
      COALESCE(CASE
        WHEN COALESCE(candidate_job.payload_json
               ->>'source_change_sequence', '') ~ '^[0-9]+$'
          THEN (candidate_job.payload_json
                  ->>'source_change_sequence')::bigint
        ELSE 0 END, 0)
    )), 0)
  )
  INTO v_common_source_seq
  FROM public.banking_pay_workbench_jobs AS candidate_job
  WHERE candidate_job.id = ANY(v_admitted_member_ids);

  IF v_authority_scope = 'CANDIDATE_FULL_LIVE' THEN
    v_invalidation_candidate_ids := ARRAY[p_candidate_id];
    v_invalidation_timesheet_ids := ARRAY[NULL::uuid];

    -- When a bounded union is available beside an explicit ALL member, stamp
    -- those Timesheet rows too so targeted jobs retain their ordinary exact
    -- per-row proof. ALL remains the stronger Candidate authority.
    IF v_effective_timesheet_count > 0 THEN
      v_invalidation_candidate_ids := v_invalidation_candidate_ids ||
        pg_catalog.array_fill(
          p_candidate_id,
          ARRAY[v_effective_timesheet_count]
        );
      v_invalidation_timesheet_ids := v_invalidation_timesheet_ids ||
        v_effective_timesheet_ids;
    END IF;
  ELSE
    v_invalidation_candidate_ids := pg_catalog.array_fill(
      p_candidate_id,
      ARRAY[v_effective_timesheet_count]
    );
    v_invalidation_timesheet_ids := v_effective_timesheet_ids;
  END IF;

  v_invalidation_result := private.pay_workbench_scope_invalidate_v1(
    v_invalidation_candidate_ids,
    v_invalidation_timesheet_ids,
    'DIRTY_APPLY_CANDIDATE_COHORT_REISSUE',
    v_stage_token,
    pg_catalog.jsonb_build_object(
      'skip_candidate_job_enqueue', true,
      'latest_source_change_seq', v_common_source_seq,
      'source_change_seq', v_common_source_seq,
      'source_change_sequence', v_common_source_seq,
      'dirty_apply_cohort_contract_version',
        'DIRTY_APPLY_COHORT_AUTHORITY_V1',
      'dirty_apply_cohort_candidate_id', p_candidate_id,
      'dirty_apply_cohort_tx_token', v_stage_token,
      'dirty_apply_cohort_authority_scope', v_authority_scope,
      'dirty_apply_cohort_member_count', v_member_count,
      'dirty_apply_cohort_excluded_request_owned_count', v_excluded_count,
      'dirty_apply_cohort_effective_timesheet_count',
        v_effective_timesheet_count,
      'dirty_apply_cohort_full_fallback_reason', v_full_fallback_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'economic_calculation_performed', false
    )
  );

  IF pg_catalog.lower(pg_catalog.btrim(COALESCE(
       v_invalidation_result->>'ok', 'false'
     ))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
     OR COALESCE(v_invalidation_result->>'scope_change_tx_token', '') <>
          v_stage_token::text THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_COHORT_INVALIDATION_NOT_STAGED'
      USING ERRCODE = '40001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PAY_WORKBENCH_DIRTY_COHORT_INVALIDATION_NOT_STAGED',
        'job_id', p_job_id,
        'candidate_id', p_candidate_id,
        'scope_change_tx_token', v_stage_token,
        'invalidation_result', v_invalidation_result
      )::text;
  END IF;

  UPDATE public.banking_pay_workbench_jobs AS candidate_job
  SET status = CASE
        WHEN candidate_job.id = p_job_id THEN 'QUEUED'
        ELSE candidate_job.status
      END,
      attempt_count = CASE
        WHEN candidate_job.id = p_job_id THEN GREATEST(
          COALESCE(candidate_job.attempt_count, 0) - 1,
          0
        )
        ELSE candidate_job.attempt_count
      END,
      run_at_utc = CASE
        WHEN candidate_job.id = p_job_id THEN v_now
        ELSE candidate_job.run_at_utc
      END,
      started_at_utc = CASE
        WHEN candidate_job.id = p_job_id THEN NULL
        ELSE candidate_job.started_at_utc
      END,
      completed_at_utc = CASE
        WHEN candidate_job.id = p_job_id THEN NULL
        ELSE candidate_job.completed_at_utc
      END,
      failed_at_utc = CASE
        WHEN candidate_job.id = p_job_id THEN NULL
        ELSE candidate_job.failed_at_utc
      END,
      last_error_json = CASE
        WHEN candidate_job.id = p_job_id THEN NULL
        ELSE candidate_job.last_error_json
      END,
      payload_json = (
        COALESCE(candidate_job.payload_json, '{}'::jsonb)
          - 'scope_change_tx_token'
          - 'scope_change_generation'
          - 'bounded_scope_state_precedes_job'
      ) || pg_catalog.jsonb_build_object(
        'scope_change_tx_token', v_stage_token,
        'bounded_scope_state_precedes_job', true,
        'preinvalidated_scope_reissued', true,
        'preinvalidated_scope_reissued_at_utc', v_now,
        'preinvalidated_scope_reissue_pending_finalization', true,
        'preinvalidated_scope_original_tx_token',
          candidate_job.payload_json->>'scope_change_tx_token',
        'preinvalidated_scope_original_generation',
          candidate_job.payload_json->>'scope_change_generation',
        'preinvalidated_scope_effective_timesheet_count',
          v_effective_timesheet_count,
        'latest_source_change_seq', v_common_source_seq,
        'source_change_seq', v_common_source_seq,
        'source_change_sequence', v_common_source_seq,
        'dirty_apply_cohort_contract_version',
          'DIRTY_APPLY_COHORT_AUTHORITY_V1',
        'dirty_apply_cohort_candidate_id', p_candidate_id,
        'dirty_apply_cohort_tx_token', v_stage_token,
        'dirty_apply_cohort_leader_job_id', p_job_id,
        'dirty_apply_cohort_member_count', v_member_count,
        'dirty_apply_cohort_excluded_request_owned_count', v_excluded_count,
        'dirty_apply_cohort_authority_scope', v_authority_scope,
        'dirty_apply_cohort_contains_full_scope', v_contains_full_scope,
        'dirty_apply_cohort_effective_timesheet_count',
          v_effective_timesheet_count,
        'dirty_apply_cohort_source_change_seq', v_common_source_seq,
        'dirty_apply_cohort_full_fallback_reason', v_full_fallback_reason,
        'dirty_apply_cohort_snapshot_max_updated_at_utc',
          v_snapshot_max_updated_at,
        'dirty_apply_cohort_snapshot_max_latest_event_at_utc',
          v_snapshot_max_latest_event,
        'dirty_apply_cohort_staged_at_utc', v_now,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      ),
      scope_change_tx_token = v_stage_token,
      scope_change_generation = NULL,
      updated_at_utc = v_now
  WHERE candidate_job.id = ANY(v_admitted_member_ids);

  IF EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_jobs AS candidate_job
    WHERE candidate_job.id = ANY(v_admitted_member_ids)
      AND (
        candidate_job.scope_change_tx_token IS DISTINCT FROM v_stage_token
        OR candidate_job.scope_change_generation IS NOT NULL
        OR COALESCE(candidate_job.payload_json
             ->>'scope_change_tx_token', '') <> v_stage_token::text
        OR COALESCE(candidate_job.payload_json
             ->>'dirty_apply_cohort_tx_token', '') <> v_stage_token::text
      )
  ) OR NOT EXISTS (
    SELECT 1
    FROM private.banking_pay_workbench_candidate_scope_registry AS registry
    WHERE registry.candidate_id = p_candidate_id
      AND registry.last_scope_change_tx_token = v_stage_token
      AND registry.current_source_change_seq >= v_common_source_seq
  ) OR NOT EXISTS (
    SELECT 1
    FROM public.app_change_counters AS change_counter
    WHERE change_counter.entity_key =
            'pay_candidate:' || p_candidate_id::text
      AND change_counter.scope_change_tx_token = v_stage_token
      AND change_counter.seq >= v_common_source_seq
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_COHORT_POSTCONDITION_FAILED'
      USING ERRCODE = '40001', DETAIL = pg_catalog.jsonb_build_object(
        'code', 'PAY_WORKBENCH_DIRTY_COHORT_POSTCONDITION_FAILED',
        'job_id', p_job_id,
        'candidate_id', p_candidate_id,
        'scope_change_tx_token', v_stage_token,
        'member_count', v_member_count
      )::text;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'COHORT_REISSUED_PENDING_FINALIZATION',
    'authority_reusable', false,
    'pending_finalization', true,
    'candidate_id', p_candidate_id,
    'scope_change_tx_token', v_stage_token,
    'scope_change_generation', NULL,
    'authority_scope', v_authority_scope,
    'full_fallback_reason', v_full_fallback_reason,
    'member_count', v_member_count,
    'excluded_request_owned_count', v_excluded_count,
    'effective_timesheet_count', v_effective_timesheet_count,
    'source_change_seq', v_common_source_seq,
    'snapshot_max_updated_at_utc', v_snapshot_max_updated_at,
    'snapshot_max_latest_event_at_utc', v_snapshot_max_latest_event
  );
END;
$function$;

-- public.pay_workbench_candidate_dirty_apply_job_process from supabase/repeatable/08092026_0518_banking_pay_candidate_dirty_cohort_authority_v1.sql; definition SHA-256 53ec276a36e132f594d5c7a78204d7364f97555a658f720b2a2f6d822386da0b.
CREATE OR REPLACE FUNCTION public.pay_workbench_candidate_dirty_apply_job_process(p_job_id uuid, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_now timestamptz := clock_timestamp();
  v_job public.banking_pay_workbench_jobs%ROWTYPE;
  v_payload jsonb := '{}'::jsonb;
  v_candidate_id uuid;
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_finance_case_ids uuid[] := ARRAY[]::uuid[];
  v_dependency_closure_json jsonb := '{}'::jsonb;
  v_dependency_closure_requires_full boolean := false;
  v_dependency_closure_reason text := NULL::text;
  v_family_scope_json jsonb := '{}'::jsonb;
  v_family_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_reported_family_timesheet_count integer := 0;
  v_canonical_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_canonical_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_all_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_effective_bounded_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_preceding_scope_authority_reusable boolean := false;
  v_preinvalidated_scope_reissued boolean := false;
  v_payload_scope_change_tx_token uuid := NULL::uuid;
  v_payload_scope_change_generation bigint := NULL::bigint;
  v_effective_scope_change_tx_token uuid := NULL::uuid;
  v_effective_scope_change_generation bigint := NULL::bigint;
  v_scope_transaction_state text := NULL::text;
  v_scope_transaction_generation bigint := NULL::bigint;
  v_registry_dirty_generation bigint := NULL::bigint;
  v_live_scope_change_generation bigint := NULL::bigint;
  v_scope_state_generation_match_count integer := 0;
  v_dirty_cohort_result jsonb := '{}'::jsonb;
  v_dirty_cohort_action text := NULL::text;
  v_dirty_cohort_authority_scope text := NULL::text;
  v_dirty_cohort_full_authority_reusable boolean := false;
  v_dirty_cohort_fast_path_reusable boolean := false;
  v_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_reason text := 'DIRTY_TRIGGER:CANDIDATE';
  v_payload_seq bigint := 0;
  v_live_seq bigint := 0;
  v_processed_source_change_seq bigint := 0;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_updated integer := 0;
  v_scope_count integer := 0;
  v_source_dirty_count integer := 0;
  v_source_dirty_total integer := 0;
  v_line_work_count integer := 0;
  v_line_work_total integer := 0;
  v_preview_count integer := 0;
  v_preview_total integer := 0;
  v_session_count integer := 0;
  v_jobs_queued integer := 0;
  v_refresh_result jsonb := '{}'::jsonb;
  v_refresh_payload_json jsonb := '{}'::jsonb;
  v_jobs_coalesced_active integer := 0;
  v_jobs_coalesced_complete integer := 0;
  v_jobs_requeued_for_conflict integer := 0;
  v_preflight_result jsonb := '{}'::jsonb;
  v_preflight_action text := 'PROCEED';
  v_preflight_match_count integer := 0;
  v_dirty_marking_skipped boolean := false;
  v_is_authorise_delta_targeted boolean := false;
  v_lifecycle_context text := NULL::text;
  v_candidate_serial_state jsonb := '{}'::jsonb;
  v_candidate_serial_blocked boolean := false;
  v_scope_ensure_result jsonb := '{}'::jsonb;
  v_new_scope_baseline_required boolean := false;
  v_session_scan_cutoff_created_at timestamptz;
  v_session_scan_cutoff_id uuid;
  v_session_scan_last_created_at timestamptz;
  v_session_scan_last_id uuid;
  v_session_scan_has_more boolean := false;
  v_session_scan_started_at timestamptz;
  v_session_scan_sessions_examined bigint := 0;
  v_session_page_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_lock_acquired boolean := false;
  v_private_cursor jsonb := '{}'::jsonb;
  v_cursor_sequence bigint := NULL::bigint;
  v_reuse_selection jsonb := '{}'::jsonb;
  v_reuse_job_id uuid := NULL::uuid;
  v_reuse_source_session_id uuid := NULL::uuid;
  v_reuse_dedupe_key text := NULL::text;
  v_request_owned_dirty_request_id uuid := NULL::uuid;
  v_request_owned_dirty_operation_id uuid := NULL::uuid;
  v_request_owned_dirty_operation_phase text := NULL::text;
  v_request_owned_dirty_context jsonb := '{}'::jsonb;
  v_request_owned_dirty_context_digest text := NULL::text;
  v_request_owned_dirty_deferral_enabled boolean := false;
  v_request_owned_dirty_delay interval := interval '5 seconds';
BEGIN
  SELECT job_row.*
  INTO v_job
  FROM public.banking_pay_workbench_jobs AS job_row
  WHERE job_row.id = p_job_id
  FOR UPDATE;

  IF v_job.id IS NULL THEN
    RAISE EXCEPTION 'Banking Pay candidate dirty apply job not found: %', p_job_id
      USING ERRCODE = 'P0002';
  END IF;
  IF UPPER(BTRIM(COALESCE(v_job.job_type, ''))) <> 'WORKBENCH_CANDIDATE_DIRTY_APPLY' THEN
    RAISE EXCEPTION 'Job % is %, not WORKBENCH_CANDIDATE_DIRTY_APPLY', p_job_id, v_job.job_type
      USING ERRCODE = '22023';
  END IF;
  IF UPPER(BTRIM(COALESCE(v_job.status, ''))) <> 'RUNNING' THEN
    RAISE EXCEPTION 'Job % must be RUNNING before processing; status=%', p_job_id, v_job.status
      USING ERRCODE = '55000';
  END IF;

  v_payload := COALESCE(v_job.payload_json, '{}'::jsonb);
  v_preinvalidated_scope_reissued := lower(BTRIM(COALESCE(
    v_payload->>'preinvalidated_scope_reissued','false'
  ))) IN ('true','t','1','yes','y','on');
  v_candidate_id := COALESCE(
    v_job.candidate_id,
    CASE WHEN COALESCE(v_payload->>'candidate_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (v_payload->>'candidate_id')::uuid END
  );
  IF v_candidate_id IS NULL THEN
    RAISE EXCEPTION 'Candidate dirty apply job % has no candidate_id', p_job_id
      USING ERRCODE = '22023';
  END IF;

  v_candidate_lock_acquired := pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtextextended(
      public._pay_workbench_candidate_serial_key(v_candidate_id),
      24062027
    )
  );

  IF v_candidate_lock_acquired THEN
    v_candidate_serial_state := public._pay_workbench_candidate_serial_active_state(
      p_job_id,
      v_candidate_id,
      v_job.job_type,
      v_payload,
      v_now
    );
  END IF;
  v_candidate_serial_blocked := NOT v_candidate_lock_acquired;

  IF v_candidate_serial_blocked IS TRUE THEN
    UPDATE public.banking_pay_workbench_jobs AS delayed_job
    SET status = 'QUEUED',
        attempt_count = GREATEST(COALESCE(delayed_job.attempt_count, 0) - 1, 0),
        run_at_utc = GREATEST(COALESCE(delayed_job.run_at_utc, v_now), v_now + interval '5 seconds'),
        started_at_utc = NULL,
        updated_at_utc = v_now,
        payload_json = public._pay_workbench_dirty_payload_merge(
          COALESCE(delayed_job.payload_json, '{}'::jsonb),
          jsonb_strip_nulls(jsonb_build_object(
            'candidate_serial_key', public._pay_workbench_candidate_serial_key(v_candidate_id),
            'candidate_serial_candidate_id', v_candidate_id::text,
            'candidate_serial_blocked_by_job_id', v_candidate_serial_state->>'blocked_job_id',
            'candidate_serial_blocked_by_chain_job_id', v_candidate_serial_state->>'blocked_chain_job_id',
            'candidate_serial_blocked_by_projection_run_id', v_candidate_serial_state->>'projection_run_id',
            'candidate_serial_wait_reason', COALESCE(v_candidate_serial_state->>'reason', CASE WHEN NOT v_candidate_lock_acquired THEN 'CANDIDATE_SERIAL_LOCK_BUSY' ELSE 'CANDIDATE_SERIAL_DIRTY_APPLY_DELAYED' END),
            'candidate_serial_delayed_at_utc', v_now::text,
            'dirty_apply_row_marking_applied', false,
            'dirty_marking_skipped', true,
            'session_progress_dirtying_skipped', true,
            'classifier_work_skipped_by_candidate_serial', true,
            'source_build_enqueue_skipped_by_candidate_serial', true,
            'line_work_enqueue_skipped_by_candidate_serial', true,
            'preview_materialise_enqueue_skipped_by_candidate_serial', true,
            'rerun_required', true,
            'has_more', true,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          ))
        )
    WHERE delayed_job.id = p_job_id;

    PERFORM public._pay_workbench_candidate_serial_audit(
      'CANDIDATE_SERIAL_DIRTY_APPLY_DELAYED',
      p_job_id,
      v_candidate_id,
      COALESCE(v_candidate_serial_state, '{}'::jsonb) || jsonb_build_object(
        'job_type', v_job.job_type,
        'dirty_apply_row_marking_applied', false,
        'dirty_marking_skipped', true,
        'delayed_until_utc', (v_now + interval '5 seconds')::text
      ),
      'CANDIDATE_SERIAL_DIRTY_APPLY_DELAYED',
      NULL::uuid
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', p_job_id::text,
      'candidate_id', v_candidate_id::text,
      'candidate_serial_delayed', true,
      'has_more', true,
      'rerun_required', true,
      'next_cursor_json', COALESCE(v_job.private_cursor_json, '{}'::jsonb),
      'reason', COALESCE(v_candidate_serial_state->>'reason', CASE WHEN NOT v_candidate_lock_acquired THEN 'CANDIDATE_SERIAL_LOCK_BUSY' ELSE 'CANDIDATE_SERIAL_DIRTY_APPLY_DELAYED' END),
      'dirty_apply_row_marking_applied', false,
      'dirty_marking_skipped', true,
      'session_progress_dirtying_skipped', true,
      'classifier_work_skipped_by_candidate_serial', true,
      'source_build_enqueue_skipped_by_candidate_serial', true,
      'line_work_enqueue_skipped_by_candidate_serial', true,
      'preview_materialise_enqueue_skipped_by_candidate_serial', true,
      'elapsed_ms', EXTRACT(MILLISECONDS FROM clock_timestamp() - v_started_at)
    );
  END IF;

  SELECT COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid), ARRAY[]::uuid[])
  INTO v_targeted_timesheet_ids
  FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_payload->'targeted_timesheet_ids') = 'array' THEN v_payload->'targeted_timesheet_ids' ELSE '[]'::jsonb END) AS raw_value(value_text)
  WHERE raw_value.value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  SELECT COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid), ARRAY[]::uuid[])
  INTO v_linked_timesheet_ids
  FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_payload->'linked_timesheet_ids') = 'array' THEN v_payload->'linked_timesheet_ids' ELSE '[]'::jsonb END) AS raw_value(value_text)
  WHERE raw_value.value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  SELECT COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid), ARRAY[]::uuid[])
  INTO v_finance_case_ids
  FROM jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(v_payload->'finance_case_ids') = 'array'
        THEN v_payload->'finance_case_ids'
      ELSE '[]'::jsonb
    END
  ) AS raw_value(value_text)
  WHERE raw_value.value_text
    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  IF COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0
     OR COALESCE(array_length(v_linked_timesheet_ids, 1), 0) > 0
     OR COALESCE(array_length(v_finance_case_ids, 1), 0) > 0 THEN
    IF to_regprocedure(
         'public._pay_workbench_refresh_dependency_closure_v1(uuid,uuid[],uuid[],uuid[],integer,integer)'
       ) IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_REFRESH_DEPENDENCY_CLOSURE_UNAVAILABLE'
        USING ERRCODE = 'P0001';
    END IF;

    EXECUTE
      'SELECT public._pay_workbench_refresh_dependency_closure_v1($1,$2,$3,$4,$5,$6)'
    INTO v_dependency_closure_json
    USING
      v_candidate_id,
      v_targeted_timesheet_ids,
      v_linked_timesheet_ids,
      v_finance_case_ids,
      250,
      100;

    v_dependency_closure_requires_full :=
      LOWER(BTRIM(COALESCE(
        v_dependency_closure_json->>'requires_full_candidate',
        'true'
      ))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR LOWER(BTRIM(COALESCE(
        v_dependency_closure_json->>'coverage_complete',
        'false'
      ))) NOT IN ('true', 't', '1', 'yes', 'y', 'on');
    v_dependency_closure_reason := NULLIF(BTRIM(COALESCE(
      v_dependency_closure_json->>'fallback_reason',
      ''
    )), '');

    IF v_dependency_closure_requires_full THEN
      v_targeted_timesheet_ids := ARRAY[]::uuid[];
      v_linked_timesheet_ids := ARRAY[]::uuid[];
      v_finance_case_ids := ARRAY[]::uuid[];
      v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
    ELSE
      SELECT COALESCE(array_agg(DISTINCT value::uuid ORDER BY value::uuid), ARRAY[]::uuid[])
      INTO v_targeted_timesheet_ids
      FROM jsonb_array_elements_text(
        COALESCE(v_dependency_closure_json->'effective_targeted_timesheet_ids', '[]'::jsonb)
      ) AS effective_timesheet(value)
      WHERE value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

      v_linked_timesheet_ids := ARRAY[]::uuid[];

      SELECT COALESCE(array_agg(DISTINCT value::uuid ORDER BY value::uuid), ARRAY[]::uuid[])
      INTO v_finance_case_ids
      FROM jsonb_array_elements_text(
        COALESCE(v_dependency_closure_json->'effective_finance_case_ids', '[]'::jsonb)
      ) AS effective_finance_case(value)
      WHERE value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
    END IF;
  END IF;

  IF COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0
     OR COALESCE(array_length(v_finance_case_ids, 1), 0) > 0 THEN
    v_family_scope_json := public._pay_workbench_normalise_timesheet_rotation_scope_payload(v_targeted_timesheet_ids, v_linked_timesheet_ids);

    SELECT COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid), ARRAY[]::uuid[])
    INTO v_family_timesheet_ids
    FROM jsonb_array_elements_text(COALESCE(v_family_scope_json->'family_timesheet_ids', '[]'::jsonb)) AS raw_value(value_text)
    WHERE raw_value.value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    SELECT COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid), ARRAY[]::uuid[])
    INTO v_canonical_targeted_timesheet_ids
    FROM jsonb_array_elements_text(COALESCE(v_family_scope_json->'targeted_timesheet_ids', '[]'::jsonb)) AS raw_value(value_text)
    WHERE raw_value.value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    SELECT COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid), ARRAY[]::uuid[])
    INTO v_canonical_linked_timesheet_ids
    FROM jsonb_array_elements_text(COALESCE(v_family_scope_json->'linked_timesheet_ids', '[]'::jsonb)) AS raw_value(value_text)
    WHERE raw_value.value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    SELECT COALESCE(array_agg(DISTINCT all_ids.timesheet_id ORDER BY all_ids.timesheet_id), ARRAY[]::uuid[])
    INTO v_all_timesheet_ids
    FROM (
      SELECT unnest(v_targeted_timesheet_ids) AS timesheet_id
      UNION ALL
      SELECT unnest(v_linked_timesheet_ids) AS timesheet_id
      UNION ALL
      SELECT unnest(v_family_timesheet_ids) AS timesheet_id
    ) AS all_ids
    WHERE all_ids.timesheet_id IS NOT NULL;
    v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
  ELSE
    v_linked_timesheet_ids := ARRAY[]::uuid[];
    v_family_timesheet_ids := ARRAY[]::uuid[];
    v_canonical_targeted_timesheet_ids := ARRAY[]::uuid[];
    v_canonical_linked_timesheet_ids := ARRAY[]::uuid[];
    v_all_timesheet_ids := ARRAY[]::uuid[];
    v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT bounded_id ORDER BY bounded_id), ARRAY[]::uuid[])
  INTO v_effective_bounded_timesheet_ids
  FROM (
    SELECT unnest(v_canonical_targeted_timesheet_ids) AS bounded_id
    UNION ALL
    SELECT unnest(v_canonical_linked_timesheet_ids) AS bounded_id
  ) AS bounded_scope
  WHERE bounded_id IS NOT NULL;

  v_reason := COALESCE(NULLIF(BTRIM(COALESCE(v_payload->>'reason_latest', v_payload->>'reason', '')), ''), 'DIRTY_TRIGGER:CANDIDATE');
  v_payload_seq := GREATEST(
    COALESCE(CASE WHEN COALESCE(v_payload->>'latest_source_change_seq', '') ~ '^\d+$' THEN (v_payload->>'latest_source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_seq', '') ~ '^\d+$' THEN (v_payload->>'source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_sequence', '') ~ '^\d+$' THEN (v_payload->>'source_change_sequence')::bigint END, 0)
  );

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_live_seq
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || v_candidate_id::text;

  v_processed_source_change_seq := GREATEST(COALESCE(v_payload_seq, 0), COALESCE(v_live_seq, 0));

  -- A correction request transition is orchestration evidence, not economic
  -- truth.  Validate the transaction-stamped causal envelope before consulting
  -- the durable correction lifecycle.  The latest scope token must be the
  -- request-owned token; any later unrelated invalidation changes that token
  -- and immediately falls through to the ordinary classifier.
  SELECT COALESCE(
    (pg_catalog.to_jsonb(settings_row)
      ->>'banking_pay_correction_request_dirty_deferral_v1_enabled')::boolean,
    false
  )
  INTO v_request_owned_dirty_deferral_enabled
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  v_request_owned_dirty_context:=CASE
    WHEN pg_catalog.jsonb_typeof(v_payload->'correction_dirty_contexts')='object'
      AND pg_catalog.jsonb_typeof(
        v_payload->'correction_dirty_contexts'->v_candidate_id::text
      )='object'
      THEN v_payload->'correction_dirty_contexts'->v_candidate_id::text
    ELSE '{}'::jsonb
  END;

  IF COALESCE(v_request_owned_dirty_deferral_enabled,false)
     AND COALESCE(v_request_owned_dirty_context->>'contract_version','')
           ='CORRECTION_OWNED_DIRTY_CAUSAL_V1'
     AND COALESCE(v_request_owned_dirty_context->>'candidate_id','')=v_candidate_id::text
     AND COALESCE(v_request_owned_dirty_context->>'correction_request_id','')
           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     AND COALESCE(v_request_owned_dirty_context->>'pay_batch_id','')
           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     AND COALESCE(v_request_owned_dirty_context->>'lifecycle_phase','') IN (
       'REQUEST_PREPARE','REQUEST_START','FINANCIAL_PAGE_START',
       'FINANCIAL_PAGE_APPLIED','FINANCIAL_TERMINAL'
     )
     AND COALESCE(v_request_owned_dirty_context->>'policy_x_boundary','') IN (
       'POST_DRAFT_FROZEN_EVIDENCE','PRE_DRAFT_LIVE_TRUTH'
     )
     AND COALESCE(v_request_owned_dirty_context->>'pre_request_source_change_seq','')
           ~ '^[0-9]{1,18}$'
     AND COALESCE(v_request_owned_dirty_context->>'pre_request_dirty_generation','')
           ~ '^[0-9]{1,18}$'
     AND COALESCE(v_payload->>'request_owned_scope_change_tx_token','')
           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     AND COALESCE(v_payload->>'scope_change_tx_token','')
           =COALESCE(v_payload->>'request_owned_scope_change_tx_token','')
     AND (
       v_job.scope_change_tx_token IS NULL
       OR v_job.scope_change_tx_token::text
            =COALESCE(v_payload->>'request_owned_scope_change_tx_token','')
     )
     AND LOWER(BTRIM(COALESCE(v_payload->>'policy_x_dirtying_only','false')))
           IN ('true','t','1','yes','y','on')
     AND LOWER(BTRIM(COALESCE(v_payload->>'economic_truth_mutation_allowed','false')))
           NOT IN ('true','t','1','yes','y','on') THEN
    v_request_owned_dirty_context_digest:=pg_catalog.encode(extensions.digest(
      pg_catalog.convert_to(
        'CORRECTION_OWNED_DIRTY_CAUSAL_V1'||'|'||
        COALESCE(v_request_owned_dirty_context->>'correction_request_id','')||'|'||
        COALESCE(v_request_owned_dirty_context->>'correction_operation_id','')||'|'||
        COALESCE(v_request_owned_dirty_context->>'correction_work_item_id','')||'|'||
        COALESCE(v_request_owned_dirty_context->>'pay_batch_id','')||'|'||
        v_candidate_id::text||'|'||
        COALESCE(v_request_owned_dirty_context->>'lifecycle_phase','')||'|'||
        COALESCE(v_request_owned_dirty_context->>'policy_x_boundary','')||'|'||
        COALESCE(v_request_owned_dirty_context->>'pre_request_source_change_seq','')||'|'||
        COALESCE(v_request_owned_dirty_context->>'pre_request_dirty_generation','')||'|'||
        COALESCE(v_request_owned_dirty_context->>'pre_request_fence_digest',''),
        'UTF8'
      ),
      'sha256'
    ),'hex');

    IF v_request_owned_dirty_context_digest
         =COALESCE(v_request_owned_dirty_context->>'context_digest','') THEN
      SELECT request_row.id,correction_operation.id,correction_operation.phase,
             CASE
               WHEN correction_operation.status='WAITING_AUTHORISATION'
                 OR correction_operation.phase='AWAITING_REAUTHENTICATION'
                 OR request_row.status IN ('PLANNING','PLANNED','REQUESTED','AWAITING_AUTHORISATION')
                 THEN interval '30 seconds'
               ELSE interval '5 seconds'
             END
      INTO v_request_owned_dirty_request_id,
           v_request_owned_dirty_operation_id,
           v_request_owned_dirty_operation_phase,
           v_request_owned_dirty_delay
      FROM public.pay_payment_correction_requests AS request_row
      JOIN public.banking_pay_operations AS correction_operation
        ON correction_operation.operation_type='PAYMENT_CORRECTION'
       AND correction_operation.input_json->>'correction_request_id'=request_row.id::text
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.pay_batch_id=request_row.pay_batch_id
       AND batch_candidate.candidate_id=v_candidate_id
      WHERE request_row.id=(v_request_owned_dirty_context->>'correction_request_id')::uuid
        AND request_row.pay_batch_id=(v_request_owned_dirty_context->>'pay_batch_id')::uuid
        AND correction_operation.status IN ('QUEUED','RUNNING','WAITING_AUTHORISATION')
        AND correction_operation.phase<>'COMPLETE'
        AND request_row.status NOT IN ('CANCELLED','FAILED','REJECTED')
        -- Candidate dirty jobs are deliberately deduplicated and may be reused.
        -- Their immutable created_at can therefore predate the correction even
        -- when the exact request-owned event was merged later.  The causal
        -- digest and transaction token above prove ownership; updated_at proves
        -- that this durable job received the request event after it existed.
        AND request_row.created_at_utc<=GREATEST(
          v_job.created_at_utc,
          COALESCE(v_job.updated_at_utc,v_job.created_at_utc)
        )
        AND (
          COALESCE(v_request_owned_dirty_context->>'correction_operation_id','')=''
          OR correction_operation.id::text
               =v_request_owned_dirty_context->>'correction_operation_id'
        )
      ORDER BY correction_operation.created_at_utc DESC
      LIMIT 1;
    END IF;
  ELSE
    -- Compatibility fallback while the new setting is disabled.  This is the
    -- prior retrospective proof and is deliberately retained for rollback.
    IF LOWER(BTRIM(COALESCE(v_payload->>'trigger_table','')))
          ='pay_payment_correction_requests'
       AND LOWER(BTRIM(COALESCE(v_payload->>'policy_x_dirtying_only','false')))
             IN ('true','t','1','yes','y','on')
       AND LOWER(BTRIM(COALESCE(v_payload->>'economic_truth_mutation_allowed','false')))
             NOT IN ('true','t','1','yes','y','on')
       AND (
         (
           jsonb_typeof(v_payload->'reasons')='array'
           AND jsonb_array_length(v_payload->'reasons')>0
           AND NOT EXISTS (
             SELECT 1
             FROM jsonb_array_elements_text(v_payload->'reasons') AS dirty_reason(reason_text)
             WHERE UPPER(BTRIM(dirty_reason.reason_text)) NOT IN (
               'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:INSERT',
               'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:UPDATE'
             )
           )
         )
         OR (
           jsonb_typeof(v_payload->'reasons') IS DISTINCT FROM 'array'
           AND UPPER(BTRIM(COALESCE(v_payload->>'reason_latest',v_payload->>'reason',''))) IN (
             'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:INSERT',
             'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:UPDATE'
           )
         )
       ) THEN
      SELECT request_row.id,correction_operation.id,correction_operation.phase
      INTO v_request_owned_dirty_request_id,
           v_request_owned_dirty_operation_id,
           v_request_owned_dirty_operation_phase
      FROM public.banking_pay_operations AS correction_operation
      JOIN public.pay_payment_correction_requests AS request_row
        ON request_row.id=CASE
          WHEN COALESCE(correction_operation.input_json->>'correction_request_id','')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (correction_operation.input_json->>'correction_request_id')::uuid
          ELSE NULL::uuid END
      JOIN public.pay_payment_correction_request_candidates AS request_candidate
        ON request_candidate.correction_request_id=request_row.id
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id=request_candidate.pay_batch_candidate_id
       AND batch_candidate.candidate_id=v_candidate_id
      WHERE correction_operation.operation_type='PAYMENT_CORRECTION'
        AND correction_operation.status IN ('QUEUED','RUNNING')
        AND correction_operation.phase NOT IN ('REFRESH_WORKBENCH','COMPLETE')
        AND correction_operation.input_json->'draft_overlay_fast_start_authorities'
              ->v_candidate_id::text->>'request_owned_dirty_job_id'=p_job_id::text
        AND request_row.status IN (
          'REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING'
        )
        AND request_row.created_at_utc<=GREATEST(
          v_job.created_at_utc,
          COALESCE(v_job.updated_at_utc,v_job.created_at_utc)
        )
      ORDER BY request_row.created_at_utc DESC,correction_operation.created_at_utc DESC
      LIMIT 1;
    END IF;
  END IF;

  IF v_request_owned_dirty_request_id IS NOT NULL THEN
    UPDATE public.banking_pay_workbench_jobs AS delayed_job
    SET status = 'QUEUED',
        attempt_count = GREATEST(COALESCE(delayed_job.attempt_count, 0) - 1, 0),
        run_at_utc = GREATEST(COALESCE(delayed_job.run_at_utc, v_now), v_now + v_request_owned_dirty_delay),
        started_at_utc = NULL,
        updated_at_utc = v_now,
        payload_json = public._pay_workbench_dirty_payload_merge(
          COALESCE(delayed_job.payload_json, '{}'::jsonb),
          jsonb_build_object(
            'request_owned_dirty_classification', 'REQUEST_OWNED_POLICY_X_DIRTY',
            'waiting_for_correction_financial_boundary',
              COALESCE(v_request_owned_dirty_operation_phase,'')<>'REFRESH_WORKBENCH',
            'waiting_for_correction_route_election',
              COALESCE(v_request_owned_dirty_operation_phase,'')='REFRESH_WORKBENCH'
              OR COALESCE(v_request_owned_dirty_context->>'lifecycle_phase','') IN (
                'FINANCIAL_PAGE_APPLIED','FINANCIAL_TERMINAL'
              ),
            'correction_request_id', v_request_owned_dirty_request_id::text,
            'correction_operation_id', v_request_owned_dirty_operation_id::text,
            'correction_operation_phase', v_request_owned_dirty_operation_phase,
            'correction_dirty_context_digest', v_request_owned_dirty_context->>'context_digest',
            'request_owned_scope_change_tx_token', v_payload->>'request_owned_scope_change_tx_token',
            'request_boundary_delayed_at_utc', v_now::text,
            'dirty_apply_row_marking_applied', false,
            'dirty_marking_skipped', true,
            'session_progress_dirtying_skipped', true,
            'classifier_work_skipped_by_request_boundary', true,
            'source_build_enqueue_skipped_by_request_boundary', true,
            'rerun_required', true,
            'has_more', true,
            'policy_x_authority_scope', 'POST_DRAFT_FROZEN_BATCH_EVIDENCE'
          )
        )
    WHERE delayed_job.id = p_job_id;

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', p_job_id::text,
      'candidate_id', v_candidate_id::text,
      'candidate_serial_delayed', true,
      'request_boundary_delayed', true,
      'has_more', true,
      'rerun_required', true,
      'reason', CASE
        WHEN COALESCE(v_request_owned_dirty_operation_phase,'')='REFRESH_WORKBENCH'
          OR COALESCE(v_request_owned_dirty_context->>'lifecycle_phase','') IN (
            'FINANCIAL_PAGE_APPLIED','FINANCIAL_TERMINAL'
          )
          THEN 'WAITING_FOR_CORRECTION_ROUTE_ELECTION'
        ELSE 'REQUEST_OWNED_POLICY_X_DIRTY_WAITING_FOR_FINANCIAL_BOUNDARY'
      END,
      'correction_request_id', v_request_owned_dirty_request_id::text,
      'correction_operation_id', v_request_owned_dirty_operation_id::text,
      'correction_operation_phase', v_request_owned_dirty_operation_phase,
      'correction_dirty_context_digest', v_request_owned_dirty_context->>'context_digest',
      'request_owned_scope_change_tx_token', v_payload->>'request_owned_scope_change_tx_token',
      'dirty_apply_row_marking_applied', false,
      'dirty_marking_skipped', true,
      'session_progress_dirtying_skipped', true,
      'classifier_work_skipped_by_request_boundary', true,
      'source_build_enqueue_skipped_by_request_boundary', true,
      'elapsed_ms', EXTRACT(MILLISECONDS FROM clock_timestamp() - v_started_at)
    );
  END IF;

  IF v_job.private_cursor_kind IS NOT NULL
     AND v_job.private_cursor_kind <> 'DIRTY_SESSION_SCAN_V1' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_SESSION_CURSOR_KIND_INVALID'
      USING ERRCODE='P0001';
  END IF;

  v_private_cursor := COALESCE(v_job.private_cursor_json, '{}'::jsonb);
  BEGIN
    v_cursor_sequence := CASE
      WHEN COALESCE(v_private_cursor->>'scan_source_change_seq','') ~ '^\d+$'
        THEN (v_private_cursor->>'scan_source_change_seq')::bigint
      ELSE NULL::bigint
    END;
    v_session_scan_cutoff_created_at := NULLIF(BTRIM(COALESCE(v_private_cursor->>'upper_created_at_utc','')),'')::timestamptz;
    v_session_scan_cutoff_id := NULLIF(BTRIM(COALESCE(v_private_cursor->>'upper_session_id','')),'')::uuid;
    v_session_scan_last_created_at := NULLIF(BTRIM(COALESCE(v_private_cursor->>'last_created_at_utc','')),'')::timestamptz;
    v_session_scan_last_id := NULLIF(BTRIM(COALESCE(v_private_cursor->>'last_session_id','')),'')::uuid;
    v_session_scan_started_at := COALESCE(
      NULLIF(BTRIM(COALESCE(v_private_cursor->>'scan_started_at_utc','')),'')::timestamptz,
      v_now
    );
    v_session_scan_sessions_examined := COALESCE(
      CASE WHEN COALESCE(v_private_cursor->>'sessions_examined','') ~ '^\d+$'
        THEN (v_private_cursor->>'sessions_examined')::bigint END,
      0
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_SESSION_CURSOR_INVALID' USING ERRCODE='P0001';
  END;

  IF v_job.private_cursor_kind IS NULL
     OR v_job.private_stage_version IS DISTINCT FROM 1
     OR v_cursor_sequence IS DISTINCT FROM v_processed_source_change_seq THEN
    SELECT session_candidate.created_at_utc, session_candidate.id
    INTO v_session_scan_cutoff_created_at, v_session_scan_cutoff_id
    FROM public.banking_pay_workbench_sessions AS session_candidate
    WHERE session_candidate.status='OPEN'
      AND session_candidate.discarded_at_utc IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_sessions AS newer_session
        WHERE newer_session.actor_user_id=session_candidate.actor_user_id
          AND newer_session.status='OPEN' AND newer_session.discarded_at_utc IS NULL
          AND (newer_session.pay_date,newer_session.created_at_utc,newer_session.id)>
              (session_candidate.pay_date,session_candidate.created_at_utc,session_candidate.id)
      )
    ORDER BY session_candidate.created_at_utc DESC,session_candidate.id DESC
    LIMIT 1;

    v_session_scan_last_created_at := NULL::timestamptz;
    v_session_scan_last_id := NULL::uuid;
    v_session_scan_started_at := v_now;
    v_session_scan_sessions_examined := 0;

    UPDATE public.banking_pay_workbench_jobs AS cursor_job
    SET private_cursor_kind='DIRTY_SESSION_SCAN_V1',
        private_stage_version=1,
        private_cursor_json=jsonb_strip_nulls(jsonb_build_object(
          'scan_source_change_seq',v_processed_source_change_seq,
          'upper_created_at_utc',v_session_scan_cutoff_created_at,
          'upper_session_id',v_session_scan_cutoff_id,
          'last_created_at_utc',NULL,
          'last_session_id',NULL,
          'scan_started_at_utc',v_session_scan_started_at,
          'sessions_examined',0
        )),
        updated_at_utc=v_now
    WHERE cursor_job.id=p_job_id;
  END IF;
  v_lifecycle_context := LOWER(BTRIM(COALESCE(v_payload->>'lifecycle_mutation_context', v_payload->>'mutation_context', v_payload->>'lifecycle_context', '')));
  v_is_authorise_delta_targeted := v_refresh_scope_kind = 'TARGETED_TIMESHEETS'
    AND COALESCE(array_length(v_canonical_targeted_timesheet_ids, 1), 0) > 0
    AND COALESCE(array_length(v_finance_case_ids, 1), 0) = 0
    AND lower(BTRIM(COALESCE(v_payload->>'ordinary_timesheet_edit_save_no_dirty', 'false'))) NOT IN ('true','t','1','yes','y','on')
    AND (
      lower(BTRIM(COALESCE(v_payload->>'authorise_boundary_changed', v_payload->>'timesheet_authorise_boundary_changed', 'false'))) IN ('true','t','1','yes','y','on')
      OR lower(BTRIM(COALESCE(v_payload->>'unauthorise_boundary_changed', v_payload->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true','t','1','yes','y','on')
      OR v_lifecycle_context IN ('timesheet_authorise', 'authorise_timesheet', 'timesheet_unauthorise', 'unauthorise_timesheet')
      OR LOWER(COALESCE(v_reason, '')) LIKE '%authorise%'
      OR LOWER(COALESCE(v_reason, '')) LIKE '%unauthorise%'
    );

  -- The trigger invalidates the exact row known at write time.  Dependency and
  -- rotation closure can legitimately discover a wider Timesheet family by
  -- the time this worker runs, and a newer event can also supersede the
  -- original generation.  Prove the *final* bounded scope here, once under the
  -- Candidate serial lock and before scanning any open session.  If the old
  -- proof is incomplete or stale, issue one fresh central invalidation for the
  -- complete effective scope and reuse that one proof for every session.
  v_payload_scope_change_tx_token := CASE
    WHEN COALESCE(v_payload->>'scope_change_tx_token','')
      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN (v_payload->>'scope_change_tx_token')::uuid
    ELSE NULL::uuid
  END;
  v_payload_scope_change_generation := CASE
    WHEN COALESCE(v_payload->>'scope_change_generation','') ~ '^[0-9]{1,18}$'
      THEN (v_payload->>'scope_change_generation')::bigint
    ELSE NULL::bigint
  END;

  SELECT scope_tx.state,scope_tx.allocated_generation
  INTO v_scope_transaction_state,v_scope_transaction_generation
  FROM public.banking_pay_scope_change_transactions AS scope_tx
  WHERE scope_tx.tx_token=v_payload_scope_change_tx_token;

  SELECT registry.dirty_generation,
         change_counter.scope_change_generation
  INTO v_registry_dirty_generation,v_live_scope_change_generation
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry
  LEFT JOIN public.app_change_counters AS change_counter
    ON change_counter.entity_key='pay_candidate:'||v_candidate_id::text
  WHERE registry.candidate_id=v_candidate_id;

  SELECT count(*)::integer
  INTO v_scope_state_generation_match_count
  FROM unnest(v_effective_bounded_timesheet_ids) AS requested(timesheet_id)
  JOIN private.banking_pay_workbench_timesheet_scope_state AS scope_state
    ON scope_state.timesheet_id=requested.timesheet_id
   AND scope_state.candidate_id=v_candidate_id
   AND scope_state.dirty_generation=v_payload_scope_change_generation;

  -- A bounded-union cohort keeps the original per-Timesheet proof below. A
  -- cap/ownership fallback is a stronger Candidate-full authority and is
  -- accepted only when this exact postgres-owned helper stamped the same
  -- Candidate/token and the ordinary finalized generation fences all match.
  v_dirty_cohort_full_authority_reusable :=
    COALESCE(v_payload->>'dirty_apply_cohort_authority_scope', '') =
          'CANDIDATE_FULL_LIVE'
    AND COALESCE(v_payload->>'dirty_apply_cohort_contract_version', '') =
          'DIRTY_APPLY_COHORT_AUTHORITY_V1'
    AND COALESCE(v_payload->>'dirty_apply_cohort_candidate_id', '') =
          v_candidate_id::text
    AND COALESCE(v_payload->>'dirty_apply_cohort_tx_token', '') =
          v_payload_scope_change_tx_token::text;

  v_preceding_scope_authority_reusable :=
    lower(BTRIM(COALESCE(v_payload->>'bounded_scope_state_precedes_job','false')))
      IN ('true','t','1','yes','y','on')
    AND v_payload_scope_change_tx_token IS NOT NULL
    AND COALESCE(v_payload_scope_change_generation,0)>0
    AND v_scope_transaction_state='FINALIZED'
    AND v_scope_transaction_generation=v_payload_scope_change_generation
    AND v_registry_dirty_generation=v_payload_scope_change_generation
    AND v_live_scope_change_generation=v_payload_scope_change_generation
    AND (
      (
        cardinality(v_effective_bounded_timesheet_ids)>0
        AND COALESCE(v_payload->>'dirty_apply_cohort_authority_scope', '') =
              'TARGETED_UNION'
        AND v_scope_state_generation_match_count=
              cardinality(v_effective_bounded_timesheet_ids)
      )
      OR v_dirty_cohort_full_authority_reusable
    );

  -- A member whose own exact proof still matches the finalized cohort can
  -- finish without rescanning every active sibling. If a later event has a
  -- different token/generation, that job fails this fast path and forms the
  -- next cohort with whatever active members remain.
  v_dirty_cohort_fast_path_reusable :=
    v_preceding_scope_authority_reusable
    AND COALESCE(v_payload->>'dirty_apply_cohort_contract_version', '') =
          'DIRTY_APPLY_COHORT_AUTHORITY_V1'
    AND COALESCE(v_payload->>'dirty_apply_cohort_candidate_id', '') =
          v_candidate_id::text
    AND COALESCE(v_payload->>'dirty_apply_cohort_tx_token', '') =
          v_payload_scope_change_tx_token::text
    AND (
      (
        cardinality(v_effective_bounded_timesheet_ids)>0
        AND COALESCE(v_payload->>'dirty_apply_cohort_authority_scope', '') =
              'TARGETED_UNION'
      )
      OR v_dirty_cohort_full_authority_reusable
    );

  IF v_dirty_cohort_fast_path_reusable THEN
    v_dirty_cohort_action := 'FAST_PATH_FINALIZED_COHORT';
    v_dirty_cohort_authority_scope :=
      v_payload->>'dirty_apply_cohort_authority_scope';
    v_effective_scope_change_tx_token := v_payload_scope_change_tx_token;
    v_effective_scope_change_generation :=
      v_payload_scope_change_generation;
  ELSE
    -- The current proof is absent/stale, or this row predates cohort metadata.
    -- The cohort owner either returns one already-current shared authority or
    -- stages every admitted same-Candidate sibling under one pending token.
    v_dirty_cohort_result :=
      private.pay_workbench_candidate_dirty_cohort_stage_v1(
        p_job_id,
        v_candidate_id,
        v_now
      );
    v_dirty_cohort_action := COALESCE(
      v_dirty_cohort_result->>'action',
      ''
    );
    v_dirty_cohort_authority_scope := NULLIF(BTRIM(COALESCE(
      v_dirty_cohort_result->>'authority_scope',
      ''
    )), '');

    IF v_dirty_cohort_action IN (
      'COHORT_REISSUED_PENDING_FINALIZATION',
      'WAITING_FOR_COHORT_FINALIZATION'
    ) THEN
      v_preinvalidated_scope_reissued := true;
      v_effective_scope_change_tx_token := CASE
        WHEN COALESCE(v_dirty_cohort_result->>'scope_change_tx_token', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (v_dirty_cohort_result->>'scope_change_tx_token')::uuid
        ELSE NULL::uuid
      END;

      RETURN jsonb_build_object(
        'ok', true,
        'job_id', p_job_id::text,
        'job_type', 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        'candidate_id', v_candidate_id::text,
        'refresh_scope_kind', v_refresh_scope_kind,
        'targeted_timesheet_count',
          COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
        'family_timesheet_count',
          COALESCE(array_length(v_family_timesheet_ids, 1), 0),
        'preinvalidated_scope_reissued', true,
        'preinvalidated_scope_reissue_pending_finalization', true,
        'effective_scope_change_tx_token',
          v_effective_scope_change_tx_token::text,
        'effective_scope_change_generation', NULL,
        'dirty_apply_cohort_action', v_dirty_cohort_action,
        'dirty_apply_cohort_authority_scope',
          v_dirty_cohort_authority_scope,
        'dirty_apply_cohort_member_count', COALESCE(
          (v_dirty_cohort_result->>'member_count')::integer,
          0
        ),
        'dirty_apply_cohort_excluded_request_owned_count', COALESCE(
          (v_dirty_cohort_result
            ->>'excluded_request_owned_count')::integer,
          0
        ),
        'dirty_apply_row_marking_applied', false,
        'dirty_marking_skipped', true,
        'session_progress_dirtying_skipped', true,
        'more_due', true,
        'has_more', true,
        'rerun_required', true,
        'next_cursor_json',
          COALESCE(v_job.private_cursor_json, '{}'::jsonb),
        'made_progress',
          v_dirty_cohort_action =
            'COHORT_REISSUED_PENDING_FINALIZATION',
        'dirty_apply_complete', false,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (
          clock_timestamp() - v_started_at
        )) * 1000)::numeric, 2)
      );
    ELSIF v_dirty_cohort_action <> 'REUSE_FINALIZED_AUTHORITY' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_COHORT_POSTCONDITION_FAILED'
        USING ERRCODE = '40001', DETAIL = jsonb_build_object(
          'code', 'PAY_WORKBENCH_DIRTY_COHORT_POSTCONDITION_FAILED',
          'job_id', p_job_id,
          'candidate_id', v_candidate_id,
          'cohort_result', v_dirty_cohort_result
        )::text;
    END IF;

    v_effective_scope_change_tx_token := CASE
      WHEN COALESCE(v_dirty_cohort_result->>'scope_change_tx_token', '')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (v_dirty_cohort_result->>'scope_change_tx_token')::uuid
      ELSE NULL::uuid
    END;
    v_effective_scope_change_generation := CASE
      WHEN COALESCE(
             v_dirty_cohort_result->>'scope_change_generation',
             ''
           ) ~ '^[0-9]{1,18}$'
        THEN (v_dirty_cohort_result->>'scope_change_generation')::bigint
      ELSE NULL::bigint
    END;

    IF v_effective_scope_change_tx_token IS DISTINCT FROM
         v_payload_scope_change_tx_token
       OR v_effective_scope_change_generation IS DISTINCT FROM
         v_payload_scope_change_generation THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_COHORT_REUSE_PROOF_MISMATCH'
        USING ERRCODE = '40001', DETAIL = jsonb_build_object(
          'code', 'PAY_WORKBENCH_DIRTY_COHORT_REUSE_PROOF_MISMATCH',
          'job_id', p_job_id,
          'candidate_id', v_candidate_id,
          'cohort_result', v_dirty_cohort_result
        )::text;
    END IF;
  END IF;

  -- ALL dominates a mixed cohort, and any dependency/cap fallback must really
  -- take the established Candidate-full refresh path. The durable per-job
  -- scopes/reasons remain unchanged for audit and replay compatibility.
  IF v_dirty_cohort_authority_scope = 'CANDIDATE_FULL_LIVE' THEN
    v_dependency_closure_requires_full := true;
    v_dependency_closure_reason := COALESCE(
      NULLIF(BTRIM(COALESCE(
        v_dirty_cohort_result->>'full_fallback_reason',
        v_payload->>'dirty_apply_cohort_full_fallback_reason',
        ''
      )), ''),
      'DIRTY_APPLY_COHORT_FULL_AUTHORITY'
    );
    v_dependency_closure_json := jsonb_build_object(
      'ok', true,
      'coverage_complete', false,
      'requires_full_candidate', true,
      'fallback_reason', v_dependency_closure_reason,
      'effective_targeted_timesheet_ids', '[]'::jsonb,
      'effective_linked_timesheet_ids', '[]'::jsonb,
      'effective_finance_case_ids', '[]'::jsonb,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'economic_calculation_performed', false
    );
    v_targeted_timesheet_ids := ARRAY[]::uuid[];
    v_linked_timesheet_ids := ARRAY[]::uuid[];
    v_finance_case_ids := ARRAY[]::uuid[];
    v_family_timesheet_ids := ARRAY[]::uuid[];
    v_canonical_targeted_timesheet_ids := ARRAY[]::uuid[];
    v_canonical_linked_timesheet_ids := ARRAY[]::uuid[];
    v_all_timesheet_ids := ARRAY[]::uuid[];
    v_effective_bounded_timesheet_ids := ARRAY[]::uuid[];
    v_family_scope_json := '{}'::jsonb;
    v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
    v_is_authorise_delta_targeted := false;
    -- The downstream scope merge unions array keys from its existing payload.
    -- Strip only the local working copy so a previously targeted durable job
    -- cannot leak stale IDs into this stronger Candidate-full refresh request.
    v_payload := v_payload
      - 'targeted_timesheet_ids'
      - 'linked_timesheet_ids'
      - 'finance_case_ids';
  END IF;

  -- Candidate-full execution deliberately clears the local arrays so no later
  -- step can accidentally fall back to the targeted path.  Preserve the
  -- already certified cohort's bounded Timesheet count in the response,
  -- however: family_timesheet_count is an established diagnostic/result field
  -- and clearing the working arrays must not rewrite its meaning to zero.
  v_reported_family_timesheet_count := COALESCE(
    array_length(v_family_timesheet_ids, 1),
    0
  );
  IF v_dirty_cohort_authority_scope = 'CANDIDATE_FULL_LIVE' THEN
    IF COALESCE(
         v_payload->>'dirty_apply_cohort_effective_timesheet_count',
         ''
       ) ~ '^[0-9]{1,9}$' THEN
      v_reported_family_timesheet_count :=
        (v_payload->>'dirty_apply_cohort_effective_timesheet_count')::integer;
    ELSIF COALESCE(
            v_dirty_cohort_result->>'effective_timesheet_count',
            ''
          ) ~ '^[0-9]{1,9}$' THEN
      v_reported_family_timesheet_count :=
        (v_dirty_cohort_result->>'effective_timesheet_count')::integer;
    END IF;
  END IF;

  PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', p_job_id::text, jsonb_build_object('function_name', 'pay_workbench_candidate_dirty_apply_job_process', 'stage', 'dirty_worker_apply_start', 'job_id', p_job_id::text, 'candidate_id', v_candidate_id::text, 'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0), 'family_timesheet_count', v_reported_family_timesheet_count, 'latest_source_change_seq', v_payload_seq, 'processed_source_change_seq', v_processed_source_change_seq));

  SELECT COALESCE(array_agg(page_row.id ORDER BY page_row.created_at_utc,page_row.id),ARRAY[]::uuid[])
  INTO v_session_page_ids
  FROM (
    SELECT session_candidate.id,session_candidate.created_at_utc
    FROM public.banking_pay_workbench_sessions AS session_candidate
    WHERE session_candidate.status='OPEN'
      AND session_candidate.discarded_at_utc IS NULL
      AND v_session_scan_cutoff_created_at IS NOT NULL
      AND (session_candidate.created_at_utc,session_candidate.id)<=
          (v_session_scan_cutoff_created_at,v_session_scan_cutoff_id)
      AND (
        v_session_scan_last_created_at IS NULL
        OR (session_candidate.created_at_utc,session_candidate.id)>
           (v_session_scan_last_created_at,v_session_scan_last_id)
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_sessions AS newer_session
        WHERE newer_session.actor_user_id=session_candidate.actor_user_id
          AND newer_session.status='OPEN' AND newer_session.discarded_at_utc IS NULL
          AND (newer_session.pay_date,newer_session.created_at_utc,newer_session.id)>
              (session_candidate.pay_date,session_candidate.created_at_utc,session_candidate.id)
      )
    ORDER BY session_candidate.created_at_utc,session_candidate.id
    LIMIT GREATEST(1, COALESCE(p_limit, 100))
  ) AS page_row;

  PERFORM session_lock.id
  FROM public.banking_pay_workbench_sessions AS session_lock
  WHERE session_lock.id=ANY(v_session_page_ids)
  ORDER BY session_lock.id
  FOR UPDATE;

  FOR v_session_row IN
    SELECT session_candidate.*
    FROM public.banking_pay_workbench_sessions AS session_candidate
    WHERE session_candidate.id=ANY(v_session_page_ids)
    ORDER BY session_candidate.created_at_utc,session_candidate.id
  LOOP
    v_session_scan_last_created_at:=v_session_row.created_at_utc;
    v_session_scan_last_id:=v_session_row.id;
    v_session_scan_sessions_examined:=v_session_scan_sessions_examined+1;
    IF NOT EXISTS (
      SELECT 1 FROM public.banking_pay_workbench_session_scope AS existing_scope
      WHERE existing_scope.session_id=v_session_row.id
        AND existing_scope.candidate_id=v_candidate_id
    ) THEN
      v_scope_ensure_result:=private.pay_workbench_session_candidate_scope_ensure_v1(
        v_session_row.id,v_candidate_id,p_job_id,v_processed_source_change_seq,v_reason
      );
      IF COALESCE((v_scope_ensure_result->>'eligible')::boolean,false) IS NOT TRUE THEN
        CONTINUE;
      END IF;
      v_new_scope_baseline_required:=COALESCE((v_scope_ensure_result->>'inserted')::boolean,false);
    ELSE
      v_new_scope_baseline_required:=false;
    END IF;
    IF v_new_scope_baseline_required IS TRUE THEN
      v_reuse_selection := private.pay_workbench_candidate_reuse_source_select_v1(
        v_session_row.id,
        v_candidate_id,
        v_processed_source_change_seq,
        jsonb_build_object(
          'source_job_id',p_job_id::text,
          'direct_candidate_id',v_candidate_id::text,
          'target_session_id',v_session_row.id::text
        )
      );

      IF coalesce((v_reuse_selection->>'reuse_available')::boolean,false) IS TRUE
         AND coalesce(v_reuse_selection->>'selected_source_session_id','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_reuse_source_session_id := (v_reuse_selection->>'selected_source_session_id')::uuid;
        v_reuse_dedupe_key := 'workbench:certified-reuse-v2:'
          ||v_session_row.id::text||':'||v_candidate_id::text||':'||v_processed_source_change_seq::text;

        INSERT INTO public.banking_pay_workbench_jobs AS reuse_job(
          id,job_type,status,priority,run_at_utc,attempt_count,max_attempts,
          dedupe_key,snapshot_run_id,session_id,candidate_id,payload_json,
          created_at_utc,updated_at_utc,started_at_utc,completed_at_utc,
          failed_at_utc,last_error_json
        ) VALUES (
          gen_random_uuid(),'WORKBENCH_SESSION_CLONE_REBASE','QUEUED',42,v_now,0,8,
          v_reuse_dedupe_key,v_session_row.source_snapshot_run_id,v_session_row.id,v_candidate_id,
          jsonb_strip_nulls(jsonb_build_object(
            'job_type','WORKBENCH_SESSION_CLONE_REBASE',
            'source_session_id',v_reuse_source_session_id::text,
            'target_session_id',v_session_row.id::text,
            'direct_candidate_id',v_candidate_id::text,
            'source_change_seq',v_processed_source_change_seq,
            'source_job_id',p_job_id::text,
            'source_selection_authorised',true,
            'allow_session_rebase',true,
            'rebase_simple_rows_only',true,
            'clone_mode','CERTIFIED_ONLY',
            'cursor_json','{}'::jsonb,
            'limit',1,
            'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
          )),
          v_now,v_now,NULL,NULL,NULL,NULL
        )
        ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED','RUNNING')
        DO UPDATE SET
          run_at_utc=LEAST(reuse_job.run_at_utc,EXCLUDED.run_at_utc),
          payload_json=coalesce(reuse_job.payload_json,'{}'::jsonb)||EXCLUDED.payload_json,
          updated_at_utc=v_now
        RETURNING reuse_job.id INTO v_reuse_job_id;

        UPDATE public.banking_pay_workbench_session_scope AS reuse_scope
        SET status='PENDING',dirty=true,pending_job_id=v_reuse_job_id,
            error_json=NULL::jsonb,
            certified_preview_publication_required=true,
            certified_preview_publication_parity_ok=false,
            certified_preview_publication_session_version=NULL,
            certified_preview_publication_source_change_seq=NULL,
            certified_preview_publication_source_build_run_id=NULL,
            certified_preview_publication_source_publication_id=NULL,
            certified_preview_publication_attestation_json='{}'::jsonb,
            certified_preview_publication_attested_at_utc=NULL,
            updated_at_utc=v_now
        WHERE reuse_scope.session_id=v_session_row.id
          AND reuse_scope.candidate_id=v_candidate_id;

        v_jobs_queued:=v_jobs_queued+1;
        v_session_count:=v_session_count+1;
        v_refresh_result:=jsonb_build_object(
          'ok',true,
          'job_id',v_reuse_job_id::text,
          'job_type','WORKBENCH_SESSION_CLONE_REBASE',
          'scope_status','PENDING',
          'source_build_required',false,
          'certified_reuse_pending',true
        );
        CONTINUE;
      END IF;
    END IF;


    IF v_is_authorise_delta_targeted AND NOT v_new_scope_baseline_required THEN
      SELECT public.pay_workbench_authorise_delta_hotkey_preflight(
        p_session_id => v_session_row.id,
        p_candidate_id => v_candidate_id,
        p_targeted_timesheet_ids => v_canonical_targeted_timesheet_ids,
        p_linked_timesheet_ids => v_canonical_linked_timesheet_ids,
        p_payload_json => public._pay_workbench_merge_targeted_scope_payload(
          v_payload,
          jsonb_build_object(
            'session_id', v_session_row.id::text,
            'source_session_id', v_session_row.id::text,
            'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
            'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
            'session_version', COALESCE(v_session_row.version, 0),
            'session_signature', v_session_row.session_signature,
            'refresh_scope_kind', 'TARGETED_TIMESHEETS',
            'projection_mode', 'DELTA',
            'projection_class', 'TIMESHEET_LIFECYCLE',
            'targeted_timesheet_ids', COALESCE(v_family_scope_json->'targeted_timesheet_ids', to_jsonb(v_canonical_targeted_timesheet_ids)),
            'linked_timesheet_ids', COALESCE(v_family_scope_json->'linked_timesheet_ids', to_jsonb(v_canonical_linked_timesheet_ids)),
            'queue_identity_targeted_timesheet_ids', COALESCE(v_family_scope_json->'queue_identity_targeted_timesheet_ids', v_family_scope_json->'family_timesheet_ids', to_jsonb(v_canonical_targeted_timesheet_ids)),
            'queue_identity_linked_timesheet_ids', COALESCE(v_family_scope_json->'queue_identity_linked_timesheet_ids', '[]'::jsonb),
            'requested_timesheet_ids', COALESCE(v_family_scope_json->'requested_timesheet_ids', to_jsonb(v_targeted_timesheet_ids)),
            'targeted_timesheet_ids_requested', COALESCE(v_family_scope_json->'requested_targeted_timesheet_ids', to_jsonb(v_targeted_timesheet_ids)),
            'linked_timesheet_ids_requested', COALESCE(v_family_scope_json->'requested_linked_timesheet_ids', to_jsonb(v_linked_timesheet_ids)),
            'source_change_seq', v_processed_source_change_seq,
            'latest_source_change_seq', v_processed_source_change_seq,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          )
        ),
        p_reason => v_reason,
        p_actor_user_id => v_session_row.actor_user_id,
        p_source_change_seq => v_processed_source_change_seq
      ) INTO v_preflight_result;

      v_preflight_action := COALESCE(v_preflight_result->>'action', 'PROCEED');

      IF v_preflight_action IN ('REUSED_QUEUED_SAME_FAMILY_JOB', 'UPDATED_WAITING_AFTER_RUNNING_JOB') THEN
        v_preflight_match_count := v_preflight_match_count + 1;
        v_dirty_marking_skipped := true;
        v_jobs_queued := v_jobs_queued + CASE WHEN NULLIF(BTRIM(COALESCE(v_preflight_result->>'job_id', '')), '') IS NOT NULL THEN 1 ELSE 0 END;
        v_session_count := v_session_count + 1;

        UPDATE public.banking_pay_workbench_jobs AS job_update
        SET payload_json = public._pay_workbench_dirty_payload_merge(
              COALESCE(job_update.payload_json, '{}'::jsonb),
              jsonb_build_object(
                'processed_source_change_seq', v_processed_source_change_seq,
                'processed_at_utc', v_now::text,
                'processed_candidate_id', v_candidate_id::text,
                'source_change_seq', v_processed_source_change_seq,
                'source_change_sequence', v_processed_source_change_seq,
                'latest_source_change_seq', v_processed_source_change_seq,
                'rerun_required', false,
                'has_more', false,
                'cursor_json', '{}'::jsonb,
                'next_cursor_json', '{}'::jsonb,
                'dirty_apply_row_marking_applied', false,
                'dirty_marking_skipped', true,
                'session_progress_dirtying_skipped', true,
                'classifier_work_skipped', true,
                'source_rows_marking_skipped', true,
                'line_work_marking_skipped', true,
                'preview_marking_skipped', true,
                'early_preflight_action', v_preflight_action,
                'early_preflight_result', COALESCE(v_preflight_result, '{}'::jsonb),
                'actual_refresh_job_id', NULLIF(BTRIM(COALESCE(v_preflight_result->>'job_id', '')), ''),
                'actual_refresh_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
                'actual_refresh_scope_status', 'DELTA_REFRESH_PENDING',
                'source_build_required', false,
                'delta_refresh_required', true,
                'line_work_action', 'EARLY_PREFLIGHT_SKIPPED_DIRTY_MARKING',
                'early_preflight_completed_cleanly', true,
                'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
              )
            ),
            updated_at_utc = v_now
        WHERE job_update.id = p_job_id;

        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', p_job_id::text, jsonb_build_object('function_name', 'pay_workbench_candidate_dirty_apply_job_process', 'stage', 'early_preflight_return_before_dirty_marking', 'job_id', p_job_id::text, 'candidate_id', v_candidate_id::text, 'session_id', v_session_row.id::text, 'action', v_preflight_action, 'normalised_delta_family_key', v_preflight_result->>'normalised_delta_family_key', 'dirty_marking_skipped', true));

        CONTINUE;
      END IF;
    END IF;

    -- Resolve the current economic owner before making public source/preview
    -- rows dirty.  This allows delayed finance/batch/candidate dirty events to
    -- be absorbed by an already-active or already-published full authority.
    v_refresh_payload_json := public._pay_workbench_merge_targeted_scope_payload(
      v_payload,
      jsonb_build_object(
        'session_id', v_session_row.id::text,
        'source_session_id', v_session_row.id::text,
        'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
        'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'session_signature', v_session_row.session_signature,
        'pay_channel_scope', COALESCE(NULLIF(UPPER(BTRIM(COALESCE(v_session_row.filters_json->>'pay_channel_scope', v_session_row.filters_json#>>'{filters,pay_channel_scope}', ''))), ''), 'ALL'),
        'refresh_scope_kind', v_refresh_scope_kind,
        'targeted_timesheet_ids', COALESCE(to_jsonb(v_canonical_targeted_timesheet_ids), '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(to_jsonb(v_canonical_linked_timesheet_ids), '[]'::jsonb),
        'finance_case_ids', COALESCE(to_jsonb(v_finance_case_ids), '[]'::jsonb),
        'dependency_closure', COALESCE(v_dependency_closure_json, '{}'::jsonb),
        'dependency_closure_fallback_reason', v_dependency_closure_reason,
        'requested_timesheet_ids', COALESCE(v_family_scope_json->'requested_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb)),
        'targeted_timesheet_ids_requested', COALESCE(v_family_scope_json->'requested_targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb)),
        'linked_timesheet_ids_requested', COALESCE(v_family_scope_json->'requested_linked_timesheet_ids', COALESCE(to_jsonb(v_linked_timesheet_ids), '[]'::jsonb)),
        'family_timesheet_ids', COALESCE(v_family_scope_json->'family_timesheet_ids', COALESCE(to_jsonb(v_family_timesheet_ids), '[]'::jsonb)),
        'source_rows_marked_dirty_count', 0,
        'line_work_marked_pending_count', 0,
        'preview_rows_marked_dirty_count', 0,
        'source_change_seq', v_processed_source_change_seq,
        'latest_source_change_seq', v_processed_source_change_seq,
        'force_legacy', false,
        'force_broad_legacy', false,
        'new_scope_baseline_required',v_new_scope_baseline_required,
        'source_dirty_job_id', p_job_id::text,
        'enqueue_origin', 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      )
    );

    SELECT public.pay_workbench_enqueue_candidate_refresh(
      p_snapshot_run_id => v_session_row.source_snapshot_run_id,
      p_candidate_id => v_candidate_id,
      p_reason => v_reason,
      p_actor_user_id => v_session_row.actor_user_id,
      p_payload_json => v_refresh_payload_json
    )
    INTO v_refresh_result;

    IF lower(BTRIM(COALESCE(v_refresh_result->>'coalesced', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_dirty_marking_skipped := true;
      v_session_count := v_session_count + 1;
      IF UPPER(BTRIM(COALESCE(v_refresh_result->>'owner_resolution', ''))) = 'COMPLETE_CURRENT_AUTHORITY' THEN
        v_jobs_coalesced_complete := v_jobs_coalesced_complete + 1;
      ELSE
        v_jobs_coalesced_active := v_jobs_coalesced_active + 1;
      END IF;

      UPDATE public.banking_pay_workbench_jobs AS coalesced_dirty_job
      SET payload_json = public._pay_workbench_dirty_payload_merge(
            COALESCE(coalesced_dirty_job.payload_json, '{}'::jsonb),
            jsonb_build_object(
              'processed_source_change_seq', v_processed_source_change_seq,
              'processed_at_utc', v_now::text,
              'processed_candidate_id', v_candidate_id::text,
              'dirty_apply_row_marking_applied', false,
              'dirty_marking_skipped', true,
              'coalesced_to_current_refresh_authority', true,
              'coalesced_owner_resolution', v_refresh_result->>'owner_resolution',
              'coalesced_owner_build_id', v_refresh_result->>'owner_build_id',
              'coalesced_owner_root_job_id', v_refresh_result->>'owner_root_job_id',
              'refresh_enqueue_result', v_refresh_result,
              'rerun_required', false,
              'has_more', false,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          ),
          updated_at_utc = v_now
      WHERE coalesced_dirty_job.id = p_job_id;

      CONTINUE;
    END IF;

    UPDATE public.banking_pay_workbench_session_scope AS scope_row
    SET status = COALESCE(NULLIF(BTRIM(v_refresh_result->>'scope_status'), ''), 'SOURCE_BUILD_PENDING'),
        dirty = true,
        error_json = NULL::jsonb,
        certified_preview_publication_required = true,
        certified_preview_publication_parity_ok = false,
        certified_preview_publication_session_version = NULL,
        certified_preview_publication_source_change_seq = NULL,
        certified_preview_publication_source_build_run_id = NULL,
        certified_preview_publication_source_publication_id = NULL,
        certified_preview_publication_attestation_json = '{}'::jsonb,
        certified_preview_publication_attested_at_utc = NULL,
        updated_at_utc = v_now
    WHERE scope_row.session_id = v_session_row.id
      AND scope_row.candidate_id = v_candidate_id;
    GET DIAGNOSTICS v_scope_updated = ROW_COUNT;
    v_scope_count := v_scope_count + COALESCE(v_scope_updated, 0);

    UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line
    SET status = 'DIRTY',
        source_row_json = jsonb_strip_nulls(
          COALESCE(source_line.source_row_json, '{}'::jsonb)
          || jsonb_build_object(
            'dirty_reason', v_reason,
            'source_change_seq', v_processed_source_change_seq,
            'dirty_trigger_table', COALESCE(v_payload->>'trigger_table', 'dirty_apply_worker'),
            'dirty_trigger_operation', COALESCE(v_payload->>'trigger_op', 'APPLY'),
            'dirty_at_utc', v_now::text,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          )
        ),
        updated_at_utc = v_now
    WHERE source_line.session_id = v_session_row.id
      AND source_line.candidate_id = v_candidate_id
      AND source_line.status = 'CURRENT'
      AND (
        v_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
        OR source_line.timesheet_id = ANY(v_all_timesheet_ids)
        OR (
          NULLIF(BTRIM(COALESCE(source_line.source_row_json->>'finance_case_id', '')), '')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND (source_line.source_row_json->>'finance_case_id')::uuid
                = ANY(COALESCE(v_finance_case_ids, ARRAY[]::uuid[]))
        )
      );
    GET DIAGNOSTICS v_source_dirty_count = ROW_COUNT;
    v_source_dirty_total := v_source_dirty_total + COALESCE(v_source_dirty_count, 0);

    UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
    SET status = 'PENDING',
        result_row_json = NULL::jsonb,
        error_json = NULL::jsonb,
        work_payload_json = jsonb_strip_nulls(
          COALESCE(line_work.work_payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'dirty_reason', v_reason,
            'source_change_seq', v_processed_source_change_seq,
            'dirty_at_utc', v_now::text,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          )
        ),
        updated_at_utc = v_now
    WHERE line_work.session_id = v_session_row.id
      AND line_work.candidate_id = v_candidate_id
      AND (
        v_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
        OR line_work.timesheet_id = ANY(v_all_timesheet_ids)
        OR (
          NULLIF(BTRIM(COALESCE(line_work.result_row_json->>'finance_case_id', '')), '')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND (line_work.result_row_json->>'finance_case_id')::uuid
                = ANY(COALESCE(v_finance_case_ids, ARRAY[]::uuid[]))
        )
      );
    GET DIAGNOSTICS v_line_work_count = ROW_COUNT;
    v_line_work_total := v_line_work_total + COALESCE(v_line_work_count, 0);

    UPDATE public.banking_pay_workbench_preview_rows AS preview_row
    SET status = 'DIRTY',
        selected = false,
        selection_state = 'DIRTY',
        row_json = jsonb_strip_nulls(
          COALESCE(preview_row.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'dirty_reason', v_reason,
            'source_change_seq', v_processed_source_change_seq,
            'dirty_at_utc', v_now::text,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          )
        ),
        updated_at_utc = v_now
    WHERE preview_row.session_id = v_session_row.id
      AND preview_row.candidate_id = v_candidate_id
      AND (
        v_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
        OR preview_row.timesheet_id = ANY(v_all_timesheet_ids)
        OR (
          NULLIF(BTRIM(COALESCE(preview_row.row_json->>'finance_case_id', '')), '')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND (preview_row.row_json->>'finance_case_id')::uuid
                = ANY(COALESCE(v_finance_case_ids, ARRAY[]::uuid[]))
        )
      );
    GET DIAGNOSTICS v_preview_count = ROW_COUNT;
    v_preview_total := v_preview_total + COALESCE(v_preview_count, 0);

    UPDATE public.banking_pay_workbench_sessions AS session_update
    SET progress_state = 'DIRTY',
        scope_pending_count = GREATEST(COALESCE(session_update.scope_pending_count, 0), 1),
        selected_row_count = GREATEST(COALESCE(session_update.selected_row_count, 0) - COALESCE(v_preview_count, 0), 0),
        candidate_sample_rows_json = jsonb_build_array(jsonb_build_object('candidate_id', v_candidate_id::text, 'status', 'SOURCE_BUILD_PENDING', 'reason', v_reason)),
        progress_json = jsonb_strip_nulls(
          COALESCE(session_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'last_dirty_candidate_id', v_candidate_id::text,
            'last_dirty_reason', v_reason,
            'last_dirty_at_utc', v_now::text,
            'last_dirty_job_id', p_job_id::text,
            'last_dirty_source_change_seq', v_processed_source_change_seq,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          )
        ),
        progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    WHERE session_update.id = v_session_row.id;
    v_session_count := v_session_count + 1;

    UPDATE public.banking_pay_workbench_jobs AS refresh_job
    SET payload_json = jsonb_strip_nulls(
          COALESCE(refresh_job.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'source_rows_marked_dirty_count', COALESCE(v_source_dirty_count, 0),
            'line_work_marked_pending_count', COALESCE(v_line_work_count, 0),
            'preview_rows_marked_dirty_count', COALESCE(v_preview_count, 0),
            'dirty_apply_marking_completed_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    WHERE COALESCE(v_refresh_result->>'job_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND refresh_job.id = (v_refresh_result->>'job_id')::uuid;

    v_jobs_queued := v_jobs_queued
      + CASE
          WHEN lower(BTRIM(COALESCE(v_refresh_result->>'new_owner_created', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 1
          WHEN NULLIF(BTRIM(COALESCE(v_refresh_result->>'job_id', '')), '') IS NOT NULL
               AND lower(BTRIM(COALESCE(v_refresh_result->>'reused', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN 1
          WHEN COALESCE(v_refresh_result->>'jobs_queued', '') ~ '^-?[0-9]+$' THEN (v_refresh_result->>'jobs_queued')::integer
          ELSE 0
        END;
  END LOOP;

  SELECT EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_sessions AS remaining_session
    WHERE remaining_session.status='OPEN' AND remaining_session.discarded_at_utc IS NULL
      AND v_session_scan_cutoff_created_at IS NOT NULL
      AND (remaining_session.created_at_utc,remaining_session.id)<=
          (v_session_scan_cutoff_created_at,v_session_scan_cutoff_id)
      AND (v_session_scan_last_created_at IS NULL OR
        (remaining_session.created_at_utc,remaining_session.id)>
          (v_session_scan_last_created_at,v_session_scan_last_id))
      AND NOT EXISTS (
        SELECT 1 FROM public.banking_pay_workbench_sessions AS newer_session
        WHERE newer_session.actor_user_id=remaining_session.actor_user_id
          AND newer_session.status='OPEN' AND newer_session.discarded_at_utc IS NULL
          AND (newer_session.pay_date,newer_session.created_at_utc,newer_session.id)>
              (remaining_session.pay_date,remaining_session.created_at_utc,remaining_session.id)
      )
  ) INTO v_session_scan_has_more;

  UPDATE public.banking_pay_workbench_jobs AS job_update
  SET payload_json = public._pay_workbench_dirty_payload_merge(
        COALESCE(job_update.payload_json, '{}'::jsonb),
        jsonb_build_object(
          'processed_source_change_seq', v_processed_source_change_seq,
          'processed_at_utc', v_now::text,
          'processed_candidate_id', v_candidate_id::text,
          'dirty_scope_count', v_scope_count,
          'dirty_line_count', v_line_work_total,
          'dirty_preview_count', v_preview_total,
          'dirty_apply_row_marking_applied', (v_scope_count + v_source_dirty_total + v_line_work_total + v_preview_total) > 0,
          'dirty_marking_skipped', v_dirty_marking_skipped,
          'jobs_coalesced_active', v_jobs_coalesced_active,
          'jobs_coalesced_complete', v_jobs_coalesced_complete,
          'jobs_requeued_for_conflict', v_jobs_requeued_for_conflict,
          'early_preflight_checked', v_is_authorise_delta_targeted,
          'early_preflight_action', COALESCE(v_preflight_action, 'PROCEED'),
          'actual_refresh_job_id', NULLIF(BTRIM(COALESCE(v_refresh_result->>'job_id', '')), ''),
          'actual_refresh_job_type', NULLIF(BTRIM(COALESCE(v_refresh_result->>'job_type', v_refresh_result->>'canonical_job_type', '')), ''),
          'actual_refresh_scope_status', NULLIF(BTRIM(COALESCE(v_refresh_result->>'scope_status', '')), ''),
          'source_build_required', lower(BTRIM(COALESCE(v_refresh_result->>'source_build_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
          'delta_refresh_required', lower(BTRIM(COALESCE(v_refresh_result->>'delta_refresh_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
          'line_work_action', CASE
            WHEN lower(BTRIM(COALESCE(v_refresh_result->>'delta_refresh_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              THEN 'DIRTY_ROW_MARKING_ONLY_DELTA_REFRESH'
            ELSE 'SOURCE_BUILD_OR_LEGACY_REFRESH'
          END,
          'refresh_enqueue_result', COALESCE(v_refresh_result, '{}'::jsonb)
          ,'preinvalidated_scope_reissued',v_preinvalidated_scope_reissued
          ,'effective_scope_change_tx_token',v_effective_scope_change_tx_token::text
          ,'effective_scope_change_generation',v_effective_scope_change_generation
          ,'session_scan_cutoff_created_at_utc',v_session_scan_cutoff_created_at::text
          ,'session_scan_cutoff_id',v_session_scan_cutoff_id::text
          ,'session_scan_last_created_at_utc',CASE WHEN v_session_scan_has_more THEN v_session_scan_last_created_at::text ELSE NULL END
          ,'session_scan_last_id',CASE WHEN v_session_scan_has_more THEN v_session_scan_last_id::text ELSE NULL END
          ,'rerun_required',v_session_scan_has_more
          ,'has_more',v_session_scan_has_more
        )
      ),
      private_cursor_kind=CASE WHEN v_session_scan_has_more THEN 'DIRTY_SESSION_SCAN_V1' ELSE NULL::text END,
      private_stage_version=CASE WHEN v_session_scan_has_more THEN 1 ELSE NULL::integer END,
      private_cursor_json=CASE
        WHEN v_session_scan_has_more THEN jsonb_strip_nulls(jsonb_build_object(
          'scan_source_change_seq',v_processed_source_change_seq,
          'upper_created_at_utc',v_session_scan_cutoff_created_at,
          'upper_session_id',v_session_scan_cutoff_id,
          'last_created_at_utc',v_session_scan_last_created_at,
          'last_session_id',v_session_scan_last_id,
          'scan_started_at_utc',v_session_scan_started_at,
          'sessions_examined',v_session_scan_sessions_examined
        ))
        ELSE '{}'::jsonb
      END,
      updated_at_utc = v_now
  WHERE job_update.id = p_job_id;

  PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', p_job_id::text, jsonb_build_object('function_name', 'pay_workbench_candidate_dirty_apply_job_process', 'stage', 'dirty_worker_apply_done', 'job_id', p_job_id::text, 'candidate_id', v_candidate_id::text, 'dirty_scope_count', v_scope_count, 'dirty_source_line_count', v_source_dirty_total, 'dirty_line_count', v_line_work_total, 'dirty_preview_count', v_preview_total, 'jobs_queued', v_jobs_queued, 'processed_source_change_seq', v_processed_source_change_seq, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', p_job_id::text,
    'job_type', 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    'candidate_id', v_candidate_id::text,
    'refresh_scope_kind', v_refresh_scope_kind,
    'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
    'family_timesheet_count', v_reported_family_timesheet_count,
    'finance_case_count', COALESCE(array_length(v_finance_case_ids, 1), 0),
    'dependency_closure', COALESCE(v_dependency_closure_json, '{}'::jsonb),
    'dirty_scope_count', v_scope_count,
    'dirty_source_line_count', v_source_dirty_total,
    'dirty_line_count', v_line_work_total,
    'dirty_preview_count', v_preview_total,
    'sessions_touched', v_session_count,
    'jobs_queued', v_jobs_queued,
    'jobs_coalesced_active', v_jobs_coalesced_active,
    'jobs_coalesced_complete', v_jobs_coalesced_complete,
    'jobs_requeued_for_conflict', v_jobs_requeued_for_conflict,
    'processed_source_change_seq', v_processed_source_change_seq,
    'dirty_apply_row_marking_applied', (v_scope_count + v_source_dirty_total + v_line_work_total + v_preview_total) > 0,
    'dirty_marking_skipped', v_dirty_marking_skipped,
    'early_preflight_checked', v_is_authorise_delta_targeted,
    'early_preflight_action', COALESCE(v_preflight_action, 'PROCEED'),
    'actual_refresh_job_id', NULLIF(BTRIM(COALESCE(v_refresh_result->>'job_id', '')), ''),
    'actual_refresh_job_type', NULLIF(BTRIM(COALESCE(v_refresh_result->>'job_type', v_refresh_result->>'canonical_job_type', '')), ''),
    'actual_refresh_scope_status', NULLIF(BTRIM(COALESCE(v_refresh_result->>'scope_status', '')), ''),
    'source_build_required', lower(BTRIM(COALESCE(v_refresh_result->>'source_build_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'delta_refresh_required', lower(BTRIM(COALESCE(v_refresh_result->>'delta_refresh_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'line_work_action', CASE
      WHEN lower(BTRIM(COALESCE(v_refresh_result->>'delta_refresh_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        THEN 'DIRTY_ROW_MARKING_ONLY_DELTA_REFRESH'
      ELSE 'SOURCE_BUILD_OR_LEGACY_REFRESH'
    END,
    'refresh_enqueue_result', COALESCE(v_refresh_result, '{}'::jsonb),
    'preinvalidated_scope_reissued', v_preinvalidated_scope_reissued,
    'effective_scope_change_tx_token', v_effective_scope_change_tx_token::text,
    'effective_scope_change_generation', v_effective_scope_change_generation,
    'more_due', v_session_scan_has_more,
    'has_more', v_session_scan_has_more,
    'made_progress', true,
    'dirty_apply_complete', NOT v_session_scan_has_more,
    'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
  );
END;
$function$;

-- public.pay_workbench_patch_preview_after_batch_mutation_cancel_safe_v1 from supabase/repeatable/08092026_1200_banking_pay_cancel_return_selection_intent_v1.sql; definition SHA-256 e38a4ac4e04334f1a552babe6b7af52f8e8c888306d9d80036156b1c990aaa18.
CREATE OR REPLACE FUNCTION public.pay_workbench_patch_preview_after_batch_mutation_cancel_safe_v1(
  p_session_id uuid,
  p_pay_batch_id uuid,
  p_operation_type text,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_options_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_result jsonb := '{}'::jsonb;
  v_operation_type text := UPPER(BTRIM(COALESCE(p_operation_type, '')));
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_candidate_id uuid;
  v_changed_finance_case_ids uuid[] := ARRAY[]::uuid[];
  v_enqueue_result jsonb := '{}'::jsonb;
  v_job_id uuid;
  v_full_refresh_count integer := 0;
  v_candidate_full_refresh_count integer := 0;
  v_superseded_targeted_job_count integer := 0;
  v_superseded_targeted_job_chunk_count integer := 0;
  v_superseded_finance_dirty_job_count integer := 0;
  v_full_refresh_job_ids jsonb := '[]'::jsonb;
  v_preserved_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_preserved_selected_row_count integer := 0;
  v_cancelled_row_unselected_count integer := 0;
  v_cancelled_selection_expected_count integer := 0;
  v_cancelled_selection_intent_count integer := 0;
  v_cancelled_selection_duplicate_count integer := 0;
  v_cancelled_selection_registered_count integer := 0;
  v_cancelled_selection_reused_count integer := 0;
  v_cancelled_selection_superseded_count integer := 0;
  v_cancelled_selection_pending_count integer := 0;
  v_cancelled_selection_applied_count integer := 0;
  v_targeted_timesheet_ids jsonb := '[]'::jsonb;
  v_requested_refresh_scope text := 'CANDIDATE_FULL_LIVE';
  v_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_attestation jsonb := '{}'::jsonb;
  v_republication_result jsonb := '{}'::jsonb;
  v_candidate_state_result jsonb := '{}'::jsonb;
  v_physical_currentness jsonb := '{}'::jsonb;
  v_candidate_currentness jsonb := '{}'::jsonb;
  v_direct_current_candidate_ids jsonb := '[]'::jsonb;
  v_physical_currentness_results jsonb := '[]'::jsonb;
  v_direct_current_count integer := 0;
  v_repair_owner_count integer := 0;
  v_post_cancel_patch_digest text := NULL::text;
  v_progress_recompute jsonb := '{}'::jsonb;
  v_post_commit_authority jsonb := '{}'::jsonb;
  v_preceding_scope_proven boolean := false;
BEGIN
  -- Preserve the last certified source authority before the generic overlay
  -- patch deliberately marks the scope non-current.  The saved authority is
  -- used only to republish the same immutable source rows; it is never used to
  -- derive or recalculate post-Draft economics.
  DROP TABLE IF EXISTS pg_temp._bpay_cancel_safe_original_authority;
  CREATE TEMPORARY TABLE pg_temp._bpay_cancel_safe_original_authority(
    candidate_id uuid PRIMARY KEY,
    attestation jsonb NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp._bpay_cancel_safe_original_authority(candidate_id,attestation)
  SELECT scope_row.candidate_id,
         COALESCE(scope_row.certified_preview_publication_attestation_json,'{}'::jsonb)
  FROM public.banking_pay_workbench_session_scope AS scope_row
  JOIN public.pay_batch_candidates AS batch_candidate
    ON batch_candidate.candidate_id=scope_row.candidate_id
   AND batch_candidate.pay_batch_id=p_pay_batch_id
  WHERE scope_row.session_id=p_session_id
  ORDER BY scope_row.candidate_id;

  v_result := public.pay_workbench_patch_preview_after_batch_mutation(
    p_session_id,
    p_pay_batch_id,
    p_operation_type,
    p_actor_user_id,
    COALESCE(p_options_json,'{}'::jsonb) || jsonb_build_object('defer_complex_enqueue',true)
  );

  IF COALESCE((v_result->>'ok')::boolean, true) IS NOT TRUE
     OR v_operation_type NOT IN ('DRAFT_DELETE', 'DRAFT_CANCEL') THEN
    RETURN v_result;
  END IF;

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
    AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
    AND session_row.discarded_at_utc IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_FULL_REFRESH_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_FULL_REFRESH_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  v_post_cancel_patch_digest:=NULLIF(BTRIM(COALESCE(v_result->>'post_cancel_patch_digest','')),'');

  -- V8 Draft rows are frozen by stable financial identity. A certified rebuild can
  -- replace their public preview UUIDs, so direct patched-row IDs are not a durable
  -- selection authority. Register only the exact frozen constituents belonging to
  -- the cancelled Candidate/channel scopes. The existing carry trigger applies the
  -- UNSELECTED intent to a matching rebuilt row without deriving any economics.
  DROP TABLE IF EXISTS pg_temp._bpay_cancelled_selection_intents;
  CREATE TEMPORARY TABLE pg_temp._bpay_cancelled_selection_intents ON COMMIT DROP AS
  SELECT
    frozen_payload.candidate_id,
    frozen_payload.preview_row_id AS source_preview_row_id,
    public._pay_workbench_preview_selection_key_v1(
      frozen_payload.candidate_id,
      frozen_payload.payload_json->>'section',
      frozen_payload.timesheet_id,
      frozen_payload.payload_json->>'key_type',
      frozen_payload.payload_json->>'key_value',
      frozen_payload.row_key,
      frozen_payload.payload_json
    ) AS stable_selection_key
  FROM private.banking_pay_draft_frozen_candidate_scopes_v8 AS frozen_scope
  JOIN private.banking_pay_draft_frozen_constituent_payloads_v8 AS frozen_payload
    ON frozen_payload.operation_id = frozen_scope.operation_id
   AND frozen_payload.candidate_id = frozen_scope.candidate_id
   AND frozen_payload.resolved_pay_channel = frozen_scope.resolved_pay_channel
  JOIN pg_temp._bpay_batch_mutation_candidates AS cancelled_candidate
    ON cancelled_candidate.candidate_id = frozen_scope.candidate_id
  WHERE frozen_scope.pay_batch_id = p_pay_batch_id
  ORDER BY frozen_payload.candidate_id, frozen_payload.constituent_ordinal;

  SELECT COALESCE(pg_catalog.sum(frozen_scope.constituent_count), 0)::integer
  INTO v_cancelled_selection_expected_count
  FROM private.banking_pay_draft_frozen_candidate_scopes_v8 AS frozen_scope
  JOIN pg_temp._bpay_batch_mutation_candidates AS cancelled_candidate
    ON cancelled_candidate.candidate_id = frozen_scope.candidate_id
  WHERE frozen_scope.pay_batch_id = p_pay_batch_id;

  SELECT pg_catalog.count(*)::integer,
         (pg_catalog.count(*) - pg_catalog.count(DISTINCT (intent.candidate_id, intent.stable_selection_key)))::integer
  INTO v_cancelled_selection_intent_count,
       v_cancelled_selection_duplicate_count
  FROM pg_temp._bpay_cancelled_selection_intents AS intent;

  IF v_cancelled_selection_expected_count > 0
     AND (
       v_cancelled_selection_intent_count IS DISTINCT FROM v_cancelled_selection_expected_count
       OR COALESCE(v_cancelled_selection_duplicate_count, 0) <> 0
       OR EXISTS (
         SELECT 1
         FROM pg_temp._bpay_cancelled_selection_intents AS invalid_intent
         WHERE invalid_intent.stable_selection_key IS NULL
       )
     ) THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_SELECTION_INTENT_IDENTITY_INCOMPLETE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_SELECTION_INTENT_IDENTITY_INCOMPLETE',
              'session_id', p_session_id,
              'pay_batch_id', p_pay_batch_id,
              'expected_count', v_cancelled_selection_expected_count,
              'actual_count', v_cancelled_selection_intent_count,
              'duplicate_count', v_cancelled_selection_duplicate_count
            )::text;
  END IF;

  WITH superseded AS (
    UPDATE public.banking_pay_workbench_selection_carry_registrations AS prior_intent
    SET status = 'SUPERSEDED',
        state_reason_code = 'NEWER_POST_CANCEL_UNSELECT_INTENT',
        updated_at_utc = v_now,
        completed_at_utc = v_now
    FROM pg_temp._bpay_cancelled_selection_intents AS current_intent
    WHERE prior_intent.target_session_id = p_session_id
      AND prior_intent.candidate_id = current_intent.candidate_id
      AND prior_intent.stable_selection_key = current_intent.stable_selection_key
      AND prior_intent.source_preview_row_id IS DISTINCT FROM current_intent.source_preview_row_id
      AND prior_intent.status IN ('PENDING', 'APPLIED')
    RETURNING prior_intent.id
  )
  SELECT pg_catalog.count(*)::integer
  INTO v_cancelled_selection_superseded_count
  FROM superseded;

  WITH inserted AS (
    INSERT INTO public.banking_pay_workbench_selection_carry_registrations(
      target_session_id,
      source_session_id,
      candidate_id,
      source_preview_row_id,
      stable_selection_key,
      selected,
      selection_state,
      source_priority,
      carry_reason,
      status,
      state_reason_code,
      source_row_snapshot_json,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      p_session_id,
      p_session_id,
      intent.candidate_id,
      intent.source_preview_row_id,
      intent.stable_selection_key,
      false,
      'UNSELECTED',
      -1000,
      'POST_CANCEL_RETURN_UNSELECTED',
      'PENDING',
      'AWAITING_STABLE_SELECTION_KEY',
      jsonb_build_object(
        'source_preview_row_id', intent.source_preview_row_id,
        'source_session_id', p_session_id,
        'candidate_id', intent.candidate_id,
        'stable_selection_key', intent.stable_selection_key,
        'selected', false,
        'selection_state', 'UNSELECTED',
        'selection_user_override', 'UNSELECTED',
        'selection_origin', 'POST_CANCEL_RETURN_UNSELECTED',
        'pay_batch_id', p_pay_batch_id,
        'policy_x_authority_scope', 'PRE_DRAFT_SELECTION_INTENT_ONLY'
      ),
      v_now,
      v_now
    FROM pg_temp._bpay_cancelled_selection_intents AS intent
    WHERE intent.stable_selection_key IS NOT NULL
    ON CONFLICT (target_session_id, source_preview_row_id) DO NOTHING
    RETURNING id
  )
  SELECT pg_catalog.count(*)::integer
  INTO v_cancelled_selection_registered_count
  FROM inserted;

  v_cancelled_selection_reused_count := GREATEST(
    COALESCE(v_cancelled_selection_intent_count, 0) - COALESCE(v_cancelled_selection_registered_count, 0),
    0
  );

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_cancelled_selection_intents AS intent
    LEFT JOIN public.banking_pay_workbench_selection_carry_registrations AS registered_intent
      ON registered_intent.target_session_id = p_session_id
     AND registered_intent.source_preview_row_id = intent.source_preview_row_id
    WHERE registered_intent.id IS NULL
       OR registered_intent.candidate_id IS DISTINCT FROM intent.candidate_id
       OR registered_intent.stable_selection_key IS DISTINCT FROM intent.stable_selection_key
       OR registered_intent.selected IS DISTINCT FROM false
       OR registered_intent.selection_state IS DISTINCT FROM 'UNSELECTED'
       OR registered_intent.status NOT IN ('PENDING', 'APPLIED')
  ) THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_SELECTION_INTENT_REGISTRATION_CONFLICT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_SELECTION_INTENT_REGISTRATION_CONFLICT',
              'session_id', p_session_id,
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  -- Cancelling a draft returns its rows to the live workbench, but it must not
  -- silently select those rows again. Persist an explicit selection snapshot
  -- before the full-candidate refresh is queued so the materialiser preserves
  -- every unrelated selection while restoring the cancelled rows unselected.
  UPDATE public.banking_pay_workbench_preview_rows AS cancelled_preview_row
  SET selected = false,
      selection_state = CASE
        WHEN UPPER(BTRIM(COALESCE(cancelled_preview_row.status, ''))) = 'READY' THEN 'UNSELECTED'
        ELSE 'NOT_SELECTABLE'
      END,
      row_json = jsonb_strip_nulls(
        COALESCE(cancelled_preview_row.row_json, '{}'::jsonb)
        || jsonb_build_object(
          'selected', false,
          'selection_state', CASE
            WHEN UPPER(BTRIM(COALESCE(cancelled_preview_row.status, ''))) = 'READY' THEN 'UNSELECTED'
            ELSE 'NOT_SELECTABLE'
          END,
          'selection_user_override', CASE
            WHEN COALESCE((SELECT setting.banking_pay_selection_intent_identity_v1_enabled
                             FROM public.settings_defaults AS setting WHERE setting.id=1),false)
              THEN 'UNSELECTED' ELSE cancelled_preview_row.row_json->>'selection_user_override' END,
          'selection_origin', CASE
            WHEN COALESCE((SELECT setting.banking_pay_selection_intent_identity_v1_enabled
                             FROM public.settings_defaults AS setting WHERE setting.id=1),false)
              THEN 'POST_CANCEL_RETURN_UNSELECTED' ELSE cancelled_preview_row.row_json->>'selection_origin' END,
          'selection_user_override_at_utc', CASE
            WHEN COALESCE((SELECT setting.banking_pay_selection_intent_identity_v1_enabled
                             FROM public.settings_defaults AS setting WHERE setting.id=1),false)
              THEN v_now::text ELSE cancelled_preview_row.row_json->>'selection_user_override_at_utc' END,
          'post_cancel_selection_restored', true,
          'post_cancel_selection_restored_at_utc', v_now::text,
          'post_cancel_selection_pay_batch_id', p_pay_batch_id::text
        )
      ),
      updated_at_utc = v_now
  WHERE cancelled_preview_row.session_id = p_session_id
    AND cancelled_preview_row.session_version = v_session.version
    AND EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(v_result->'patched_row_ids', '[]'::jsonb)) = 'array'
            THEN COALESCE(v_result->'patched_row_ids', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS patched_preview_row_id(value)
      WHERE patched_preview_row_id.value = cancelled_preview_row.id::text
    );

  GET DIAGNOSTICS v_cancelled_row_unselected_count = ROW_COUNT;

  SELECT COALESCE(
           jsonb_agg(to_jsonb(selected_preview_row.id::text) ORDER BY selected_preview_row.row_ordinal, selected_preview_row.id),
           '[]'::jsonb
         ),
         COUNT(*)::integer
  INTO v_preserved_selected_preview_row_ids,
       v_preserved_selected_row_count
  FROM public.banking_pay_workbench_preview_rows AS selected_preview_row
  WHERE selected_preview_row.session_id = p_session_id
    AND selected_preview_row.session_version = v_session.version
    AND LOWER(COALESCE(NULLIF(BTRIM(selected_preview_row.section), ''), 'canonical_preview_lines')) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(selected_preview_row.status, ''))) = 'READY'
    AND COALESCE(selected_preview_row.selected, false) IS TRUE
    AND UPPER(BTRIM(COALESCE(selected_preview_row.selection_state, ''))) = 'SELECTED';

  UPDATE public.banking_pay_workbench_sessions AS selection_session
  SET selected_row_count = COALESCE(v_preserved_selected_row_count, 0),
      server_selected_preview_row_ids = COALESCE(v_preserved_selected_preview_row_ids, '[]'::jsonb),
      server_selected_preview_row_ids_provided = true,
      progress_json = COALESCE(selection_session.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_post_cancel_selection_reconcile_at_utc', v_now::text,
          'last_post_cancel_selection_pay_batch_id', p_pay_batch_id::text,
          'last_post_cancel_unselected_row_count', COALESCE(v_cancelled_row_unselected_count, 0),
          'selection_intent_v1', COALESCE(selection_session.progress_json->'selection_intent_v1', '{}'::jsonb)
            || jsonb_build_object(
              'canonical_preview_lines', jsonb_build_object(
                'mode', 'EXPLICIT_INCLUDE',
                'section', 'canonical_preview_lines',
                'identity', 'preview_row_id_with_session_section_candidate_row_key_conflict_identity',
                'updated_at_utc', v_now::text,
                'updated_by_user_id', COALESCE(p_actor_user_id, v_session.actor_user_id)::text,
                'source_selection_mode', 'POST_CANCEL_RECONCILE',
                'source_selection_action', 'RETURN_CANCELLED_ROWS_UNSELECTED',
                'server_selected_preview_row_ids_provided', true,
                'selected_row_count', COALESCE(v_preserved_selected_row_count, 0)
              )
            )
        ),
      progress_counter_version = COALESCE(selection_session.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE selection_session.id = p_session_id;

  DROP TABLE IF EXISTS pg_temp._bpay_cancel_safe_route_candidates;
  CREATE TEMPORARY TABLE pg_temp._bpay_cancel_safe_route_candidates(
    candidate_id uuid PRIMARY KEY,
    direct_current boolean NOT NULL DEFAULT false,
    currentness_reason text NULL,
    repair_job_id uuid NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp._bpay_cancel_safe_route_candidates(candidate_id)
  SELECT DISTINCT candidate_value.value::uuid
  FROM jsonb_array_elements_text(
    CASE WHEN jsonb_typeof(v_result->'affected_candidate_ids')='array'
      THEN v_result->'affected_candidate_ids' ELSE '[]'::jsonb END
  ) AS candidate_value(value)
  WHERE candidate_value.value
    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ORDER BY candidate_value.value::uuid;

  -- The fast direct branch does not recalculate economics. It asks the
  -- existing certified publisher to reconstruct the preview byte-for-byte
  -- from the already-current bounded source, then proves the physical rows.
  -- Unsupported authority kinds fail closed to one canonical repair owner.
  FOR v_candidate_id IN
    SELECT route_candidate.candidate_id
    FROM pg_temp._bpay_cancel_safe_route_candidates AS route_candidate
    ORDER BY route_candidate.candidate_id
  LOOP
    PERFORM pg_advisory_xact_lock(
      hashtextextended(public._pay_workbench_candidate_serial_key(v_candidate_id),24062027)
    );

    SELECT scope_row.* INTO v_scope
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.session_id=p_session_id
      AND scope_row.candidate_id=v_candidate_id
    FOR UPDATE;
    SELECT COALESCE(original_authority.attestation,'{}'::jsonb)
    INTO v_attestation
    FROM pg_temp._bpay_cancel_safe_original_authority AS original_authority
    WHERE original_authority.candidate_id=v_candidate_id;
    v_attestation:=COALESCE(v_attestation,'{}'::jsonb);
    v_republication_result:='{}'::jsonb;

    IF v_attestation->>'attestation_version'='CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
       AND v_attestation->>'contract_version'='3'
       AND v_attestation->>'semantic_contract_version'='READY_TO_PAY_SEMANTIC_V2'
       AND v_attestation->>'authority_kind'='BOUNDED_FULL_SOURCE_BUILD'
       AND COALESCE(v_attestation->>'economic_build_id','')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND COALESCE(v_attestation->>'source_build_run_id','')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND COALESCE(v_attestation->>'completion_job_id','')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND COALESCE(v_attestation->>'source_change_seq','')~'^[0-9]{1,18}$'
       AND COALESCE(v_attestation->>'session_version','')~'^[1-9][0-9]{0,18}$'
       AND (v_attestation->>'session_version')::bigint=v_session.version THEN
      BEGIN
        v_republication_result:=private.pay_workbench_publish_certified_source_preview_v1(
          p_session_id,v_candidate_id,
          (v_attestation->>'economic_build_id')::uuid,
          (v_attestation->>'source_build_run_id')::uuid,
          (v_attestation->>'source_change_seq')::bigint,
          (v_attestation->>'session_version')::bigint,
          (v_attestation->>'completion_job_id')::uuid,
          -- This branch is intentionally restricted to an already-certified
          -- BOUNDED_FULL_SOURCE_BUILD.  Republish its complete retained source
          -- as candidate-wide authority even where the historical request that
          -- escalated to that full build was originally labelled TARGETED.
          -- Reusing that stale request label would make the publisher demand a
          -- targeted-scope certificate that is irrelevant to the completed
          -- full-candidate source and can leave one public row DIRTY.
          'CANDIDATE_FULL_LIVE',
          '[]'::jsonb,'[]'::jsonb,
          jsonb_build_object(
            'contract_version',3,
            'semantic_contract_version','READY_TO_PAY_SEMANTIC_V2',
            'authority_kind','BOUNDED_FULL_SOURCE_BUILD',
            'invocation_kind','DUPLICATE_REPLAY_REPAIR',
            'final_state',CASE WHEN COALESCE((v_attestation->>'source_row_count')::integer,0)=0
              THEN 'SOURCE_EMPTY' ELSE 'READY' END
          )
        );
      EXCEPTION WHEN OTHERS THEN
        v_republication_result:=jsonb_build_object(
          'ok',false,'code','POST_CANCEL_EXACT_REPUBLICATION_REJECTED',
          'sqlstate',SQLSTATE
        );
      END;
    END IF;

    -- The certified publisher owns physical source/preview parity and its V3
    -- attestation; the caller owns the session lifecycle transition.  Mirror
    -- the established terminal-completion contract only after the publisher
    -- has proved the retained full source exactly, then recompute candidate
    -- state before the independent physical-currentness fence below.
    IF COALESCE((v_republication_result->>'ok')::boolean,false)
       AND COALESCE((v_republication_result->>'parity_complete')::boolean,false) THEN
      UPDATE public.banking_pay_workbench_session_scope AS republished_scope
      SET status=CASE
            WHEN COALESCE((v_republication_result->>'source_row_count')::integer,0)=0
              THEN 'SOURCE_EMPTY' ELSE 'MATERIALISED' END,
          seeded=true,
          dirty=false,
          pending_job_id=NULL::uuid,
          error_json=NULL::jsonb,
          updated_at_utc=v_now
      WHERE republished_scope.session_id=p_session_id
        AND republished_scope.candidate_id=v_candidate_id;

      v_candidate_state_result:=public.pay_workbench_delta_update_candidate_state_v1(
        p_session_id,
        v_candidate_id,
        (v_attestation->>'source_build_run_id')::uuid,
        jsonb_build_object(
          'context','DELTA_REFRESH',
          'source_change_seq',(v_attestation->>'source_change_seq')::bigint,
          'session_version',(v_attestation->>'session_version')::bigint,
          'authority_kind','BOUNDED_FULL_SOURCE_BUILD',
          'invocation_kind','POST_CANCEL_EXACT_REPUBLICATION'
        )
      );

      PERFORM public.pay_workbench_session_recompute_progress_counters(
        p_session_id,true,'POST_CANCEL_EXACT_REPUBLICATION',true
      );
    END IF;

    EXECUTE 'SELECT private.pay_workbench_candidate_physical_currentness_page_v1($1,$2,$3,$4)'
      INTO v_physical_currentness
      USING p_session_id,ARRAY[v_candidate_id],'TERMINAL_CURRENT',
        jsonb_build_object('contract_version',1,'allow_active_owner',false);
    v_candidate_currentness:=COALESCE(v_physical_currentness->'candidate_results'->0,'{}'::jsonb);
    v_physical_currentness_results:=v_physical_currentness_results||jsonb_build_array(
      v_candidate_currentness||jsonb_build_object(
        'republication',v_republication_result,
        'candidate_state_adoption',v_candidate_state_result
      )
    );

    IF COALESCE((v_candidate_currentness->>'terminal_current')::boolean,false) THEN
      UPDATE pg_temp._bpay_cancel_safe_route_candidates AS route_candidate
      SET direct_current=true,currentness_reason=v_candidate_currentness->>'currentness_reason'
      WHERE route_candidate.candidate_id=v_candidate_id;
      v_direct_current_count:=v_direct_current_count+1;
      v_direct_current_candidate_ids:=v_direct_current_candidate_ids||jsonb_build_array(v_candidate_id::text);
    ELSE
      UPDATE pg_temp._bpay_cancel_safe_route_candidates AS route_candidate
      SET currentness_reason=v_candidate_currentness->>'currentness_reason'
      WHERE route_candidate.candidate_id=v_candidate_id;
    END IF;
  END LOOP;

  -- The Worker may supply these identifiers, but the cancelled frozen batch is
  -- the fail-closed authority. Reading its retained (now voided) items makes the
  -- race guard independent of optional response fields.
  WITH finance_case_scope AS (
    SELECT batch_item.finance_case_id
    FROM public.pay_batch_items AS batch_item
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
    WHERE batch_candidate.pay_batch_id = p_pay_batch_id
      AND batch_item.finance_case_id IS NOT NULL

    UNION ALL

    SELECT raw_value.value_text::uuid
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(p_options_json->'changed_finance_case_ids') = 'array'
          THEN p_options_json->'changed_finance_case_ids'
        ELSE '[]'::jsonb
      END
    ) AS raw_value(value_text)
    WHERE raw_value.value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

    UNION ALL

    SELECT raw_value.value_text::uuid
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(p_options_json#>'{cancellation_result,changed_scope_json,changed_finance_case_ids}') = 'array'
          THEN p_options_json#>'{cancellation_result,changed_scope_json,changed_finance_case_ids}'
        ELSE '[]'::jsonb
      END
    ) AS raw_value(value_text)
    WHERE raw_value.value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  )
  SELECT COALESCE(
    array_agg(DISTINCT finance_case_scope.finance_case_id ORDER BY finance_case_scope.finance_case_id),
    ARRAY[]::uuid[]
  )
  INTO v_changed_finance_case_ids
  FROM finance_case_scope
  WHERE finance_case_scope.finance_case_id IS NOT NULL;

  -- Component restoration and reservation release enqueue finance-case dirty
  -- work in the cancellation transaction. If allowed to fan out afterwards it
  -- can narrow the scope to one linked timesheet and overwrite the correct
  -- candidate-wide recovery allocation. Only still-QUEUED jobs for finance
  -- cases frozen into this cancelled batch are superseded. A supersession is a
  -- successful terminal orchestration result, not a processing failure. Keep
  -- the reason as immutable payload audit evidence while the replacement full
  -- candidate refresh remains responsible for rebuilding the live preview.
  -- RUNNING jobs and all unrelated finance cases are deliberately outside this
  -- update.
  -- Do not terminalise queued finance/targeted work before canonical owner
  -- election.  The enqueue owner now decides whether existing work is covered,
  -- coalesced or genuinely superseded; RUNNING work is never killed here.
  v_superseded_finance_dirty_job_count := 0;

  FOR v_candidate_id IN
    SELECT route_candidate.candidate_id
    FROM pg_temp._bpay_cancel_safe_route_candidates AS route_candidate
    WHERE route_candidate.direct_current IS NOT TRUE
    ORDER BY route_candidate.candidate_id
  LOOP
    v_superseded_targeted_job_chunk_count := 0;
    v_post_commit_authority:=COALESCE(
      p_options_json->'post_commit_authorities_v3'->v_candidate_id::text,'{}'::jsonb
    );
    v_preceding_scope_proven:=
      COALESCE(v_post_commit_authority->>'contract_version','')
        ='POST_FINANCIAL_TERMINAL_AUTHORITY_V3'
      AND COALESCE((v_post_commit_authority->>'admitted')::boolean,false)
      AND COALESCE(v_post_commit_authority->>'candidate_id','')=v_candidate_id::text
      AND COALESCE(v_post_commit_authority->>'dirty_generation','') ~ '^[0-9]{1,18}$'
      AND COALESCE(v_post_commit_authority->>'scope_change_tx_token','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    SELECT COALESCE(
      jsonb_agg(DISTINCT batch_item.timesheet_id::text ORDER BY batch_item.timesheet_id::text),
      '[]'::jsonb
    )
    INTO v_targeted_timesheet_ids
    FROM public.pay_batch_items AS batch_item
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id=batch_item.pay_batch_candidate_id
    WHERE batch_candidate.pay_batch_id=p_pay_batch_id
      AND batch_candidate.candidate_id=v_candidate_id
      AND batch_item.timesheet_id IS NOT NULL;

    v_requested_refresh_scope:=CASE
      WHEN jsonb_array_length(COALESCE(v_targeted_timesheet_ids,'[]'::jsonb))>0
        THEN 'TARGETED_TIMESHEETS'
      ELSE 'CANDIDATE_FULL_LIVE'
    END;

    v_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
      p_snapshot_run_id => v_session.source_snapshot_run_id,
      p_candidate_id => v_candidate_id,
      p_reason => 'POST_DRAFT_CANCEL_CURRENT_AUTHORITY_REFRESH',
      p_actor_user_id => COALESCE(p_actor_user_id, v_session.actor_user_id),
      p_payload_json => jsonb_build_object(
        'session_id', p_session_id::text,
        'source_session_id', p_session_id::text,
        'source_snapshot_run_id', v_session.source_snapshot_run_id::text,
        'snapshot_run_id', v_session.source_snapshot_run_id::text,
        'session_version', v_session.version,
        'session_signature', v_session.session_signature,
        'operation_type', v_operation_type,
        'pay_batch_id', p_pay_batch_id::text,
        'enqueue_origin', 'PAYMENT_CANCEL_CANONICAL_REFRESH_V3',
        'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids,'[]'::jsonb),
        'targeted_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids,'[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_targeted_timesheet_ids,'[]'::jsonb),
        'linked_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids,'[]'::jsonb),
        'refresh_scope_kind', v_requested_refresh_scope,
        'pay_channel_scope', 'ALL',
        'projection_class', 'POST_DRAFT_CANCEL_CURRENT_AUTHORITY',
        'fallback_reason', 'CERTIFIED_CANCELLATION_REVERSION_REJECTED',
        'canonical_route_ladder_required', true,
        'source_publication_baseline_required', true,
        'required_physical_publication_contract_version', 1,
        'bounded_scope_state_precedes_job',v_preceding_scope_proven,
        'scope_change_tx_token',CASE WHEN v_preceding_scope_proven
          THEN v_post_commit_authority->>'scope_change_tx_token' ELSE NULL END,
        'scope_change_generation',CASE WHEN v_preceding_scope_proven
          THEN (v_post_commit_authority->>'dirty_generation')::bigint ELSE NULL END,
        'correction_request_id',p_options_json->>'correction_request_id',
        'correction_operation_id',v_post_commit_authority->>'operation_id',
        'correction_held_dirty_job_id',v_post_commit_authority->>'held_dirty_job_id',
        'post_commit_authority_digest',v_post_commit_authority->>'authority_digest',
        'post_cancel_patch_digest',v_post_cancel_patch_digest,
        'superseded_finance_dirty_job_count', v_superseded_finance_dirty_job_count,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      )
    );

    IF COALESCE((v_enqueue_result->>'ok')::boolean,true) IS NOT TRUE
       OR (
         COALESCE(v_enqueue_result->>'job_id','')
           !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         AND UPPER(BTRIM(COALESCE(v_enqueue_result->>'owner_resolution',''))) NOT IN (
           'ACTIVE_CURRENT_OWNER_COVERS_REQUEST','COMPLETE_CURRENT_AUTHORITY','STALE_INCOMING_REQUEST'
         )
         AND COALESCE((v_enqueue_result->>'coalesced')::boolean,false) IS NOT TRUE
       ) THEN
      RAISE EXCEPTION 'PAYMENT_CANCEL_FULL_REFRESH_JOB_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAYMENT_CANCEL_FULL_REFRESH_JOB_INVALID',
                'session_id', p_session_id::text,
                'candidate_id', v_candidate_id::text,
                'pay_batch_id', p_pay_batch_id::text,
                'enqueue_result', v_enqueue_result
              )::text;
    END IF;

    EXECUTE 'SELECT private.pay_workbench_candidate_physical_currentness_page_v1($1,$2,$3,$4)'
      INTO v_physical_currentness
      USING p_session_id,ARRAY[v_candidate_id],'TERMINAL_CURRENT',
        jsonb_build_object('contract_version',1,'allow_active_owner',true);
    v_candidate_currentness:=COALESCE(v_physical_currentness->'candidate_results'->0,'{}'::jsonb);
    v_physical_currentness_results:=v_physical_currentness_results||jsonb_build_array(
      v_candidate_currentness||jsonb_build_object('enqueue_result',v_enqueue_result)
    );

    IF COALESCE((v_candidate_currentness->>'current_or_active_owner')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAYMENT_CANCEL_CURRENT_OR_REPAIR_OWNER_REQUIRED'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object(
          'code','PAYMENT_CANCEL_CURRENT_OR_REPAIR_OWNER_REQUIRED',
          'session_id',p_session_id,'candidate_id',v_candidate_id,
          'pay_batch_id',p_pay_batch_id,
          'currentness_reason',v_candidate_currentness->>'currentness_reason'
        )::text;
    END IF;

    IF COALESCE(v_candidate_currentness->>'active_owner_job_id','')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_job_id:=(v_candidate_currentness->>'active_owner_job_id')::uuid;
      UPDATE pg_temp._bpay_cancel_safe_route_candidates AS route_candidate
      SET repair_job_id=v_job_id,currentness_reason=v_candidate_currentness->>'currentness_reason'
      WHERE route_candidate.candidate_id=v_candidate_id;
      v_repair_owner_count:=v_repair_owner_count+1;
      v_full_refresh_job_ids := v_full_refresh_job_ids || jsonb_build_array(v_job_id::text);
      v_full_refresh_count := v_full_refresh_count + 1;
      IF v_requested_refresh_scope='CANDIDATE_FULL_LIVE' THEN
        v_candidate_full_refresh_count:=v_candidate_full_refresh_count+1;
      END IF;
    ELSIF COALESCE((v_candidate_currentness->>'terminal_current')::boolean,false) THEN
      UPDATE pg_temp._bpay_cancel_safe_route_candidates AS route_candidate
      SET direct_current=true,currentness_reason=v_candidate_currentness->>'currentness_reason'
      WHERE route_candidate.candidate_id=v_candidate_id;
      v_direct_current_count:=v_direct_current_count+1;
      v_direct_current_candidate_ids:=v_direct_current_candidate_ids||jsonb_build_array(v_candidate_id::text);
    END IF;
  END LOOP;

  SELECT pg_catalog.count(*) FILTER (WHERE registered_intent.status = 'PENDING')::integer,
         pg_catalog.count(*) FILTER (WHERE registered_intent.status = 'APPLIED')::integer
  INTO v_cancelled_selection_pending_count,
       v_cancelled_selection_applied_count
  FROM pg_temp._bpay_cancelled_selection_intents AS intent
  JOIN public.banking_pay_workbench_selection_carry_registrations AS registered_intent
    ON registered_intent.target_session_id = p_session_id
   AND registered_intent.source_preview_row_id = intent.source_preview_row_id
   AND registered_intent.candidate_id = intent.candidate_id
   AND registered_intent.stable_selection_key = intent.stable_selection_key;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_cancel_safe_route_candidates AS route_candidate
    JOIN pg_temp._bpay_cancelled_selection_intents AS intent
      ON intent.candidate_id = route_candidate.candidate_id
    LEFT JOIN public.banking_pay_workbench_selection_carry_registrations AS applied_intent
      ON applied_intent.target_session_id = p_session_id
     AND applied_intent.source_preview_row_id = intent.source_preview_row_id
     AND applied_intent.status = 'APPLIED'
    WHERE route_candidate.direct_current IS TRUE
      AND applied_intent.id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_CURRENT_SELECTION_INTENT_NOT_APPLIED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_CURRENT_SELECTION_INTENT_NOT_APPLIED',
              'session_id', p_session_id,
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  v_progress_recompute:=public.pay_workbench_session_recompute_progress_counters(
    p_session_id,true,'POST_CANCEL_PHYSICAL_CURRENTNESS_FINALISE',true
  );

  RETURN v_result || jsonb_build_object(
    'targeted_refresh_enqueued', v_full_refresh_count > 0,
    'targeted_refresh_enqueued_count', v_full_refresh_count,
    'full_candidate_refresh_enqueued', v_candidate_full_refresh_count > 0,
    'full_candidate_refresh_enqueued_count', v_candidate_full_refresh_count,
    'full_candidate_refresh_job_ids', v_full_refresh_job_ids,
    'superseded_targeted_refresh_job_count', v_superseded_targeted_job_count,
    'superseded_finance_dirty_job_count', v_superseded_finance_dirty_job_count,
    'changed_finance_case_count', COALESCE(array_length(v_changed_finance_case_ids, 1), 0),
    'cancelled_row_unselected_count', COALESCE(v_cancelled_row_unselected_count, 0),
    'cancelled_selection_intent_expected_count', COALESCE(v_cancelled_selection_expected_count, 0),
    'cancelled_selection_intent_count', COALESCE(v_cancelled_selection_intent_count, 0),
    'cancelled_selection_intent_registered_count', COALESCE(v_cancelled_selection_registered_count, 0),
    'cancelled_selection_intent_reused_count', COALESCE(v_cancelled_selection_reused_count, 0),
    'cancelled_selection_intent_superseded_count', COALESCE(v_cancelled_selection_superseded_count, 0),
    'cancelled_selection_intent_pending_count', COALESCE(v_cancelled_selection_pending_count, 0),
    'cancelled_selection_intent_applied_count', COALESCE(v_cancelled_selection_applied_count, 0),
    'server_selected_preview_row_ids', COALESCE(v_preserved_selected_preview_row_ids, '[]'::jsonb),
    'server_selected_preview_row_ids_provided', true,
    'selected_row_count', COALESCE(v_preserved_selected_row_count, 0),
    'post_cancel_patch_digest',v_post_cancel_patch_digest,
    'physical_currentness_checked',true,
    'physical_currentness_proven',v_direct_current_count=(SELECT COUNT(*) FROM pg_temp._bpay_cancel_safe_route_candidates),
    'direct_current_patch_applied',v_direct_current_count>0,
    'direct_current_candidate_count',v_direct_current_count,
    'direct_current_candidate_ids',v_direct_current_candidate_ids,
    'repair_job_created_or_reused',v_repair_owner_count>0,
    'repair_owner_count',v_repair_owner_count,
    'physical_currentness_results',v_physical_currentness_results,
    'progress_recompute',v_progress_recompute,
    'final_scope_status',CASE
      WHEN v_repair_owner_count>0 THEN 'SOURCE_BUILD_PENDING'
      WHEN v_direct_current_count>0 THEN 'MATERIALISED'
      ELSE 'NOT_REQUIRED' END,
    'nudge_required',v_repair_owner_count>0,
    'refresh_scope_kind', CASE
      WHEN v_candidate_full_refresh_count>0 AND v_candidate_full_refresh_count=v_full_refresh_count THEN 'CANDIDATE_FULL_LIVE'
      WHEN v_full_refresh_count>0 THEN 'CANONICAL_ROUTE_LADDER'
      ELSE NULL::text END,
    'source_session_preserved', true,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
    'policy_x_checked', true
  );
END;
$function$;

-- public._pay_active_settled_components from supabase/repeatable/26092026_0201_banking_pay_stage2_financial_readers_v1.sql; definition SHA-256 073842bb1da6abb079d548922a3fb56a77b8d26b76001c2b74740731b37142df.
CREATE OR REPLACE FUNCTION public._pay_active_settled_components(p_timesheet_ids uuid[])
 RETURNS TABLE(timesheet_id uuid, key_type text, key_value text, amount_ex_vat numeric, amount_inc_vat numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET jit TO 'off'
AS $function$
WITH input_timesheets AS (
  SELECT DISTINCT
    input_timesheet_values.timesheet_id_value AS timesheet_id
  FROM unnest(COALESCE(p_timesheet_ids, ARRAY[]::uuid[])) AS input_timesheet_values(timesheet_id_value)
  WHERE input_timesheet_values.timesheet_id_value IS NOT NULL
),
rotation_scope_rows AS (
  SELECT
    scope_rows.requested_timesheet_id,
    scope_rows.booking_id,
    scope_rows.canonical_timesheet_id,
    scope_rows.family_timesheet_id,
    scope_rows.family_is_current,
    scope_rows.family_version,
    scope_rows.requested_is_canonical
  FROM private.bpay_settled_financial_scope_v1(
    (
      SELECT COALESCE(
        ARRAY_AGG(input_timesheets.timesheet_id ORDER BY input_timesheets.timesheet_id),
        ARRAY[]::uuid[]
      )
      FROM input_timesheets
    )
  ) AS scope_rows
),
rotation_scope_keyed AS (
  SELECT
    rotation_scope_rows.requested_timesheet_id,
    rotation_scope_rows.booking_id,
    rotation_scope_rows.canonical_timesheet_id,
    rotation_scope_rows.family_timesheet_id,
    rotation_scope_rows.family_is_current,
    rotation_scope_rows.family_version,
    rotation_scope_rows.requested_is_canonical,
    COALESCE(rotation_scope_rows.booking_id, rotation_scope_rows.requested_timesheet_id::text) AS scope_family_key
  FROM rotation_scope_rows
  WHERE rotation_scope_rows.requested_timesheet_id IS NOT NULL
),
projection_targets AS (
  SELECT
    rotation_scope_keyed.scope_family_key,
    COALESCE(
      (
        ARRAY_AGG(DISTINCT rotation_scope_keyed.canonical_timesheet_id ORDER BY rotation_scope_keyed.canonical_timesheet_id)
        FILTER (
          WHERE COALESCE(rotation_scope_keyed.requested_is_canonical, false) = true
            AND rotation_scope_keyed.canonical_timesheet_id IS NOT NULL
        )
      )[1],
      (
        ARRAY_AGG(DISTINCT rotation_scope_keyed.requested_timesheet_id ORDER BY rotation_scope_keyed.requested_timesheet_id)
        FILTER (WHERE rotation_scope_keyed.requested_timesheet_id IS NOT NULL)
      )[1],
      (
        ARRAY_AGG(DISTINCT rotation_scope_keyed.canonical_timesheet_id ORDER BY rotation_scope_keyed.canonical_timesheet_id)
        FILTER (WHERE rotation_scope_keyed.canonical_timesheet_id IS NOT NULL)
      )[1]
    ) AS projected_timesheet_id
  FROM rotation_scope_keyed
  GROUP BY rotation_scope_keyed.scope_family_key
),
family_to_projection AS (
  SELECT DISTINCT
    rotation_scope_keyed.family_timesheet_id,
    projection_targets.projected_timesheet_id
  FROM rotation_scope_keyed
  JOIN projection_targets
    ON projection_targets.scope_family_key = rotation_scope_keyed.scope_family_key
  WHERE rotation_scope_keyed.family_timesheet_id IS NOT NULL
    AND projection_targets.projected_timesheet_id IS NOT NULL
),
active_item_ids AS (
  SELECT DISTINCT
    pay_batch_items.id AS pay_batch_item_id,
    family_to_projection.projected_timesheet_id AS projected_timesheet_id
  FROM family_to_projection
  -- CAP-01 A8: probe items per requested family Timesheet (idx_pay_batch_items_timesheet); the fence keeps the
  -- planner from re-flattening this into a hash join over every payment item ever written.
  CROSS JOIN LATERAL (
    SELECT scoped_item.*
    FROM public.pay_batch_items AS scoped_item
    WHERE scoped_item.timesheet_id = family_to_projection.family_timesheet_id
    OFFSET 0
  ) AS pay_batch_items
  JOIN public.pay_batch_candidates
    ON public.pay_batch_candidates.id = pay_batch_items.pay_batch_candidate_id
  LEFT JOIN public.pay_bank_transfers
    ON public.pay_bank_transfers.id = pay_batch_items.pay_bank_transfer_id
  WHERE COALESCE(pay_batch_items.is_voided, false) = false
    AND UPPER(BTRIM(COALESCE(pay_batch_items.item_type, ''))) IN (
      'SEGMENT_DELTA',
      'EXPENSE_DELTA',
      'ADJUSTMENT_DELTA',
      'MILEAGE_DELTA'
    )
    AND (
      UPPER(BTRIM(COALESCE(public.pay_batch_candidates.settlement_status, ''))) = 'SETTLED'
      OR public.pay_batch_candidates.settled_at_utc IS NOT NULL
      OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) = 'COMPLETED'
      OR public.pay_bank_transfers.completed_at_utc IS NOT NULL
      OR EXISTS (
        SELECT 1
        FROM public.timesheet_pay_state_history AS active_history
        WHERE active_history.pay_batch_id = public.pay_batch_candidates.pay_batch_id
          AND active_history.timesheet_id = pay_batch_items.timesheet_id
      )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS applied_corrections
      WHERE applied_corrections.pay_batch_item_id = pay_batch_items.id
        AND applied_corrections.status = 'APPLIED'
        AND applied_corrections.correction_item_kind IN (
          'PRE_BANK_CANCEL',
          'NO_MONEY_UNWIND',
          'SETTLED_REVERSAL'
        )
    )
),
active_item_id_array AS (
  SELECT
    CASE
      WHEN COUNT(*) = 0 THEN ARRAY['00000000-0000-0000-0000-000000000000'::uuid]
      ELSE ARRAY_AGG(active_item_ids.pay_batch_item_id ORDER BY active_item_ids.pay_batch_item_id)
    END AS pay_batch_item_ids
  FROM active_item_ids
),
active_components AS (
  SELECT
    active_item_ids.pay_batch_item_id,
    active_item_ids.projected_timesheet_id AS component_timesheet_id,
    economic_components.key_type AS component_key_type,
    economic_components.key_value AS component_key_value,
    economic_components.source_amount_ex_vat AS component_amount_ex_vat,
    economic_components.source_amount_inc_vat AS component_amount_inc_vat
  FROM active_item_id_array
  JOIN LATERAL public._pay_batch_item_economic_components(
    p_pay_batch_id => NULL::uuid,
    p_pay_batch_item_ids => active_item_id_array.pay_batch_item_ids
  ) AS economic_components
    ON true
  JOIN active_item_ids
    ON active_item_ids.pay_batch_item_id = economic_components.pay_batch_item_id
  WHERE active_item_ids.projected_timesheet_id IS NOT NULL
    AND economic_components.timesheet_id IS NOT NULL
    AND economic_components.key_type IS NOT NULL
    AND BTRIM(COALESCE(economic_components.key_type, '')) <> ''
    AND economic_components.key_value IS NOT NULL
    AND BTRIM(COALESCE(economic_components.key_value, '')) <> ''
    AND economic_components.key_resolution_failure_reason IS NULL
    AND UPPER(BTRIM(COALESCE(economic_components.item_type, ''))) IN (
      'SEGMENT_DELTA',
      'EXPENSE_DELTA',
      'ADJUSTMENT_DELTA',
      'MILEAGE_DELTA'
    )
    AND UPPER(BTRIM(COALESCE(economic_components.key_type, ''))) IN (
      'TS_DAY',
      'TS_TOTAL',
      'ADDITIONAL_CODE',
      'ADJUSTMENT_CODE',
      'EXPENSE_CODE'
    )
    AND NOT (
      UPPER(BTRIM(COALESCE(economic_components.key_type, ''))) = 'TS_DAY'
      AND economic_components.key_value !~ '^\d{4}-\d{2}-\d{2}$'
    )
),
active_components_by_item_key AS (
  SELECT
    active_components.pay_batch_item_id,
    active_components.component_timesheet_id AS timesheet_id,
    UPPER(BTRIM(active_components.component_key_type)) AS key_type,
    active_components.component_key_value AS key_value,
    ROUND(COALESCE(SUM(COALESCE(active_components.component_amount_ex_vat, 0)), 0), 2)::numeric AS amount_ex_vat,
    ROUND(COALESCE(SUM(COALESCE(active_components.component_amount_inc_vat, 0)), 0), 2)::numeric AS amount_inc_vat
  FROM active_components
  GROUP BY
    active_components.pay_batch_item_id,
    active_components.component_timesheet_id,
    UPPER(BTRIM(active_components.component_key_type)),
    active_components.component_key_value
),
settled_finance_movement_components AS (
  SELECT
    finance_item.id AS pay_batch_item_id,
    family_to_projection.projected_timesheet_id AS timesheet_id,
    UPPER(BTRIM(finance_item.frozen_component_key_type)) AS key_type,
    BTRIM(finance_item.frozen_component_key_value) AS key_value,
    ROUND(
      CASE
        WHEN UPPER(BTRIM(finance_item.item_type)) = 'OVERPAYMENT_RECOVERY' THEN -1
        ELSE 1
      END
      * finance_source_amount.source_amount_ex_vat,
      2
    )::numeric AS amount_ex_vat,
    ROUND(
      CASE
        WHEN UPPER(BTRIM(finance_item.item_type)) = 'OVERPAYMENT_RECOVERY' THEN -1
        ELSE 1
      END
      * COALESCE(
          NULLIF(ABS(finance_item.amount_inc_vat), 0),
          finance_source_amount.source_amount_ex_vat
        ),
      2
    )::numeric AS amount_inc_vat
  FROM family_to_projection
  -- CAP-01 A9: per requested family, index-driven; identical mapping to the retired CASE
  -- (direct = item timesheet else valid frozen-basis timesheet, maintained by bpay_item_work_reference_v1;
  --  component fallback only when direct is NULL).
  CROSS JOIN LATERAL (
    SELECT direct_item.*
    FROM public.pay_batch_items AS direct_item
    WHERE direct_item.bpay_direct_source_timesheet_id_v1 = family_to_projection.family_timesheet_id
    UNION ALL
    SELECT fallback_item.*
    FROM public.pay_finance_case_components AS fallback_component
    JOIN public.pay_batch_items AS fallback_item
      ON fallback_item.finance_component_id = fallback_component.id
     AND fallback_item.bpay_direct_source_timesheet_id_v1 IS NULL
    WHERE fallback_component.linked_timesheet_id = family_to_projection.family_timesheet_id
    OFFSET 0
  ) AS finance_item
  JOIN public.pay_batch_candidates AS finance_candidate
    ON finance_candidate.id = finance_item.pay_batch_candidate_id
  LEFT JOIN public.pay_bank_transfers AS finance_transfer
    ON finance_transfer.id = finance_item.pay_bank_transfer_id
  -- Read only this item's reservations through its existing item-id index.
  -- Keep GROUP BY: no reservation must remain a missing LEFT JOIN row, not
  -- a synthetic zero-valued reservation that could change fallback semantics.
  LEFT JOIN LATERAL (
    SELECT
      item_reservation.pay_batch_item_id,
      BOOL_OR(
        UPPER(BTRIM(COALESCE(item_reservation.status, ''))) = 'SETTLED'
        OR item_reservation.settled_at_utc IS NOT NULL
      ) AS has_settled_reservation,
      ROUND(COALESCE(SUM(
        ABS(COALESCE(
          item_reservation.reserved_source_amount,
          item_reservation.reserved_amount,
          0
        ))
      ) FILTER (
        WHERE UPPER(BTRIM(COALESCE(item_reservation.status, ''))) = 'SETTLED'
           OR item_reservation.settled_at_utc IS NOT NULL
      ), 0), 2)::numeric AS settled_source_amount_ex_vat
    FROM public.pay_advance_reservations AS item_reservation
    WHERE item_reservation.pay_batch_item_id = finance_item.id
    GROUP BY item_reservation.pay_batch_item_id
  ) AS finance_reservation ON true
  LEFT JOIN public.pay_finance_case_components AS finance_component
    ON finance_component.id = finance_item.finance_component_id
  CROSS JOIN LATERAL (
    SELECT ROUND(ABS(COALESCE(
      NULLIF(finance_item.frozen_source_amount, 0),
      NULLIF(finance_reservation.settled_source_amount_ex_vat, 0),
      NULLIF(finance_item.amount_ex_vat, 0),
      NULLIF(finance_item.amount_inc_vat, 0)
    )), 2)::numeric AS source_amount_ex_vat
  ) AS finance_source_amount
  WHERE COALESCE(finance_item.is_voided, false) = false
    AND UPPER(BTRIM(COALESCE(finance_item.item_type, ''))) IN (
      'OVERPAYMENT_RECOVERY',
      'UNDERPAYMENT_PAYMENT'
    )
    AND finance_item.frozen_component_key_type IS NOT NULL
    AND BTRIM(finance_item.frozen_component_key_type) <> ''
    AND finance_item.frozen_component_key_value IS NOT NULL
    AND BTRIM(finance_item.frozen_component_key_value) <> ''
    AND UPPER(BTRIM(finance_item.frozen_component_key_type)) IN (
      'TS_DAY',
      'TS_TOTAL',
      'ADDITIONAL_CODE',
      'ADJUSTMENT_CODE',
      'EXPENSE_CODE'
    )
    AND NOT (
      UPPER(BTRIM(finance_item.frozen_component_key_type)) = 'TS_DAY'
      AND finance_item.frozen_component_key_value !~ '^\d{4}-\d{2}-\d{2}$'
    )
    AND finance_source_amount.source_amount_ex_vat IS NOT NULL
    AND finance_source_amount.source_amount_ex_vat > 0
    AND (
      UPPER(BTRIM(COALESCE(finance_candidate.settlement_status, ''))) = 'SETTLED'
      OR finance_candidate.settled_at_utc IS NOT NULL
      OR UPPER(BTRIM(COALESCE(finance_transfer.status, ''))) = 'COMPLETED'
      OR finance_transfer.completed_at_utc IS NOT NULL
      OR COALESCE(finance_reservation.has_settled_reservation, false) = true
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS applied_finance_correction
      WHERE applied_finance_correction.pay_batch_item_id = finance_item.id
        AND applied_finance_correction.status = 'APPLIED'
        AND applied_finance_correction.correction_item_kind IN (
          'PRE_BANK_CANCEL',
          'NO_MONEY_UNWIND',
          'SETTLED_REVERSAL'
        )
    )
),
all_settled_components_by_item_key AS (
  SELECT
    active_components_by_item_key.pay_batch_item_id,
    active_components_by_item_key.timesheet_id,
    active_components_by_item_key.key_type,
    active_components_by_item_key.key_value,
    active_components_by_item_key.amount_ex_vat,
    active_components_by_item_key.amount_inc_vat
  FROM active_components_by_item_key

  UNION ALL

  SELECT
    settled_finance_movement_components.pay_batch_item_id,
    settled_finance_movement_components.timesheet_id,
    settled_finance_movement_components.key_type,
    settled_finance_movement_components.key_value,
    settled_finance_movement_components.amount_ex_vat,
    settled_finance_movement_components.amount_inc_vat
  FROM settled_finance_movement_components
),
active_component_totals AS (
  SELECT
    all_settled_components_by_item_key.timesheet_id,
    all_settled_components_by_item_key.key_type,
    all_settled_components_by_item_key.key_value,
    ROUND(COALESCE(SUM(COALESCE(all_settled_components_by_item_key.amount_ex_vat, 0)), 0), 2)::numeric AS amount_ex_vat,
    ROUND(COALESCE(SUM(COALESCE(all_settled_components_by_item_key.amount_inc_vat, 0)), 0), 2)::numeric AS amount_inc_vat
  FROM all_settled_components_by_item_key
  GROUP BY
    all_settled_components_by_item_key.timesheet_id,
    all_settled_components_by_item_key.key_type,
    all_settled_components_by_item_key.key_value
)
SELECT
  active_component_totals.timesheet_id,
  active_component_totals.key_type,
  active_component_totals.key_value,
  active_component_totals.amount_ex_vat,
  active_component_totals.amount_inc_vat
FROM active_component_totals
WHERE active_component_totals.timesheet_id IS NOT NULL
  AND active_component_totals.key_type IS NOT NULL
  AND active_component_totals.key_value IS NOT NULL
  AND (
    ROUND(COALESCE(active_component_totals.amount_ex_vat, 0), 2) <> 0
    OR ROUND(COALESCE(active_component_totals.amount_inc_vat, 0), 2) <> 0
  )
ORDER BY
  active_component_totals.timesheet_id,
  active_component_totals.key_type,
  active_component_totals.key_value;
$function$;

-- public.pay_workbench_contract_client_dirty_fanout_chunk from supabase/repeatable/26092026_0202_banking_pay_stage2_source_authorisation_v1.sql; definition SHA-256 6023e0bc10fb3a6bfd71d6732bc7b1cb0da4e41aa0d84a8b8f1a27a4c3c5f54c.
CREATE OR REPLACE FUNCTION public.pay_workbench_contract_client_dirty_fanout_chunk(p_job_id uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  -- v5.2: the former function-level configuration clause that emptied the custom setting
  -- cloudtms.banking_pay_inherited_scope_generation is replaced by an explicit save / reset /
  -- restore of the same transaction-local setting, because a non-superuser release owner cannot
  -- CREATE a function whose configuration names an unregistered custom parameter (PostgreSQL 15+,
  -- "permission denied to set parameter"). Behaviour is unchanged: the body starts
  -- with the setting empty, and every normal return restores the caller's value so the
  -- inherited scope generation never leaks past this call; an error unwinds the setting
  -- through the enclosing (sub)transaction abort exactly as it did with the SET clause.
  v_saved_inherited_scope_generation text :=
    pg_catalog.current_setting('cloudtms.banking_pay_inherited_scope_generation', true);
  v_now timestamptz := now();
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_job_row public.banking_pay_workbench_jobs%ROWTYPE;
  v_payload_json jsonb := '{}'::jsonb;
  v_cursor_json jsonb := '{}'::jsonb;
  v_scope_kind text := '';
  v_scope_id_text text := NULL::text;
  v_scope_id uuid := NULL::uuid;
  v_specific_scope_id_text text := NULL::text;
  v_specific_scope_id uuid := NULL::uuid;
  v_payload_candidate_id_text text := NULL::text;
  v_payload_candidate_id uuid := NULL::uuid;
  v_payload_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_payload_candidate_value jsonb := NULL::jsonb;
  v_payload_candidate_value_text text := NULL::text;
  v_payload_candidate_index integer := 0;
  v_cursor_candidate_id_text text := NULL::text;
  v_cursor_candidate_id uuid := NULL::uuid;
  v_reason text := NULL::text;
  v_trigger_table text := NULL::text;
  v_trigger_op text := NULL::text;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_ids_json jsonb := '[]'::jsonb;
  v_candidate_count integer := 0;
  v_has_more boolean := false;
  v_last_candidate_id uuid := NULL::uuid;
  v_next_cursor_json jsonb := NULL::jsonb;
  v_affected_scope_count integer := 0;
  v_affected_session_count integer := 0;
  v_jobs_queued_or_reused integer := 0;
  v_source_rows_marked_dirty_count integer := 0;
  v_gate_candidate_id uuid := NULL::uuid;
  v_gate_result jsonb := '{}'::jsonb;
  v_gate_allowed_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_gate_blocked boolean := false;
  v_gate_blocked_candidate_id uuid := NULL::uuid;
  v_gate_last_allowed_candidate_id uuid := NULL::uuid;
  v_gate_allowed_count integer := 0;
  v_invalidation_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_invalidation_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_scope_change_tx_token uuid := NULL::uuid;
  v_scope_invalidation_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM pg_catalog.set_config('cloudtms.banking_pay_inherited_scope_generation', '', true);
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_ID_REQUIRED'
            )::text;
  END IF;

  SELECT fanout_job.*
  INTO v_job_row
  FROM public.banking_pay_workbench_jobs AS fanout_job
  WHERE fanout_job.id = p_job_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_FOUND',
              'job_id', p_job_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_job_row.job_type, ''))) <> 'CONTRACT_CLIENT_DIRTY_FANOUT' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_TYPE_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_TYPE_INVALID',
              'job_id', v_job_row.id::text,
              'job_type', v_job_row.job_type
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_job_row.status, ''))) <> 'RUNNING' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_RUNNING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_RUNNING',
              'job_id', v_job_row.id::text,
              'status', v_job_row.status
            )::text;
  END IF;

  IF v_job_row.scope_change_generation IS NOT NULL THEN
    PERFORM set_config(
      'cloudtms.banking_pay_inherited_scope_generation',
      v_job_row.scope_change_generation::text,
      true
    );
  END IF;

  v_payload_json := CASE
    WHEN jsonb_typeof(COALESCE(v_job_row.payload_json, '{}'::jsonb)) = 'object'
      THEN COALESCE(v_job_row.payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_cursor_json := CASE
    WHEN p_cursor_json IS NOT NULL
         AND jsonb_typeof(p_cursor_json) = 'object'
      THEN p_cursor_json
    WHEN jsonb_typeof(v_payload_json->'cursor_json') = 'object'
      THEN v_payload_json->'cursor_json'
    WHEN jsonb_typeof(v_payload_json->'cursor') = 'object'
      THEN v_payload_json->'cursor'
    ELSE '{}'::jsonb
  END;

  v_scope_kind := UPPER(BTRIM(COALESCE(v_payload_json->>'scope_kind', '')));

  IF v_scope_kind NOT IN ('CONTRACT', 'CLIENT', 'UMBRELLA') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_KIND_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_KIND_INVALID',
              'job_id', v_job_row.id::text,
              'scope_kind', v_scope_kind
            )::text;
  END IF;

  v_scope_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_payload_json->>'scope_id', '')), ''),
    CASE
      WHEN v_scope_kind = 'CONTRACT'
        THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'contract_id', '')), '')
      WHEN v_scope_kind = 'CLIENT'
        THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'client_id', '')), '')
      WHEN v_scope_kind = 'UMBRELLA'
        THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'umbrella_id', '')), '')
      ELSE NULL::text
    END
  );

  IF COALESCE(v_scope_id_text, '')
     !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_ID_INVALID',
              'job_id', v_job_row.id::text,
              'scope_kind', v_scope_kind,
              'scope_id', v_scope_id_text
            )::text;
  END IF;

  v_scope_id := v_scope_id_text::uuid;

  v_specific_scope_id_text := CASE
    WHEN v_scope_kind = 'CONTRACT'
      THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'contract_id', '')), '')
    WHEN v_scope_kind = 'CLIENT'
      THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'client_id', '')), '')
    WHEN v_scope_kind = 'UMBRELLA'
      THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'umbrella_id', '')), '')
    ELSE NULL::text
  END;

  IF v_specific_scope_id_text IS NOT NULL THEN
    IF v_specific_scope_id_text
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SPECIFIC_SCOPE_ID_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SPECIFIC_SCOPE_ID_INVALID',
                'job_id', v_job_row.id::text,
                'scope_kind', v_scope_kind,
                'scope_id', v_scope_id::text,
                'specific_scope_id', v_specific_scope_id_text
              )::text;
    END IF;

    v_specific_scope_id := v_specific_scope_id_text::uuid;

    IF v_specific_scope_id IS DISTINCT FROM v_scope_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_PAYLOAD_CONFLICT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_PAYLOAD_CONFLICT',
                'job_id', v_job_row.id::text,
                'scope_kind', v_scope_kind,
                'scope_id', v_scope_id::text,
                'specific_scope_id', v_specific_scope_id::text
              )::text;
    END IF;
  END IF;

  IF v_payload_json ? 'candidate_ids' THEN
    IF jsonb_typeof(v_payload_json->'candidate_ids') IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID',
                'job_id', v_job_row.id::text,
                'candidate_ids', v_payload_json->'candidate_ids'
              )::text;
    END IF;

    v_payload_candidate_index := 0;

    FOR v_payload_candidate_value IN
      SELECT payload_candidate.value
      FROM jsonb_array_elements(v_payload_json->'candidate_ids') AS payload_candidate(value)
    LOOP
      v_payload_candidate_index := v_payload_candidate_index + 1;
      v_payload_candidate_value_text := CASE
        WHEN jsonb_typeof(v_payload_candidate_value) = 'string'
          THEN NULLIF(BTRIM(v_payload_candidate_value #>> '{}'), '')
        ELSE NULL::text
      END;

      IF COALESCE(v_payload_candidate_value_text, '')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID',
                  'job_id', v_job_row.id::text,
                  'candidate_index', v_payload_candidate_index,
                  'candidate_value', v_payload_candidate_value
                )::text;
      END IF;

      v_payload_candidate_ids := array_append(
        v_payload_candidate_ids,
        v_payload_candidate_value_text::uuid
      );
    END LOOP;

    SELECT COALESCE(
      array_agg(DISTINCT payload_candidate.candidate_id ORDER BY payload_candidate.candidate_id),
      ARRAY[]::uuid[]
    )
    INTO v_payload_candidate_ids
    FROM unnest(v_payload_candidate_ids) AS payload_candidate(candidate_id);
  END IF;

  v_payload_candidate_id_text := NULLIF(
    BTRIM(COALESCE(v_payload_json->>'candidate_id', '')),
    ''
  );

  IF v_payload_candidate_id_text IS NOT NULL THEN
    IF v_payload_candidate_id_text
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_ID_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_ID_INVALID',
                'job_id', v_job_row.id::text,
                'candidate_id', v_payload_candidate_id_text
              )::text;
    END IF;

    v_payload_candidate_id := v_payload_candidate_id_text::uuid;
  END IF;

  v_cursor_candidate_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_cursor_json->>'last_candidate_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_cursor_json->>'after_candidate_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_cursor_json->>'candidate_id', '')), '')
  );

  IF v_cursor_candidate_id_text IS NOT NULL THEN
    IF v_cursor_candidate_id_text
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CURSOR_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CURSOR_INVALID',
                'job_id', v_job_row.id::text,
                'cursor_json', v_cursor_json
              )::text;
    END IF;

    v_cursor_candidate_id := v_cursor_candidate_id_text::uuid;
  END IF;

  v_reason := COALESCE(
    NULLIF(BTRIM(COALESCE(v_payload_json->>'reason', '')), ''),
    'DIRTY_FANOUT:' || v_scope_kind
  );
  v_trigger_table := NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_table', '')), '');
  v_trigger_op := NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_op', '')), '');

  WITH candidate_pool AS (
    SELECT historical_candidate.candidate_id
    FROM unnest(v_payload_candidate_ids) AS historical_candidate(candidate_id)
    WHERE historical_candidate.candidate_id IS NOT NULL

    UNION

    SELECT v_payload_candidate_id AS candidate_id
    WHERE v_payload_candidate_id IS NOT NULL

    UNION

    SELECT derived_payload_candidate.candidate_id
    FROM public._pay_workbench_candidate_serial_candidate_ids(v_job_row.candidate_id, v_payload_json) AS derived_payload_candidate(candidate_id)
    WHERE derived_payload_candidate.candidate_id IS NOT NULL

    UNION

    SELECT contract_scope.candidate_id
    FROM public.contracts AS contract_scope
    WHERE v_scope_kind = 'CONTRACT'
      AND contract_scope.id = v_scope_id
      AND contract_scope.candidate_id IS NOT NULL

    UNION

    SELECT client_contract.candidate_id
    FROM public.contracts AS client_contract
    WHERE v_scope_kind = 'CLIENT'
      AND client_contract.client_id = v_scope_id
      AND client_contract.candidate_id IS NOT NULL

    UNION

    SELECT umbrella_candidate.id
    FROM public.candidates AS umbrella_candidate
    WHERE v_scope_kind = 'UMBRELLA'
      AND umbrella_candidate.umbrella_id = v_scope_id
  ),
  ordered_candidates AS (
    SELECT candidate_pool.candidate_id,
           ROW_NUMBER() OVER (ORDER BY candidate_pool.candidate_id) AS candidate_ordinal
    FROM candidate_pool
    WHERE candidate_pool.candidate_id IS NOT NULL
      AND (
        v_cursor_candidate_id IS NULL
        OR candidate_pool.candidate_id > v_cursor_candidate_id
      )
    ORDER BY candidate_pool.candidate_id
    LIMIT (v_limit + 1)
  ),
  selected_candidates AS (
    SELECT ordered_candidates.candidate_id,
           ordered_candidates.candidate_ordinal
    FROM ordered_candidates
    WHERE ordered_candidates.candidate_ordinal <= v_limit
  )
  SELECT
    COALESCE(
      array_agg(
        selected_candidates.candidate_id
        ORDER BY selected_candidates.candidate_id
      ),
      ARRAY[]::uuid[]
    ),
    COALESCE(COUNT(*)::integer, 0),
    EXISTS (
      SELECT 1
      FROM ordered_candidates AS extra_candidate
      WHERE extra_candidate.candidate_ordinal > v_limit
    ),
    (
      SELECT last_selected.candidate_id
      FROM selected_candidates AS last_selected
      ORDER BY last_selected.candidate_id DESC
      LIMIT 1
    )
  INTO
    v_candidate_ids,
    v_candidate_count,
    v_has_more,
    v_last_candidate_id
  FROM selected_candidates;

  v_candidate_ids_json := COALESCE(to_jsonb(v_candidate_ids), '[]'::jsonb);

  IF v_has_more AND v_last_candidate_id IS NOT NULL THEN
    v_next_cursor_json := jsonb_build_object(
      'last_candidate_id', v_last_candidate_id::text,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id::text
    );
  ELSE
    v_next_cursor_json := NULL::jsonb;
  END IF;

  IF COALESCE(v_candidate_count, 0) = 0 THEN
    PERFORM pg_catalog.set_config('cloudtms.banking_pay_inherited_scope_generation', COALESCE(v_saved_inherited_scope_generation, ''), true);
    RETURN jsonb_build_object(
      'ok', true,
      'job_id', v_job_row.id::text,
      'job_type', v_job_row.job_type,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id::text,
      'reason', v_reason,
      'limit', v_limit,
      'cursor_json', v_cursor_json,
      'candidate_ids', '[]'::jsonb,
      'candidate_count', 0,
      'processed_count', 0,
      'affected_scope_count', 0,
      'affected_session_count', 0,
      'enqueued_count', 0,
      'has_more', false,
      'next_cursor', NULL::jsonb,
      'next_cursor_json', NULL::jsonb,
      'candidate_line_calculation_performed', false
    );
  END IF;

  v_gate_allowed_candidate_ids := ARRAY[]::uuid[];
  v_gate_blocked := false;
  v_gate_blocked_candidate_id := NULL::uuid;
  v_gate_last_allowed_candidate_id := NULL::uuid;

  FOREACH v_gate_candidate_id IN ARRAY v_candidate_ids
  LOOP
    v_gate_result := public._pay_workbench_candidate_serial_try_gate(
      p_job_id => v_job_row.id,
      p_candidate_id => v_gate_candidate_id,
      p_job_type => v_job_row.job_type,
      p_payload_json => v_payload_json || jsonb_build_object(
        'candidate_id', v_gate_candidate_id::text,
        'candidate_serial_candidate_id', v_gate_candidate_id::text,
        'candidate_serial_key', public._pay_workbench_candidate_serial_key(v_gate_candidate_id),
        'fanout_scope_kind', v_scope_kind,
        'fanout_scope_id', v_scope_id::text,
        'cursor_json', v_cursor_json
      ),
      p_reason => 'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_GATE'
    );

    IF lower(BTRIM(COALESCE(v_gate_result->>'blocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR lower(BTRIM(COALESCE(v_gate_result->>'allowed', 'true'))) IN ('false', 'f', '0', 'no', 'n', 'off') THEN
      v_gate_blocked := true;
      v_gate_blocked_candidate_id := v_gate_candidate_id;
      EXIT;
    END IF;

    v_gate_allowed_candidate_ids := array_append(v_gate_allowed_candidate_ids, v_gate_candidate_id);
    v_gate_last_allowed_candidate_id := v_gate_candidate_id;
  END LOOP;

  IF v_gate_blocked IS TRUE THEN
    SELECT COALESCE(array_agg(DISTINCT allowed_candidate.candidate_id ORDER BY allowed_candidate.candidate_id), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM unnest(COALESCE(v_gate_allowed_candidate_ids, ARRAY[]::uuid[])) AS allowed_candidate(candidate_id)
    WHERE allowed_candidate.candidate_id IS NOT NULL;

    v_candidate_count := COALESCE(array_length(v_candidate_ids, 1), 0);
    v_candidate_ids_json := COALESCE(to_jsonb(v_candidate_ids), '[]'::jsonb);
    v_has_more := true;
    v_last_candidate_id := v_gate_last_allowed_candidate_id;

    v_next_cursor_json := jsonb_strip_nulls(
      CASE
        WHEN v_gate_last_allowed_candidate_id IS NOT NULL THEN
          jsonb_build_object(
            'last_candidate_id', v_gate_last_allowed_candidate_id::text,
            'scope_kind', v_scope_kind,
            'scope_id', v_scope_id::text
          )
        ELSE
          COALESCE(v_cursor_json, '{}'::jsonb)
          || jsonb_build_object(
            'scope_kind', v_scope_kind,
            'scope_id', v_scope_id::text
          )
      END
      || jsonb_build_object(
        'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
        'candidate_serial_blocked_at_utc', v_now::text,
        'candidate_serial_wait_reason', COALESCE(v_gate_result->>'reason', 'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED'),
        'candidate_serial_delayed', true
      )
    );

    PERFORM public._pay_workbench_candidate_serial_audit(
      'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED',
      v_job_row.id,
      v_gate_blocked_candidate_id,
      COALESCE(v_gate_result, '{}'::jsonb) || jsonb_build_object(
        'job_type', v_job_row.job_type,
        'scope_kind', v_scope_kind,
        'scope_id', v_scope_id::text,
        'cursor_json', v_cursor_json,
        'next_cursor_json', v_next_cursor_json,
        'allowed_before_block_count', COALESCE(v_candidate_count, 0),
        'blocked_candidate_preserved', true,
        'candidate_mutation_skipped_for_blocked_candidate', true
      ),
      'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED',
      NULL::uuid
    );

    IF COALESCE(v_candidate_count, 0) = 0 THEN
      UPDATE public.banking_pay_workbench_jobs AS delayed_job
      SET payload_json = public._pay_workbench_dirty_payload_merge(
            COALESCE(delayed_job.payload_json, '{}'::jsonb),
            jsonb_build_object(
              'candidate_serial_delayed', true,
              'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
              'candidate_serial_wait_reason', COALESCE(v_gate_result->>'reason', 'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED'),
              'next_cursor_json', v_next_cursor_json,
              'cursor_json', v_next_cursor_json,
              'has_more', true,
              'rerun_required', true,
              'candidate_mutation_skipped_for_blocked_candidate', true,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          ),
          updated_at_utc = v_now
      WHERE delayed_job.id = v_job_row.id;

      PERFORM pg_catalog.set_config('cloudtms.banking_pay_inherited_scope_generation', COALESCE(v_saved_inherited_scope_generation, ''), true);
      RETURN jsonb_build_object(
        'ok', true,
        'job_id', v_job_row.id::text,
        'job_type', v_job_row.job_type,
        'scope_kind', v_scope_kind,
        'scope_id', v_scope_id::text,
        'reason', v_reason,
        'limit', v_limit,
        'cursor_json', v_cursor_json,
        'candidate_ids', '[]'::jsonb,
        'candidate_count', 0,
        'processed_count', 0,
        'affected_scope_count', 0,
        'affected_session_count', 0,
        'enqueued_count', 0,
        'has_more', true,
        'next_cursor', v_next_cursor_json,
        'next_cursor_json', v_next_cursor_json,
        'candidate_serial_delayed', true,
        'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
        'candidate_mutation_skipped_for_blocked_candidate', true,
        'candidate_line_calculation_performed', false
      );
    END IF;
  END IF;

  CREATE TEMPORARY TABLE IF NOT EXISTS pay_workbench_dirty_fanout_candidates (
    candidate_id uuid PRIMARY KEY,
    source_change_seq bigint NOT NULL DEFAULT 0
  ) ON COMMIT DROP;

  CREATE TEMPORARY TABLE IF NOT EXISTS pay_workbench_dirty_fanout_affected_scope (
    session_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    PRIMARY KEY (session_id, candidate_id)
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.pay_workbench_dirty_fanout_candidates;
  TRUNCATE TABLE pg_temp.pay_workbench_dirty_fanout_affected_scope;

  INSERT INTO pg_temp.pay_workbench_dirty_fanout_candidates (
    candidate_id,
    source_change_seq
  )
  SELECT page_candidate.candidate_id,
         0::bigint
  FROM unnest(v_candidate_ids) AS page_candidate(candidate_id)
  ON CONFLICT (candidate_id) DO NOTHING;

  WITH exact_pairs AS (
    SELECT active_state.candidate_id,active_state.timesheet_id
    FROM private.banking_pay_workbench_timesheet_scope_state active_state
    JOIN pg_temp.pay_workbench_dirty_fanout_candidates fanout_candidate
      ON fanout_candidate.candidate_id=active_state.candidate_id
    WHERE active_state.economic_state IN ('DIRTY','LIVE')
    UNION
    SELECT source_owner.candidate_id,source_owner.timesheet_id
    FROM public.banking_pay_workbench_candidate_source_lines source_owner
    JOIN pg_temp.pay_workbench_dirty_fanout_candidates fanout_candidate
      ON fanout_candidate.candidate_id=source_owner.candidate_id
    WHERE source_owner.status IN ('CURRENT','DIRTY') AND source_owner.timesheet_id IS NOT NULL
  ), complete_pairs AS (
    SELECT candidate_id,timesheet_id FROM exact_pairs
    UNION ALL
    SELECT fanout_candidate.candidate_id,NULL::uuid
    FROM pg_temp.pay_workbench_dirty_fanout_candidates fanout_candidate
    WHERE NOT EXISTS(SELECT 1 FROM exact_pairs WHERE exact_pairs.candidate_id=fanout_candidate.candidate_id)
  )
  SELECT array_agg(candidate_id ORDER BY candidate_id,timesheet_id NULLS FIRST),
         array_agg(timesheet_id ORDER BY candidate_id,timesheet_id NULLS FIRST)
  INTO v_invalidation_candidate_ids,v_invalidation_timesheet_ids
  FROM complete_pairs;

  IF COALESCE(v_job_row.payload_json->>'scope_change_tx_token','')
     ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_scope_change_tx_token:=(v_job_row.payload_json->>'scope_change_tx_token')::uuid;
  END IF;
  v_scope_invalidation_result:=private.pay_workbench_scope_invalidate_v1(
    COALESCE(v_invalidation_candidate_ids,ARRAY[]::uuid[]),
    COALESCE(v_invalidation_timesheet_ids,ARRAY[]::uuid[]),
    v_reason,v_scope_change_tx_token,
    COALESCE(v_job_row.payload_json,'{}'::jsonb)||jsonb_build_object(
      'skip_candidate_job_enqueue',true,'inherited_scope_generation',v_job_row.scope_change_generation)
  );

  WITH bumped_counters AS (
    INSERT INTO public.app_change_counters AS candidate_counter (
      entity_key,
      seq,
      updated_at
    )
    SELECT
      'pay_candidate:' || fanout_candidate.candidate_id::text,
      1::bigint,
      v_now
    FROM pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
    ON CONFLICT (entity_key)
    DO UPDATE
    SET seq = candidate_counter.seq + 1,
        updated_at = v_now
    RETURNING candidate_counter.entity_key,
              candidate_counter.seq
  )
  UPDATE pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
  SET source_change_seq = bumped_counter.seq
  FROM bumped_counters AS bumped_counter
  WHERE bumped_counter.entity_key = 'pay_candidate:' || fanout_candidate.candidate_id::text;

  WITH candidate_open_scope AS (
    SELECT
      scope_row.session_id,
      scope_row.candidate_id,
      open_session.actor_user_id,
      open_session.pay_date,
      MAX(open_session.pay_date) OVER (
        PARTITION BY open_session.actor_user_id
      ) AS latest_actor_open_pay_date
    FROM public.banking_pay_workbench_session_scope AS scope_row
    JOIN public.banking_pay_workbench_sessions AS open_session
      ON open_session.id = scope_row.session_id
    JOIN pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
      ON fanout_candidate.candidate_id = scope_row.candidate_id
    WHERE open_session.status = 'OPEN'
      AND open_session.discarded_at_utc IS NULL
  ),
  affected_scope AS (
    UPDATE public.banking_pay_workbench_session_scope AS scope_update
    SET status = 'SOURCE_BUILD_PENDING',
        dirty = true,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    FROM candidate_open_scope AS target_scope
    WHERE target_scope.session_id = scope_update.session_id
      AND target_scope.candidate_id = scope_update.candidate_id
      AND target_scope.pay_date = target_scope.latest_actor_open_pay_date
    RETURNING scope_update.session_id,
              scope_update.candidate_id
  )
  INSERT INTO pg_temp.pay_workbench_dirty_fanout_affected_scope (
    session_id,
    candidate_id
  )
  SELECT affected_scope.session_id,
         affected_scope.candidate_id
  FROM affected_scope
  ON CONFLICT (session_id, candidate_id) DO NOTHING;

  GET DIAGNOSTICS v_affected_scope_count = ROW_COUNT;

  WITH affected_session_summary AS (
    SELECT
      affected_scope.session_id,
      COUNT(*)::integer AS affected_candidate_count,
      (array_agg(
        affected_scope.candidate_id
        ORDER BY affected_scope.candidate_id DESC
      ))[1] AS last_candidate_id
    FROM pg_temp.pay_workbench_dirty_fanout_affected_scope AS affected_scope
    GROUP BY affected_scope.session_id
  ),
  updated_sessions AS (
    UPDATE public.banking_pay_workbench_sessions AS session_update
    SET progress_state = 'DIRTY',
        scope_pending_count = GREATEST(
          COALESCE(session_update.scope_pending_count, 0),
          1
        ),
        candidate_sample_rows_json = jsonb_build_array(
          jsonb_build_object(
            'candidate_id', affected_summary.last_candidate_id::text,
            'status', 'SOURCE_BUILD_PENDING',
            'reason', v_reason
          )
        ),
        progress_json = jsonb_strip_nulls(
          COALESCE(session_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'last_dirty_candidate_id', affected_summary.last_candidate_id::text,
            'last_dirty_reason', v_reason,
            'last_dirty_at_utc', v_now::text,
            'last_dirty_fanout_job_id', v_job_row.id::text,
            'last_dirty_fanout_scope_kind', v_scope_kind,
            'last_dirty_fanout_scope_id', v_scope_id::text,
            'last_dirty_fanout_candidate_count', affected_summary.affected_candidate_count
          )
        ),
        progress_counter_version = COALESCE(session_update.progress_counter_version, 0)
          + affected_summary.affected_candidate_count,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    FROM affected_session_summary AS affected_summary
    WHERE session_update.id = affected_summary.session_id
    RETURNING session_update.id
  )
  SELECT COUNT(*)::integer
  INTO v_affected_session_count
  FROM updated_sessions;

  WITH dirtied_source_rows AS (
    UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line
    SET status = 'DIRTY',
        source_row_json = jsonb_strip_nulls(
          COALESCE(source_line.source_row_json, '{}'::jsonb)
          || jsonb_build_object(
            'dirty_reason', v_reason,
            'dirty_fanout_job_id', v_job_row.id::text,
            'dirty_fanout_scope_kind', v_scope_kind,
            'dirty_fanout_scope_id', v_scope_id::text,
            'dirty_trigger_table', v_trigger_table,
            'dirty_trigger_operation', v_trigger_op,
            'dirty_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    FROM pg_temp.pay_workbench_dirty_fanout_affected_scope AS affected_scope
    WHERE source_line.session_id = affected_scope.session_id
      AND source_line.candidate_id = affected_scope.candidate_id
      AND source_line.status = 'CURRENT'
    RETURNING source_line.id
  )
  SELECT COUNT(*)::integer
  INTO v_source_rows_marked_dirty_count
  FROM dirtied_source_rows;

  WITH upserted_jobs AS (
    INSERT INTO public.banking_pay_workbench_jobs AS refresh_job (
      job_type,
      status,
      priority,
      run_at_utc,
      attempt_count,
      max_attempts,
      dedupe_key,
      snapshot_run_id,
      session_id,
      candidate_id,
      payload_json,
      economic_build_id,
      private_stage,
      private_cursor_kind,
      private_cursor_json,
      private_stage_version,
      created_at_utc,
      updated_at_utc,
      started_at_utc,
      completed_at_utc,
      failed_at_utc,
      last_error_json
    )
    SELECT
      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'QUEUED',
      44,
      v_now,
      0,
      8,
      'WORKBENCH_CANDIDATE_SOURCE_BUILD:'
        || open_session.id::text
        || ':'
        || affected_scope.candidate_id::text
        || ':v'
        || COALESCE(open_session.version, 0)::text
        || ':s'
        || COALESCE(fanout_candidate.source_change_seq, 0)::text
        || ':snapshot:'
        || open_session.source_snapshot_run_id::text
        || ':signature:'
        || md5(COALESCE(open_session.session_signature, ''))
        || ':source_build:'
        || source_build_identity.source_build_run_id::text
        || ':cursor:START',
      open_session.source_snapshot_run_id,
      open_session.id,
      affected_scope.candidate_id,
      jsonb_build_object(
        'trigger_table', v_trigger_table,
        'trigger_operation', v_trigger_op,
        'trigger_op', v_trigger_op,
        'scope_kind', 'CANDIDATE',
        'scope_id', affected_scope.candidate_id::text,
        'candidate_id', affected_scope.candidate_id::text,
        'reason', v_reason,
        'source_change_seq', fanout_candidate.source_change_seq,
        'source_change_sequence', fanout_candidate.source_change_seq,
        'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
        'candidate_serial_key', public._pay_workbench_candidate_serial_key(affected_scope.candidate_id),
        'candidate_serial_candidate_id', affected_scope.candidate_id::text,
        'candidate_serial_active_chain_id', COALESCE(NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'candidate_serial_active_chain_id', '')), ''), v_job_row.id::text),
        'candidate_serial_source_job_id', v_job_row.id::text,
        'candidate_serial_reason', 'CANDIDATE_SERIAL_FANOUT_SOURCE_BUILD_QUEUED'
      )
      || jsonb_build_object(
        'targeted_timesheet_ids', '[]'::jsonb,
        'linked_timesheet_ids', '[]'::jsonb,
        'session_id', open_session.id::text,
        'source_session_id', open_session.id::text,
        'session_version', COALESCE(open_session.version, 0),
        'session_signature', open_session.session_signature,
        'snapshot_run_id', open_session.source_snapshot_run_id::text,
        'source_snapshot_run_id', open_session.source_snapshot_run_id::text,
        'source_build_run_id', source_build_identity.source_build_run_id::text,
        'source_fanout_job_id', v_job_row.id::text
      )
      || jsonb_build_object(
        'fanout_scope_kind', v_scope_kind,
        'fanout_scope_id', v_scope_id::text,
        'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'source_build_required', true,
        'line_work_required', true,
        'line_work_only', false,
        'source_build_action', 'BUILD_SOURCE',
        'line_work_action', 'SOURCE_BUILD',
        'pay_channel_scope', COALESCE(NULLIF(UPPER(BTRIM(COALESCE(open_session.filters_json->>'pay_channel_scope', open_session.filters_json#>>'{filters,pay_channel_scope}', ''))), ''), 'ALL'),
        'limit', v_limit,
        'source_build_limit', v_limit,
        'source_rows_marked_dirty_count', COALESCE(v_source_rows_marked_dirty_count, 0)
      ),
      NULL::uuid,
      'BUILD_INITIALISE',
      'BUILD_INITIALISE',
      '{}'::jsonb,
      1,
      v_now,
      v_now,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::jsonb
    FROM pg_temp.pay_workbench_dirty_fanout_affected_scope AS affected_scope
    JOIN public.banking_pay_workbench_sessions AS open_session
      ON open_session.id = affected_scope.session_id
     AND open_session.status = 'OPEN'
     AND open_session.discarded_at_utc IS NULL
    JOIN pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
      ON fanout_candidate.candidate_id = affected_scope.candidate_id
    CROSS JOIN LATERAL (
      SELECT md5(concat_ws(':',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        open_session.source_snapshot_run_id::text,
        open_session.id::text,
        affected_scope.candidate_id::text,
        COALESCE(open_session.version, 0)::text,
        COALESCE(fanout_candidate.source_change_seq, 0)::text,
        'CANDIDATE_FULL_LIVE',
        v_scope_kind,
        v_scope_id::text,
        v_reason
      )) AS source_build_hash
    ) AS source_build_hash
    CROSS JOIN LATERAL (
      SELECT (
        substr(source_build_hash.source_build_hash, 1, 8) || '-' ||
        substr(source_build_hash.source_build_hash, 9, 4) || '-' ||
        substr(source_build_hash.source_build_hash, 13, 4) || '-' ||
        substr(source_build_hash.source_build_hash, 17, 4) || '-' ||
        substr(source_build_hash.source_build_hash, 21, 12)
      )::uuid AS source_build_run_id
    ) AS source_build_identity
    ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
    DO UPDATE
    SET priority = LEAST(refresh_job.priority, EXCLUDED.priority),
        run_at_utc = LEAST(refresh_job.run_at_utc, EXCLUDED.run_at_utc),
        payload_json = public._pay_workbench_merge_targeted_scope_payload(
          COALESCE(refresh_job.payload_json, '{}'::jsonb),
          COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
        ),
        updated_at_utc = v_now
    RETURNING refresh_job.id
  )
  SELECT COUNT(*)::integer
  INTO v_jobs_queued_or_reused
  FROM upserted_jobs;

  PERFORM pg_catalog.set_config('cloudtms.banking_pay_inherited_scope_generation', COALESCE(v_saved_inherited_scope_generation, ''), true);
  RETURN jsonb_build_object(
      'ok', true,
      'job_id', v_job_row.id::text,
      'job_type', v_job_row.job_type,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id::text,
      'reason', v_reason,
      'trigger_table', v_trigger_table,
      'trigger_op', v_trigger_op,
      'limit', v_limit,
      'cursor_json', v_cursor_json,
      'candidate_ids', v_candidate_ids_json,
      'candidate_count', COALESCE(v_candidate_count, 0),
      'processed_count', COALESCE(v_candidate_count, 0),
      'affected_scope_count', COALESCE(v_affected_scope_count, 0),
      'affected_session_count', COALESCE(v_affected_session_count, 0),
      'enqueued_count', COALESCE(v_jobs_queued_or_reused, 0),
      'jobs_queued_or_reused', COALESCE(v_jobs_queued_or_reused, 0),
      'source_rows_marked_dirty_count', COALESCE(v_source_rows_marked_dirty_count, 0),
      'first_stage_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    )
    || jsonb_build_object(
      'has_more', COALESCE(v_has_more, false),
      'candidate_serial_delayed', COALESCE(v_gate_blocked, false),
      'candidate_serial_blocked_candidate_id', CASE WHEN v_gate_blocked_candidate_id IS NULL THEN NULL::text ELSE v_gate_blocked_candidate_id::text END,
      'next_cursor', v_next_cursor_json,
      'next_cursor_json', v_next_cursor_json,
      'last_candidate_id', CASE
        WHEN v_last_candidate_id IS NULL THEN NULL::text
        ELSE v_last_candidate_id::text
      END,
      'candidate_line_calculation_performed', false,
      'session_created', false,
      'rpc_fanout_performed', false
    );
END;
$function$;

-- public.pay_workbench_scope_change_tx_token_v1 from supabase/repeatable/26092026_0202_banking_pay_stage2_source_authorisation_v1.sql; definition SHA-256 7a1ba1c6b3f066eaaae46ee8977298f1873c9b9ee723d3383645448c5cb94ea6.
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_change_tx_token_v1()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_token uuid;
  v_state text;
BEGIN
  IF LOWER(BTRIM(COALESCE(current_setting('cloudtms.scope_generation_finalising', true), 'false')))
       IN ('true', 't', '1', 'yes', 'y', 'on') THEN
    RETURN NULL::uuid;
  END IF;

  BEGIN
    v_token := NULLIF(BTRIM(COALESCE(
      current_setting('cloudtms.banking_pay_scope_tx_token', true),
      ''
    )), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_TRANSACTION_TOKEN_INVALID'
      USING ERRCODE = 'P0001';
  END;

  -- This finalizer seals transaction-wide collected work. Under an IMMEDIATE
  -- entry mode its token INSERT must not finalize before counters/jobs exist.
  -- Defer this internal finalizer only, preserving every other constraint mode.
  SET CONSTRAINTS public.trg_pay_workbench_scope_change_finalize_v1 DEFERRED;

  IF v_token IS NULL THEN
    v_token := gen_random_uuid();
    PERFORM set_config('cloudtms.banking_pay_scope_tx_token', v_token::text, true);
    INSERT INTO public.banking_pay_scope_change_transactions(
      tx_token, state, created_at_utc
    ) VALUES (
      v_token, 'PENDING', clock_timestamp()
    );
    RETURN v_token;
  END IF;

  SELECT scope_tx.state
  INTO v_state
  FROM public.banking_pay_scope_change_transactions AS scope_tx
  WHERE scope_tx.tx_token = v_token;

  IF v_state IN ('FINALIZED', 'NOOP') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_GENERATION_FINALIZED_TOO_EARLY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SCOPE_GENERATION_FINALIZED_TOO_EARLY',
              'state', v_state
            )::text;
  END IF;

  INSERT INTO public.banking_pay_scope_change_transactions(
    tx_token, state, created_at_utc
  ) VALUES (
    v_token, 'PENDING', clock_timestamp()
  ) ON CONFLICT (tx_token) DO NOTHING;

  RETURN v_token;
END;
$function$;

-- public.timesheet_authorise_generic_atomic from supabase/repeatable/26092026_0202_banking_pay_stage2_source_authorisation_v1.sql; definition SHA-256 bae8b7130c37253b30dc98d243927610a0ee1a2861dc31ac00c6988e0248311a.
CREATE OR REPLACE FUNCTION public.timesheet_authorise_generic_atomic(p_timesheet_id uuid, p_expected_timesheet_id uuid, p_actor_user_id uuid, p_now_utc timestamp with time zone DEFAULT now(), p_expected_row_signature text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamp with time zone := COALESCE(p_now_utc, now());
  v_requested_ts public.timesheets%ROWTYPE;
  v_current_ts public.timesheets%ROWTYPE;
  v_current_tsfin public.timesheets_financials%ROWTYPE;
  v_contract_week public.contract_weeks%ROWTYPE;
  v_prev_status public.ts_fin_processing_status_enum := NULL;
  v_new_status public.ts_fin_processing_status_enum := NULL;
  v_before_signature_json jsonb := '{}'::jsonb;
  v_after_signature_json jsonb := '{}'::jsonb;
  v_current_row_signature text := NULL;
  v_expected_row_signature text := NULL;
  v_after_row_signature text := NULL;
  v_has_segment_invoice_lock boolean := false;
  v_validation_status text := NULL;
  v_validation_pre_validated boolean := false;
  v_validation_ok boolean := false;
  v_contract_requires_hr boolean := false;
  v_client_requires_hr boolean := false;
  v_hr_validation_required_for_invoice boolean := false;
  v_must_hold_for_hr_validation boolean := false;
  v_prevalidated_fast_track boolean := false;
  v_force_ready_for_invoice boolean := false;
  v_error_state text := NULL;
  v_error_message text := NULL;
  v_diag_started_at timestamptz := clock_timestamp();
  v_temp_log_enabled boolean := false;
  v_advance_state_refresh_json jsonb := '{}'::jsonb;
  v_has_uncleared_advance_override boolean := false;
  v_duplicate_expense_review jsonb := '{}'::jsonb;
BEGIN

  if coalesce((public._ctms_import_correction_classify_v1(p_timesheet_id)
       ->> 'is_import_authoritative_correction')::boolean, false) then
    return jsonb_build_object(
      'ok', false,
      'error_code', 'IMPORT_CORRECTION_UNIT_REQUIRES_BULK_LIFECYCLE',
      'timesheet_id', p_timesheet_id,
      'required_rpc', case when 'AUTHORISE' = 'AUTHORISE'
        then 'timesheet_authorise_bulk_atomic' else 'timesheet_unauthorise_bulk_atomic' end
    );
  end if;
  PERFORM set_config('lock_timeout', '300ms', true);

  BEGIN
    SELECT COALESCE(sd.temp_log, false)
      INTO v_temp_log_enabled
    FROM public.settings_defaults AS sd
    ORDER BY sd.id
    LIMIT 1;
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_temp_log_enabled := false;
    WHEN OTHERS THEN
      v_temp_log_enabled := false;
  END;

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    p_timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'entry',
      'timesheet_id', p_timesheet_id,
      'expected_timesheet_id', p_expected_timesheet_id,
      'actor_user_id_present', p_actor_user_id IS NOT NULL,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  IF p_timesheet_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'INVALID_PAYLOAD', DETAIL = jsonb_build_object('field', 'p_timesheet_id')::text;
  END IF;
  IF p_expected_timesheet_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'INVALID_PAYLOAD', DETAIL = jsonb_build_object('field', 'p_expected_timesheet_id')::text;
  END IF;
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'INVALID_PAYLOAD', DETAIL = jsonb_build_object('field', 'p_actor_user_id')::text;
  END IF;

  SELECT ts.*
    INTO v_requested_ts
  FROM public.timesheets AS ts
  WHERE ts.timesheet_id = p_timesheet_id
  LIMIT 1
  FOR UPDATE;

  IF v_requested_ts.timesheet_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'TARGET_NOT_FOUND', DETAIL = jsonb_build_object('timesheet_id', p_timesheet_id)::text;
  END IF;

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_requested_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'requested_timesheet_resolved',
      'timesheet_id', v_requested_ts.timesheet_id,
      'is_current', COALESCE(v_requested_ts.is_current, false),
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  IF COALESCE(v_requested_ts.is_current, false) THEN
    v_current_ts := v_requested_ts;
  ELSE
    SELECT ts.*
      INTO v_current_ts
    FROM public.timesheets AS ts
    WHERE ts.booking_id = v_requested_ts.booking_id
      AND ts.is_current = true
    ORDER BY ts.version DESC NULLS LAST, ts.updated_at DESC NULLS LAST, ts.created_at DESC NULLS LAST, ts.timesheet_id DESC
    LIMIT 1
    FOR UPDATE;
    IF v_current_ts.timesheet_id IS NULL THEN
      v_current_ts := v_requested_ts;
    END IF;
  END IF;

  IF p_expected_timesheet_id IS DISTINCT FROM v_current_ts.timesheet_id THEN
    RAISE EXCEPTION USING MESSAGE = 'EXPECTED_TIMESHEET_MISMATCH', DETAIL = jsonb_build_object('expected_timesheet_id', p_expected_timesheet_id, 'current_timesheet_id', v_current_ts.timesheet_id)::text;
  END IF;

  v_duplicate_expense_review:=private._timesheet_duplicate_expense_review_v1(
    v_current_ts.timesheet_id
  );
  IF COALESCE((v_duplicate_expense_review->>'required')::boolean,false)
     AND COALESCE(current_setting('cloudtms.duplicate_expense_reviewed',true),'')<>'true' THEN
    RAISE EXCEPTION 'DUPLICATE_EXPENSE_REVIEW_REQUIRED'
      USING ERRCODE='PT409',DETAIL=jsonb_build_object(
        'code','DUPLICATE_EXPENSE_REVIEW_REQUIRED',
        'timesheet_id',v_current_ts.timesheet_id,
        'categories',COALESCE(v_duplicate_expense_review->'categories','[]'::jsonb)
      )::text;
  END IF;

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'current_timesheet_locked',
      'timesheet_id', v_current_ts.timesheet_id,
      'contract_week_id', NULL,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  SELECT tf.*
    INTO v_current_tsfin
  FROM public.timesheets_financials AS tf
  WHERE tf.timesheet_id = v_current_ts.timesheet_id
    AND tf.is_current = true
  ORDER BY tf.computed_at_utc DESC NULLS LAST, tf.updated_at DESC NULLS LAST, tf.created_at DESC NULLS LAST, tf.id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_current_tsfin.id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'TARGET_NOT_FOUND', DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'reason', 'NO_TSFIN')::text;
  END IF;

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'tsfin_locked',
      'timesheet_id', v_current_ts.timesheet_id,
      'tsfin_id', v_current_tsfin.id,
      'old_processing_status', v_current_tsfin.processing_status::text,
      'old_authorised_present', v_current_tsfin.authorised_at_utc IS NOT NULL,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  IF v_current_ts.contract_id IS NOT NULL THEN
    SELECT COALESCE(c.requires_hr, false)
      INTO v_contract_requires_hr
    FROM public.contracts AS c
    WHERE c.id = v_current_ts.contract_id
    LIMIT 1;
  END IF;

  IF private._candidate_expense_source_family_v1(v_current_ts.timesheet_id) THEN
SELECT
  COALESCE((authority.settings_json#>>'{values,requires_hr}')::boolean,false) AS client_requires_hr,
  (ts.timesheet_id IS NOT NULL
    AND COALESCE((authority.settings_json#>>'{values,hr_validation_required_for_invoice}')::boolean,false)
    AND NOT COALESCE((authority.settings_json#>>'{values,no_timesheet_required}')::boolean,false)
    AND COALESCE(tf.total_hours,0)>0) AS hr_validation_required_for_invoice,
  UPPER(vl.status::text) AS validation_status
INTO v_client_requires_hr, v_hr_validation_required_for_invoice, v_validation_status
FROM public.timesheets ts
LEFT JOIN public.contract_weeks cw ON cw.timesheet_id=ts.timesheet_id
LEFT JOIN public.contracts ct ON ct.id=COALESCE(ts.contract_id,cw.contract_id)
LEFT JOIN LATERAL (
  SELECT f.client_id,f.total_hours FROM public.timesheets_financials f
  WHERE f.timesheet_id=ts.timesheet_id AND f.is_current=true
  ORDER BY f.created_at DESC LIMIT 1
) tf ON true
CROSS JOIN LATERAL (
  SELECT private._contract_settings_effective_core_v1(
    COALESCE(tf.client_id,ct.client_id),COALESCE(ts.contract_id,cw.contract_id),
    COALESCE((ts.worked_start_iso AT TIME ZONE 'Europe/London')::date,
      (ts.scheduled_start_iso AT TIME ZONE 'Europe/London')::date,ts.week_ending_date),
    CASE WHEN ts.sheet_scope='DAILY'::public.timesheet_scope_enum THEN 'DAILY' ELSE 'FINANCE' END,
    ts.timesheet_id) AS settings_json
) authority
LEFT JOIN LATERAL (
  SELECT tv.status FROM public.timesheet_validations tv
  WHERE tv.timesheet_id=ts.timesheet_id ORDER BY tv.created_at DESC LIMIT 1
) vl ON true
WHERE ts.timesheet_id=v_current_ts.timesheet_id AND ts.is_current=true
LIMIT 1
;
  ELSE
  SELECT
    COALESCE(vts.client_requires_hr, COALESCE(v_contract_requires_hr, false)),
    COALESCE(vts.hr_validation_required_for_invoice, COALESCE(v_contract_requires_hr, false)),
    CASE
      WHEN vts.validation_status IS NULL THEN NULL::text
      ELSE UPPER(vts.validation_status::text)
    END
    INTO v_client_requires_hr,
         v_hr_validation_required_for_invoice,
         v_validation_status
  FROM public.v_timesheets_summary_base AS vts
  WHERE vts.timesheet_id = v_current_ts.timesheet_id
  LIMIT 1;
  END IF;

  v_client_requires_hr := COALESCE(v_client_requires_hr, v_contract_requires_hr, false);
  v_hr_validation_required_for_invoice := COALESCE(v_hr_validation_required_for_invoice, v_contract_requires_hr, false);

  IF private._candidate_expense_source_family_v1(v_current_ts.timesheet_id) THEN
    SELECT cw.* INTO v_contract_week FROM public.contract_weeks cw
    WHERE cw.timesheet_id=v_current_ts.timesheet_id FOR UPDATE;
  ELSE
  SELECT cw.*
    INTO v_contract_week
  FROM public.contract_weeks AS cw
  WHERE cw.timesheet_id = v_current_ts.timesheet_id
     OR EXISTS (
       SELECT 1
       FROM public.timesheets AS cw_ts
       WHERE cw_ts.timesheet_id = cw.timesheet_id
         AND cw_ts.booking_id = v_current_ts.booking_id
     )
  ORDER BY CASE WHEN cw.timesheet_id = v_current_ts.timesheet_id THEN 0 ELSE 1 END,
           cw.updated_at DESC NULLS LAST,
           cw.id DESC
  LIMIT 1
  FOR UPDATE;
  END IF;

  IF v_current_ts.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum AND v_contract_week.id IS NULL THEN
    RAISE EXCEPTION USING
      MESSAGE = 'TARGET_NOT_FOUND',
      DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'reason', 'CONTRACT_WEEK_NOT_FOUND_FOR_WEEKLY_TIMESHEET')::text;
  END IF;

  IF v_contract_week.id IS NOT NULL AND v_contract_week.status = 'INVOICED'::public.contract_week_status_enum THEN
    RAISE EXCEPTION USING
      MESSAGE = 'TIMESHEET_LOCKED_BY_INVOICE',
      DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', v_contract_week.id, 'contract_week_status', v_contract_week.status::text, 'lock_scope', 'contract_week_status')::text;
  END IF;

  IF v_contract_week.id IS NOT NULL AND v_contract_week.status = 'CANCELLED'::public.contract_week_status_enum THEN
    RAISE EXCEPTION USING
      MESSAGE = 'CONTRACT_WEEK_NOT_AUTHORISABLE',
      DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', v_contract_week.id, 'contract_week_status', v_contract_week.status::text)::text;
  END IF;

  v_prev_status := v_current_tsfin.processing_status;

  SELECT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(
      CASE
        WHEN v_current_tsfin.invoice_breakdown_json IS NULL THEN '[]'::jsonb
        WHEN jsonb_typeof(v_current_tsfin.invoice_breakdown_json) = 'array' THEN v_current_tsfin.invoice_breakdown_json
        WHEN jsonb_typeof(v_current_tsfin.invoice_breakdown_json) = 'object'
         AND jsonb_typeof(v_current_tsfin.invoice_breakdown_json -> 'segments') = 'array' THEN v_current_tsfin.invoice_breakdown_json -> 'segments'
        ELSE '[]'::jsonb
      END
    ) AS invoice_segment(segment_json)
    WHERE NULLIF(BTRIM(COALESCE(invoice_segment.segment_json ->> 'invoice_locked_invoice_id', '')), '') IS NOT NULL
  ) INTO v_has_segment_invoice_lock;

  IF v_current_ts.archived_at_utc IS NOT NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'TIMESHEET_ARCHIVED', DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id)::text;
  END IF;

  IF v_current_tsfin.locked_by_invoice_id IS NOT NULL OR COALESCE(v_has_segment_invoice_lock, false) THEN
    RAISE EXCEPTION USING MESSAGE = 'TIMESHEET_LOCKED_BY_INVOICE', DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'invoice_id', v_current_tsfin.locked_by_invoice_id)::text;
  END IF;

  IF v_current_ts.authorised_at_server IS NOT NULL OR v_current_tsfin.authorised_at_utc IS NOT NULL OR v_contract_week.status = 'AUTHORISED'::public.contract_week_status_enum THEN
    RAISE EXCEPTION USING MESSAGE = 'ALREADY_AUTHORISED', DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END)::text;
  END IF;

  v_before_signature_json := public.timesheet_lifecycle_guard_signature_v1(v_current_ts.timesheet_id, CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END, COALESCE(v_temp_log_enabled, false));
  v_current_row_signature := NULLIF(BTRIM(COALESCE(v_before_signature_json ->> 'backend_row_signature', v_before_signature_json ->> 'row_signature', v_before_signature_json ->> 'signature', '')), '');
  v_expected_row_signature := NULLIF(BTRIM(COALESCE(p_expected_row_signature, '')), '');
  IF v_expected_row_signature IS NOT NULL AND COALESCE(v_current_row_signature, '') IS DISTINCT FROM v_expected_row_signature THEN
    IF COALESCE(v_temp_log_enabled, false) THEN
      PERFORM public._temp_diag_log(
        'TIMESHEET_LIFECYCLE_SIGNATURE_DIAG',
        'TEMP_TIMESHEET_LIFECYCLE',
        v_current_ts.timesheet_id::text,
        jsonb_strip_nulls(jsonb_build_object(
          'tag', 'TIMESHEET_LIFECYCLE_SIGNATURE_DIAG',
          'function_name', 'timesheet_authorise_generic_atomic',
          'stage', 'row_signature_mismatch_before_authorise',
          'action', 'authorise',
          'route_family', 'timesheet_lifecycle',
          'timesheet_id', p_timesheet_id,
          'current_timesheet_id', v_current_ts.timesheet_id,
          'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
          'expected_row_signature', v_expected_row_signature,
          'current_row_signature', v_current_row_signature,
          'current_signature_payload', v_before_signature_json,
          'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
        ))
      );
    END IF;
    RAISE EXCEPTION USING MESSAGE = 'ROW_SIGNATURE_MISMATCH', DETAIL = jsonb_build_object('expected_row_signature', v_expected_row_signature, 'current_row_signature', v_current_row_signature, 'current_timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END)::text;
  END IF;

  SELECT COALESCE(tv.pre_validated, false)
    INTO v_validation_pre_validated
  FROM public.timesheet_validations AS tv
  WHERE tv.timesheet_id = v_current_ts.timesheet_id
  ORDER BY tv.updated_at DESC NULLS LAST, tv.created_at DESC NULLS LAST, tv.id DESC
  LIMIT 1;

  IF NOT FOUND THEN
    v_validation_pre_validated := false;
  END IF;

  v_validation_ok := COALESCE(v_validation_status, '') IN ('VALIDATION_OK', 'OVERRIDDEN');
  v_force_ready_for_invoice := v_current_tsfin.basis IN ('NHSP'::public.timesheet_fin_basis_enum, 'NHSP_ADJUSTMENT'::public.timesheet_fin_basis_enum, 'HEALTHROSTER_SELF_BILL'::public.timesheet_fin_basis_enum, 'HEALTHROSTER_ADJUSTMENT'::public.timesheet_fin_basis_enum);
  v_must_hold_for_hr_validation := COALESCE(v_hr_validation_required_for_invoice, false) AND NOT v_validation_ok;
  v_prevalidated_fast_track := COALESCE(v_validation_pre_validated, false) AND v_validation_ok;

  IF v_prev_status NOT IN ('PENDING_AUTH'::public.ts_fin_processing_status_enum, 'READY_FOR_HR'::public.ts_fin_processing_status_enum) THEN
    RAISE EXCEPTION USING MESSAGE = 'AUTHORISE_NOT_ALLOWED', DETAIL = jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'processing_status', v_prev_status::text)::text;
  END IF;

  v_new_status := CASE
    WHEN v_force_ready_for_invoice THEN 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum
    WHEN v_must_hold_for_hr_validation THEN 'READY_FOR_HR'::public.ts_fin_processing_status_enum
    WHEN v_prevalidated_fast_track THEN 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum
    WHEN COALESCE(v_client_requires_hr, false) THEN 'READY_FOR_HR'::public.ts_fin_processing_status_enum
    ELSE 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum
  END;

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'before_signature_done',
      'timesheet_id', v_current_ts.timesheet_id,
      'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
      'tsfin_id', v_current_tsfin.id,
      'current_row_signature_present', v_current_row_signature IS NOT NULL,
      'expected_row_signature_present', v_expected_row_signature IS NOT NULL,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  PERFORM set_config('cloudtms.lifecycle_mutation_context', 'timesheet_authorise', true);
  PERFORM set_config('cloudtms.lifecycle_target_timesheet_id', v_current_ts.timesheet_id::text, true);
  PERFORM set_config('cloudtms.lifecycle_defer_summary_refresh', 'on', true);

  UPDATE public.timesheets AS ts
     SET authorised_at_server = v_now,
         revoked_at = NULL,
         revoked_reason = NULL,
         revoked_by = NULL,
         updated_at = v_now
   WHERE ts.timesheet_id = v_current_ts.timesheet_id
     AND ts.is_current = true
   RETURNING * INTO v_current_ts;

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'timesheets_update_done',
      'timesheet_id', v_current_ts.timesheet_id,
      'new_authorised_present', v_current_ts.authorised_at_server IS NOT NULL,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  UPDATE public.timesheets_financials AS tf
     SET processing_status = v_new_status,
         authorised_by_user_id = p_actor_user_id,
         authorised_at_utc = v_now,
         updated_at = v_now
   WHERE tf.id = v_current_tsfin.id
     AND tf.is_current = true
   RETURNING * INTO v_current_tsfin;

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'tsfin_update_done',
      'timesheet_id', v_current_ts.timesheet_id,
      'tsfin_id', v_current_tsfin.id,
      'old_processing_status', v_prev_status::text,
      'new_processing_status', v_current_tsfin.processing_status::text,
      'new_authorised_present', v_current_tsfin.authorised_at_utc IS NOT NULL,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  IF v_contract_week.id IS NOT NULL THEN
    UPDATE public.contract_weeks AS cw
       SET status = 'AUTHORISED'::public.contract_week_status_enum,
           updated_at = v_now
     WHERE cw.id = v_contract_week.id
     RETURNING * INTO v_contract_week;
  END IF;

  PERFORM set_config('cloudtms.lifecycle_defer_summary_refresh', 'off', true);

  v_has_uncleared_advance_override := private.bpay_has_uncleared_advance_v1(v_current_ts.timesheet_id);

  IF COALESCE(v_has_uncleared_advance_override, false) THEN
    v_advance_state_refresh_json := public.pay_timesheet_summary_advance_state_refresh(
      p_timesheet_id => v_current_ts.timesheet_id,
      p_actor_user_id => p_actor_user_id
    );

    PERFORM public._temp_diag_log(
      'TEMP_AUTHORISE_STAGE',
      'TEMP_TIMESHEET_LIFECYCLE',
      v_current_ts.timesheet_id::text,
      jsonb_build_object(
        'function_name', 'timesheet_authorise_generic_atomic',
        'stage', 'advance_state_refresh_done',
        'timesheet_id', v_current_ts.timesheet_id,
        'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
        'refresh_result', COALESCE(v_advance_state_refresh_json, '{}'::jsonb),
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
      )
    );
  ELSE
    PERFORM public._temp_diag_log(
      'TEMP_AUTHORISE_STAGE',
      'TEMP_TIMESHEET_LIFECYCLE',
      v_current_ts.timesheet_id::text,
      jsonb_build_object(
        'function_name', 'timesheet_authorise_generic_atomic',
        'stage', 'advance_state_refresh_skipped',
        'timesheet_id', v_current_ts.timesheet_id,
        'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
        'reason', 'NO_ACTIVE_ADVANCE_THIS_PAYMENT_OVERRIDE',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
      )
    );
  END IF;

  v_after_signature_json := public.timesheet_lifecycle_guard_signature_v1(v_current_ts.timesheet_id, CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END, COALESCE(v_temp_log_enabled, false));
  v_after_row_signature := NULLIF(BTRIM(COALESCE(v_after_signature_json ->> 'backend_row_signature', v_after_signature_json ->> 'row_signature', v_after_signature_json ->> 'signature', '')), '');

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'after_signature_done',
      'timesheet_id', v_current_ts.timesheet_id,
      'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
      'row_signature_present', v_after_row_signature IS NOT NULL,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  PERFORM public._audit_insert(
    'timesheet',
    v_current_ts.timesheet_id::text,
    'TIMESHEET_AUTHORISED',
    jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END, 'previous_processing_status', v_prev_status::text, 'previous_row_signature', v_current_row_signature),
    jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END, 'new_processing_status', v_new_status::text, 'authorised_at_utc', v_now, 'authorised_by_user_id', p_actor_user_id, 'new_row_signature', v_after_row_signature),
    'TIMESHEET_AUTHORISE',
    p_actor_user_id
  );

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'audit_done',
      'timesheet_id', v_current_ts.timesheet_id,
      'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    v_current_ts.timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'return',
      'timesheet_id', v_current_ts.timesheet_id,
      'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
      'new_processing_status', v_new_status::text,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'success', true,
    'operation', 'timesheet_authorise',
    'timesheet_id', v_current_ts.timesheet_id,
    'current_timesheet_id', v_current_ts.timesheet_id,
    'requested_timesheet_id', v_requested_ts.timesheet_id,
    'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END,
    'booking_id', v_current_ts.booking_id,
    'candidate_id', v_current_tsfin.candidate_id,
    'authorised_at_server', v_current_ts.authorised_at_server,
    'revoked_at', v_current_ts.revoked_at,
    'authorised_at_utc', v_current_tsfin.authorised_at_utc,
    'advance_state_refresh', COALESCE(v_advance_state_refresh_json, '{}'::jsonb),
    'current_version', v_current_ts.version,
    'was_stale', v_requested_ts.timesheet_id IS DISTINCT FROM v_current_ts.timesheet_id,
    'previous_processing_status', v_prev_status::text,
    'processing_status', v_new_status::text,
    'new_processing_status', v_new_status::text,
    'validation_status', v_validation_status,
    'validation_pre_validated', COALESCE(v_validation_pre_validated, false),
    'hr_validation_required_for_invoice', COALESCE(v_hr_validation_required_for_invoice, false),
    'backend_row_signature', v_after_row_signature,
    'row_signature', v_after_row_signature,
    'affected_rows', jsonb_build_array(jsonb_build_object('timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END, 'booking_id', v_current_ts.booking_id, 'row_key', 'timesheet:' || v_current_ts.timesheet_id::text)),
    'cache_invalidation_hints', jsonb_build_object('changed_domains', CASE WHEN COALESCE(v_has_uncleared_advance_override, false) THEN jsonb_build_array('timesheets', 'timesheets_financials', 'contract_weeks', 'timesheet_summary_pay_state_cache') ELSE jsonb_build_array('timesheets', 'timesheets_financials', 'contract_weeks') END, 'timesheet_id', v_current_ts.timesheet_id, 'contract_week_id', CASE WHEN v_contract_week.id IS NULL THEN NULL ELSE v_contract_week.id END)
  );
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS v_error_state = RETURNED_SQLSTATE, v_error_message = MESSAGE_TEXT;
  PERFORM public._temp_diag_log(
    'TEMP_AUTHORISE_STAGE',
    'TEMP_TIMESHEET_LIFECYCLE',
    p_timesheet_id::text,
    jsonb_build_object(
      'function_name', 'timesheet_authorise_generic_atomic',
      'stage', 'exception',
      'timesheet_id', p_timesheet_id,
      'sqlstate', v_error_state,
      'error_message', v_error_message,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_diag_started_at)) * 1000)::numeric, 2)
    )
  );
  IF v_error_state = '55P03' THEN
    RAISE EXCEPTION USING MESSAGE = 'LOCK_TIMEOUT', DETAIL = jsonb_build_object('timesheet_id', p_timesheet_id)::text;
  END IF;
  RAISE;
END;
$function$;

-- private.pay_sync_overpayments_from_workbench_workspace_v1 from supabase/repeatable/26092026_0203_banking_pay_stage2_workbench_draft_v1.sql; definition SHA-256 319d654bc20b79817205534074b63914e3ecdf63e1b09d58d0bbbfe150f80b41.
CREATE OR REPLACE FUNCTION private.pay_sync_overpayments_from_workbench_workspace_v1(p_build_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_nonce uuid, p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_pay_channel_scope text, p_candidate_ids uuid[], p_mismatch_choices jsonb DEFAULT '{}'::jsonb, p_client_filter_single uuid DEFAULT NULL::uuid, p_force_include_timesheet_ids uuid[] DEFAULT NULL::uuid[], p_exclude_timesheet_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_bounded_build private.banking_pay_workbench_economic_builds%rowtype;
  v_bounded_job public.banking_pay_workbench_jobs%rowtype;
  v_bounded_attempt private.banking_pay_workbench_stage_attempts%rowtype;
  v_bounded_registry private.banking_pay_workbench_candidate_scope_registry%rowtype;
  v_bounded_scope_ids uuid[] := array[]::uuid[];
  v_bounded_scope_count integer := 0;
  v_bounded_fact_count bigint := 0;
  v_bounded_pre_sync_digest text;
  v_bounded_post_sync_digest text;
  v_bounded_canonical_digest text;
  v_bounded_economic_component_digest text;
  v_bounded_presentation_allocation_digest text;
  v_bounded_canonical_count integer := 0;
  v_bounded_canonical_stage_timestamp timestamptz;
  v_bounded_canonical_result jsonb := '{}'::jsonb;
  v_public_result_json jsonb := '{}'::jsonb;
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, '')));
  v_timesheet_case_count int := 0;
  v_cases_inserted int := 0;
  v_cases_touched int := 0;
  v_cases_amended int := 0;
  v_cases_reopened int := 0;
  v_cases_cleared int := 0;
  v_case_update_count int := 0;
  v_overpayment_case_count int := 0;
  v_underpayment_case_count int := 0;
  v_case_candidates_json jsonb := '[]'::jsonb;
  v_overpayment_json jsonb := '[]'::jsonb;
  v_underpayment_json jsonb := '[]'::jsonb;
  v_preview_decisions_json jsonb := '{}'::jsonb;
  v_preview_context_json jsonb := '{}'::jsonb;
  v_preview_baseline_json jsonb := '{}'::jsonb;
  v_preview_collect_result_json jsonb := '{}'::jsonb;
  v_preview_canonical_result_json jsonb := '{}'::jsonb;
  v_preview_candidate_row_json jsonb := '{}'::jsonb;
  v_preview_scope_context_json jsonb := '{}'::jsonb;
  v_preview_scope_candidate_ids_json jsonb := '[]'::jsonb;
  v_preview_candidate_loop_id uuid := NULL::uuid;
  v_preview_candidate_count integer := 0;
  v_requested_candidate_count integer := 0;
  v_missing_candidate_count integer := 0;
  v_missing_candidate_ids_json jsonb := '[]'::jsonb;
  v_authoritative_timesheet_scope_requested boolean := false;
  v_authoritative_timesheet_scope boolean := false;
  v_explicit_empty_timesheet_scope boolean := false;
  v_preview_scope_strategy text := 'CANDIDATE_FULL_LIVE';
  v_sync_authority_token text := NULL::text;
  v_current_sync_authority_token text := NULL::text;
  v_workbench_session_id_text text := NULL::text;
  v_source_build_run_id_text text := NULL::text;
  v_session_version_text text := NULL::text;
  v_workbench_session_id uuid := NULL::uuid;
  v_source_build_run_id uuid := NULL::uuid;
  v_workbench_session_version bigint := NULL::bigint;
  v_authoritative_candidate_id uuid := NULL::uuid;
  v_existing_active_reserved_amount numeric(12,2) := 0;
  v_effective_case_amount_ex numeric(12,2);
  v_active_reservation_protection_applied boolean := false;
  v_correction_rewrite_result jsonb := '{}'::jsonb;
  v_resolution_pending_member_ids uuid[] := array[]::uuid[];
  v_resolution_pending_root_ids uuid[] := array[]::uuid[];

  v_target_case_row record;
  v_existing_case_row record;
  v_case_before_json jsonb;
  v_case_after_json jsonb;
  v_components_sync_result jsonb;
  v_component_case_outstanding_amount numeric(12,2) := 0;
  v_component_open_remaining_total numeric(12,2) := 0;
  v_component_case_mismatch_amount numeric(12,2) := 0;
  v_existing_recovered_amount numeric(12,2);
  v_new_outstanding_amount numeric(12,2);
  v_target_amount_is_authoritative_outstanding boolean := false;
  v_selected_finance_case_id uuid;
  v_selected_event_type text;
  v_selected_reason text;
  v_selected_note text;
  v_open_case_candidate record;
  v_target_case_amount_ex numeric(12,2);
  v_case_taxability public.pay_finance_taxability_enum := NULL;
  v_case_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_synced_case_taxability public.pay_finance_taxability_enum := NULL;
  v_synced_case_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_synced_before_taxability public.pay_finance_taxability_enum := NULL;
  v_synced_before_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_case_metadata_component_count integer := 0;
  v_synced_open_component_count integer := 0;
  v_taxability_event_before_json jsonb;
  v_taxability_event_after_json jsonb;
  v_authoritative_negative_component_count integer := 0;
  v_authoritative_negative_component_digest text := NULL::text;
  v_expected_negative_component_digest text := NULL::text;
  v_authoritative_settled_baseline_digest text := NULL::text;
  v_expected_settled_baseline_digest text := NULL::text;
  v_authoritative_session_valid boolean := false;
  v_observed_effect_count integer := 0;
  v_observed_effect_digest text := md5('');
  v_effect_mismatch_detail jsonb := '{}'::jsonb;
  v_presentation_mismatch_detail jsonb := '{}'::jsonb;
  v_rate_authority_failure_code text := NULL::text;
  v_rate_authority_failure_detail jsonb := '[]'::jsonb;
  v_exception_detail text := NULL::text;
  v_exception_context text := NULL::text;
  v_effect_capture_mode boolean := lower(COALESCE(current_setting('cloudtms.pay_workbench_effect_capture_mode',true),''))='capture';
  v_captured_effects jsonb := '[]'::jsonb;
  v_execution_profile_version integer := CASE
    WHEN COALESCE(current_setting('cloudtms.pay_workbench_execution_profile_version', true), '') ~ '^[12]$'
      THEN current_setting('cloudtms.pay_workbench_execution_profile_version', true)::integer
    ELSE 1
  END;
  v_reconciliation_optimization_version integer := 0;
  v_reconcile_started_at timestamptz := clock_timestamp();
  v_freshness_set_ms integer := 0;
  v_workspace_cache_ms integer := 0;
  v_authoritative_components_ms integer := 0;
  v_preflight_setup_ms integer := 0;
  v_correction_residuals_ms integer := 0;
  v_authority_validation_ms integer := 0;
  v_component_assembly_ms integer := 0;
  v_preview_workspace_ms integer := 0;
  v_preview_collect_ms integer := 0;
  v_preview_canonical_ms integer := 0;
  v_preview_summary_ms integer := 0;
  v_case_workspace_ms integer := 0;
  v_finance_apply_ms integer := 0;
  v_post_freshness_ms integer := 0;
  v_canonical_render_ms integer := 0;
  v_canonical_stage_ms integer := 0;
  v_phase_started_at timestamptz := clock_timestamp();
  -- A28 reconciliation slicing
  v_slice jsonb := NULL::jsonb;
  v_slice_active boolean := false;
  v_slice_final boolean := false;
  v_slice_plan jsonb := NULL::jsonb;
  v_slice_ordinal_base bigint := 0;
  v_slice_max_ordinal bigint := 0;
  v_slice_kept integer := 0;
  v_slice_dropped_candidate_level integer := 0;
  v_slice_dropped_other_slice integer := 0;
  v_slice_recovery_headroom numeric := 0;
  v_slice_ordinary_headroom numeric := 0;
  v_slice_total_scope_count integer := 0;
  v_slice_line_total integer := 0;
begin
  SELECT * INTO v_bounded_registry
  FROM private.banking_pay_workbench_candidate_scope_registry
  WHERE current_build_id=p_build_id FOR UPDATE;
  SELECT * INTO v_bounded_build
  FROM private.banking_pay_workbench_economic_builds
  WHERE id=p_build_id FOR UPDATE;
  SELECT * INTO v_bounded_job
  FROM public.banking_pay_workbench_jobs
  WHERE id=p_job_id FOR UPDATE;
  SELECT * INTO v_bounded_attempt
  FROM private.banking_pay_workbench_stage_attempts
  WHERE id=p_attempt_id FOR UPDATE;

  IF v_bounded_build.id IS NULL OR v_bounded_job.id IS NULL OR v_bounded_attempt.id IS NULL
     OR v_bounded_registry.candidate_id IS DISTINCT FROM v_bounded_build.candidate_id
     OR v_bounded_registry.dirty_generation IS DISTINCT FROM v_bounded_build.captured_candidate_generation
     OR v_bounded_registry.current_source_change_seq IS DISTINCT FROM v_bounded_build.source_change_seq
     OR v_bounded_job.economic_build_id IS DISTINCT FROM p_build_id
     OR v_bounded_job.private_stage IS DISTINCT FROM 'RECONCILE_EXECUTE'
     OR v_bounded_job.status IS DISTINCT FROM 'RUNNING'
     OR v_bounded_attempt.job_id IS DISTINCT FROM p_job_id
     OR v_bounded_attempt.build_id IS DISTINCT FROM p_build_id
     OR v_bounded_attempt.private_stage IS DISTINCT FROM 'RECONCILE_EXECUTE'
     OR v_bounded_attempt.attempt_nonce IS DISTINCT FROM p_attempt_nonce
     OR v_bounded_attempt.attempt_status IS DISTINCT FROM 'STARTED'
     OR clock_timestamp()>=v_bounded_attempt.lease_expires_at_utc
     OR v_bounded_build.status IS DISTINCT FROM 'RECONCILING'
     OR v_bounded_build.private_stage IS DISTINCT FROM 'RECONCILE_EXECUTE'
     OR v_bounded_build.dependency_closure_sealed_at_utc IS NULL
     OR NOT v_bounded_build.dependency_edge_stream_complete
     OR NOT v_bounded_build.edge_tag_stream_complete
     OR v_bounded_build.tagged_edge_count<>v_bounded_build.dependency_edge_count
     OR v_bounded_build.row_seal_count<>v_bounded_build.scope_count THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001';
  END IF;

  IF COALESCE(NULLIF(v_bounded_build.attestation_json->>'execution_profile_version','')::integer,1)
       IS DISTINCT FROM v_execution_profile_version
     OR COALESCE(v_bounded_attempt.execution_profile_version,1)
       IS DISTINCT FROM v_execution_profile_version THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_EXECUTION_PROFILE_MISMATCH' USING ERRCODE='23514';
  END IF;
  BEGIN
    v_reconciliation_optimization_version:=COALESCE(
      NULLIF(v_bounded_build.attestation_json->>'reconciliation_optimization_version','')::integer,0
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_OPTIMIZATION_INVALID' USING ERRCODE='23514';
  END;
  IF v_reconciliation_optimization_version NOT IN (0,1)
     OR (v_execution_profile_version=1 AND v_reconciliation_optimization_version<>0) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_OPTIMIZATION_MISMATCH' USING ERRCODE='23514';
  END IF;
  PERFORM pg_catalog.set_config(
    'cloudtms.pay_workbench_reconciliation_optimization_version',
    v_reconciliation_optimization_version::text,
    true
  );
  IF v_reconciliation_optimization_version=1 THEN
    CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp._bpay_wb_correction_residual_cache_v2(
      candidate_id uuid NOT NULL,session_key text NOT NULL,exclude_key text NOT NULL,result_json jsonb NOT NULL,
      PRIMARY KEY(candidate_id,session_key,exclude_key)
    ) ON COMMIT DROP;
    TRUNCATE TABLE pg_temp._bpay_wb_correction_residual_cache_v2;
  END IF;

  IF EXISTS(
    SELECT 1 FROM private.banking_pay_workbench_economic_build_scope
    WHERE build_id=p_build_id AND closure_status<>'SEALED' LIMIT 1
  ) OR EXISTS(
    SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
    WHERE scope_row.build_id=p_build_id
      AND NOT scope_row.required_fact_families <@ scope_row.completed_fact_families
    LIMIT 1
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_FACTS_INCOMPLETE' USING ERRCODE='23514';
  END IF;

  SELECT array_agg(timesheet_id ORDER BY stable_ordinal),count(*)::integer
  INTO v_bounded_scope_ids,v_bounded_scope_count
  FROM private.banking_pay_workbench_economic_build_scope
  WHERE build_id=p_build_id AND closure_status='SEALED';
  v_bounded_scope_ids:=COALESCE(v_bounded_scope_ids,array[]::uuid[]);
  v_slice_total_scope_count:=v_bounded_scope_count;

  -- A28: a sliced build reconciles only the whole dependency units of its current slice. The slice is chosen by
  -- the source-build owner and recorded on the locked build; it is re-derived here from the sealed scope.
  v_slice_plan := v_bounded_build.attestation_json->'reconcile_slicing';
  v_slice := v_slice_plan->'current';
  IF jsonb_typeof(v_slice_plan)='object' THEN
    IF jsonb_typeof(v_slice)<>'object' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SLICE_REQUIRED' USING ERRCODE='23514';
    END IF;
    v_slice_active := true;
    v_slice_final := COALESCE((v_slice->>'final')::boolean,false);
    SELECT array_agg(scope_row.timesheet_id ORDER BY scope_row.stable_ordinal),count(*)::integer
    INTO v_bounded_scope_ids,v_bounded_scope_count
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    WHERE scope_row.build_id=p_build_id AND scope_row.closure_status='SEALED'
      AND scope_row.dependency_unit_key IN (
        SELECT unit_scope.dependency_unit_key
        FROM private.banking_pay_workbench_economic_build_scope unit_scope
        WHERE unit_scope.build_id=p_build_id AND unit_scope.closure_status='SEALED'
        GROUP BY unit_scope.dependency_unit_key
        HAVING min(unit_scope.stable_ordinal)>(v_slice->>'after_unit_ordinal')::bigint
           AND min(unit_scope.stable_ordinal)<=(v_slice->>'through_unit_ordinal')::bigint);
    v_bounded_scope_ids:=COALESCE(v_bounded_scope_ids,array[]::uuid[]);
    IF v_bounded_scope_count<1 OR v_bounded_scope_count>100
       OR v_bounded_scope_count IS DISTINCT FROM (v_slice->>'timesheet_count')::integer THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SLICE_INVALID' USING ERRCODE='23514';
    END IF;
  END IF;

  -- Session-replacement correction decisions are registered before the
  -- target candidate has authoritative build evidence.  The legacy source
  -- builder consumed those registrations immediately before materialising
  -- correction residuals; the bounded workspace must preserve that same
  -- ordering.  Capture and execute each recompute from raw authority.  The
  -- capture subtransaction rolls this state back with its finance DML, while
  -- execute persists the identical carried decision before effect and
  -- canonical-output attestation.
  PERFORM public._pay_workbench_case_resolution_carry_process_candidate_v1(
    v_bounded_build.session_id,
    v_bounded_build.candidate_id,
    v_bounded_build.source_build_run_id,
    clock_timestamp()
  );

  CREATE TEMP TABLE pg_temp.tmp_sync_entitlement_components_v2(
    timesheet_id uuid NOT NULL,
    key_type text NOT NULL,
    key_value text NOT NULL,
    truth_ex_vat numeric,
    baseline_ex_vat numeric,
    truth_inc_vat numeric,
    baseline_inc_vat numeric,
    PRIMARY KEY(timesheet_id,key_type,key_value)
  ) ON COMMIT DROP;
  CREATE TEMP TABLE pg_temp.tmp_sync_settled_basis_by_timesheet_v2(
    timesheet_id uuid PRIMARY KEY,
    active_settled_component_count integer NOT NULL,
    active_settled_signature text NOT NULL
  ) ON COMMIT DROP;

  IF v_execution_profile_version = 2 THEN
    INSERT INTO pg_temp.tmp_sync_entitlement_components_v2(
      timesheet_id,key_type,key_value,truth_ex_vat,baseline_ex_vat,truth_inc_vat,baseline_inc_vat)
    SELECT component.timesheet_id,UPPER(BTRIM(component.key_type)),BTRIM(component.key_value),
      component.truth_ex_vat,component.baseline_ex_vat,component.truth_inc_vat,component.baseline_inc_vat
    FROM private.pay_current_timesheet_entitlement_components_from_build_v1(p_build_id,NULL::text) component
    WHERE NULLIF(BTRIM(COALESCE(component.key_type,'')),'') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(component.key_value,'')),'') IS NOT NULL
      AND (NOT v_slice_active OR component.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */;

    INSERT INTO pg_temp.tmp_sync_settled_basis_by_timesheet_v2(
      timesheet_id,active_settled_component_count,active_settled_signature)
    SELECT scope_row.timesheet_id,
      COUNT(fact.natural_key)::integer,
      md5(COALESCE((jsonb_agg(jsonb_build_object(
        'key_type',fact.economic_key_type,
        'key_value',fact.economic_key_value,
        'amount_ex_vat',ROUND(COALESCE(fact.amount_ex_vat,0),2),
        'amount_inc_vat',ROUND(COALESCE(fact.amount_inc_vat,0),2)
      ) ORDER BY fact.economic_key_type,fact.economic_key_value)
        FILTER (WHERE fact.natural_key IS NOT NULL))::text,'[]'))
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN private.banking_pay_workbench_economic_build_facts fact
      ON fact.build_id=scope_row.build_id
     AND fact.timesheet_id=scope_row.timesheet_id
     AND fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
    WHERE scope_row.build_id=p_build_id
      AND (NOT v_slice_active OR scope_row.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */
    GROUP BY scope_row.timesheet_id;
  END IF;
  v_workspace_cache_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer;

  IF to_regclass('pg_temp._bpay_wb_pre_sync_freshness_v1') IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_FRESHNESS_CONTEXT_CONFLICT'
      USING ERRCODE='23514';
  END IF;
  CREATE TEMP TABLE pg_temp._bpay_wb_pre_sync_freshness_v1(
    timesheet_id uuid PRIMARY KEY,
    input_fingerprint text NULL,
    revision_json jsonb NULL,
    settled_authority_digest text NOT NULL
  ) ON COMMIT DROP;
  IF v_execution_profile_version = 2 THEN
    INSERT INTO pg_temp._bpay_wb_pre_sync_freshness_v1(
      timesheet_id,input_fingerprint,revision_json,settled_authority_digest)
    SELECT scope_row.timesheet_id,current_fingerprint.input_fingerprint,
      current_fingerprint.revision_json,
      md5(jsonb_build_object(
        'last_settled_snapshot_json',pay_state.last_settled_snapshot_json,
        'last_settled_signature',pay_state.last_settled_signature,
        'last_settled_pay_batch_id',pay_state.last_settled_pay_batch_id,
        'last_settled_at_utc',pay_state.last_settled_at_utc
      )::text)
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN private.pay_workbench_timesheet_input_fingerprint_v1(
      p_build_id,v_bounded_build.candidate_id,v_bounded_scope_ids
    ) current_fingerprint ON current_fingerprint.timesheet_id=scope_row.timesheet_id
    LEFT JOIN public.timesheet_pay_state pay_state ON pay_state.timesheet_id=scope_row.timesheet_id
    WHERE scope_row.build_id=p_build_id
      AND (NOT v_slice_active OR scope_row.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */;
  ELSE
    INSERT INTO pg_temp._bpay_wb_pre_sync_freshness_v1(
      timesheet_id,input_fingerprint,revision_json,settled_authority_digest)
    SELECT scope_row.timesheet_id,current_fingerprint.input_fingerprint,
      current_fingerprint.revision_json,
      md5(jsonb_build_object(
        'last_settled_snapshot_json',pay_state.last_settled_snapshot_json,
        'last_settled_signature',pay_state.last_settled_signature,
        'last_settled_pay_batch_id',pay_state.last_settled_pay_batch_id,
        'last_settled_at_utc',pay_state.last_settled_at_utc
      )::text)
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN LATERAL private.pay_workbench_timesheet_input_fingerprint_v1(
      p_build_id,v_bounded_build.candidate_id,ARRAY[scope_row.timesheet_id]
    ) current_fingerprint ON true
    LEFT JOIN public.timesheet_pay_state pay_state ON pay_state.timesheet_id=scope_row.timesheet_id
    WHERE scope_row.build_id=p_build_id
      AND (NOT v_slice_active OR scope_row.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */;
  END IF;
  v_freshness_set_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer-v_workspace_cache_ms;
  v_phase_started_at := clock_timestamp();

  IF EXISTS(
    SELECT 1
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN pg_temp._bpay_wb_pre_sync_freshness_v1 pre_sync
      ON pre_sync.timesheet_id=scope_row.timesheet_id
    WHERE scope_row.build_id=p_build_id
      AND (NOT v_slice_active OR scope_row.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */
      AND pre_sync.input_fingerprint IS DISTINCT FROM scope_row.captured_input_fingerprint
    LIMIT 1
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001';
  END IF;

  SELECT count(*)::bigint,
         md5(COALESCE(string_agg(fact_family||':'||natural_key||':'||financial_digest,''
           ORDER BY fact_family,natural_key),''))
  INTO v_bounded_fact_count,v_bounded_pre_sync_digest
  FROM private.banking_pay_workbench_economic_build_facts
  WHERE build_id=p_build_id AND fact_family NOT IN ('DEPENDENCY_EDGE','EXPECTED_FINANCE_EFFECT');

  -- A28 (PRE-EXISTING SB02 fix, item 1): a Candidate with NOTHING to pay. The sealed build's only facts are
  -- zero-amount UNIT_PROJECTION dependency evidence (it owns no economic occurrence): no priced, settled,
  -- reserved, finance-case, component, protection or allocation fact at all. There is nothing to price, reconcile
  -- or present, so it reconciles to ZERO staged lines exactly like the existing empty-scope route, instead of
  -- failing checks that assume something to present. The freshness fence above has already run. Any other fact
  -- keeps the full reconciliation.
  IF NOT v_slice_active AND v_bounded_scope_count>0 AND NOT EXISTS(
       SELECT 1 FROM private.banking_pay_workbench_economic_build_facts ntp_fact
       WHERE ntp_fact.build_id=p_build_id
         AND ntp_fact.fact_family NOT IN ('DEPENDENCY_EDGE','EXPECTED_FINANCE_EFFECT')
         AND NOT (ntp_fact.fact_family='LIVE_ENTITLEMENT_INPUT' AND ntp_fact.source_relation='UNIT_PROJECTION'
           AND COALESCE(ntp_fact.amount_ex_vat,0)=0 AND COALESCE(ntp_fact.amount_inc_vat,0)=0
           AND COALESCE(ntp_fact.truth_ex_vat,0)=0 AND COALESCE(ntp_fact.truth_inc_vat,0)=0
           AND COALESCE(ntp_fact.baseline_ex_vat,0)=0 AND COALESCE(ntp_fact.baseline_inc_vat,0)=0
           AND COALESCE(ntp_fact.reserved_source_amount,0)=0
           AND ntp_fact.finance_case_id IS NULL AND ntp_fact.finance_component_id IS NULL
           AND ntp_fact.reservation_id IS NULL)
       LIMIT 1) THEN
    PERFORM set_config('cloudtms.pay_workbench_reconcile_slice_v1','',true);
    IF v_effect_capture_mode THEN
      RETURN jsonb_build_object('ok',true,'public_result_json',jsonb_build_object(
        'ok',true,'effect_plan_capture',true,'captured_effects','[]'::jsonb,'nothing_to_price',true,
        '_internal_reconcile_timing',jsonb_build_object('nothing_to_price',true,
          'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer)),
        'internal_result_json',jsonb_build_object('captured_effect_count',0,'nothing_to_price',true));
    END IF;
    IF COALESCE((v_bounded_build.attestation_json->>'effect_plan_sealed')::boolean,false) IS NOT TRUE
       OR COALESCE((v_bounded_build.attestation_json->>'effect_plan_count')::integer,-1)<>0
       OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_facts effect_row
         WHERE effect_row.build_id=p_build_id AND effect_row.fact_family='EXPECTED_FINANCE_EFFECT' LIMIT 1) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_PLAN_MISMATCH' USING ERRCODE='23514';
    END IF;
    DELETE FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=p_build_id;
    SELECT md5(jsonb_build_object(
      'candidate_id',v_bounded_build.candidate_id,'case_count',count(*),
      'case_digest',md5(COALESCE(string_agg(md5(to_jsonb(case_row)::text),'' ORDER BY case_row.id),''))
    )::text)
    INTO v_bounded_post_sync_digest
    FROM public.pay_advances case_row WHERE case_row.candidate_id=v_bounded_build.candidate_id;
    UPDATE private.banking_pay_workbench_economic_builds
    SET status='RECONCILED',private_stage='SOURCE_PUBLISH',fact_count=v_bounded_fact_count,
        pre_sync_digest=v_bounded_pre_sync_digest,post_sync_digest=v_bounded_post_sync_digest,
        canonical_count=0,canonical_digest=md5(''),
        attestation_json=COALESCE(attestation_json,'{}'::jsonb)||jsonb_build_object(
          'version',1,'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH',
          'build_id',p_build_id,'attempt_id',p_attempt_id,'scope_count',v_bounded_scope_count,
          'fact_count',v_bounded_fact_count,'canonical_count',0,
          'effect_plan_sealed',true,'effect_plan_count',0,
          'effect_plan_digest',v_bounded_build.attestation_json->>'effect_plan_digest',
          'observed_finance_effect_count',0,'observed_finance_effect_digest',md5(''),
          'economic_component_digest',md5(''),'presentation_allocation_digest',md5(''),
          'pre_sync_digest',v_bounded_pre_sync_digest,'post_sync_digest',v_bounded_post_sync_digest,
          'canonical_digest',md5(''),'nothing_to_price_reconciliation_version',1),
        reconciled_at_utc=clock_timestamp(),publication_cursor_json=jsonb_build_object(
          'cursor_kind','SOURCE_PUBLISH','cursor_version',1,'build_id',p_build_id,
          'candidate_id',v_bounded_build.candidate_id,'canonical_count',0,'canonical_digest',md5('')),
        updated_at_utc=clock_timestamp()
    WHERE id=p_build_id AND status='RECONCILING' AND private_stage='RECONCILE_EXECUTE';
    IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001'; END IF;
    RETURN jsonb_build_object(
      'ok',true,'public_result_json',jsonb_build_object('ok',true,'nothing_to_price',true,
        'pay_channel_scope',upper(NULLIF(btrim(p_pay_channel_scope),'')),
        'cases_inserted',0,'cases_touched',0,'cases_amended',0,'cases_reopened',0,'cases_cleared',0),
      'internal_result_json',jsonb_build_object('build_id',p_build_id,'attempt_id',p_attempt_id,
        'scope_timesheet_count',v_bounded_scope_count,'fact_count',v_bounded_fact_count,
        'canonical_stage_count',0,'nothing_to_price',true),
      'build_id',p_build_id,'attempt_id',p_attempt_id,'scope_timesheet_count',v_bounded_scope_count,
      'canonical_stage_count',0,'nothing_to_price',true);
  END IF;

  IF to_regclass('pg_temp._bpay_wb_expected_effects') IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_CONFLICT' USING ERRCODE='23514';
  END IF;
  CREATE TEMP TABLE pg_temp._bpay_wb_expected_effects(
    build_token uuid NOT NULL,
    candidate_id uuid NOT NULL,
    timesheet_id uuid NULL,
    relation_name text NOT NULL,
    operation text NOT NULL,
    source_id uuid NOT NULL,
    actual_source_id uuid NULL,
    finance_case_id uuid NULL,
    finance_component_id uuid NULL,
    economic_key_type text NULL,
    economic_key_value text NULL,
    proposed boolean NOT NULL DEFAULT false,
    expected_before_digest text NULL,
    expected_after_digest text NULL,
    observed boolean NOT NULL DEFAULT false,
    UNIQUE NULLS NOT DISTINCT(
      build_token,relation_name,operation,source_id,candidate_id,timesheet_id,
      expected_before_digest,expected_after_digest
    )
  ) ON COMMIT DROP;
  CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_effect_identity_map_v1(
    relation_name text NOT NULL,
    logical_source_id uuid NOT NULL,
    actual_source_id uuid NOT NULL,
    PRIMARY KEY(relation_name,logical_source_id),
    UNIQUE(relation_name,actual_source_id)
  ) ON COMMIT DROP;
  TRUNCATE pg_temp._bpay_wb_effect_identity_map_v1;

  IF NOT v_effect_capture_mode THEN
    INSERT INTO pg_temp._bpay_wb_expected_effects(build_token,candidate_id,timesheet_id,
      relation_name,operation,source_id,finance_case_id,finance_component_id,
      economic_key_type,economic_key_value,expected_before_digest,expected_after_digest,proposed,observed)
    SELECT v_bounded_build.build_token,fact.candidate_id,fact.timesheet_id,fact.source_relation,
      fact.source_payload_json->>'operation',fact.source_id,fact.finance_case_id,
      fact.finance_component_id,fact.economic_key_type,fact.economic_key_value,
      NULLIF(fact.source_payload_json->>'expected_before_digest',''),
      NULLIF(fact.source_payload_json->>'expected_after_digest',''),false,false
    FROM private.banking_pay_workbench_economic_build_facts fact
    WHERE fact.build_id=p_build_id AND fact.fact_family='EXPECTED_FINANCE_EFFECT';
    IF COALESCE((v_bounded_build.attestation_json->>'effect_plan_sealed')::boolean,false) IS NOT TRUE
       OR NULLIF(v_bounded_build.attestation_json->>'effect_plan_digest','') IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_PLAN_REQUIRED' USING ERRCODE='23514';
    END IF;
  END IF;

  p_candidate_ids:=ARRAY[v_bounded_build.candidate_id];
  p_force_include_timesheet_ids:=v_bounded_scope_ids;
  p_exclude_timesheet_ids:=ARRAY(
    SELECT excluded_id FROM unnest(COALESCE(p_exclude_timesheet_ids,array[]::uuid[])) excluded_id
    WHERE excluded_id=ANY(v_bounded_scope_ids) ORDER BY excluded_id
  );
  PERFORM set_config('cloudtms.pay_workbench_overpayment_sync_token',v_bounded_build.build_token::text,true);
  -- A28: the final slice renders the Candidate-level balance lines. Its recovery headroom must be the whole
  -- Candidate's, so the additive headroom of the earlier slices is handed to the two preview owners, bound to
  -- this build token (they ignore it otherwise). Transaction-local; cleared before every return.
  PERFORM set_config('cloudtms.pay_workbench_reconcile_slice_v1',CASE WHEN v_slice_active THEN jsonb_build_object(
    'build_token',v_bounded_build.build_token::text,'candidate_id',v_bounded_build.candidate_id::text,
    'final',v_slice_final,'slice_index',v_slice->'index',
    'prior_recovery_headroom_ex',COALESCE((v_slice_plan->>'prior_recovery_headroom_ex')::numeric,0),
    'prior_ordinary_positive_headroom_ex',COALESCE((v_slice_plan->>'prior_ordinary_positive_headroom_ex')::numeric,0)
  )::text ELSE '' END,true);
  p_mismatch_choices:=(CASE WHEN jsonb_typeof(COALESCE(p_mismatch_choices,'{}'::jsonb))='object'
    THEN COALESCE(p_mismatch_choices,'{}'::jsonb) ELSE '{}'::jsonb END)
    - 'overpayment_sync_negative_component_digest'
    - 'overpayment_sync_settled_baseline_digest'
    ||jsonb_build_object(
      'overpayment_sync_authoritative_timesheet_scope',true,
      'overpayment_sync_authority_token',v_bounded_build.build_token::text,
      'workbench_session_id',v_bounded_build.session_id::text,
      'source_build_run_id',v_bounded_build.source_build_run_id::text,
      'source_change_seq',v_bounded_build.source_change_seq,
      'session_version',v_bounded_build.session_version,
      'overpayment_sync_scope_digest',v_bounded_build.scope_digest,
      'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
    );

  v_preflight_setup_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  declare
    v_correction_candidate uuid;
    v_residuals jsonb;
    v_candidate_pending_member_ids uuid[] := array[]::uuid[];
    v_candidate_pending_root_ids uuid[] := array[]::uuid[];
  begin
    foreach v_correction_candidate in array coalesce(p_candidate_ids,array[]::uuid[]) loop
      v_residuals:=public._ctms_candidate_correction_residuals_v1(
        NULL::uuid,
        v_correction_candidate,
        NULL::uuid,
        'PAY_SYNC_OVERPAYMENTS'
      );

      v_candidate_pending_member_ids := ARRAY(
        select distinct member_id.value::uuid
        from jsonb_array_elements(v_residuals) residual(value)
        cross join lateral jsonb_array_elements_text(
          coalesce(residual.value->'member_timesheet_ids', '[]'::jsonb)
        ) member_id(value)
        where coalesce((residual.value->>'draftable')::boolean, false) is not true
          and coalesce(residual.value->>'block_code', '')
                = 'CORRECTION_CHAIN_PAY_METHOD_RESOLUTION_REQUIRED'
          and coalesce((residual.value->>'unresolved_count')::integer, 0) > 0
          and coalesce((residual.value->>'reservation_overrun_count')::integer, 0) = 0
          and coalesce((residual.value->>'component_count')::integer, 0) > 0
          and member_id.value
                ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        order by member_id.value::uuid
      );

      v_candidate_pending_root_ids := ARRAY(
        select distinct (residual.value->>'root_timesheet_id')::uuid
        from jsonb_array_elements(v_residuals) residual(value)
        where coalesce((residual.value->>'draftable')::boolean, false) is not true
          and coalesce(residual.value->>'block_code', '')
                = 'CORRECTION_CHAIN_PAY_METHOD_RESOLUTION_REQUIRED'
          and coalesce((residual.value->>'unresolved_count')::integer, 0) > 0
          and coalesce((residual.value->>'reservation_overrun_count')::integer, 0) = 0
          and coalesce((residual.value->>'component_count')::integer, 0) > 0
          and coalesce(residual.value->>'root_timesheet_id', '')
                ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        order by (residual.value->>'root_timesheet_id')::uuid
      );

      v_resolution_pending_member_ids := ARRAY(
        select distinct pending_id
        from unnest(
          coalesce(v_resolution_pending_member_ids, array[]::uuid[])
          || coalesce(v_candidate_pending_member_ids, array[]::uuid[])
        ) pending_id
        order by pending_id
      );

      v_resolution_pending_root_ids := ARRAY(
        select distinct pending_id
        from unnest(
          coalesce(v_resolution_pending_root_ids, array[]::uuid[])
          || coalesce(v_candidate_pending_root_ids, array[]::uuid[])
        ) pending_id
        order by pending_id
      );

      if exists(
        select 1
        from jsonb_array_elements(v_residuals) r
        where coalesce((r->>'draftable')::boolean,false) is not true
          and not (
            coalesce(r->>'block_code','')
              = 'CORRECTION_CHAIN_PAY_METHOD_RESOLUTION_REQUIRED'
            and coalesce((r->>'unresolved_count')::integer,0) > 0
            and coalesce((r->>'reservation_overrun_count')::integer,0) = 0
            and coalesce((r->>'component_count')::integer,0) > 0
          )
          and not (
            coalesce(r->>'block_code','') = 'CORRECTION_CHAIN_RESERVATION_OVERRUN'
            and coalesce((r->>'reservation_overrun_count')::integer,0) > 0
            and exists (
              select 1
              from private.banking_pay_workbench_economic_build_facts active_batch_item
              where active_batch_item.build_id=p_build_id
                and active_batch_item.fact_family='PROTECTION_EVIDENCE'
                and active_batch_item.source_relation='pay_batch_items'
                and active_batch_item.candidate_id=v_correction_candidate
                and active_batch_item.source_payload_json->>'protection_kind'
                  ='ACTIVE_CORRECTION_CHAIN_BATCH_ITEM'
                and coalesce(
                  active_batch_item.source_payload_json #>> '{frozen_component_snapshot_json,correction_root_id}',
                  active_batch_item.source_payload_json #>> '{frozen_resolution_payload_json,correction_root_id}',
                  '')=coalesce(r->>'root_timesheet_id','')
            )
          )
          and (
            coalesce(array_length(p_force_include_timesheet_ids,1),0)=0
            or exists (
              select 1
              from jsonb_array_elements_text(
                coalesce(r->'member_timesheet_ids','[]'::jsonb)
              ) member_id(value)
              where member_id.value::uuid
                    = any(coalesce(p_force_include_timesheet_ids,array[]::uuid[]))
            )
          )
      ) then
        raise exception 'CORRECTION_RESIDUAL_NOT_READY_FOR_OVERPAYMENT_SYNC' using errcode='P0001',detail=v_residuals::text;
      end if;
    end loop;
  end;
  v_correction_residuals_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();
  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_START',
    jsonb_build_object(
      'pay_date', p_pay_date,
      'week_ending_cutoff', p_week_ending_cutoff,
      'pay_channel_scope', p_pay_channel_scope,
      'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
      'force_include_timesheet_count', COALESCE(array_length(p_force_include_timesheet_ids, 1), 0),
      'exclude_timesheet_count', COALESCE(array_length(p_exclude_timesheet_ids, 1), 0)
    ),
    'pay_sync_overpayments',
    COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  if p_pay_date is null then
    raise exception 'pay_date is required';
  end if;

  if p_week_ending_cutoff is null then
    raise exception 'week_ending_cutoff is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if v_scope not in ('PAYE', 'UMBRELLA') then
    raise exception 'Invalid pay_channel_scope (expected PAYE or UMBRELLA)';
  end if;

  v_requested_candidate_count := COALESCE(array_length(p_candidate_ids, 1), 0);

  v_authoritative_timesheet_scope_requested := LOWER(BTRIM(COALESCE(
    p_mismatch_choices->>'overpayment_sync_authoritative_timesheet_scope',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_sync_authority_token := NULLIF(BTRIM(COALESCE(
    p_mismatch_choices->>'overpayment_sync_authority_token',
    ''
  )), '');
  v_current_sync_authority_token := NULLIF(BTRIM(COALESCE(
    current_setting('cloudtms.pay_workbench_overpayment_sync_token', true),
    ''
  )), '');

  IF COALESCE(v_authoritative_timesheet_scope_requested, false)
     AND (
       p_force_include_timesheet_ids IS NULL
       OR v_sync_authority_token IS NULL
       OR v_current_sync_authority_token IS NULL
       OR v_sync_authority_token IS DISTINCT FROM v_current_sync_authority_token
     ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_AUTHORITY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_AUTHORITY_INVALID',
              'message', 'Authoritative Timesheet scope is internal Workbench authority and requires the matching transaction-local source-build token.',
              'force_include_argument_supplied', p_force_include_timesheet_ids IS NOT NULL,
              'authority_token_supplied', v_sync_authority_token IS NOT NULL,
              'transaction_authority_present', v_current_sync_authority_token IS NOT NULL
            )::text;
  END IF;

  v_authoritative_timesheet_scope := COALESCE(v_authoritative_timesheet_scope_requested, false)
    AND p_force_include_timesheet_ids IS NOT NULL
    AND v_sync_authority_token IS NOT NULL
    AND v_sync_authority_token = v_current_sync_authority_token;

  v_explicit_empty_timesheet_scope := COALESCE(v_authoritative_timesheet_scope, false)
    AND COALESCE(array_length(p_force_include_timesheet_ids, 1), 0) = 0;

  v_preview_scope_strategy := CASE
    WHEN COALESCE(v_authoritative_timesheet_scope, false)
     AND COALESCE(array_length(p_force_include_timesheet_ids, 1), 0) > 0
      THEN 'TARGETED_TIMESHEETS'
    WHEN COALESCE(v_authoritative_timesheet_scope, false)
      THEN 'AUTHORITATIVE_EMPTY'
    ELSE 'CANDIDATE_FULL_LIVE'
  END;

  v_preview_decisions_json := (
      CASE
        WHEN jsonb_typeof(COALESCE(p_mismatch_choices, '{}'::jsonb)) = 'object'
          THEN COALESCE(p_mismatch_choices, '{}'::jsonb)
        ELSE '{}'::jsonb
      END
      - 'refresh_scope_kind'
      - 'targeted_timesheet_ids'
      - 'targeted_timesheet_ids_requested'
      - 'linked_timesheet_ids'
      - 'linked_timesheet_ids_requested'
      - 'source_build_allow_full_fallback'
      - 'overpayment_sync_authority_token'
      - 'overpayment_sync_authoritative_timesheet_scope'
      - 'authoritative_timesheet_scope'
      - 'exact_timesheet_scope'
      - 'workbench_session_id'
      - 'source_build_run_id'
      - 'source_change_seq'
      - 'session_version'
      - 'overpayment_sync_scope_digest'
      - 'overpayment_sync_negative_component_digest'
      - 'overpayment_sync_settled_baseline_digest'
      - 'policy_x_authority_scope'
    )
    || jsonb_build_object(
      'overpayment_sync_mode', true,
      'emit_raw_overpayment_components', true,
      'preview_context_mode', CASE WHEN v_requested_candidate_count = 1 THEN 'FULL_COMPAT' ELSE 'PAGE' END,
      'scope_limit', LEAST(GREATEST(COALESCE(v_requested_candidate_count, 1), 1), 100),
      'pay_channel_scope', v_scope,
      'candidate_ids', COALESCE(to_jsonb(p_candidate_ids), '[]'::jsonb),
      'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
      'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb),
      'overpayment_sync_preview_scope_strategy', v_preview_scope_strategy
    )
    || CASE
      WHEN v_preview_scope_strategy = 'TARGETED_TIMESHEETS' THEN
        jsonb_build_object(
          'refresh_scope_kind', 'TARGETED_TIMESHEETS',
          'targeted_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
          'targeted_timesheet_ids_requested', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
          'linked_timesheet_ids', '[]'::jsonb,
          'linked_timesheet_ids_requested', '[]'::jsonb,
          'source_build_allow_full_fallback', false,
          'overpayment_sync_explicit_empty_scope', false
        )
      ELSE
        jsonb_build_object(
          'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
          'targeted_timesheet_ids', '[]'::jsonb,
          'targeted_timesheet_ids_requested', '[]'::jsonb,
          'linked_timesheet_ids', '[]'::jsonb,
          'linked_timesheet_ids_requested', '[]'::jsonb,
          'overpayment_sync_explicit_empty_scope', COALESCE(v_explicit_empty_timesheet_scope, false)
        )
    END
    || CASE
      WHEN COALESCE(v_authoritative_timesheet_scope, false) THEN
        jsonb_build_object(
          'workbench_source_build_mode', true,
          'source_build_mode', true,
          'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'overpayment_sync_authority_token', v_sync_authority_token
        )
      ELSE '{}'::jsonb
    END;


  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
    WHERE requested_candidate.candidate_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_ID_INVALID',
              'message', 'candidate_ids must not contain null values.'
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])) AS included_timesheet(timesheet_id)
    WHERE included_timesheet.timesheet_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_FORCE_INCLUDE_TIMESHEET_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_FORCE_INCLUDE_TIMESHEET_ID_INVALID',
              'message', 'force_include_timesheet_ids must not contain null values.'
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])) AS excluded_timesheet(timesheet_id)
    WHERE excluded_timesheet.timesheet_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_EXCLUDE_TIMESHEET_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_EXCLUDE_TIMESHEET_ID_INVALID',
              'message', 'exclude_timesheet_ids must not contain null values.'
            )::text;
  END IF;

  IF v_requested_candidate_count > 100 THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_TOO_LARGE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_TOO_LARGE',
              'candidate_count', v_requested_candidate_count,
              'limit', 100,
              'message', 'Supply at most 100 explicit candidate IDs per bounded reconciliation call.'
            )::text;
  END IF;

  IF COALESCE(v_authoritative_timesheet_scope, false) THEN
    IF v_requested_candidate_count IS DISTINCT FROM 1 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SINGLE_CANDIDATE_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SINGLE_CANDIDATE_REQUIRED',
                'candidate_count', v_requested_candidate_count
              )::text;
    END IF;

    v_workbench_session_id_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'workbench_session_id', '')), '');
    v_source_build_run_id_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'source_build_run_id', '')), '');
    v_session_version_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'session_version', '')), '');

    IF v_workbench_session_id_text IS NULL
       OR v_workbench_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_source_build_run_id_text IS NULL
       OR v_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_session_version_text IS NULL
       OR v_session_version_text !~ '^[0-9]{1,18}$'
       OR NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_scope_digest', '')), '') IS NULL
       OR UPPER(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', ''))) <> 'PRE_DRAFT_LIVE_TRUTH' THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_METADATA_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_METADATA_INVALID',
                'workbench_session_id', v_workbench_session_id_text,
                'source_build_run_id', v_source_build_run_id_text,
                'session_version', v_session_version_text,
                'policy_x_authority_scope', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', '')), '')
              )::text;
    END IF;

    v_workbench_session_id := v_workbench_session_id_text::uuid;
    v_source_build_run_id := v_source_build_run_id_text::uuid;
    v_workbench_session_version := v_session_version_text::bigint;

    v_authoritative_candidate_id := p_candidate_ids[1];

    -- Supabase preloads plpgsql_check with fatal nested-statement inspection.
    -- Keep this predicate in its bounded owner-only SQL helper so the deeply
    -- nested PL/pgSQL frame does not corrupt pldbgapi2's parent stack.
    v_authoritative_session_valid :=
      public._pay_workbench_authoritative_scope_valid_v1(
      v_workbench_session_id,
      v_authoritative_candidate_id,
      v_workbench_session_version,
      p_actor_user_id,
      p_pay_date,
      p_week_ending_cutoff,
      v_scope
    );

    IF COALESCE(v_authoritative_session_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SESSION_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SESSION_INVALID',
                'workbench_session_id', v_workbench_session_id::text,
                'source_build_run_id', v_source_build_run_id::text,
                'session_version', v_workbench_session_version,
                'candidate_id', v_authoritative_candidate_id::text,
                'pay_channel_scope', v_scope
              )::text;
    END IF;

    IF EXISTS (
      WITH candidate_authority_seed_timesheets AS (
        SELECT authoritative_tsfin.timesheet_id
        FROM public.timesheets_financials AS authoritative_tsfin
        WHERE authoritative_tsfin.candidate_id = v_authoritative_candidate_id
          AND authoritative_tsfin.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_case.linked_timesheet_id
        FROM public.pay_advances AS authoritative_case
        WHERE authoritative_case.candidate_id = v_authoritative_candidate_id
          AND authoritative_case.linked_timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_component.linked_timesheet_id
        FROM public.pay_finance_case_components AS authoritative_component
        WHERE authoritative_component.candidate_id = v_authoritative_candidate_id
          AND authoritative_component.linked_timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_override.timesheet_id
        FROM public.timesheet_payment_overrides AS authoritative_override
        WHERE authoritative_override.candidate_id = v_authoritative_candidate_id
          AND authoritative_override.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_adjustment.timesheet_id
        FROM public.ts_pay_adjustments AS authoritative_adjustment
        WHERE authoritative_adjustment.candidate_id = v_authoritative_candidate_id
          AND authoritative_adjustment.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_snooze.timesheet_id
        FROM public.pay_item_snoozes AS authoritative_snooze
        WHERE authoritative_snooze.candidate_id = v_authoritative_candidate_id
          AND authoritative_snooze.timesheet_id IS NOT NULL
          AND authoritative_snooze.cleared_at_utc IS NULL
          AND authoritative_snooze.cancelled_at_utc IS NULL

        UNION

        SELECT authoritative_batch_item.timesheet_id
        FROM public.pay_batch_candidates AS authoritative_batch_candidate
        JOIN public.pay_batch_items AS authoritative_batch_item
          ON authoritative_batch_item.pay_batch_candidate_id = authoritative_batch_candidate.id
        WHERE authoritative_batch_candidate.candidate_id = v_authoritative_candidate_id
          AND authoritative_batch_item.timesheet_id IS NOT NULL
          AND COALESCE(authoritative_batch_item.is_voided, false) IS NOT TRUE

        UNION

        SELECT authoritative_correction.timesheet_id
        FROM public.pay_payment_correction_items AS authoritative_correction
        WHERE authoritative_correction.candidate_id = v_authoritative_candidate_id
          AND authoritative_correction.timesheet_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(authoritative_correction.status, ''))) = 'APPLIED'
      ), candidate_authority_seed_array AS (
        SELECT COALESCE(
          ARRAY_AGG(
            DISTINCT candidate_authority_seed_timesheets.timesheet_id
            ORDER BY candidate_authority_seed_timesheets.timesheet_id
          ),
          ARRAY[]::uuid[]
        ) AS timesheet_ids
        FROM candidate_authority_seed_timesheets
      ), candidate_authority_timesheets AS (
        SELECT candidate_authority_seed_timesheets.timesheet_id
        FROM candidate_authority_seed_timesheets

        UNION

        SELECT authority_rotation.canonical_timesheet_id
        FROM candidate_authority_seed_array
        JOIN public._pay_timesheet_rotation_scope(
          candidate_authority_seed_array.timesheet_ids
        ) AS authority_rotation
          ON true
        WHERE authority_rotation.canonical_timesheet_id IS NOT NULL

        UNION

        SELECT authority_rotation.family_timesheet_id
        FROM candidate_authority_seed_array
        JOIN public._pay_timesheet_rotation_scope(
          candidate_authority_seed_array.timesheet_ids
        ) AS authority_rotation
          ON true
        WHERE authority_rotation.family_timesheet_id IS NOT NULL
      )
      SELECT 1
      FROM unnest(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])) AS authoritative_timesheet(timesheet_id)
      WHERE NOT EXISTS (
        SELECT 1
        FROM candidate_authority_timesheets AS candidate_authority
        WHERE candidate_authority.timesheet_id = authoritative_timesheet.timesheet_id
      )
    ) THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_CANDIDATE_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_CANDIDATE_MISMATCH',
                'candidate_id', v_authoritative_candidate_id::text,
                'scope_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb)
              )::text;
    END IF;
  END IF;

  IF COALESCE(v_explicit_empty_timesheet_scope, false) THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_RESULT',
      jsonb_build_object(
        'pay_channel_scope', v_scope,
        'authoritative_timesheet_scope', true,
        'explicit_empty_timesheet_scope', true,
        'preview_scope_strategy', v_preview_scope_strategy,
        'candidate_count', v_requested_candidate_count,
        'cases_inserted', 0,
        'cases_touched', 0,
        'cases_amended', 0,
        'cases_reopened', 0,
        'cases_cleared', 0
      ),
      'pay_sync_overpayments',
      COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RETURN jsonb_build_object(
      'ok', true,
      'pay_channel_scope', v_scope,
      'authoritative_timesheet_scope', true,
      'explicit_empty_timesheet_scope', true,
      'preview_scope_strategy', v_preview_scope_strategy,
      'scope_timesheet_ids', '[]'::jsonb,
      'requested_candidate_count', v_requested_candidate_count,
      'preview_candidate_count', 0,
      'preview_candidate_coverage_complete', true,
      'negative_preview_timesheets_count', 0,
      'negative_preview_timesheets', '[]'::jsonb,
      'underpayment_case_count', 0,
      'underpayment_cases', '[]'::jsonb,
      'timesheet_finance_case_candidates_count', 0,
      'timesheet_finance_case_candidates', '[]'::jsonb,
      'cases_inserted', 0,
      'cases_touched', 0,
      'cases_amended', 0,
      'cases_reopened', 0,
      'cases_cleared', 0
    );
  END IF;

  create temporary table if not exists pg_temp.tmp_sync_timesheet_case_candidates (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    client_id uuid null,
    linked_shift_date date null,
    corrected_amount_ex numeric(12,2) not null,
    baseline_signature text null,
    candidate_pay_method text not null,
    case_is_blocked boolean not null,
    needs_lifecycle_tracking boolean not null default false,
    overpayment_amount_ex numeric(12,2) not null,
    underpayment_amount_ex numeric(12,2) not null,
    desired_case_type public.pay_finance_case_type_enum null,
    desired_advance_kind public.pay_advance_kind_enum null,
    desired_reason public.pay_advance_reason_enum null,
    source_original_paid_amount numeric(12,2) null,
    source_corrected_paid_amount numeric(12,2) null,
    components_sync_json jsonb not null default '[]'::jsonb,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_case_links (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    finance_case_id uuid not null,
    desired_case_type public.pay_finance_case_type_enum not null,
    source_original_paid_amount numeric(12,2) not null,
    source_corrected_paid_amount numeric(12,2) not null,
    case_amount_ex numeric(12,2) not null,
    linked_shift_date date null,
    baseline_signature text null,
    components_sync_json jsonb not null,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_case_clears (
    finance_case_id uuid not null primary key,
    candidate_id uuid not null,
    timesheet_id uuid not null,
    old_case_type public.pay_finance_case_type_enum not null,
    old_original_amount numeric(12,2) not null,
    old_outstanding_amount numeric(12,2) not null,
    old_source_original_paid_amount numeric(12,2) null,
    old_source_corrected_paid_amount numeric(12,2) null,
    old_linked_shift_date date null,
    old_baseline_signature text null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_preview_candidates (
    candidate_id uuid not null primary key,
    candidate_json jsonb not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_authoritative_negative_components (
    timesheet_id uuid not null,
    key_type text not null,
    key_value text not null,
    truth_ex_vat numeric(12,2) not null,
    baseline_ex_vat numeric(12,2) not null,
    reserved_ex_vat numeric(12,2) not null,
    outstanding_ex_vat numeric(12,2) not null,
    baseline_signature text null,
    primary key (timesheet_id, key_type, key_value)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_authoritative_components (
    timesheet_id uuid not null,
    key_type text not null,
    key_value text not null,
    truth_ex_vat numeric(12,2) not null,
    baseline_ex_vat numeric(12,2) not null,
    reserved_ex_vat numeric(12,2) not null,
    outstanding_ex_vat numeric(12,2) not null,
    baseline_signature text null,
    primary key (timesheet_id, key_type, key_value)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_raw_negative_timesheet_rows (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    client_id uuid null,
    candidate_pay_method text not null,
    case_is_blocked boolean not null,
    case_components_json jsonb not null default '[]'::jsonb,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  truncate table pg_temp.tmp_sync_timesheet_case_candidates;
  truncate table pg_temp.tmp_sync_case_links;
  truncate table pg_temp.tmp_sync_case_clears;
  truncate table pg_temp.tmp_sync_preview_candidates;
  truncate table pg_temp.tmp_sync_authoritative_negative_components;
  truncate table pg_temp.tmp_sync_authoritative_components;
  truncate table pg_temp.tmp_sync_raw_negative_timesheet_rows;

  v_authority_validation_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  IF COALESCE(v_authoritative_timesheet_scope, false) THEN
    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_finance_case_authority;
    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_finance_case_authority ON COMMIT DROP AS
    SELECT fact.build_id,fact.candidate_id,fact.finance_case_id,
      COUNT(*)::integer AS evidence_count,
      COUNT(DISTINCT UPPER(NULLIF(BTRIM(fact.source_payload_json->>'case_type'),'')))::integer
        AS distinct_case_type_count,
      MIN(UPPER(NULLIF(BTRIM(fact.source_payload_json->>'case_type'),''))) AS case_type
    FROM private.banking_pay_workbench_economic_build_facts fact
    WHERE fact.build_id=p_build_id
      AND fact.fact_family='FINANCE_CASE_IDENTITY'
      AND fact.finance_case_id IS NOT NULL
    GROUP BY fact.build_id,fact.candidate_id,fact.finance_case_id;

    CREATE UNIQUE INDEX tmp_sync_sealed_finance_case_authority_idx
      ON pg_temp.tmp_sync_sealed_finance_case_authority(
        build_id,candidate_id,finance_case_id);

    INSERT INTO pg_temp.tmp_sync_authoritative_components (
      timesheet_id,
      key_type,
      key_value,
      truth_ex_vat,
      baseline_ex_vat,
      reserved_ex_vat,
      outstanding_ex_vat,
      baseline_signature
    )
    WITH live_entitlement_components AS (
      SELECT
        entitlement_component.timesheet_id,
        UPPER(BTRIM(entitlement_component.key_type)) AS key_type,
        BTRIM(entitlement_component.key_value) AS key_value,
        ROUND(COALESCE(entitlement_component.truth_ex_vat, 0), 2)::numeric(12,2) AS truth_ex_vat,
        ROUND(COALESCE(entitlement_component.baseline_ex_vat, 0), 2)::numeric(12,2) AS baseline_ex_vat
      FROM (
        SELECT legacy_component.*
        FROM private.pay_current_timesheet_entitlement_components_from_build_v1(
          p_build_id,NULL::text
        ) AS legacy_component
        WHERE v_execution_profile_version = 1
        UNION ALL
        SELECT cached_component.*
        FROM pg_temp.tmp_sync_entitlement_components_v2 AS cached_component
        WHERE v_execution_profile_version = 2
      ) AS entitlement_component
      WHERE NULLIF(BTRIM(COALESCE(entitlement_component.key_type, '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(entitlement_component.key_value, '')), '') IS NOT NULL
        AND (NOT v_slice_active OR entitlement_component.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */
    ), active_entitlement_reservations AS (
      SELECT
        reserved_component.timesheet_id,
        UPPER(BTRIM(reserved_component.key_type)) AS key_type,
        BTRIM(reserved_component.key_value) AS key_value,
        ROUND(COALESCE(reserved_component.amount_ex_vat, 0), 2)::numeric(12,2) AS reserved_ex_vat
      FROM (
        SELECT fact.timesheet_id,fact.economic_key_type AS key_type,
          fact.economic_key_value AS key_value,
          SUM(CASE
            WHEN case_authority.evidence_count=1
              AND case_authority.distinct_case_type_count=1
              AND case_authority.case_type='OVERPAYMENT'
              THEN -ABS(COALESCE(fact.reserved_source_amount,0))
            ELSE COALESCE(fact.reserved_source_amount,0)
          END) AS amount_ex_vat
        FROM private.banking_pay_workbench_economic_build_facts fact
        LEFT JOIN pg_temp.tmp_sync_sealed_finance_case_authority case_authority
          ON case_authority.build_id=fact.build_id
         AND case_authority.candidate_id=fact.candidate_id
         AND case_authority.finance_case_id=fact.finance_case_id
        WHERE fact.build_id=p_build_id AND fact.fact_family='RESERVATION_COMPONENT'
          AND (NOT v_slice_active OR fact.timesheet_id=ANY(v_bounded_scope_ids)
            OR (fact.timesheet_id IS NULL AND v_slice_final)) /* A28 */
        GROUP BY fact.timesheet_id,fact.economic_key_type,fact.economic_key_value
      ) AS reserved_component
      WHERE NULLIF(BTRIM(COALESCE(reserved_component.key_type, '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(reserved_component.key_value, '')), '') IS NOT NULL
    ), live_economic_keys AS (
      SELECT
        live_component.timesheet_id,
        live_component.key_type,
        live_component.key_value
      FROM live_entitlement_components AS live_component

      UNION

      SELECT
        reserved_component.timesheet_id,
        reserved_component.key_type,
        reserved_component.key_value
      FROM active_entitlement_reservations AS reserved_component
    ), raw_outstanding_components AS (
      SELECT
        live_key.timesheet_id,
        live_key.key_type,
        live_key.key_value,
        ROUND(COALESCE(live_component.truth_ex_vat, 0), 2)::numeric(12,2) AS truth_ex_vat,
        ROUND(COALESCE(live_component.baseline_ex_vat, 0), 2)::numeric(12,2) AS baseline_ex_vat,
        ROUND(COALESCE(reserved_component.reserved_ex_vat, 0), 2)::numeric(12,2) AS reserved_ex_vat,
        ROUND(
          COALESCE(live_component.truth_ex_vat, 0)
          - COALESCE(live_component.baseline_ex_vat, 0)
          - COALESCE(reserved_component.reserved_ex_vat, 0),
          2
        )::numeric(12,2) AS outstanding_ex_vat
      FROM live_economic_keys AS live_key
      LEFT JOIN live_entitlement_components AS live_component
        ON live_component.timesheet_id = live_key.timesheet_id
       AND live_component.key_type = live_key.key_type
       AND live_component.key_value = live_key.key_value
      LEFT JOIN active_entitlement_reservations AS reserved_component
        ON reserved_component.timesheet_id = live_key.timesheet_id
       AND reserved_component.key_type = live_key.key_type
       AND reserved_component.key_value = live_key.key_value
    )
    SELECT
      raw_component.timesheet_id,
      raw_component.key_type,
      raw_component.key_value,
      raw_component.truth_ex_vat,
      raw_component.baseline_ex_vat,
      raw_component.reserved_ex_vat,
      raw_component.outstanding_ex_vat,
      COALESCE(active_settled_basis.active_settled_signature,md5('[]')) AS baseline_signature
    FROM raw_outstanding_components AS raw_component
    LEFT JOIN LATERAL (
      SELECT
        COUNT(*)::integer AS active_settled_component_count,
        md5(COALESCE(jsonb_agg(
          jsonb_build_object(
            'key_type', active_settled_component.key_type,
            'key_value', active_settled_component.key_value,
            'amount_ex_vat', ROUND(COALESCE(active_settled_component.amount_ex_vat, 0), 2),
            'amount_inc_vat', ROUND(COALESCE(active_settled_component.amount_inc_vat, 0), 2)
          ) ORDER BY active_settled_component.key_type, active_settled_component.key_value
        )::text, '[]')) AS active_settled_signature
      FROM (
        SELECT fact.economic_key_type AS key_type,fact.economic_key_value AS key_value,
          fact.amount_ex_vat,fact.amount_inc_vat
        FROM private.banking_pay_workbench_economic_build_facts fact
        WHERE fact.build_id=p_build_id AND fact.timesheet_id=raw_component.timesheet_id
          AND fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
      ) AS active_settled_component
      HAVING v_execution_profile_version = 1

      UNION ALL

      SELECT cached_basis.active_settled_component_count,cached_basis.active_settled_signature
      FROM pg_temp.tmp_sync_settled_basis_by_timesheet_v2 cached_basis
      WHERE v_execution_profile_version = 2
        AND cached_basis.timesheet_id=raw_component.timesheet_id
    ) AS active_settled_basis ON true
    ;

    INSERT INTO pg_temp.tmp_sync_authoritative_negative_components(
      timesheet_id,key_type,key_value,truth_ex_vat,baseline_ex_vat,
      reserved_ex_vat,outstanding_ex_vat,baseline_signature
    )
    SELECT timesheet_id,key_type,key_value,truth_ex_vat,baseline_ex_vat,
      reserved_ex_vat,outstanding_ex_vat,baseline_signature
    FROM pg_temp.tmp_sync_authoritative_components
    WHERE outstanding_ex_vat < 0;

    PERFORM public._ctms_rewrite_sync_authoritative_correction_negative_components_v1(
      nullif(btrim(p_mismatch_choices->>'workbench_session_id'), '')::uuid,
      v_authoritative_candidate_id,
      coalesce(p_force_include_timesheet_ids, array[]::uuid[])
    );

    SELECT
      COUNT(*)::integer,
      md5(COALESCE(jsonb_agg(
        jsonb_build_object(
          'timesheet_id', negative_component.timesheet_id::text,
          'key_type', negative_component.key_type,
          'key_value', negative_component.key_value,
          'truth_ex_vat', ROUND(negative_component.truth_ex_vat, 2)::numeric(12,2),
          'baseline_ex_vat', ROUND(negative_component.baseline_ex_vat, 2)::numeric(12,2),
          'reserved_ex_vat', ROUND(negative_component.reserved_ex_vat, 2)::numeric(12,2),
          'outstanding_ex_vat', ROUND(negative_component.outstanding_ex_vat, 2)::numeric(12,2)
        ) ORDER BY negative_component.timesheet_id, negative_component.key_type, negative_component.key_value
      )::text, '[]'))
    INTO
      v_authoritative_negative_component_count,
      v_authoritative_negative_component_digest
    FROM pg_temp.tmp_sync_authoritative_negative_components AS negative_component;

    SELECT md5(COALESCE(jsonb_agg(
      jsonb_build_object(
        'timesheet_id', settled_component.timesheet_id::text,
        'key_type', settled_component.key_type,
        'key_value', settled_component.key_value,
        'amount_ex_vat', ROUND(COALESCE(settled_component.amount_ex_vat, 0), 2),
        'amount_inc_vat', ROUND(COALESCE(settled_component.amount_inc_vat, 0), 2)
      ) ORDER BY settled_component.timesheet_id, settled_component.key_type, settled_component.key_value
    )::text, '[]'))
    INTO v_authoritative_settled_baseline_digest
    FROM (
      SELECT fact.timesheet_id,fact.economic_key_type AS key_type,
        fact.economic_key_value AS key_value,fact.amount_ex_vat,fact.amount_inc_vat
      FROM private.banking_pay_workbench_economic_build_facts fact
      WHERE fact.build_id=p_build_id
        AND fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
    ) AS settled_component;

    -- These two attestations are private build authority.  They are derived
    -- only after immutable fact materialisation; caller/job values were
    -- stripped above and can never assert them.
    v_expected_negative_component_digest := v_authoritative_negative_component_digest;
    v_expected_settled_baseline_digest := v_authoritative_settled_baseline_digest;
    p_mismatch_choices:=p_mismatch_choices||jsonb_build_object(
      'overpayment_sync_negative_component_digest',v_expected_negative_component_digest,
      'overpayment_sync_settled_baseline_digest',v_expected_settled_baseline_digest);

    IF v_authoritative_negative_component_digest IS DISTINCT FROM v_expected_negative_component_digest
       OR v_authoritative_settled_baseline_digest IS DISTINCT FROM v_expected_settled_baseline_digest THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_COMPONENT_DIGEST_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_COMPONENT_DIGEST_MISMATCH',
                'candidate_id', v_authoritative_candidate_id::text,
                'negative_component_count', COALESCE(v_authoritative_negative_component_count, 0),
                'expected_negative_component_digest', v_expected_negative_component_digest,
                'actual_negative_component_digest', v_authoritative_negative_component_digest,
                'expected_settled_baseline_digest', v_expected_settled_baseline_digest,
                'actual_settled_baseline_digest', v_authoritative_settled_baseline_digest,
                'message', 'The Workbench negative-component or settled-baseline authority changed before finance-case synchronisation.'
              )::text;
    END IF;
  END IF;

  IF COALESCE(v_authoritative_timesheet_scope,false) THEN
    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_rate_projection_raw;
    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_rate_projection_failures;
    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_rate_projection;

    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_rate_projection_raw
    ON COMMIT DROP AS
    SELECT row_number() OVER(ORDER BY helper_row.timesheet_id NULLS FIRST,
        helper_row.economic_key_type NULLS FIRST,helper_row.economic_key_value NULLS FIRST,
        helper_row.physical_bucket_key NULLS FIRST,helper_row.failure_code NULLS FIRST,
        helper_row.evidence_json::text)::bigint AS materialization_ordinal,
      helper_row.*
    FROM private.pay_workbench_sealed_rate_component_projection_v1(
      p_build_id,v_bounded_build.candidate_id,
      CASE WHEN p_force_include_timesheet_ids IS NULL THEN NULL::uuid[]
        ELSE p_force_include_timesheet_ids END
    ) helper_row;

    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_rate_projection_failures(
      failure_rank integer NOT NULL,failure_code text NOT NULL,timesheet_id uuid,
      economic_key_type text,economic_key_value text,physical_bucket_key text,
      detail_json jsonb NOT NULL
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 10,COALESCE(NULLIF(BTRIM(raw.failure_code),''),
        'RATE_AUTHORITY_FAILED_ROW_CODE_MISSING'),raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,raw.physical_bucket_key,
      jsonb_build_object('materialization_ordinal',raw.materialization_ordinal,
        'projection_status',raw.projection_status,'failure_code',raw.failure_code)
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,''))='FAILED';

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 20,'RATE_AUTHORITY_PHYSICAL_IDENTITY_INCOMPLETE',raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,raw.physical_bucket_key,
      jsonb_build_object('materialization_ordinal',raw.materialization_ordinal,
        'source_family_key',raw.source_family_key,'component_kind',raw.component_kind,
        'component_member_identity',raw.component_member_identity,'bucket_code',raw.bucket_code)
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,''))<>'FAILED'
      AND (raw.timesheet_id IS NULL OR NULLIF(BTRIM(raw.economic_key_type),'') IS NULL
        OR NULLIF(BTRIM(raw.economic_key_value),'') IS NULL
        OR NULLIF(BTRIM(raw.source_family_key),'') IS NULL
        OR NULLIF(BTRIM(raw.component_kind),'') IS NULL
        OR NULLIF(BTRIM(raw.component_member_identity),'') IS NULL
        OR NULLIF(BTRIM(raw.bucket_code),'') IS NULL
        OR NULLIF(BTRIM(raw.physical_bucket_key),'') IS NULL);

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 21,'RATE_AUTHORITY_SOURCE_PAY_METHOD_MISSING',raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,raw.physical_bucket_key,
      jsonb_build_object('materialization_ordinal',raw.materialization_ordinal,
        'source_pay_method',raw.source_pay_method)
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,''))<>'FAILED'
      AND (NULLIF(BTRIM(raw.source_pay_method),'') IS NULL
        OR UPPER(BTRIM(raw.source_pay_method)) NOT IN ('PAYE','UMBRELLA'));

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 22,'RATE_AUTHORITY_TARGET_PAY_METHOD_MISSING',raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,raw.physical_bucket_key,
      jsonb_build_object('materialization_ordinal',raw.materialization_ordinal,
        'target_pay_method',raw.target_pay_method)
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,''))<>'FAILED'
      AND (NULLIF(BTRIM(raw.target_pay_method),'') IS NULL
        OR UPPER(BTRIM(raw.target_pay_method)) NOT IN ('PAYE','UMBRELLA'));

    WITH key_methods AS MATERIALIZED (
      SELECT DISTINCT raw.timesheet_id,
        UPPER(BTRIM(raw.economic_key_type)) AS economic_key_type,
        BTRIM(raw.economic_key_value) AS economic_key_value,
        UPPER(BTRIM(raw.source_pay_method)) AS source_pay_method
      FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
      WHERE UPPER(COALESCE(raw.projection_status,'')) IN ('READY','FIXED')
        AND raw.failure_code IS NULL
    ), timesheet_methods AS MATERIALIZED (
      SELECT key_method.timesheet_id,
        COUNT(DISTINCT key_method.source_pay_method)::integer
          AS distinct_supported_method_count,
        COUNT(*)::integer AS economic_key_count,
        jsonb_agg(jsonb_build_object(
          'economic_key_type',key_method.economic_key_type,
          'economic_key_value',key_method.economic_key_value,
          'source_pay_method',key_method.source_pay_method)
          ORDER BY key_method.economic_key_type,key_method.economic_key_value,
            key_method.source_pay_method) AS complete_key_method_set
      FROM key_methods key_method
      GROUP BY key_method.timesheet_id
    )
    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 23,'RATE_AUTHORITY_SOURCE_PAY_METHOD_CONFLICT',method.timesheet_id,
      NULL::text,NULL::text,NULL::text,
      jsonb_build_object(
        'distinct_supported_method_count',method.distinct_supported_method_count,
        'economic_key_count',method.economic_key_count,
        'complete_economic_key_method_digest',pg_catalog.encode(extensions.digest(
          pg_catalog.convert_to(method.complete_key_method_set::text,'UTF8'),
          'sha256'),'hex'),
        'sample_truncated',method.economic_key_count>25,
        'economic_key_method_sample',pg_catalog.jsonb_path_query_array(
          method.complete_key_method_set,'$[0 to 24]'))
    FROM timesheet_methods method
    WHERE method.distinct_supported_method_count<>1;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 30,'RATE_AUTHORITY_DUPLICATE_PHYSICAL_BUCKET',duplicate.timesheet_id,
      duplicate.economic_key_type,duplicate.economic_key_value,
      duplicate.physical_bucket_key,
      jsonb_build_object('duplicate_count',duplicate.duplicate_count)
    FROM (
      SELECT raw.timesheet_id,raw.economic_key_type,raw.economic_key_value,
        raw.physical_bucket_key,count(*)::integer AS duplicate_count
      FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
      WHERE UPPER(COALESCE(raw.projection_status,''))<>'FAILED'
        AND raw.timesheet_id IS NOT NULL
        AND NULLIF(BTRIM(raw.economic_key_type),'') IS NOT NULL
        AND NULLIF(BTRIM(raw.economic_key_value),'') IS NOT NULL
        AND NULLIF(BTRIM(raw.physical_bucket_key),'') IS NOT NULL
      GROUP BY raw.timesheet_id,raw.economic_key_type,raw.economic_key_value,
        raw.physical_bucket_key HAVING count(*)>1
    ) duplicate;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 40,'RATE_AUTHORITY_TARGET_AUTHORITY_CONFLICT',NULL::uuid,NULL::text,
      NULL::text,NULL::text,jsonb_build_object(
        'target_method_count',count(DISTINCT raw.target_pay_method),
        'target_digest_count',count(DISTINCT raw.target_authority_digest),
        'conversion_digest_count',count(DISTINCT raw.conversion_context_digest))
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,'')) IN ('READY','FIXED')
    HAVING count(DISTINCT raw.target_pay_method)<>1
       OR count(DISTINCT raw.target_authority_digest)<>1
       OR count(DISTINCT raw.conversion_context_digest)<>1;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 45,'RATE_AUTHORITY_MULTIPLE_RATES_UNSUPPORTED',raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,MIN(raw.physical_bucket_key),
      jsonb_build_object('component_kind',raw.component_kind,
        'component_member_identity',raw.component_member_identity,
        'bucket_code',raw.bucket_code,
        'source_rate_count',count(DISTINCT ROUND(raw.source_rate,6)),
        'source_charge_rate_count',count(DISTINCT ROUND(raw.source_charge_rate,6)))
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,'')) IN ('READY','FIXED')
      AND raw.component_kind IN ('WORKED_TIME','ADDITIONAL_UNIT')
    GROUP BY raw.timesheet_id,raw.component_kind,raw.component_member_identity,
      raw.economic_key_type,raw.economic_key_value,raw.bucket_code
    HAVING count(DISTINCT ROUND(raw.source_rate,6))>1
       OR count(DISTINCT ROUND(raw.source_charge_rate,6))>1;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 50,'PAY_SYNC_OVERPAYMENTS_RATE_ECONOMIC_FENCE_MISMATCH',
      COALESCE(expected.timesheet_id,actual.timesheet_id),
      COALESCE(expected.key_type,actual.economic_key_type),
      COALESCE(expected.key_value,actual.economic_key_value),NULL::text,
      jsonb_build_object('expected_truth_ex_vat',expected.truth_ex_vat,
        'actual_truth_ex_vat',actual.truth_ex_vat,
        'expected_baseline_ex_vat',expected.baseline_ex_vat,
        'actual_baseline_ex_vat',actual.baseline_ex_vat,
        'expected_reserved_ex_vat',expected.reserved_ex_vat,
        'actual_reserved_ex_vat',actual.reserved_ex_vat,
        'expected_outstanding_ex_vat',expected.outstanding_ex_vat,
        'actual_outstanding_ex_vat',actual.outstanding_ex_vat)
    FROM pg_temp.tmp_sync_authoritative_components expected
    FULL OUTER JOIN (
      SELECT raw.timesheet_id,UPPER(BTRIM(raw.economic_key_type)) AS economic_key_type,
        BTRIM(raw.economic_key_value) AS economic_key_value,
        ROUND(SUM(raw.truth_ex_vat),2) AS truth_ex_vat,
        ROUND(SUM(raw.baseline_ex_vat),2) AS baseline_ex_vat,
        ROUND(SUM(raw.reserved_ex_vat),2) AS reserved_ex_vat,
        ROUND(SUM(raw.outstanding_ex_vat),2) AS outstanding_ex_vat
      FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
      WHERE UPPER(COALESCE(raw.projection_status,'')) IN ('READY','FIXED')
        AND raw.failure_code IS NULL
      GROUP BY raw.timesheet_id,UPPER(BTRIM(raw.economic_key_type)),
        BTRIM(raw.economic_key_value)
    ) actual ON actual.timesheet_id=expected.timesheet_id
      AND actual.economic_key_type=expected.key_type
      AND actual.economic_key_value=expected.key_value
    WHERE expected.timesheet_id IS NULL OR actual.timesheet_id IS NULL
      OR actual.truth_ex_vat IS DISTINCT FROM expected.truth_ex_vat
      OR actual.baseline_ex_vat IS DISTINCT FROM expected.baseline_ex_vat
      OR actual.reserved_ex_vat IS DISTINCT FROM expected.reserved_ex_vat
      OR actual.outstanding_ex_vat IS DISTINCT FROM expected.outstanding_ex_vat;

    v_rate_authority_failure_code:=NULL::text;
    v_rate_authority_failure_detail:='[]'::jsonb;

    SELECT failure.failure_code
    INTO v_rate_authority_failure_code
    FROM pg_temp.tmp_sync_sealed_rate_projection_failures failure
    ORDER BY failure.failure_rank,failure.timesheet_id NULLS FIRST,
      failure.economic_key_type NULLS FIRST,failure.economic_key_value NULLS FIRST,
      failure.physical_bucket_key NULLS FIRST,failure.failure_code
    LIMIT 1;

    SELECT COALESCE(jsonb_agg(jsonb_build_object('failure_rank',failure.failure_rank,
        'failure_code',failure.failure_code,'timesheet_id',failure.timesheet_id,
        'economic_key_type',failure.economic_key_type,
        'economic_key_value',failure.economic_key_value,
        'physical_bucket_key',failure.physical_bucket_key,
        'detail',failure.detail_json) ORDER BY failure.failure_rank,
        failure.timesheet_id NULLS FIRST,failure.economic_key_type NULLS FIRST,
        failure.economic_key_value NULLS FIRST,failure.physical_bucket_key NULLS FIRST,
        failure.failure_code),'[]'::jsonb)
    INTO v_rate_authority_failure_detail
    FROM pg_temp.tmp_sync_sealed_rate_projection_failures failure;

    IF v_rate_authority_failure_code IS NOT NULL THEN
      RAISE EXCEPTION '%',v_rate_authority_failure_code USING ERRCODE='P0001',
        DETAIL=jsonb_build_object('code',v_rate_authority_failure_code,
          'failures',v_rate_authority_failure_detail)::text;
    END IF;

    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_rate_projection ON COMMIT DROP AS
    SELECT raw.build_id,raw.candidate_id,raw.timesheet_id,raw.financial_row_id,
      raw.source_family_key,raw.economic_key_type,raw.economic_key_value,
      raw.component_kind,raw.component_member_identity,raw.segment_id,raw.segment_key,
      raw.segment_stable_key,raw.bucket_code,raw.bucket_sort_ordinal,
      raw.physical_bucket_key,raw.physical_bucket_digest,raw.source_units,
      raw.source_rate,raw.source_charge_rate,raw.truth_ex_vat,raw.baseline_ex_vat,
      raw.reserved_ex_vat,raw.outstanding_ex_vat,raw.source_charge_ex_vat,
      raw.source_pay_method,raw.target_pay_method,raw.umbrella_id,
      raw.umbrella_enabled,raw.umbrella_vat_chargeable,raw.erni_pct,raw.vat_rate_pct,
      raw.financial_revision_digest,raw.target_authority_digest,
      raw.conversion_context_digest,raw.sealed_evidence_digest,
      raw.projection_status,raw.failure_code,raw.evidence_json
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(raw.projection_status) IN ('READY','FIXED') AND raw.failure_code IS NULL;

    ALTER TABLE pg_temp.tmp_sync_sealed_rate_projection
      ALTER COLUMN timesheet_id SET NOT NULL,
      ALTER COLUMN economic_key_type SET NOT NULL,
      ALTER COLUMN economic_key_value SET NOT NULL,
      ALTER COLUMN source_family_key SET NOT NULL,
      ALTER COLUMN component_kind SET NOT NULL,
      ALTER COLUMN component_member_identity SET NOT NULL,
      ALTER COLUMN bucket_code SET NOT NULL,
      ALTER COLUMN physical_bucket_key SET NOT NULL,
      ALTER COLUMN physical_bucket_digest SET NOT NULL,
      ALTER COLUMN source_pay_method SET NOT NULL,
      ALTER COLUMN target_pay_method SET NOT NULL,
      ALTER COLUMN projection_status SET NOT NULL,
      ALTER COLUMN evidence_json SET NOT NULL,
      ADD CHECK (projection_status IN ('READY','FIXED')),
      ADD PRIMARY KEY(timesheet_id,economic_key_type,economic_key_value,physical_bucket_key);
    CREATE INDEX tmp_sync_sealed_rate_projection_lookup_idx
      ON pg_temp.tmp_sync_sealed_rate_projection(
        timesheet_id,source_family_key,economic_key_type,economic_key_value,bucket_code);

    /* The legacy pre-Draft renderer is allowed to omit an economic component
       whose live truth is zero.  Preserve every renderer-owned component as-is,
       but retain an exact physical-bucket map so a frozen baseline-only
       component can be supplied from the already validated sealed projection
       when (and only when) the renderer has no owner for that bucket. */
    DROP TABLE IF EXISTS pg_temp.tmp_sync_raw_preview_physical_components;
    CREATE TEMP TABLE pg_temp.tmp_sync_raw_preview_physical_components (
      candidate_id uuid NOT NULL,
      timesheet_id uuid NOT NULL,
      component_ordinality bigint NOT NULL,
      physical_bucket_key text NULL,
      component_json jsonb NOT NULL
    ) ON COMMIT DROP;

    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_missing_preview_components;
    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_missing_preview_components (
      candidate_id uuid NOT NULL,
      timesheet_id uuid NOT NULL,
      economic_key_type text NOT NULL,
      economic_key_value text NOT NULL,
      bucket_sort_ordinal integer NOT NULL,
      physical_bucket_key text NOT NULL,
      component_json jsonb NOT NULL,
      PRIMARY KEY(candidate_id,timesheet_id,physical_bucket_key)
    ) ON COMMIT DROP;
  END IF;

  v_component_assembly_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_authoritative_components_ms := COALESCE(v_preflight_setup_ms,0)
    + COALESCE(v_correction_residuals_ms,0)
    + COALESCE(v_authority_validation_ms,0)
    + COALESCE(v_component_assembly_ms,0);
  v_phase_started_at := clock_timestamp();
  IF v_requested_candidate_count > 0 THEN
    FOR v_preview_candidate_loop_id IN
      SELECT DISTINCT requested_candidate.candidate_id
      FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
      WHERE requested_candidate.candidate_id IS NOT NULL
      ORDER BY requested_candidate.candidate_id
    LOOP
      v_preview_context_json := public.pay_preview_build_context(
        p_pay_date => p_pay_date,
        p_week_ending_cutoff => p_week_ending_cutoff,
        p_actor_user_id => p_actor_user_id,
        p_candidate_id => v_preview_candidate_loop_id,
        p_client_id => p_client_filter_single,
        p_preview_decisions_json => v_preview_decisions_json
      )
      || jsonb_build_object(
        'overpayment_sync_mode', true,
        'emit_raw_overpayment_components', true,
        'pay_channel_scope', v_scope,
        'candidate_ids', COALESCE(to_jsonb(p_candidate_ids), '[]'::jsonb),
        'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
        'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb)
      )
      || CASE
        WHEN COALESCE(v_authoritative_timesheet_scope, false) THEN
          jsonb_build_object(
            'workbench_source_build_mode', true,
            'source_build_mode', true,
            'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
            -- v_workbench_session_id has already passed the exact session,
            -- candidate, version, actor, pay-date and scope authority checks
            -- above.  The existing preview overlay deliberately requires this
            -- explicit session authority before consuming saved rate choices.
            'workbench_resolution_session_id',v_workbench_session_id::text
          )
        ELSE '{}'::jsonb
      END;

      IF COALESCE(v_authoritative_timesheet_scope, false) THEN
        v_phase_started_at := clock_timestamp();
        v_preview_collect_result_json := public.pay_preview_candidate_collect_scope(
          p_context_json => v_preview_context_json,
          p_candidate_id => v_preview_candidate_loop_id
        );
        v_preview_collect_ms := v_preview_collect_ms
          + FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;

        -- pay_preview_candidate_collect_scope intentionally discovers current
        -- pre-Draft reservation state.  A sealed build must not continue using
        -- those later live rows, so replace the complete reservation workspace
        -- with the RESERVATION_COMPONENT facts captured by this build before
        -- any baseline or component construction consumes it.
        DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_reservation_items;
        CREATE TEMP TABLE pg_temp.tmp_sync_sealed_reservation_items ON COMMIT DROP AS
        SELECT fact.fact_family||':'||fact.natural_key AS authority_fact_identity,
          CASE WHEN COALESCE(fact.source_payload_json#>>'{pay_batch_item,id}','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (fact.source_payload_json#>>'{pay_batch_item,id}')::uuid
            WHEN COALESCE(fact.source_payload_json->>'pay_batch_item_id','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (fact.source_payload_json->>'pay_batch_item_id')::uuid END AS pay_batch_item_id,
          CASE WHEN COALESCE(fact.source_payload_json#>>'{pay_batch_item,pay_batch_id}','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (fact.source_payload_json#>>'{pay_batch_item,pay_batch_id}')::uuid
            WHEN COALESCE(fact.source_payload_json->>'pay_batch_id','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (fact.source_payload_json->>'pay_batch_id')::uuid END AS pay_batch_id,
          fact.timesheet_id,
          NULLIF(BTRIM(COALESCE(fact.source_payload_json#>>'{pay_batch_item,segment_key}',
            fact.source_payload_json#>>'{pay_batch_item,frozen_source_basis_json,segment_key}',
            fact.source_payload_json#>>'{frozen_source_basis_json,segment_key}')),'')
            AS segment_key,
          NULLIF(BTRIM(COALESCE(
            fact.source_payload_json#>>'{pay_batch_item,frozen_source_basis_json,segment_id}',
            fact.source_payload_json#>>'{frozen_source_basis_json,segment_id}',
            CASE WHEN NULLIF(BTRIM(COALESCE(
                fact.source_payload_json#>>'{pay_batch_item,source_ref}',
                fact.source_payload_json->>'source_ref')),'') LIKE 'seg:%'
              THEN split_part(COALESCE(fact.source_payload_json#>>'{pay_batch_item,source_ref}',
                fact.source_payload_json->>'source_ref'),':',2) END,
            fact.source_payload_json#>>'{pay_batch_item,segment_key}',
            fact.source_payload_json#>>'{pay_batch_item,frozen_source_basis_json,segment_key}',
            fact.source_payload_json#>>'{frozen_source_basis_json,segment_key}')),'')
            AS segment_id_norm,
          NULLIF(BTRIM(COALESCE(fact.source_payload_json#>>'{pay_batch_item,source_ref}',
            fact.source_payload_json->>'source_ref')),'') AS source_ref,
          COALESCE(NULLIF(BTRIM(fact.source_payload_json#>>'{pay_batch_item,item_type}'),''),
            CASE WHEN case_authority.evidence_count=1
                AND case_authority.distinct_case_type_count=1
                AND case_authority.case_type='OVERPAYMENT'
              THEN 'OVERPAYMENT_RECOVERY' END,
            CASE UPPER(BTRIM(fact.economic_key_type))
              WHEN 'TS_DAY' THEN 'SEGMENT_DELTA' WHEN 'TS_TOTAL' THEN 'SEGMENT_DELTA'
              WHEN 'EXPENSE_CODE' THEN 'EXPENSE_DELTA'
              WHEN 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
              WHEN 'ADDITIONAL_CODE' THEN 'ADJUSTMENT_DELTA'
              ELSE 'ADJUSTMENT_DELTA' END) AS item_type,
          UPPER(BTRIM(fact.economic_key_type)) AS component_key_type,
          BTRIM(fact.economic_key_value) AS component_key_value,
          COALESCE(NULLIF(BTRIM(fact.source_payload_json#>>'{economic_key,key_resolution_source}'),''),
            CASE WHEN case_authority.evidence_count=1
                AND case_authority.distinct_case_type_count=1
                AND case_authority.case_type='OVERPAYMENT'
              THEN 'FINANCE_CASE_IDENTITY' END,
            'SEALED_RESERVATION_COMPONENT') AS key_resolution_source,
          NULLIF(BTRIM(COALESCE(fact.source_payload_json#>>'{economic_key,key_resolution_failure_reason}',
            fact.source_payload_json->>'resolution_failure')),'') AS key_resolution_failure_reason,
          ROUND(CASE WHEN case_authority.evidence_count=1
                AND case_authority.distinct_case_type_count=1
                AND case_authority.case_type='OVERPAYMENT'
              THEN -ABS(COALESCE(fact.reserved_source_amount,0))
            ELSE COALESCE(fact.reserved_source_amount,0) END,2) AS amount_ex_vat,
          CASE WHEN jsonb_typeof(fact.source_payload_json->'breakdowns')='array'
            THEN fact.source_payload_json->'breakdowns' ELSE '[]'::jsonb END AS breakdowns
        FROM private.banking_pay_workbench_economic_build_facts fact
        LEFT JOIN pg_temp.tmp_sync_sealed_finance_case_authority case_authority
          ON case_authority.build_id=fact.build_id
         AND case_authority.candidate_id=fact.candidate_id
         AND case_authority.finance_case_id=fact.finance_case_id
        WHERE fact.build_id=p_build_id AND fact.candidate_id=v_preview_candidate_loop_id
          AND fact.fact_family='RESERVATION_COMPONENT'
          AND fact.timesheet_id IS NOT NULL
          AND (NOT v_slice_active OR fact.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */
          AND NULLIF(BTRIM(COALESCE(fact.economic_key_type,'')),'') IS NOT NULL
          AND NULLIF(BTRIM(COALESCE(fact.economic_key_value,'')),'') IS NOT NULL;

        CREATE UNIQUE INDEX tmp_sync_sealed_reservation_items_authority_idx
          ON pg_temp.tmp_sync_sealed_reservation_items(authority_fact_identity);
        CREATE INDEX tmp_sync_sealed_reservation_items_key_idx
          ON pg_temp.tmp_sync_sealed_reservation_items(
            timesheet_id,component_key_type,component_key_value);
        CREATE INDEX tmp_sync_sealed_reservation_items_source_ref_idx
          ON pg_temp.tmp_sync_sealed_reservation_items(timesheet_id,source_ref);
        CREATE INDEX tmp_sync_sealed_reservation_items_type_idx
          ON pg_temp.tmp_sync_sealed_reservation_items(timesheet_id,item_type);

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_batch_items_replacement
          (LIKE pg_temp.reserved_batch_items INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_batch_items_replacement(
          pay_batch_item_id,pay_batch_id,timesheet_id,segment_key,segment_id_norm,
          source_ref,item_type,component_key_type,component_key_value,
          key_resolution_source,key_resolution_failure_reason,amount_ex_vat)
        SELECT sealed.pay_batch_item_id,sealed.pay_batch_id,sealed.timesheet_id,
          sealed.segment_key,sealed.segment_id_norm,sealed.source_ref,sealed.item_type,
          sealed.component_key_type,sealed.component_key_value,
          sealed.key_resolution_source,sealed.key_resolution_failure_reason,
          sealed.amount_ex_vat
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_by_source_ref_replacement
          (LIKE pg_temp.reserved_by_source_ref INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_by_source_ref_replacement
        SELECT sealed.timesheet_id,sealed.source_ref,ROUND(SUM(sealed.amount_ex_vat),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        WHERE sealed.source_ref IS NOT NULL
        GROUP BY sealed.timesheet_id,sealed.source_ref;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_total_by_timesheet_replacement
          (LIKE pg_temp.reserved_total_by_timesheet INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_total_by_timesheet_replacement
        SELECT sealed.timesheet_id,ROUND(SUM(sealed.amount_ex_vat),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        GROUP BY sealed.timesheet_id;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_segment_key_map_replacement
          (LIKE pg_temp.reserved_segment_key_map INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_segment_key_map_replacement
        SELECT sealed.timesheet_id,sealed.segment_id_norm,
          sealed.component_key_type,sealed.component_key_value
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        WHERE sealed.item_type='SEGMENT_DELTA'
          AND sealed.component_key_type IN ('TS_DAY','TS_TOTAL')
          AND sealed.component_key_value IS NOT NULL
          AND (sealed.component_key_type<>'TS_DAY'
            OR sealed.component_key_value ~ '^\d{4}-\d{2}-\d{2}$');

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_segment_sums_replacement
          (LIKE pg_temp.reserved_segment_sums INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_segment_sums_replacement
        SELECT sealed.timesheet_id,sealed.component_key_type,sealed.component_key_value,
          ROUND(SUM(sealed.amount_ex_vat),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        WHERE sealed.item_type='SEGMENT_DELTA'
          AND sealed.component_key_type IN ('TS_DAY','TS_TOTAL')
          AND sealed.component_key_value IS NOT NULL
          AND (sealed.component_key_type<>'TS_DAY'
            OR sealed.component_key_value ~ '^\d{4}-\d{2}-\d{2}$')
        GROUP BY sealed.timesheet_id,sealed.component_key_type,sealed.component_key_value;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_preview_segment_ords_replacement
          (LIKE pg_temp.reserved_preview_segment_ords INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_preview_segment_ords_replacement
        SELECT sealed.timesheet_id,
          CASE WHEN split_part(COALESCE(sealed.source_ref,''),':',3) ~ '^\d+$'
            THEN split_part(sealed.source_ref,':',3)::integer END,
          ROUND(SUM(sealed.amount_ex_vat),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        WHERE sealed.item_type='ADJUSTMENT_DELTA'
          AND BTRIM(COALESCE(sealed.source_ref,'')) LIKE 'preview_seg:%'
        GROUP BY sealed.timesheet_id,
          CASE WHEN split_part(COALESCE(sealed.source_ref,''),':',3) ~ '^\d+$'
            THEN split_part(sealed.source_ref,':',3)::integer END;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_additional_by_code_replacement
          (LIKE pg_temp.reserved_additional_by_code INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_additional_by_code_replacement
        SELECT sealed.timesheet_id,UPPER(NULLIF(BTRIM(COALESCE(
            breakdown.value->>'bucket_code',
            CASE WHEN sealed.component_key_type='ADDITIONAL_CODE'
              THEN sealed.component_key_value END)),'')) AS code,
          ROUND(SUM(CASE
            WHEN COALESCE(breakdown.value#>>'{meta_json,source_amount_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN ABS((breakdown.value#>>'{meta_json,source_amount_ex_vat}')::numeric)
            WHEN COALESCE(breakdown.value#>>'{meta_json,source_pay_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN ABS((breakdown.value#>>'{meta_json,source_pay_ex_vat}')::numeric)
            WHEN COALESCE(breakdown.value->>'amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
              THEN ABS((breakdown.value->>'amount_ex_vat')::numeric)
            ELSE ABS(sealed.amount_ex_vat) END),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        LEFT JOIN LATERAL jsonb_array_elements(CASE
          WHEN jsonb_typeof(sealed.breakdowns)='array' AND jsonb_array_length(sealed.breakdowns)>0
            THEN sealed.breakdowns
          WHEN sealed.component_key_type='ADDITIONAL_CODE'
            THEN jsonb_build_array(jsonb_build_object(
              'bucket_code',sealed.component_key_value,
              'amount_ex_vat',sealed.amount_ex_vat,
              'line_kind','ADDITIONAL_UNIT'))
          ELSE '[]'::jsonb END) breakdown(value) ON true
        WHERE (breakdown.value->>'line_kind'='ADDITIONAL_UNIT'
            OR sealed.component_key_type='ADDITIONAL_CODE')
          AND NULLIF(BTRIM(COALESCE(breakdown.value->>'bucket_code',
            sealed.component_key_value)),'') IS NOT NULL
        GROUP BY sealed.timesheet_id,UPPER(NULLIF(BTRIM(COALESCE(
          breakdown.value->>'bucket_code',
          CASE WHEN sealed.component_key_type='ADDITIONAL_CODE'
            THEN sealed.component_key_value END)),''));

        DROP TABLE pg_temp.reserved_batch_items,pg_temp.reserved_by_source_ref,
          pg_temp.reserved_total_by_timesheet,pg_temp.reserved_segment_key_map,
          pg_temp.reserved_segment_sums,pg_temp.reserved_preview_segment_ords,
          pg_temp.reserved_additional_by_code;
        ALTER TABLE pg_temp.tmp_sync_reserved_batch_items_replacement RENAME TO reserved_batch_items;
        ALTER TABLE pg_temp.tmp_sync_reserved_by_source_ref_replacement RENAME TO reserved_by_source_ref;
        ALTER TABLE pg_temp.tmp_sync_reserved_total_by_timesheet_replacement RENAME TO reserved_total_by_timesheet;
        ALTER TABLE pg_temp.tmp_sync_reserved_segment_key_map_replacement RENAME TO reserved_segment_key_map;
        ALTER TABLE pg_temp.tmp_sync_reserved_segment_sums_replacement RENAME TO reserved_segment_sums;
        ALTER TABLE pg_temp.tmp_sync_reserved_preview_segment_ords_replacement RENAME TO reserved_preview_segment_ords;
        ALTER TABLE pg_temp.tmp_sync_reserved_additional_by_code_replacement RENAME TO reserved_additional_by_code;

        IF to_regclass('pg_temp.ts_baseline') IS NULL
           OR to_regclass('pg_temp.pay_preview_candidate_context') IS NULL THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_INPUT_MISSING'
            USING ERRCODE='P0001',DETAIL=jsonb_build_object(
              'code','PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_INPUT_MISSING',
              'candidate_id',v_preview_candidate_loop_id::text)::text;
        END IF;

        IF EXISTS(
          SELECT 1 FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          LEFT JOIN pg_temp.ts_baseline baseline
            ON baseline.candidate_id=v_preview_candidate_loop_id
           AND baseline.timesheet_id=sealed.timesheet_id
          WHERE baseline.timesheet_id IS NULL
        ) THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PRESENTATION_METADATA_INCOMPLETE'
            USING ERRCODE='23514';
        END IF;

        UPDATE pg_temp.pay_preview_candidate_context context_row
        SET erni_pct=authority.erni_pct,vat_rate_pct=authority.vat_rate_pct
        FROM (
          SELECT MIN(sealed.erni_pct) AS erni_pct,MIN(sealed.vat_rate_pct) AS vat_rate_pct
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
        ) authority
        WHERE context_row.candidate_id=v_preview_candidate_loop_id;

        WITH segment_bucket_rows AS (
          SELECT sealed.*,
            CASE WHEN COALESCE(sealed.evidence_json#>>'{source_ordinal}','') ~ '^\d+$'
              THEN (sealed.evidence_json#>>'{source_ordinal}')::bigint ELSE 0 END
              AS source_ordinal,
            CASE WHEN jsonb_typeof(sealed.evidence_json#>'{source_payload,segment}')='object'
              THEN sealed.evidence_json#>'{source_payload,segment}' ELSE '{}'::jsonb END
              AS source_segment,
            COALESCE(sealed.segment_stable_key,sealed.segment_id,sealed.segment_key,
              CASE WHEN sealed.component_kind='WORKED_TIME_RESIDUAL'
                THEN 'worked-time-residual:'||sealed.economic_key_type||':'
                  ||sealed.economic_key_value END) AS builder_segment_identity
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          WHERE sealed.component_kind IN ('WORKED_TIME','WORKED_TIME_RESIDUAL')
        ), segment_grouped AS (
          SELECT segment.timesheet_id,segment.builder_segment_identity,
            segment.economic_key_type,segment.economic_key_value,
            COALESCE(MIN(segment.segment_id),segment.builder_segment_identity) AS segment_id,
            COALESCE(MIN(segment.segment_key),segment.builder_segment_identity) AS segment_key,
            MIN(segment.source_ordinal) AS source_ordinal,
            (array_agg(segment.source_segment ORDER BY segment.source_ordinal,
              segment.builder_segment_identity,segment.segment_id))[1]
              ||jsonb_build_object(
                'segment_id',COALESCE(MIN(segment.segment_id),segment.builder_segment_identity),
                'segment_key',COALESCE(MIN(segment.segment_key),segment.builder_segment_identity),
                'segment_stable_key',segment.builder_segment_identity,
                'date',MIN(COALESCE(segment.source_segment->>'date',
                  segment.source_segment->>'work_date',CASE
                    WHEN segment.economic_key_type='TS_DAY' THEN segment.economic_key_value END)),
                'hours_day',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='DAY'),0),6),
                'hours_night',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='NIGHT'),0),6),
                'hours_sat',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='SAT'),0),6),
                'hours_sun',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='SUN'),0),6),
                'hours_bh',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='BH'),0),6),
                'pay_amount',ROUND(SUM(segment.truth_ex_vat),2),
                'charge_amount',ROUND(SUM(COALESCE(segment.source_charge_ex_vat,0)),2))
              AS segment_json
          FROM segment_bucket_rows segment
          GROUP BY segment.timesheet_id,segment.builder_segment_identity,
            segment.economic_key_type,segment.economic_key_value
        ), segments_by_timesheet AS (
          SELECT grouped.timesheet_id,jsonb_agg(grouped.segment_json ORDER BY
            grouped.source_ordinal,grouped.builder_segment_identity,grouped.segment_id)
              AS segments_json
          FROM segment_grouped grouped GROUP BY grouped.timesheet_id
        ), additional_by_timesheet AS (
          SELECT additional.timesheet_id,
            COALESCE(jsonb_object_agg(
              additional.evidence_json#>>'{source_payload,raw_additional_code}',
              additional.evidence_json#>'{source_payload,source_value}' ORDER BY
              octet_length(additional.evidence_json#>>'{source_payload,raw_additional_code}'),
              encode(convert_to(additional.evidence_json#>>'{source_payload,raw_additional_code}',
                'UTF8'),'hex')),'{}'::jsonb) AS additional_json,
            ROUND(SUM(additional.truth_ex_vat),2) AS additional_pay_ex_vat,
            ROUND(SUM(COALESCE(additional.source_charge_ex_vat,0)),2)
              AS additional_charge_ex_vat
          FROM pg_temp.tmp_sync_sealed_rate_projection additional
          WHERE additional.component_kind='ADDITIONAL_UNIT'
            AND COALESCE(additional.evidence_json->>'source_key','') NOT LIKE 'SEALED_SYNTHETIC:%'
            AND NULLIF(additional.evidence_json#>>'{source_payload,raw_additional_code}','')
              IS NOT NULL
          GROUP BY additional.timesheet_id
        ), adjustments_by_timesheet AS (
          SELECT adjustment.timesheet_id,jsonb_agg(jsonb_build_object(
              'id',adjustment.evidence_json#>>'{source_payload,adjustment_id}',
              'delta_pay_ex_vat',ROUND(adjustment.truth_ex_vat,2))
            ORDER BY adjustment.evidence_json#>>'{source_payload,adjustment_id}') AS adjustments_json
          FROM pg_temp.tmp_sync_sealed_rate_projection adjustment
          WHERE adjustment.component_kind='ADJUSTMENT'
            AND COALESCE(adjustment.evidence_json->>'source_key','') NOT LIKE 'SEALED_SYNTHETIC:%'
          GROUP BY adjustment.timesheet_id
        ), economic_projection_totals AS (
          SELECT sealed.timesheet_id,sealed.economic_key_type,sealed.economic_key_value,
            ROUND(SUM(sealed.truth_ex_vat),2) AS truth_ex_vat,
            ROUND(SUM(sealed.baseline_ex_vat),2) AS baseline_ex_vat,
            ROUND(SUM(sealed.reserved_ex_vat),2) AS reserved_ex_vat,
            MIN(CASE WHEN COALESCE(sealed.evidence_json#>>'{economic_authority,baseline_inc_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN (sealed.evidence_json#>>'{economic_authority,baseline_inc_vat}')::numeric END)
              AS baseline_inc_vat
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          GROUP BY sealed.timesheet_id,sealed.economic_key_type,sealed.economic_key_value
        ), baseline_only_keys AS (
          SELECT total.*
          FROM economic_projection_totals total
          WHERE ABS(total.truth_ex_vat)<=0.005 AND ABS(total.baseline_ex_vat)>0.005
        ), baseline_only_physical_evidence AS (
          SELECT sealed.timesheet_id,sealed.economic_key_type,sealed.economic_key_value,
            ROUND(SUM(sealed.source_charge_ex_vat),2) AS source_charge_ex_vat,
            (array_agg(sealed.evidence_json#>'{source_payload,source_value}' ORDER BY
              sealed.physical_bucket_key))[1] AS source_value
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          JOIN baseline_only_keys baseline
            USING(timesheet_id,economic_key_type,economic_key_value)
          GROUP BY sealed.timesheet_id,sealed.economic_key_type,sealed.economic_key_value
        ), baseline_only_active_artifacts AS (
          SELECT baseline.timesheet_id,
            jsonb_agg(jsonb_build_object(
              'key_type',baseline.economic_key_type,
              'key_value',baseline.economic_key_value,
              'amount_ex_vat',baseline.baseline_ex_vat,
              'amount_inc_vat',COALESCE(baseline.baseline_inc_vat,baseline.baseline_ex_vat),
              'baseline_source','SEALED_BUILD_FACTS') ORDER BY
              baseline.economic_key_type,baseline.economic_key_value) AS components_json,
            COUNT(*)::integer AS component_count,
            ROUND(SUM(baseline.baseline_ex_vat),2) AS amount_ex_vat,
            ROUND(SUM(COALESCE(baseline.baseline_inc_vat,baseline.baseline_ex_vat)),2)
              AS amount_inc_vat
          FROM baseline_only_keys baseline GROUP BY baseline.timesheet_id
        ), baseline_only_expenses AS (
          SELECT baseline.timesheet_id,
            ROUND(SUM(baseline.baseline_ex_vat),2) AS expenses_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat),0),2) AS expenses_charge_ex_vat,
            ROUND(SUM(baseline.baseline_ex_vat) FILTER(
              WHERE baseline.economic_key_value='TRAVEL'),2) AS travel_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat) FILTER(
              WHERE baseline.economic_key_value='TRAVEL'),0),2) AS travel_charge_ex_vat,
            ROUND(SUM(baseline.baseline_ex_vat) FILTER(
              WHERE baseline.economic_key_value='ACCOMMODATION'),2) AS accommodation_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat) FILTER(
              WHERE baseline.economic_key_value='ACCOMMODATION'),0),2)
              AS accommodation_charge_ex_vat,
            ROUND(SUM(baseline.baseline_ex_vat) FILTER(
              WHERE baseline.economic_key_value='OTHER'),2) AS other_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat) FILTER(
              WHERE baseline.economic_key_value='OTHER'),0),2) AS other_charge_ex_vat,
            ROUND(SUM(baseline.baseline_ex_vat) FILTER(
              WHERE baseline.economic_key_value='MILEAGE'),2) AS mileage_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat) FILTER(
              WHERE baseline.economic_key_value='MILEAGE'),0),2) AS mileage_charge_ex_vat
          FROM baseline_only_keys baseline
          LEFT JOIN baseline_only_physical_evidence sealed
            USING(timesheet_id,economic_key_type,economic_key_value)
          WHERE baseline.economic_key_type='EXPENSE_CODE'
          GROUP BY baseline.timesheet_id
        ), baseline_only_additional AS (
          SELECT baseline.timesheet_id,
            ROUND(SUM(baseline.baseline_ex_vat),2) AS additional_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat),0),2) AS additional_charge_ex_vat,
            COALESCE(jsonb_object_agg(baseline.economic_key_value,
              COALESCE(sealed.source_value,
                jsonb_build_object('source_pay_ex_vat',baseline.baseline_ex_vat))
              ORDER BY octet_length(baseline.economic_key_value),
                encode(convert_to(baseline.economic_key_value,'UTF8'),'hex')),'{}'::jsonb)
              AS additional_units_json
          FROM baseline_only_keys baseline
          LEFT JOIN baseline_only_physical_evidence sealed
            USING(timesheet_id,economic_key_type,economic_key_value)
          WHERE baseline.economic_key_type='ADDITIONAL_CODE'
          GROUP BY baseline.timesheet_id
        ), baseline_only_adjustments AS (
          SELECT baseline.timesheet_id,jsonb_agg(jsonb_build_object(
              'id',baseline.economic_key_value,
              'pay_amount_ex_vat',baseline.baseline_ex_vat,
              'source_pay_ex_vat',baseline.baseline_ex_vat)
            ORDER BY baseline.economic_key_value) AS adjustments_json
          FROM baseline_only_keys baseline
          WHERE baseline.economic_key_type='ADJUSTMENT_CODE'
          GROUP BY baseline.timesheet_id
        ), timesheet_authority AS (
          SELECT sealed.timesheet_id,
            (jsonb_agg(DISTINCT sealed.source_pay_method ORDER BY sealed.source_pay_method)->>0)
              AS source_pay_method,
            MIN(sealed.target_pay_method) AS target_pay_method,
            MIN(sealed.umbrella_id::text)::uuid AS umbrella_id,
            bool_and(sealed.umbrella_enabled) AS umbrella_enabled,
            bool_and(sealed.umbrella_vat_chargeable) AS umbrella_vat_chargeable,
            ROUND(COALESCE(SUM(sealed.source_units)
              FILTER(WHERE sealed.component_kind='WORKED_TIME'),0),6) AS total_hours,
            ROUND(SUM(sealed.truth_ex_vat),2) AS total_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE ABS(sealed.truth_ex_vat)>0.005),0),2) AS total_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='DAY'),0),6)
              AS hours_day,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='NIGHT'),0),6)
              AS hours_night,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='SAT'),0),6)
              AS hours_sat,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='SUN'),0),6)
              AS hours_sun,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='BH'),0),6)
              AS hours_bh,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='DAY') AS pay_day,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='NIGHT') AS pay_night,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='SAT') AS pay_sat,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='SUN') AS pay_sun,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='BH') AS pay_bh,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='DAY') AS charge_day,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='NIGHT') AS charge_night,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='SAT') AS charge_sat,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='SUN') AS charge_sun,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='BH') AS charge_bh,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE'),0),2) AS expenses_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE'
                AND ABS(sealed.truth_ex_vat)>0.005),0),2) AS expenses_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat) FILTER(WHERE sealed.component_kind='EXPENSE'
              AND sealed.evidence_json#>>'{source_payload,expense_code}'='TRAVEL'),0),2)
              AS travel_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE' AND ABS(sealed.truth_ex_vat)>0.005
                AND sealed.evidence_json#>>'{source_payload,expense_code}'='TRAVEL'),0),2)
              AS travel_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat) FILTER(WHERE sealed.component_kind='EXPENSE'
              AND sealed.evidence_json#>>'{source_payload,expense_code}'='ACCOMMODATION'),0),2)
              AS accommodation_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE' AND ABS(sealed.truth_ex_vat)>0.005
                AND sealed.evidence_json#>>'{source_payload,expense_code}'='ACCOMMODATION'),0),2)
              AS accommodation_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat) FILTER(WHERE sealed.component_kind='EXPENSE'
              AND sealed.evidence_json#>>'{source_payload,expense_code}'='OTHER'),0),2)
              AS other_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE' AND ABS(sealed.truth_ex_vat)>0.005
                AND sealed.evidence_json#>>'{source_payload,expense_code}'='OTHER'),0),2)
              AS other_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat) FILTER(WHERE sealed.component_kind='EXPENSE'
              AND sealed.evidence_json#>>'{source_payload,expense_code}'='MILEAGE'),0),2)
              AS mileage_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE' AND ABS(sealed.truth_ex_vat)>0.005
                AND sealed.evidence_json#>>'{source_payload,expense_code}'='MILEAGE'),0),2)
              AS mileage_charge_ex_vat
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed GROUP BY sealed.timesheet_id
        )
        UPDATE pg_temp.ts_baseline baseline
        SET ts_pay_method=authority.source_pay_method,
          cand_pay_method=authority.target_pay_method,
          cand_umbrella_id=authority.umbrella_id,
          umb_enabled=authority.umbrella_enabled,
          umb_vat_chargeable=authority.umbrella_vat_chargeable,
          base_json=jsonb_build_object(
            'baseline_source','SEALED_BUILD_FACTS',
            'active_settled_artifact_components',COALESCE(active.components_json,'[]'::jsonb),
            'active_settled_amount_ex_vat',COALESCE(active.amount_ex_vat,0),
            'active_settled_amount_inc_vat',COALESCE(active.amount_inc_vat,0),
            'segments','[]'::jsonb,
            'additional_pay_ex_vat',COALESCE(baseline_additional.additional_pay_ex_vat,0),
            'additional_charge_ex_vat',COALESCE(baseline_additional.additional_charge_ex_vat,0),
            'additional_units_json',COALESCE(baseline_additional.additional_units_json,'{}'::jsonb),
            'expenses',jsonb_build_object(
              'expenses_pay_ex_vat',COALESCE(baseline_expenses.expenses_pay_ex_vat,0),
              'expenses_charge_ex_vat',COALESCE(baseline_expenses.expenses_charge_ex_vat,0),
              'travel_pay_ex_vat',COALESCE(baseline_expenses.travel_pay_ex_vat,0),
              'travel_charge_ex_vat',COALESCE(baseline_expenses.travel_charge_ex_vat,0),
              'accommodation_pay_ex_vat',COALESCE(baseline_expenses.accommodation_pay_ex_vat,0),
              'accommodation_charge_ex_vat',COALESCE(baseline_expenses.accommodation_charge_ex_vat,0),
              'other_pay_ex_vat',COALESCE(baseline_expenses.other_pay_ex_vat,0),
              'other_charge_ex_vat',COALESCE(baseline_expenses.other_charge_ex_vat,0),
              'mileage_pay_ex_vat',COALESCE(baseline_expenses.mileage_pay_ex_vat,0),
              'mileage_charge_ex_vat',COALESCE(baseline_expenses.mileage_charge_ex_vat,0)),
            'adjustments',COALESCE(baseline_adjustments.adjustments_json,'[]'::jsonb)),
          active_settled_artifact_components_json=COALESCE(active.components_json,'[]'::jsonb),
          active_settled_artifact_component_count=COALESCE(active.component_count,0),
          active_settled_artifact_amount_ex_vat=COALESCE(active.amount_ex_vat,0),
          active_settled_artifact_amount_inc_vat=COALESCE(active.amount_inc_vat,0),
          has_active_settled_artifact_baseline=COALESCE(active.component_count,0)>0,
          bas_hours_day=0,bas_hours_night=0,bas_hours_sat=0,bas_hours_sun=0,bas_hours_bh=0,
          bas_pay_day=NULL,bas_pay_night=NULL,bas_pay_sat=NULL,bas_pay_sun=NULL,bas_pay_bh=NULL,
          bas_charge_day=NULL,bas_charge_night=NULL,bas_charge_sat=NULL,
          bas_charge_sun=NULL,bas_charge_bh=NULL,
          current_segments_json=COALESCE(segments.segments_json,'[]'::jsonb),
          current_adjustments_json=COALESCE(adjustments.adjustments_json,'[]'::jsonb),
          total_hours=authority.total_hours,total_pay_ex_vat=authority.total_pay_ex_vat,
          total_charge_ex_vat=authority.total_charge_ex_vat,
          hours_day=authority.hours_day,hours_night=authority.hours_night,
          hours_sat=authority.hours_sat,hours_sun=authority.hours_sun,hours_bh=authority.hours_bh,
          pay_day=authority.pay_day,pay_night=authority.pay_night,pay_sat=authority.pay_sat,
          pay_sun=authority.pay_sun,pay_bh=authority.pay_bh,
          charge_day=authority.charge_day,charge_night=authority.charge_night,
          charge_sat=authority.charge_sat,charge_sun=authority.charge_sun,
          charge_bh=authority.charge_bh,
          cur_hours_day=authority.hours_day,cur_hours_night=authority.hours_night,
          cur_hours_sat=authority.hours_sat,cur_hours_sun=authority.hours_sun,
          cur_hours_bh=authority.hours_bh,
          cur_pay_day=authority.pay_day,cur_pay_night=authority.pay_night,
          cur_pay_sat=authority.pay_sat,cur_pay_sun=authority.pay_sun,cur_pay_bh=authority.pay_bh,
          cur_charge_day=authority.charge_day,cur_charge_night=authority.charge_night,
          cur_charge_sat=authority.charge_sat,cur_charge_sun=authority.charge_sun,
          cur_charge_bh=authority.charge_bh,
          current_additional_units_json=COALESCE(additional.additional_json,'{}'::jsonb),
          current_additional_pay_ex_vat=COALESCE(additional.additional_pay_ex_vat,0),
          current_additional_charge_ex_vat=COALESCE(additional.additional_charge_ex_vat,0),
          current_expenses_pay_ex_vat=authority.expenses_pay_ex_vat,
          current_expenses_charge_ex_vat=authority.expenses_charge_ex_vat,
          current_travel_pay_ex_vat=authority.travel_pay_ex_vat,
          current_travel_charge_ex_vat=authority.travel_charge_ex_vat,
          current_accommodation_pay_ex_vat=authority.accommodation_pay_ex_vat,
          current_accommodation_charge_ex_vat=authority.accommodation_charge_ex_vat,
          current_other_pay_ex_vat=authority.other_pay_ex_vat,
          current_other_charge_ex_vat=authority.other_charge_ex_vat,
          current_mileage_pay_ex_vat=authority.mileage_pay_ex_vat,
          current_mileage_charge_ex_vat=authority.mileage_charge_ex_vat
        FROM timesheet_authority authority
        LEFT JOIN segments_by_timesheet segments USING(timesheet_id)
        LEFT JOIN additional_by_timesheet additional USING(timesheet_id)
        LEFT JOIN adjustments_by_timesheet adjustments USING(timesheet_id)
        LEFT JOIN baseline_only_active_artifacts active USING(timesheet_id)
        LEFT JOIN baseline_only_expenses baseline_expenses USING(timesheet_id)
        LEFT JOIN baseline_only_additional baseline_additional USING(timesheet_id)
        LEFT JOIN baseline_only_adjustments baseline_adjustments USING(timesheet_id)
        WHERE baseline.candidate_id=v_preview_candidate_loop_id
          AND baseline.timesheet_id=authority.timesheet_id;

        IF v_execution_profile_version=2 THEN
          v_phase_started_at := clock_timestamp();
          v_preview_canonical_result_json := public.pay_preview_candidate_build_canonical_lines(
            p_context_json => v_preview_context_json,
            p_candidate_id => v_preview_candidate_loop_id
          );
          v_preview_canonical_ms := v_preview_canonical_ms
            + FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
        END IF;
      END IF;

      v_phase_started_at := clock_timestamp();
      v_preview_baseline_json := public.pay_preview_candidate_build_summary_fragment(
        p_context_json => v_preview_context_json,
        p_candidate_id => v_preview_candidate_loop_id
      );
      v_preview_summary_ms := v_preview_summary_ms
        + FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;

      IF jsonb_typeof(COALESCE(v_preview_baseline_json, '{}'::jsonb)) <> 'object' THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_BASELINE_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_BASELINE_INVALID',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope
                )::text;
      END IF;

      IF COALESCE(v_authoritative_timesheet_scope, false)
         AND COALESCE(v_authoritative_negative_component_count, 0) > 0
         AND to_regclass('pg_temp.timesheet_case_rollup') IS NULL THEN
        PERFORM public.pay_preview_candidate_build_case_component_rows(
          p_context_json => v_preview_context_json,
          p_candidate_id => v_preview_candidate_loop_id
        );
      END IF;

      IF COALESCE(v_authoritative_timesheet_scope,false) THEN
        DELETE FROM pg_temp.tmp_sync_raw_preview_physical_components
        WHERE candidate_id=v_preview_candidate_loop_id;
        DELETE FROM pg_temp.tmp_sync_sealed_missing_preview_components
        WHERE candidate_id=v_preview_candidate_loop_id;

        IF to_regclass('pg_temp.timesheet_case_rollup') IS NOT NULL THEN
          INSERT INTO pg_temp.tmp_sync_raw_preview_physical_components(
            candidate_id,timesheet_id,component_ordinality,physical_bucket_key,
            component_json
          )
          SELECT raw_case.candidate_id,raw_case.timesheet_id,
            raw_component.ordinality::bigint,
            concat_ws('|','RATE_BUCKET_V1',raw_case.timesheet_id::text,
              NULLIF(BTRIM(raw_component.value->>'source_family_key'),''),
              UPPER(NULLIF(BTRIM(raw_component.value->>'component_key_type'),'')),
              NULLIF(BTRIM(raw_component.value->>'component_key_value'),''),
              CASE
                WHEN UPPER(BTRIM(COALESCE(
                    raw_component.value#>>'{source_basis_json,component_fallback}','')))
                      ='WORKED_TIME_AMOUNT'
                  THEN 'worked-time-residual:'
                    ||UPPER(BTRIM(raw_component.value->>'component_key_type'))||':'
                    ||BTRIM(raw_component.value->>'component_key_value')
                WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))
                    IN ('TS_DAY','TS_TOTAL')
                  THEN COALESCE(
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_stable_key}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_id}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_key}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,work_date}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,date}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,ref_num}'),''))
                WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADDITIONAL_CODE'
                  THEN 'additional:'
                    ||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,additional_code}'))
                WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='EXPENSE_CODE'
                  THEN 'expense:'
                    ||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,expense_code}'))
                WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADJUSTMENT_CODE'
                  THEN 'adjustment:'
                    ||BTRIM(raw_component.value#>>'{source_basis_json,adjustment_id}')
              END,
              UPPER(BTRIM(COALESCE(
                CASE WHEN UPPER(BTRIM(COALESCE(
                    raw_component.value#>>'{source_basis_json,component_fallback}','')))
                      ='WORKED_TIME_AMOUNT' THEN 'FIXED' END,
                NULLIF(raw_component.value#>>'{source_basis_json,bucket_code}',''),
                CASE UPPER(BTRIM(raw_component.value->>'component_key_type'))
                  WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
                  WHEN 'EXPENSE_CODE' THEN 'FIXED'
                  WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
                END)))) AS physical_bucket_key,
            raw_component.value
          FROM pg_temp.timesheet_case_rollup raw_case
          CROSS JOIN LATERAL jsonb_array_elements(CASE
            WHEN jsonb_typeof(raw_case.case_components_json)='array'
              THEN raw_case.case_components_json ELSE '[]'::jsonb END)
            WITH ORDINALITY raw_component(value,ordinality)
          WHERE raw_case.candidate_id=v_preview_candidate_loop_id;
        END IF;

        IF EXISTS(
          SELECT 1
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          WHERE sealed.candidate_id=v_preview_candidate_loop_id
            AND sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
            AND sealed.evidence_json#>>'{source_payload,source_kind}'
              IN ('SEGMENT','SEALED_BASELINE_COMPONENT','WORKED_TIME_RESIDUAL')
            AND jsonb_typeof(CASE
              WHEN sealed.evidence_json#>>'{source_payload,source_kind}'='SEGMENT'
                THEN sealed.evidence_json#>'{source_payload,segment}'
              ELSE sealed.evidence_json#>'{source_payload,source_value}' END)<>'object'
        ) THEN
          RAISE EXCEPTION 'RATE_AUTHORITY_PHYSICAL_IDENTITY_INCOMPLETE'
            USING ERRCODE='P0001',DETAIL=jsonb_build_object(
              'code','RATE_AUTHORITY_PHYSICAL_IDENTITY_INCOMPLETE',
              'candidate_id',v_preview_candidate_loop_id::text,
              'message','A sealed builder component has no complete frozen source basis.'
            )::text;
        END IF;

        INSERT INTO pg_temp.tmp_sync_sealed_missing_preview_components(
          candidate_id,timesheet_id,economic_key_type,economic_key_value,
          bucket_sort_ordinal,physical_bucket_key,component_json
        )
        SELECT sealed.candidate_id,sealed.timesheet_id,sealed.economic_key_type,
          sealed.economic_key_value,sealed.bucket_sort_ordinal,sealed.physical_bucket_key,
          jsonb_strip_nulls(jsonb_build_object(
            'source_family_key',sealed.source_family_key,
            'component_key_type',sealed.economic_key_type,
            'component_key_value',sealed.economic_key_value,
            'component_kind',sealed.component_kind,
            'component_member_identity',sealed.component_member_identity,
            'classification',CASE WHEN sealed.economic_key_type='EXPENSE_CODE'
              THEN 'REIMBURSEMENT_GROSS_FIXED' ELSE 'TAXABLE_CHANNEL_SENSITIVE' END,
            'source_pay_method',sealed.source_pay_method,
            'current_target_pay_method',sealed.target_pay_method,
            'source_basis_json',
              bridge.source_basis_json
              ||jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id',sealed.timesheet_id::text,
                'source_family_key',sealed.source_family_key,
                'component_key_type',sealed.economic_key_type,
                'component_key_value',sealed.economic_key_value,
                'segment_id',sealed.segment_id,
                'segment_key',COALESCE(sealed.segment_key,sealed.segment_id),
                'segment_stable_key',sealed.segment_stable_key,
                'work_date',COALESCE(
                  bridge.source_basis_json->>'work_date',
                  bridge.source_basis_json->>'date'),
                'ref_num',bridge.source_basis_json->>'ref_num',
                'additional_code',CASE WHEN sealed.economic_key_type='ADDITIONAL_CODE'
                  THEN UPPER(sealed.economic_key_value) END,
                'expense_code',CASE WHEN sealed.economic_key_type='EXPENSE_CODE'
                  THEN UPPER(sealed.economic_key_value) END,
                'adjustment_id',CASE WHEN sealed.economic_key_type='ADJUSTMENT_CODE'
                  THEN sealed.economic_key_value END,
                'bucket_code',sealed.bucket_code,
                'source_pay_method',sealed.source_pay_method)),
            'source_units',sealed.source_units,
            'source_rate',sealed.source_rate,
            'source_charge_rate',sealed.source_charge_rate,
            'source_pay_ex_vat',sealed.outstanding_ex_vat,
            'source_charge_ex_vat',sealed.source_charge_ex_vat,
            'component_amount_ex_vat',sealed.outstanding_ex_vat,
            'authoritative_truth_ex_vat',sealed.truth_ex_vat,
            'authoritative_baseline_ex_vat',sealed.baseline_ex_vat,
            'authoritative_reserved_ex_vat',sealed.reserved_ex_vat,
            'authoritative_outstanding_ex_vat',sealed.outstanding_ex_vat,
            'overpayment_component_authority','PRE_DRAFT_LIVE_TRUTH',
            'physical_bucket_key',sealed.physical_bucket_key,
            'physical_bucket_digest',sealed.physical_bucket_digest,
            'sealed_evidence_digest',sealed.sealed_evidence_digest,
            'financial_revision_digest',sealed.financial_revision_digest,
            'target_authority_digest',sealed.target_authority_digest,
            'conversion_context_digest',sealed.conversion_context_digest
          )) AS component_json
        FROM pg_temp.tmp_sync_sealed_rate_projection sealed
        CROSS JOIN LATERAL (
          SELECT CASE
            WHEN sealed.evidence_json#>>'{source_payload,source_kind}'='SEGMENT'
              THEN sealed.evidence_json#>'{source_payload,segment}'
            ELSE sealed.evidence_json#>'{source_payload,source_value}'
          END AS source_basis_json
        ) bridge
        WHERE sealed.candidate_id=v_preview_candidate_loop_id
          AND sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
          AND sealed.evidence_json#>>'{source_payload,source_kind}'
            IN ('SEGMENT','SEALED_BASELINE_COMPONENT','WORKED_TIME_RESIDUAL')
          AND jsonb_typeof(bridge.source_basis_json)='object'
          AND NOT EXISTS(
            SELECT 1
            FROM pg_temp.tmp_sync_raw_preview_physical_components raw_component
            WHERE raw_component.candidate_id=sealed.candidate_id
              AND raw_component.timesheet_id=sealed.timesheet_id
              AND raw_component.physical_bucket_key=sealed.physical_bucket_key
          );
      END IF;

      IF COALESCE(v_authoritative_timesheet_scope, false)
         AND to_regclass('pg_temp.timesheet_case_rollup') IS NOT NULL THEN
        IF EXISTS (
          WITH correction_residuals AS (
            SELECT residual.value AS residual_json
            FROM jsonb_array_elements(public._ctms_candidate_correction_residuals_v1(
              v_workbench_session_id_text::uuid,
              v_preview_candidate_loop_id,
              NULL::uuid,
              'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_METADATA'
            )) AS residual(value)
            WHERE COALESCE((residual.value->>'draftable')::boolean, false)
          ), correction_member_roots AS (
            SELECT DISTINCT
              member_id.value::uuid AS member_timesheet_id,
              (residual.residual_json->>'root_timesheet_id')::uuid AS root_timesheet_id
            FROM correction_residuals AS residual
            CROSS JOIN LATERAL jsonb_array_elements_text(
              COALESCE(residual.residual_json->'member_timesheet_ids', '[]'::jsonb)
            ) AS member_id(value)
            WHERE COALESCE(residual.residual_json->>'root_timesheet_id', '')
                    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              AND member_id.value
                    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          ), correction_component_totals AS (
            SELECT
              (residual.residual_json->>'root_timesheet_id')::uuid AS timesheet_id,
              UPPER(BTRIM(COALESCE(component.value->>'component_key_type', ''))) AS key_type,
              BTRIM(COALESCE(component.value->>'component_key_value', '')) AS key_value,
              1::integer AS preview_component_count,
              ROUND(
                (component.value->>'truth_ex_vat')::numeric,
                2
              )::numeric(12,2) AS preview_truth_ex_vat
            FROM correction_residuals AS residual
            CROSS JOIN LATERAL jsonb_array_elements(
              COALESCE(residual.residual_json->'components', '[]'::jsonb)
            ) AS component(value)
            WHERE COALESCE(residual.residual_json->>'root_timesheet_id', '')
                    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              AND COALESCE(component.value->>'truth_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              AND ROUND(
                    COALESCE(NULLIF(component.value->>'target_outstanding_ex_vat', '')::numeric, 0),
                    2
                  ) < 0
          ), raw_preview_component_totals AS (
            SELECT
              raw_case.timesheet_id,
              UPPER(BTRIM(COALESCE(raw_component.value->>'component_key_type', ''))) AS key_type,
              BTRIM(COALESCE(raw_component.value->>'component_key_value', '')) AS key_value,
              COUNT(*)::integer AS preview_component_count,
              ROUND(
                SUM((raw_component.value->>'component_amount_ex_vat')::numeric),
                2
              )::numeric(12,2) AS preview_truth_ex_vat
            FROM pg_temp.timesheet_case_rollup AS raw_case
            CROSS JOIN LATERAL jsonb_array_elements(
              CASE
                WHEN jsonb_typeof(raw_case.case_components_json) = 'array'
                  THEN COALESCE(raw_case.case_components_json, '[]'::jsonb)
                ELSE '[]'::jsonb
              END
            ) AS raw_component(value)
            WHERE raw_case.candidate_id = v_preview_candidate_loop_id
              AND raw_case.timesheet_id = ANY(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[]))
              AND NOT (raw_case.timesheet_id = ANY(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])))
              AND NOT EXISTS (
                SELECT 1
                FROM correction_member_roots AS correction_member
                WHERE correction_member.member_timesheet_id = raw_case.timesheet_id
              )
              AND COALESCE(raw_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            GROUP BY
              raw_case.timesheet_id,
              UPPER(BTRIM(COALESCE(raw_component.value->>'component_key_type', ''))),
              BTRIM(COALESCE(raw_component.value->>'component_key_value', ''))
          ), preview_component_totals AS (
            SELECT * FROM correction_component_totals
            UNION ALL
            SELECT * FROM raw_preview_component_totals
          ), sealed_baseline_only_keys AS (
            SELECT sealed.timesheet_id,sealed.economic_key_type AS key_type,
              sealed.economic_key_value AS key_value
            FROM pg_temp.tmp_sync_sealed_rate_projection sealed
            GROUP BY sealed.timesheet_id,sealed.economic_key_type,
              sealed.economic_key_value
            HAVING COUNT(*)=COUNT(*) FILTER(WHERE
                sealed.evidence_json#>>'{source_payload,source_kind}'=
                  'SEALED_BASELINE_COMPONENT')
              AND COUNT(*) FILTER(WHERE
                sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true')>0
              AND ROUND(SUM(sealed.truth_ex_vat),2)=0
              AND ROUND(SUM(sealed.outstanding_ex_vat),2)<0
          )
          SELECT 1
          FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
          LEFT JOIN preview_component_totals AS preview_total
            ON preview_total.timesheet_id = authoritative_component.timesheet_id
           AND preview_total.key_type = authoritative_component.key_type
           AND preview_total.key_value = authoritative_component.key_value
          LEFT JOIN sealed_baseline_only_keys sealed_baseline
            ON sealed_baseline.timesheet_id=authoritative_component.timesheet_id
           AND sealed_baseline.key_type=authoritative_component.key_type
           AND sealed_baseline.key_value=authoritative_component.key_value
          WHERE (
                  (
                    preview_total.preview_component_count IS NULL
                    AND ABS(ROUND(authoritative_component.truth_ex_vat, 2)) > 0.01
                  )
                  OR (
                    preview_total.preview_component_count IS NOT NULL
                    AND ABS(ROUND(
                      preview_total.preview_truth_ex_vat
                      - authoritative_component.truth_ex_vat,
                      2
                    )) > 0.01
                  )
                )
            AND sealed_baseline.timesheet_id IS NULL
            AND NOT (
              authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_root_ids, ARRAY[]::uuid[]))
              OR authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_member_ids, ARRAY[]::uuid[]))
            )
        ) THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH',
                    'candidate_id', v_preview_candidate_loop_id::text,
                    'negative_component_count', COALESCE(v_authoritative_negative_component_count, 0),
                    'negative_component_digest', v_authoritative_negative_component_digest,
                    'authoritative_component_sample', (
                      SELECT COALESCE(jsonb_agg(jsonb_build_object(
                        'timesheet_id', bounded_component.timesheet_id::text,
                        'key_type', bounded_component.key_type,
                        'key_value', bounded_component.key_value,
                        'truth_ex_vat', bounded_component.truth_ex_vat,
                        'outstanding_ex_vat', bounded_component.outstanding_ex_vat
                      ) ORDER BY bounded_component.timesheet_id, bounded_component.key_type, bounded_component.key_value), '[]'::jsonb)
                      FROM (
                        SELECT *
                        FROM pg_temp.tmp_sync_authoritative_negative_components
                        ORDER BY timesheet_id, key_type, key_value
                        LIMIT 10
                      ) AS bounded_component
                    ),
                    'correction_component_sample', (
                      SELECT COALESCE(jsonb_agg(jsonb_build_object(
                        'timesheet_id', bounded_correction.root_timesheet_id,
                        'key_type', bounded_correction.key_type,
                        'key_value', bounded_correction.key_value,
                        'truth_ex_vat', bounded_correction.truth_ex_vat,
                        'outstanding_ex_vat', bounded_correction.outstanding_ex_vat
                      ) ORDER BY bounded_correction.root_timesheet_id, bounded_correction.key_type, bounded_correction.key_value), '[]'::jsonb)
                      FROM (
                        SELECT
                          residual.value->>'root_timesheet_id' AS root_timesheet_id,
                          UPPER(BTRIM(component.value->>'component_key_type')) AS key_type,
                          BTRIM(component.value->>'component_key_value') AS key_value,
                          component.value->>'truth_ex_vat' AS truth_ex_vat,
                          component.value->>'target_outstanding_ex_vat' AS outstanding_ex_vat
                        FROM jsonb_array_elements(public._ctms_candidate_correction_residuals_v1(
                          v_workbench_session_id_text::uuid,
                          v_preview_candidate_loop_id,
                          NULL::uuid,
                          'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_METADATA_DIAGNOSTIC'
                        )) AS residual(value)
                        CROSS JOIN LATERAL jsonb_array_elements(
                          COALESCE(residual.value->'components', '[]'::jsonb)
                        ) AS component(value)
                        WHERE COALESCE((residual.value->>'draftable')::boolean, false)
                          AND ROUND(COALESCE(NULLIF(component.value->>'target_outstanding_ex_vat', '')::numeric, 0), 2) < 0
                        ORDER BY residual.value->>'root_timesheet_id',
                                 UPPER(BTRIM(component.value->>'component_key_type')),
                                 BTRIM(component.value->>'component_key_value')
                        LIMIT 10
                      ) AS bounded_correction
                    ),
                    'message', 'Canonical negative component keys were not represented by preview metadata whose current component totals match authoritative live truth.'
                  )::text;
        END IF;

        INSERT INTO pg_temp.tmp_sync_raw_negative_timesheet_rows (
          candidate_id,
          timesheet_id,
          client_id,
          candidate_pay_method,
          case_is_blocked,
          case_components_json
        )
        SELECT
          raw_case.candidate_id,
          raw_case.timesheet_id,
          raw_case.client_id,
          (SELECT MIN(sealed.target_pay_method)
            FROM pg_temp.tmp_sync_sealed_rate_projection sealed
            WHERE sealed.timesheet_id=raw_case.timesheet_id),
          COALESCE(raw_case.is_blocked, false),
          COALESCE((
            SELECT jsonb_agg(
              raw_component.value
              || jsonb_build_object(
                'component_amount_ex_vat',sealed.outstanding_ex_vat,
                'authoritative_truth_ex_vat',sealed.truth_ex_vat,
                'authoritative_baseline_ex_vat',sealed.baseline_ex_vat,
                'authoritative_reserved_ex_vat',sealed.reserved_ex_vat,
                'authoritative_outstanding_ex_vat',sealed.outstanding_ex_vat,
                'overpayment_component_authority','PRE_DRAFT_LIVE_TRUTH',
                'physical_bucket_key',sealed.physical_bucket_key,
                'physical_bucket_digest',sealed.physical_bucket_digest,
                'sealed_evidence_digest',sealed.sealed_evidence_digest
              )
              ORDER BY sealed.economic_key_type,sealed.economic_key_value,
                sealed.bucket_sort_ordinal,sealed.physical_bucket_key
            )
            FROM jsonb_array_elements(CASE
              WHEN jsonb_typeof(raw_case.case_components_json)='array'
                THEN raw_case.case_components_json ELSE '[]'::jsonb END)
              WITH ORDINALITY raw_component(value,ordinality)
            JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
              ON sealed.timesheet_id=raw_case.timesheet_id
             AND sealed.economic_key_type=UPPER(BTRIM(raw_component.value->>'component_key_type'))
             AND sealed.economic_key_value=BTRIM(raw_component.value->>'component_key_value')
             AND sealed.physical_bucket_key=concat_ws('|','RATE_BUCKET_V1',
               raw_case.timesheet_id::text,
               NULLIF(BTRIM(raw_component.value->>'source_family_key'),''),
               UPPER(BTRIM(raw_component.value->>'component_key_type')),
               BTRIM(raw_component.value->>'component_key_value'),
               CASE
                 WHEN UPPER(BTRIM(COALESCE(
                     raw_component.value#>>'{source_basis_json,component_fallback}','')))
                       ='WORKED_TIME_AMOUNT'
                   THEN 'worked-time-residual:'
                     ||UPPER(BTRIM(raw_component.value->>'component_key_type'))||':'
                     ||BTRIM(raw_component.value->>'component_key_value')
                 WHEN UPPER(BTRIM(raw_component.value->>'component_key_type')) IN ('TS_DAY','TS_TOTAL')
                   THEN COALESCE(NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_stable_key}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_id}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_key}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,work_date}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,date}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,ref_num}'),''))
                 WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADDITIONAL_CODE'
                   THEN 'additional:'||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,additional_code}'))
                 WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='EXPENSE_CODE'
                   THEN 'expense:'||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,expense_code}'))
                 WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADJUSTMENT_CODE'
                   THEN 'adjustment:'||BTRIM(raw_component.value#>>'{source_basis_json,adjustment_id}')
               END,
               UPPER(BTRIM(COALESCE(
                 CASE WHEN UPPER(BTRIM(COALESCE(
                     raw_component.value#>>'{source_basis_json,component_fallback}','')))
                       ='WORKED_TIME_AMOUNT' THEN 'FIXED' END,
                 NULLIF(raw_component.value#>>'{source_basis_json,bucket_code}',''),
                 CASE UPPER(BTRIM(raw_component.value->>'component_key_type'))
                   WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
                   WHEN 'EXPENSE_CODE' THEN 'FIXED'
                   WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
                 END))))
            JOIN pg_temp.tmp_sync_authoritative_negative_components negative_component
              ON negative_component.timesheet_id=sealed.timesheet_id
             AND negative_component.key_type=sealed.economic_key_type
             AND negative_component.key_value=sealed.economic_key_value
          ),'[]'::jsonb)
        FROM pg_temp.timesheet_case_rollup AS raw_case
        WHERE raw_case.candidate_id = v_preview_candidate_loop_id
          AND raw_case.timesheet_id = ANY(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[]))
          AND NOT (raw_case.timesheet_id = ANY(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])))
          AND NOT (
            raw_case.timesheet_id
              = ANY(COALESCE(v_resolution_pending_member_ids, ARRAY[]::uuid[]))
          )
          AND EXISTS (
            SELECT 1
            FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
            WHERE authoritative_component.timesheet_id = raw_case.timesheet_id
          )
        ON CONFLICT (candidate_id, timesheet_id) DO UPDATE
        SET
          client_id = EXCLUDED.client_id,
          candidate_pay_method = EXCLUDED.candidate_pay_method,
          case_is_blocked = EXCLUDED.case_is_blocked,
          case_components_json = EXCLUDED.case_components_json;

        WITH missing_components AS (
          SELECT missing.candidate_id,missing.timesheet_id,
            jsonb_agg(missing.component_json ORDER BY missing.economic_key_type,
              missing.economic_key_value,missing.bucket_sort_ordinal,
              missing.physical_bucket_key) AS components_json
          FROM pg_temp.tmp_sync_sealed_missing_preview_components missing
          JOIN pg_temp.tmp_sync_authoritative_negative_components negative_component
            ON negative_component.timesheet_id=missing.timesheet_id
           AND negative_component.key_type=missing.economic_key_type
           AND negative_component.key_value=missing.economic_key_value
          WHERE missing.candidate_id=v_preview_candidate_loop_id
          GROUP BY missing.candidate_id,missing.timesheet_id
        )
        UPDATE pg_temp.tmp_sync_raw_negative_timesheet_rows raw_row
        SET case_components_json=raw_row.case_components_json||missing.components_json
        FROM missing_components missing
        WHERE raw_row.candidate_id=missing.candidate_id
          AND raw_row.timesheet_id=missing.timesheet_id;

        INSERT INTO pg_temp.tmp_sync_raw_negative_timesheet_rows(
          candidate_id,timesheet_id,client_id,candidate_pay_method,
          case_is_blocked,case_components_json
        )
        SELECT missing.candidate_id,missing.timesheet_id,baseline.client_id,
          (SELECT MIN(sealed.target_pay_method)
           FROM pg_temp.tmp_sync_sealed_rate_projection sealed
           WHERE sealed.timesheet_id=missing.timesheet_id),
          false,missing.components_json
        FROM (
          SELECT sealed_missing.candidate_id,sealed_missing.timesheet_id,
            jsonb_agg(sealed_missing.component_json ORDER BY
              sealed_missing.economic_key_type,sealed_missing.economic_key_value,
              sealed_missing.bucket_sort_ordinal,sealed_missing.physical_bucket_key)
              AS components_json
          FROM pg_temp.tmp_sync_sealed_missing_preview_components sealed_missing
          JOIN pg_temp.tmp_sync_authoritative_negative_components negative_component
            ON negative_component.timesheet_id=sealed_missing.timesheet_id
           AND negative_component.key_type=sealed_missing.economic_key_type
           AND negative_component.key_value=sealed_missing.economic_key_value
          WHERE sealed_missing.candidate_id=v_preview_candidate_loop_id
          GROUP BY sealed_missing.candidate_id,sealed_missing.timesheet_id
        ) missing
        JOIN pg_temp.ts_baseline baseline
          ON baseline.candidate_id=missing.candidate_id
         AND baseline.timesheet_id=missing.timesheet_id
        WHERE NOT EXISTS(
          SELECT 1 FROM pg_temp.tmp_sync_raw_negative_timesheet_rows existing_row
          WHERE existing_row.candidate_id=missing.candidate_id
            AND existing_row.timesheet_id=missing.timesheet_id
        );

        IF EXISTS(
          SELECT 1 FROM pg_temp.tmp_sync_authoritative_negative_components negative_component
          WHERE NOT (negative_component.timesheet_id
              =ANY(COALESCE(v_resolution_pending_root_ids,ARRAY[]::uuid[])))
            AND NOT (negative_component.timesheet_id
              =ANY(COALESCE(v_resolution_pending_member_ids,ARRAY[]::uuid[])))
            AND NOT EXISTS(SELECT 1 FROM pg_temp.tmp_sync_raw_negative_timesheet_rows raw_row
              WHERE raw_row.candidate_id=v_preview_candidate_loop_id
                AND raw_row.timesheet_id=negative_component.timesheet_id)
        ) THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_COMPONENT_MISSING'
            USING ERRCODE='P0001',DETAIL=jsonb_build_object(
              'code','PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_COMPONENT_MISSING',
              'candidate_id',v_preview_candidate_loop_id::text)::text;
        END IF;

        IF EXISTS (
          WITH allocated_component_totals AS (
            SELECT
              raw_timesheet.timesheet_id,
              UPPER(BTRIM(COALESCE(component.value->>'component_key_type', ''))) AS key_type,
              BTRIM(COALESCE(component.value->>'component_key_value', '')) AS key_value,
              COUNT(*)::integer AS allocated_component_count,
              ROUND(SUM((component.value->>'component_amount_ex_vat')::numeric), 2)::numeric(12,2) AS allocated_outstanding_ex_vat
            FROM pg_temp.tmp_sync_raw_negative_timesheet_rows AS raw_timesheet
            CROSS JOIN LATERAL jsonb_array_elements(raw_timesheet.case_components_json) AS component(value)
            WHERE raw_timesheet.candidate_id = v_preview_candidate_loop_id
              AND COALESCE(component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            GROUP BY
              raw_timesheet.timesheet_id,
              UPPER(BTRIM(COALESCE(component.value->>'component_key_type', ''))),
              BTRIM(COALESCE(component.value->>'component_key_value', ''))
          )
          SELECT 1
          FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
          LEFT JOIN allocated_component_totals AS allocated_total
            ON allocated_total.timesheet_id = authoritative_component.timesheet_id
           AND allocated_total.key_type = authoritative_component.key_type
           AND allocated_total.key_value = authoritative_component.key_value
          WHERE (
                  allocated_total.allocated_component_count IS NULL
                  OR (
                  ABS(ROUND(
                    COALESCE(allocated_total.allocated_outstanding_ex_vat, 0)
                    - authoritative_component.outstanding_ex_vat,
                    2
                  )) > 0.01
                )
                )
            AND NOT (
              authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_root_ids, ARRAY[]::uuid[]))
              OR authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_member_ids, ARRAY[]::uuid[]))
            )
        ) THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH',
                    'candidate_id', v_preview_candidate_loop_id::text,
                    'negative_component_count', COALESCE(v_authoritative_negative_component_count, 0),
                    'negative_component_digest', v_authoritative_negative_component_digest,
                    'message', 'Canonical negative components were not represented exactly by the validated pre-draft component allocations.'
                  )::text;
        END IF;
      END IF;

      v_preview_candidate_row_json := CASE
        WHEN jsonb_typeof(v_preview_baseline_json->'candidate_row') = 'object'
          THEN COALESCE(v_preview_baseline_json->'candidate_row', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      IF NULLIF(BTRIM(COALESCE(
           v_preview_candidate_row_json->>'candidate_id',
           v_preview_baseline_json->>'candidate_id',
           ''
         )), '') IS DISTINCT FROM v_preview_candidate_loop_id::text THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope,
                  'baseline_candidate_id', NULLIF(BTRIM(COALESCE(
                    v_preview_candidate_row_json->>'candidate_id',
                    v_preview_baseline_json->>'candidate_id',
                    ''
                  )), '')
                )::text;
      END IF;

      IF UPPER(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', ''))) IS DISTINCT FROM v_scope THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_PAY_CHANNEL_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_PAY_CHANNEL_MISMATCH',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'requested_pay_channel_scope', v_scope,
                  'current_pay_method', NULLIF(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', '')), '')
                )::text;
      END IF;

      v_preview_candidate_row_json := v_preview_candidate_row_json
        || jsonb_build_object(
          'candidate_id', v_preview_candidate_loop_id::text,
          'itemisation', CASE
            WHEN jsonb_typeof(v_preview_candidate_row_json->'itemisation') = 'array'
              THEN COALESCE(v_preview_candidate_row_json->'itemisation', '[]'::jsonb)
            WHEN jsonb_typeof(v_preview_baseline_json->'itemisation') = 'array'
              THEN COALESCE(v_preview_baseline_json->'itemisation', '[]'::jsonb)
            ELSE '[]'::jsonb
          END
        );

      INSERT INTO pg_temp.tmp_sync_preview_candidates (
        candidate_id,
        candidate_json
      )
      VALUES (
        v_preview_candidate_loop_id,
        v_preview_candidate_row_json
      )
      ON CONFLICT (candidate_id) DO UPDATE
      SET candidate_json = EXCLUDED.candidate_json;
    END LOOP;
  ELSE
    v_preview_scope_context_json := public.pay_preview_build_context(
      p_pay_date => p_pay_date,
      p_week_ending_cutoff => p_week_ending_cutoff,
      p_actor_user_id => p_actor_user_id,
      p_candidate_id => NULL::uuid,
      p_client_id => p_client_filter_single,
      p_preview_decisions_json => v_preview_decisions_json
        || jsonb_build_object(
          'preview_context_mode', 'PAGE',
          'scope_limit', 100
        )
    );

    v_preview_scope_candidate_ids_json := CASE
      WHEN jsonb_typeof(v_preview_scope_context_json->'candidate_ids') = 'array'
        THEN COALESCE(v_preview_scope_context_json->'candidate_ids', '[]'::jsonb)
      ELSE '[]'::jsonb
    END;

    IF LOWER(BTRIM(COALESCE(v_preview_scope_context_json->>'has_more', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_REQUIRES_EXPLICIT_IDS'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_REQUIRES_EXPLICIT_IDS',
                'message', 'The bounded candidate page is incomplete. Supply explicit candidate_ids rather than accepting a partial all-candidate reconciliation.',
                'pay_channel_scope', v_scope,
                'page_count', COALESCE(v_preview_scope_context_json->>'page_count', '0'),
                'limit', COALESCE(v_preview_scope_context_json->>'limit', '100'),
                'next_cursor_json', COALESCE(v_preview_scope_context_json->'next_cursor_json', 'null'::jsonb)
              )::text;
    END IF;

    FOR v_preview_candidate_loop_id IN
      SELECT DISTINCT scoped_candidate.value::uuid
      FROM jsonb_array_elements_text(COALESCE(v_preview_scope_candidate_ids_json, '[]'::jsonb)) AS scoped_candidate(value)
      WHERE scoped_candidate.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ORDER BY scoped_candidate.value::uuid
    LOOP
      v_preview_context_json := public.pay_preview_build_context(
        p_pay_date => p_pay_date,
        p_week_ending_cutoff => p_week_ending_cutoff,
        p_actor_user_id => p_actor_user_id,
        p_candidate_id => v_preview_candidate_loop_id,
        p_client_id => p_client_filter_single,
        p_preview_decisions_json => v_preview_decisions_json
      )
      || jsonb_build_object(
        'overpayment_sync_mode', true,
        'emit_raw_overpayment_components', true,
        'pay_channel_scope', v_scope,
        'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
        'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb)
      );

      v_preview_baseline_json := public.pay_preview_candidate_build_summary_fragment(
        p_context_json => v_preview_context_json,
        p_candidate_id => v_preview_candidate_loop_id
      );

      v_preview_candidate_row_json := CASE
        WHEN jsonb_typeof(v_preview_baseline_json->'candidate_row') = 'object'
          THEN COALESCE(v_preview_baseline_json->'candidate_row', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      IF NULLIF(BTRIM(COALESCE(
           v_preview_candidate_row_json->>'candidate_id',
           v_preview_baseline_json->>'candidate_id',
           ''
         )), '') IS DISTINCT FROM v_preview_candidate_loop_id::text THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope
                )::text;
      END IF;

      IF UPPER(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', ''))) = v_scope THEN
        v_preview_candidate_row_json := v_preview_candidate_row_json
          || jsonb_build_object(
            'candidate_id', v_preview_candidate_loop_id::text,
            'itemisation', CASE
              WHEN jsonb_typeof(v_preview_candidate_row_json->'itemisation') = 'array'
                THEN COALESCE(v_preview_candidate_row_json->'itemisation', '[]'::jsonb)
              WHEN jsonb_typeof(v_preview_baseline_json->'itemisation') = 'array'
                THEN COALESCE(v_preview_baseline_json->'itemisation', '[]'::jsonb)
              ELSE '[]'::jsonb
            END
          );

        INSERT INTO pg_temp.tmp_sync_preview_candidates (
          candidate_id,
          candidate_json
        )
        VALUES (
          v_preview_candidate_loop_id,
          v_preview_candidate_row_json
        )
        ON CONFLICT (candidate_id) DO UPDATE
        SET candidate_json = EXCLUDED.candidate_json;
      END IF;
    END LOOP;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_preview_candidate_count
  FROM pg_temp.tmp_sync_preview_candidates AS preview_candidate;

  WITH requested_candidates AS (
    SELECT DISTINCT requested_candidate.candidate_id
    FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
    WHERE requested_candidate.candidate_id IS NOT NULL
  ), missing_candidates AS (
    SELECT requested_candidates.candidate_id
    FROM requested_candidates
    WHERE NOT EXISTS (
      SELECT 1
      FROM pg_temp.tmp_sync_preview_candidates AS preview_candidate
      WHERE preview_candidate.candidate_id = requested_candidates.candidate_id
    )
  )
  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(missing_candidates.candidate_id::text ORDER BY missing_candidates.candidate_id), '[]'::jsonb)
  INTO v_missing_candidate_count,
       v_missing_candidate_ids_json
  FROM missing_candidates;

  IF COALESCE(v_missing_candidate_count, 0) > 0 THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
              'pay_channel_scope', v_scope,
              'requested_candidate_count', v_requested_candidate_count,
              'preview_candidate_count', v_preview_candidate_count,
              'missing_candidate_ids', COALESCE(v_missing_candidate_ids_json, '[]'::jsonb)
            )::text;
  END IF;

  v_preview_workspace_ms := COALESCE(v_preview_collect_ms, 0)
    + COALESCE(v_preview_canonical_ms, 0)
    + COALESCE(v_preview_summary_ms, 0);
  v_phase_started_at := clock_timestamp();

  insert into pg_temp.tmp_sync_timesheet_case_candidates (
    candidate_id,
    timesheet_id,
    client_id,
    linked_shift_date,
    corrected_amount_ex,
    baseline_signature,
    candidate_pay_method,
    case_is_blocked,
    needs_lifecycle_tracking,
    overpayment_amount_ex,
    underpayment_amount_ex,
    desired_case_type,
    desired_advance_kind,
    desired_reason,
    source_original_paid_amount,
    source_corrected_paid_amount,
    components_sync_json
  )
  with candidate_rows as (
    select
      preview_candidate.candidate_id,
      upper(btrim(coalesce(preview_candidate.candidate_json->>'current_pay_method', ''))) as candidate_pay_method,
      case
        when jsonb_typeof(preview_candidate.candidate_json->'itemisation') = 'array'
          then coalesce(preview_candidate.candidate_json->'itemisation', '[]'::jsonb)
        else '[]'::jsonb
      end as itemisation_json
    from pg_temp.tmp_sync_preview_candidates as preview_candidate
    where upper(btrim(coalesce(preview_candidate.candidate_json->>'current_pay_method', ''))) = v_scope
      and (
        coalesce(array_length(p_candidate_ids, 1), 0) = 0
        or preview_candidate.candidate_id = any(p_candidate_ids)
      )
  ),
  itemisation_timesheet_rows as (
    select cr.candidate_id,cr.candidate_pay_method,itm.value as item_json,
      nullif(btrim(coalesce(itm.value->>'timesheet_id','')),'')::uuid as timesheet_id,
      nullif(btrim(coalesce(itm.value->>'client_id','')),'')::uuid as client_id,
      round(coalesce(nullif(itm.value->>'amount_ex_vat','')::numeric,0),2)::numeric(12,2) as corrected_amount_ex,
      coalesce(itm.value->>'case_is_blocked','false')::boolean as case_is_blocked,
      coalesce(itm.value->'case_components','[]'::jsonb) as case_components_json
    from candidate_rows cr
    cross join lateral jsonb_array_elements(coalesce(cr.itemisation_json,'[]'::jsonb)) itm(value)
    where coalesce(itm.value->>'line_type','')='TIMESHEET_PAYMENT'
      and nullif(btrim(coalesce(itm.value->>'timesheet_id','')),'') is not null
      and (coalesce(array_length(p_force_include_timesheet_ids,1),0)=0
        or nullif(btrim(coalesce(itm.value->>'timesheet_id','')),'')::uuid=any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null)
      and not (coalesce(array_length(p_exclude_timesheet_ids,1),0)>0
        and nullif(btrim(coalesce(itm.value->>'timesheet_id','')),'')::uuid=any(p_exclude_timesheet_ids))
  ),
  authoritative_timesheet_rows AS (
    SELECT v_authoritative_candidate_id AS candidate_id,
      (SELECT MIN(sealed.target_pay_method)
       FROM pg_temp.tmp_sync_sealed_rate_projection sealed) AS candidate_pay_method,
      jsonb_build_object('line_type','TIMESHEET_PAYMENT','timesheet_id',scope_row.timesheet_id::text,
        'client_id',CASE WHEN metadata.client_id IS NULL THEN NULL ELSE metadata.client_id::text END,
        'amount_ex_vat',ROUND(COALESCE(economic_total.truth_ex_vat,0),2),
        'case_is_blocked',COALESCE(metadata.case_is_blocked,false),
        'case_components',COALESCE(physical_components.case_components_json,'[]'::jsonb)
          ||COALESCE(missing_physical_components.case_components_json,'[]'::jsonb),
        'source_authority','SEALED_ECONOMIC_BUILD_FACTS','build_id',p_build_id::text) AS item_json,
      scope_row.timesheet_id,metadata.client_id,
      ROUND(COALESCE(economic_total.truth_ex_vat,0),2)::numeric(12,2) AS corrected_amount_ex,
      COALESCE(metadata.case_is_blocked,false) AS case_is_blocked,
      COALESCE(physical_components.case_components_json,'[]'::jsonb)
        ||COALESCE(missing_physical_components.case_components_json,'[]'::jsonb)
        AS case_components_json
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN LATERAL (
      SELECT COALESCE(preview_row.client_id,current_financial.client_id) AS client_id,
        COALESCE(preview_row.case_is_blocked,false) AS case_is_blocked
      FROM (SELECT 1) seed
      LEFT JOIN LATERAL (
        SELECT item.client_id,item.case_is_blocked
        FROM itemisation_timesheet_rows item WHERE item.timesheet_id=scope_row.timesheet_id LIMIT 1
      ) preview_row ON true
      LEFT JOIN LATERAL (
        SELECT financial.client_id FROM public.timesheets_financials financial
        WHERE financial.timesheet_id=scope_row.timesheet_id AND financial.is_current
          AND financial.candidate_id=v_authoritative_candidate_id
        ORDER BY financial.computed_at_utc DESC NULLS LAST,financial.id DESC LIMIT 1
      ) current_financial ON true
    ) metadata ON true
    LEFT JOIN LATERAL (
      SELECT ROUND(COALESCE(SUM(component.truth_ex_vat),0),2) AS truth_ex_vat
      FROM pg_temp.tmp_sync_authoritative_components component
      WHERE component.timesheet_id=scope_row.timesheet_id
    ) economic_total ON true
    LEFT JOIN LATERAL (
      SELECT COALESCE(jsonb_agg(
        raw_component.value||jsonb_build_object(
          'component_amount_ex_vat',sealed.outstanding_ex_vat,
          'authoritative_truth_ex_vat',sealed.truth_ex_vat,
          'authoritative_baseline_ex_vat',sealed.baseline_ex_vat,
          'authoritative_reserved_ex_vat',sealed.reserved_ex_vat,
          'authoritative_outstanding_ex_vat',sealed.outstanding_ex_vat,
          'overpayment_component_authority','PRE_DRAFT_LIVE_TRUTH',
          'physical_bucket_key',sealed.physical_bucket_key,
           'physical_bucket_digest',sealed.physical_bucket_digest,
           'sealed_evidence_digest',sealed.sealed_evidence_digest,
           'financial_revision_digest',sealed.financial_revision_digest,
           'target_authority_digest',sealed.target_authority_digest,
           'conversion_context_digest',sealed.conversion_context_digest,
           'source_pay_method',sealed.source_pay_method,
           'current_target_pay_method',sealed.target_pay_method,
           'source_basis_json',(CASE
             WHEN jsonb_typeof(raw_component.value->'source_basis_json')='object'
               THEN raw_component.value->'source_basis_json'
             ELSE '{}'::jsonb END)||jsonb_build_object(
               'source_pay_method',sealed.source_pay_method))
        ORDER BY raw_component.ordinality),'[]'::jsonb) AS case_components_json
      FROM pg_temp.timesheet_case_rollup raw_case
      CROSS JOIN LATERAL jsonb_array_elements(CASE
        WHEN jsonb_typeof(raw_case.case_components_json)='array'
          THEN raw_case.case_components_json ELSE '[]'::jsonb END)
        WITH ORDINALITY raw_component(value,ordinality)
      JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
        ON sealed.timesheet_id=raw_case.timesheet_id
       AND sealed.economic_key_type=UPPER(BTRIM(raw_component.value->>'component_key_type'))
       AND sealed.economic_key_value=BTRIM(raw_component.value->>'component_key_value')
       AND sealed.physical_bucket_key=concat_ws('|','RATE_BUCKET_V1',
         raw_case.timesheet_id::text,
         NULLIF(BTRIM(raw_component.value->>'source_family_key'),''),
         UPPER(BTRIM(raw_component.value->>'component_key_type')),
         BTRIM(raw_component.value->>'component_key_value'),
         CASE
           WHEN UPPER(BTRIM(COALESCE(
               raw_component.value#>>'{source_basis_json,component_fallback}','')))
                 ='WORKED_TIME_AMOUNT'
             THEN 'worked-time-residual:'
               ||UPPER(BTRIM(raw_component.value->>'component_key_type'))||':'
               ||BTRIM(raw_component.value->>'component_key_value')
           WHEN UPPER(BTRIM(raw_component.value->>'component_key_type')) IN ('TS_DAY','TS_TOTAL')
             THEN COALESCE(NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_stable_key}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_id}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_key}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,work_date}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,date}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,ref_num}'),''))
           WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADDITIONAL_CODE'
             THEN 'additional:'||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,additional_code}'))
           WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='EXPENSE_CODE'
             THEN 'expense:'||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,expense_code}'))
           WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADJUSTMENT_CODE'
             THEN 'adjustment:'||BTRIM(raw_component.value#>>'{source_basis_json,adjustment_id}')
         END,
         UPPER(BTRIM(COALESCE(
           CASE WHEN UPPER(BTRIM(COALESCE(
               raw_component.value#>>'{source_basis_json,component_fallback}','')))
                 ='WORKED_TIME_AMOUNT' THEN 'FIXED' END,
           NULLIF(raw_component.value#>>'{source_basis_json,bucket_code}',''),
           CASE UPPER(BTRIM(raw_component.value->>'component_key_type'))
             WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
             WHEN 'EXPENSE_CODE' THEN 'FIXED'
              WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
            END))))
      WHERE raw_case.candidate_id=v_authoritative_candidate_id
        AND raw_case.timesheet_id=scope_row.timesheet_id
    ) physical_components ON true
    LEFT JOIN LATERAL (
      SELECT COALESCE(jsonb_agg(missing.component_json ORDER BY
        missing.economic_key_type,missing.economic_key_value,
        missing.bucket_sort_ordinal,missing.physical_bucket_key),'[]'::jsonb)
        AS case_components_json
      FROM pg_temp.tmp_sync_sealed_missing_preview_components missing
      WHERE missing.candidate_id=v_authoritative_candidate_id
        AND missing.timesheet_id=scope_row.timesheet_id
    ) missing_physical_components ON true
    WHERE scope_row.build_id=p_build_id
      AND (coalesce(array_length(p_force_include_timesheet_ids,1),0)=0
        OR scope_row.timesheet_id=ANY(p_force_include_timesheet_ids)
        OR p_force_include_timesheet_ids IS NULL)
      AND NOT (coalesce(array_length(p_exclude_timesheet_ids,1),0)>0
        AND scope_row.timesheet_id=ANY(p_exclude_timesheet_ids))
  ),
  timesheet_item_rows AS (
    SELECT item.candidate_id,item.candidate_pay_method,item.item_json,item.timesheet_id,item.client_id,
      item.corrected_amount_ex,item.case_is_blocked,item.case_components_json
    FROM authoritative_timesheet_rows item
    WHERE COALESCE(v_authoritative_timesheet_scope,false)
    UNION ALL
    SELECT item.candidate_id,item.candidate_pay_method,item.item_json,item.timesheet_id,item.client_id,
      item.corrected_amount_ex,item.case_is_blocked,item.case_components_json
    FROM itemisation_timesheet_rows item
    WHERE NOT COALESCE(v_authoritative_timesheet_scope,false)
  ),
  active_settled_basis AS (
    SELECT
      distinct_timesheet_rows.timesheet_id,
      active_components.active_settled_component_count,
      active_components.active_settled_amount_ex,
      active_components.active_settled_signature
    FROM (
      SELECT DISTINCT timesheet_item_rows.timesheet_id
      FROM timesheet_item_rows
      WHERE timesheet_item_rows.timesheet_id IS NOT NULL
    ) AS distinct_timesheet_rows
    LEFT JOIN LATERAL (
      SELECT
        count(*)::integer AS active_settled_component_count,
        round(COALESCE(sum(COALESCE(active_settled_rows.amount_ex_vat, 0)), 0), 2)::numeric(12,2) AS active_settled_amount_ex,
        md5(COALESCE(jsonb_agg(
          jsonb_build_object(
            'key_type', active_settled_rows.key_type,
            'key_value', active_settled_rows.key_value,
            'amount_ex_vat', round(COALESCE(active_settled_rows.amount_ex_vat, 0), 2),
            'amount_inc_vat', round(COALESCE(active_settled_rows.amount_inc_vat, 0), 2)
          )
          ORDER BY active_settled_rows.key_type, active_settled_rows.key_value
        )::text, '[]')) AS active_settled_signature
      FROM (
        SELECT fact.economic_key_type AS key_type,fact.economic_key_value AS key_value,
          fact.amount_ex_vat,fact.amount_inc_vat
        FROM private.banking_pay_workbench_economic_build_facts fact
        WHERE fact.build_id=p_build_id AND fact.timesheet_id=distinct_timesheet_rows.timesheet_id
          AND fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
      ) AS active_settled_rows
    ) AS active_components
      ON true
  ),
  timesheet_item_with_baseline as (
    select
      tir.candidate_id,
      tir.timesheet_id,
      tir.client_id,
      coalesce(ts.worked_start_iso::date, ts.scheduled_start_iso::date, ts.week_ending_date) as linked_shift_date,
      tir.corrected_amount_ex,
      case
        when COALESCE(active_settled_basis.active_settled_component_count, 0) > 0
          then active_settled_basis.active_settled_signature
        else coalesce(
          tps.last_settled_signature,
          md5(coalesce(tps.last_settled_snapshot_json::text, '{}'))
        )
      end as baseline_signature,
      tir.candidate_pay_method,
      tir.case_is_blocked,
      tir.case_components_json
    from timesheet_item_rows tir
    join public.timesheets ts
      on ts.timesheet_id = tir.timesheet_id
    left join public.timesheet_pay_state tps
      on tps.timesheet_id = tir.timesheet_id
    left join active_settled_basis
      on active_settled_basis.timesheet_id = tir.timesheet_id
  ),
  timesheet_exploded_components as (
    select
      tiwb.candidate_id,
      tiwb.timesheet_id,
      tiwb.client_id,
      tiwb.linked_shift_date,
      tiwb.corrected_amount_ex,
      tiwb.baseline_signature,
      tiwb.candidate_pay_method,
      tiwb.case_is_blocked,
      comp.value as component_json,
      comp.ordinality::integer as component_order,
      UPPER(NULLIF(BTRIM(COALESCE(comp.value->>'component_key_type', '')), '')) AS component_key_type,
      NULLIF(BTRIM(COALESCE(comp.value->>'component_key_value', '')), '') AS component_key_value,
      round(coalesce(nullif(comp.value->>'component_amount_ex_vat', '')::numeric, 0), 2)::numeric(12,2) as component_amount_ex
    from timesheet_item_with_baseline tiwb
    cross join lateral jsonb_array_elements(coalesce(tiwb.case_components_json, '[]'::jsonb)) with ordinality as comp(value, ordinality)
  ),
  finance_component_movements_raw as (
    /* Authoritative builds have already folded settled baseline and active
       reservations into each signed component.  Keep the movement relation
       fact-owned so no mutable finance table can change the result. */
    select v_authoritative_candidate_id as candidate_id,fact.timesheet_id,
      upper(btrim(coalesce(fact.economic_key_type,''))) as component_key_type,
      nullif(btrim(coalesce(fact.economic_key_value,'')),'') as component_key_value,
      case
        when fact.fact_family='FROZEN_SETTLED_COMPONENT' then upper(btrim(coalesce(
          fact.source_payload_json #>> '{pay_batch_item,item_type}',
          fact.source_payload_json->>'item_type','')))
        when fact.fact_family='RESERVATION_COMPONENT' then case upper(coalesce((
          select case_fact.source_payload_json->>'case_type'
          from private.banking_pay_workbench_economic_build_facts case_fact
          where case_fact.build_id=fact.build_id
            and case_fact.fact_family='FINANCE_CASE_IDENTITY'
            and case_fact.finance_case_id=fact.finance_case_id
          limit 1),'OVERPAYMENT'))
          when 'UNDERPAYMENT' then 'UNDERPAYMENT_PAYMENT' else 'OVERPAYMENT_RECOVERY' end
        else NULL end as item_type,
      round(abs(coalesce(fact.amount_ex_vat,fact.reserved_source_amount,0)),2)::numeric(12,2) as movement_amount_ex,
      (fact.fact_family='FROZEN_SETTLED_COMPONENT') as is_settled_movement,
      (fact.fact_family='RESERVATION_COMPONENT') as is_active_reservation
    from private.banking_pay_workbench_economic_build_facts fact
    where fact.build_id=p_build_id
      and fact.fact_family in ('FROZEN_SETTLED_COMPONENT','RESERVATION_COMPONENT')
      and fact.timesheet_id is not null
      and (not v_slice_active or fact.timesheet_id=any(v_bounded_scope_ids)) /* A28 */
  ),
  finance_component_movements as (
    select
      fcmr.candidate_id,
      fcmr.timesheet_id,
      fcmr.component_key_type,
      fcmr.component_key_value,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'OVERPAYMENT_RECOVERY' and fcmr.is_settled_movement), 0), 2)::numeric(12,2) as settled_overpayment_recovery_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'OVERPAYMENT_RECOVERY' and fcmr.is_active_reservation), 0), 2)::numeric(12,2) as reserved_overpayment_recovery_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'UNDERPAYMENT_PAYMENT' and fcmr.is_settled_movement), 0), 2)::numeric(12,2) as settled_underpayment_payment_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'UNDERPAYMENT_PAYMENT' and fcmr.is_active_reservation), 0), 2)::numeric(12,2) as reserved_underpayment_payment_ex,
      true as has_finance_movement
    from finance_component_movements_raw fcmr
    where fcmr.component_key_type is not null
      and fcmr.component_key_value is not null
    group by fcmr.candidate_id, fcmr.timesheet_id, fcmr.component_key_type, fcmr.component_key_value
  ),
  timesheet_exploded_with_signed_balance as (
    select
      tec.*,
      coalesce(fcm.settled_overpayment_recovery_ex, 0) as settled_overpayment_recovery_ex,
      coalesce(fcm.reserved_overpayment_recovery_ex, 0) as reserved_overpayment_recovery_ex,
      coalesce(fcm.settled_underpayment_payment_ex, 0) as settled_underpayment_payment_ex,
      coalesce(fcm.reserved_underpayment_payment_ex, 0) as reserved_underpayment_payment_ex,
      coalesce(fcm.has_finance_movement, false) as has_finance_movement,
      case
        /* The authoritative pre-draft component amount is already the canonical
           live-truth minus settled-baseline minus active-reservation balance.
           Reapplying finance movements here would double count them. */
        when upper(btrim(coalesce(
               tec.component_json->>'overpayment_component_authority',
               ''
             ))) = 'PRE_DRAFT_LIVE_TRUTH'
          then round(coalesce(tec.component_amount_ex, 0), 2)::numeric(12,2)
        else round(
          coalesce(tec.component_amount_ex, 0)
          + coalesce(fcm.settled_overpayment_recovery_ex, 0)
          + coalesce(fcm.reserved_overpayment_recovery_ex, 0)
          - coalesce(fcm.settled_underpayment_payment_ex, 0)
          - coalesce(fcm.reserved_underpayment_payment_ex, 0),
          2
        )::numeric(12,2)
      end as signed_component_amount_ex
    from timesheet_exploded_components tec
    left join finance_component_movements fcm
      on fcm.candidate_id = tec.candidate_id
     and fcm.timesheet_id = tec.timesheet_id
     and fcm.component_key_type = tec.component_key_type
     and fcm.component_key_value = tec.component_key_value
  ),
  timesheet_case_rollup as (
    select
      tec.candidate_id,
      tec.timesheet_id,
      min(tec.client_id::text)::uuid as client_id,
      min(tec.linked_shift_date) as linked_shift_date,
      min(tec.corrected_amount_ex) as corrected_amount_ex,
      min(tec.baseline_signature) as baseline_signature,
      min(tec.candidate_pay_method) as candidate_pay_method,
      bool_or(tec.case_is_blocked) as case_is_blocked,
      bool_or(coalesce(tec.has_finance_movement, false)) as has_finance_movement,
      round(coalesce(sum(case when tec.signed_component_amount_ex < 0 and tec.component_key_type is not null and tec.component_key_value is not null then abs(tec.signed_component_amount_ex) else 0 end), 0), 2)::numeric(12,2) as overpayment_amount_ex,
      round(coalesce(sum(case when tec.signed_component_amount_ex > 0 and tec.component_key_type is not null and tec.component_key_value is not null then tec.signed_component_amount_ex else 0 end), 0), 2)::numeric(12,2) as underpayment_amount_ex,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'candidate_id', tec.candidate_id::text,
            'client_id', case when tec.client_id is null then null else tec.client_id::text end,
            'linked_timesheet_id', tec.timesheet_id::text,
            'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
            'component_key_type', tec.component_key_type,
            'component_key_value', tec.component_key_value,
            'classification', CASE
              WHEN upper(btrim(coalesce(tec.component_json->>'classification', ''))) IN ('TAXABLE_CHANNEL_SENSITIVE','REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY')
                THEN upper(btrim(coalesce(tec.component_json->>'classification', '')))
              WHEN tec.component_key_type = 'EXPENSE_CODE'
                THEN 'REIMBURSEMENT_GROSS_FIXED'
              ELSE 'TAXABLE_CHANNEL_SENSITIVE'
            END,
            'source_pay_method', nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''),
            'current_target_pay_method', nullif(btrim(coalesce(tec.component_json->>'current_target_pay_method', '')), ''),
            'source_basis_json', (CASE
              WHEN jsonb_typeof(tec.component_json->'source_basis_json') = 'object'
                   AND coalesce(tec.component_json->'source_basis_json', '{}'::jsonb) <> '{}'::jsonb
                THEN tec.component_json->'source_basis_json'
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id', tec.timesheet_id::text,
                'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
                'component_key_type', tec.component_key_type,
                'component_key_value', tec.component_key_value,
                'component_amount_ex_vat', abs(tec.signed_component_amount_ex)
              ))
            END)||jsonb_build_object('source_pay_method',
              nullif(btrim(coalesce(tec.component_json->>'source_pay_method','')),'')),
            'source_amount', abs(tec.signed_component_amount_ex),
            'overpayment_component_authority', NULLIF(UPPER(BTRIM(COALESCE(
              tec.component_json->>'overpayment_component_authority',
              ''
            ))), ''),
            'remaining_source_amount', CASE
              WHEN upper(btrim(coalesce(
                     tec.component_json->>'overpayment_component_authority',
                     ''
                   ))) = 'PRE_DRAFT_LIVE_TRUTH'
                THEN abs(tec.signed_component_amount_ex)
              ELSE NULL
            END,
            'allocation_priority_group', case when tec.component_json->>'classification' = 'TAXABLE_CHANNEL_SENSITIVE' then 0 else 1 end,
            'allocation_priority_order', tec.component_order
          )
          order by coalesce(tec.component_json->>'classification',''), coalesce(tec.component_json->>'component_key_type',''), coalesce(tec.component_json->>'component_key_value','')
        ) filter (where tec.signed_component_amount_ex < 0 and tec.component_key_type is not null and tec.component_key_value is not null),
        '[]'::jsonb
      ) as overpayment_components_json,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'candidate_id', tec.candidate_id::text,
            'client_id', case when tec.client_id is null then null else tec.client_id::text end,
            'linked_timesheet_id', tec.timesheet_id::text,
            'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
            'component_key_type', tec.component_key_type,
            'component_key_value', tec.component_key_value,
            'classification', CASE
              WHEN upper(btrim(coalesce(tec.component_json->>'classification', ''))) IN ('TAXABLE_CHANNEL_SENSITIVE','REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY')
                THEN upper(btrim(coalesce(tec.component_json->>'classification', '')))
              WHEN tec.component_key_type = 'EXPENSE_CODE'
                THEN 'REIMBURSEMENT_GROSS_FIXED'
              ELSE 'TAXABLE_CHANNEL_SENSITIVE'
            END,
            'source_pay_method', nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''),
            'current_target_pay_method', nullif(btrim(coalesce(tec.component_json->>'current_target_pay_method', '')), ''),
            'source_basis_json', (CASE
              WHEN jsonb_typeof(tec.component_json->'source_basis_json') = 'object'
                   AND coalesce(tec.component_json->'source_basis_json', '{}'::jsonb) <> '{}'::jsonb
                THEN tec.component_json->'source_basis_json'
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id', tec.timesheet_id::text,
                'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
                'component_key_type', tec.component_key_type,
                'component_key_value', tec.component_key_value,
                'component_amount_ex_vat', abs(tec.signed_component_amount_ex)
              ))
            END)||jsonb_build_object('source_pay_method',
              nullif(btrim(coalesce(tec.component_json->>'source_pay_method','')),'')),
            'source_amount', abs(tec.signed_component_amount_ex),
            'overpayment_component_authority', NULLIF(UPPER(BTRIM(COALESCE(
              tec.component_json->>'overpayment_component_authority',
              ''
            ))), ''),
            'remaining_source_amount', CASE
              WHEN upper(btrim(coalesce(
                     tec.component_json->>'overpayment_component_authority',
                     ''
                   ))) = 'PRE_DRAFT_LIVE_TRUTH'
                THEN abs(tec.signed_component_amount_ex)
              ELSE NULL
            END,
            'allocation_priority_group', case when tec.component_json->>'classification' = 'TAXABLE_CHANNEL_SENSITIVE' then 0 else 1 end,
            'allocation_priority_order', tec.component_order
          )
          order by coalesce(tec.component_json->>'classification',''), coalesce(tec.component_json->>'component_key_type',''), coalesce(tec.component_json->>'component_key_value','')
        ) filter (where tec.signed_component_amount_ex > 0 and tec.component_key_type is not null and tec.component_key_value is not null),
        '[]'::jsonb
      ) as underpayment_components_json
    from timesheet_exploded_with_signed_balance tec
    group by tec.candidate_id, tec.timesheet_id
  ),
  active_linked_underpayment_cases as (
    select
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      true as has_existing_active_underpayment_case
    from public.pay_advances pa
    where pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum
      and pa.linked_timesheet_id is not null
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and round(coalesce(pa.outstanding_amount, 0), 2) > 0
    group by pa.candidate_id, pa.linked_timesheet_id
  ),
  timesheet_case_candidates as (
    select
      tcr.candidate_id,
      tcr.timesheet_id,
      tcr.client_id,
      tcr.linked_shift_date,
      tcr.corrected_amount_ex,
      tcr.baseline_signature,
      tcr.candidate_pay_method,
      tcr.case_is_blocked,
      (
        tcr.overpayment_amount_ex > 0
        or (
          tcr.underpayment_amount_ex > 0
          and (
            tcr.case_is_blocked = true
            or coalesce(aluc.has_existing_active_underpayment_case, false) = true
            or coalesce(tcr.has_finance_movement, false) = true
          )
        )
      ) as needs_lifecycle_tracking,
      tcr.overpayment_amount_ex,
      tcr.underpayment_amount_ex,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_finance_case_type_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_finance_case_type_enum
        else null::public.pay_finance_case_type_enum
      end as desired_case_type,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_advance_kind_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_advance_kind_enum
        else null::public.pay_advance_kind_enum
      end as desired_advance_kind,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_advance_reason_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_advance_reason_enum
        else null::public.pay_advance_reason_enum
      end as desired_reason,
      case
        when tcr.overpayment_amount_ex > 0 then round(tcr.corrected_amount_ex + tcr.overpayment_amount_ex, 2)::numeric(12,2)
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then round(tcr.corrected_amount_ex - tcr.underpayment_amount_ex, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_original_paid_amount,
      case
        when tcr.overpayment_amount_ex > 0 then round(tcr.corrected_amount_ex, 2)::numeric(12,2)
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then round(tcr.corrected_amount_ex, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_corrected_paid_amount,
      case
        when tcr.overpayment_amount_ex > 0 then tcr.overpayment_components_json
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then tcr.underpayment_components_json
        else '[]'::jsonb
      end as components_sync_json,
      1 as candidate_priority
    from timesheet_case_rollup tcr
    left join active_linked_underpayment_cases aluc
      on aluc.candidate_id = tcr.candidate_id
     and aluc.timesheet_id = tcr.timesheet_id
    where tcr.overpayment_amount_ex > 0
       or (
         tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         )
       )
  ),
  finance_case_item_rows as (
    select
      cr.candidate_id,
      cr.candidate_pay_method,
      itm.value as item_json,
      nullif(btrim(coalesce(itm.value->>'finance_case_id', '')), '')::uuid as finance_case_id,
      nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid as timesheet_id,
      nullif(btrim(coalesce(itm.value->>'client_id', '')), '')::uuid as client_id,
      nullif(btrim(coalesce(itm.value->>'linked_shift_date', '')), '')::date as linked_shift_date,
      upper(btrim(coalesce(itm.value->>'case_type', ''))) as case_type_text,
      coalesce(itm.value->>'case_is_blocked', 'false')::boolean as case_is_blocked,
      round(abs(coalesce(nullif(itm.value->>'amount_ex_vat', '')::numeric, 0)), 2)::numeric(12,2) as line_amount_ex,
      coalesce(itm.value->'case_components', '[]'::jsonb) as case_components_json
    from candidate_rows cr
    cross join lateral jsonb_array_elements(coalesce(cr.itemisation_json, '[]'::jsonb)) as itm(value)
    where coalesce(itm.value->>'line_type', '') in ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
      and nullif(btrim(coalesce(itm.value->>'finance_case_id', '')), '') is not null
      and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '') is not null
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_exclude_timesheet_ids)
      )
  ),
  finance_case_candidates_raw as (
    select
      fcir.candidate_id,
      fcir.timesheet_id,
      coalesce(fcir.client_id, pa.client_id) as client_id,
      coalesce(fcir.linked_shift_date, pa.linked_shift_date) as linked_shift_date,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as corrected_amount_ex,
      pa.baseline_signature,
      fcir.candidate_pay_method,
      fcir.case_is_blocked,
      true as needs_lifecycle_tracking,
      case when pa.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) else 0::numeric(12,2) end as overpayment_amount_ex,
      case when pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) else 0::numeric(12,2) end as underpayment_amount_ex,
      pa.case_type as desired_case_type,
      pa.advance_kind as desired_advance_kind,
      pa.reason as desired_reason,
      round(coalesce(pa.source_original_paid_amount, 0), 2)::numeric(12,2) as source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as source_corrected_paid_amount,
      coalesce(fcir.case_components_json, '[]'::jsonb) as components_sync_json,
      2 as candidate_priority
    from finance_case_item_rows fcir
    join public.pay_advances pa
      on pa.id = fcir.finance_case_id
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id = fcir.timesheet_id
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and round(coalesce(pa.outstanding_amount, 0), 2) > 0
  ),
  combined_case_candidates as (
    select
      tcc.candidate_id,
      tcc.timesheet_id,
      tcc.client_id,
      tcc.linked_shift_date,
      tcc.corrected_amount_ex,
      tcc.baseline_signature,
      tcc.candidate_pay_method,
      tcc.case_is_blocked,
      tcc.needs_lifecycle_tracking,
      tcc.overpayment_amount_ex,
      tcc.underpayment_amount_ex,
      tcc.desired_case_type,
      tcc.desired_advance_kind,
      tcc.desired_reason,
      tcc.source_original_paid_amount,
      tcc.source_corrected_paid_amount,
      tcc.components_sync_json,
      tcc.candidate_priority
    from timesheet_case_candidates tcc

    union all

    select
      fccr.candidate_id,
      fccr.timesheet_id,
      fccr.client_id,
      fccr.linked_shift_date,
      fccr.corrected_amount_ex,
      fccr.baseline_signature,
      fccr.candidate_pay_method,
      fccr.case_is_blocked,
      fccr.needs_lifecycle_tracking,
      fccr.overpayment_amount_ex,
      fccr.underpayment_amount_ex,
      fccr.desired_case_type,
      fccr.desired_advance_kind,
      fccr.desired_reason,
      fccr.source_original_paid_amount,
      fccr.source_corrected_paid_amount,
      fccr.components_sync_json,
      fccr.candidate_priority
    from finance_case_candidates_raw fccr
  ),
  deduped_case_candidates as (
    select
      ccc.candidate_id,
      ccc.timesheet_id,
      ccc.client_id,
      ccc.linked_shift_date,
      ccc.corrected_amount_ex,
      ccc.baseline_signature,
      ccc.candidate_pay_method,
      ccc.case_is_blocked,
      ccc.needs_lifecycle_tracking,
      ccc.overpayment_amount_ex,
      ccc.underpayment_amount_ex,
      ccc.desired_case_type,
      ccc.desired_advance_kind,
      ccc.desired_reason,
      ccc.source_original_paid_amount,
      ccc.source_corrected_paid_amount,
      ccc.components_sync_json
    from (
      select
        ccc_inner.*,
        row_number() over (
          partition by ccc_inner.candidate_id, ccc_inner.timesheet_id
          order by
            ccc_inner.candidate_priority asc,
            case when ccc_inner.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 0 else 1 end,
            case when ccc_inner.needs_lifecycle_tracking then 0 else 1 end
        ) as rn
      from combined_case_candidates ccc_inner
    ) ccc
    where ccc.rn = 1
  )
  select
    dcc.candidate_id,
    dcc.timesheet_id,
    dcc.client_id,
    dcc.linked_shift_date,
    dcc.corrected_amount_ex,
    dcc.baseline_signature,
    dcc.candidate_pay_method,
    dcc.case_is_blocked,
    dcc.needs_lifecycle_tracking,
    dcc.overpayment_amount_ex,
    dcc.underpayment_amount_ex,
    dcc.desired_case_type,
    dcc.desired_advance_kind,
    dcc.desired_reason,
    dcc.source_original_paid_amount,
    dcc.source_corrected_paid_amount,
    dcc.components_sync_json
  from deduped_case_candidates dcc
  where dcc.desired_case_type is not null;

  IF COALESCE(v_authoritative_timesheet_scope,false) THEN
    v_rate_authority_failure_code:=NULL::text;
    v_rate_authority_failure_detail:='{}'::jsonb;
    WITH component_methods AS MATERIALIZED (
      SELECT candidate.candidate_id,candidate.timesheet_id,
        UPPER(NULLIF(BTRIM(component.value->>'source_pay_method'),''))
          AS source_pay_method,
        UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),''))
          AS economic_key_type,
        NULLIF(BTRIM(component.value->>'component_key_value'),'')
          AS economic_key_value,
        component.ordinality::integer AS component_ordinality
      FROM pg_temp.tmp_sync_timesheet_case_candidates candidate
      CROSS JOIN LATERAL jsonb_array_elements(CASE
        WHEN jsonb_typeof(candidate.components_sync_json)='array'
          THEN candidate.components_sync_json ELSE '[]'::jsonb END)
        WITH ORDINALITY component(value,ordinality)
    ), method_summary AS MATERIALIZED (
      SELECT method.candidate_id,method.timesheet_id,COUNT(*)::integer AS component_count,
        COUNT(*) FILTER(WHERE method.source_pay_method IS NULL
          OR method.source_pay_method NOT IN ('PAYE','UMBRELLA'))::integer
          AS invalid_method_count,
        COUNT(DISTINCT method.source_pay_method) FILTER(
          WHERE method.source_pay_method IN ('PAYE','UMBRELLA'))::integer
          AS distinct_supported_method_count,
        jsonb_agg(jsonb_build_object(
          'component_ordinality',method.component_ordinality,
          'economic_key_type',method.economic_key_type,
          'economic_key_value',method.economic_key_value,
          'source_pay_method',method.source_pay_method)
          ORDER BY method.component_ordinality) AS complete_component_method_set
      FROM component_methods method
      GROUP BY method.candidate_id,method.timesheet_id
    )
    SELECT CASE WHEN summary.invalid_method_count>0
        THEN 'RATE_AUTHORITY_SOURCE_PAY_METHOD_MISSING'
        ELSE 'RATE_AUTHORITY_SOURCE_PAY_METHOD_CONFLICT' END,
      jsonb_build_object(
        'candidate_id',summary.candidate_id,
        'timesheet_id',summary.timesheet_id,
        'component_count',summary.component_count,
        'invalid_method_count',summary.invalid_method_count,
        'distinct_supported_method_count',summary.distinct_supported_method_count,
        'complete_component_method_digest',pg_catalog.encode(extensions.digest(
          pg_catalog.convert_to(summary.complete_component_method_set::text,'UTF8'),
          'sha256'),'hex'),
        'sample_truncated',summary.component_count>25,
        'component_method_sample',pg_catalog.jsonb_path_query_array(
          summary.complete_component_method_set,'$[0 to 24]'))
    INTO v_rate_authority_failure_code,v_rate_authority_failure_detail
    FROM method_summary summary
    WHERE summary.invalid_method_count>0
       OR summary.distinct_supported_method_count<>1
    ORDER BY summary.timesheet_id
    LIMIT 1;

    IF v_rate_authority_failure_code IS NOT NULL THEN
      RAISE EXCEPTION '%',v_rate_authority_failure_code USING ERRCODE='P0001',
        DETAIL=jsonb_build_object('code',v_rate_authority_failure_code,
          'detail',v_rate_authority_failure_detail)::text;
    END IF;
  END IF;

  v_correction_rewrite_result :=
    public._ctms_rewrite_sync_correction_cases_v1(
    case
      when nullif(btrim(coalesce(p_mismatch_choices->>'workbench_session_id', '')), '')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then nullif(btrim(p_mismatch_choices->>'workbench_session_id'), '')::uuid
      else null::uuid
    end,
    coalesce(p_candidate_ids, array[]::uuid[]),
    coalesce(p_force_include_timesheet_ids, array[]::uuid[])
  );

  select coalesce(array_agg(distinct value::uuid order by value::uuid),array[]::uuid[])
  into v_resolution_pending_member_ids
  from jsonb_array_elements_text(
    coalesce(
      v_correction_rewrite_result
        ->'resolution_pending_member_timesheet_ids',
      '[]'::jsonb
    )
  ) pending_member(value);

  select count(*)::int into v_timesheet_case_count from pg_temp.tmp_sync_timesheet_case_candidates;
  select count(*)::int into v_overpayment_case_count from pg_temp.tmp_sync_timesheet_case_candidates where desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum;
  select count(*)::int into v_underpayment_case_count from pg_temp.tmp_sync_timesheet_case_candidates where desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'client_id', case when t.client_id is null then null else t.client_id::text end,
        'linked_shift_date', case when t.linked_shift_date is null then null else t.linked_shift_date::text end,
        'baseline_signature', t.baseline_signature,
        'corrected_amount_ex', t.corrected_amount_ex,
        'case_is_blocked', t.case_is_blocked,
        'desired_case_type', case when t.desired_case_type is null then null else t.desired_case_type::text end,
        'needs_lifecycle_tracking', t.needs_lifecycle_tracking,
        'overpayment_amount_ex', t.overpayment_amount_ex,
        'underpayment_amount_ex', t.underpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_case_candidates_json
  from pg_temp.tmp_sync_timesheet_case_candidates t;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'case_type', t.desired_case_type::text,
        'amount_ex', t.overpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_overpayment_json
  from pg_temp.tmp_sync_timesheet_case_candidates t
  where t.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'case_type', t.desired_case_type::text,
        'amount_ex', t.underpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_underpayment_json
  from pg_temp.tmp_sync_timesheet_case_candidates t
  where t.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum;

  v_case_workspace_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  for v_target_case_row in
    select
      t.*
    from pg_temp.tmp_sync_timesheet_case_candidates t
    order by t.candidate_id, t.timesheet_id
  loop
    v_selected_event_type := NULL;
    v_selected_reason := NULL;
    v_selected_note := NULL;
    v_case_update_count := 0;

    if v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then
      v_target_case_amount_ex := round(v_target_case_row.overpayment_amount_ex, 2)::numeric(12,2);
    elsif v_target_case_row.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then
      v_target_case_amount_ex := round(v_target_case_row.underpayment_amount_ex, 2)::numeric(12,2);
    else
      v_target_case_amount_ex := null;
    end if;

    SELECT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(v_target_case_row.components_sync_json) = 'array'
            THEN v_target_case_row.components_sync_json
          ELSE '[]'::jsonb
        END
      ) AS authoritative_component(value)
      WHERE UPPER(BTRIM(COALESCE(
        authoritative_component.value->>'overpayment_component_authority',
        ''
      ))) = 'PRE_DRAFT_LIVE_TRUTH'
    )
    INTO v_target_amount_is_authoritative_outstanding;

    v_case_taxability := NULL;
    v_case_routing_kind := NULL;
    v_case_metadata_component_count := 0;
    IF v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN
      SELECT
        COUNT(*)::integer,
        CASE
          WHEN COUNT(*) = 0 THEN NULL::public.pay_finance_taxability_enum
          WHEN BOOL_AND(COALESCE(normalized_component.classification = 'TAXABLE_CHANNEL_SENSITIVE', false)) THEN 'TAXABLE'::public.pay_finance_taxability_enum
          WHEN BOOL_AND(COALESCE(normalized_component.classification IN ('REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY'), false)) THEN 'NON_TAXABLE'::public.pay_finance_taxability_enum
          ELSE NULL::public.pay_finance_taxability_enum
        END,
        CASE
          WHEN COUNT(*) = 0 THEN NULL::public.pay_finance_routing_kind_enum
          WHEN upper(coalesce(v_target_case_row.candidate_pay_method, '')) = 'PAYE' THEN 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
          WHEN upper(coalesce(v_target_case_row.candidate_pay_method, '')) = 'UMBRELLA' THEN 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
          ELSE NULL::public.pay_finance_routing_kind_enum
        END
      INTO
        v_case_metadata_component_count,
        v_case_taxability,
        v_case_routing_kind
      FROM (
        SELECT
          upper(nullif(btrim(coalesce(component_element.value->>'classification', '')), '')) AS classification,
          upper(nullif(btrim(component_element.value->>'source_pay_method'),''))
            AS source_pay_method
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(v_target_case_row.components_sync_json) = 'array' THEN v_target_case_row.components_sync_json
            ELSE '[]'::jsonb
          END
        ) AS component_element(value)
      ) AS normalized_component;
    END IF;

    select
      pa.id as finance_case_id,
      pa.case_type as old_case_type,
      pa.status as old_status,
      round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) as old_original_amount,
      round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2) as old_outstanding_amount,
      round(coalesce(pa.source_original_paid_amount, 0), 2)::numeric(12,2) as old_source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as old_source_corrected_paid_amount,
      pa.linked_shift_date as old_linked_shift_date,
      pa.baseline_signature as old_baseline_signature,
      pa.taxability as old_taxability,
      pa.routing_kind as old_routing_kind,
      pa.written_off_at_utc as old_written_off_at_utc,
      pa.cleared_at_utc as old_cleared_at_utc,
      exists (
        select 1
        from private.banking_pay_workbench_economic_build_facts sync_safety_events
        where sync_safety_events.build_id=p_build_id
          and sync_safety_events.fact_family='PROTECTION_EVIDENCE'
          and sync_safety_events.finance_case_id = pa.id
          and (
            upper(btrim(coalesce(sync_safety_events.source_payload_json->>'event_type', ''))) like '%WRITE%OFF%'
            or upper(btrim(coalesce(sync_safety_events.source_payload_json->>'event_type', ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'MANUAL_WRITE_OFF',
              'CASE_MANUAL_ECONOMIC_OVERRIDE',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
            or upper(btrim(coalesce(sync_safety_events.source_payload_json->>'reason', ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'WRITE_OFF',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
          )
      ) as old_has_manual_or_restructure_event,
      exists (
        select 1
        from private.banking_pay_workbench_economic_build_facts automatic_clear_event
        where automatic_clear_event.build_id=p_build_id
          and automatic_clear_event.fact_family='PROTECTION_EVIDENCE'
          and automatic_clear_event.finance_case_id = pa.id
          and (
            (
              upper(btrim(coalesce(automatic_clear_event.source_payload_json->>'event_type', ''))) = 'CASE_CLEARED'
              and lower(btrim(coalesce(automatic_clear_event.source_payload_json->>'reason', ''))) = 'rail_settlement'
            )
            or (
              upper(btrim(coalesce(automatic_clear_event.source_payload_json->>'event_type', ''))) = 'CLEARED'
              and upper(btrim(coalesce(automatic_clear_event.source_payload_json->>'reason', ''))) = 'PREVIEW_FINANCE_SYNC'
            )
          )
      ) as old_has_automatic_reconcilable_clear,
      round(coalesce((
        select sum(abs(coalesce(settled_fact.amount_ex_vat,0)))
        from private.banking_pay_workbench_economic_build_facts settled_fact
        where settled_fact.build_id=p_build_id
          and settled_fact.fact_family='FROZEN_SETTLED_COMPONENT'
          and settled_fact.finance_case_id=pa.id
          and (
            (
              v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
              and upper(btrim(coalesce(settled_fact.source_payload_json #>> '{pay_batch_item,item_type}',
                settled_fact.source_payload_json->>'item_type',''))) = 'OVERPAYMENT_RECOVERY'
            )
            or (
              v_target_case_row.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum
              and upper(btrim(coalesce(settled_fact.source_payload_json #>> '{pay_batch_item,item_type}',
                settled_fact.source_payload_json->>'item_type',''))) = 'UNDERPAYMENT_PAYMENT'
            )
          )
      ), 0), 2)::numeric(12,2) as old_active_recovered_amount
    into v_existing_case_row
    from public.pay_advances pa
    where pa.candidate_id = v_target_case_row.candidate_id
      and pa.linked_timesheet_id = v_target_case_row.timesheet_id
      and pa.case_type = v_target_case_row.desired_case_type
    order by
      case when upper(coalesce(pa.status::text,'')) = 'ACTIVE' then 0 else 1 end,
      pa.updated_at desc,
      pa.created_at desc,
      pa.id desc
    limit 1
    for update;

    v_existing_recovered_amount := greatest(
      coalesce(v_existing_case_row.old_active_recovered_amount, 0),
      0
    );

    v_existing_active_reserved_amount := 0::numeric(12,2);

    IF v_existing_case_row.finance_case_id IS NOT NULL THEN
      SELECT ROUND(COALESCE(SUM(ABS(COALESCE(
        reservation_fact.reserved_source_amount,reservation_fact.amount_ex_vat,0))),0),2)::numeric(12,2)
      INTO v_existing_active_reserved_amount
      FROM private.banking_pay_workbench_economic_build_facts reservation_fact
      WHERE reservation_fact.build_id=p_build_id
        AND reservation_fact.fact_family='RESERVATION_COMPONENT'
        AND reservation_fact.finance_case_id=v_existing_case_row.finance_case_id;
    END IF;

    if v_existing_case_row.finance_case_id is not null
       and (
         v_existing_case_row.old_written_off_at_utc is not null
         or (
           v_existing_case_row.old_cleared_at_utc is not null
           and not (
             upper(coalesce(v_existing_case_row.old_status::text, '')) = 'PAID_OFF'
             and coalesce(v_existing_case_row.old_has_automatic_reconcilable_clear, false)
             and coalesce(v_existing_case_row.old_has_manual_or_restructure_event, false) is not true
             and (
               (
                 coalesce(v_target_amount_is_authoritative_outstanding, false)
                 and round(coalesce(v_target_case_amount_ex, 0), 2) > 0
               )
               or (
                 coalesce(v_target_amount_is_authoritative_outstanding, false) is not true
                 and round(
                   coalesce(v_target_case_amount_ex, 0)
                   - coalesce(v_existing_recovered_amount, 0),
                   2
                 ) > 0
               )
             )
           )
         )
         or upper(coalesce(v_existing_case_row.old_status::text,'')) not in ('ACTIVE','PAID_OFF')
         or coalesce(v_existing_case_row.old_has_manual_or_restructure_event, false)
       ) then
      insert into public.pay_finance_case_events (
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      values (
        v_existing_case_row.finance_case_id,
        'SYNC_SKIPPED',
        now(),
        p_actor_user_id,
        null,
        null,
        jsonb_build_object(
          'case_type', v_existing_case_row.old_case_type::text,
          'status', v_existing_case_row.old_status::text,
          'original_amount', v_existing_case_row.old_original_amount,
          'outstanding_amount', v_existing_case_row.old_outstanding_amount,
          'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
          'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
          'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
          'baseline_signature', v_existing_case_row.old_baseline_signature,
          'written_off_at_utc', v_existing_case_row.old_written_off_at_utc,
          'cleared_at_utc', v_existing_case_row.old_cleared_at_utc,
          'has_manual_or_restructure_event', v_existing_case_row.old_has_manual_or_restructure_event,
          'has_automatic_reconcilable_clear', v_existing_case_row.old_has_automatic_reconcilable_clear,
          'existing_recovered_amount', v_existing_recovered_amount
        ),
        jsonb_build_object(
          'sync_skipped', true,
          'component_sync_skipped', true,
          'component_authority_preserved', true,
          'target_case_type', case when v_target_case_row.desired_case_type is null then null else v_target_case_row.desired_case_type::text end,
          'target_original_amount', v_target_case_amount_ex,
          'target_source_original_paid_amount', v_target_case_row.source_original_paid_amount,
          'target_source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
          'target_baseline_signature', v_target_case_row.baseline_signature,
          'target_pay_channel_scope', v_scope,
          'workbench_session_id', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'workbench_session_id', '')), ''),
          'source_build_run_id', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'source_build_run_id', '')), ''),
          'session_version', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'session_version', '')), ''),
          'overpayment_sync_scope_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_scope_digest', '')), ''),
          'overpayment_sync_negative_component_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_negative_component_digest', '')), ''),
          'overpayment_sync_settled_baseline_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_settled_baseline_digest', '')), ''),
          'policy_x_authority_scope', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', '')), '')
        ),
        'PREVIEW_FINANCE_SYNC_SKIPPED_PROTECTED_CASE',
        'Skipped case and component synchronisation because the existing case is written-off, cleared, closed, paused, manually resolved, or restructured.'
      );

      /* A protected case must not be inserted into tmp_sync_case_links with an
         empty component payload.  Every row in tmp_sync_case_links is processed
         later by pay_finance_components_sync_from_preview; an empty payload is
         authoritative removal input and can close open components.  The case
         clear pass already excludes protected cases by lifecycle state/event,
         so omitting the link preserves the complete protected case/component
         authority without allowing automatic sync to rewrite it. */
      continue;
    end if;

    IF v_existing_case_row.finance_case_id IS NOT NULL
       AND v_existing_case_row.old_case_type IS DISTINCT FROM v_target_case_row.desired_case_type
       AND COALESCE(v_existing_active_reserved_amount, 0) > 0 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_ACTIVE_RESERVATION_DIRECTION_CONFLICT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_ACTIVE_RESERVATION_DIRECTION_CONFLICT',
                'finance_case_id', v_existing_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'existing_case_type', v_existing_case_row.old_case_type::text,
                'target_case_type', v_target_case_row.desired_case_type::text,
                'active_reserved_amount', COALESCE(v_existing_active_reserved_amount, 0),
                'message', 'The finance-case direction cannot change while a frozen recovery or payment reservation remains active. Settle or cancel the active batch before reconciling the opposite direction.'
              )::text;
    END IF;

    IF COALESCE(v_target_amount_is_authoritative_outstanding, false) THEN
      /* PRE_DRAFT_LIVE_TRUTH supplies the canonical amount that remains after
         settled baseline movements and active reservations.  Keep historic
         consumption in the case lifetime total, but do not subtract it from
         the authoritative remaining amount a second time. */
      v_active_reservation_protection_applied := COALESCE(v_existing_active_reserved_amount, 0) > 0
        AND COALESCE(v_target_case_amount_ex, 0) < COALESCE(v_existing_active_reserved_amount, 0);
      v_new_outstanding_amount := GREATEST(
        COALESCE(v_target_case_amount_ex, 0),
        COALESCE(v_existing_active_reserved_amount, 0),
        0
      )::numeric(12,2);
      v_effective_case_amount_ex := ROUND(
        COALESCE(v_existing_recovered_amount, 0) + v_new_outstanding_amount,
        2
      )::numeric(12,2);
    ELSE
      v_active_reservation_protection_applied := COALESCE(v_existing_active_reserved_amount, 0) > 0
        AND COALESCE(v_target_case_amount_ex, 0) < ROUND(COALESCE(v_existing_recovered_amount, 0) + COALESCE(v_existing_active_reserved_amount, 0), 2);
      v_effective_case_amount_ex := GREATEST(
        COALESCE(v_target_case_amount_ex, 0),
        ROUND(COALESCE(v_existing_recovered_amount, 0) + COALESCE(v_existing_active_reserved_amount, 0), 2)
      )::numeric(12,2);
      v_new_outstanding_amount := greatest(v_effective_case_amount_ex - v_existing_recovered_amount, COALESCE(v_existing_active_reserved_amount, 0), 0)::numeric(12,2);
    END IF;

    if v_existing_case_row.finance_case_id is null then
      insert into public.pay_advances (
        candidate_id,
        client_id,
        case_type,
        advance_kind,
        reason,
        linked_timesheet_id,
        linked_shift_date,
        baseline_signature,
        source_original_paid_amount,
        source_corrected_paid_amount,
        original_amount,
        outstanding_amount,
        status,
        created_by,
        updated_at,
        created_at,
        cleared_at_utc,
        cleared_by_user_id,
        write_off_reason,
        written_off_at_utc,
        written_off_by_user_id,
        taxability,
        routing_kind
      )
      values (
        v_target_case_row.candidate_id,
        v_target_case_row.client_id,
        v_target_case_row.desired_case_type,
        v_target_case_row.desired_advance_kind,
        v_target_case_row.desired_reason,
        v_target_case_row.timesheet_id,
        v_target_case_row.linked_shift_date,
        v_target_case_row.baseline_signature,
        v_target_case_row.source_original_paid_amount,
        v_target_case_row.source_corrected_paid_amount,
        v_effective_case_amount_ex,
        v_new_outstanding_amount,
        'ACTIVE'::public.pay_advance_status_enum,
        p_actor_user_id,
        now(),
        now(),
        null,
        null,
        null,
        null,
        null,
        v_case_taxability,
        v_case_routing_kind
      )
      returning id into v_selected_finance_case_id;

      v_cases_inserted := v_cases_inserted + 1;
      v_selected_event_type := 'CREATED';
      v_selected_reason := 'PREVIEW_FINANCE_SYNC';
      v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Created overpayment finance case from component-aware preview sync' else 'Created lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      v_case_before_json := null;
      v_case_after_json := jsonb_build_object(
        'case_type', v_target_case_row.desired_case_type::text,
        'candidate_id', v_target_case_row.candidate_id::text,
        'linked_timesheet_id', v_target_case_row.timesheet_id::text,
        'linked_shift_date', case when v_target_case_row.linked_shift_date is null then null else v_target_case_row.linked_shift_date::text end,
        'baseline_signature', v_target_case_row.baseline_signature,
        'original_amount', v_effective_case_amount_ex,
        'outstanding_amount', v_new_outstanding_amount,
        'source_original_paid_amount', v_target_case_row.source_original_paid_amount,
        'source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
        'taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
        'routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
        'status', 'ACTIVE'
      )
      || CASE
        WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
         AND v_case_metadata_component_count > 0
         AND (v_case_taxability IS NOT NULL OR v_case_routing_kind IS NOT NULL) THEN jsonb_build_object(
          'before_taxability', null,
          'after_taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
          'before_routing_kind', null,
          'after_routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
          'inferred_from_open_components', true
        )
        ELSE '{}'::jsonb
      END;
    else
      v_case_before_json := jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', v_existing_case_row.old_status::text,
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', v_existing_case_row.old_outstanding_amount,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
        'routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      )
      || CASE
        WHEN v_existing_case_row.old_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN jsonb_build_object(
          'before_taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
          'before_routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END
        )
        ELSE '{}'::jsonb
      END;

      update public.pay_advances pa
      set
        client_id = v_target_case_row.client_id,
        case_type = v_target_case_row.desired_case_type,
        advance_kind = v_target_case_row.desired_advance_kind,
        reason = v_target_case_row.desired_reason,
        linked_shift_date = v_target_case_row.linked_shift_date,
        baseline_signature = v_target_case_row.baseline_signature,
        source_original_paid_amount = v_target_case_row.source_original_paid_amount,
        source_corrected_paid_amount = v_target_case_row.source_corrected_paid_amount,
        original_amount = v_effective_case_amount_ex,
        outstanding_amount = v_new_outstanding_amount,
        status = case when v_new_outstanding_amount > 0 then 'ACTIVE'::public.pay_advance_status_enum else 'PAID_OFF'::public.pay_advance_status_enum end,
        cleared_at_utc = case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_at_utc, now()) end,
        cleared_by_user_id = case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_by_user_id, p_actor_user_id) end,
        taxability = case
          when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_taxability
          else pa.taxability
        end,
        routing_kind = case
          when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_routing_kind
          else pa.routing_kind
        end,
        updated_at = now()
      where pa.id = v_existing_case_row.finance_case_id
        and row(
          pa.client_id,
          pa.case_type,
          pa.advance_kind,
          pa.reason,
          pa.linked_shift_date,
          pa.baseline_signature,
          pa.source_original_paid_amount,
          pa.source_corrected_paid_amount,
          pa.original_amount,
          pa.outstanding_amount,
          pa.status,
          pa.cleared_at_utc,
          pa.cleared_by_user_id,
          pa.taxability,
          pa.routing_kind
        ) is distinct from row(
          v_target_case_row.client_id,
          v_target_case_row.desired_case_type,
          v_target_case_row.desired_advance_kind,
          v_target_case_row.desired_reason,
          v_target_case_row.linked_shift_date,
          v_target_case_row.baseline_signature,
          v_target_case_row.source_original_paid_amount,
          v_target_case_row.source_corrected_paid_amount,
          v_effective_case_amount_ex,
          v_new_outstanding_amount,
          case when v_new_outstanding_amount > 0 then 'ACTIVE'::public.pay_advance_status_enum else 'PAID_OFF'::public.pay_advance_status_enum end,
          case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_at_utc, now()) end,
          case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_by_user_id, p_actor_user_id) end,
          case
            when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_taxability
            else pa.taxability
          end,
          case
            when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_routing_kind
            else pa.routing_kind
          end
        );

      get diagnostics v_case_update_count = row_count;

      v_selected_finance_case_id := v_existing_case_row.finance_case_id;
      v_cases_touched := v_cases_touched + 1;

      if v_case_update_count > 0
         and upper(coalesce(v_existing_case_row.old_status::text,'')) = 'PAID_OFF'
         and v_new_outstanding_amount > 0 then
        v_cases_reopened := v_cases_reopened + 1;
        v_selected_event_type := 'REOPENED';
        v_selected_reason := 'PREVIEW_FINANCE_SYNC';
        v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Reopened overpayment finance case from component-aware preview sync' else 'Reopened lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      elsif v_case_update_count > 0 then
        v_cases_amended := v_cases_amended + 1;
        v_selected_event_type := 'AMENDED';
        v_selected_reason := 'PREVIEW_FINANCE_SYNC';
        v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Amended overpayment finance case from component-aware preview sync' else 'Amended lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      end if;

      v_case_after_json := jsonb_build_object(
        'case_type', v_target_case_row.desired_case_type::text,
        'status', case when v_new_outstanding_amount > 0 then 'ACTIVE' else 'PAID_OFF' end,
        'original_amount', v_effective_case_amount_ex,
        'outstanding_amount', v_new_outstanding_amount,
        'source_original_paid_amount', v_target_case_row.source_original_paid_amount,
        'source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
        'taxability', CASE
          WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum AND v_case_metadata_component_count > 0 THEN CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END
          ELSE CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END
        END,
        'routing_kind', CASE
          WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum AND v_case_metadata_component_count > 0 THEN CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END
          ELSE CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END
        END,
        'linked_shift_date', case when v_target_case_row.linked_shift_date is null then null else v_target_case_row.linked_shift_date::text end,
        'baseline_signature', v_target_case_row.baseline_signature
      )
      || CASE
        WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
         AND v_case_metadata_component_count > 0
         AND (
           v_existing_case_row.old_taxability IS DISTINCT FROM v_case_taxability
           OR v_existing_case_row.old_routing_kind IS DISTINCT FROM v_case_routing_kind
         ) THEN jsonb_build_object(
          'before_taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
          'after_taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
          'before_routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END,
          'after_routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
          'inferred_from_open_components', true
        )
        ELSE '{}'::jsonb
      END;
    end if;

    insert into pg_temp.tmp_sync_case_links (
      candidate_id,
      timesheet_id,
      finance_case_id,
      desired_case_type,
      source_original_paid_amount,
      source_corrected_paid_amount,
      case_amount_ex,
      linked_shift_date,
      baseline_signature,
      components_sync_json
    )
    values (
      v_target_case_row.candidate_id,
      v_target_case_row.timesheet_id,
      v_selected_finance_case_id,
      v_target_case_row.desired_case_type,
      v_target_case_row.source_original_paid_amount,
      v_target_case_row.source_corrected_paid_amount,
      COALESCE(v_effective_case_amount_ex, v_target_case_amount_ex),
      v_target_case_row.linked_shift_date,
      v_target_case_row.baseline_signature,
      v_target_case_row.components_sync_json
    )
    on conflict (candidate_id, timesheet_id) do update
    set
      finance_case_id = excluded.finance_case_id,
      desired_case_type = excluded.desired_case_type,
      source_original_paid_amount = excluded.source_original_paid_amount,
      source_corrected_paid_amount = excluded.source_corrected_paid_amount,
      case_amount_ex = excluded.case_amount_ex,
      linked_shift_date = excluded.linked_shift_date,
      baseline_signature = excluded.baseline_signature,
      components_sync_json = excluded.components_sync_json;

    if v_selected_event_type is not null then
    insert into public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_selected_finance_case_id,
      v_selected_event_type,
      now(),
      p_actor_user_id,
      null,
      null,
      v_case_before_json,
      v_case_after_json,
      v_selected_reason,
      v_selected_note
    );
    end if;

    IF COALESCE(v_active_reservation_protection_applied, false)
       AND NOT EXISTS (
         SELECT 1
         FROM public.pay_finance_case_events AS protection_event
         WHERE protection_event.finance_case_id = v_selected_finance_case_id
           AND protection_event.event_type = 'SYNC_SHRINK_DEFERRED_ACTIVE_RESERVATION'
           AND protection_event.reason = 'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION'
           AND protection_event.before_json IS NOT DISTINCT FROM v_case_before_json
           AND protection_event.after_json = jsonb_build_object(
             'target_case_amount_ex', v_target_case_amount_ex,
             'effective_case_amount_ex', v_effective_case_amount_ex,
             'active_reserved_recovery_amount', v_existing_active_reserved_amount,
             'existing_recovered_amount', v_existing_recovered_amount,
             'outstanding_amount', v_new_outstanding_amount
           )
       ) THEN
      insert into public.pay_finance_case_events (
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      values (
        v_selected_finance_case_id,
        'SYNC_SHRINK_DEFERRED_ACTIVE_RESERVATION',
        now(),
        p_actor_user_id,
        null,
        null,
        v_case_before_json,
        jsonb_build_object(
          'target_case_amount_ex', v_target_case_amount_ex,
          'effective_case_amount_ex', v_effective_case_amount_ex,
          'active_reserved_recovery_amount', v_existing_active_reserved_amount,
          'existing_recovered_amount', v_existing_recovered_amount,
          'outstanding_amount', v_new_outstanding_amount
        ),
        'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION',
        'Deferred overpayment/underpayment case shrink because an active recovery reservation exists.'
      );
    END IF;
  end loop;

  for v_open_case_candidate in
    select
      pa.id as finance_case_id,
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      pa.case_type as old_case_type,
      round(coalesce(pa.original_amount,0),2)::numeric(12,2) as old_original_amount,
      round(coalesce(pa.outstanding_amount,0),2)::numeric(12,2) as old_outstanding_amount,
      round(coalesce(pa.source_original_paid_amount,0),2)::numeric(12,2) as old_source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount,0),2)::numeric(12,2) as old_source_corrected_paid_amount,
      pa.linked_shift_date as old_linked_shift_date,
      pa.baseline_signature as old_baseline_signature
    from public.pay_advances pa
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id is not null
      and (
        coalesce(array_length(p_candidate_ids, 1), 0) = 0
        or pa.candidate_id = any(p_candidate_ids)
      )
      and (
        p_client_filter_single is null
        or pa.client_id = p_client_filter_single
      )
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or pa.linked_timesheet_id = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and pa.linked_timesheet_id = any(p_exclude_timesheet_ids)
      )
      and not (
        coalesce(array_length(v_resolution_pending_member_ids, 1), 0) > 0
        and pa.linked_timesheet_id
              = any(v_resolution_pending_member_ids)
      )
      and not exists (
        select 1
        from pg_temp.tmp_sync_case_links l
        where l.finance_case_id = pa.id
      )
      and exists (
        select 1
        from public.candidates c
        where c.id = pa.candidate_id
          and upper(coalesce(c.pay_method,'')) = v_scope
      )
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and pa.written_off_at_utc is null
      and pa.cleared_at_utc is null
      and not exists (
        select 1
        from private.banking_pay_workbench_economic_build_facts sync_clear_safety_events
        where sync_clear_safety_events.build_id=p_build_id
          and sync_clear_safety_events.fact_family='PROTECTION_EVIDENCE'
          and sync_clear_safety_events.finance_case_id = pa.id
          and (
            upper(btrim(coalesce(sync_clear_safety_events.source_payload_json->>'event_type', ''))) like '%WRITE%OFF%'
            or upper(btrim(coalesce(sync_clear_safety_events.source_payload_json->>'event_type', ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'MANUAL_WRITE_OFF',
              'CASE_MANUAL_ECONOMIC_OVERRIDE',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
            or upper(btrim(coalesce(sync_clear_safety_events.source_payload_json->>'reason', ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'WRITE_OFF',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
          )
      )
  loop
    SELECT ROUND(COALESCE(SUM(ABS(COALESCE(
      reservation_fact.reserved_source_amount,reservation_fact.amount_ex_vat,0))),0),2)::numeric(12,2)
    INTO v_existing_active_reserved_amount
    FROM private.banking_pay_workbench_economic_build_facts reservation_fact
    WHERE reservation_fact.build_id=p_build_id
      AND reservation_fact.fact_family='RESERVATION_COMPONENT'
      AND reservation_fact.finance_case_id=v_open_case_candidate.finance_case_id;

    IF COALESCE(v_existing_active_reserved_amount, 0) > 0 THEN
      IF NOT EXISTS (
        SELECT 1
        FROM public.pay_finance_case_events AS protection_event
        WHERE protection_event.finance_case_id = v_open_case_candidate.finance_case_id
          AND protection_event.event_type = 'SYNC_CLEAR_DEFERRED_ACTIVE_RESERVATION'
          AND protection_event.reason = 'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION'
          AND protection_event.before_json = jsonb_build_object(
            'case_type', v_open_case_candidate.old_case_type::text,
            'status', 'ACTIVE',
            'original_amount', v_open_case_candidate.old_original_amount,
            'outstanding_amount', v_open_case_candidate.old_outstanding_amount
          )
          AND protection_event.after_json = jsonb_build_object(
            'clear_deferred', true,
            'active_reserved_recovery_amount', v_existing_active_reserved_amount
          )
      ) THEN
        insert into public.pay_finance_case_events (
          finance_case_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        values (
          v_open_case_candidate.finance_case_id,
          'SYNC_CLEAR_DEFERRED_ACTIVE_RESERVATION',
          now(),
          p_actor_user_id,
          null,
          null,
          jsonb_build_object(
            'case_type', v_open_case_candidate.old_case_type::text,
            'status', 'ACTIVE',
            'original_amount', v_open_case_candidate.old_original_amount,
            'outstanding_amount', v_open_case_candidate.old_outstanding_amount
          ),
          jsonb_build_object(
            'clear_deferred', true,
            'active_reserved_recovery_amount', v_existing_active_reserved_amount
          ),
          'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION',
          'Deferred finance case clear because an active recovery reservation exists.'
        );
      END IF;

      CONTINUE;
    END IF;

    insert into pg_temp.tmp_sync_case_clears (
      finance_case_id,
      candidate_id,
      timesheet_id,
      old_case_type,
      old_original_amount,
      old_outstanding_amount,
      old_source_original_paid_amount,
      old_source_corrected_paid_amount,
      old_linked_shift_date,
      old_baseline_signature
    )
    values (
      v_open_case_candidate.finance_case_id,
      v_open_case_candidate.candidate_id,
      v_open_case_candidate.timesheet_id,
      v_open_case_candidate.old_case_type,
      v_open_case_candidate.old_original_amount,
      v_open_case_candidate.old_outstanding_amount,
      v_open_case_candidate.old_source_original_paid_amount,
      v_open_case_candidate.old_source_corrected_paid_amount,
      v_open_case_candidate.old_linked_shift_date,
      v_open_case_candidate.old_baseline_signature
    )
    on conflict (finance_case_id) do nothing;
  end loop;

  for v_existing_case_row in
    select *
    from pg_temp.tmp_sync_case_clears
    order by candidate_id, timesheet_id, finance_case_id
  loop
    update public.pay_advances pa
    set
      status = 'PAID_OFF'::public.pay_advance_status_enum,
      outstanding_amount = 0,
      cleared_at_utc = coalesce(pa.cleared_at_utc, now()),
      cleared_by_user_id = coalesce(pa.cleared_by_user_id, p_actor_user_id),
      updated_at = now()
    where pa.id = v_existing_case_row.finance_case_id;

    insert into public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_existing_case_row.finance_case_id,
      'CLEARED',
      now(),
      p_actor_user_id,
      null,
      null,
      jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', 'ACTIVE',
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', v_existing_case_row.old_outstanding_amount,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      ),
      jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', 'PAID_OFF',
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', 0,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      ),
      'PREVIEW_FINANCE_SYNC',
      'Cleared finance case because the current preview no longer requires a persistent lifecycle-tracked overpayment/underpayment header'
    );

    v_components_sync_result := public.pay_finance_components_sync_from_preview(
      v_existing_case_row.finance_case_id,
      '[]'::jsonb,
      p_actor_user_id
    );

    IF jsonb_typeof(COALESCE(v_components_sync_result, '{}'::jsonb)) <> 'object'
       OR LOWER(BTRIM(COALESCE(v_components_sync_result->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED',
                'finance_case_id', v_existing_case_row.finance_case_id::text,
                'candidate_id', v_existing_case_row.candidate_id::text,
                'timesheet_id', v_existing_case_row.timesheet_id::text,
                'operation', 'CLEAR',
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    v_cases_cleared := v_cases_cleared + 1;
  end loop;

  for v_target_case_row in
    select l.*
    from pg_temp.tmp_sync_case_links l
    order by l.candidate_id, l.timesheet_id
  loop
    v_components_sync_result := public.pay_finance_components_sync_from_preview(
      v_target_case_row.finance_case_id,
      v_target_case_row.components_sync_json,
      p_actor_user_id
    );

    IF jsonb_typeof(COALESCE(v_components_sync_result, '{}'::jsonb)) <> 'object'
       OR LOWER(BTRIM(COALESCE(v_components_sync_result->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED',
                'finance_case_id', v_target_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'desired_case_type', v_target_case_row.desired_case_type::text,
                'operation', 'RECONCILE',
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    SELECT
      round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2),
      round(coalesce(sum(coalesce(pfc.remaining_source_amount, 0)) FILTER (WHERE pfc.closed_at_utc IS NULL), 0), 2)::numeric(12,2)
    INTO
      v_component_case_outstanding_amount,
      v_component_open_remaining_total
    FROM public.pay_advances AS pa
    LEFT JOIN public.pay_finance_case_components AS pfc
      ON pfc.finance_case_id = pa.id
    WHERE pa.id = v_target_case_row.finance_case_id
    GROUP BY pa.outstanding_amount;

    v_component_case_mismatch_amount := round(
      coalesce(v_component_case_outstanding_amount, 0) - coalesce(v_component_open_remaining_total, 0),
      2
    )::numeric(12,2);

    IF abs(coalesce(v_component_case_mismatch_amount, 0)) > 0.01 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_CASE_RECONCILIATION_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_CASE_RECONCILIATION_FAILED',
                'finance_case_id', v_target_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'desired_case_type', v_target_case_row.desired_case_type::text,
                'case_outstanding_amount', coalesce(v_component_case_outstanding_amount, 0),
                'open_component_remaining_total', coalesce(v_component_open_remaining_total, 0),
                'mismatch_amount', coalesce(v_component_case_mismatch_amount, 0),
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    if v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then
      v_synced_open_component_count := 0;
      v_synced_case_taxability := NULL;
      v_synced_case_routing_kind := NULL;

      select
        pa.taxability,
        pa.routing_kind
      into
        v_synced_before_taxability,
        v_synced_before_routing_kind
      from public.pay_advances pa
      where pa.id = v_target_case_row.finance_case_id
      limit 1;

      select
        count(*)::integer,
        case
          when count(*) = 0 then null::public.pay_finance_taxability_enum
          when bool_and(pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) then 'TAXABLE'::public.pay_finance_taxability_enum
          when bool_and(pfc.classification in (
            'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
            'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
          )) then 'NON_TAXABLE'::public.pay_finance_taxability_enum
          else null::public.pay_finance_taxability_enum
        end,
        case
          when count(*) = 0 then null::public.pay_finance_routing_kind_enum
          when v_scope = 'PAYE' then 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
          when v_scope = 'UMBRELLA' then 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
          else null::public.pay_finance_routing_kind_enum
        end
      into
        v_synced_open_component_count,
        v_synced_case_taxability,
        v_synced_case_routing_kind
      from public.pay_finance_case_components pfc
      where pfc.finance_case_id = v_target_case_row.finance_case_id
        and pfc.closed_at_utc is null
        and round(coalesce(pfc.remaining_source_amount, 0), 2) > 0;

      if v_synced_open_component_count > 0
         and (v_synced_before_taxability is distinct from v_synced_case_taxability
              or v_synced_before_routing_kind is distinct from v_synced_case_routing_kind) then
        v_taxability_event_before_json := jsonb_build_object(
          'case_type', 'OVERPAYMENT',
          'taxability', case when v_synced_before_taxability is null then null else v_synced_before_taxability::text end,
          'routing_kind', case when v_synced_before_routing_kind is null then null else v_synced_before_routing_kind::text end
        );

        v_taxability_event_after_json := jsonb_build_object(
          'case_type', 'OVERPAYMENT',
          'taxability', case when v_synced_case_taxability is null then null else v_synced_case_taxability::text end,
          'routing_kind', case when v_synced_case_routing_kind is null then null else v_synced_case_routing_kind::text end,
          'before_taxability', case when v_synced_before_taxability is null then null else v_synced_before_taxability::text end,
          'after_taxability', case when v_synced_case_taxability is null then null else v_synced_case_taxability::text end,
          'before_routing_kind', case when v_synced_before_routing_kind is null then null else v_synced_before_routing_kind::text end,
          'after_routing_kind', case when v_synced_case_routing_kind is null then null else v_synced_case_routing_kind::text end,
          'inferred_from_open_components', true
        );

        update public.pay_advances pa
        set
          taxability = v_synced_case_taxability,
          routing_kind = v_synced_case_routing_kind,
          updated_at = now()
        where pa.id = v_target_case_row.finance_case_id;

        insert into public.pay_finance_case_events (
          finance_case_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        values (
          v_target_case_row.finance_case_id,
          case
            when v_synced_before_taxability is distinct from v_synced_case_taxability
             and v_synced_before_routing_kind is distinct from v_synced_case_routing_kind then 'HEADER_METADATA_INFERRED'
            when v_synced_before_taxability is distinct from v_synced_case_taxability then 'TAXABILITY_INFERRED'
            else 'ROUTING_KIND_INFERRED'
          end,
          now(),
          p_actor_user_id,
          null,
          null,
          v_taxability_event_before_json,
          v_taxability_event_after_json,
          'PREVIEW_FINANCE_SYNC',
          'Inferred overpayment taxability/routing metadata from open finance case components after component sync'
        );
      end if;
    end if;
  end loop;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_RESULT',
    jsonb_build_object(
      'pay_channel_scope', v_scope,
      'requested_candidate_count', v_requested_candidate_count,
      'preview_candidate_count', v_preview_candidate_count,
      'preview_candidate_coverage_complete', COALESCE(v_missing_candidate_count, 0) = 0,
      'authoritative_timesheet_scope', COALESCE(v_authoritative_timesheet_scope, false),
      'explicit_empty_timesheet_scope', COALESCE(v_explicit_empty_timesheet_scope, false),
      'preview_scope_strategy', v_preview_scope_strategy,
      'overpayment_case_count', v_overpayment_case_count,
      'underpayment_case_count', v_underpayment_case_count,
      'cases_inserted', v_cases_inserted,
      'cases_touched', v_cases_touched,
      'cases_amended', v_cases_amended,
      'cases_reopened', v_cases_reopened,
      'cases_cleared', v_cases_cleared
    ),
    'pay_sync_overpayments',
    COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  v_public_result_json := jsonb_build_object(
    'ok', true,
    'pay_channel_scope', v_scope,
    'requested_candidate_count', v_requested_candidate_count,
    'preview_candidate_count', v_preview_candidate_count,
    'preview_candidate_coverage_complete', COALESCE(v_missing_candidate_count, 0) = 0,
    'missing_candidate_ids', COALESCE(v_missing_candidate_ids_json, '[]'::jsonb),
    'authoritative_timesheet_scope', COALESCE(v_authoritative_timesheet_scope, false),
    'explicit_empty_timesheet_scope', COALESCE(v_explicit_empty_timesheet_scope, false),
    'preview_scope_strategy', v_preview_scope_strategy,
    'scope_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
    'negative_preview_timesheets_count', v_overpayment_case_count,
    'negative_preview_timesheets', v_overpayment_json,
    'underpayment_case_count', v_underpayment_case_count,
    'underpayment_cases', v_underpayment_json,
    'timesheet_finance_case_candidates_count', v_timesheet_case_count,
    'timesheet_finance_case_candidates', v_case_candidates_json,
    'correction_resolution_pending_chain_count',
      coalesce(
        nullif(
          v_correction_rewrite_result
            ->>'resolution_pending_chain_count',
          ''
        )::integer,
        0
      ),
    'correction_resolution_pending_member_timesheet_ids',
      to_jsonb(v_resolution_pending_member_ids),
    'cases_inserted', v_cases_inserted,
    'cases_touched', v_cases_touched,
    'cases_amended', v_cases_amended,
    'cases_reopened', v_cases_reopened,
    'cases_cleared', v_cases_cleared
  );

  v_finance_apply_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  IF v_effect_capture_mode THEN
    PERFORM set_config('cloudtms.pay_workbench_reconcile_slice_v1','',true); /* A28 */
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'candidate_id',candidate_id,'timesheet_id',timesheet_id,'relation_name',relation_name,
      'operation',operation,'source_id',source_id,'finance_case_id',finance_case_id,
      'finance_component_id',finance_component_id,'economic_key_type',economic_key_type,
      'economic_key_value',economic_key_value,'expected_before_digest',expected_before_digest,
      'expected_after_digest',expected_after_digest)
      ORDER BY relation_name,operation,source_id),'[]'::jsonb)
    INTO v_captured_effects FROM pg_temp._bpay_wb_expected_effects;
    IF EXISTS(SELECT 1 FROM pg_temp._bpay_wb_expected_effects WHERE proposed IS NOT TRUE OR observed IS NOT TRUE) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_CAPTURE_INCOMPLETE' USING ERRCODE='23514';
    END IF;
    RETURN jsonb_build_object('ok',true,'public_result_json',jsonb_build_object(
      'ok',true,'effect_plan_capture',true,'captured_effects',v_captured_effects,
      '_internal_reconcile_timing',jsonb_build_object(
        'execution_profile_version',v_execution_profile_version,
      'reconciliation_optimization_version',v_reconciliation_optimization_version,
        'workspace_cache_ms',v_workspace_cache_ms,
        'freshness_set_ms',v_freshness_set_ms,
        'authoritative_components_ms',v_authoritative_components_ms,
        'preflight_setup_ms',v_preflight_setup_ms,
        'correction_residuals_ms',v_correction_residuals_ms,
        'authority_validation_ms',v_authority_validation_ms,
        'component_assembly_ms',v_component_assembly_ms,
        'preview_workspace_ms',v_preview_workspace_ms,
        'preview_collect_ms',v_preview_collect_ms,
        'preview_canonical_ms',v_preview_canonical_ms,
        'preview_summary_ms',v_preview_summary_ms,
        'case_workspace_ms',v_case_workspace_ms,
        'finance_apply_ms',v_finance_apply_ms,
        'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer)),
      'internal_result_json',jsonb_build_object(
        'captured_effect_count',jsonb_array_length(v_captured_effects),
        'execution_profile_version',v_execution_profile_version,
      'reconciliation_optimization_version',v_reconciliation_optimization_version,
        'freshness_set_ms',v_freshness_set_ms,
        'workspace_cache_ms',v_workspace_cache_ms,
        'authoritative_components_ms',v_authoritative_components_ms,
        'preflight_setup_ms',v_preflight_setup_ms,
        'correction_residuals_ms',v_correction_residuals_ms,
        'authority_validation_ms',v_authority_validation_ms,
        'component_assembly_ms',v_component_assembly_ms,
        'preview_workspace_ms',v_preview_workspace_ms,
        'preview_collect_ms',v_preview_collect_ms,
        'preview_canonical_ms',v_preview_canonical_ms,
        'preview_summary_ms',v_preview_summary_ms,
        'case_workspace_ms',v_case_workspace_ms,
        'finance_apply_ms',v_finance_apply_ms,
        'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer));
  END IF;

  IF EXISTS(SELECT 1 FROM pg_temp._bpay_wb_expected_effects WHERE proposed IS NOT TRUE OR observed IS NOT TRUE)
     OR EXISTS(SELECT 1 FROM pg_temp._bpay_wb_expected_effects
       WHERE build_token IS DISTINCT FROM v_bounded_build.build_token
          OR candidate_id IS DISTINCT FROM v_bounded_build.candidate_id
          OR relation_name NOT IN ('pay_advances','pay_finance_case_components','pay_finance_case_events')) THEN
    SELECT jsonb_build_object(
      'total_effects',count(*),
      'not_proposed',count(*) FILTER (WHERE proposed IS NOT TRUE),
      'not_observed',count(*) FILTER (WHERE observed IS NOT TRUE),
      'wrong_build_token',count(*) FILTER (
        WHERE build_token IS DISTINCT FROM v_bounded_build.build_token),
      'wrong_candidate',count(*) FILTER (
        WHERE candidate_id IS DISTINCT FROM v_bounded_build.candidate_id),
      'invalid_relation',count(*) FILTER (
        WHERE relation_name NOT IN (
          'pay_advances','pay_finance_case_components','pay_finance_case_events')),
      'pay_advances_not_observed',count(*) FILTER (
        WHERE relation_name='pay_advances' AND observed IS NOT TRUE),
      'components_not_observed',count(*) FILTER (
        WHERE relation_name='pay_finance_case_components' AND observed IS NOT TRUE),
      'events_not_observed',count(*) FILTER (
        WHERE relation_name='pay_finance_case_events' AND observed IS NOT TRUE)
    )
    INTO v_effect_mismatch_detail
    FROM pg_temp._bpay_wb_expected_effects;

    RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH %',
      v_effect_mismatch_detail::text
      USING ERRCODE='23514', DETAIL=v_effect_mismatch_detail::text;
  END IF;
  IF (v_cases_inserted+v_cases_amended+v_cases_reopened+v_cases_cleared)>0
     AND (SELECT count(*) FROM pg_temp._bpay_wb_expected_effects
          WHERE relation_name='pay_advances' AND observed)
       < (v_cases_inserted+v_cases_amended+v_cases_reopened+v_cases_cleared) THEN
    SELECT jsonb_build_object(
      'case_transitions',v_cases_inserted+v_cases_amended+v_cases_reopened+v_cases_cleared,
      'observed_case_effects',count(*) FILTER (
        WHERE relation_name='pay_advances' AND observed)
    )
    INTO v_effect_mismatch_detail
    FROM pg_temp._bpay_wb_expected_effects;

    RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH %',
      v_effect_mismatch_detail::text
      USING ERRCODE='23514', DETAIL=v_effect_mismatch_detail::text;
  END IF;
  SELECT count(*)::integer,md5(COALESCE(string_agg(
    relation_name||':'||operation||':'||source_id::text||':'||
    COALESCE(expected_before_digest,'')||':'||COALESCE(expected_after_digest,''),''
    ORDER BY relation_name,operation,source_id),''))
  INTO v_observed_effect_count,v_observed_effect_digest
  FROM pg_temp._bpay_wb_expected_effects;

  -- Final freshness fence: preview helpers retained for presentation metadata
  -- cannot publish if any build-bound economic input changed during this RPC.
  -- Finance-case DML legitimately refreshes derived timesheet-pay summary cache
  -- fields.  The initial full-row fingerprint above remains exact; after DML,
  -- compare every non-pay-state revision plus the four settled-authority fields
  -- so cache-only refreshes cannot make the transaction stale while Policy X
  -- settlement authority and every other captured input remain fail-closed.
  CREATE TEMP TABLE pg_temp._bpay_wb_post_sync_freshness_v2(
    timesheet_id uuid PRIMARY KEY,
    input_fingerprint text NULL,
    revision_json jsonb NULL
  ) ON COMMIT DROP;
  IF v_execution_profile_version = 2 THEN
    INSERT INTO pg_temp._bpay_wb_post_sync_freshness_v2(timesheet_id,input_fingerprint,revision_json)
    SELECT fingerprint.timesheet_id,fingerprint.input_fingerprint,fingerprint.revision_json
    FROM private.pay_workbench_timesheet_input_fingerprint_v1(
      p_build_id,v_bounded_build.candidate_id,v_bounded_scope_ids
    ) fingerprint;
  ELSE
    INSERT INTO pg_temp._bpay_wb_post_sync_freshness_v2(timesheet_id,input_fingerprint,revision_json)
    SELECT scope_row.timesheet_id,fingerprint.input_fingerprint,fingerprint.revision_json
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN LATERAL private.pay_workbench_timesheet_input_fingerprint_v1(
      p_build_id,v_bounded_build.candidate_id,ARRAY[scope_row.timesheet_id]
    ) fingerprint ON true
    WHERE scope_row.build_id=p_build_id
      AND (NOT v_slice_active OR scope_row.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */;
  END IF;
  IF EXISTS(
      SELECT 1
      FROM private.banking_pay_workbench_candidate_scope_registry registry
      WHERE registry.candidate_id=v_bounded_build.candidate_id
        AND (registry.current_build_id IS DISTINCT FROM p_build_id
          OR registry.dirty_generation IS DISTINCT FROM v_bounded_build.captured_candidate_generation
          OR registry.current_source_change_seq IS DISTINCT FROM v_bounded_build.source_change_seq)
    ) OR EXISTS(
      SELECT 1
      FROM private.banking_pay_workbench_economic_build_scope scope_row
      LEFT JOIN pg_temp._bpay_wb_pre_sync_freshness_v1 pre_sync
        ON pre_sync.timesheet_id=scope_row.timesheet_id
      LEFT JOIN pg_temp._bpay_wb_post_sync_freshness_v2 current_fingerprint
        ON current_fingerprint.timesheet_id=scope_row.timesheet_id
      LEFT JOIN public.timesheet_pay_state pay_state
        ON pay_state.timesheet_id=scope_row.timesheet_id
      WHERE scope_row.build_id=p_build_id
        AND (NOT v_slice_active OR scope_row.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */
        AND (
          pre_sync.timesheet_id IS NULL
          OR current_fingerprint.input_fingerprint IS NULL
          OR (current_fingerprint.revision_json-'pay_state_digest')
               IS DISTINCT FROM (pre_sync.revision_json-'pay_state_digest')
          OR md5(jsonb_build_object(
               'last_settled_snapshot_json',pay_state.last_settled_snapshot_json,
               'last_settled_signature',pay_state.last_settled_signature,
               'last_settled_pay_batch_id',pay_state.last_settled_pay_batch_id,
               'last_settled_at_utc',pay_state.last_settled_at_utc
             )::text) IS DISTINCT FROM pre_sync.settled_authority_digest
        )
      LIMIT 1
    ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001';
  END IF;
  v_post_freshness_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();
  /* The preview canonicaliser is retained only as a presentation renderer.
     Replace its complete timesheet economic input with the sealed build
     workspace before it runs, then attest the protected output fields. */
  IF to_regclass('pg_temp.timesheet_case_rollup_effective') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_FACT_WORKSPACE_MISSING' USING ERRCODE='23514';
  END IF;
  IF to_regclass('pg_temp.ts_baseline') IS NULL
     OR to_regclass('pg_temp.cand_payee') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_FACT_WORKSPACE_MISSING' USING ERRCODE='23514';
  END IF;
  -- The legacy renderer may omit a revoked or otherwise zero-current-truth
  -- economic target from its case rollup.  Preserve the complete private
  -- presentation graph by creating a neutral metadata-only row for every
  -- fact-derived economic target.  UNIT_PROJECTION also contains physical
  -- dependency evidence which deliberately owns no economic occurrence; that
  -- evidence remains sealed/attested but must not invent a presentation row.
  -- The sealed build facts below remain the sole source of every economic
  -- value.
  IF (SELECT count(*) FROM pg_temp.cand_payee payee
      WHERE payee.candidate_id=v_bounded_build.candidate_id)<>1
     OR EXISTS(
       WITH economic_target AS (
         SELECT DISTINCT component.timesheet_id
         FROM pg_temp.tmp_sync_authoritative_components component
       )
       SELECT 1
       FROM economic_target target
       LEFT JOIN pg_temp.ts_baseline baseline
         ON baseline.candidate_id=v_bounded_build.candidate_id
        AND baseline.timesheet_id=target.timesheet_id
       GROUP BY target.timesheet_id
       HAVING count(baseline.timesheet_id)<>1
     ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PRESENTATION_METADATA_INCOMPLETE' USING ERRCODE='23514';
  END IF;
  INSERT INTO pg_temp.timesheet_case_rollup_effective(
    candidate_id,timesheet_id,client_id,ts_week_ending_date,ts_client_name,ts_pay_method,
    cand_pay_method,cand_tms_ref,cand_display_name,cand_umbrella_id,umb_enabled,
    umb_vat_chargeable,candidate_has_bank_details,candidate_bank_hash,
    umbrella_has_bank_details,umbrella_bank_hash,resolution_family,case_needs_resolution,
    case_resolution_satisfied_now,resolution_action_label,linked_resolution_scope_json,
    case_total_amount_ex,safe_amount_ex,unresolved_taxable_amount_ex,open_taxable_count,
    open_reimbursement_count,unresolved_taxable_count,stale_count,is_mixed_case,is_blocked,
    segments_total_ex,delta_additional_pay_ex_vat,delta_expenses_pay_ex_vat,
    delta_travel_pay_ex_vat,delta_accommodation_pay_ex_vat,delta_other_pay_ex_vat,
    delta_mileage_pay_ex_vat,segment_deltas_json,adjustment_deltas_json,
    additional_unit_deltas_json,reservation_overrun_detected,payment_amount_ex_vat,
    payment_amount_inc_vat,payment_amount,case_resolution_summary_json,case_components_json
  )
  SELECT v_bounded_build.candidate_id,target.timesheet_id,baseline.client_id,
    baseline.ts_week_ending_date,baseline.ts_client_name,baseline.ts_pay_method,
    baseline.cand_pay_method,baseline.cand_tms_ref,baseline.cand_display_name,
    baseline.cand_umbrella_id,baseline.umb_enabled,baseline.umb_vat_chargeable,
    (baseline.cand_bank_hash IS NOT NULL AND BTRIM(baseline.cand_bank_hash)<>''),
    baseline.cand_bank_hash,
    (baseline.umb_bank_hash IS NOT NULL AND BTRIM(baseline.umb_bank_hash)<>''),
    baseline.umb_bank_hash,'BUCKETED',false,true,'Suggested Rate',
    jsonb_build_object(
      'resolve_all_linked_timesheets_default',true,
      'linked_scope_type','SELF_ONLY','linked_timesheet_count',1,
      'linked_timesheet_ids',jsonb_build_array(target.timesheet_id::text),
      'seed_timesheet_id',target.timesheet_id::text),
    0::numeric,0::numeric,0::numeric,0,0,0,0,false,false,
    0::numeric,0::numeric,0::numeric,0::numeric,0::numeric,0::numeric,0::numeric,
    '[]'::jsonb,'[]'::jsonb,'[]'::jsonb,false,
    0::numeric,0::numeric,0::numeric,
    jsonb_build_object(
      'case_needs_resolution',false,'case_resolution_satisfied_now',true,
      'safe_amount_ex_vat',0,'blocked_case_amount_ex_vat',0,
      'unresolved_taxable_amount_ex_vat',0,
      'economic_authority','SEALED_ECONOMIC_BUILD_FACTS','build_id',p_build_id::text),
    '[]'::jsonb
  FROM (
    SELECT DISTINCT component.timesheet_id
    FROM pg_temp.tmp_sync_authoritative_components component
  ) target
  JOIN pg_temp.ts_baseline baseline
    ON baseline.candidate_id=v_bounded_build.candidate_id
   AND baseline.timesheet_id=target.timesheet_id
  WHERE NOT EXISTS(
    SELECT 1 FROM pg_temp.timesheet_case_rollup_effective preview_row
    WHERE preview_row.candidate_id=v_bounded_build.candidate_id
      AND preview_row.timesheet_id=target.timesheet_id
  );
  IF EXISTS(
    SELECT 1
    FROM pg_temp.tmp_sync_authoritative_components component
    WHERE component.timesheet_id IS NOT NULL
      AND NOT EXISTS(SELECT 1 FROM pg_temp.timesheet_case_rollup_effective preview_row
        WHERE preview_row.candidate_id=v_bounded_build.candidate_id
          AND preview_row.timesheet_id=component.timesheet_id)
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_FACT_SCOPE_INCOMPLETE' USING ERRCODE='23514';
  END IF;
  DELETE FROM pg_temp.timesheet_case_rollup_effective preview_row
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id
    AND NOT EXISTS(SELECT 1 FROM pg_temp.tmp_sync_authoritative_components component
      WHERE component.timesheet_id=preview_row.timesheet_id);

  UPDATE pg_temp.timesheet_case_rollup_effective preview_row
  SET case_components_json=COALESCE((
    SELECT jsonb_agg(component.component_json ORDER BY component.source_rank,
      component.component_ordinality,component.physical_bucket_key)
    FROM (
      SELECT 0::integer AS source_rank,raw_component.component_ordinality,
        raw_component.physical_bucket_key,
        raw_component.component_json||jsonb_strip_nulls(jsonb_build_object(
          'component_amount_ex_vat',COALESCE(
            CASE WHEN COALESCE(sealed.evidence_json#>>
                '{physical_bucket,builder_component_amount_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN (sealed.evidence_json#>>
                '{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
            sealed.outstanding_ex_vat),
          'source_pay_ex_vat',COALESCE(
            CASE WHEN COALESCE(sealed.evidence_json#>>
                '{physical_bucket,builder_component_amount_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN (sealed.evidence_json#>>
                '{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
            sealed.outstanding_ex_vat),
          'source_charge_ex_vat',sealed.source_charge_ex_vat
        )) AS component_json
      FROM pg_temp.tmp_sync_raw_preview_physical_components raw_component
      JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
        ON sealed.timesheet_id=raw_component.timesheet_id
       AND sealed.physical_bucket_key=raw_component.physical_bucket_key
       AND sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
      WHERE raw_component.candidate_id=preview_row.candidate_id
        AND raw_component.timesheet_id=preview_row.timesheet_id
      UNION ALL
      SELECT 1::integer,missing.bucket_sort_ordinal::bigint,
        missing.physical_bucket_key,missing.component_json
      FROM pg_temp.tmp_sync_sealed_missing_preview_components missing
      WHERE missing.candidate_id=preview_row.candidate_id
        AND missing.timesheet_id=preview_row.timesheet_id
    ) component
  ),'[]'::jsonb)
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id;

  DROP TABLE IF EXISTS pg_temp.tmp_sync_builder_physical_components;
  CREATE TEMP TABLE pg_temp.tmp_sync_builder_physical_components ON COMMIT DROP AS
  SELECT preview_row.candidate_id,preview_row.timesheet_id,
    component.ordinality::integer AS component_ordinality,component.value AS component_json,
    UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),'')) AS economic_key_type,
    NULLIF(BTRIM(component.value->>'component_key_value'),'') AS economic_key_value,
    concat_ws('|','RATE_BUCKET_V1',preview_row.timesheet_id::text,
      NULLIF(BTRIM(component.value->>'source_family_key'),''),
      UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),'')),
      NULLIF(BTRIM(component.value->>'component_key_value'),''),
      CASE
        WHEN UPPER(BTRIM(COALESCE(
            component.value#>>'{source_basis_json,component_fallback}','')))='WORKED_TIME_AMOUNT'
          THEN 'worked-time-residual:'||UPPER(BTRIM(component.value->>'component_key_type'))
            ||':'||BTRIM(component.value->>'component_key_value')
        WHEN UPPER(BTRIM(component.value->>'component_key_type')) IN ('TS_DAY','TS_TOTAL')
          THEN COALESCE(
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_stable_key}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_key}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,work_date}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,date}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,ref_num}'),''))
        WHEN UPPER(BTRIM(component.value->>'component_key_type'))='ADDITIONAL_CODE'
          THEN 'additional:'||UPPER(BTRIM(component.value#>>'{source_basis_json,additional_code}'))
        WHEN UPPER(BTRIM(component.value->>'component_key_type'))='EXPENSE_CODE'
          THEN 'expense:'||UPPER(BTRIM(component.value#>>'{source_basis_json,expense_code}'))
        WHEN UPPER(BTRIM(component.value->>'component_key_type'))='ADJUSTMENT_CODE'
          THEN 'adjustment:'||BTRIM(component.value#>>'{source_basis_json,adjustment_id}')
      END,
      UPPER(BTRIM(COALESCE(
        CASE WHEN UPPER(BTRIM(COALESCE(
            component.value#>>'{source_basis_json,component_fallback}','')))='WORKED_TIME_AMOUNT'
          THEN 'FIXED' END,
        NULLIF(component.value#>>'{source_basis_json,bucket_code}',''),
        CASE UPPER(BTRIM(component.value->>'component_key_type'))
          WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
          WHEN 'EXPENSE_CODE' THEN 'FIXED'
          WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
        END))))
      AS physical_bucket_key,
    md5(jsonb_build_object(
      'builder_comparison_version',1,'timesheet_id',preview_row.timesheet_id::text,
      'source_family_key',NULLIF(BTRIM(component.value->>'source_family_key'),''),
      'component_key_type',UPPER(BTRIM(component.value->>'component_key_type')),
      'component_key_value',BTRIM(component.value->>'component_key_value'),
      'segment_id',NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),''),
      'segment_key',COALESCE(
        NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_key}'),''),
        NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),'')),
      'segment_stable_key',NULLIF(BTRIM(
        component.value#>>'{source_basis_json,segment_stable_key}'),''),
      'work_date',NULLIF(BTRIM(COALESCE(component.value#>>'{source_basis_json,work_date}',
        component.value#>>'{source_basis_json,date}')),''),
      'ref_num',NULLIF(BTRIM(component.value#>>'{source_basis_json,ref_num}'),''),
      'additional_code',NULLIF(UPPER(BTRIM(
        component.value#>>'{source_basis_json,additional_code}')),''),
      'expense_code',NULLIF(UPPER(BTRIM(
        component.value#>>'{source_basis_json,expense_code}')),''),
      'adjustment_id',NULLIF(BTRIM(component.value#>>'{source_basis_json,adjustment_id}'),''),
      'bucket_code',UPPER(BTRIM(COALESCE(
        CASE WHEN UPPER(BTRIM(COALESCE(
            component.value#>>'{source_basis_json,component_fallback}','')))='WORKED_TIME_AMOUNT'
          THEN 'FIXED' END,
        NULLIF(component.value#>>'{source_basis_json,bucket_code}',''),
        CASE UPPER(BTRIM(component.value->>'component_key_type'))
          WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
          WHEN 'EXPENSE_CODE' THEN 'FIXED'
          WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
        END))),
      'source_units',CASE WHEN COALESCE(component.value->>'source_units','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_units')::numeric,6) END,
      'source_rate',CASE WHEN COALESCE(component.value->>'source_rate','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_rate')::numeric,6) END,
      'source_charge_rate',CASE WHEN COALESCE(component.value->>'source_charge_rate','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_charge_rate')::numeric,6) END,
      'source_pay_ex_vat',CASE WHEN COALESCE(component.value->>'source_pay_ex_vat','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_pay_ex_vat')::numeric,2) END,
      'source_charge_ex_vat',CASE WHEN COALESCE(component.value->>'source_charge_ex_vat','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_charge_ex_vat')::numeric,2) END,
      'source_pay_method',UPPER(NULLIF(BTRIM(component.value->>'source_pay_method'),'')),
      'target_pay_method',UPPER(NULLIF(BTRIM(
        component.value->>'current_target_pay_method'),'')))::text) AS builder_comparison_digest
  FROM pg_temp.timesheet_case_rollup_effective preview_row
  CROSS JOIN LATERAL jsonb_array_elements(CASE
    WHEN jsonb_typeof(preview_row.case_components_json)='array'
      THEN preview_row.case_components_json ELSE '[]'::jsonb END)
    WITH ORDINALITY component(value,ordinality)
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id;

  SELECT failure.failure_code,failure.detail_json
  INTO v_rate_authority_failure_code,v_rate_authority_failure_detail
  FROM (
    SELECT 10 AS failure_rank,'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_COMPONENT_MISSING'::text
        AS failure_code,jsonb_build_object('timesheet_id',sealed.timesheet_id,
          'physical_bucket_key',sealed.physical_bucket_key) AS detail_json
    FROM pg_temp.tmp_sync_sealed_rate_projection sealed
    LEFT JOIN pg_temp.tmp_sync_builder_physical_components builder
      ON builder.timesheet_id=sealed.timesheet_id
     AND builder.physical_bucket_key=sealed.physical_bucket_key
    WHERE sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
      AND builder.timesheet_id IS NULL
    UNION ALL
    SELECT 20,'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_COMPONENT_EXTRA',jsonb_build_object(
      'timesheet_id',builder.timesheet_id,'physical_bucket_key',builder.physical_bucket_key)
    FROM pg_temp.tmp_sync_builder_physical_components builder
    LEFT JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
      ON sealed.timesheet_id=builder.timesheet_id
     AND sealed.physical_bucket_key=builder.physical_bucket_key
    WHERE sealed.timesheet_id IS NULL
    UNION ALL
    SELECT 30,'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_DIGEST_MISMATCH',jsonb_build_object(
      'timesheet_id',sealed.timesheet_id,'physical_bucket_key',sealed.physical_bucket_key,
      'economic_key_type',sealed.economic_key_type,
      'economic_key_value',sealed.economic_key_value,
      'digest_mismatch',builder.builder_comparison_digest IS DISTINCT FROM
        sealed.evidence_json#>>'{physical_bucket,builder_comparison_digest}',
      'amount_mismatch',CASE WHEN COALESCE(builder.component_json->>'component_amount_ex_vat','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((builder.component_json->>'component_amount_ex_vat')::numeric,2)
        ELSE NULL::numeric END IS DISTINCT FROM ROUND(COALESCE(
          CASE WHEN COALESCE(sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}','')
              ~ '^-?\d+(\.\d+)?$'
            THEN (sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
          sealed.outstanding_ex_vat),2),
      'expected_digest',sealed.evidence_json#>>'{physical_bucket,builder_comparison_digest}',
      'actual_digest',builder.builder_comparison_digest,
      'expected_amount_ex_vat',ROUND(COALESCE(
        CASE WHEN COALESCE(sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}','')
            ~ '^-?\d+(\.\d+)?$'
          THEN (sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
        sealed.outstanding_ex_vat),2),
      'actual_amount_ex_vat',CASE WHEN COALESCE(builder.component_json->>'component_amount_ex_vat','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((builder.component_json->>'component_amount_ex_vat')::numeric,2) END)
    FROM pg_temp.tmp_sync_sealed_rate_projection sealed
    JOIN pg_temp.tmp_sync_builder_physical_components builder
      ON builder.timesheet_id=sealed.timesheet_id
     AND builder.physical_bucket_key=sealed.physical_bucket_key
    WHERE builder.builder_comparison_digest IS DISTINCT FROM
        sealed.evidence_json#>>'{physical_bucket,builder_comparison_digest}'
       OR CASE WHEN COALESCE(builder.component_json->>'component_amount_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((builder.component_json->>'component_amount_ex_vat')::numeric,2)
          ELSE NULL::numeric END IS DISTINCT FROM ROUND(COALESCE(
            CASE WHEN COALESCE(sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN (sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
            sealed.outstanding_ex_vat),2)
  ) failure
  ORDER BY failure.failure_rank,
    failure.detail_json->>'timesheet_id',failure.detail_json->>'physical_bucket_key'
  LIMIT 1;

  IF v_rate_authority_failure_code IS NOT NULL THEN
    RAISE EXCEPTION '%',v_rate_authority_failure_code USING ERRCODE='P0001',
      DETAIL=jsonb_build_object('code',v_rate_authority_failure_code,
        'detail',v_rate_authority_failure_detail)::text;
  END IF;

  WITH overlaid AS (
    SELECT builder.candidate_id,builder.timesheet_id,builder.component_ordinality,
      builder.component_json||jsonb_build_object(
        'component_amount_ex_vat',sealed.outstanding_ex_vat,
        'authoritative_truth_ex_vat',sealed.truth_ex_vat,
        'authoritative_baseline_ex_vat',sealed.baseline_ex_vat,
        'authoritative_reserved_ex_vat',sealed.reserved_ex_vat,
        'authoritative_outstanding_ex_vat',sealed.outstanding_ex_vat,
        'overpayment_component_authority','PRE_DRAFT_LIVE_TRUTH',
        'physical_bucket_key',sealed.physical_bucket_key,
        'physical_bucket_digest',sealed.physical_bucket_digest,
        'sealed_evidence_digest',sealed.sealed_evidence_digest,
        'financial_revision_digest',sealed.financial_revision_digest,
        'target_authority_digest',sealed.target_authority_digest,
        'conversion_context_digest',sealed.conversion_context_digest,
        'source_pay_method',sealed.source_pay_method,
        'current_target_pay_method',sealed.target_pay_method,
        'source_basis_json',(CASE
          WHEN jsonb_typeof(builder.component_json->'source_basis_json')='object'
            THEN builder.component_json->'source_basis_json'
          ELSE '{}'::jsonb END)||jsonb_build_object(
            'source_pay_method',sealed.source_pay_method))
        AS component_json
    FROM pg_temp.tmp_sync_builder_physical_components builder
    JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
      ON sealed.timesheet_id=builder.timesheet_id
     AND sealed.physical_bucket_key=builder.physical_bucket_key
  ), grouped AS (
    SELECT overlaid.candidate_id,overlaid.timesheet_id,
      jsonb_agg(overlaid.component_json ORDER BY overlaid.component_ordinality) AS components_json
    FROM overlaid GROUP BY overlaid.candidate_id,overlaid.timesheet_id
  )
  UPDATE pg_temp.timesheet_case_rollup_effective preview_row
  SET case_components_json=grouped.components_json
  FROM grouped
  WHERE preview_row.candidate_id=grouped.candidate_id
    AND preview_row.timesheet_id=grouped.timesheet_id;

  WITH fact_totals AS (
    SELECT component.timesheet_id,
      ROUND(COALESCE(SUM(component.truth_ex_vat),0),2)::numeric(12,2) AS truth_ex_vat,
      ROUND(COALESCE(SUM(entitlement.truth_inc_vat),0),2)::numeric(12,2) AS truth_inc_vat
    FROM pg_temp.tmp_sync_authoritative_components component
    LEFT JOIN (
      SELECT legacy_component.*
      FROM private.pay_current_timesheet_entitlement_components_from_build_v1(p_build_id,NULL::text) legacy_component
      WHERE v_execution_profile_version = 1
      UNION ALL
      SELECT cached_component.*
      FROM pg_temp.tmp_sync_entitlement_components_v2 cached_component
      WHERE v_execution_profile_version = 2
    ) entitlement
      ON entitlement.timesheet_id=component.timesheet_id
     AND entitlement.key_type=component.key_type AND entitlement.key_value=component.key_value
    GROUP BY component.timesheet_id
  )
  UPDATE pg_temp.timesheet_case_rollup_effective preview_row
  SET payment_amount_ex_vat=COALESCE(fact_totals.truth_ex_vat,0),
      payment_amount_inc_vat=COALESCE(fact_totals.truth_inc_vat,fact_totals.truth_ex_vat,0),
      payment_amount=COALESCE(fact_totals.truth_inc_vat,fact_totals.truth_ex_vat,0),
      case_total_amount_ex=COALESCE(fact_totals.truth_ex_vat,0),
      safe_amount_ex=CASE WHEN preview_row.is_blocked THEN 0 ELSE COALESCE(fact_totals.truth_ex_vat,0) END,
      case_resolution_summary_json=COALESCE(preview_row.case_resolution_summary_json,'{}'::jsonb)
        ||jsonb_build_object('economic_authority','SEALED_ECONOMIC_BUILD_FACTS','build_id',p_build_id::text)
  FROM fact_totals
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id
    AND preview_row.timesheet_id=fact_totals.timesheet_id;
  UPDATE pg_temp.timesheet_case_rollup_effective preview_row
  SET payment_amount_ex_vat=0,payment_amount_inc_vat=0,payment_amount=0,
      case_total_amount_ex=0,safe_amount_ex=0,case_components_json='[]'::jsonb,
      case_resolution_summary_json=COALESCE(preview_row.case_resolution_summary_json,'{}'::jsonb)
        ||jsonb_build_object('economic_authority','SEALED_ECONOMIC_BUILD_FACTS','build_id',p_build_id::text)
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id
    AND EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
      WHERE scope_row.build_id=p_build_id AND scope_row.timesheet_id=preview_row.timesheet_id)
    AND NOT EXISTS(SELECT 1 FROM pg_temp.tmp_sync_authoritative_components component
      WHERE component.timesheet_id=preview_row.timesheet_id);

  -- Economic completeness is private build authority.  It is deliberately
  -- attested before presentation rendering so a zero-net, hidden, blocked or
  -- snoozed line is not required to invent a public row merely to prove that
  -- its physical components were preserved.
  SELECT md5(COALESCE(string_agg(
    sealed.timesheet_id::text||':'||sealed.economic_key_type||':'||
    sealed.economic_key_value||':'||sealed.physical_bucket_key||':'||
    sealed.sealed_evidence_digest,'' ORDER BY sealed.timesheet_id,
    sealed.economic_key_type,sealed.economic_key_value,sealed.bucket_sort_ordinal,
    sealed.physical_bucket_key),''))
  INTO v_bounded_economic_component_digest
  FROM pg_temp.tmp_sync_sealed_rate_projection sealed;

  v_bounded_canonical_result:=public.pay_preview_candidate_build_canonical_lines(
    v_preview_context_json,v_bounded_build.candidate_id);
  IF to_regclass('pg_temp.canonical_preview_lines') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CANONICAL_LINES_MISSING' USING ERRCODE='23514';
  END IF;
  IF to_regclass('pg_temp.canonical_timesheet_presentation_state') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PRESENTATION_STATE_MISSING' USING ERRCODE='23514';
  END IF;
  -- The renderer's protected state must cover the sealed scope exactly.  Its
  -- ready + blocked + indefinitely-hidden allocation must also reconstruct the
  -- complete private economic truth.  Case-resolution presentation is an
  -- overlay and is intentionally not added to that economic total.
  WITH economic_target AS (
    SELECT DISTINCT component.timesheet_id
    FROM pg_temp.tmp_sync_authoritative_components component
  ), fact_truth AS (
    SELECT target.timesheet_id,
      ROUND(COALESCE(SUM(component.truth_ex_vat),0),2) AS truth_ex_vat
    FROM economic_target target
    LEFT JOIN pg_temp.tmp_sync_authoritative_components component
      ON component.timesheet_id=target.timesheet_id
    GROUP BY target.timesheet_id
  ), state_row AS (
    SELECT state.timesheet_id,COUNT(*) AS state_count,
      MIN(state.amount_ex_vat) AS amount_ex_vat,
      MIN(state.ready_section_amount_ex_vat) AS ready_amount,
      MIN(state.blocked_section_amount_ex_vat) AS blocked_amount,
      MIN(state.hidden_indefinite_segment_amount_ex_vat) AS hidden_segment_amount,
      MIN(state.hidden_expense_amount_ex_vat) AS hidden_expense_amount,
      BOOL_OR(COALESCE(state.resolved_segment_rows_replace_source_total,false))
        AS resolved_segment_rows_replace_source_total,
      MIN(component_allocation.component_count) AS component_count,
      MIN(component_allocation.invalid_amount_count) AS invalid_component_amount_count,
      MIN(component_allocation.presentation_amount_ex_vat)
        AS component_presentation_amount_ex_vat
    FROM pg_temp.canonical_timesheet_presentation_state state
    LEFT JOIN LATERAL (
      SELECT COUNT(*)::integer AS component_count,
        COUNT(*) FILTER (WHERE
          COALESCE(component.value->>'ready_preview_amount_ex_vat','')
            !~ '^-?\d+(\.\d+)?$'
          AND COALESCE(component.value->>'preview_component_amount_ex_vat','')
            !~ '^-?\d+(\.\d+)?$')::integer AS invalid_amount_count,
        ROUND(COALESCE(SUM(CASE
          WHEN COALESCE(component.value->>'ready_preview_amount_ex_vat','')
              ~ '^-?\d+(\.\d+)?$'
            THEN (component.value->>'ready_preview_amount_ex_vat')::numeric
          WHEN COALESCE(component.value->>'preview_component_amount_ex_vat','')
              ~ '^-?\d+(\.\d+)?$'
            THEN (component.value->>'preview_component_amount_ex_vat')::numeric
          ELSE 0::numeric
        END),0),2) AS presentation_amount_ex_vat
      FROM jsonb_array_elements(CASE
        WHEN jsonb_typeof(state.case_components_json)='array'
          THEN state.case_components_json ELSE '[]'::jsonb END) component(value)
    ) component_allocation ON true
    WHERE state.candidate_id=v_bounded_build.candidate_id
    GROUP BY state.timesheet_id
  ), rollup_row AS (
    SELECT rollup.timesheet_id,COUNT(*) AS rollup_count
    FROM pg_temp.timesheet_case_rollup_effective rollup
    WHERE rollup.candidate_id=v_bounded_build.candidate_id
    GROUP BY rollup.timesheet_id
  ), canonical_line_row AS (
    SELECT line.timesheet_id,COUNT(*) AS line_count
    FROM pg_temp.canonical_timesheet_lines line
    WHERE line.candidate_id=v_bounded_build.candidate_id
    GROUP BY line.timesheet_id
  ), presentation_seed_row AS (
    SELECT seed.timesheet_id,COUNT(*) AS seed_count
    FROM pg_temp.canonical_timesheet_presentation_seed seed
    WHERE seed.candidate_id=v_bounded_build.candidate_id
    GROUP BY seed.timesheet_id
  ), mismatch AS (
    SELECT
      fact.timesheet_id IS NULL AS missing_fact_target,
      state.timesheet_id IS NULL AS missing_state,
      COALESCE(state.state_count,0)<>1 AS state_multiplicity_mismatch,
      ABS(COALESCE(state.amount_ex_vat,0)-COALESCE(fact.truth_ex_vat,0))>0.01
        AS truth_amount_mismatch,
      (
        COALESCE(state.resolved_segment_rows_replace_source_total,false)
        AND (COALESCE(state.component_count,0)=0
          OR COALESCE(state.invalid_component_amount_count,0)>0)
      ) AS resolved_basis_bridge_invalid,
      ABS(COALESCE(CASE
        -- A resolved-rate presentation is intentionally target-valued while
        -- amount_ex_vat remains the sealed source economic truth.  The
        -- renderer's existing replacement marker selects the independently
        -- materialised component presentation total for this sum only.
        WHEN COALESCE(state.resolved_segment_rows_replace_source_total,false)
          THEN state.component_presentation_amount_ex_vat
        ELSE state.amount_ex_vat
      END,0)-(
        COALESCE(state.ready_amount,0)+COALESCE(state.blocked_amount,0)
        +COALESCE(state.hidden_segment_amount,0)+COALESCE(state.hidden_expense_amount,0)))>0.01
        AS allocation_sum_mismatch,
      COALESCE(rollup.rollup_count,0)>0 AS rollup_present,
      COALESCE(canonical_line.line_count,0)>0 AS canonical_line_present,
      COALESCE(presentation_seed.seed_count,0)>0 AS presentation_seed_present
    FROM fact_truth fact
    FULL OUTER JOIN state_row state USING(timesheet_id)
    LEFT JOIN rollup_row rollup USING(timesheet_id)
    LEFT JOIN canonical_line_row canonical_line USING(timesheet_id)
    LEFT JOIN presentation_seed_row presentation_seed USING(timesheet_id)
  )
  SELECT jsonb_build_object(
    'mismatch_count',count(*) FILTER (
      WHERE missing_fact_target OR missing_state OR state_multiplicity_mismatch
         OR truth_amount_mismatch OR resolved_basis_bridge_invalid
         OR allocation_sum_mismatch),
    'missing_fact_target_count',count(*) FILTER (WHERE missing_fact_target),
    'missing_state_count',count(*) FILTER (WHERE missing_state),
    'state_multiplicity_mismatch_count',count(*) FILTER (WHERE state_multiplicity_mismatch),
    'truth_amount_mismatch_count',count(*) FILTER (WHERE truth_amount_mismatch),
    'resolved_basis_bridge_invalid_count',count(*) FILTER (
      WHERE resolved_basis_bridge_invalid),
    'allocation_sum_mismatch_count',count(*) FILTER (WHERE allocation_sum_mismatch),
    'missing_state_with_rollup_count',count(*) FILTER (WHERE missing_state AND rollup_present),
    'missing_state_with_canonical_line_count',count(*) FILTER (
      WHERE missing_state AND canonical_line_present),
    'missing_state_with_presentation_seed_count',count(*) FILTER (
      WHERE missing_state AND presentation_seed_present)
  )
  INTO v_presentation_mismatch_detail
  FROM mismatch;

  IF COALESCE((v_presentation_mismatch_detail->>'mismatch_count')::integer,0)>0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PRESENTATION_ALLOCATION_AUTHORITY_MISMATCH %',
      v_presentation_mismatch_detail::text
      USING ERRCODE='23514';
  END IF;
  IF EXISTS(
    SELECT 1 FROM pg_temp.canonical_preview_lines line
    WHERE line.candidate_id=v_bounded_build.candidate_id
      AND UPPER(COALESCE(line.line_json->>'line_type',''))='TIMESHEET_PAYMENT'
      AND (
        COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
          !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR NOT EXISTS(
          SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
          WHERE scope_row.build_id=p_build_id
            AND scope_row.timesheet_id=COALESCE(line.line_json->>'real_business_timesheet_id',
              line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid)
        OR UPPER(BTRIM(COALESCE(line.pay_channel::text,''))) IS DISTINCT FROM v_scope
      )
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_FACT_AUTHORITY_MISMATCH' USING ERRCODE='23514';
  END IF;
  IF EXISTS(
    SELECT 1
    FROM pg_temp.canonical_preview_lines line
    WHERE line.candidate_id=v_bounded_build.candidate_id
    GROUP BY COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_line_id'),''),
      NULLIF(BTRIM(line.line_json->>'preview_row_id'),''),
      NULLIF(BTRIM(line.line_json->>'line_id'),''),NULLIF(BTRIM(line.line_json->>'case_key'),''),
      md5(line.line_json::text))
    HAVING count(*)>1
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_LINE_IDENTITY_CONFLICT %', (
      WITH keyed_lines AS (
        SELECT
          COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_line_id'),''),
            NULLIF(BTRIM(line.line_json->>'preview_row_id'),''),
            NULLIF(BTRIM(line.line_json->>'line_id'),''),NULLIF(BTRIM(line.line_json->>'case_key'),''),
            md5(line.line_json::text)) AS line_identity,
          CASE
            WHEN NULLIF(BTRIM(line.line_json->>'presentation_line_id'),'') IS NOT NULL THEN 'PRESENTATION_LINE_ID'
            WHEN NULLIF(BTRIM(line.line_json->>'preview_row_id'),'') IS NOT NULL THEN 'PREVIEW_ROW_ID'
            WHEN NULLIF(BTRIM(line.line_json->>'line_id'),'') IS NOT NULL THEN 'LINE_ID'
            WHEN NULLIF(BTRIM(line.line_json->>'case_key'),'') IS NOT NULL THEN 'CASE_KEY'
            ELSE 'ROW_DIGEST'
          END AS identity_source,
          UPPER(COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_role'),''),'~')) AS presentation_role,
          UPPER(COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_section'),''),'~')) AS presentation_section,
          UPPER(COALESCE(NULLIF(BTRIM(line.line_json->>'line_type'),''),'~')) AS line_type,
          UPPER(COALESCE(NULLIF(BTRIM(line.line_json->>'component_key_type'),''),'~')) AS component_key_type,
          UPPER(COALESCE(NULLIF(BTRIM(COALESCE(
            line.line_json->>'bucket_code',
            line.line_json#>>'{source_basis_json,bucket_code}'
          )),''),'~')) AS bucket_code
        FROM pg_temp.canonical_preview_lines line
        WHERE line.candidate_id=v_bounded_build.candidate_id
      ), duplicate_identities AS (
        SELECT keyed.line_identity,count(*)::integer AS row_count
        FROM keyed_lines keyed
        GROUP BY keyed.line_identity
        HAVING count(*)>1
      ), duplicate_rows AS (
        SELECT keyed.*
        FROM keyed_lines keyed
        JOIN duplicate_identities duplicate_identity
          ON duplicate_identity.line_identity=keyed.line_identity
      ), shape_counts AS (
        SELECT concat_ws('|',duplicate_row.identity_source,duplicate_row.presentation_role,
                 duplicate_row.presentation_section,duplicate_row.line_type,
                 duplicate_row.component_key_type,duplicate_row.bucket_code) AS shape,
               count(*)::integer AS row_count
        FROM duplicate_rows duplicate_row
        GROUP BY duplicate_row.identity_source,duplicate_row.presentation_role,
          duplicate_row.presentation_section,duplicate_row.line_type,
          duplicate_row.component_key_type,duplicate_row.bucket_code
      )
      SELECT jsonb_build_object(
        'duplicate_identity_count',(SELECT count(*)::integer FROM duplicate_identities),
        'duplicate_row_count',(SELECT count(*)::integer FROM duplicate_rows),
        'maximum_identity_multiplicity',COALESCE((SELECT max(row_count) FROM duplicate_identities),0),
        'line_shape_counts',COALESCE((SELECT jsonb_object_agg(shape,row_count ORDER BY shape)
          FROM shape_counts),'{}'::jsonb)
      )
    )::text USING ERRCODE='23514';
  END IF;
  IF EXISTS(
    WITH expected AS (
      SELECT (allocation.value->>'timesheet_id')::uuid AS timesheet_id,
        allocation.value->>'line_identity' AS line_identity,
        allocation.value->>'parent_line_identity' AS parent_line_identity,
        allocation.value->>'presentation_section' AS presentation_section,
        allocation.value->>'pay_channel' AS pay_channel,
        ROUND((allocation.value->>'amount_ex_vat')::numeric,2) AS amount_ex_vat,
        (allocation.value->>'draftable')::boolean AS draftable,
        (allocation.value->>'excluded_from_allocation')::boolean AS excluded_from_allocation,
        ROUND((allocation.value->>'section_non_segment_amount_ex_vat')::numeric,2)
          AS section_non_segment_amount_ex_vat,
        allocation.value->'section_segment_rows' AS section_segment_rows,
        (allocation.value->>'resolved_segment_rows_replace_source_total')::boolean
          AS resolved_segment_rows_replace_source_total
      FROM pg_temp.canonical_timesheet_presentation_state state
      CROSS JOIN LATERAL jsonb_array_elements(
        private.pay_workbench_presentation_allocation_expected_v1(to_jsonb(state))) allocation(value)
      WHERE state.candidate_id=v_bounded_build.candidate_id
    ), actual AS (
      SELECT COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid
          AS timesheet_id,
        COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_line_id'),''),
          NULLIF(BTRIM(line.line_json->>'line_id'),'')) AS line_identity,
        NULLIF(BTRIM(line.line_json->>'presentation_parent_line_id'),'') AS parent_line_identity,
        UPPER(NULLIF(BTRIM(line.line_json->>'presentation_section'),'')) AS presentation_section,
        UPPER(BTRIM(COALESCE(line.pay_channel::text,line.line_json->>'pay_channel',''))) AS pay_channel,
        ROUND(COALESCE(line.amount_ex_vat,0),2) AS amount_ex_vat,
        COALESCE((line.line_json->>'is_ready_for_draft')::boolean,false) AS draftable,
        COALESCE((line.line_json->>'is_excluded_from_allocation')::boolean,false)
          AS excluded_from_allocation,
        (
          UPPER(COALESCE(line.line_json->>'presentation_role',''))='PARENT'
          AND COALESCE((line.line_json->>'selection_allowed')::boolean,false)=false
          AND COALESCE((line.line_json->>'is_excluded_from_allocation')::boolean,false)=true
        ) AS semantic_non_selectable_parent,
        (
          UPPER(COALESCE(line.line_json->>'presentation_role',''))='PARENT'
          AND UPPER(COALESCE(line.line_json->>'presentation_reason',''))=
            'NEGATIVE_ORDINARY_PRESENTATION_ONLY'
          AND UPPER(COALESCE(line.line_json->>'presentation_section',''))='BLOCKED_FOR_PAY'
          AND COALESCE((line.line_json->>'selection_allowed')::boolean,false)=false
          AND COALESCE((line.line_json->>'is_excluded_from_allocation')::boolean,false)=true
          AND ROUND(COALESCE(line.amount_ex_vat,0),2)<0
        ) AS semantic_negative_parent,
        ROUND(COALESCE((line.line_json->>'section_non_segment_amount_ex_vat')::numeric,0),2)
          AS section_non_segment_amount_ex_vat,
        CASE WHEN jsonb_typeof(line.line_json->'section_segment_rows')='array'
          THEN line.line_json->'section_segment_rows' ELSE '[]'::jsonb END AS section_segment_rows,
        COALESCE((line.line_json->>'resolved_segment_rows_replace_source_total')::boolean,false)
          AS resolved_segment_rows_replace_source_total
      FROM pg_temp.canonical_preview_lines line
      WHERE line.candidate_id=v_bounded_build.candidate_id
        AND UPPER(COALESCE(line.line_json->>'line_type',''))='TIMESHEET_PAYMENT'
        -- Semantic V3 publishes exact keyed allocation components beside the
        -- aggregate presentation parent.  The protected presentation fence
        -- continues to compare the parent only; economic component equality
        -- is independently enforced by the canonical fact-component fence
        -- immediately below.
        AND UPPER(COALESCE(line.line_json->>'presentation_role','PARENT'))
          <> 'ALLOCATION_COMPONENT'
        AND COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
    SELECT 1
    FROM expected
    FULL OUTER JOIN actual USING(timesheet_id,line_identity)
    WHERE expected.timesheet_id IS NULL OR actual.timesheet_id IS NULL
       OR actual.parent_line_identity IS DISTINCT FROM expected.parent_line_identity
       OR (
         actual.presentation_section IS DISTINCT FROM expected.presentation_section
         AND NOT (
           actual.semantic_negative_parent
           AND actual.presentation_section='BLOCKED_FOR_PAY'
           AND expected.presentation_section='READY_TO_PAY'
         )
       )
       OR actual.pay_channel IS DISTINCT FROM expected.pay_channel
       OR ABS(actual.amount_ex_vat-expected.amount_ex_vat)>0.01
       OR (
         actual.semantic_non_selectable_parent
         AND actual.draftable IS DISTINCT FROM false
       )
       OR (
         NOT actual.semantic_non_selectable_parent
         AND actual.draftable IS DISTINCT FROM expected.draftable
       )
       OR (
         NOT actual.semantic_non_selectable_parent
         AND actual.excluded_from_allocation IS DISTINCT FROM expected.excluded_from_allocation
       )
       OR ABS(actual.section_non_segment_amount_ex_vat-
         expected.section_non_segment_amount_ex_vat)>0.01
       OR actual.section_segment_rows IS DISTINCT FROM expected.section_segment_rows
       OR actual.resolved_segment_rows_replace_source_total IS DISTINCT FROM
         expected.resolved_segment_rows_replace_source_total
    LIMIT 1
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PRESENTATION_ALLOCATION_MISMATCH'
      USING ERRCODE='23514';
  END IF;
  SELECT md5(COALESCE(string_agg(allocation.value::text,'' ORDER BY
    allocation.value->>'timesheet_id',allocation.value->>'line_identity'),''))
  INTO v_bounded_presentation_allocation_digest
  FROM pg_temp.canonical_timesheet_presentation_state state
  CROSS JOIN LATERAL jsonb_array_elements(
    private.pay_workbench_presentation_allocation_expected_v1(to_jsonb(state))) allocation(value)
  WHERE state.candidate_id=v_bounded_build.candidate_id;
  IF EXISTS(
    WITH expected AS (
      SELECT sealed.timesheet_id,sealed.economic_key_type AS key_type,
        sealed.economic_key_value AS key_value,sealed.physical_bucket_key,
        sealed.evidence_json#>>'{physical_bucket,builder_comparison_digest}'
          AS builder_comparison_digest,
        sealed.outstanding_ex_vat AS component_amount_ex_vat,
        sealed.truth_ex_vat,sealed.baseline_ex_vat,sealed.reserved_ex_vat,
        sealed.outstanding_ex_vat,sealed.physical_bucket_digest,
        sealed.sealed_evidence_digest,sealed.financial_revision_digest,
        sealed.target_authority_digest,sealed.conversion_context_digest
      FROM pg_temp.tmp_sync_sealed_rate_projection sealed
      WHERE sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
    ), actual_lines AS (
      SELECT COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid AS timesheet_id,
        COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_line_id'),''),
          NULLIF(BTRIM(line.line_json->>'preview_row_id'),''),
          NULLIF(BTRIM(line.line_json->>'line_id'),''),NULLIF(BTRIM(line.line_json->>'case_key'),''),
          md5(line.line_json::text)) AS line_identity,
        CASE WHEN jsonb_typeof(line.line_json->'case_components')='array'
          THEN line.line_json->'case_components' ELSE '[]'::jsonb END AS components_json
      FROM pg_temp.canonical_preview_lines line
      WHERE line.candidate_id=v_bounded_build.candidate_id
        AND UPPER(COALESCE(line.line_json->>'line_type',''))='TIMESHEET_PAYMENT'
        AND COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), expected_presentation_timesheets AS (
      SELECT DISTINCT (allocation.value->>'timesheet_id')::uuid AS timesheet_id
      FROM pg_temp.canonical_timesheet_presentation_state state
      CROSS JOIN LATERAL jsonb_array_elements(
        private.pay_workbench_presentation_allocation_expected_v1(to_jsonb(state))) allocation(value)
      WHERE state.candidate_id=v_bounded_build.candidate_id
    ), actual_occurrence AS (
      SELECT actual_line.timesheet_id,actual_line.line_identity,
        UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),'')) AS key_type,
        NULLIF(BTRIM(component.value->>'component_key_value'),'') AS key_value,
        NULLIF(BTRIM(component.value->>'physical_bucket_key'),'') AS physical_bucket_key,
        md5(jsonb_build_object(
          'builder_comparison_version',1,
          'timesheet_id',actual_line.timesheet_id::text,
          'source_family_key',NULLIF(BTRIM(component.value->>'source_family_key'),''),
          'component_key_type',UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),'')),
          'component_key_value',NULLIF(BTRIM(component.value->>'component_key_value'),''),
          'segment_id',NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),''),
          'segment_key',COALESCE(
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_key}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),'')),
          'segment_stable_key',NULLIF(BTRIM(
            component.value#>>'{source_basis_json,segment_stable_key}'),''),
          'work_date',NULLIF(BTRIM(COALESCE(component.value#>>'{source_basis_json,work_date}',
            component.value#>>'{source_basis_json,date}')),''),
          'ref_num',NULLIF(BTRIM(component.value#>>'{source_basis_json,ref_num}'),''),
          'additional_code',NULLIF(UPPER(BTRIM(
            component.value#>>'{source_basis_json,additional_code}')),''),
          'expense_code',NULLIF(UPPER(BTRIM(
            component.value#>>'{source_basis_json,expense_code}')),''),
          'adjustment_id',NULLIF(BTRIM(component.value#>>'{source_basis_json,adjustment_id}'),''),
          'bucket_code',UPPER(BTRIM(COALESCE(
            CASE WHEN UPPER(BTRIM(COALESCE(
                component.value#>>'{source_basis_json,component_fallback}','')))='WORKED_TIME_AMOUNT'
              THEN 'FIXED' END,
            NULLIF(component.value#>>'{source_basis_json,bucket_code}',''),
            CASE UPPER(BTRIM(component.value->>'component_key_type'))
              WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
              WHEN 'EXPENSE_CODE' THEN 'FIXED'
              WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
            END))),
          'source_units',CASE WHEN COALESCE(component.value->>'source_units','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_units')::numeric,6) END,
          'source_rate',CASE WHEN COALESCE(component.value->>'source_rate','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_rate')::numeric,6) END,
          'source_charge_rate',CASE WHEN COALESCE(component.value->>'source_charge_rate','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_charge_rate')::numeric,6) END,
          'source_pay_ex_vat',CASE WHEN COALESCE(component.value->>'source_pay_ex_vat','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_pay_ex_vat')::numeric,2) END,
          'source_charge_ex_vat',CASE WHEN COALESCE(component.value->>'source_charge_ex_vat','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_charge_ex_vat')::numeric,2) END,
          'source_pay_method',UPPER(NULLIF(BTRIM(component.value->>'source_pay_method'),'')),
          'target_pay_method',UPPER(NULLIF(BTRIM(
            component.value->>'current_target_pay_method'),'')))::text)
          AS builder_comparison_digest,
        CASE WHEN COALESCE(component.value->>'component_amount_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'component_amount_ex_vat')::numeric,2) END
          AS component_amount_ex_vat,
        CASE WHEN COALESCE(component.value->>'authoritative_truth_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'authoritative_truth_ex_vat')::numeric,2) END
          AS truth_ex_vat,
        CASE WHEN COALESCE(component.value->>'authoritative_baseline_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'authoritative_baseline_ex_vat')::numeric,2) END
          AS baseline_ex_vat,
        CASE WHEN COALESCE(component.value->>'authoritative_reserved_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'authoritative_reserved_ex_vat')::numeric,2) END
          AS reserved_ex_vat,
        CASE WHEN COALESCE(component.value->>'authoritative_outstanding_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'authoritative_outstanding_ex_vat')::numeric,2) END
          AS outstanding_ex_vat,
        NULLIF(BTRIM(component.value->>'physical_bucket_digest'),'') AS physical_bucket_digest,
        NULLIF(BTRIM(component.value->>'sealed_evidence_digest'),'') AS sealed_evidence_digest,
        NULLIF(BTRIM(component.value->>'financial_revision_digest'),'') AS financial_revision_digest,
        NULLIF(BTRIM(component.value->>'target_authority_digest'),'') AS target_authority_digest,
        NULLIF(BTRIM(component.value->>'conversion_context_digest'),'') AS conversion_context_digest
      FROM actual_lines actual_line
      CROSS JOIN LATERAL jsonb_array_elements(actual_line.components_json) component(value)
    ), conflicting_actual AS (
      SELECT timesheet_id,line_identity,physical_bucket_key
      FROM actual_occurrence
      GROUP BY timesheet_id,line_identity,physical_bucket_key
      HAVING physical_bucket_key IS NULL
        OR bool_or(key_type IS NULL OR key_value IS NULL OR
          builder_comparison_digest IS NULL OR physical_bucket_digest IS NULL OR
          sealed_evidence_digest IS NULL)
        OR count(*)>1
        OR count(DISTINCT jsonb_build_object('key_type',key_type,'key_value',key_value,
          'builder_comparison_digest',builder_comparison_digest,
          'component_amount_ex_vat',component_amount_ex_vat,'truth_ex_vat',truth_ex_vat,
          'baseline_ex_vat',baseline_ex_vat,'reserved_ex_vat',reserved_ex_vat,
          'outstanding_ex_vat',outstanding_ex_vat,
          'physical_bucket_digest',physical_bucket_digest,
          'sealed_evidence_digest',sealed_evidence_digest,
          'financial_revision_digest',financial_revision_digest,
          'target_authority_digest',target_authority_digest,
          'conversion_context_digest',conversion_context_digest))>1
    ), actual AS (
      -- Presentation splitting may repeat one identical physical component on
      -- several stable lines.  Collapse only after per-line duplicate and
      -- conflict checks have succeeded; never collapse DAY and NIGHT together.
      SELECT DISTINCT timesheet_id,key_type,key_value,physical_bucket_key,
        builder_comparison_digest,component_amount_ex_vat,truth_ex_vat,
        baseline_ex_vat,reserved_ex_vat,outstanding_ex_vat,
        physical_bucket_digest,sealed_evidence_digest,financial_revision_digest,
        target_authority_digest,conversion_context_digest
      FROM actual_occurrence
    ), expected_rendered AS (
      SELECT expected.* FROM expected
      JOIN expected_presentation_timesheets USING(timesheet_id)
    )
    SELECT 1 FROM conflicting_actual
    UNION ALL
    SELECT 1 FROM expected_rendered expected
      FULL OUTER JOIN actual USING(timesheet_id,key_type,key_value,physical_bucket_key)
    WHERE expected.timesheet_id IS NULL OR actual.timesheet_id IS NULL
       OR actual.builder_comparison_digest IS DISTINCT FROM expected.builder_comparison_digest
       OR actual.component_amount_ex_vat IS DISTINCT FROM expected.component_amount_ex_vat
       OR actual.truth_ex_vat IS DISTINCT FROM expected.truth_ex_vat
       OR actual.baseline_ex_vat IS DISTINCT FROM expected.baseline_ex_vat
       OR actual.reserved_ex_vat IS DISTINCT FROM expected.reserved_ex_vat
       OR actual.outstanding_ex_vat IS DISTINCT FROM expected.outstanding_ex_vat
       OR actual.physical_bucket_digest IS DISTINCT FROM expected.physical_bucket_digest
       OR actual.sealed_evidence_digest IS DISTINCT FROM expected.sealed_evidence_digest
       OR actual.financial_revision_digest IS DISTINCT FROM expected.financial_revision_digest
       OR actual.target_authority_digest IS DISTINCT FROM expected.target_authority_digest
       OR actual.conversion_context_digest IS DISTINCT FROM expected.conversion_context_digest
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_RATE_PHYSICAL_FENCE_MISMATCH' USING ERRCODE='P0001';
  END IF;

  v_canonical_render_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  IF v_slice_active THEN
    -- A28: earlier slices' staged lines are kept (private, unpublished). A first slice never has any.
    SELECT COALESCE(max(source_ordinal),0),count(*)::integer INTO v_slice_ordinal_base,v_slice_line_total
    FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=p_build_id;
    IF COALESCE((v_slice_plan->>'slices_completed')::integer,0)=0 AND v_slice_line_total>0 THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SLICE_STAGE_NOT_EMPTY' USING ERRCODE='23514';
    END IF;
    IF v_slice_line_total IS DISTINCT FROM COALESCE((v_slice_plan->>'staged_line_count')::integer,0) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SLICE_STAGE_MISMATCH' USING ERRCODE='23514';
    END IF;
    SELECT count(*) FILTER (WHERE owner.is_candidate_level AND NOT v_slice_final)::integer,
           count(*) FILTER (WHERE NOT owner.is_candidate_level AND owner.line_timesheet_id IS NOT NULL
             AND NOT (owner.line_timesheet_id=ANY(v_bounded_scope_ids))
             AND EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_scope other_scope
               WHERE other_scope.build_id=p_build_id AND other_scope.timesheet_id=owner.line_timesheet_id))::integer
    INTO v_slice_dropped_candidate_level,v_slice_dropped_other_slice
    FROM pg_temp.canonical_preview_lines line
    CROSS JOIN LATERAL (SELECT
      (COALESCE(line.line_json->>'preview_row_id','') LIKE 'finance:%'
        OR UPPER(COALESCE(line.line_json->>'line_type',''))='MANUAL_ADJUSTMENT_CARRY_FORWARD') AS is_candidate_level,
      CASE WHEN COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid END AS line_timesheet_id
    ) owner
    WHERE line.candidate_id=v_bounded_build.candidate_id;
  ELSE
  DELETE FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=p_build_id;
  END IF;
  v_bounded_canonical_stage_timestamp:=clock_timestamp();
  INSERT INTO private.banking_pay_workbench_canonical_stage_lines(
    build_id,source_ordinal,session_id,candidate_id,session_version,source_change_seq,
    source_build_run_id,timesheet_id,line_key,parent_line_key,split_suffix,section,
    source_row_json,economic_key_json,contract_json,pay_channel_scope,
    refresh_scope_kind,row_digest,stage_status,verified_at_utc,created_at_utc
  )
  SELECT p_build_id,
    v_slice_ordinal_base+row_number() OVER(ORDER BY public.pay_workbench_preview_section_from_line_json(line.line_json),
      COALESCE(line.line_json->>'preview_row_id',line.line_json->>'line_id',
        line.line_json->>'case_key',md5(line.line_json::text)))::bigint,
    v_bounded_build.session_id,v_bounded_build.candidate_id,v_bounded_build.session_version,
    v_bounded_build.source_change_seq,v_bounded_build.source_build_run_id,
    CASE WHEN COALESCE(line.line_json->>'real_business_timesheet_id',
      line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN COALESCE(line.line_json->>'real_business_timesheet_id',
        line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid ELSE NULL END,
    COALESCE(NULLIF(btrim(line.line_json->>'preview_row_id'),''),
      NULLIF(btrim(line.line_json->>'line_id'),''),NULLIF(btrim(line.line_json->>'case_key'),''),
      md5(line.line_json::text)),
    NULLIF(btrim(line.line_json->>'parent_line_key'),''),
    NULLIF(btrim(line.line_json->>'split_suffix'),''),
    public.pay_workbench_preview_section_from_line_json(line.line_json),line.line_json,
    CASE WHEN jsonb_typeof(line.line_json->'economic_key')='object'
      THEN line.line_json->'economic_key' ELSE '{}'::jsonb END,
    CASE WHEN jsonb_typeof(line.line_json->'contract_json')='object'
      THEN line.line_json->'contract_json'
      WHEN jsonb_typeof(line.line_json->'contract')='object' THEN line.line_json->'contract'
      ELSE '{}'::jsonb END,
    v_scope,'BOUNDED_ECONOMIC_BUILD',md5(line.line_json::text),'VERIFIED',
    v_bounded_canonical_stage_timestamp,v_bounded_canonical_stage_timestamp
  FROM pg_temp.canonical_preview_lines line
  WHERE line.candidate_id=v_bounded_build.candidate_id
    -- A28: a slice stages only what it owns. Timesheet lines belong to the slice of their Timesheet; the
    -- Candidate-level balance lines (finance cases, carry-forwards) and any line outside the build scope belong
    -- to the final slice, which sees the whole Candidate's headroom.
    AND (NOT v_slice_active OR (
      CASE WHEN COALESCE(line.line_json->>'preview_row_id','') LIKE 'finance:%'
             OR UPPER(COALESCE(line.line_json->>'line_type',''))='MANUAL_ADJUSTMENT_CARRY_FORWARD' THEN v_slice_final
        WHEN COALESCE(line.line_json->>'real_business_timesheet_id',
            line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
            !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_slice_final
        WHEN COALESCE(line.line_json->>'real_business_timesheet_id',
            line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid
            =ANY(v_bounded_scope_ids) THEN true
        WHEN EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_scope other_scope
            WHERE other_scope.build_id=p_build_id
              AND other_scope.timesheet_id=COALESCE(line.line_json->>'real_business_timesheet_id',
                line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid) THEN false
        ELSE v_slice_final END));
  GET DIAGNOSTICS v_slice_kept = ROW_COUNT;

  IF v_slice_active AND v_slice_final THEN
    -- A28: restore exactly the unsliced staging order over every staged line (two collision-free passes).
    SELECT COALESCE(max(source_ordinal),0) INTO v_slice_max_ordinal
    FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=p_build_id;
    WITH ordered AS (
      SELECT stage_line.source_ordinal AS old_ordinal,
        row_number() OVER(ORDER BY public.pay_workbench_preview_section_from_line_json(stage_line.source_row_json),
          COALESCE(stage_line.source_row_json->>'preview_row_id',stage_line.source_row_json->>'line_id',
            stage_line.source_row_json->>'case_key',md5(stage_line.source_row_json::text)),
          stage_line.line_key,stage_line.timesheet_id NULLS FIRST)::bigint AS new_ordinal
      FROM private.banking_pay_workbench_canonical_stage_lines stage_line
      WHERE stage_line.build_id=p_build_id
    )
    UPDATE private.banking_pay_workbench_canonical_stage_lines stage_line
    SET source_ordinal=v_slice_max_ordinal+ordered.new_ordinal
    FROM ordered
    WHERE stage_line.build_id=p_build_id AND stage_line.source_ordinal=ordered.old_ordinal;
    UPDATE private.banking_pay_workbench_canonical_stage_lines
    SET source_ordinal=source_ordinal-v_slice_max_ordinal
    WHERE build_id=p_build_id;
  END IF;

  IF v_slice_active AND NOT v_slice_final THEN
    -- A28: close a non-final slice. Its lines stay privately staged; nothing is published; the build returns
    -- to READY_FOR_RECONCILIATION for the next slice's own bounded capture and execute. The slice's additive
    -- recovery headroom is carried to the final slice.
    IF to_regclass('pg_temp.candidate_authoritative_recovery_headroom') IS NOT NULL THEN
      EXECUTE 'SELECT COALESCE(sum(authoritative_recovery_headroom_ex),0) FROM pg_temp.candidate_authoritative_recovery_headroom WHERE candidate_id=$1'
        INTO v_slice_recovery_headroom USING v_bounded_build.candidate_id;
    END IF;
    IF to_regclass('pg_temp.timesheet_allocation_component_lines') IS NOT NULL THEN
      EXECUTE 'SELECT COALESCE(round(sum(amount_ex_vat),2),0) FROM pg_temp.timesheet_allocation_component_lines WHERE candidate_id=$1 AND amount_ex_vat>0'
        INTO v_slice_ordinary_headroom USING v_bounded_build.candidate_id;
    END IF;
    SELECT count(*)::integer INTO v_slice_line_total
    FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=p_build_id;
    UPDATE private.banking_pay_workbench_economic_builds
    SET status='READY_FOR_RECONCILIATION',
        attestation_json=COALESCE(attestation_json,'{}'::jsonb)||jsonb_build_object(
          'effect_plan_sealed',false,
          'reconcile_slicing',(v_slice_plan-'current')||jsonb_build_object(
            'next_after_unit_ordinal',(v_slice->>'through_unit_ordinal')::bigint,
            'slices_completed',COALESCE((v_slice_plan->>'slices_completed')::integer,0)+1,
            'reconciled_timesheet_count',COALESCE((v_slice_plan->>'reconciled_timesheet_count')::integer,0)+v_bounded_scope_count,
            'prior_recovery_headroom_ex',ROUND(COALESCE((v_slice_plan->>'prior_recovery_headroom_ex')::numeric,0)+COALESCE(v_slice_recovery_headroom,0),2),
            'prior_ordinary_positive_headroom_ex',ROUND(COALESCE((v_slice_plan->>'prior_ordinary_positive_headroom_ex')::numeric,0)+COALESCE(v_slice_ordinary_headroom,0),2),
            'observed_finance_effect_count',COALESCE((v_slice_plan->>'observed_finance_effect_count')::integer,0)+v_observed_effect_count,
            'staged_line_count',v_slice_line_total,
            'last_slice',jsonb_build_object('index',v_slice->'index','timesheet_count',v_bounded_scope_count,
              'unit_count',v_slice->'unit_count','staged_lines',v_slice_kept,
              'held_for_final_slice',v_slice_dropped_candidate_level,'owned_by_other_slice',v_slice_dropped_other_slice,
              'recovery_headroom_ex',COALESCE(v_slice_recovery_headroom,0),
              'ordinary_positive_headroom_ex',COALESCE(v_slice_ordinary_headroom,0),
              'observed_finance_effect_count',v_observed_effect_count,
              'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer,
              'case_workspace_ms',v_case_workspace_ms,'finance_apply_ms',v_finance_apply_ms,
              'canonical_render_ms',v_canonical_render_ms))),
        updated_at_utc=clock_timestamp()
    WHERE id=p_build_id AND status='RECONCILING' AND private_stage='RECONCILE_EXECUTE';
    IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001'; END IF;
    PERFORM set_config('cloudtms.pay_workbench_reconcile_slice_v1','',true);
    RETURN jsonb_build_object(
      'ok',true,'public_result_json',v_public_result_json,
      'internal_result_json',jsonb_build_object('build_id',p_build_id,'attempt_id',p_attempt_id,
        'slice_index',v_slice->'index','slice_final',false,'scope_timesheet_count',v_bounded_scope_count,
        'staged_lines',v_slice_kept,'total_reconcile_ms',
        FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer),
      'build_id',p_build_id,'attempt_id',p_attempt_id,'slice_index',v_slice->'index','slice_final',false,
      'scope_timesheet_count',v_bounded_scope_count);
  END IF;

  SELECT count(*)::integer,
         md5(COALESCE(string_agg(row_digest,'' ORDER BY source_ordinal),''))
  INTO v_bounded_canonical_count,v_bounded_canonical_digest
  FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=p_build_id;

  SELECT md5(jsonb_build_object(
    'candidate_id',v_bounded_build.candidate_id,'case_count',count(*),
    'case_digest',md5(COALESCE(string_agg(md5(to_jsonb(case_row)::text),'' ORDER BY case_row.id),''))
  )::text)
  INTO v_bounded_post_sync_digest
  FROM public.pay_advances case_row WHERE case_row.candidate_id=v_bounded_build.candidate_id;

  v_canonical_stage_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;

  UPDATE private.banking_pay_workbench_economic_builds
  SET status='RECONCILED',private_stage='SOURCE_PUBLISH',fact_count=v_bounded_fact_count,
      pre_sync_digest=v_bounded_pre_sync_digest,post_sync_digest=v_bounded_post_sync_digest,
      canonical_count=v_bounded_canonical_count,canonical_digest=v_bounded_canonical_digest,
      attestation_json=COALESCE(attestation_json,'{}'::jsonb)||jsonb_build_object(
        'version',1,'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH',
        'build_id',p_build_id,'attempt_id',p_attempt_id,'scope_count',v_slice_total_scope_count,
        'fact_count',v_bounded_fact_count,'canonical_count',v_bounded_canonical_count,
        'effect_plan_sealed',true,
        'effect_plan_count',COALESCE((v_bounded_build.attestation_json->>'effect_plan_count')::integer,0),
        'effect_plan_digest',v_bounded_build.attestation_json->>'effect_plan_digest',
        'effect_plan_created_at_utc',v_bounded_build.attestation_json->'effect_plan_created_at_utc',
        'observed_finance_effect_count',v_observed_effect_count,
        'observed_finance_effect_digest',v_observed_effect_digest,
        'economic_component_digest',v_bounded_economic_component_digest,
        'presentation_allocation_digest',v_bounded_presentation_allocation_digest,
        'pre_sync_digest',v_bounded_pre_sync_digest,'post_sync_digest',v_bounded_post_sync_digest,
        'canonical_digest',v_bounded_canonical_digest,
        'reconcile_slicing',CASE WHEN v_slice_active THEN (v_slice_plan-'current')||jsonb_build_object(
          'slices_completed',COALESCE((v_slice_plan->>'slices_completed')::integer,0)+1,
          'reconciled_timesheet_count',COALESCE((v_slice_plan->>'reconciled_timesheet_count')::integer,0)+v_bounded_scope_count,
          'observed_finance_effect_count',COALESCE((v_slice_plan->>'observed_finance_effect_count')::integer,0)+v_observed_effect_count,
          'staged_line_count',v_bounded_canonical_count,'completed_at_utc',clock_timestamp(),
          'last_slice',jsonb_build_object('index',v_slice->'index','timesheet_count',v_bounded_scope_count,
            'unit_count',v_slice->'unit_count','staged_lines',v_slice_kept,'final',true,
            'observed_finance_effect_count',v_observed_effect_count,
            'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer))
          ELSE NULL::jsonb END,
        'reconcile_execute_timing_json',jsonb_build_object(
          'execution_profile_version',v_execution_profile_version,
      'reconciliation_optimization_version',v_reconciliation_optimization_version,
          'workspace_cache_ms',v_workspace_cache_ms,
          'freshness_set_ms',v_freshness_set_ms,
          'authoritative_components_ms',v_authoritative_components_ms,
          'preflight_setup_ms',v_preflight_setup_ms,
          'correction_residuals_ms',v_correction_residuals_ms,
          'authority_validation_ms',v_authority_validation_ms,
          'component_assembly_ms',v_component_assembly_ms,
          'preview_workspace_ms',v_preview_workspace_ms,
          'preview_collect_ms',v_preview_collect_ms,
          'preview_canonical_ms',v_preview_canonical_ms,
          'preview_summary_ms',v_preview_summary_ms,
          'case_workspace_ms',v_case_workspace_ms,
          'finance_apply_ms',v_finance_apply_ms,
          'post_freshness_ms',v_post_freshness_ms,
          'canonical_render_ms',v_canonical_render_ms,
          'canonical_stage_ms',v_canonical_stage_ms,
          'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer)),
      reconciled_at_utc=clock_timestamp(),publication_cursor_json=jsonb_build_object(
        'cursor_kind','SOURCE_PUBLISH','cursor_version',1,'build_id',p_build_id,
        'candidate_id',v_bounded_build.candidate_id,'canonical_count',v_bounded_canonical_count,
        'canonical_digest',v_bounded_canonical_digest),updated_at_utc=clock_timestamp()
  WHERE id=p_build_id AND status='RECONCILING' AND private_stage='RECONCILE_EXECUTE';
  IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001'; END IF;
  PERFORM set_config('cloudtms.pay_workbench_reconcile_slice_v1','',true); /* A28 */

  RETURN jsonb_build_object(
    'ok',true,'public_result_json',v_public_result_json,
    'internal_result_json',jsonb_build_object(
      'build_id',p_build_id,'attempt_id',p_attempt_id,'scope_timesheet_count',v_bounded_scope_count,
      'fact_count',v_bounded_fact_count,'canonical_stage_count',v_bounded_canonical_count,
      'economic_component_digest',v_bounded_economic_component_digest,
      'presentation_allocation_digest',v_bounded_presentation_allocation_digest,
      'pre_sync_digest',v_bounded_pre_sync_digest,'post_sync_digest',v_bounded_post_sync_digest,
      'canonical_digest',v_bounded_canonical_digest,
      'execution_profile_version',v_execution_profile_version,
      'reconciliation_optimization_version',v_reconciliation_optimization_version,
      'freshness_set_ms',v_freshness_set_ms,
      'workspace_cache_ms',v_workspace_cache_ms,
      'authoritative_components_ms',v_authoritative_components_ms,
      'preflight_setup_ms',v_preflight_setup_ms,
      'correction_residuals_ms',v_correction_residuals_ms,
      'authority_validation_ms',v_authority_validation_ms,
      'component_assembly_ms',v_component_assembly_ms,
      'preview_workspace_ms',v_preview_workspace_ms,
      'preview_collect_ms',v_preview_collect_ms,
      'preview_canonical_ms',v_preview_canonical_ms,
      'preview_summary_ms',v_preview_summary_ms,
      'case_workspace_ms',v_case_workspace_ms,
      'finance_apply_ms',v_finance_apply_ms,
      'post_freshness_ms',v_post_freshness_ms,
      'canonical_render_ms',v_canonical_render_ms,
      'canonical_stage_ms',v_canonical_stage_ms,
      'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer),
    'build_id',p_build_id,'attempt_id',p_attempt_id,
    'scope_timesheet_count',v_slice_total_scope_count,
    'slice_final',CASE WHEN v_slice_active THEN true ELSE NULL END,
    'canonical_stage_count',v_bounded_canonical_count,
    'pre_sync_digest',v_bounded_pre_sync_digest,'post_sync_digest',v_bounded_post_sync_digest,
    'canonical_digest',v_bounded_canonical_digest
  );
exception
  when others then
    GET STACKED DIAGNOSTICS
      v_exception_detail = PG_EXCEPTION_DETAIL,
      v_exception_context = PG_EXCEPTION_CONTEXT;
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_ERROR',
      jsonb_build_object(
        'pay_date', p_pay_date,
        'week_ending_cutoff', p_week_ending_cutoff,
        'pay_channel_scope', p_pay_channel_scope,
        'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM,
        'exception_detail', NULLIF(v_exception_detail, ''),
        'exception_context', NULLIF(v_exception_context, '')
      ),
      'pay_sync_overpayments',
      COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    IF SQLSTATE = '23514'
       AND SQLERRM = 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH %',
        jsonb_build_object(
          'source',COALESCE(
            substring(v_exception_context FROM 'PL/pgSQL function [^\n]+'),
            'UNKNOWN_EFFECT_ATTESTATION_SOURCE'),
          'has_detail',NULLIF(v_exception_detail,'') IS NOT NULL
        )::text
        USING ERRCODE='23514';
    END IF;
    RAISE;
end;
$function$
;

-- public.pay_workbench_dirty_event_enqueue from supabase/repeatable/26092026_0203_banking_pay_stage2_workbench_draft_v1.sql; definition SHA-256 f1897108d9fd6d04cede2de65f9a426ea9ef1fe4365975e7219de94c8fba3d9e.
CREATE OR REPLACE FUNCTION public.pay_workbench_dirty_event_enqueue(p_job_type text, p_scope_kind text, p_scope_id text, p_candidate_id uuid DEFAULT NULL::uuid, p_targeted_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_linked_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_payload_json jsonb DEFAULT '{}'::jsonb, p_reason text DEFAULT NULL::text, p_priority integer DEFAULT '-1000'::integer, p_run_at_utc timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_job_type text := UPPER(BTRIM(COALESCE(p_job_type, '')));
  v_scope_kind text := UPPER(BTRIM(COALESCE(p_scope_kind, '')));
  v_scope_id text := NULLIF(BTRIM(COALESCE(p_scope_id, '')), '');
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_targeted_key_part text := 'ALL';
  v_dedupe_key text;
  v_reason text := NULLIF(BTRIM(COALESCE(p_reason, '')), '');
  v_payload_json jsonb := '{}'::jsonb;
  v_incoming_payload jsonb := '{}'::jsonb;
  v_latest_source_change_seq bigint := 0;
  v_job_id uuid;
  v_job_status text;
  v_job_payload jsonb;
  v_priority integer := COALESCE(p_priority, -1000);
  v_run_at_utc timestamptz := COALESCE(p_run_at_utc, v_now);
  v_scope_uuid uuid := NULL::uuid;
  v_scope_invalidation_result jsonb := '{}'::jsonb;
  v_scope_change_tx_token uuid := NULL::uuid;
  -- A15 (PRE-EXISTING SB02 Workbench fix): bounded active-dedupe identity.
  v_full_dedupe_key text := NULL::text;
  v_dedupe_is_digest boolean := false;
BEGIN
  IF v_job_type NOT IN (
    'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
    'CONTRACT_CLIENT_DIRTY_FANOUT'
  ) THEN
    RAISE EXCEPTION 'Unsupported Banking Pay dirty event job_type: %', p_job_type
      USING ERRCODE = '22023';
  END IF;

  IF v_scope_kind = '' OR v_scope_id IS NULL THEN
    RAISE EXCEPTION 'Banking Pay dirty event requires scope_kind and scope_id'
      USING ERRCODE = '22023';
  END IF;

  IF v_scope_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_scope_uuid := v_scope_id::uuid;
  END IF;

  IF v_job_type IN ('WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
     AND v_scope_uuid IS NULL THEN
    RAISE EXCEPTION 'Banking Pay dirty event scope_id must be a UUID for job_type %, scope_kind %, scope_id %', v_job_type, v_scope_kind, v_scope_id
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT target_id ORDER BY target_id), ARRAY[]::uuid[])
  INTO v_targeted_timesheet_ids
  FROM unnest(COALESCE(p_targeted_timesheet_ids, ARRAY[]::uuid[])) AS target_id
  WHERE target_id IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT linked_id ORDER BY linked_id), ARRAY[]::uuid[])
  INTO v_linked_timesheet_ids
  FROM unnest(COALESCE(p_linked_timesheet_ids, ARRAY[]::uuid[])) AS linked_id
  WHERE linked_id IS NOT NULL;

  -- The central invalidator owns durable candidate/timesheet economic state.
  -- Its guarded callback into this function preserves the installed queue
  -- envelope without recursion or a second queue authority.
  IF v_job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
     AND p_candidate_id IS NOT NULL
     AND COALESCE(current_setting('cloudtms.bpay_scope_invalidator_active',true),'')<>'true' THEN
    IF COALESCE(p_payload_json->>'scope_change_tx_token','')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_scope_change_tx_token:=(p_payload_json->>'scope_change_tx_token')::uuid;
    END IF;
    v_scope_invalidation_result:=private.pay_workbench_scope_invalidate_v1(
      CASE WHEN cardinality(v_targeted_timesheet_ids)=0 THEN ARRAY[p_candidate_id]
        ELSE array_fill(p_candidate_id,ARRAY[cardinality(v_targeted_timesheet_ids)]) END,
      CASE WHEN cardinality(v_targeted_timesheet_ids)=0 THEN ARRAY[NULL::uuid]
        ELSE v_targeted_timesheet_ids END,
      COALESCE(v_reason,'DIRTY_TRIGGER:'||v_scope_kind),
      v_scope_change_tx_token,
      COALESCE(p_payload_json,'{}'::jsonb)||jsonb_build_object('skip_candidate_job_enqueue',true)
    );
  END IF;

  IF COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN
    v_targeted_key_part := array_to_string(v_targeted_timesheet_ids, ',');
  END IF;

  IF p_candidate_id IS NOT NULL THEN
    PERFORM public._change_bump('pay_candidate:' || p_candidate_id::text);

    SELECT COALESCE(change_counter.seq, 0)
    INTO v_latest_source_change_seq
    FROM public.app_change_counters AS change_counter
    WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;
  END IF;

  v_latest_source_change_seq := GREATEST(
    COALESCE(v_latest_source_change_seq, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'latest_source_change_seq', '') ~ '^\d+$' THEN (p_payload_json->>'latest_source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'source_change_seq', '') ~ '^\d+$' THEN (p_payload_json->>'source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'source_change_sequence', '') ~ '^\d+$' THEN (p_payload_json->>'source_change_sequence')::bigint END, 0)
  );

  IF v_reason IS NULL THEN
    v_reason := 'DIRTY_TRIGGER:' || v_scope_kind;
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_DIRTY_APPLY' THEN
    IF p_candidate_id IS NULL THEN
      RAISE EXCEPTION 'Candidate dirty apply job requires p_candidate_id'
        USING ERRCODE = '22023';
    END IF;
    v_dedupe_key := 'DIRTY_TRIGGER:WORKBENCH_CANDIDATE_DIRTY_APPLY:CANDIDATE:'
      || p_candidate_id::text
      || ':TIMESHEETS:' || v_targeted_key_part;
    -- A15: the full key names every targeted Timesheet, so above about 69
    -- Timesheets it cannot be stored in the active-dedupe B-tree index
    -- (2,704-byte / 8,191-byte limits) and the whole business statement fails.
    -- Keys up to 2,048 bytes (<=52 Timesheets) keep their exact historical
    -- text.  A longer key is replaced by a fixed-size SHA-256 of the SAME
    -- canonical, sorted, de-duplicated Timesheet list, so equal scopes still
    -- share one key and different scopes still get different keys.  The full
    -- list stays in the unindexed payload_json.targeted_timesheet_ids that the
    -- consumer already reads; the key is never parsed.
    IF pg_catalog.octet_length(v_dedupe_key) > 2048 THEN
      v_full_dedupe_key := v_dedupe_key;
      v_dedupe_key := 'DIRTY_TRIGGER:WORKBENCH_CANDIDATE_DIRTY_APPLY:CANDIDATE:'
        || p_candidate_id::text
        || ':TIMESHEETS:SHA256:'
        || pg_catalog.encode(
             pg_catalog.sha256(pg_catalog.convert_to(v_targeted_key_part, 'UTF8')),
             'hex'
           )
        || ':COUNT:' || cardinality(v_targeted_timesheet_ids)::text;
      v_dedupe_is_digest := true;
      -- Transition exactness: a job queued before A15 under the full key
      -- (53..69 Timesheets were storable) keeps absorbing the same scope.
      IF EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_jobs AS legacy_job
        WHERE legacy_job.dedupe_key = v_full_dedupe_key
          AND legacy_job.status IN ('QUEUED', 'RUNNING')
      ) THEN
        v_dedupe_key := v_full_dedupe_key;
        v_dedupe_is_digest := false;
      END IF;
    END IF;
  ELSIF v_job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY' THEN
    v_dedupe_key := 'DIRTY_TRIGGER:WORKBENCH_FINANCE_CASE_DIRTY_APPLY:' || v_scope_kind || ':' || v_scope_id;
  ELSE
    v_dedupe_key := 'DIRTY_TRIGGER:CONTRACT_CLIENT_DIRTY_FANOUT:' || v_scope_kind || ':' || v_scope_id;
  END IF;

  v_incoming_payload := jsonb_strip_nulls(
    COALESCE(p_payload_json, '{}'::jsonb)
    || jsonb_build_object(
      'job_type', v_job_type,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'priority_class', 'DIRTY_TRIGGER_PRIORITY',
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'finance_case_id', CASE WHEN v_job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'contract_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'CONTRACT' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'client_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'CLIENT' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'umbrella_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'UMBRELLA' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(to_jsonb(v_linked_timesheet_ids), '[]'::jsonb),
      'reason', v_reason,
      'reason_latest', v_reason,
      'reason_count', 1,
      'trigger_source', COALESCE(p_payload_json->>'trigger_source', p_payload_json->>'trigger_table', v_scope_kind),
      'latest_source_change_seq', v_latest_source_change_seq,
      'source_change_seq', v_latest_source_change_seq,
      'source_change_sequence', v_latest_source_change_seq,
      'latest_event_at_utc', v_now::text,
      'event_at_utc', v_now::text,
      'rerun_required', false,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'policy_x_dirtying_only', true,
      'economic_truth_mutation_allowed', false
    )
  );

  v_payload_json := public._pay_workbench_dirty_payload_merge('{}'::jsonb, v_incoming_payload);

  INSERT INTO public.banking_pay_workbench_jobs AS queued_job (
    job_type,
    status,
    priority,
    run_at_utc,
    attempt_count,
    max_attempts,
    dedupe_key,
    snapshot_run_id,
    session_id,
    candidate_id,
    payload_json,
    created_at_utc,
    updated_at_utc,
    started_at_utc,
    completed_at_utc,
    failed_at_utc,
    last_error_json
  )
  VALUES (
    v_job_type,
    'QUEUED',
    v_priority,
    v_run_at_utc,
    0,
    8,
    v_dedupe_key,
    NULL,
    NULL,
    CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DIRTY_APPLY' THEN p_candidate_id ELSE NULL::uuid END,
    v_payload_json,
    v_now,
    v_now,
    NULL,
    NULL,
    NULL,
    NULL
  )
  ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
  DO UPDATE
  SET priority = LEAST(queued_job.priority, EXCLUDED.priority),
      run_at_utc = LEAST(queued_job.run_at_utc, EXCLUDED.run_at_utc),
      updated_at_utc = v_now,
      failed_at_utc = CASE WHEN queued_job.status = 'QUEUED' THEN NULL ELSE queued_job.failed_at_utc END,
      last_error_json = CASE WHEN queued_job.status = 'QUEUED' THEN NULL::jsonb ELSE queued_job.last_error_json END,
      payload_json = public._pay_workbench_dirty_payload_merge(
        COALESCE(queued_job.payload_json, '{}'::jsonb),
        COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
        || CASE
             WHEN queued_job.status = 'RUNNING' THEN jsonb_build_object('rerun_required', true)
             ELSE '{}'::jsonb
           END
      )
  -- A15: a digest key may only coalesce into a job that already covers every
  -- Timesheet of the incoming canonical scope (the durable targeted list only
  -- grows by union).  Anything else would be a digest collision: refuse it.
  WHERE v_dedupe_is_digest IS NOT TRUE
     OR NOT EXISTS (
       SELECT incoming_id.value::text
       FROM pg_catalog.unnest(v_targeted_timesheet_ids) AS incoming_id(value)
       EXCEPT
       SELECT covered_id.value
       FROM pg_catalog.jsonb_array_elements_text(
         CASE WHEN pg_catalog.jsonb_typeof(queued_job.payload_json->'targeted_timesheet_ids') = 'array'
           THEN queued_job.payload_json->'targeted_timesheet_ids'
           ELSE '[]'::jsonb END
       ) AS covered_id(value)
     )
  RETURNING queued_job.id, queued_job.status, queued_job.payload_json
  INTO v_job_id, v_job_status, v_job_payload;

  IF v_job_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_DEDUPE_DIGEST_SCOPE_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_DEDUPE_DIGEST_SCOPE_MISMATCH',
              'dedupe_key', v_dedupe_key,
              'candidate_id', p_candidate_id,
              'targeted_timesheet_count', cardinality(v_targeted_timesheet_ids)
            )::text;
  END IF;

  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    v_scope_id,
    jsonb_build_object(
      'function_name', 'pay_workbench_dirty_event_enqueue',
      'stage', CASE WHEN v_job_status = 'RUNNING' THEN 'dirty_enqueue_coalesced_existing_running' ELSE 'dirty_enqueue_inserted_or_coalesced_queued' END,
      'job_id', v_job_id::text,
      'job_type', v_job_type,
      'dedupe_key', v_dedupe_key,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'priority', v_priority,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id,
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
      'latest_source_change_seq', v_latest_source_change_seq,
      'rerun_required', COALESCE((v_job_payload->>'rerun_required')::boolean, false)
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', v_job_type,
    'status', v_job_status,
    'dedupe_key', v_dedupe_key,
    'queue_class', 'DIRTY_TRIGGER_PRIORITY',
    'priority', v_priority,
    'scope_kind', v_scope_kind,
    'scope_id', v_scope_id,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
    'latest_source_change_seq', v_latest_source_change_seq,
    'rerun_required', COALESCE((v_job_payload->>'rerun_required')::boolean, false)
  );
END;
$function$;

-- public.pay_workbench_mark_candidate_dirty from supabase/repeatable/26092026_0203_banking_pay_stage2_workbench_draft_v1.sql; definition SHA-256 ca88d40fca88c66261f15c3764a341284fd8c64ecfd82d5c77c4fdc5c770c26f.
CREATE OR REPLACE FUNCTION public.pay_workbench_mark_candidate_dirty()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_now timestamptz := clock_timestamp();
  v_trigger_table text := lower(TG_TABLE_NAME);
  v_new_row jsonb := '{}'::jsonb;
  v_old_row jsonb := '{}'::jsonb;
  v_previous_tsfin_row jsonb := '{}'::jsonb;
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_id uuid;
  v_old_timesheet_id uuid := NULL::uuid;
  v_new_timesheet_id uuid := NULL::uuid;
  v_old_contract_id uuid := NULL::uuid;
  v_new_contract_id uuid := NULL::uuid;
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_old_payment_eligible boolean := false;
  v_new_payment_eligible boolean := false;
  v_authorise_boundary_changed boolean := false;
  v_authorise_boundary_is_authorise boolean := false;
  v_authorise_boundary_is_unauthorise boolean := false;
  v_archive_boundary_changed boolean := false;
  v_archive_boundary_is_archive boolean := false;
  v_archive_boundary_is_unarchive boolean := false;
  v_material_live_source_changed boolean := false;
  v_tsfin_payability_state_changed boolean := false;
  v_timesheet_pay_state_settlement_changed boolean := false;
  v_timesheet_pay_state_summary_changed boolean := false;
  v_timesheet_pay_state_bookkeeping_ignored boolean := false;
  v_timesheet_pay_state_noop_ignored boolean := false;
  v_timesheet_pay_state_routing_reason text := NULL::text;
  v_tsfin_insert_authorise_like boolean := false;
  v_tsfin_insert_not_coalesced_reason text := NULL::text;
  v_tsfin_insert_coalesced_job_id uuid := NULL::uuid;
  v_tsfin_insert_coalesced_projection_run_id uuid := NULL::uuid;
  v_tsfin_insert_coalesced_session_id uuid := NULL::uuid;
  v_tsfin_insert_coalesced_source_change_seq bigint := NULL::bigint;
  v_lifecycle_context text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.lifecycle_mutation_context', true), '')), '');
  v_effective_lifecycle_context text := NULL::text;
  v_lifecycle_dedupe_keys text := '';
  v_lifecycle_dedupe_token text := '';
  v_explicit_banking_pay_action boolean := false;
  v_banking_pay_dirty_required boolean := false;
  v_ordinary_timesheet_edit_save_no_dirty boolean := false;
  v_entity_kind_old text := '';
  v_entity_kind_new text := '';
  v_umbrella_id_old uuid := NULL::uuid;
  v_umbrella_id_new uuid := NULL::uuid;
  v_scope_id text;
  v_reason text;
  v_payload_json jsonb := '{}'::jsonb;
  v_enqueue_result jsonb := '{}'::jsonb;
  v_jobs_queued integer := 0;
  v_candidate_route_change boolean := false;
  v_route_source_method text := NULL::text;
  v_route_target_method text := NULL::text;
  v_route_operation_id text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_operation_id', true), '')), '');
  v_route_actor_user_id text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_actor_user_id', true), '')), '');
  v_route_reason text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_reason', true), '')), '');
  v_route_scope_result jsonb := '{}'::jsonb;
  v_route_authoritative_sessions jsonb := '[]'::jsonb;
  v_route_replaced_source_session_ids jsonb := '[]'::jsonb;
  v_route_target_details jsonb := '[]'::jsonb;
  v_route_authorised_timesheet_ids jsonb := '[]'::jsonb;
  v_route_active_advance_timesheet_ids jsonb := '[]'::jsonb;
  v_route_retained_finance_timesheet_ids jsonb := '[]'::jsonb;
  v_route_authorised_timesheet_count integer := 0;
  v_route_active_advance_timesheet_count integer := 0;
  v_route_retained_finance_timesheet_count integer := 0;
  v_route_source_target_mismatch_count integer := 0;
  v_route_exact_scope boolean := false;
  v_route_coverage_complete boolean := false;
  v_route_targeted_scope_is_empty boolean := false;
  v_route_job_id uuid := NULL::uuid;
  v_route_job_status text := NULL::text;
  v_route_job_source_change_seq bigint := 0;
  v_route_dedupe_key text := NULL::text;
  v_internal_build_token uuid := NULL::uuid;
  v_internal_candidate_id uuid := NULL::uuid;
  v_internal_source_id uuid := NULL::uuid;
  v_internal_timesheet_id uuid := NULL::uuid;
  v_internal_logical_source_id uuid := NULL::uuid;
  v_internal_before_digest text := NULL::text;
  v_internal_after_digest text := NULL::text;
  v_expected_match_count integer := 0;
  v_delete_owner_candidate_id uuid := NULL::uuid;
  v_delete_context regclass := pg_catalog.to_regclass('pg_temp._bpay_candidate_delete_context_v1');
  v_delete_context_suppressed boolean := false;
  v_effect_capture_mode boolean := lower(COALESCE(current_setting('cloudtms.pay_workbench_effect_capture_mode',true),''))='capture';
BEGIN
  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    NULL::text,
    jsonb_build_object(
      'function_name', 'pay_workbench_mark_candidate_dirty',
      'stage', 'entry',
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'mutation_context', v_lifecycle_context,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
    )
  );

  IF TG_OP <> 'DELETE' THEN
    v_new_row := to_jsonb(NEW);
  END IF;
  IF TG_OP <> 'INSERT' THEN
    v_old_row := to_jsonb(OLD);
  END IF;


  IF TG_OP='DELETE' AND v_delete_context IS NOT NULL THEN
    IF v_trigger_table='candidates' AND NULLIF(v_old_row->>'id','')~*v_uuid_re THEN
      v_delete_owner_candidate_id:=(v_old_row->>'id')::uuid;
    ELSIF NULLIF(v_old_row->>'candidate_id','')~*v_uuid_re THEN
      v_delete_owner_candidate_id:=(v_old_row->>'candidate_id')::uuid;
    ELSIF NULLIF(COALESCE(v_old_row->>'timesheet_id',v_old_row->>'linked_timesheet_id'),'')~*v_uuid_re THEN
      SELECT COALESCE(
        financial.candidate_id,
        contract_row.candidate_id,
        deleted_timesheet_contract.candidate_id
      )
      INTO v_delete_owner_candidate_id
      FROM (SELECT COALESCE(NULLIF(v_old_row->>'timesheet_id','')::uuid,
             NULLIF(v_old_row->>'linked_timesheet_id','')::uuid) AS timesheet_id) owner_key
      LEFT JOIN public.timesheets_financials financial
        ON financial.timesheet_id=owner_key.timesheet_id AND financial.is_current
      LEFT JOIN public.timesheets timesheet_row ON timesheet_row.timesheet_id=owner_key.timesheet_id
      LEFT JOIN public.contracts contract_row ON contract_row.id=timesheet_row.contract_id
      LEFT JOIN public.contracts deleted_timesheet_contract
        ON deleted_timesheet_contract.id=NULLIF(v_old_row->>'contract_id','')::uuid
      LIMIT 1;
    ELSIF NULLIF(v_old_row->>'contract_id','')~*v_uuid_re THEN
      SELECT contract_row.candidate_id INTO v_delete_owner_candidate_id
      FROM public.contracts contract_row WHERE contract_row.id=(v_old_row->>'contract_id')::uuid;
    ELSIF NULLIF(v_old_row->>'finance_case_id','')~*v_uuid_re THEN
      SELECT finance_case.candidate_id INTO v_delete_owner_candidate_id
      FROM public.pay_advances finance_case WHERE finance_case.id=(v_old_row->>'finance_case_id')::uuid;
    ELSIF NULLIF(v_old_row->>'finance_component_id','')~*v_uuid_re THEN
      SELECT component.candidate_id INTO v_delete_owner_candidate_id
      FROM public.pay_finance_case_components component
      WHERE component.id=(v_old_row->>'finance_component_id')::uuid;
    END IF;
  END IF;

  IF TG_OP='DELETE' AND v_delete_context IS NOT NULL
     AND v_delete_owner_candidate_id IS NOT NULL THEN
    IF EXISTS(
         SELECT 1 FROM pg_catalog.pg_class relation
         WHERE relation.oid=v_delete_context
           AND relation.relowner=current_user::regrole::oid AND relation.relpersistence='t'
           AND relation.relnamespace=pg_catalog.pg_my_temp_schema()
       )
       AND (SELECT array_agg(attribute.attname||':'||pg_catalog.format_type(attribute.atttypid,attribute.atttypmod)
              ORDER BY attribute.attnum)
            FROM pg_catalog.pg_attribute attribute
            WHERE attribute.attrelid=v_delete_context
              AND attribute.attnum>0 AND NOT attribute.attisdropped)
         =ARRAY['candidate_id:uuid','delete_operation_id:uuid','candidate_lock_key:bigint',
           'backend_pid:integer','transaction_id:bigint','created_at_utc:timestamp with time zone',
           'suppress:boolean'] THEN
      -- The delete context is optional.  Keep its only row read behind dynamic
      -- SQL so an ordinary finance DELETE cannot fail during statement planning
      -- merely because candidate deletion did not create the temporary table.
      EXECUTE $delete_context$
        SELECT EXISTS(
          SELECT 1
          FROM pg_temp._bpay_candidate_delete_context_v1 context
          WHERE context.candidate_id=$1 AND context.suppress
            AND context.candidate_lock_key=pg_catalog.hashtextextended(
              public._pay_workbench_candidate_serial_key(context.candidate_id),24062027)
            AND context.backend_pid=pg_catalog.pg_backend_pid()
            AND context.transaction_id=pg_catalog.txid_current()
            AND (SELECT count(*) FROM pg_temp._bpay_candidate_delete_context_v1)=1
        )
      $delete_context$ INTO v_delete_context_suppressed USING v_delete_owner_candidate_id;
    END IF;
    IF v_delete_context_suppressed THEN
      RETURN OLD;
    END IF;
  END IF;

  -- The retained pay_advances dirty trigger is recreated as BEFORE ROW.  It
  -- declares the exact full transition before the row mutation and suppresses
  -- only an owner-controlled effect inside the current sealed build scope.
  IF v_trigger_table='pay_advances'
     AND to_regclass('pg_temp._bpay_wb_sync_context_v1') IS NOT NULL
     AND to_regclass('pg_temp._bpay_wb_expected_effects') IS NOT NULL
     AND COALESCE(current_setting('cloudtms.pay_workbench_overpayment_sync_token',true),'')
       ~* v_uuid_re THEN
    v_internal_build_token:=current_setting(
      'cloudtms.pay_workbench_overpayment_sync_token',true)::uuid;
    SELECT build_row.candidate_id INTO v_internal_candidate_id
    FROM pg_temp._bpay_wb_sync_context_v1 sync_context
       JOIN private.banking_pay_workbench_economic_builds build_row
         ON build_row.id=sync_context.build_id AND build_row.build_token=sync_context.build_token
       JOIN private.banking_pay_workbench_stage_attempts attempt
         ON attempt.id=sync_context.attempt_id AND attempt.attempt_nonce=sync_context.attempt_nonce
        AND attempt.build_id=build_row.id AND attempt.attempt_status='STARTED'
    WHERE build_row.status='RECONCILING' AND build_row.private_stage='RECONCILE_EXECUTE'
      AND build_row.build_token=v_internal_build_token;
    IF v_internal_candidate_id IS NOT NULL THEN
      IF TG_WHEN<>'BEFORE' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_CONFLICT' USING ERRCODE='23514';
      END IF;
      v_internal_source_id:=COALESCE(NULLIF(v_new_row->>'id','')::uuid,
        NULLIF(v_old_row->>'id','')::uuid);
      v_internal_timesheet_id:=COALESCE(NULLIF(v_new_row->>'linked_timesheet_id','')::uuid,
        NULLIF(v_old_row->>'linked_timesheet_id','')::uuid);
      v_internal_before_digest:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE md5(
        private.pay_workbench_finance_effect_normalise_row_v1(
          v_trigger_table,TG_OP,v_old_row,v_old_row)::text) END;
      v_internal_after_digest:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE md5(
        private.pay_workbench_finance_effect_normalise_row_v1(
          v_trigger_table,TG_OP,v_new_row,v_old_row)::text) END;
      IF v_internal_source_id IS NULL
         OR COALESCE(NULLIF(v_new_row->>'candidate_id','')::uuid,
              NULLIF(v_old_row->>'candidate_id','')::uuid)
            IS DISTINCT FROM v_internal_candidate_id
         OR (v_internal_timesheet_id IS NOT NULL AND NOT EXISTS(
           SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
           JOIN pg_temp._bpay_wb_sync_context_v1 sync_context
             ON sync_context.build_id=scope_row.build_id
           WHERE scope_row.timesheet_id=v_internal_timesheet_id
         )) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' USING ERRCODE='23514';
      END IF;
      IF v_effect_capture_mode THEN
        INSERT INTO pg_temp._bpay_wb_expected_effects(
          build_token,candidate_id,timesheet_id,relation_name,operation,source_id,
          finance_case_id,finance_component_id,economic_key_type,economic_key_value,
          expected_before_digest,expected_after_digest,proposed,observed
        ) VALUES(
          v_internal_build_token,v_internal_candidate_id,v_internal_timesheet_id,
          v_trigger_table,TG_OP,v_internal_source_id,v_internal_source_id,NULL,NULL,NULL,
          v_internal_before_digest,v_internal_after_digest,true,false
        );
      ELSIF TG_OP='INSERT' THEN
        UPDATE pg_temp._bpay_wb_expected_effects expected
        SET actual_source_id=v_internal_source_id,proposed=true
        WHERE expected.ctid=(SELECT candidate.ctid
          FROM pg_temp._bpay_wb_expected_effects candidate
          WHERE candidate.build_token=v_internal_build_token
            AND candidate.candidate_id=v_internal_candidate_id
            AND candidate.timesheet_id IS NOT DISTINCT FROM v_internal_timesheet_id
            AND candidate.relation_name=v_trigger_table AND candidate.operation=TG_OP
            AND candidate.proposed IS NOT TRUE AND candidate.observed IS NOT TRUE
            AND candidate.expected_before_digest IS NULL
            AND candidate.expected_after_digest IS NOT DISTINCT FROM v_internal_after_digest
          ORDER BY candidate.source_id LIMIT 1)
        RETURNING expected.source_id INTO v_internal_logical_source_id;
        GET DIAGNOSTICS v_expected_match_count=ROW_COUNT;
        IF v_expected_match_count<>1 OR v_internal_logical_source_id IS NULL THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' USING ERRCODE='23514';
        END IF;
        INSERT INTO pg_temp._bpay_wb_effect_identity_map_v1(
          relation_name,logical_source_id,actual_source_id)
        VALUES(v_trigger_table,v_internal_logical_source_id,v_internal_source_id);
      ELSE
        UPDATE pg_temp._bpay_wb_expected_effects expected SET proposed=true
        WHERE expected.build_token=v_internal_build_token
          AND expected.candidate_id=v_internal_candidate_id
          AND expected.timesheet_id IS NOT DISTINCT FROM v_internal_timesheet_id
          AND expected.relation_name=v_trigger_table AND expected.operation=TG_OP
          AND expected.source_id=v_internal_source_id
          AND expected.proposed IS NOT TRUE AND expected.observed IS NOT TRUE
          AND expected.expected_before_digest IS NOT DISTINCT FROM v_internal_before_digest
          AND expected.expected_after_digest IS NOT DISTINCT FROM v_internal_after_digest;
        GET DIAGNOSTICS v_expected_match_count=ROW_COUNT;
        IF v_expected_match_count<>1 THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' USING ERRCODE='23514';
        END IF;
      END IF;
      IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
    END IF;
  END IF;

  -- Natural-expiry fields are derived scheduler metadata.  An update confined
  -- to this allowlist must not create another generation or candidate build.
  IF TG_OP = 'UPDATE'
     AND v_trigger_table = 'pay_item_snoozes'
     AND (
       v_new_row - ARRAY[
         'natural_expiry_source_fingerprint',
         'natural_expiry_checked_fingerprint',
         'natural_expiry_checked_at_utc',
         'natural_expiry_state_changed',
         'natural_expiry_result_code'
       ]::text[]
     ) IS NOT DISTINCT FROM (
       v_old_row - ARRAY[
         'natural_expiry_source_fingerprint',
         'natural_expiry_checked_fingerprint',
         'natural_expiry_checked_at_utc',
         'natural_expiry_state_changed',
         'natural_expiry_result_code'
       ]::text[]
     ) THEN
    RETURN NEW;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '') ~* v_uuid_re THEN
    v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid);
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '') ~* v_uuid_re THEN
    v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid);
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_old_row->>'timesheet_id', v_old_row->>'linked_timesheet_id', '')), '') ~* v_uuid_re THEN
    v_old_timesheet_id := NULLIF(BTRIM(COALESCE(v_old_row->>'timesheet_id', v_old_row->>'linked_timesheet_id', '')), '')::uuid;
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_new_row->>'timesheet_id', v_new_row->>'linked_timesheet_id', '')), '') ~* v_uuid_re THEN
    v_new_timesheet_id := NULLIF(BTRIM(COALESCE(v_new_row->>'timesheet_id', v_new_row->>'linked_timesheet_id', '')), '')::uuid;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '') ~* v_uuid_re THEN
    v_old_contract_id := NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '')::uuid;
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '') ~* v_uuid_re THEN
    v_new_contract_id := NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '')::uuid;
  END IF;

  v_explicit_banking_pay_action := lower(BTRIM(COALESCE(current_setting('cloudtms.banking_pay_explicit_action', true), 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR lower(BTRIM(COALESCE(current_setting('cloudtms.banking_pay_dirty_allowed', true), 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN (
      'timesheet_authorise',
      'timesheet_unauthorise',
      'timesheet_archive',
      'timesheet_unarchive',
      'authorise_timesheet',
      'unauthorise_timesheet',
      'archive_timesheet',
      'unarchive_timesheet',
      'banking_pay',
      'banking_pay_refresh',
      'banking_pay_dirty',
      'banking_pay_action',
      'banking_pay_recalculate',
      'banking_pay_decision',
      'banking_pay_case_resolution',
      'banking_pay_timesheet_advance',
      'banking_pay_patch'
    );

  IF TG_OP = 'INSERT'
     AND v_trigger_table = 'timesheets'
     AND v_explicit_banking_pay_action IS NOT TRUE
     AND lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('manual_timesheet_save', 'ordinary_timesheet_save', 'timesheet_manual_save', 'manual_save')
     AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', v_new_row->>'authorised_at_utc', '')), '') IS NULL
     AND NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', v_new_row->>'revoked_at_utc', '')), '') IS NULL THEN
    PERFORM public._temp_diag_log(
      'TEMP_TRIGGER_DIRTY_STAGE',
      'TEMP_BANKING_PAY_DIRTY',
      COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
      jsonb_build_object(
        'function_name', 'pay_workbench_mark_candidate_dirty',
        'stage', 'early_return_ordinary_timesheet_insert_save_no_dirty',
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'mutation_context', v_lifecycle_context,
        'authorised_at_server_present', false,
        'revoked_at_present', false,
        'explicit_banking_pay_action', false,
        'banking_pay_dirty_required', false,
        'source_build_required', false,
        'line_work_required', false,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
      )
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    v_authorise_boundary_changed :=
      (
        NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_server', '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(v_old_row->>'revoked_at', '')), '') IS NULL
      ) IS DISTINCT FROM (
        NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NULL
      );

    v_archive_boundary_changed :=
      (NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NOT NULL)
      IS DISTINCT FROM
      (NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NOT NULL);

    v_material_live_source_changed :=
      (v_old_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
      OR (v_old_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
      OR (v_old_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
      OR (v_old_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
      OR (v_old_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
      OR (v_old_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
      OR (v_old_row->'additional_units_week') IS DISTINCT FROM (v_new_row->'additional_units_week')
      OR (v_old_row->'additional_units_per_day') IS DISTINCT FROM (v_new_row->'additional_units_per_day')
      OR (v_old_row->'week_ending_date') IS DISTINCT FROM (v_new_row->'week_ending_date')
      OR (v_old_row->'booking_id') IS DISTINCT FROM (v_new_row->'booking_id')
      OR (v_old_row->'line_type') IS DISTINCT FROM (v_new_row->'line_type')
      OR (v_old_row->'sheet_scope') IS DISTINCT FROM (v_new_row->'sheet_scope')
      OR (v_old_row->'reference_number') IS DISTINCT FROM (v_new_row->'reference_number')
      OR (v_old_row->'status') IS DISTINCT FROM (v_new_row->'status')
      OR (v_old_row->'submission_mode') IS DISTINCT FROM (v_new_row->'submission_mode')
      OR (v_old_row->'contract_id') IS DISTINCT FROM (v_new_row->'contract_id')
      OR (v_old_row->'is_adjustment') IS DISTINCT FROM (v_new_row->'is_adjustment')
      OR (v_old_row->'parent_timesheet_id') IS DISTINCT FROM (v_new_row->'parent_timesheet_id')
      OR (v_old_row->'correction_id') IS DISTINCT FROM (v_new_row->'correction_id')
      OR (v_old_row->'correction_kind') IS DISTINCT FROM (v_new_row->'correction_kind')
      OR (v_old_row->'adjustment_origin') IS DISTINCT FROM (v_new_row->'adjustment_origin');
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    v_authorise_boundary_changed :=
      (NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_utc', '')), '') IS NOT NULL)
      IS DISTINCT FROM
      (NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL);

    IF LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_material_live_source_changed :=
      (v_old_row->'pay_method') IS DISTINCT FROM (v_new_row->'pay_method')
      OR (v_old_row->'policy_snapshot_json') IS DISTINCT FROM (v_new_row->'policy_snapshot_json')
      OR (v_old_row->'rate_source_refs_json') IS DISTINCT FROM (v_new_row->'rate_source_refs_json')
      OR (v_old_row->'hours_day') IS DISTINCT FROM (v_new_row->'hours_day')
      OR (v_old_row->'hours_night') IS DISTINCT FROM (v_new_row->'hours_night')
      OR (v_old_row->'hours_sat') IS DISTINCT FROM (v_new_row->'hours_sat')
      OR (v_old_row->'hours_sun') IS DISTINCT FROM (v_new_row->'hours_sun')
      OR (v_old_row->'hours_bh') IS DISTINCT FROM (v_new_row->'hours_bh')
      OR (v_old_row->'pay_day') IS DISTINCT FROM (v_new_row->'pay_day')
      OR (v_old_row->'pay_night') IS DISTINCT FROM (v_new_row->'pay_night')
      OR (v_old_row->'pay_sat') IS DISTINCT FROM (v_new_row->'pay_sat')
      OR (v_old_row->'pay_sun') IS DISTINCT FROM (v_new_row->'pay_sun')
      OR (v_old_row->'pay_bh') IS DISTINCT FROM (v_new_row->'pay_bh')
      OR (v_old_row->'total_hours') IS DISTINCT FROM (v_new_row->'total_hours')
      OR (v_old_row->'total_pay_ex_vat') IS DISTINCT FROM (v_new_row->'total_pay_ex_vat')
      OR (v_old_row->'expenses_pay_ex_vat') IS DISTINCT FROM (v_new_row->'expenses_pay_ex_vat')
      OR (v_old_row->'travel_pay_ex_vat') IS DISTINCT FROM (v_new_row->'travel_pay_ex_vat')
      OR (v_old_row->'accommodation_pay_ex_vat') IS DISTINCT FROM (v_new_row->'accommodation_pay_ex_vat')
      OR (v_old_row->'other_pay_ex_vat') IS DISTINCT FROM (v_new_row->'other_pay_ex_vat')
      OR (v_old_row->'mileage_units') IS DISTINCT FROM (v_new_row->'mileage_units')
      OR (v_old_row->'mileage_pay_rate') IS DISTINCT FROM (v_new_row->'mileage_pay_rate')
      OR (v_old_row->'mileage_pay_ex_vat') IS DISTINCT FROM (v_new_row->'mileage_pay_ex_vat')
      OR (v_old_row->'additional_pay_ex_vat') IS DISTINCT FROM (v_new_row->'additional_pay_ex_vat')
      OR (v_old_row->'pay_wtr_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_wtr_rate_pct_snapshot')
      OR (v_old_row->'pay_vat_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_rate_pct_snapshot')
      OR (v_old_row->'pay_vat_amount_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_amount_snapshot')
      OR (v_old_row->'pay_total_inc_vat_snapshot') IS DISTINCT FROM (v_new_row->'pay_total_inc_vat_snapshot')
      OR (v_old_row->'invoice_breakdown_json') IS DISTINCT FROM (v_new_row->'invoice_breakdown_json')
      OR (v_old_row->'additional_units_json') IS DISTINCT FROM (v_new_row->'additional_units_json')
      OR (v_old_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
      OR (v_old_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
      OR (v_old_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
      OR (v_old_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
      OR (v_old_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
      OR (v_old_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
      OR (v_old_row->'pay_on_hold') IS DISTINCT FROM (v_new_row->'pay_on_hold')
      OR (v_old_row->'pay_on_hold_reason') IS DISTINCT FROM (v_new_row->'pay_on_hold_reason')
      OR (v_old_row->'has_rate_issue') IS DISTINCT FROM (v_new_row->'has_rate_issue')
      OR (v_old_row->'has_pay_channel_issue') IS DISTINCT FROM (v_new_row->'has_pay_channel_issue')
      OR (v_old_row->'processing_status') IS DISTINCT FROM (v_new_row->'processing_status')
      OR (v_old_row->'locked_by_invoice_id') IS DISTINCT FROM (v_new_row->'locked_by_invoice_id')
      OR (v_old_row->'unlocked_by_credit_note_id') IS DISTINCT FROM (v_new_row->'unlocked_by_credit_note_id')
      OR (v_old_row->'candidate_id') IS DISTINCT FROM (v_new_row->'candidate_id')
      OR (v_old_row->'client_id') IS DISTINCT FROM (v_new_row->'client_id');
    ELSE
      -- Snapshot rotation demotes the previous row before inserting its
      -- replacement.  The demotion itself is bookkeeping, not a live-source
      -- economic change and must not mark a frozen Draft stale.
      v_material_live_source_changed := false;
    END IF;
  ELSIF TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN
    IF LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      SELECT COALESCE(to_jsonb(previous_financial_row), '{}'::jsonb)
      INTO v_previous_tsfin_row
      FROM public.timesheets_financials AS previous_financial_row
      WHERE previous_financial_row.timesheet_id = v_new_timesheet_id
        AND previous_financial_row.id IS DISTINCT FROM
          CASE
            WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re
              THEN NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid
            ELSE NULL::uuid
          END
      ORDER BY
        previous_financial_row.timesheet_version DESC NULLS LAST,
        previous_financial_row.computed_at_utc DESC NULLS LAST,
        previous_financial_row.created_at DESC NULLS LAST,
        previous_financial_row.id DESC
      LIMIT 1;

      v_previous_tsfin_row := COALESCE(v_previous_tsfin_row, '{}'::jsonb);
      IF v_previous_tsfin_row = '{}'::jsonb THEN
        v_material_live_source_changed := true;
      ELSE
        v_material_live_source_changed :=
          (v_previous_tsfin_row->'pay_method') IS DISTINCT FROM (v_new_row->'pay_method')
          OR (v_previous_tsfin_row->'policy_snapshot_json') IS DISTINCT FROM (v_new_row->'policy_snapshot_json')
          OR (v_previous_tsfin_row->'rate_source_refs_json') IS DISTINCT FROM (v_new_row->'rate_source_refs_json')
          OR (v_previous_tsfin_row->'hours_day') IS DISTINCT FROM (v_new_row->'hours_day')
          OR (v_previous_tsfin_row->'hours_night') IS DISTINCT FROM (v_new_row->'hours_night')
          OR (v_previous_tsfin_row->'hours_sat') IS DISTINCT FROM (v_new_row->'hours_sat')
          OR (v_previous_tsfin_row->'hours_sun') IS DISTINCT FROM (v_new_row->'hours_sun')
          OR (v_previous_tsfin_row->'hours_bh') IS DISTINCT FROM (v_new_row->'hours_bh')
          OR (v_previous_tsfin_row->'pay_day') IS DISTINCT FROM (v_new_row->'pay_day')
          OR (v_previous_tsfin_row->'pay_night') IS DISTINCT FROM (v_new_row->'pay_night')
          OR (v_previous_tsfin_row->'pay_sat') IS DISTINCT FROM (v_new_row->'pay_sat')
          OR (v_previous_tsfin_row->'pay_sun') IS DISTINCT FROM (v_new_row->'pay_sun')
          OR (v_previous_tsfin_row->'pay_bh') IS DISTINCT FROM (v_new_row->'pay_bh')
          OR (v_previous_tsfin_row->'total_hours') IS DISTINCT FROM (v_new_row->'total_hours')
          OR (v_previous_tsfin_row->'total_pay_ex_vat') IS DISTINCT FROM (v_new_row->'total_pay_ex_vat')
          OR (v_previous_tsfin_row->'expenses_pay_ex_vat') IS DISTINCT FROM (v_new_row->'expenses_pay_ex_vat')
          OR (v_previous_tsfin_row->'travel_pay_ex_vat') IS DISTINCT FROM (v_new_row->'travel_pay_ex_vat')
          OR (v_previous_tsfin_row->'accommodation_pay_ex_vat') IS DISTINCT FROM (v_new_row->'accommodation_pay_ex_vat')
          OR (v_previous_tsfin_row->'other_pay_ex_vat') IS DISTINCT FROM (v_new_row->'other_pay_ex_vat')
          OR (v_previous_tsfin_row->'mileage_units') IS DISTINCT FROM (v_new_row->'mileage_units')
          OR (v_previous_tsfin_row->'mileage_pay_rate') IS DISTINCT FROM (v_new_row->'mileage_pay_rate')
          OR (v_previous_tsfin_row->'mileage_pay_ex_vat') IS DISTINCT FROM (v_new_row->'mileage_pay_ex_vat')
          OR (v_previous_tsfin_row->'additional_pay_ex_vat') IS DISTINCT FROM (v_new_row->'additional_pay_ex_vat')
          OR (v_previous_tsfin_row->'pay_wtr_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_wtr_rate_pct_snapshot')
          OR (v_previous_tsfin_row->'pay_vat_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_rate_pct_snapshot')
          OR (v_previous_tsfin_row->'pay_vat_amount_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_amount_snapshot')
          OR (v_previous_tsfin_row->'pay_total_inc_vat_snapshot') IS DISTINCT FROM (v_new_row->'pay_total_inc_vat_snapshot')
          OR (v_previous_tsfin_row->'invoice_breakdown_json') IS DISTINCT FROM (v_new_row->'invoice_breakdown_json')
          OR (v_previous_tsfin_row->'additional_units_json') IS DISTINCT FROM (v_new_row->'additional_units_json')
          OR (v_previous_tsfin_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
          OR (v_previous_tsfin_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
          OR (v_previous_tsfin_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
          OR (v_previous_tsfin_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
          OR (v_previous_tsfin_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
          OR (v_previous_tsfin_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
          OR (v_previous_tsfin_row->'pay_on_hold') IS DISTINCT FROM (v_new_row->'pay_on_hold')
          OR (v_previous_tsfin_row->'pay_on_hold_reason') IS DISTINCT FROM (v_new_row->'pay_on_hold_reason')
          OR (v_previous_tsfin_row->'has_rate_issue') IS DISTINCT FROM (v_new_row->'has_rate_issue')
          OR (v_previous_tsfin_row->'has_pay_channel_issue') IS DISTINCT FROM (v_new_row->'has_pay_channel_issue')
          OR (v_previous_tsfin_row->'processing_status') IS DISTINCT FROM (v_new_row->'processing_status')
          OR (v_previous_tsfin_row->'locked_by_invoice_id') IS DISTINCT FROM (v_new_row->'locked_by_invoice_id')
          OR (v_previous_tsfin_row->'unlocked_by_credit_note_id') IS DISTINCT FROM (v_new_row->'unlocked_by_credit_note_id')
          OR (v_previous_tsfin_row->'candidate_id') IS DISTINCT FROM (v_new_row->'candidate_id')
          OR (v_previous_tsfin_row->'client_id') IS DISTINCT FROM (v_new_row->'client_id');
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    IF v_authorise_boundary_changed IS NOT TRUE
       AND v_archive_boundary_changed IS NOT TRUE
       AND v_explicit_banking_pay_action IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_timesheet_edit_save_no_dirty', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'material_live_source_changed', v_material_live_source_changed, 'draft_stale_signal_only', v_material_live_source_changed, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    IF v_authorise_boundary_changed IS NOT TRUE AND v_explicit_banking_pay_action IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_timesheet_financials_edit_save_no_dirty', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'material_live_source_changed', v_material_live_source_changed, 'draft_stale_signal_only', v_material_live_source_changed, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  END IF;

  IF TG_OP = 'INSERT'
     AND v_trigger_table = 'timesheets_financials'
     AND v_explicit_banking_pay_action IS NOT TRUE
     AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NULL THEN
    PERFORM public._temp_diag_log(
      'TEMP_TRIGGER_DIRTY_STAGE',
      'TEMP_BANKING_PAY_DIRTY',
      COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
      jsonb_build_object(
        'function_name', 'pay_workbench_mark_candidate_dirty',
        'stage', 'early_return_ordinary_timesheet_financials_insert_edit_save_no_dirty',
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'mutation_context', v_lifecycle_context,
        'authorised_at_utc_present', false,
        'explicit_banking_pay_action', false,
        'banking_pay_dirty_required', false,
        'source_build_required', false,
        'line_work_required', false,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
      )
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheet_pay_state' THEN
    v_timesheet_pay_state_settlement_changed :=
      (v_old_row->'last_settled_snapshot_json') IS DISTINCT FROM (v_new_row->'last_settled_snapshot_json')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_signature', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_signature', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_pay_batch_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_pay_batch_id', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_at_utc', '')), '');

    v_timesheet_pay_state_summary_changed :=
      NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_status_code', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_status_code', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_icon_code', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_icon_code', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_paid_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_paid_at_utc', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_net_delta_ex_vat', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_net_delta_ex_vat', '')), '');

    IF v_timesheet_pay_state_settlement_changed IS NOT TRUE THEN
      v_timesheet_pay_state_bookkeeping_ignored := COALESCE(v_timesheet_pay_state_summary_changed, false);
      v_timesheet_pay_state_noop_ignored := COALESCE(v_timesheet_pay_state_summary_changed, false) IS NOT TRUE;

      PERFORM public._temp_diag_log(
        'TEMP_TRIGGER_DIRTY_STAGE',
        'TEMP_BANKING_PAY_DIRTY',
        COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
        jsonb_build_object(
          'function_name', 'pay_workbench_mark_candidate_dirty',
          'stage', CASE
            WHEN v_timesheet_pay_state_bookkeeping_ignored IS TRUE THEN 'early_return_timesheet_pay_state_bookkeeping_no_dirty'
            ELSE 'early_return_timesheet_pay_state_noop_no_dirty'
          END,
          'trigger_table', v_trigger_table,
          'trigger_op', TG_OP,
          'dirty_classification', CASE
            WHEN v_timesheet_pay_state_bookkeeping_ignored IS TRUE THEN 'TIMESHEET_PAY_STATE_BOOKKEEPING_IGNORED'
            ELSE 'TIMESHEET_PAY_STATE_NOOP_IGNORED'
          END,
          'timesheet_pay_state_settlement_changed', COALESCE(v_timesheet_pay_state_settlement_changed, false),
          'timesheet_pay_state_summary_changed', COALESCE(v_timesheet_pay_state_summary_changed, false),
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
        )
      );
      RETURN NEW;
    END IF;

    v_timesheet_pay_state_routing_reason := 'SOURCE_BUILD_REQUIRED_PAY_STATE_SETTLED_BASELINE_CHANGE';
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    v_old_payment_eligible := NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_server', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_old_row->>'revoked_at', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NULL;
    v_new_payment_eligible := NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NULL;
    IF v_old_payment_eligible IS NOT TRUE
       AND v_new_payment_eligible IS NOT TRUE
       AND v_archive_boundary_changed IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_unauthorised_edit', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    v_old_payment_eligible := NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_utc', '')), '') IS NOT NULL;
    v_new_payment_eligible := NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL;
    IF v_old_payment_eligible IS NOT TRUE AND v_new_payment_eligible IS NOT TRUE THEN
      v_tsfin_payability_state_changed :=
        NULLIF(BTRIM(COALESCE(v_old_row->>'paid_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'paid_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'paid_by_user_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'paid_by_user_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'payment_reference', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'payment_reference', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold_reason', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold_reason', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold_since_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold_since_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'locked_by_invoice_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'locked_by_invoice_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'locked_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'locked_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'unlocked_by_credit_note_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'unlocked_by_credit_note_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'remittance_last_sent_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'remittance_last_sent_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'remittance_send_count', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'remittance_send_count', '')), '');
      IF v_tsfin_payability_state_changed IS NOT TRUE THEN
        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_unauthorised_edit', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'payability_state_changed', false, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
        RETURN NEW;
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND v_trigger_table IN ('timesheets', 'timesheets_financials')
     AND v_authorise_boundary_changed IS TRUE THEN
    IF v_new_payment_eligible IS TRUE AND v_old_payment_eligible IS NOT TRUE THEN
      v_authorise_boundary_is_authorise := true;
    ELSIF v_old_payment_eligible IS TRUE AND v_new_payment_eligible IS NOT TRUE THEN
      v_authorise_boundary_is_unauthorise := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_authorise', 'authorise_timesheet') THEN
      v_authorise_boundary_is_authorise := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unauthorise', 'unauthorise_timesheet') THEN
      v_authorise_boundary_is_unauthorise := true;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND v_trigger_table = 'timesheets'
     AND v_archive_boundary_changed IS TRUE THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NULL
       AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NOT NULL THEN
      v_archive_boundary_is_archive := true;
    ELSIF NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NOT NULL
       AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NULL THEN
      v_archive_boundary_is_unarchive := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_archive', 'archive_timesheet') THEN
      v_archive_boundary_is_archive := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unarchive', 'unarchive_timesheet') THEN
      v_archive_boundary_is_unarchive := true;
    END IF;
  END IF;

  v_effective_lifecycle_context := CASE
    WHEN v_archive_boundary_is_archive IS TRUE THEN 'timesheet_archive'
    WHEN v_archive_boundary_is_unarchive IS TRUE THEN 'timesheet_unarchive'
    WHEN v_authorise_boundary_is_unauthorise IS TRUE THEN 'timesheet_unauthorise'
    WHEN v_authorise_boundary_is_authorise IS TRUE THEN 'timesheet_authorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_authorise', 'authorise_timesheet') THEN 'timesheet_authorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unauthorise', 'unauthorise_timesheet') THEN 'timesheet_unauthorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_archive', 'archive_timesheet') THEN 'timesheet_archive'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unarchive', 'unarchive_timesheet') THEN 'timesheet_unarchive'
    ELSE v_lifecycle_context
  END;

  v_banking_pay_dirty_required := v_authorise_boundary_changed IS TRUE
    OR v_archive_boundary_changed IS TRUE
    OR v_explicit_banking_pay_action IS TRUE
    OR (v_trigger_table = 'timesheet_pay_state' AND v_timesheet_pay_state_settlement_changed IS TRUE);
  v_ordinary_timesheet_edit_save_no_dirty := TG_OP = 'UPDATE'
    AND v_trigger_table IN ('timesheets', 'timesheets_financials')
    AND v_banking_pay_dirty_required IS NOT TRUE;

  IF v_old_timesheet_id IS NOT NULL OR v_new_timesheet_id IS NOT NULL THEN
    v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
    SELECT COALESCE(array_agg(DISTINCT timesheet_ids.timesheet_id ORDER BY timesheet_ids.timesheet_id), ARRAY[]::uuid[])
    INTO v_targeted_timesheet_ids
    FROM (
      SELECT v_old_timesheet_id AS timesheet_id
      UNION ALL
      SELECT v_new_timesheet_id AS timesheet_id
    ) AS timesheet_ids
    WHERE timesheet_ids.timesheet_id IS NOT NULL;
  END IF;

  IF v_trigger_table = 'candidates' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid);
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid);
    END IF;

    IF TG_OP = 'UPDATE' THEN
      v_route_source_method := UPPER(BTRIM(COALESCE(v_old_row->>'pay_method', '')));
      v_route_target_method := UPPER(BTRIM(COALESCE(v_new_row->>'pay_method', '')));
      v_candidate_route_change := v_route_source_method IN ('PAYE', 'UMBRELLA')
        AND v_route_target_method IN ('PAYE', 'UMBRELLA')
        AND v_route_source_method <> v_route_target_method;

      IF v_candidate_route_change IS TRUE THEN
        IF v_route_operation_id IS NULL OR v_route_operation_id !~* v_uuid_re THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_CONTEXT_REQUIRED'
            USING ERRCODE = '22023';
        END IF;
        IF v_route_actor_user_id IS NULL OR v_route_actor_user_id !~* v_uuid_re THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_ACTOR_CONTEXT_REQUIRED'
            USING ERRCODE = '22023';
        END IF;

        v_route_scope_result := public.candidate_pay_method_change_refresh_scope_v1(
          NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid,
          v_route_source_method,
          v_route_target_method
        );

        v_route_exact_scope := LOWER(BTRIM(COALESCE(v_route_scope_result->>'exact_scope', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
        v_route_coverage_complete := LOWER(BTRIM(COALESCE(v_route_scope_result->>'coverage_complete', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

        IF COALESCE(v_route_scope_result->>'ok', 'false') <> 'true'
           OR v_route_exact_scope IS NOT TRUE
           OR v_route_coverage_complete IS NOT TRUE
           OR jsonb_typeof(v_route_scope_result->'targeted_timesheet_ids') IS DISTINCT FROM 'array' THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_EXACT_SCOPE_UNAVAILABLE'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        IF EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(v_route_scope_result->'targeted_timesheet_ids') AS raw_target(value)
          WHERE raw_target.value !~* v_uuid_re
        ) THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_TARGET_SCOPE_INVALID'
            USING ERRCODE = 'P0001';
        END IF;

        SELECT COALESCE(array_agg(DISTINCT target_value::uuid ORDER BY target_value::uuid), ARRAY[]::uuid[])
        INTO v_targeted_timesheet_ids
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(v_route_scope_result->'targeted_timesheet_ids') = 'array'
              THEN v_route_scope_result->'targeted_timesheet_ids'
            ELSE '[]'::jsonb
          END
        ) AS target_values(target_value)
        WHERE target_value ~* v_uuid_re;

        v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
        v_route_targeted_scope_is_empty := COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 0;
        v_route_authoritative_sessions := COALESCE(v_route_scope_result->'authoritative_sessions', '[]'::jsonb);
        v_route_replaced_source_session_ids := COALESCE(v_route_scope_result->'replaced_source_session_ids', '[]'::jsonb);
        v_route_target_details := COALESCE(v_route_scope_result->'target_details', '[]'::jsonb);
        v_route_authorised_timesheet_ids := COALESCE(v_route_scope_result->'authorised_timesheet_ids', '[]'::jsonb);
        v_route_active_advance_timesheet_ids := COALESCE(v_route_scope_result->'active_advance_timesheet_ids', '[]'::jsonb);
        v_route_retained_finance_timesheet_ids := COALESCE(v_route_scope_result->'retained_finance_timesheet_ids', '[]'::jsonb);
        v_route_authorised_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'authorised_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'authorised_timesheet_count')::integer END,
          0
        );
        v_route_active_advance_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'active_advance_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'active_advance_timesheet_count')::integer END,
          0
        );
        v_route_retained_finance_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'retained_finance_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'retained_finance_timesheet_count')::integer END,
          0
        );
        v_route_source_target_mismatch_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'source_target_mismatch_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'source_target_mismatch_count')::integer END,
          0
        );

        IF COALESCE(v_route_scope_result->>'durable_job_id', '') !~* v_uuid_re
           OR LOWER(BTRIM(COALESCE(v_route_scope_result->>'durable_scope_persisted', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_MISSING'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        v_route_job_id := (v_route_scope_result->>'durable_job_id')::uuid;
        v_route_job_status := NULLIF(BTRIM(COALESCE(v_route_scope_result->>'durable_job_status', '')), '');
        v_route_dedupe_key := NULLIF(BTRIM(COALESCE(v_route_scope_result->>'durable_job_dedupe_key', '')), '');
        v_route_job_source_change_seq := COALESCE(
          CASE
            WHEN COALESCE(v_route_scope_result->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (v_route_scope_result->>'source_change_seq')::bigint
            ELSE 0
          END,
          0
        );

        IF v_route_job_status NOT IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
           OR v_route_dedupe_key IS NULL
           OR v_route_job_source_change_seq <= 0 THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_INVALID'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        v_explicit_banking_pay_action := true;
        v_banking_pay_dirty_required := true;
        v_ordinary_timesheet_edit_save_no_dirty := false;
        v_effective_lifecycle_context := 'candidate_pay_method_change';
      END IF;
    END IF;
  END IF;

  IF v_trigger_table IN ('bank_name_checks', 'bank_payee_map') THEN
    v_entity_kind_old := UPPER(BTRIM(COALESCE(v_old_row->>'entity_kind', '')));
    v_entity_kind_new := UPPER(BTRIM(COALESCE(v_new_row->>'entity_kind', '')));
    IF v_entity_kind_old = 'CANDIDATE' AND NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '')::uuid);
    ELSIF v_entity_kind_old IN ('UMBRELLA', 'UMBRELLA_COMPANY') AND NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '')::uuid;
    END IF;
    IF v_entity_kind_new = 'CANDIDATE' AND NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')::uuid);
    ELSIF v_entity_kind_new IN ('UMBRELLA', 'UMBRELLA_COMPANY') AND NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')::uuid;
    END IF;
  END IF;

  IF v_trigger_table = 'umbrellas' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid;
    END IF;
  END IF;

  IF v_umbrella_id_old IS NOT NULL OR v_umbrella_id_new IS NOT NULL THEN
    FOR v_scope_id IN
      SELECT DISTINCT umbrella_scope.umbrella_id::text
      FROM (
        SELECT v_umbrella_id_old AS umbrella_id
        UNION ALL
        SELECT v_umbrella_id_new AS umbrella_id
      ) AS umbrella_scope
      WHERE umbrella_scope.umbrella_id IS NOT NULL
    LOOP
      v_reason := 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP;
      v_payload_json := jsonb_build_object(
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'trigger_operation', TG_OP,
        'scope_kind', 'UMBRELLA',
        'scope_id', v_scope_id,
        'reason', v_reason,
        'fallback_reason', 'UMBRELLA_BANK_DETAIL_DIRTY',
        'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
        'source_build_required', true,
        'line_work_required', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
      PERFORM public.pay_workbench_dirty_event_enqueue(
        p_job_type => 'CONTRACT_CLIENT_DIRTY_FANOUT',
        p_scope_kind => 'UMBRELLA',
        p_scope_id => v_scope_id,
        p_candidate_id => NULL::uuid,
        p_targeted_timesheet_ids => ARRAY[]::uuid[],
        p_linked_timesheet_ids => ARRAY[]::uuid[],
        p_payload_json => v_payload_json,
        p_reason => v_reason,
        p_priority => -1000,
        p_run_at_utc => v_now
      );
    END LOOP;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT candidate_candidates.candidate_id ORDER BY candidate_candidates.candidate_id), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM (
    SELECT unnest(COALESCE(v_candidate_ids, ARRAY[]::uuid[])) AS candidate_id
    UNION ALL
    SELECT contract_old.candidate_id FROM public.contracts AS contract_old WHERE contract_old.id = v_old_contract_id
    UNION ALL
    SELECT contract_new.candidate_id FROM public.contracts AS contract_new WHERE contract_new.id = v_new_contract_id
    UNION ALL
    SELECT financial_old.candidate_id FROM public.timesheets_financials AS financial_old WHERE financial_old.timesheet_id = v_old_timesheet_id AND financial_old.is_current = true
    UNION ALL
    SELECT financial_new.candidate_id FROM public.timesheets_financials AS financial_new WHERE financial_new.timesheet_id = v_new_timesheet_id AND financial_new.is_current = true
    UNION ALL
    SELECT timesheet_contract_old.candidate_id
    FROM public.timesheets AS timesheet_old
    JOIN public.contracts AS timesheet_contract_old ON timesheet_contract_old.id = timesheet_old.contract_id
    WHERE timesheet_old.timesheet_id = v_old_timesheet_id
    UNION ALL
    SELECT timesheet_contract_new.candidate_id
    FROM public.timesheets AS timesheet_new
    JOIN public.contracts AS timesheet_contract_new ON timesheet_contract_new.id = timesheet_new.contract_id
    WHERE timesheet_new.timesheet_id = v_new_timesheet_id
  ) AS candidate_candidates
  WHERE candidate_candidates.candidate_id IS NOT NULL;

  IF COALESCE(array_length(v_candidate_ids, 1), 0) = 0 THEN
    PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'return_no_candidate', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  v_reason := CASE
    WHEN v_candidate_route_change IS TRUE
      THEN 'CANDIDATE_PAY_METHOD_CHANGE:' || v_route_source_method || '_TO_' || v_route_target_method
    ELSE 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP
  END;

  FOREACH v_candidate_id IN ARRAY v_candidate_ids
  LOOP

    IF TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN
      v_tsfin_insert_not_coalesced_reason := NULL::text;
      v_tsfin_insert_coalesced_job_id := NULL::uuid;
      v_tsfin_insert_coalesced_projection_run_id := NULL::uuid;
      v_tsfin_insert_coalesced_session_id := NULL::uuid;
      v_tsfin_insert_coalesced_source_change_seq := NULL::bigint;
      v_tsfin_insert_authorise_like := v_new_timesheet_id IS NOT NULL
        AND COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 1
        AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL
        AND COALESCE(LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'true'))), 'true') NOT IN ('false', 'f', '0', 'no', 'n', 'off');

      IF v_tsfin_insert_authorise_like IS TRUE THEN
        SELECT
          existing_delta.id,
          CASE
            WHEN COALESCE(existing_delta.payload_json->>'projection_run_id', '') ~* v_uuid_re
              THEN (existing_delta.payload_json->>'projection_run_id')::uuid
            ELSE NULL::uuid
          END,
          existing_delta.session_id,
          CASE
            WHEN COALESCE(existing_delta.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (existing_delta.payload_json->>'source_change_seq')::bigint
            WHEN COALESCE(existing_delta.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$'
              THEN (existing_delta.payload_json->>'source_change_sequence')::bigint
            ELSE NULL::bigint
          END
        INTO
          v_tsfin_insert_coalesced_job_id,
          v_tsfin_insert_coalesced_projection_run_id,
          v_tsfin_insert_coalesced_session_id,
          v_tsfin_insert_coalesced_source_change_seq
        FROM public.banking_pay_workbench_jobs AS existing_delta
        JOIN public.banking_pay_workbench_sessions AS existing_session
          ON existing_session.id = existing_delta.session_id
         AND UPPER(BTRIM(COALESCE(existing_session.status, ''))) = 'OPEN'
         AND existing_session.discarded_at_utc IS NULL
        WHERE existing_delta.candidate_id = v_candidate_id
          AND existing_delta.created_at_utc >= (v_now - INTERVAL '10 minutes')
          AND UPPER(BTRIM(COALESCE(existing_delta.status, ''))) IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
          AND UPPER(BTRIM(COALESCE(existing_delta.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'projection_class', ''))) = 'NORMAL_TIMESHEET'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'trigger_table', ''))) = 'TIMESHEETS'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'trigger_operation', existing_delta.payload_json->>'trigger_op', ''))) = 'UPDATE'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'mutation_context', existing_delta.payload_json->>'lifecycle_mutation_context', ''))) IN ('TIMESHEET_AUTHORISE', 'AUTHORISE_TIMESHEET')
          AND LOWER(BTRIM(COALESCE(existing_delta.payload_json->>'authorise_boundary_changed', existing_delta.payload_json#>>'{complexity_flags,authorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND EXISTS (
            SELECT 1
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof(existing_delta.payload_json->'targeted_timesheet_ids') = 'array'
                  THEN existing_delta.payload_json->'targeted_timesheet_ids'
                ELSE '[]'::jsonb
              END
            ) AS targeted_timesheet_id(value)
            WHERE targeted_timesheet_id.value ~* v_uuid_re
              AND targeted_timesheet_id.value::uuid = v_new_timesheet_id
          )
        ORDER BY existing_delta.created_at_utc DESC, existing_delta.id DESC
        LIMIT 1;

        IF v_tsfin_insert_coalesced_job_id IS NOT NULL THEN
          PERFORM public._temp_diag_log(
            'TEMP_TRIGGER_DIRTY_STAGE',
            'TEMP_BANKING_PAY_DIRTY',
            v_new_timesheet_id::text,
            jsonb_build_object(
              'function_name', 'pay_workbench_mark_candidate_dirty',
              'stage', 'early_return_timesheet_financials_insert_authorise_coalesced_no_dirty',
              'trigger_table', v_trigger_table,
              'trigger_op', TG_OP,
              'coalesced_with_timesheets_authorise_delta', true,
              'coalesced_source_change_seq', v_tsfin_insert_coalesced_source_change_seq,
              'coalesced_job_id', v_tsfin_insert_coalesced_job_id::text,
              'coalesced_projection_run_id', CASE WHEN v_tsfin_insert_coalesced_projection_run_id IS NULL THEN NULL ELSE v_tsfin_insert_coalesced_projection_run_id::text END,
              'coalesced_session_id', CASE WHEN v_tsfin_insert_coalesced_session_id IS NULL THEN NULL ELSE v_tsfin_insert_coalesced_session_id::text END,
              'coalesced_candidate_id', v_candidate_id::text,
              'coalesced_timesheet_id', v_new_timesheet_id::text,
              'banking_pay_dirty_required', false,
              'source_build_required', false,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
              'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
            )
          );
          CONTINUE;
        END IF;

        v_tsfin_insert_not_coalesced_reason := 'NO_PRIOR_AUTHORISE_DELTA';
      ELSE
        v_tsfin_insert_not_coalesced_reason := CASE
          WHEN v_new_timesheet_id IS NULL THEN 'NO_TARGET_TIMESHEET'
          WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) <> 1 THEN 'MULTI_OR_EMPTY_TARGET_SCOPE'
          WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NULL THEN 'UNAUTHORISED_INSERT'
          WHEN COALESCE(LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'true'))), 'true') IN ('false', 'f', '0', 'no', 'n', 'off') THEN 'NON_CURRENT_INSERT'
          ELSE 'UNKNOWN_SAFE_STATE'
        END;
      END IF;
    END IF;

    IF v_effective_lifecycle_context IN ('timesheet_authorise', 'timesheet_unauthorise', 'timesheet_archive', 'timesheet_unarchive') THEN
      v_lifecycle_dedupe_token := '|LIFECYCLE_DIRTY:' || v_effective_lifecycle_context || ':' || v_candidate_id::text || ':' || COALESCE(array_to_string(v_targeted_timesheet_ids, ','), '') || '|';
      v_lifecycle_dedupe_keys := COALESCE(current_setting('cloudtms.pay_dirty_dedupe_keys', true), '');
      IF POSITION(v_lifecycle_dedupe_token IN v_lifecycle_dedupe_keys) > 0 THEN
        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN v_targeted_timesheet_ids[1]::text ELSE NULL::text END, jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'dedupe_skip_lifecycle_duplicate', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'mutation_context', v_lifecycle_context, 'candidate_id', v_candidate_id::text, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
        CONTINUE;
      END IF;
      PERFORM set_config('cloudtms.pay_dirty_dedupe_keys', LEFT(v_lifecycle_dedupe_keys || v_lifecycle_dedupe_token, 60000), true);
    END IF;

    v_payload_json := jsonb_build_object(
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'trigger_operation', TG_OP,
      'mutation_context', v_effective_lifecycle_context,
      'lifecycle_mutation_context', v_effective_lifecycle_context,
      'authorise_boundary_changed', COALESCE(v_authorise_boundary_is_authorise, false),
      'unauthorise_boundary_changed', COALESCE(v_authorise_boundary_is_unauthorise, false),
      'archive_boundary_changed', COALESCE(v_archive_boundary_is_archive, false),
      'unarchive_boundary_changed', COALESCE(v_archive_boundary_is_unarchive, false),
      'explicit_banking_pay_action', COALESCE(v_explicit_banking_pay_action, false) OR COALESCE(v_authorise_boundary_changed, false) OR COALESCE(v_archive_boundary_changed, false),
      'banking_pay_dirty_required', COALESCE(v_banking_pay_dirty_required, false),
      'ordinary_timesheet_edit_save_no_dirty', COALESCE(v_ordinary_timesheet_edit_save_no_dirty, false),
      'timesheets_financials_insert_not_coalesced_reason', CASE WHEN v_trigger_table = 'timesheets_financials' AND TG_OP = 'INSERT' THEN v_tsfin_insert_not_coalesced_reason ELSE NULL END,
      'timesheets_financials_insert_coalesced_authorise_delta', false,
      'scope_kind', 'CANDIDATE',
      'scope_id', v_candidate_id::text,
      'candidate_id', v_candidate_id::text,
      'reason', v_reason,
      'dirty_reason', v_reason,
      'timesheet_pay_state_settlement_changed', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_settlement_changed, false) ELSE NULL END,
      'timesheet_pay_state_summary_changed', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_summary_changed, false) ELSE NULL END,
      'timesheet_pay_state_bookkeeping_ignored', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_bookkeeping_ignored, false) ELSE NULL END,
      'timesheet_pay_state_noop_ignored', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_noop_ignored, false) ELSE NULL END,
      'pay_state_dirty_routing_reason', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN v_timesheet_pay_state_routing_reason ELSE NULL END,
      'source_build_required_reason', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN v_timesheet_pay_state_routing_reason ELSE NULL END,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
      'linked_timesheet_ids', '[]'::jsonb,
      'linked_scope_recompute_required', true,
      'source_build_required', true,
      'line_work_required', true,
      'line_work_only', false,
      'line_work_action', 'SOURCE_BUILD',
      'force_legacy', false,
      'force_broad_legacy', false,
      'projection_class', CASE
        WHEN v_candidate_route_change IS TRUE THEN 'PAYE_UMBRELLA_SWITCH'
        WHEN v_trigger_table IN ('timesheets', 'timesheets_financials')
             AND (v_authorise_boundary_changed IS TRUE OR v_archive_boundary_changed IS TRUE) THEN 'TIMESHEET_LIFECYCLE'
        ELSE 'DIRTY_TRIGGER'
      END,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );

    IF v_candidate_route_change IS TRUE THEN
      v_payload_json := v_payload_json
        || jsonb_strip_nulls(
          jsonb_build_object(
            'candidate_pay_method_change', true,
            'candidate_payment_status_changed', true,
            'pay_method_changed', true,
            'prospective_only', true,
            'old_pay_method', v_route_source_method,
            'new_pay_method', v_route_target_method,
            'route_change_operation_id', v_route_operation_id,
            'route_change_actor_user_id', v_route_actor_user_id,
            'actor_user_id', v_route_actor_user_id,
            'route_change_reason', COALESCE(v_route_reason, 'PAY_METHOD_CHANGE'),
            'route_change_source_method', v_route_source_method,
            'route_change_target_method', v_route_target_method,
            'authorised_timesheet_ids', v_route_authorised_timesheet_ids,
            'authorised_timesheet_count', v_route_authorised_timesheet_count,
            'active_advance_timesheet_ids', v_route_active_advance_timesheet_ids,
            'active_advance_timesheet_count', v_route_active_advance_timesheet_count,
            'retained_finance_timesheet_ids', v_route_retained_finance_timesheet_ids,
            'retained_finance_timesheet_count', v_route_retained_finance_timesheet_count,
            'source_target_mismatch_count', v_route_source_target_mismatch_count,
            'authoritative_sessions', v_route_authoritative_sessions,
            'replaced_source_session_ids', v_route_replaced_source_session_ids,
            'target_details', v_route_target_details,
            'coverage_basis', COALESCE(v_route_scope_result->>'coverage_basis', 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY'),
            'coverage_complete', v_route_coverage_complete,
            'exact_target_scope', v_route_exact_scope,
            'targeted_scope_is_empty', v_route_targeted_scope_is_empty
          )
          || jsonb_build_object(
            'contracts_changed', 0,
            'contract_weeks_changed', 0,
            'timesheets_changed', 0,
            'rates_changed', 0,
            'tsfin_repricing_rows', 0,
            'source_records_mutated', false,
            'economic_truth_mutation_allowed', false,
            'refresh_completion_requires_terminal_exact_scope', true,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'policy_x_dirtying_only', true
          )
        );
    END IF;

    IF v_candidate_route_change IS TRUE THEN
      v_enqueue_result := jsonb_build_object(
        'ok', true,
        'job_id', v_route_job_id::text,
        'job_type', 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        'status', v_route_job_status,
        'dedupe_key', v_route_dedupe_key,
        'scope_kind', 'CANDIDATE',
        'scope_id', v_candidate_id::text,
        'candidate_id', v_candidate_id::text,
        'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
        'latest_source_change_seq', v_route_job_source_change_seq,
        'exact_target_scope', true,
        'targeted_scope_is_empty', v_route_targeted_scope_is_empty,
        'durable_scope_persisted', true
      );
    ELSE
      SELECT public.pay_workbench_dirty_event_enqueue(
        p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        p_scope_kind => 'CANDIDATE',
        p_scope_id => v_candidate_id::text,
        p_candidate_id => v_candidate_id,
        p_targeted_timesheet_ids => v_targeted_timesheet_ids,
        p_linked_timesheet_ids => ARRAY[]::uuid[],
        p_payload_json => v_payload_json,
        p_reason => v_reason,
        p_priority => -1000,
        p_run_at_utc => v_now
      )
      INTO v_enqueue_result;
    END IF;

    v_jobs_queued := v_jobs_queued + 1;
  END LOOP;

  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN v_targeted_timesheet_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_workbench_mark_candidate_dirty',
      'stage', CASE
        WHEN v_jobs_queued = 0 AND TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN 'return_no_dirty_after_timesheet_financials_insert_coalesced'
        ELSE 'return_enqueued_dirty_priority'
      END,
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'mutation_context', v_lifecycle_context,
      'candidate_count', COALESCE(array_length(v_candidate_ids, 1), 0),
      'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
      'jobs_queued', v_jobs_queued,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
    )
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$function$;

-- public.pay_workbench_scope_blocker_state_v1 from supabase/repeatable/26092026_0203_banking_pay_stage2_workbench_draft_v1.sql; definition SHA-256 b36bd25adcd18d1ba36a4b712da2411a5bd5f42a37278ee2b228c7fecc119eea.
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_blocker_state_v1(p_session_id uuid, p_target_generation bigint, p_operation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_operation public.banking_pay_operations%ROWTYPE;
  v_filter_candidate_id uuid;
  v_filter_client_id uuid;
  v_upstream_active integer := 0;
  v_upstream_failed integer := 0;
  v_session_active integer := 0;
  v_session_failed integer := 0;
  v_broad_pending integer := 0;
  v_unknown_relevance integer := 0;
  v_active_sample jsonb := '[]'::jsonb;
  v_failure_sample jsonb := '[]'::jsonb;
  v_session_active_sample jsonb := '[]'::jsonb;
  v_session_failure_sample jsonb := '[]'::jsonb;
  -- A14 (F-DRAFT-04): read only live / possibly-UNKNOWN generated rows and their complete work-identity
  -- partitions instead of every dirty/fan-out row ever written.
  v_unknown_possible boolean := false;
  v_prefilter_candidate_id uuid := NULL::uuid;
  v_prefilter_path jsonpath := NULL::jsonpath;
  -- A27 (Draft perf)
  v_light boolean := false;
  v_operation_candidate_ids uuid[] := NULL::uuid[];
  v_operation_path jsonpath := NULL::jsonpath;
  v_unknown_terminal integer := 0;
BEGIN
  IF p_session_id IS NULL OR p_target_generation IS NULL OR p_target_generation < 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_BLOCKER_INPUT_INVALID'
      USING ERRCODE = '22023';
  END IF;

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_BLOCKER_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001';
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
      AND operation_row.workbench_session_id = p_session_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_BLOCKER_OPERATION_MISMATCH'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF BTRIM(COALESCE(v_session.filters_json->>'candidate_id', v_session.filters_json->>'candidateId', ''))
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_candidate_id := COALESCE(
      v_session.filters_json->>'candidate_id',
      v_session.filters_json->>'candidateId'
    )::uuid;
  END IF;

  IF BTRIM(COALESCE(v_session.filters_json->>'client_id', v_session.filters_json->>'clientId', ''))
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_client_id := COALESCE(
      v_session.filters_json->>'client_id',
      v_session.filters_json->>'clientId'
    )::uuid;
  END IF;

  -- A27: sessions with no operation and no Candidate filter (unfiltered, or Client-only) take the light path below.
  -- A Client-only filter classifies every dirty-apply row UNKNOWN and unknown_relevance_count counts them over the
  -- whole history; the light path counts the identities made only of SUCCEEDED dirty-apply rows from index columns.
  v_light := p_operation_id IS NULL AND v_filter_candidate_id IS NULL;
  v_unknown_possible := p_operation_id IS NOT NULL OR v_filter_candidate_id IS NOT NULL;
  IF p_operation_id IS NOT NULL THEN
    -- A27: the operation's Candidate set for the live-seed prefilter, and one strict jsonpath that matches a payload
    -- candidate_id / processed_candidate_id / candidate_ids[] string equal (case-insensitively) to one of them. As
    -- A14's Candidate prefilter: the original rule (value ~* uuid pattern AND value::uuid in the set) is a
    -- case-insensitive exact match of a canonical uuid text. An empty set gives no path, so no payload names it.
    SELECT COALESCE(array_agg(DISTINCT operation_scope.candidate_id ORDER BY operation_scope.candidate_id), ARRAY[]::uuid[])
    INTO v_operation_candidate_ids
    FROM public.banking_pay_operation_candidate_scope AS operation_scope
    WHERE operation_scope.operation_id = p_operation_id
      AND operation_scope.candidate_id IS NOT NULL;
    IF cardinality(v_operation_candidate_ids) > 0 THEN
      v_operation_path := format(
        'strict $ ? (@.candidate_id like_regex %1$s flag "i" || @.processed_candidate_id like_regex %1$s flag "i"'
          || ' || exists (@.candidate_ids[*] ? (@ like_regex %1$s flag "i")))',
        to_json('^(' || array_to_string(v_operation_candidate_ids::text[], '|') || ')$')::text
      )::jsonpath;
    END IF;
  END IF;
  IF p_operation_id IS NULL THEN
    v_prefilter_candidate_id := v_filter_candidate_id;
    IF v_prefilter_candidate_id IS NOT NULL THEN
      v_prefilter_path := format(
        'strict $ ? (@.candidate_id like_regex %1$s flag "i" || @.processed_candidate_id like_regex %1$s flag "i"'
          || ' || exists (@.candidate_ids[*] ? (@ like_regex %1$s flag "i")))',
        to_json('^' || v_prefilter_candidate_id::text || '$')::text
      )::jsonpath;
    END IF;
  END IF;

  IF v_light THEN
    -- A27 (Draft perf): no operation and no Candidate filter. Here relevance never reads Candidate evidence
    -- (unfiltered: every row RELEVANT; Client-only: a fan-out by its payload scope, every other row UNKNOWN), and the
    -- evidence is read only by the effective-status rules, which apply to FAILED/DEAD rows only. So ranking uses light
    -- columns, and the full row plus evidence is read only for FAILED/DEAD winners. Classification, ranking,
    -- effective-status rules, counts and samples are A14's text.
    WITH generated_seed_rows AS MATERIALIZED (
      -- (a) every live generated row (as A14).
      SELECT seed_job.id, seed_job.dedupe_key
      FROM public.banking_pay_workbench_jobs AS seed_job
      WHERE seed_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
        AND seed_job.scope_change_generation IS NOT NULL
        AND seed_job.status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD')
        AND seed_job.scope_change_generation <= p_target_generation
      UNION ALL
      -- (b) Client-only: every SUCCEEDED fan-out row (its relevance depends on its payload scope). Identities with no
      --     seed consist only of SUCCEEDED dirty-apply rows; they are counted in (c) below.
      SELECT seed_job.id, seed_job.dedupe_key
      FROM public.banking_pay_workbench_jobs AS seed_job
      WHERE v_filter_client_id IS NOT NULL
        AND seed_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
        AND seed_job.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
        AND seed_job.scope_change_generation IS NOT NULL
        AND seed_job.status = 'SUCCEEDED'
        AND (seed_job.candidate_id IS NULL OR seed_job.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT')
        AND seed_job.scope_change_generation <= p_target_generation
    ), generated_seed_identity AS MATERIALIZED (
      SELECT DISTINCT COALESCE(NULLIF(BTRIM(seed_row.dedupe_key), ''), 'JOB:' || seed_row.id::text) AS work_identity
      FROM generated_seed_rows AS seed_row
    ), generated_partition_ids AS MATERIALIZED (
      -- Complete work-identity partitions of the seeds (ranking is per work identity), so each winner is exact.
      SELECT seed_row.id FROM generated_seed_rows AS seed_row
      UNION
      -- same raw dedupe_key (idx_bpay_workbench_jobs_generated_work_authority)
      SELECT same_key.id
      FROM generated_seed_identity AS seed_identity
      CROSS JOIN LATERAL (
        SELECT key_job.id
        FROM public.banking_pay_workbench_jobs AS key_job
        WHERE key_job.dedupe_key = seed_identity.work_identity
          AND key_job.scope_change_generation IS NOT NULL
          AND key_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
        OFFSET 0
      ) AS same_key
      UNION
      -- dedupe_key with leading/trailing blanks whose BTRIM is the identity (idx_bpay_wb_jobs_generated_padded_key_v1)
      SELECT padded_key.id
      FROM generated_seed_identity AS seed_identity
      CROSS JOIN LATERAL (
        SELECT padded_job.id
        FROM public.banking_pay_workbench_jobs AS padded_job
        WHERE md5(BTRIM(padded_job.dedupe_key)) = md5(seed_identity.work_identity)
          AND BTRIM(padded_job.dedupe_key) = seed_identity.work_identity
          AND padded_job.scope_change_generation IS NOT NULL
          AND padded_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
          AND padded_job.dedupe_key <> BTRIM(padded_job.dedupe_key)
        OFFSET 0
      ) AS padded_key
      UNION
      -- blank dedupe_key: identity 'JOB:' || id (primary key)
      SELECT blank_key.id
      FROM generated_seed_identity AS seed_identity
      CROSS JOIN LATERAL (
        SELECT blank_job.id
        FROM public.banking_pay_workbench_jobs AS blank_job
        WHERE blank_job.id = CASE
            WHEN seed_identity.work_identity ~* '^JOB:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN SUBSTRING(seed_identity.work_identity FROM 5)::uuid
            ELSE NULL::uuid
          END
          AND NULLIF(BTRIM(blank_job.dedupe_key), '') IS NULL
          AND 'JOB:' || blank_job.id::text = seed_identity.work_identity
        OFFSET 0
      ) AS blank_key
    ), generated_light AS MATERIALIZED (
      SELECT job_row.*
      FROM generated_partition_ids AS partition_row
      CROSS JOIN LATERAL (
        SELECT
          partition_job.id,
          partition_job.job_type,
          partition_job.status,
          partition_job.scope_change_generation,
          partition_job.created_at_utc,
          COALESCE(NULLIF(BTRIM(partition_job.dedupe_key), ''), 'JOB:' || partition_job.id::text) AS work_identity,
          CASE
            WHEN v_filter_client_id IS NULL THEN 'RELEVANT'
            -- A14's Client rule gives UNKNOWN to every row that is not a fan-out.
            WHEN partition_job.job_type <> 'CONTRACT_CLIENT_DIRTY_FANOUT' THEN 'UNKNOWN'
            ELSE (
              -- A14's Client rule and scope columns, verbatim, for a fan-out row.
              SELECT
                CASE
                  WHEN generated_raw.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
                   AND generated_raw.scope_kind = 'CLIENT'
                   AND generated_raw.direct_client_id IS NOT NULL
                    THEN CASE WHEN generated_raw.direct_client_id = v_filter_client_id THEN 'RELEVANT' ELSE 'IRRELEVANT' END
                  WHEN generated_raw.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
                   AND generated_raw.scope_kind = 'CONTRACT'
                   AND generated_raw.direct_contract_id IS NOT NULL
                    THEN CASE
                      WHEN EXISTS (
                        SELECT 1
                        FROM public.contracts AS contract_row
                        WHERE contract_row.id = generated_raw.direct_contract_id
                          AND contract_row.client_id = v_filter_client_id
                      ) THEN 'RELEVANT'
                      ELSE 'IRRELEVANT'
                    END
                  ELSE 'UNKNOWN'
                END
              FROM (
                SELECT
                  partition_job.job_type,
                  UPPER(BTRIM(COALESCE(partition_job.payload_json->>'scope_kind', ''))) AS scope_kind,
                  CASE
                    WHEN UPPER(BTRIM(COALESCE(partition_job.payload_json->>'scope_kind', ''))) = 'CLIENT'
                     AND COALESCE(partition_job.payload_json->>'scope_id', partition_job.payload_json->>'client_id', '')
                           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      THEN COALESCE(partition_job.payload_json->>'scope_id', partition_job.payload_json->>'client_id')::uuid
                    ELSE NULL::uuid
                  END AS direct_client_id,
                  CASE
                    WHEN UPPER(BTRIM(COALESCE(partition_job.payload_json->>'scope_kind', ''))) = 'CONTRACT'
                     AND COALESCE(partition_job.payload_json->>'scope_id', partition_job.payload_json->>'contract_id', '')
                           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      THEN COALESCE(partition_job.payload_json->>'scope_id', partition_job.payload_json->>'contract_id')::uuid
                    ELSE NULL::uuid
                  END AS direct_contract_id
              ) AS generated_raw
            )
          END AS relevance_decision
        FROM public.banking_pay_workbench_jobs AS partition_job
        WHERE partition_job.id = partition_row.id
          AND partition_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
          AND partition_job.scope_change_generation IS NOT NULL
          AND partition_job.scope_change_generation <= p_target_generation
          AND partition_job.status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD', 'SUCCEEDED')
        OFFSET 0
      ) AS job_row
    ), generated_winner AS MATERIALIZED (
      SELECT generated_ranked.*
      FROM (
        SELECT
          generated_light.*,
          ROW_NUMBER() OVER (
            -- COLLATE "C": the same partitions (en_US.utf8 is deterministic, so equality is byte equality) with a
            -- byte-wise sort instead of a locale sort; the ORDER BY inside each partition is unchanged.
            PARTITION BY generated_light.work_identity COLLATE "C"
            ORDER BY generated_light.scope_change_generation DESC,
                     generated_light.created_at_utc DESC,
                     generated_light.id DESC
          ) AS authority_ordinal
        FROM generated_light
        WHERE generated_light.relevance_decision <> 'IRRELEVANT'
      ) AS generated_ranked
      WHERE generated_ranked.authority_ordinal = 1
    ), generated_effective AS MATERIALIZED (
      SELECT
        generated_winner.id,
        generated_winner.job_type,
        generated_winner.status,
        generated_winner.scope_change_generation,
        generated_winner.work_identity,
        generated_winner.relevance_decision,
        CASE
          WHEN generated_winner.status IN ('FAILED', 'DEAD') THEN (
            -- A14's effective-status rules, verbatim, on the winner's full row and Candidate evidence.
            SELECT
                CASE
                  -- A terminal row that the normal failure processor has proved obsolete
                  -- is audit history, not current blocking authority.
                  WHEN generated_ranked.status IN ('FAILED', 'DEAD')
                   AND LOWER(BTRIM(COALESCE(generated_ranked.payload_json->>'non_blocking_terminal_failure', 'false'))) = 'true'
                    THEN 'SUCCEEDED'
                  -- A direct dirty-apply failure is also recovered once every candidate
                  -- asserted by that row has subsequently completed and published a
                  -- generation-fenced build for this exact session version.  The
                  -- original FAILED/DEAD row is immutable history and can have a
                  -- different dedupe key from the replacement source build, so ranking
                  -- by work_identity alone cannot establish recovery.  Require the
                  -- registry and completed build to agree on generation and source
                  -- sequence, and require the registry to have no newer dirty work,
                  -- active build or failure authority.  Partial or stale recovery keeps
                  -- the original terminal row blocking.
                  WHEN generated_ranked.status IN ('FAILED', 'DEAD')
                   AND generated_ranked.job_type IN (
                     'WORKBENCH_CANDIDATE_DIRTY_APPLY',
                     'WORKBENCH_FINANCE_CASE_DIRTY_APPLY'
                   )
                   AND COALESCE(array_length(generated_ranked.candidate_ids, 1), 0) > 0
                   AND NOT EXISTS (
                     SELECT 1
                     FROM unnest(generated_ranked.candidate_ids) AS recovered_candidate(candidate_id)
                     WHERE NOT EXISTS (
                       SELECT 1
                       FROM private.banking_pay_workbench_candidate_scope_registry AS recovered_registry
                       JOIN private.banking_pay_workbench_economic_builds AS recovered_build
                         ON recovered_build.candidate_id = recovered_registry.candidate_id
                        AND recovered_build.session_id = p_session_id
                        AND recovered_build.session_version = v_session.version
                        AND recovered_build.captured_candidate_generation = recovered_registry.evaluated_generation
                        AND recovered_build.source_change_seq = recovered_registry.current_source_change_seq
                        AND recovered_build.status = 'COMPLETE'
                        AND recovered_build.private_stage = 'COMPLETE'
                        AND recovered_build.completed_at_utc IS NOT NULL
                        AND recovered_build.completed_at_utc >= generated_ranked.created_at_utc
                       WHERE recovered_registry.candidate_id = recovered_candidate.candidate_id
                         AND recovered_registry.initialisation_status = 'READY'
                         AND recovered_registry.current_build_id IS NULL
                         AND recovered_registry.dirty_generation = recovered_registry.evaluated_generation
                         AND recovered_registry.evaluated_generation >= generated_ranked.scope_change_generation
                         AND COALESCE(recovered_registry.failure_json, '{}'::jsonb) = '{}'::jsonb
                     )
                   ) THEN 'SUCCEEDED'
                  -- Backward compatibility for cancellation jobs written before
                  -- supersessions became successful terminal work. Do not trust the flag
                  -- alone: require the exact legacy code and the replacement full-candidate
                  -- job for this session/batch. The replacement's own active/error state is
                  -- evaluated independently with the session pipeline below.
                  WHEN generated_ranked.status IN ('FAILED', 'DEAD')
                   AND generated_ranked.job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY'
                   AND LOWER(BTRIM(COALESCE(generated_ranked.payload_json->>'superseded_by_cancel_full_candidate_refresh', 'false'))) = 'true'
                   AND UPPER(BTRIM(COALESCE(generated_ranked.last_error_json->>'code', '')))
                         = 'WORKBENCH_FINANCE_DIRTY_SUPERSEDED_BY_CANCEL_FULL_CANDIDATE_REFRESH'
                   AND generated_ranked.payload_json->>'superseding_session_id' = p_session_id::text
                   AND COALESCE(generated_ranked.payload_json->>'superseding_pay_batch_id', '')
                         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                   AND EXISTS (
                     SELECT 1
                     FROM public.banking_pay_workbench_jobs AS replacement_job
                     WHERE replacement_job.session_id = p_session_id
                       AND replacement_job.job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
                       AND replacement_job.created_at_utc >= generated_ranked.created_at_utc
                       AND COALESCE(
                             replacement_job.payload_json->>'pay_batch_id',
                             replacement_job.payload_json#>>'{source_build,pay_batch_id}',
                             ''
                           ) = generated_ranked.payload_json->>'superseding_pay_batch_id'
                       AND UPPER(BTRIM(COALESCE(
                             replacement_job.payload_json->>'refresh_scope_kind',
                             replacement_job.payload_json#>>'{source_build,refresh_scope_kind}',
                             ''
                           ))) = 'CANDIDATE_FULL_LIVE'
                       AND LOWER(BTRIM(COALESCE(
                             replacement_job.payload_json->>'full_candidate_recovery_reallocation_required',
                             'false'
                           ))) = 'true'
                       AND (
                         COALESCE(array_length(generated_ranked.candidate_ids, 1), 0) = 0
                         OR replacement_job.candidate_id = ANY(generated_ranked.candidate_ids)
                       )
                   ) THEN 'SUCCEEDED'
                  ELSE generated_ranked.status
                END
            FROM (
              SELECT failed_job.*, evidence.candidate_ids
              FROM public.banking_pay_workbench_jobs AS failed_job
              CROSS JOIN LATERAL (
                  SELECT COALESCE(array_agg(DISTINCT candidate_source.candidate_id ORDER BY candidate_source.candidate_id), ARRAY[]::uuid[]) AS candidate_ids
                  FROM (
                    SELECT failed_job.candidate_id
                    WHERE failed_job.candidate_id IS NOT NULL
                    UNION ALL
                    SELECT (failed_job.payload_json->>'candidate_id')::uuid
                    WHERE COALESCE(failed_job.payload_json->>'candidate_id', '')
                      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                    UNION ALL
                    SELECT (failed_job.payload_json->>'processed_candidate_id')::uuid
                    WHERE COALESCE(failed_job.payload_json->>'processed_candidate_id', '')
                      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                    UNION ALL
                    SELECT candidate_value.value::uuid
                    FROM jsonb_array_elements_text(
                      CASE
                        WHEN jsonb_typeof(failed_job.payload_json->'candidate_ids') = 'array'
                          THEN failed_job.payload_json->'candidate_ids'
                        ELSE '[]'::jsonb
                      END
                    ) AS candidate_value(value)
                    WHERE candidate_value.value
                      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                  ) AS candidate_source
                ) AS evidence
              WHERE failed_job.id = generated_winner.id
            ) AS generated_ranked
          )
          ELSE generated_winner.status
        END AS effective_status
      FROM generated_winner
    )
    SELECT
      (SELECT COUNT(*)::integer FROM generated_effective WHERE effective_status IN ('QUEUED', 'RUNNING')),
      (SELECT COUNT(*)::integer FROM generated_effective WHERE effective_status IN ('FAILED', 'DEAD')),
      (SELECT COUNT(*)::integer FROM generated_effective
        WHERE job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
          AND effective_status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD')),
      (SELECT COUNT(*)::integer FROM generated_effective WHERE relevance_decision = 'UNKNOWN'),
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'job_id', limited_job.id::text,
          'job_type', limited_job.job_type,
          'status', limited_job.effective_status,
          'scope_change_generation', limited_job.scope_change_generation,
          'dedupe_key', limited_job.work_identity,
          'relevance', limited_job.relevance_decision
        ) ORDER BY limited_job.scope_change_generation, limited_job.id)
        FROM (
          SELECT * FROM generated_effective
          WHERE effective_status IN ('QUEUED', 'RUNNING')
          ORDER BY scope_change_generation, id
          LIMIT 25
        ) AS limited_job
      ), '[]'::jsonb),
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'job_id', limited_job.id::text,
          'job_type', limited_job.job_type,
          'status', limited_job.effective_status,
          'scope_change_generation', limited_job.scope_change_generation,
          'dedupe_key', limited_job.work_identity,
          'relevance', limited_job.relevance_decision
        ) ORDER BY limited_job.scope_change_generation, limited_job.id)
        FROM (
          SELECT * FROM generated_effective
          WHERE effective_status IN ('FAILED', 'DEAD')
          ORDER BY scope_change_generation, id
          LIMIT 25
        ) AS limited_job
      ), '[]'::jsonb)
    INTO
      v_upstream_active,
      v_upstream_failed,
      v_broad_pending,
      v_unknown_relevance,
      v_active_sample,
      v_failure_sample;

    IF v_filter_client_id IS NOT NULL THEN
      -- (c) Client-only: an identity whose every row (up to the target) is a SUCCEEDED dirty-apply row has a SUCCEEDED,
      --     UNKNOWN winner under A14's rules, so it adds exactly one to unknown_relevance_count and nothing else. Every
      --     other identity has a seed in (a) or (b) and was counted above. Index columns only
      --     (idx_bpay_workbench_jobs_generated_work_authority carries dedupe_key, id, job_type, status, generation).
      SELECT COUNT(*)::integer
      INTO v_unknown_terminal
      FROM (
        SELECT COALESCE(NULLIF(BTRIM(history_job.dedupe_key), ''), 'JOB:' || history_job.id::text) AS work_identity
        FROM public.banking_pay_workbench_jobs AS history_job
        WHERE history_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
          AND history_job.scope_change_generation IS NOT NULL
          AND history_job.scope_change_generation <= p_target_generation
          AND history_job.status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD', 'SUCCEEDED')
        GROUP BY 1
        HAVING bool_and(history_job.status = 'SUCCEEDED' AND history_job.job_type <> 'CONTRACT_CLIENT_DIRTY_FANOUT')
      ) AS terminal_identity;
      v_unknown_relevance := COALESCE(v_unknown_relevance, 0) + COALESCE(v_unknown_terminal, 0);
    END IF;
  ELSE
    WITH generated_seed_rows AS MATERIALIZED (
      -- (a) every live generated row. FAILED/DEAD stay here: a terminal failure is still a blocker unless the
      --     unchanged effective-status rules below prove it recovered or superseded.
      --     Candidate-filtered sessions skip rows that are provably IRRELEVANT (the unchanged classification
      --     would drop them before ranking): non-fan-out, with a candidate, whose candidate evidence
      --     (column, payload candidate_id / processed_candidate_id / candidate_ids) excludes the filter.
      SELECT seed_job.id, seed_job.dedupe_key
      FROM public.banking_pay_workbench_jobs AS seed_job
      WHERE seed_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
        AND seed_job.scope_change_generation IS NOT NULL
        AND seed_job.status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD')
        AND seed_job.scope_change_generation <= p_target_generation
          AND (
            v_prefilter_candidate_id IS NULL
            OR seed_job.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
            OR seed_job.candidate_id IS NULL
            OR seed_job.candidate_id = v_prefilter_candidate_id
            -- payload candidate_id / processed_candidate_id / candidate_ids[] naming the filter Candidate: the
            -- original rule (value ~* uuid pattern AND value::uuid = filter) is a case-insensitive exact match of
            -- the filter text; one strict jsonpath pass reads the payload once (non-object payload or non-array
            -- candidate_ids: no match, as in the original).
            OR seed_job.payload_json @? v_prefilter_path
          )
          -- A27: an operation-bound session skips live rows that are provably IRRELEVANT to the operation (the
          -- unchanged classification drops them before ranking): not a fan-out, with a candidate_id outside the
          -- operation's Candidate set, and no payload candidate_id / processed_candidate_id / candidate_ids[] naming a
          -- Candidate of the set (v_operation_path; NULL when the set is empty, so the test is then never true).
          AND (
            v_operation_candidate_ids IS NULL
            OR seed_job.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
            OR seed_job.candidate_id IS NULL
            OR seed_job.candidate_id = ANY(v_operation_candidate_ids)
            OR seed_job.payload_json @? v_operation_path
          )
      UNION ALL
      -- (b) Candidate-filtered or operation-bound sessions only: SUCCEEDED rows whose relevance can be
      --     UNKNOWN (no candidate_id column, or fan-out). unknown_relevance_count counts terminal winners.
      SELECT seed_job.id, seed_job.dedupe_key
      FROM public.banking_pay_workbench_jobs AS seed_job
      WHERE v_unknown_possible
        AND seed_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
        AND seed_job.scope_change_generation IS NOT NULL
        AND seed_job.status = 'SUCCEEDED'
        AND (seed_job.candidate_id IS NULL OR seed_job.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT')
        AND seed_job.scope_change_generation <= p_target_generation
    ), generated_seed_identity AS MATERIALIZED (
      SELECT DISTINCT COALESCE(NULLIF(BTRIM(seed_row.dedupe_key), ''), 'JOB:' || seed_row.id::text) AS work_identity
      FROM generated_seed_rows AS seed_row
    ), generated_partition_ids AS MATERIALIZED (
      -- Complete work-identity partitions of the seeds (ranking is per work identity), so each winner is exact.
      SELECT seed_row.id FROM generated_seed_rows AS seed_row
      UNION
      -- same raw dedupe_key (idx_bpay_workbench_jobs_generated_work_authority)
      SELECT same_key.id
      FROM generated_seed_identity AS seed_identity
      CROSS JOIN LATERAL (
        SELECT key_job.id
        FROM public.banking_pay_workbench_jobs AS key_job
        WHERE key_job.dedupe_key = seed_identity.work_identity
          AND key_job.scope_change_generation IS NOT NULL
          AND key_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
        OFFSET 0
      ) AS same_key
      UNION
      -- dedupe_key with leading/trailing blanks whose BTRIM is the identity (idx_bpay_wb_jobs_generated_padded_key_v1)
      SELECT padded_key.id
      FROM generated_seed_identity AS seed_identity
      CROSS JOIN LATERAL (
        SELECT padded_job.id
        FROM public.banking_pay_workbench_jobs AS padded_job
        WHERE md5(BTRIM(padded_job.dedupe_key)) = md5(seed_identity.work_identity)
          AND BTRIM(padded_job.dedupe_key) = seed_identity.work_identity
          AND padded_job.scope_change_generation IS NOT NULL
          AND padded_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
          AND padded_job.dedupe_key <> BTRIM(padded_job.dedupe_key)
        OFFSET 0
      ) AS padded_key
      UNION
      -- blank dedupe_key: identity 'JOB:' || id (primary key)
      SELECT blank_key.id
      FROM generated_seed_identity AS seed_identity
      CROSS JOIN LATERAL (
        SELECT blank_job.id
        FROM public.banking_pay_workbench_jobs AS blank_job
        WHERE blank_job.id = CASE
            WHEN seed_identity.work_identity ~* '^JOB:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN SUBSTRING(seed_identity.work_identity FROM 5)::uuid
            ELSE NULL::uuid
          END
          AND NULLIF(BTRIM(blank_job.dedupe_key), '') IS NULL
          AND 'JOB:' || blank_job.id::text = seed_identity.work_identity
        OFFSET 0
      ) AS blank_key
    ), generated_raw AS MATERIALIZED (
      SELECT
        job_row.*,
        COALESCE(NULLIF(BTRIM(job_row.dedupe_key), ''), 'JOB:' || job_row.id::text) AS work_identity,
        UPPER(BTRIM(COALESCE(job_row.payload_json->>'scope_kind', ''))) AS scope_kind,
        COALESCE(
          NULLIF(BTRIM(job_row.payload_json->>'scope_id'), ''),
          NULLIF(BTRIM(job_row.payload_json->>'client_id'), ''),
          NULLIF(BTRIM(job_row.payload_json->>'contract_id'), '')
        ) AS direct_scope_id,
        evidence.candidate_ids,
        CASE
          WHEN UPPER(BTRIM(COALESCE(job_row.payload_json->>'scope_kind', ''))) = 'CLIENT'
           AND COALESCE(job_row.payload_json->>'scope_id', job_row.payload_json->>'client_id', '')
                 ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN COALESCE(job_row.payload_json->>'scope_id', job_row.payload_json->>'client_id')::uuid
          ELSE NULL::uuid
        END AS direct_client_id,
        CASE
          WHEN UPPER(BTRIM(COALESCE(job_row.payload_json->>'scope_kind', ''))) = 'CONTRACT'
           AND COALESCE(job_row.payload_json->>'scope_id', job_row.payload_json->>'contract_id', '')
                 ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN COALESCE(job_row.payload_json->>'scope_id', job_row.payload_json->>'contract_id')::uuid
          ELSE NULL::uuid
        END AS direct_contract_id
      FROM generated_partition_ids AS partition_row
      CROSS JOIN LATERAL (
        SELECT partition_job.*
        FROM public.banking_pay_workbench_jobs AS partition_job
        WHERE partition_job.id = partition_row.id
        OFFSET 0
      ) AS job_row
      CROSS JOIN LATERAL (
        SELECT COALESCE(array_agg(DISTINCT candidate_source.candidate_id ORDER BY candidate_source.candidate_id), ARRAY[]::uuid[]) AS candidate_ids
        FROM (
          SELECT job_row.candidate_id
          WHERE job_row.candidate_id IS NOT NULL
          UNION ALL
          SELECT (job_row.payload_json->>'candidate_id')::uuid
          WHERE COALESCE(job_row.payload_json->>'candidate_id', '')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          UNION ALL
          SELECT (job_row.payload_json->>'processed_candidate_id')::uuid
          WHERE COALESCE(job_row.payload_json->>'processed_candidate_id', '')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          UNION ALL
          SELECT candidate_value.value::uuid
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json->'candidate_ids') = 'array'
                THEN job_row.payload_json->'candidate_ids'
              ELSE '[]'::jsonb
            END
          ) AS candidate_value(value)
          WHERE candidate_value.value
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        ) AS candidate_source
      ) AS evidence
      WHERE job_row.job_type IN (
        'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
        'CONTRACT_CLIENT_DIRTY_FANOUT'
      )
        AND job_row.scope_change_generation IS NOT NULL
        AND job_row.scope_change_generation <= p_target_generation
        AND job_row.status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD', 'SUCCEEDED')
    ), generated_classified AS MATERIALIZED (
      SELECT
        generated_raw.*,
        CASE
          WHEN p_operation_id IS NOT NULL THEN
            CASE
              WHEN generated_raw.job_type <> 'CONTRACT_CLIENT_DIRTY_FANOUT' THEN
                CASE
                  WHEN COALESCE(array_length(generated_raw.candidate_ids, 1), 0) = 0 THEN 'UNKNOWN'
                  WHEN EXISTS (
                    SELECT 1
                    FROM public.banking_pay_operation_candidate_scope AS operation_scope
                    WHERE operation_scope.operation_id = p_operation_id
                      AND operation_scope.candidate_id = ANY(generated_raw.candidate_ids)
                  ) THEN 'RELEVANT'
                  ELSE 'IRRELEVANT'
                END
              WHEN generated_raw.scope_kind = 'CANDIDATE'
               AND COALESCE(array_length(generated_raw.candidate_ids, 1), 0) > 0 THEN
                CASE
                  WHEN EXISTS (
                    SELECT 1
                    FROM public.banking_pay_operation_candidate_scope AS operation_scope
                    WHERE operation_scope.operation_id = p_operation_id
                      AND operation_scope.candidate_id = ANY(generated_raw.candidate_ids)
                  ) THEN 'RELEVANT'
                  ELSE 'IRRELEVANT'
                END
              ELSE 'UNKNOWN'
            END
          WHEN v_filter_candidate_id IS NOT NULL THEN
            CASE
              WHEN generated_raw.job_type <> 'CONTRACT_CLIENT_DIRTY_FANOUT' THEN
                CASE
                  WHEN COALESCE(array_length(generated_raw.candidate_ids, 1), 0) = 0 THEN 'UNKNOWN'
                  WHEN v_filter_candidate_id = ANY(generated_raw.candidate_ids) THEN 'RELEVANT'
                  ELSE 'IRRELEVANT'
                END
              WHEN generated_raw.scope_kind = 'CANDIDATE'
               AND COALESCE(array_length(generated_raw.candidate_ids, 1), 0) > 0 THEN
                CASE WHEN v_filter_candidate_id = ANY(generated_raw.candidate_ids) THEN 'RELEVANT' ELSE 'IRRELEVANT' END
              ELSE 'UNKNOWN'
            END
          WHEN v_filter_client_id IS NOT NULL THEN
            CASE
              WHEN generated_raw.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
               AND generated_raw.scope_kind = 'CLIENT'
               AND generated_raw.direct_client_id IS NOT NULL
                THEN CASE WHEN generated_raw.direct_client_id = v_filter_client_id THEN 'RELEVANT' ELSE 'IRRELEVANT' END
              WHEN generated_raw.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
               AND generated_raw.scope_kind = 'CONTRACT'
               AND generated_raw.direct_contract_id IS NOT NULL
                THEN CASE
                  WHEN EXISTS (
                    SELECT 1
                    FROM public.contracts AS contract_row
                    WHERE contract_row.id = generated_raw.direct_contract_id
                      AND contract_row.client_id = v_filter_client_id
                  ) THEN 'RELEVANT'
                  ELSE 'IRRELEVANT'
                END
              ELSE 'UNKNOWN'
            END
          ELSE 'RELEVANT'
        END AS relevance_decision
      FROM generated_raw
    ), generated_ranked AS MATERIALIZED (
      SELECT
        generated_classified.*,
        ROW_NUMBER() OVER (
          -- A27: COLLATE "C" gives the same partitions (deterministic collation: equality is byte equality) with a
          -- byte-wise sort; the ORDER BY inside each partition is unchanged.
          PARTITION BY generated_classified.work_identity COLLATE "C"
          ORDER BY generated_classified.scope_change_generation DESC,
                   generated_classified.created_at_utc DESC,
                   generated_classified.id DESC
        ) AS authority_ordinal
      FROM generated_classified
      WHERE generated_classified.relevance_decision <> 'IRRELEVANT'
    ), generated_effective AS MATERIALIZED (
      SELECT
        generated_ranked.*,
        CASE
          -- A terminal row that the normal failure processor has proved obsolete
          -- is audit history, not current blocking authority.
          WHEN generated_ranked.status IN ('FAILED', 'DEAD')
           AND LOWER(BTRIM(COALESCE(generated_ranked.payload_json->>'non_blocking_terminal_failure', 'false'))) = 'true'
            THEN 'SUCCEEDED'
          -- A direct dirty-apply failure is also recovered once every candidate
          -- asserted by that row has subsequently completed and published a
          -- generation-fenced build for this exact session version.  The
          -- original FAILED/DEAD row is immutable history and can have a
          -- different dedupe key from the replacement source build, so ranking
          -- by work_identity alone cannot establish recovery.  Require the
          -- registry and completed build to agree on generation and source
          -- sequence, and require the registry to have no newer dirty work,
          -- active build or failure authority.  Partial or stale recovery keeps
          -- the original terminal row blocking.
          WHEN generated_ranked.status IN ('FAILED', 'DEAD')
           AND generated_ranked.job_type IN (
             'WORKBENCH_CANDIDATE_DIRTY_APPLY',
             'WORKBENCH_FINANCE_CASE_DIRTY_APPLY'
           )
           AND COALESCE(array_length(generated_ranked.candidate_ids, 1), 0) > 0
           AND NOT EXISTS (
             SELECT 1
             FROM unnest(generated_ranked.candidate_ids) AS recovered_candidate(candidate_id)
             WHERE NOT EXISTS (
               SELECT 1
               FROM private.banking_pay_workbench_candidate_scope_registry AS recovered_registry
               JOIN private.banking_pay_workbench_economic_builds AS recovered_build
                 ON recovered_build.candidate_id = recovered_registry.candidate_id
                AND recovered_build.session_id = p_session_id
                AND recovered_build.session_version = v_session.version
                AND recovered_build.captured_candidate_generation = recovered_registry.evaluated_generation
                AND recovered_build.source_change_seq = recovered_registry.current_source_change_seq
                AND recovered_build.status = 'COMPLETE'
                AND recovered_build.private_stage = 'COMPLETE'
                AND recovered_build.completed_at_utc IS NOT NULL
                AND recovered_build.completed_at_utc >= generated_ranked.created_at_utc
               WHERE recovered_registry.candidate_id = recovered_candidate.candidate_id
                 AND recovered_registry.initialisation_status = 'READY'
                 AND recovered_registry.current_build_id IS NULL
                 AND recovered_registry.dirty_generation = recovered_registry.evaluated_generation
                 AND recovered_registry.evaluated_generation >= generated_ranked.scope_change_generation
                 AND COALESCE(recovered_registry.failure_json, '{}'::jsonb) = '{}'::jsonb
             )
           ) THEN 'SUCCEEDED'
          -- Backward compatibility for cancellation jobs written before
          -- supersessions became successful terminal work. Do not trust the flag
          -- alone: require the exact legacy code and the replacement full-candidate
          -- job for this session/batch. The replacement's own active/error state is
          -- evaluated independently with the session pipeline below.
          WHEN generated_ranked.status IN ('FAILED', 'DEAD')
           AND generated_ranked.job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY'
           AND LOWER(BTRIM(COALESCE(generated_ranked.payload_json->>'superseded_by_cancel_full_candidate_refresh', 'false'))) = 'true'
           AND UPPER(BTRIM(COALESCE(generated_ranked.last_error_json->>'code', '')))
                 = 'WORKBENCH_FINANCE_DIRTY_SUPERSEDED_BY_CANCEL_FULL_CANDIDATE_REFRESH'
           AND generated_ranked.payload_json->>'superseding_session_id' = p_session_id::text
           AND COALESCE(generated_ranked.payload_json->>'superseding_pay_batch_id', '')
                 ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           AND EXISTS (
             SELECT 1
             FROM public.banking_pay_workbench_jobs AS replacement_job
             WHERE replacement_job.session_id = p_session_id
               AND replacement_job.job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
               AND replacement_job.created_at_utc >= generated_ranked.created_at_utc
               AND COALESCE(
                     replacement_job.payload_json->>'pay_batch_id',
                     replacement_job.payload_json#>>'{source_build,pay_batch_id}',
                     ''
                   ) = generated_ranked.payload_json->>'superseding_pay_batch_id'
               AND UPPER(BTRIM(COALESCE(
                     replacement_job.payload_json->>'refresh_scope_kind',
                     replacement_job.payload_json#>>'{source_build,refresh_scope_kind}',
                     ''
                   ))) = 'CANDIDATE_FULL_LIVE'
               AND LOWER(BTRIM(COALESCE(
                     replacement_job.payload_json->>'full_candidate_recovery_reallocation_required',
                     'false'
                   ))) = 'true'
               AND (
                 COALESCE(array_length(generated_ranked.candidate_ids, 1), 0) = 0
                 OR replacement_job.candidate_id = ANY(generated_ranked.candidate_ids)
               )
           ) THEN 'SUCCEEDED'
          ELSE generated_ranked.status
        END AS effective_status
      FROM generated_ranked
      WHERE authority_ordinal = 1
    )
    SELECT
      (SELECT COUNT(*)::integer FROM generated_effective WHERE effective_status IN ('QUEUED', 'RUNNING')),
      (SELECT COUNT(*)::integer FROM generated_effective WHERE effective_status IN ('FAILED', 'DEAD')),
      (SELECT COUNT(*)::integer FROM generated_effective
        WHERE job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
          AND effective_status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD')),
      (SELECT COUNT(*)::integer FROM generated_effective WHERE relevance_decision = 'UNKNOWN'),
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'job_id', limited_job.id::text,
          'job_type', limited_job.job_type,
          'status', limited_job.effective_status,
          'scope_change_generation', limited_job.scope_change_generation,
          'dedupe_key', limited_job.work_identity,
          'relevance', limited_job.relevance_decision
        ) ORDER BY limited_job.scope_change_generation, limited_job.id)
        FROM (
          SELECT * FROM generated_effective
          WHERE effective_status IN ('QUEUED', 'RUNNING')
          ORDER BY scope_change_generation, id
          LIMIT 25
        ) AS limited_job
      ), '[]'::jsonb),
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'job_id', limited_job.id::text,
          'job_type', limited_job.job_type,
          'status', limited_job.effective_status,
          'scope_change_generation', limited_job.scope_change_generation,
          'dedupe_key', limited_job.work_identity,
          'relevance', limited_job.relevance_decision
        ) ORDER BY limited_job.scope_change_generation, limited_job.id)
        FROM (
          SELECT * FROM generated_effective
          WHERE effective_status IN ('FAILED', 'DEAD')
          ORDER BY scope_change_generation, id
          LIMIT 25
        ) AS limited_job
      ), '[]'::jsonb)
    INTO
      v_upstream_active,
      v_upstream_failed,
      v_broad_pending,
      v_unknown_relevance,
      v_active_sample,
      v_failure_sample;
  END IF;

  -- Session job rows are immutable execution history. Their raw FAILED/DEAD
  -- status is not durable readiness authority because a later current-state
  -- rebuild may have recovered the candidate under a different dedupe key.
  -- Active work remains a blocker. Terminal failure authority is held by the
  -- session's recomputed scope/line failure counters, which the worker updates
  -- from current candidate state and clears after a successful recovery.
  WITH session_active AS MATERIALIZED (
    SELECT
      session_job.*,
      COALESCE(NULLIF(BTRIM(session_job.dedupe_key), ''), 'JOB:' || session_job.id::text) AS work_identity
    FROM public.banking_pay_workbench_jobs AS session_job
    WHERE session_job.session_id = p_session_id
      AND session_job.job_type IN (
        'WORKBENCH_SESSION_SCOPE_SEED',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'WORKBENCH_SESSION_CLONE_REBASE',
        'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
        'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
        'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
      )
      AND session_job.status IN ('QUEUED', 'RUNNING')
  )
  SELECT
    (SELECT COUNT(*)::integer FROM session_active),
    0::integer,
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'job_id', limited_job.id::text,
        'job_type', limited_job.job_type,
        'status', limited_job.status,
        'dedupe_key', limited_job.work_identity
      ) ORDER BY limited_job.created_at_utc, limited_job.id)
      FROM (
        SELECT * FROM session_active
        ORDER BY created_at_utc, id
        LIMIT 25
      ) AS limited_job
    ), '[]'::jsonb),
    '[]'::jsonb
  INTO
    v_session_active,
    v_session_failed,
    v_session_active_sample,
    v_session_failure_sample;

  SELECT COALESCE(jsonb_agg(sample_row.value ORDER BY sample_row.ordinality), '[]'::jsonb)
  INTO v_active_sample
  FROM jsonb_array_elements(COALESCE(v_active_sample, '[]'::jsonb) || COALESCE(v_session_active_sample, '[]'::jsonb))
       WITH ORDINALITY AS sample_row(value, ordinality)
  WHERE sample_row.ordinality <= 25;

  SELECT COALESCE(jsonb_agg(sample_row.value ORDER BY sample_row.ordinality), '[]'::jsonb)
  INTO v_failure_sample
  FROM jsonb_array_elements(COALESCE(v_failure_sample, '[]'::jsonb) || COALESCE(v_session_failure_sample, '[]'::jsonb))
       WITH ORDINALITY AS sample_row(value, ordinality)
  WHERE sample_row.ordinality <= 25;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'target_generation', p_target_generation,
    'upstream_active_count', COALESCE(v_upstream_active, 0),
    'upstream_unresolved_failure_count', COALESCE(v_upstream_failed, 0),
    'session_active_count', COALESCE(v_session_active, 0),
    'session_unresolved_failure_count', COALESCE(v_session_failed, 0),
    'session_scope_failed_count', COALESCE(v_session.scope_failed_count, 0),
    'session_line_failed_count', COALESCE(v_session.line_units_failed, 0),
    'broad_root_pending_count', COALESCE(v_broad_pending, 0),
    'unknown_relevance_count', COALESCE(v_unknown_relevance, 0),
    'active_sample', COALESCE(v_active_sample, '[]'::jsonb),
    'failure_sample', COALESCE(v_failure_sample, '[]'::jsonb),
    'all_clear',
      COALESCE(v_upstream_active, 0) = 0
      AND COALESCE(v_upstream_failed, 0) = 0
      AND COALESCE(v_session_active, 0) = 0
      AND COALESCE(v_session_failed, 0) = 0
      AND COALESCE(v_session.scope_failed_count, 0) = 0
      AND COALESCE(v_session.line_units_failed, 0) = 0
  );
END;
$function$;

-- public.pay_workbench_scope_reconcile_drain_one_v1 from supabase/repeatable/26092026_0203_banking_pay_stage2_workbench_draft_v1.sql; definition SHA-256 5da010b265f0f3d14d1e8522b739dbe0c464c32f2d1077f070e8c395d3858495.
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_reconcile_drain_one_v1(p_candidate_limit integer DEFAULT 25, p_worker_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_limit integer := LEAST(GREATEST(COALESCE(p_candidate_limit, 25), 1), 50);
  v_job public.banking_pay_workbench_jobs%ROWTYPE;
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_enabled boolean := true;
  v_config_shadow boolean := false;
  v_mode text := 'AUTHORITATIVE';
  v_target bigint := 0;
  v_current_generation bigint := 0;
  v_base_generation bigint := 0;
  v_cursor_generation bigint := 0;
  v_cursor_entity_key text := '';
  v_page_count integer := 0;
  v_has_more boolean := false;
  v_last_generation bigint := 0;
  v_last_entity_key text := '';
  v_shortlist jsonb := '[]'::jsonb;
  v_admission jsonb := '{}'::jsonb;
  v_eligible jsonb := '[]'::jsonb;
  v_inserted jsonb := '[]'::jsonb;
  v_inserted_count integer := 0;
  v_enqueue jsonb := '{}'::jsonb;
  v_blocker jsonb := '{}'::jsonb;
  v_upstream_active integer := 0;
  v_upstream_failed integer := 0;
  v_more_sessions boolean := false;
  v_already_in_scope integer := 0;
  v_would_admit integer := 0;
  v_would_reject integer := 0;
  v_shadow_summary jsonb := '{}'::jsonb;
  v_shadow_previous jsonb := '{}'::jsonb;
  v_shadow_sample jsonb := '[]'::jsonb;
  v_error_message text;
  v_error_detail text;
  v_error_state text;
BEGIN
  SELECT queued_job.*
  INTO v_job
  FROM public.banking_pay_workbench_jobs AS queued_job
  WHERE UPPER(BTRIM(COALESCE(queued_job.job_type, ''))) = 'WORKBENCH_SCOPE_RECONCILE'
    AND queued_job.status = 'QUEUED'
    AND queued_job.run_at_utc <= v_now
  ORDER BY queued_job.priority, queued_job.run_at_utc, queued_job.created_at_utc, queued_job.id
  FOR UPDATE SKIP LOCKED
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'processed', false, 'reason', 'NO_DUE_COORDINATOR');
  END IF;

  UPDATE public.banking_pay_workbench_jobs AS claimed_job
  SET status = 'RUNNING',
      started_at_utc = v_now,
      updated_at_utc = v_now,
      payload_json = COALESCE(claimed_job.payload_json, '{}'::jsonb)
        || jsonb_build_object('worker_id', COALESCE(NULLIF(BTRIM(p_worker_id), ''), 'SCOPE_RECONCILE'))
  WHERE claimed_job.id = v_job.id
  RETURNING claimed_job.* INTO v_job;

  BEGIN
    SELECT
      COALESCE(settings_row.banking_pay_workbench_scope_reconcile_enabled, true),
      COALESCE(settings_row.banking_pay_workbench_scope_reconcile_shadow_mode, false)
    INTO v_enabled, v_config_shadow
    FROM public.settings_defaults AS settings_row
    ORDER BY settings_row.id
    LIMIT 1;

    IF NOT COALESCE(v_enabled, true) THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'SUCCEEDED',
          completed_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object('completion_reason', 'SCOPE_RECONCILIATION_DISABLED'),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object('ok', true, 'processed', true, 'status', 'SUCCEEDED', 'reason', 'SCOPE_RECONCILIATION_DISABLED');
    END IF;

    v_mode := UPPER(BTRIM(COALESCE(
      v_job.payload_json->>'reconcile_mode',
      CASE WHEN v_config_shadow THEN 'SHADOW' ELSE 'AUTHORITATIVE' END
    )));
    IF v_mode NOT IN ('SHADOW', 'AUTHORITATIVE') THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_RECONCILE_MODE_INVALID'
        USING ERRCODE = '22023';
    END IF;

    IF v_config_shadow AND v_mode = 'AUTHORITATIVE' THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          payload_json = (COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            - 'active_session_id' - 'cursor_generation' - 'cursor_entity_key')
            || jsonb_build_object('reconcile_mode', 'SHADOW', 'shadow_mode', true),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object('ok', true, 'processed', true, 'status', 'QUEUED', 'reason', 'CONVERTED_TO_SHADOW');
    END IF;

    v_current_generation := public.pay_workbench_scope_current_generation_v1();
    v_target := CASE
      WHEN COALESCE(v_job.payload_json->>'target_generation', '') ~ '^\d+$'
        THEN (v_job.payload_json->>'target_generation')::bigint
      ELSE 0
    END;
    v_target := GREATEST(v_target, v_current_generation);

    UPDATE public.banking_pay_workbench_jobs AS coordinator_job
    SET scope_change_generation = v_target,
        payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
          || jsonb_build_object('target_generation', v_target, 'reconcile_mode', v_mode),
        updated_at_utc = v_now
    WHERE coordinator_job.id = v_job.id;

    IF COALESCE(v_job.payload_json->>'active_session_id', '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      SELECT session_row.*
      INTO v_session
      FROM public.banking_pay_workbench_sessions AS session_row
      WHERE session_row.id = (v_job.payload_json->>'active_session_id')::uuid
        AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
        AND session_row.discarded_at_utc IS NULL
        AND session_row.replacement_session_id IS NULL
        AND COALESCE(session_row.scope_seed_complete, false)
        AND (
          (v_mode = 'SHADOW' AND COALESCE(session_row.scope_change_generation_shadow_checked, 0) < v_target)
          OR
          (v_mode = 'AUTHORITATIVE' AND COALESCE(session_row.scope_change_generation_applied, 0) < v_target)
        )
      FOR UPDATE;
    END IF;

    IF v_session.id IS NULL THEN
      SELECT session_row.*
      INTO v_session
      FROM public.banking_pay_workbench_sessions AS session_row
      WHERE UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
        AND session_row.discarded_at_utc IS NULL
        AND session_row.replacement_session_id IS NULL
        AND COALESCE(session_row.scope_seed_complete, false)
        AND (
          (v_mode = 'SHADOW' AND COALESCE(session_row.scope_change_generation_shadow_checked, 0) < v_target)
          OR
          (v_mode = 'AUTHORITATIVE' AND COALESCE(session_row.scope_change_generation_applied, 0) < v_target)
        )
      ORDER BY session_row.session_signature, session_row.id
      FOR UPDATE SKIP LOCKED
      LIMIT 1;
    END IF;
    IF v_session.id IS NULL THEN
      SELECT generation_counter.seq
      INTO v_current_generation
      FROM public.app_change_counters AS generation_counter
      WHERE generation_counter.entity_key = 'pay_candidate_scope_generation'
      FOR UPDATE;

      SELECT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_sessions AS lagging_session
        WHERE UPPER(BTRIM(COALESCE(lagging_session.status, ''))) = 'OPEN'
          AND lagging_session.discarded_at_utc IS NULL
          AND lagging_session.replacement_session_id IS NULL
          AND COALESCE(lagging_session.scope_seed_complete, false)
          AND (
            (v_mode = 'SHADOW' AND COALESCE(lagging_session.scope_change_generation_shadow_checked, 0) < v_current_generation)
            OR
            (v_mode = 'AUTHORITATIVE' AND COALESCE(lagging_session.scope_change_generation_applied, 0) < v_current_generation)
          )
      ) INTO v_more_sessions;

      IF v_current_generation > v_target OR v_more_sessions THEN
        UPDATE public.banking_pay_workbench_jobs AS coordinator_job
        SET status = 'QUEUED',
            run_at_utc = v_now,
            started_at_utc = NULL::timestamptz,
            failed_at_utc = NULL::timestamptz,
            last_error_json = NULL::jsonb,
            payload_json = (COALESCE(coordinator_job.payload_json, '{}'::jsonb)
              - 'active_session_id' - 'cursor_generation' - 'cursor_entity_key')
              || jsonb_build_object('target_generation', v_current_generation, 'reconcile_mode', v_mode),
            scope_change_generation = v_current_generation,
            updated_at_utc = v_now
        WHERE coordinator_job.id = v_job.id;
        RETURN jsonb_build_object('ok', true, 'processed', true, 'status', 'QUEUED', 'reason', 'NEW_GENERATION_OR_SESSION_LAG');
      END IF;

      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'SUCCEEDED',
          completed_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          failed_at_utc = NULL::timestamptz,
          last_error_json = NULL::jsonb,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object('completed_generation', v_target, 'completed_mode', v_mode),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object(
        'ok', true, 'processed', true, 'status', 'SUCCEEDED',
        'target_generation', v_target, 'reconcile_mode', v_mode
      );
    END IF;

    v_base_generation := CASE
      WHEN v_mode = 'SHADOW' THEN COALESCE(v_session.scope_change_generation_shadow_checked, 0)
      ELSE COALESCE(v_session.scope_change_generation_applied, 0)
    END;
    v_cursor_generation := CASE
      WHEN COALESCE(v_job.payload_json->>'cursor_generation', '') ~ '^\d+$'
        THEN (v_job.payload_json->>'cursor_generation')::bigint
      ELSE v_base_generation
    END;
    v_cursor_entity_key := COALESCE(v_job.payload_json->>'cursor_entity_key', '');

    UPDATE public.banking_pay_workbench_sessions AS session_update
    SET scope_change_generation_target = CASE
          WHEN v_mode = 'AUTHORITATIVE' THEN v_target
          ELSE session_update.scope_change_generation_target
        END,
        progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'scope_reconcile_status', CASE WHEN v_mode = 'SHADOW' THEN 'SHADOW_RUNNING' ELSE 'RUNNING' END,
            'scope_reconcile_mode', v_mode,
            'scope_change_generation_target', v_target,
            'scope_change_generation_applied', COALESCE(session_update.scope_change_generation_applied, 0),
            'scope_change_generation_shadow_checked', COALESCE(session_update.scope_change_generation_shadow_checked, 0)
          ),
        updated_at_utc = v_now
    WHERE session_update.id = v_session.id;

    v_blocker := public.pay_workbench_scope_blocker_state_v1(v_session.id, v_target, NULL::uuid);
    v_upstream_active := COALESCE((v_blocker->>'upstream_active_count')::integer, 0);
    v_upstream_failed := COALESCE((v_blocker->>'upstream_unresolved_failure_count')::integer, 0);

    IF v_upstream_failed > 0 THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now + interval '30 seconds',
          started_at_utc = NULL::timestamptz,
          last_error_json = jsonb_build_object(
            'code', 'PAY_WORKBENCH_SCOPE_RECONCILIATION_UPSTREAM_FAILED',
            'failure_sample', COALESCE(v_blocker->'failure_sample', '[]'::jsonb),
            'target_generation', v_target
          ),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object(
        'ok', false, 'processed', true, 'status', 'QUEUED',
        'reason', 'UPSTREAM_SCOPE_FAILURE_UNRESOLVED',
        'target_generation', v_target,
        'failure_sample', COALESCE(v_blocker->'failure_sample', '[]'::jsonb)
      );
    END IF;

    -- A previously observed blocker may have recovered under the promoted
    -- generation target. Clear stale coordinator error evidence before waiting
    -- for active work or processing the next bounded page.
    UPDATE public.banking_pay_workbench_jobs AS recovered_coordinator
    SET failed_at_utc = NULL::timestamptz,
        last_error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE recovered_coordinator.id = v_job.id;

    IF v_upstream_active > 0 THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now + interval '1 second',
          started_at_utc = NULL::timestamptz,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'target_generation', v_target,
              'active_session_id', v_session.id::text,
              'upstream_wait_count', v_upstream_active
            ),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object(
        'ok', true, 'processed', true, 'status', 'QUEUED',
        'reason', 'WAITING_FOR_UPSTREAM', 'upstream_count', v_upstream_active
      );
    END IF;

    DROP TABLE IF EXISTS pg_temp._bpay_scope_reconcile_page;
    CREATE TEMP TABLE _bpay_scope_reconcile_page ON COMMIT DROP AS
    SELECT candidate_change.entity_key,
           candidate_change.scope_change_generation,
           SUBSTRING(candidate_change.entity_key FROM 15)::uuid AS candidate_id,
           ROW_NUMBER() OVER (
             ORDER BY candidate_change.scope_change_generation, candidate_change.entity_key
           ) AS page_ordinal
    FROM public.app_change_counters AS candidate_change
    WHERE candidate_change.entity_key LIKE 'pay_candidate:%'
      AND candidate_change.entity_key
            ~* '^pay_candidate:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND candidate_change.scope_change_generation > v_base_generation
      AND candidate_change.scope_change_generation <= v_target
      AND (
        candidate_change.scope_change_generation > v_cursor_generation
        OR (
          candidate_change.scope_change_generation = v_cursor_generation
          AND candidate_change.entity_key > v_cursor_entity_key
        )
      )
    ORDER BY candidate_change.scope_change_generation, candidate_change.entity_key
    LIMIT (v_limit + 1);

    SELECT COUNT(*)::integer,
           EXISTS (SELECT 1 FROM pg_temp._bpay_scope_reconcile_page WHERE page_ordinal > v_limit)
    INTO v_page_count, v_has_more
    FROM pg_temp._bpay_scope_reconcile_page
    WHERE page_ordinal <= v_limit;

    SELECT COUNT(*)::integer
    INTO v_already_in_scope
    FROM pg_temp._bpay_scope_reconcile_page AS page_row
    WHERE page_row.page_ordinal <= v_limit
      AND EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_session_scope AS existing_scope
        WHERE existing_scope.session_id = v_session.id
          AND existing_scope.candidate_id = page_row.candidate_id
      );

    SELECT COALESCE(
             jsonb_agg(to_jsonb(page_row.candidate_id::text) ORDER BY page_row.page_ordinal),
             '[]'::jsonb
           )
    INTO v_shortlist
    FROM pg_temp._bpay_scope_reconcile_page AS page_row
    WHERE page_row.page_ordinal <= v_limit
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_session_scope AS existing_scope
        WHERE existing_scope.session_id = v_session.id
          AND existing_scope.candidate_id = page_row.candidate_id
      );

    IF jsonb_array_length(v_shortlist) > 0 THEN
      v_admission := public.pay_workbench_scope_admission_candidates_v1(
        v_session.id,
        v_shortlist,
        v_target
      );
      v_eligible := CASE
        WHEN jsonb_typeof(v_admission->'candidate_ids') = 'array' THEN v_admission->'candidate_ids'
        ELSE '[]'::jsonb
      END;
    ELSE
      v_eligible := '[]'::jsonb;
    END IF;

    v_would_admit := jsonb_array_length(v_eligible);
    v_would_reject := GREATEST(jsonb_array_length(v_shortlist) - v_would_admit, 0);
    IF v_mode = 'AUTHORITATIVE' AND v_would_admit > 0 THEN
      WITH input_candidates AS (
        SELECT DISTINCT candidate_value.value::uuid AS candidate_id
        FROM jsonb_array_elements_text(v_eligible) AS candidate_value(value)
      ), base_ordinal AS (
        SELECT COALESCE(MAX(scope_row.scope_ordinal), 0)::bigint AS value
        FROM public.banking_pay_workbench_session_scope AS scope_row
        WHERE scope_row.session_id = v_session.id
      ), inserted_scope AS (
        INSERT INTO public.banking_pay_workbench_session_scope(
          session_id, candidate_id, scope_ordinal, status, pending_job_id,
          seeded, dirty, error_json, created_at_utc, updated_at_utc
        )
        SELECT v_session.id,
               input_candidates.candidate_id,
               base_ordinal.value + ROW_NUMBER() OVER (ORDER BY input_candidates.candidate_id),
               'PENDING', NULL::uuid, true, false, NULL::jsonb, v_now, v_now
        FROM input_candidates
        CROSS JOIN base_ordinal
        ON CONFLICT (session_id, candidate_id) DO NOTHING
        RETURNING candidate_id
      )
      SELECT COUNT(*)::integer,
             COALESCE(
               jsonb_agg(to_jsonb(inserted_scope.candidate_id::text) ORDER BY inserted_scope.candidate_id),
               '[]'::jsonb
             )
      INTO v_inserted_count, v_inserted
      FROM inserted_scope;

      IF v_inserted_count > 0 THEN
        v_enqueue := public.pay_workbench_enqueue_candidate_refresh_many(
          p_session_id => v_session.id,
          p_candidate_ids => v_inserted,
          p_reason => 'CONTINUOUS_SCOPE_RECONCILE_ADMISSION',
          p_actor_user_id => v_session.actor_user_id
        );
      END IF;
    END IF;

    SELECT page_row.scope_change_generation, page_row.entity_key
    INTO v_last_generation, v_last_entity_key
    FROM pg_temp._bpay_scope_reconcile_page AS page_row
    WHERE page_row.page_ordinal <= v_limit
    ORDER BY page_row.page_ordinal DESC
    LIMIT 1;

    v_shadow_previous := CASE
      WHEN jsonb_typeof(v_job.payload_json->'shadow_accumulator') = 'object'
        THEN v_job.payload_json->'shadow_accumulator'
      ELSE '{}'::jsonb
    END;

    SELECT COALESCE(jsonb_agg(sample_row.value ORDER BY sample_row.ordinality), '[]'::jsonb)
    INTO v_shadow_sample
    FROM jsonb_array_elements(
      COALESCE(v_shadow_previous->'candidate_sample', '[]'::jsonb)
      || COALESCE((
        SELECT jsonb_agg(to_jsonb(sample_candidate.value) ORDER BY sample_candidate.ordinality)
        FROM jsonb_array_elements_text(v_shortlist)
             WITH ORDINALITY AS sample_candidate(value, ordinality)
        WHERE sample_candidate.ordinality <= 25
      ), '[]'::jsonb)
    ) WITH ORDINALITY AS sample_row(value, ordinality)
    WHERE sample_row.ordinality <= 25;

    v_shadow_summary := jsonb_build_object(
      'target_generation', v_target,
      'candidates_considered', COALESCE((v_shadow_previous->>'candidates_considered')::integer, 0) + v_page_count,
      'already_in_scope', COALESCE((v_shadow_previous->>'already_in_scope')::integer, 0) + v_already_in_scope,
      'would_admit', COALESCE((v_shadow_previous->>'would_admit')::integer, 0) + v_would_admit,
      'would_reject', COALESCE((v_shadow_previous->>'would_reject')::integer, 0) + v_would_reject,
      'would_enqueue_refresh', COALESCE((v_shadow_previous->>'would_enqueue_refresh')::integer, 0) + v_would_admit,
      'candidate_sample', v_shadow_sample,
      'decision_hash', encode(
        extensions.digest(
          convert_to(v_shortlist::text || '|' || v_eligible::text || '|' || v_target::text, 'UTF8'),
          'sha256'
        ),
        'hex'
      )
    );

    IF v_has_more THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          failed_at_utc = NULL::timestamptz,
          last_error_json = NULL::jsonb,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'target_generation', v_target,
              'active_session_id', v_session.id::text,
              'cursor_generation', v_last_generation,
              'cursor_entity_key', v_last_entity_key,
              'candidate_limit', v_limit,
              'reconcile_mode', v_mode,
              'shadow_accumulator', CASE
                WHEN v_mode = 'SHADOW' THEN v_shadow_summary
                ELSE NULL::jsonb
              END,
              'last_shadow_page', CASE
                WHEN v_mode = 'SHADOW' THEN v_shadow_summary
                ELSE NULL::jsonb
              END
            ),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;

      RETURN jsonb_build_object(
        'ok', true,
        'processed', true,
        'status', 'QUEUED',
        'reconcile_mode', v_mode,
        'session_id', v_session.id::text,
        'target_generation', v_target,
        'page_count', v_page_count,
        'admitted_count', CASE WHEN v_mode = 'AUTHORITATIVE' THEN v_inserted_count ELSE 0 END,
        'shadow_summary', CASE WHEN v_mode = 'SHADOW' THEN v_shadow_summary ELSE NULL::jsonb END,
        'has_more', true
      );
    END IF;

    v_blocker := public.pay_workbench_scope_blocker_state_v1(v_session.id, v_target, NULL::uuid);
    v_upstream_active := COALESCE((v_blocker->>'upstream_active_count')::integer, 0);
    v_upstream_failed := COALESCE((v_blocker->>'upstream_unresolved_failure_count')::integer, 0);

    IF v_upstream_failed > 0 OR v_upstream_active > 0 THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now + CASE
            WHEN v_upstream_failed > 0 THEN interval '30 seconds'
            ELSE interval '1 second'
          END,
          started_at_utc = NULL::timestamptz,
          last_error_json = CASE
            WHEN v_upstream_failed > 0 THEN jsonb_build_object(
              'code', 'PAY_WORKBENCH_SCOPE_RECONCILIATION_UPSTREAM_FAILED',
              'failure_sample', COALESCE(v_blocker->'failure_sample', '[]'::jsonb),
              'target_generation', v_target
            )
            ELSE coordinator_job.last_error_json
          END,
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object(
        'ok', v_upstream_failed = 0,
        'processed', true,
        'status', 'QUEUED',
        'reason', CASE
          WHEN v_upstream_failed > 0 THEN 'UPSTREAM_SCOPE_FAILURE_UNRESOLVED'
          ELSE 'UPSTREAM_APPEARED_BEFORE_ADVANCE'
        END
      );
    END IF;

    IF v_mode = 'SHADOW' THEN
      UPDATE public.banking_pay_workbench_sessions AS session_update
      SET scope_change_generation_shadow_checked = v_target,
          progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'scope_reconcile_status', 'SHADOW_SUCCEEDED',
              'scope_reconcile_mode', 'SHADOW',
              'scope_change_generation_shadow_checked', v_target,
              'scope_shadow_summary', v_shadow_summary,
              'scope_shadow_checked_at_utc', v_now::text
            ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_update.id = v_session.id;
    ELSE
      -- A23 (PRE-EXISTING SB02 fix, AA-B3): an AUTHORITATIVE completion has applied every candidate change up to
      -- v_target, which is strictly more than a SHADOW dry-run check of the same page range. Record it as checked
      -- too, so the settled certificate's target = applied = shadow_checked equality can hold in the default
      -- (AUTHORITATIVE) mode. SHADOW mode, the certificate, due_claim and the table CHECK are unchanged.
      UPDATE public.banking_pay_workbench_sessions AS session_update
      SET scope_change_generation_applied = v_target,
          scope_change_generation_target = v_target,
          scope_change_generation_shadow_checked = v_target,
          progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'scope_reconcile_status', 'SUCCEEDED',
              'scope_reconcile_mode', 'AUTHORITATIVE',
              'scope_change_generation_target', v_target,
              'scope_change_generation_applied', v_target,
              'scope_change_generation_shadow_checked', v_target,
              'scope_reconciled_at_utc', v_now::text
            ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_update.id = v_session.id;
    END IF;

    SELECT generation_counter.seq
    INTO v_current_generation
    FROM public.app_change_counters AS generation_counter
    WHERE generation_counter.entity_key = 'pay_candidate_scope_generation'
    FOR UPDATE;

    SELECT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_sessions AS lagging_session
      WHERE UPPER(BTRIM(COALESCE(lagging_session.status, ''))) = 'OPEN'
        AND lagging_session.discarded_at_utc IS NULL
        AND lagging_session.replacement_session_id IS NULL
        AND COALESCE(lagging_session.scope_seed_complete, false)
        AND (
          (v_mode = 'SHADOW' AND COALESCE(lagging_session.scope_change_generation_shadow_checked, 0) < v_current_generation)
          OR
          (v_mode = 'AUTHORITATIVE' AND COALESCE(lagging_session.scope_change_generation_applied, 0) < v_current_generation)
        )
    ) INTO v_more_sessions;

    IF v_current_generation > v_target OR v_more_sessions THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          failed_at_utc = NULL::timestamptz,
          last_error_json = NULL::jsonb,
          payload_json = (COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            - 'active_session_id' - 'cursor_generation' - 'cursor_entity_key')
            || jsonb_build_object('target_generation', v_current_generation, 'reconcile_mode', v_mode),
          scope_change_generation = v_current_generation,
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
    ELSE
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'SUCCEEDED',
          completed_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          failed_at_utc = NULL::timestamptz,
          last_error_json = NULL::jsonb,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object('completed_generation', v_target, 'completed_mode', v_mode),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
    END IF;
    RETURN jsonb_build_object(
      'ok', true,
      'processed', true,
      'status', CASE
        WHEN v_current_generation > v_target OR v_more_sessions THEN 'QUEUED'
        ELSE 'SUCCEEDED'
      END,
      'reconcile_mode', v_mode,
      'session_id', v_session.id::text,
      'target_generation', v_target,
      'current_generation', v_current_generation,
      'page_count', v_page_count,
      'admitted_count', CASE WHEN v_mode = 'AUTHORITATIVE' THEN v_inserted_count ELSE 0 END,
      'shadow_summary', CASE WHEN v_mode = 'SHADOW' THEN v_shadow_summary ELSE NULL::jsonb END,
      'has_more', false,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
      v_error_message = MESSAGE_TEXT,
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_state = RETURNED_SQLSTATE;

    UPDATE public.banking_pay_workbench_jobs AS failed_coordinator
    SET attempt_count = COALESCE(failed_coordinator.attempt_count, 0) + 1,
        status = CASE
          WHEN COALESCE(failed_coordinator.attempt_count, 0) + 1 >= COALESCE(failed_coordinator.max_attempts, 8)
            THEN 'FAILED'
          ELSE 'QUEUED'
        END,
        run_at_utc = v_now + make_interval(
          secs => LEAST(900, 30 * GREATEST(COALESCE(failed_coordinator.attempt_count, 0) + 1, 1))
        ),
        started_at_utc = NULL::timestamptz,
        failed_at_utc = CASE
          WHEN COALESCE(failed_coordinator.attempt_count, 0) + 1 >= COALESCE(failed_coordinator.max_attempts, 8)
            THEN v_now
          ELSE NULL::timestamptz
        END,
        last_error_json = jsonb_strip_nulls(jsonb_build_object(
          'code', COALESCE(NULLIF(v_error_state, ''), 'PAY_WORKBENCH_SCOPE_RECONCILE_FAILED'),
          'message', v_error_message,
          'detail', v_error_detail,
          'failed_at_utc', v_now::text
        )),
        updated_at_utc = v_now
    WHERE failed_coordinator.id = v_job.id;

    RETURN jsonb_build_object(
      'ok', false,
      'processed', true,
      'job_id', v_job.id::text,
      'code', COALESCE(NULLIF(v_error_state, ''), 'PAY_WORKBENCH_SCOPE_RECONCILE_FAILED'),
      'message', v_error_message
    );
  END;
END;
$function$
;

-- private.pay_workbench_recovery_selection_overlay_apply_v1 from supabase/repeatable/26092026_0207_banking_pay_stage2_recovery_order_floor_v1.sql; definition SHA-256 f64426f73563166dea27dd2644a0ce2f5bff8d5f2d5785da154e8668e76569d4.
CREATE OR REPLACE FUNCTION private.pay_workbench_recovery_selection_overlay_apply_v1(p_session_id uuid, p_candidate_id uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_force_v3 boolean := false;
  v_reason text := 'SELECTION_CHANGED';
  v_unknown_option_count integer := 0;
  v_is_v3 boolean := false;
  v_recovery_row_count integer := 0;
  v_ready_recovery_count integer := 0;
  v_case_recovery_count integer := 0;
  v_blocked_recovery_count integer := 0;
  v_forced_deselected_count integer := 0;
  v_updated_count integer := 0;
  v_selected_positive_amount numeric := 0;
  v_ready_recovery_amount numeric := 0;
  v_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_selected_row_count integer := 0;
  v_overlay_digest text := NULL::text;
  v_duplicate_recovery_identity_count integer := 0;
  v_session_ready boolean := false;
  v_draft_blocker_codes jsonb := '[]'::jsonb;
BEGIN
  IF p_session_id IS NULL OR p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_SCOPE_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  IF p_options_json IS NULL OR pg_catalog.jsonb_typeof(p_options_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_OPTIONS_INVALID'
      USING ERRCODE = '22023';
  END IF;

  SELECT pg_catalog.count(*)::integer
  INTO v_unknown_option_count
  FROM pg_catalog.jsonb_object_keys(p_options_json) AS supplied_option(option_key)
  WHERE supplied_option.option_key NOT IN ('force_v3', 'reason', 'pay_channel_scope');

  IF v_unknown_option_count > 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_OPTIONS_UNKNOWN'
      USING ERRCODE = '22023';
  END IF;

  -- BEGIN BANKING_PAY_MODAL_WRITE_CHANNEL_VALIDATION_V2
  IF COALESCE(p_options_json->>'pay_channel_scope','ALL') NOT IN ('ALL','PAYE','UMBRELLA') THEN
    RAISE EXCEPTION 'BANKING_PAY_V2_INVALID_INPUT' USING ERRCODE='22023';
  END IF;
  -- END BANKING_PAY_MODAL_WRITE_CHANNEL_VALIDATION_V2
  v_force_v3 := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_options_json->>'force_v3', 'false')))
    IN ('true', 't', '1', 'yes', 'y', 'on');
  v_reason := pg_catalog.upper(pg_catalog.btrim(COALESCE(NULLIF(p_options_json->>'reason', ''), 'SELECTION_CHANGED')));

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_session.status, ''))) <> 'OPEN'
     OR v_session.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT scope_row.*
  INTO v_scope
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_CANDIDATE_NOT_IN_SCOPE'
      USING ERRCODE = 'P0001';
  END IF;

  v_is_v3 := v_force_v3 OR (
    v_scope.certified_preview_publication_attestation_json->>'attestation_version'
      = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
    AND v_scope.certified_preview_publication_attestation_json->>'contract_version' = '3'
    AND v_scope.certified_preview_publication_attestation_json->>'semantic_contract_version'
      = 'READY_TO_PAY_SEMANTIC_V2'
  );

  IF v_is_v3 IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'NOT_V3_SEMANTIC_SOURCE',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'updated_count', 0,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._bpay_recovery_selection_overlay;
  CREATE TEMPORARY TABLE pg_temp._bpay_recovery_selection_overlay ON COMMIT DROP AS
  WITH selected_positive_by_channel AS (
    SELECT
      pg_catalog.upper(pg_catalog.btrim(COALESCE(
        positive_row.row_json->>'pay_channel',
        positive_row.row_json->>'candidate_pay_method',
        positive_row.row_json->>'current_pay_method',
        ''
      ))) AS pay_channel,
      pg_catalog.round(COALESCE(pg_catalog.sum(
        CASE
          WHEN COALESCE(positive_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN GREATEST((positive_row.row_json->>'amount_ex_vat')::numeric, 0)
          ELSE 0::numeric
        END
      ), 0), 2) AS selected_positive_headroom_ex_vat
    FROM public.banking_pay_workbench_preview_rows AS positive_row
    WHERE positive_row.session_id = p_session_id
      AND positive_row.session_version = v_session.version
      AND positive_row.candidate_id = p_candidate_id
      AND positive_row.status = 'READY'
      AND positive_row.selected IS TRUE
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(positive_row.selection_state, ''))) = 'SELECTED'
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(positive_row.row_json->>'line_type', ''))) = 'TIMESHEET_PAYMENT'
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(positive_row.row_json->>'presentation_role', ''))) = 'ALLOCATION_COMPONENT'
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(positive_row.row_json->>'draftable', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(positive_row.row_json->>'is_ready_for_draft', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(positive_row.row_json->>'selection_allowed', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
      AND COALESCE(positive_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND (positive_row.row_json->>'amount_ex_vat')::numeric > 0
    GROUP BY pg_catalog.upper(pg_catalog.btrim(COALESCE(
      positive_row.row_json->>'pay_channel',
      positive_row.row_json->>'candidate_pay_method',
      positive_row.row_json->>'current_pay_method',
      ''
    )))
  ), recovery_base_raw AS (
    SELECT
      recovery_row.id,
      recovery_row.row_ordinal,
      recovery_row.section AS physical_section,
      recovery_row.row_key,
      recovery_row.selected AS current_selected,
      recovery_row.selection_state AS current_selection_state,
      COALESCE(recovery_row.row_json, '{}'::jsonb) AS base_row_json,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(
        recovery_row.row_json->>'selection_user_override',
        ''
      ))) = 'UNSELECTED' AS explicitly_user_unselected,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(
        recovery_row.row_json->>'pay_channel',
        recovery_row.row_json->>'candidate_pay_method',
        recovery_row.row_json->>'current_pay_method',
        ''
      ))) AS pay_channel,
      pg_catalog.round(COALESCE(
        CASE
          WHEN COALESCE(recovery_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((recovery_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(recovery_row.row_json->>'source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((recovery_row.row_json->>'source_due_amount_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(recovery_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((recovery_row.row_json->>'amount_ex_vat')::numeric)
          ELSE 0::numeric
        END
      ), 2) AS nominal_due_amount_ex_vat,
      CASE
        WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'case_components') = 'array'
          THEN recovery_row.row_json->'case_components'
        ELSE '[]'::jsonb
      END AS canonical_case_components,
      CASE
        WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'case_resolution_summary') = 'object'
          THEN recovery_row.row_json->'case_resolution_summary'
        WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'case_resolution_summary_json') = 'object'
          THEN recovery_row.row_json->'case_resolution_summary_json'
        ELSE '{}'::jsonb
      END AS case_resolution_summary_json,
      (
        pg_catalog.lower(pg_catalog.btrim(COALESCE(
          recovery_row.row_json#>>'{case_resolution_summary,case_needs_resolution}',
          recovery_row.row_json#>>'{case_resolution_summary_json,case_needs_resolution}',
          recovery_row.row_json->>'case_needs_resolution_now',
          'false'
        ))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.lower(pg_catalog.btrim(COALESCE(
          recovery_row.row_json#>>'{case_resolution_summary,taxable_channel_restructure,can_apply}',
          recovery_row.row_json#>>'{case_resolution_summary_json,taxable_channel_restructure,can_apply}',
          'false'
        ))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(
          recovery_row.row_json#>>'{case_resolution_summary,resolution_family}',
          recovery_row.row_json#>>'{case_resolution_summary_json,resolution_family}',
          recovery_row.row_json->>'resolution_family',
          ''
        ))) = 'TAXABLE_CHANNEL_RESTRUCTURE'
      ) AS actionable_restructure,
      COALESCE(
        recovery_row.row_json#>'{selection_recovery_headroom_v1,base_blocked_reason_codes}',
        (
          SELECT COALESCE(pg_catalog.jsonb_agg(reason.value ORDER BY reason.ordinality), '[]'::jsonb)
          FROM pg_catalog.jsonb_array_elements_text(
            CASE
              WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'blocked_reason_codes') = 'array'
                THEN recovery_row.row_json->'blocked_reason_codes'
              ELSE '[]'::jsonb
            END
          ) WITH ORDINALITY AS reason(value, ordinality)
          WHERE pg_catalog.upper(pg_catalog.btrim(reason.value)) <> 'NO_PAY_HEADROOM'
        ),
        '[]'::jsonb
      ) AS base_blocked_reason_codes,
      COALESCE(
        NULLIF(recovery_row.row_json#>>'{selection_recovery_headroom_v1,base_presentation_reason}', ''),
        CASE
          WHEN pg_catalog.upper(COALESCE(recovery_row.row_json->>'presentation_reason', '')) = 'NO_PAY_HEADROOM'
            THEN 'READY_TO_PAY'
          ELSE NULLIF(recovery_row.row_json->>'presentation_reason', '')
        END,
        'READY_TO_PAY'
      ) AS base_presentation_reason,
      (
        recovery_row.row_json->>'finance_case_id'
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(recovery_row.row_json->>'line_type', ''))) IN (
          'OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY',
          'PAYMENT_ADVANCE_REPAYMENT', 'LOAN_REPAYMENT'
        )
        AND pg_catalog.lower(pg_catalog.btrim(COALESCE(recovery_row.row_json->>'post_draft_overlay_applied', 'false')))
          NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.lower(pg_catalog.btrim(COALESCE(recovery_row.row_json->>'case_needs_resolution_now', 'false')))
          NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(recovery_row.row_json#>>'{snooze_state,state}', 'NONE'))) = 'NONE'
        AND NOT EXISTS (
          SELECT 1
          FROM pg_catalog.jsonb_array_elements_text(
            COALESCE(
              recovery_row.row_json#>'{selection_recovery_headroom_v1,base_blocked_reason_codes}',
              CASE
                WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'blocked_reason_codes') = 'array'
                  THEN recovery_row.row_json->'blocked_reason_codes'
                ELSE '[]'::jsonb
              END
            )
          ) AS blocker(value)
          -- A34: the legacy component blocker is re-derived below on every run, never read back as sticky.
          WHERE pg_catalog.upper(pg_catalog.btrim(blocker.value)) NOT IN ('NO_PAY_HEADROOM', 'LEGACY_FINANCE_CASE_COMPONENTS_MISSING')
        )
      ) AS static_recovery_eligible
    FROM public.banking_pay_workbench_preview_rows AS recovery_row
    WHERE recovery_row.session_id = p_session_id
      AND recovery_row.session_version = v_session.version
      AND recovery_row.candidate_id = p_candidate_id
      AND recovery_row.status = 'READY'
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(
        recovery_row.row_json->>'line_type',
        recovery_row.row_json->>'case_type',
        ''
      ))) IN (
        'OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY',
        'PAYMENT_ADVANCE_REPAYMENT', 'LOAN_REPAYMENT'
      )
  ), recovery_base AS (
    -- A34 (legacy finance case blocker, Worker BT): a repayment with money due whose finance case has NO open component
    -- records (the published row carries case_components = []) cannot be deducted under the certified V3 contract
    -- (every recovered penny must name its component; Policy X forbids inventing one). Before A34 this raised
    -- PAY_WORKBENCH_RECOVERY_COMPONENT_AUTHORITY_MISSING and the WHOLE Candidate failed to prepare. Now that row alone
    -- is a visible Blocked row with reason LEGACY_FINANCE_CASE_COMPONENTS_MISSING: it recovers GBP0 and consumes no pay headroom
    -- (as a snoozed or otherwise ineligible repayment does), so the Office sees it and every other row is unchanged.
    -- Derived afresh on every run from the row's own components: it clears itself once component records exist.
    SELECT
      raw.id,
      raw.row_ordinal,
      raw.physical_section,
      raw.row_key,
      raw.current_selected,
      raw.current_selection_state,
      raw.base_row_json,
      raw.explicitly_user_unselected,
      raw.pay_channel,
      raw.nominal_due_amount_ex_vat,
      raw.canonical_case_components,
      raw.case_resolution_summary_json,
      raw.actionable_restructure AND legacy.components_missing IS NOT TRUE AS actionable_restructure,
      COALESCE((
        SELECT pg_catalog.jsonb_agg(code.value ORDER BY code.ordinality)
        FROM pg_catalog.jsonb_array_elements(
          CASE WHEN pg_catalog.jsonb_typeof(raw.base_blocked_reason_codes) = 'array'
            THEN raw.base_blocked_reason_codes ELSE '[]'::jsonb END
        ) WITH ORDINALITY AS code(value, ordinality)
        WHERE pg_catalog.upper(pg_catalog.btrim(COALESCE(code.value #>> '{}', ''))) <> 'LEGACY_FINANCE_CASE_COMPONENTS_MISSING'
      ), '[]'::jsonb)
        || CASE WHEN legacy.components_missing
             THEN pg_catalog.jsonb_build_array('LEGACY_FINANCE_CASE_COMPONENTS_MISSING') ELSE '[]'::jsonb END
        AS base_blocked_reason_codes,
      CASE
        WHEN legacy.components_missing THEN 'LEGACY_FINANCE_CASE_COMPONENTS_MISSING'
        WHEN pg_catalog.upper(pg_catalog.btrim(COALESCE(raw.base_presentation_reason, ''))) = 'LEGACY_FINANCE_CASE_COMPONENTS_MISSING'
          THEN 'READY_TO_PAY'
        ELSE raw.base_presentation_reason
      END AS base_presentation_reason,
      raw.static_recovery_eligible AND legacy.components_missing IS NOT TRUE AS static_recovery_eligible,
      legacy.components_missing AS legacy_components_missing
    FROM recovery_base_raw AS raw
    CROSS JOIN LATERAL (
      SELECT raw.nominal_due_amount_ex_vat > 0
         AND pg_catalog.jsonb_array_length(raw.canonical_case_components) = 0 AS components_missing
    ) AS legacy
  ), ranked_recovery AS (
    SELECT
      recovery_base.*,
      COALESCE(selected_headroom.selected_positive_headroom_ex_vat, 0)::numeric AS selected_positive_headroom_ex_vat
    FROM recovery_base
    LEFT JOIN selected_positive_by_channel AS selected_headroom
      ON selected_headroom.pay_channel = recovery_base.pay_channel
  ), recovery_allocation AS (
    -- A34 (user rulings 25/31 order, 29 exclusion and headroom, 30 type-specific protection; Worker BT): ONE sequential
    -- allocation, oldest debt first (the SAME key and tie-break as the canonical builder and Stage 3 WP3: creation date
    -- and time, a loan by its payout; ties finance case id, then row). Each repayment is capped by its OWN type's rule:
    -- a loan (PAYMENT_ADVANCE) or manual debt keeps the minimum take-home floor and its minimum earnings threshold,
    -- exactly as public._pay_finance_protected_recovery_allocate does; an overpayment is capped by pay headroom only.
    -- A repayment the Office excluded, or one that cannot be recovered now, consumes nothing (A30). Replaces the
    -- running-nominal window, which applied no floor at all.
    SELECT allocation.*
    FROM private.pay_workbench_recovery_type_capped_allocate_v1(
      p_candidate_id,
      v_session.pay_date,
      (
        SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'id', rr.id::text,
          'pay_channel', rr.pay_channel,
          'finance_case_id', rr.base_row_json->>'finance_case_id',
          'line_type', pg_catalog.upper(pg_catalog.btrim(COALESCE(rr.base_row_json->>'line_type', rr.base_row_json->>'case_type', ''))),
          'row_ordinal', rr.row_ordinal,
          'nominal_due_amount_ex_vat', rr.nominal_due_amount_ex_vat,
          'headroom_ex_vat', rr.selected_positive_headroom_ex_vat,
          'eligible', rr.static_recovery_eligible AND rr.actionable_restructure IS NOT TRUE
                      AND rr.pay_channel IN ('PAYE', 'UMBRELLA'),
          'excluded', rr.explicitly_user_unselected IS TRUE
        )), '[]'::jsonb)
        FROM ranked_recovery AS rr
      )
    ) AS allocation
  ), allocated_recovery AS (
    SELECT
      ranked_recovery.*,
      COALESCE(recovery_allocation.recoverable_amount_ex_vat, 0::numeric) AS recoverable_amount_ex_vat,
      recovery_allocation.cap_reason AS recovery_cap_reason
    FROM ranked_recovery
    LEFT JOIN recovery_allocation
      ON recovery_allocation.row_id = ranked_recovery.id
  ), recovery_component_base AS (
    SELECT
      allocated_recovery.id AS recovery_row_id,
      component.ordinality::integer AS component_ordinality,
      component.value AS component_json,
      CASE
        WHEN COALESCE(component.value->>'finance_component_id', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN true
        ELSE NULLIF(pg_catalog.btrim(COALESCE(component.value->>'source_family_key', '')), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(
                component.value->>'component_key_type',
                component.value#>>'{component_key,key_type}',
                ''
              )), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(
                component.value->>'component_key_value',
                component.value#>>'{component_key,key_value}',
                ''
              )), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(component.value->>'bucket_code', '')), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(component.value->>'source_basis_fingerprint', '')), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(component.value->>'component_fingerprint', '')), '') IS NOT NULL
      END AS identity_complete,
      CASE
        WHEN COALESCE(component.value->>'finance_component_id', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN 'FINANCE:' || pg_catalog.lower(component.value->>'finance_component_id')
        ELSE 'STRUCT:' || pg_catalog.concat_ws(E'\x1f',
          pg_catalog.upper(pg_catalog.btrim(COALESCE(component.value->>'source_family_key', ''))),
          pg_catalog.upper(pg_catalog.btrim(COALESCE(
            component.value->>'component_key_type', component.value#>>'{component_key,key_type}', ''
          ))),
          pg_catalog.btrim(COALESCE(
            component.value->>'component_key_value', component.value#>>'{component_key,key_value}', ''
          )),
          pg_catalog.upper(pg_catalog.btrim(COALESCE(component.value->>'bucket_code', ''))),
          pg_catalog.btrim(COALESCE(component.value->>'source_basis_fingerprint', '')),
          pg_catalog.btrim(COALESCE(component.value->>'component_fingerprint', ''))
        )
      END AS component_identity,
      pg_catalog.round(COALESCE(
        CASE
          WHEN COALESCE(component.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'target_pay_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(component.value->>'authoritative_outstanding_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'authoritative_outstanding_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(component.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'source_pay_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'component_amount_ex_vat')::numeric)
          ELSE 0::numeric
        END
      ), 2) AS component_capacity_ex_vat,
      allocated_recovery.recoverable_amount_ex_vat
    FROM allocated_recovery
    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(
      allocated_recovery.canonical_case_components
    ) WITH ORDINALITY AS component(value, ordinality)
  ), recovery_component_ranked AS (
    SELECT
      recovery_component_base.*,
      pg_catalog.count(*) OVER (
        PARTITION BY recovery_component_base.recovery_row_id,
          recovery_component_base.component_identity
      )::integer AS component_identity_count,
      COALESCE(pg_catalog.sum(recovery_component_base.component_capacity_ex_vat) OVER (
        PARTITION BY recovery_component_base.recovery_row_id
        ORDER BY
          pg_catalog.upper(pg_catalog.btrim(COALESCE(
            recovery_component_base.component_json->>'component_key_type',
            recovery_component_base.component_json#>>'{component_key,key_type}',
            ''
          ))),
          pg_catalog.btrim(COALESCE(
            recovery_component_base.component_json->>'component_key_value',
            recovery_component_base.component_json#>>'{component_key,key_value}',
            ''
          )),
          pg_catalog.lower(COALESCE(recovery_component_base.component_json->>'finance_component_id', '')),
          COALESCE(recovery_component_base.component_json->>'component_fingerprint', ''),
          recovery_component_base.component_ordinality
        ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
      ), 0)::numeric AS prior_component_capacity_ex_vat
    FROM recovery_component_base
  ), recovery_component_allocated AS (
    SELECT
      recovery_component_ranked.*,
      pg_catalog.round(LEAST(
        recovery_component_ranked.component_capacity_ex_vat,
        GREATEST(
          recovery_component_ranked.recoverable_amount_ex_vat
            - recovery_component_ranked.prior_component_capacity_ex_vat,
          0
        )
      ), 2) AS base_component_recoverable_ex_vat,
      pg_catalog.row_number() OVER (
        PARTITION BY recovery_component_ranked.recovery_row_id
        ORDER BY
          pg_catalog.upper(pg_catalog.btrim(COALESCE(
            recovery_component_ranked.component_json->>'component_key_type',
            recovery_component_ranked.component_json#>>'{component_key,key_type}',
            ''
          ))),
          pg_catalog.btrim(COALESCE(
            recovery_component_ranked.component_json->>'component_key_value',
            recovery_component_ranked.component_json#>>'{component_key,key_value}',
            ''
          )),
          pg_catalog.lower(COALESCE(recovery_component_ranked.component_json->>'finance_component_id', '')),
          COALESCE(recovery_component_ranked.component_json->>'component_fingerprint', ''),
          recovery_component_ranked.component_ordinality
      )::integer AS allocation_order
    FROM recovery_component_ranked
  ), recovery_component_residual AS (
    SELECT
      recovery_component_allocated.*,
      pg_catalog.round(
        recovery_component_allocated.recoverable_amount_ex_vat
          - pg_catalog.sum(recovery_component_allocated.base_component_recoverable_ex_vat)
              OVER (PARTITION BY recovery_component_allocated.recovery_row_id),
        2
      ) AS penny_residual_ex_vat,
      pg_catalog.max(recovery_component_allocated.allocation_order) FILTER (
        WHERE recovery_component_allocated.component_capacity_ex_vat
              - recovery_component_allocated.base_component_recoverable_ex_vat > 0
      ) OVER (PARTITION BY recovery_component_allocated.recovery_row_id)
        AS residual_target_order
    FROM recovery_component_allocated
  ), recovery_component_final AS (
    SELECT
      recovery_component_residual.*,
      pg_catalog.round(
        recovery_component_residual.base_component_recoverable_ex_vat
          + CASE
              WHEN recovery_component_residual.penny_residual_ex_vat <> 0
               AND recovery_component_residual.allocation_order
                    = recovery_component_residual.residual_target_order
               AND recovery_component_residual.component_capacity_ex_vat
                     - recovery_component_residual.base_component_recoverable_ex_vat
                    >= recovery_component_residual.penny_residual_ex_vat
                THEN recovery_component_residual.penny_residual_ex_vat
              ELSE 0::numeric
            END,
        2
      ) AS component_recoverable_ex_vat
    FROM recovery_component_residual
  ), recovery_component_rollup AS (
    SELECT
      recovery_component_final.recovery_row_id,
      pg_catalog.jsonb_agg(
        recovery_component_final.component_json
        || pg_catalog.jsonb_build_object(
          'preview_due_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'allocated_source_due_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'ready_preview_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'preview_component_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'component_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'recoverable_this_pay_run_ex_vat', recovery_component_final.component_recoverable_ex_vat
        )
        ORDER BY recovery_component_final.component_ordinality
      ) AS allocated_case_components,
      pg_catalog.count(*) FILTER (
        WHERE recovery_component_final.identity_complete IS NOT TRUE
      )::integer AS incomplete_identity_count,
      pg_catalog.count(*) FILTER (
        WHERE recovery_component_final.component_identity_count > 1
      )::integer AS duplicate_identity_count,
      pg_catalog.round(COALESCE(pg_catalog.sum(
        recovery_component_final.component_capacity_ex_vat
      ), 0), 2) AS component_capacity_ex_vat,
      pg_catalog.round(COALESCE(pg_catalog.sum(
        recovery_component_final.component_recoverable_ex_vat
      ), 0), 2) AS component_recoverable_ex_vat
    FROM recovery_component_final
    GROUP BY recovery_component_final.recovery_row_id
  )
  SELECT
    allocated_recovery.*,
    COALESCE(recovery_component_rollup.allocated_case_components, '[]'::jsonb)
      AS allocated_case_components,
    COALESCE(recovery_component_rollup.incomplete_identity_count, 0)::integer
      AS incomplete_component_identity_count,
    COALESCE(recovery_component_rollup.duplicate_identity_count, 0)::integer
      AS duplicate_component_identity_count,
    COALESCE(recovery_component_rollup.component_capacity_ex_vat, 0)::numeric
      AS component_capacity_ex_vat,
    COALESCE(recovery_component_rollup.component_recoverable_ex_vat, 0)::numeric
      AS component_recoverable_ex_vat,
    CASE
      WHEN allocated_recovery.actionable_restructure
        THEN 'cases_resolutions'
      WHEN allocated_recovery.static_recovery_eligible
       AND allocated_recovery.recoverable_amount_ex_vat > 0
        THEN 'canonical_preview_lines'
      ELSE 'blocked_for_pay'
    END AS effective_section,
    pg_catalog.md5(pg_catalog.jsonb_build_object(
      'contract_version', 1,
      'candidate_id', p_candidate_id::text,
      'pay_channel', allocated_recovery.pay_channel,
      'row_key', allocated_recovery.row_key,
      'selected_positive_headroom_ex_vat', allocated_recovery.selected_positive_headroom_ex_vat,
      'nominal_due_amount_ex_vat', allocated_recovery.nominal_due_amount_ex_vat,
      'recoverable_amount_ex_vat', allocated_recovery.recoverable_amount_ex_vat,
      'effective_section', CASE
        WHEN allocated_recovery.actionable_restructure
          THEN 'cases_resolutions'
        WHEN allocated_recovery.static_recovery_eligible
         AND allocated_recovery.recoverable_amount_ex_vat > 0
          THEN 'canonical_preview_lines'
        ELSE 'blocked_for_pay'
      END
    )::text) AS row_overlay_digest
  FROM allocated_recovery
  LEFT JOIN recovery_component_rollup
    ON recovery_component_rollup.recovery_row_id = allocated_recovery.id;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.incomplete_component_identity_count > 0
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_IDENTITY_INCOMPLETE'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.duplicate_component_identity_count > 0
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_IDENTITY_DUPLICATE'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.nominal_due_amount_ex_vat > 0
      AND pg_catalog.jsonb_array_length(overlay_row.allocated_case_components) = 0
      -- A34: a legacy row without component records is a Blocked row (above), recovering GBP0, not a failure.
      AND overlay_row.legacy_components_missing IS NOT TRUE
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_AUTHORITY_MISSING'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.recoverable_amount_ex_vat > overlay_row.component_capacity_ex_vat
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_CAPACITY_INSUFFICIENT'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.component_recoverable_ex_vat
      IS DISTINCT FROM overlay_row.recoverable_amount_ex_vat
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_PENNY_RECONCILIATION_FAILED'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT pg_catalog.count(*)::integer
  INTO v_duplicate_recovery_identity_count
  FROM (
    SELECT
      COALESCE(NULLIF(overlay_row.base_row_json->>'finance_case_id', ''), overlay_row.row_key) AS recovery_identity,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(overlay_row.base_row_json->>'line_type', ''))) AS recovery_family
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    GROUP BY
      COALESCE(NULLIF(overlay_row.base_row_json->>'finance_case_id', ''), overlay_row.row_key),
      pg_catalog.upper(pg_catalog.btrim(COALESCE(overlay_row.base_row_json->>'line_type', '')))
    HAVING pg_catalog.count(*) > 1
  ) AS duplicate_identity;

  IF v_duplicate_recovery_identity_count > 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_DUPLICATE_IDENTITY'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT pg_catalog.count(*)::integer,
         pg_catalog.count(*) FILTER (WHERE overlay_row.effective_section = 'canonical_preview_lines')::integer,
         pg_catalog.count(*) FILTER (WHERE overlay_row.effective_section = 'cases_resolutions')::integer,
         pg_catalog.count(*) FILTER (WHERE overlay_row.effective_section = 'blocked_for_pay')::integer,
         (
           SELECT pg_catalog.round(COALESCE(pg_catalog.sum(channel_headroom.selected_positive_headroom_ex_vat), 0), 2)
           FROM (
             SELECT overlay_channel.pay_channel,
                    pg_catalog.max(overlay_channel.selected_positive_headroom_ex_vat) AS selected_positive_headroom_ex_vat
             FROM pg_temp._bpay_recovery_selection_overlay AS overlay_channel
             GROUP BY overlay_channel.pay_channel
           ) AS channel_headroom
         ),
         pg_catalog.round(COALESCE(pg_catalog.sum(overlay_row.recoverable_amount_ex_vat), 0), 2),
         pg_catalog.md5(COALESCE(pg_catalog.string_agg(
           overlay_row.row_key || E'\x1f' || overlay_row.row_overlay_digest,
           E'\x1e' ORDER BY overlay_row.row_ordinal, overlay_row.id
         ), ''))
  INTO v_recovery_row_count,
       v_ready_recovery_count,
       v_case_recovery_count,
       v_blocked_recovery_count,
       v_selected_positive_amount,
       v_ready_recovery_amount,
       v_overlay_digest
  FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row;

  WITH updated_rows AS (
    UPDATE public.banking_pay_workbench_preview_rows AS recovery_row
    SET selected = CASE
          WHEN overlay_row.effective_section = 'canonical_preview_lines'
            THEN overlay_row.explicitly_user_unselected IS NOT TRUE
          ELSE false
        END,
        selection_state = CASE
          WHEN overlay_row.effective_section = 'canonical_preview_lines'
            THEN CASE
              WHEN overlay_row.explicitly_user_unselected IS TRUE THEN 'UNSELECTED'
              ELSE 'SELECTED'
            END
          ELSE 'NOT_SELECTABLE'
        END,
        row_json = pg_catalog.jsonb_strip_nulls(
          overlay_row.base_row_json
          || pg_catalog.jsonb_build_object(
            'case_components', overlay_row.allocated_case_components,
            'amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'preview_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'amount_display', -overlay_row.recoverable_amount_ex_vat,
            'section_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'section_amount_display', -overlay_row.recoverable_amount_ex_vat,
            'target_pay_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'ready_preview_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'preview_component_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'nominal_due_amount_ex_vat', overlay_row.nominal_due_amount_ex_vat,
            'recoverable_this_pay_run_ex_vat', overlay_row.recoverable_amount_ex_vat,
            'semantic_ordinary_positive_headroom_ex_vat', overlay_row.selected_positive_headroom_ex_vat,
            'retained_positive_headroom_ex_vat', overlay_row.selected_positive_headroom_ex_vat,
            'semantic_recovery_headroom_capped',
              overlay_row.recoverable_amount_ex_vat < overlay_row.nominal_due_amount_ex_vat,
            'effective_section', overlay_row.effective_section,
            'physical_section', overlay_row.physical_section,
            'readiness_state', CASE overlay_row.effective_section
              WHEN 'canonical_preview_lines' THEN 'READY_TO_PAY'
              WHEN 'cases_resolutions' THEN 'RESOLUTION_REQUIRED'
              ELSE 'BLOCKED_FOR_PAY'
            END,
            'presentation_section', CASE overlay_row.effective_section
              WHEN 'canonical_preview_lines' THEN 'READY_TO_PAY'
              WHEN 'cases_resolutions' THEN 'CASES_RESOLUTIONS'
              ELSE 'BLOCKED_FOR_PAY'
            END,
            'presentation_reason', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN overlay_row.base_presentation_reason
              WHEN overlay_row.effective_section = 'cases_resolutions'
                THEN 'CASE_NEEDS_RESOLUTION'
              WHEN overlay_row.static_recovery_eligible THEN 'NO_PAY_HEADROOM'
              ELSE overlay_row.base_presentation_reason
            END,
            'draftable', overlay_row.effective_section = 'canonical_preview_lines',
            'is_ready_for_draft', overlay_row.effective_section = 'canonical_preview_lines',
            'selection_allowed', overlay_row.effective_section = 'canonical_preview_lines',
            'is_excluded_from_allocation', overlay_row.effective_section <> 'canonical_preview_lines',
            'selected', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN overlay_row.explicitly_user_unselected IS NOT TRUE
              ELSE false
            END,
            'selection_state', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
               AND overlay_row.explicitly_user_unselected IS NOT TRUE
                THEN 'SELECTED'
              WHEN overlay_row.effective_section = 'canonical_preview_lines' THEN 'UNSELECTED'
              ELSE 'NOT_SELECTABLE'
            END,
            'selection_origin', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
               AND overlay_row.explicitly_user_unselected IS TRUE
                THEN 'USER_EXPLICIT_DESELECT'
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN 'SERVER_DEFAULT_NEWLY_ELIGIBLE'
              ELSE COALESCE(overlay_row.base_row_json->>'selection_origin', 'SERVER_HEADROOM_BLOCKED')
            END,
            'blocked_reason_codes', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN overlay_row.base_blocked_reason_codes
              WHEN overlay_row.static_recovery_eligible
                THEN overlay_row.base_blocked_reason_codes || pg_catalog.jsonb_build_array('NO_PAY_HEADROOM')
              ELSE overlay_row.base_blocked_reason_codes
            END,
            'case_is_blocked', overlay_row.effective_section <> 'canonical_preview_lines',
            'selection_recovery_headroom_v1', pg_catalog.jsonb_build_object(
              'contract_version', 1,
              'component_allocation_contract_version', 1,
              'candidate_id', p_candidate_id::text,
              'pay_channel', overlay_row.pay_channel,
              'physical_section', overlay_row.physical_section,
              'prior_physical_section', overlay_row.physical_section,
              'effective_section', overlay_row.effective_section,
              'selected_positive_headroom_ex_vat', overlay_row.selected_positive_headroom_ex_vat,
              'nominal_due_amount_ex_vat', overlay_row.nominal_due_amount_ex_vat,
              'recoverable_amount_ex_vat', overlay_row.recoverable_amount_ex_vat,
              'base_blocked_reason_codes', overlay_row.base_blocked_reason_codes,
              'base_presentation_reason', overlay_row.base_presentation_reason,
              'static_recovery_eligible', overlay_row.static_recovery_eligible,
              'actionable_restructure', overlay_row.actionable_restructure,
              -- A34: present (true) only on a legacy row; jsonb_strip_nulls removes it everywhere else.
              'legacy_components_missing', CASE WHEN overlay_row.legacy_components_missing THEN true END,
              -- A34: which rule capped this repayment (TAKE_HOME_FLOOR / EARNINGS_THRESHOLD / PAY_HEADROOM); absent if none.
              'recovery_cap_reason', overlay_row.recovery_cap_reason,
              'component_capacity_ex_vat', overlay_row.component_capacity_ex_vat,
              'component_recoverable_ex_vat', overlay_row.component_recoverable_ex_vat,
              'overlay_digest', overlay_row.row_overlay_digest,
              'reason', v_reason,
              'updated_at_utc', v_now::text,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            ),
            'case_resolution_summary', CASE
              WHEN pg_catalog.jsonb_typeof(overlay_row.case_resolution_summary_json) = 'object'
                THEN overlay_row.case_resolution_summary_json
                  || pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
              ELSE pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
            END,
            'case_resolution_summary_json', CASE
              WHEN pg_catalog.jsonb_typeof(overlay_row.case_resolution_summary_json) = 'object'
                THEN overlay_row.case_resolution_summary_json
                  || pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
              ELSE pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
            END
          )
          || CASE
            WHEN pg_catalog.jsonb_typeof(overlay_row.base_row_json->'row_json') = 'object'
              THEN pg_catalog.jsonb_build_object(
                'row_json', (overlay_row.base_row_json->'row_json')
                  || pg_catalog.jsonb_build_object(
                    'case_components', overlay_row.allocated_case_components
                  )
              )
            ELSE '{}'::jsonb
          END
          || CASE
            WHEN pg_catalog.jsonb_typeof(overlay_row.base_row_json->'case') = 'object'
              THEN pg_catalog.jsonb_build_object(
                'case', (overlay_row.base_row_json->'case')
                  || pg_catalog.jsonb_build_object(
                    'case_components', overlay_row.allocated_case_components
                  )
              )
            ELSE '{}'::jsonb
          END
          || CASE
            WHEN pg_catalog.jsonb_typeof(overlay_row.base_row_json->'raw_case') = 'object'
              THEN pg_catalog.jsonb_build_object(
                'raw_case', (overlay_row.base_row_json->'raw_case')
                  || pg_catalog.jsonb_build_object(
                    'case_components', overlay_row.allocated_case_components
                  )
              )
            ELSE '{}'::jsonb
          END
        ),
        updated_at_utc = v_now
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE recovery_row.id = overlay_row.id
      -- BEGIN BANKING_PAY_MODAL_WRITE_CHANNEL_FILTER_V2
      AND (COALESCE(p_options_json->>'pay_channel_scope','ALL')='ALL'
        OR overlay_row.pay_channel=p_options_json->>'pay_channel_scope')
      -- END BANKING_PAY_MODAL_WRITE_CHANNEL_FILTER_V2
    RETURNING recovery_row.id,
              overlay_row.effective_section,
              overlay_row.current_selected,
              recovery_row.selected
  )
  SELECT pg_catalog.count(*)::integer,
         pg_catalog.count(*) FILTER (
           WHERE updated_rows.current_selected IS TRUE
             AND updated_rows.selected IS FALSE
         )::integer
  INTO v_updated_count, v_forced_deselected_count
  FROM updated_rows;

  SELECT COALESCE(
           pg_catalog.jsonb_agg(selected_row.id::text ORDER BY selected_row.row_ordinal, selected_row.id),
           '[]'::jsonb
         ),
         pg_catalog.count(*)::integer
  INTO v_selected_preview_row_ids,
       v_selected_row_count
  FROM public.banking_pay_workbench_preview_rows AS selected_row
  WHERE selected_row.session_id = p_session_id
    AND selected_row.session_version = v_session.version
    AND selected_row.status = 'READY'
    AND selected_row.selected IS TRUE
    AND pg_catalog.upper(pg_catalog.btrim(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

  v_session_ready := pg_catalog.lower(pg_catalog.btrim(COALESCE(
    v_session.progress_json->>'ready',
    v_session.progress_json->>'session_ready',
    v_session.progress_json->>'ready_flag',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  SELECT COALESCE(
           pg_catalog.jsonb_agg(pg_catalog.to_jsonb(blocker.value) ORDER BY blocker.ordinality),
           '[]'::jsonb
         )
  INTO v_draft_blocker_codes
  FROM pg_catalog.jsonb_array_elements_text(
    CASE
      WHEN pg_catalog.jsonb_typeof(v_session.progress_json->'draft_blocker_codes') = 'array'
        THEN v_session.progress_json->'draft_blocker_codes'
      ELSE '[]'::jsonb
    END
  ) WITH ORDINALITY AS blocker(value, ordinality)
  WHERE pg_catalog.upper(pg_catalog.btrim(blocker.value)) <> 'NO_SELECTED_ROWS';

  IF v_session_ready AND COALESCE(v_selected_row_count, 0) = 0 THEN
    v_draft_blocker_codes := COALESCE(v_draft_blocker_codes, '[]'::jsonb)
      || pg_catalog.jsonb_build_array('NO_SELECTED_ROWS');
  END IF;

  UPDATE public.banking_pay_workbench_sessions AS session_update
  SET selected_row_count = COALESCE(v_selected_row_count, 0),
      server_selected_preview_row_ids = CASE
        WHEN COALESCE(session_update.server_selected_preview_row_ids_provided, false)
          THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
        ELSE session_update.server_selected_preview_row_ids
      END,
      progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'selection_recovery_headroom_v1', pg_catalog.jsonb_build_object(
            'contract_version', 1,
            'candidate_id', p_candidate_id::text,
            'selected_positive_headroom_ex_vat', v_selected_positive_amount,
            'ready_recovery_count', v_ready_recovery_count,
            'case_recovery_count', v_case_recovery_count,
            'blocked_recovery_count', v_blocked_recovery_count,
            'recoverable_amount_ex_vat', v_ready_recovery_amount,
            'overlay_digest', v_overlay_digest,
            'reason', v_reason,
            'updated_at_utc', v_now::text
          ),
          'selected_row_count', COALESCE(v_selected_row_count, 0),
          'selected_eligible_ready_row_count', COALESCE(v_selected_row_count, 0),
          'selected_rows_available', COALESCE(v_selected_row_count, 0) > 0,
          'ready_for_draft', v_session_ready AND COALESCE(v_selected_row_count, 0) > 0,
          'can_create_draft', v_session_ready AND COALESCE(v_selected_row_count, 0) > 0,
          'draft_blocker_codes', COALESCE(v_draft_blocker_codes, '[]'::jsonb),
          'blocker_codes', COALESCE(v_draft_blocker_codes, '[]'::jsonb)
        ),
      updated_at_utc = v_now
  WHERE session_update.id = p_session_id;

  UPDATE public.banking_pay_workbench_session_scope AS scope_update
  SET certified_preview_publication_attestation_json = CASE
        WHEN v_scope.certified_preview_publication_attestation_json->>'attestation_version'
             = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
          THEN COALESCE(scope_update.certified_preview_publication_attestation_json, '{}'::jsonb)
            || pg_catalog.jsonb_build_object(
              'selection_recovery_headroom_v1', pg_catalog.jsonb_build_object(
                'contract_version', 1,
                'selected_positive_headroom_ex_vat', v_selected_positive_amount,
                'ready_recovery_count', v_ready_recovery_count,
                'case_recovery_count', v_case_recovery_count,
                'blocked_recovery_count', v_blocked_recovery_count,
                'recoverable_amount_ex_vat', v_ready_recovery_amount,
                'overlay_digest', v_overlay_digest,
                'reason', v_reason,
                'updated_at_utc', v_now::text
              )
            )
        ELSE scope_update.certified_preview_publication_attestation_json
      END,
      updated_at_utc = v_now
  WHERE scope_update.id = v_scope.id;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'SELECTION_DEPENDENT_RECOVERY_HEADROOM_APPLIED',
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'recovery_row_count', v_recovery_row_count,
    'ready_recovery_count', v_ready_recovery_count,
    'case_recovery_count', v_case_recovery_count,
    'blocked_recovery_count', v_blocked_recovery_count,
    'forced_deselected_count', v_forced_deselected_count,
    'updated_count', v_updated_count,
    'selected_positive_headroom_ex_vat', v_selected_positive_amount,
    'recoverable_amount_ex_vat', v_ready_recovery_amount,
    'overlay_digest', v_overlay_digest,
    'physical_sections_changed', false,
    'source_rows_changed', false,
    'post_draft_artifacts_touched', false,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$;

-- public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1 from supabase/repeatable/26092026_0207_banking_pay_stage2_recovery_order_floor_v1.sql; definition SHA-256 9f3017f83b1636f4f72ef603cc195b4fafb39cf36ce1b59eae488bcc634d581a.
CREATE OR REPLACE FUNCTION public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(p_session_id uuid, p_candidate_id uuid, p_options_json jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_nonterminal_line_count integer := 0;
  v_retained_positive_headroom numeric(12,2) := 0;
  v_recovery_group_count integer := 0;
  v_promoted_count integer := 0;
  v_promoted_selected_count integer := 0;
  v_repaired_authority_scope_count integer := 0;
  v_ready_recovery_capped_count integer := 0;
  v_ready_recovery_blocked_count integer := 0;
  v_demoted_count integer := 0;
  v_superseded_count integer := 0;
  v_line_work_revalidated_count integer := 0;
  v_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_selected_row_count integer := 0;
  v_selection_intent_mode text := '';
  v_progress_json jsonb := '{}'::jsonb;
  v_scope_attestation jsonb := '{}'::jsonb;
  v_v3_overlay_result jsonb := '{}'::jsonb;
BEGIN
  -- BEGIN BANKING_PAY_MODAL_RECOVERY_SCOPE_VALIDATION_V2
  IF jsonb_typeof(p_options_json) IS DISTINCT FROM 'object'
     OR COALESCE(p_options_json->>'pay_channel_scope','ALL') NOT IN ('ALL','PAYE','UMBRELLA')
     OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_options_json) k(value) WHERE k.value<>'pay_channel_scope') THEN
    RAISE EXCEPTION 'BANKING_PAY_V2_INVALID_INPUT' USING ERRCODE='22023';
  END IF;
  -- END BANKING_PAY_MODAL_RECOVERY_SCOPE_VALIDATION_V2
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_ID_REQUIRED')::text;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status
            )::text;
  END IF;

  SELECT COALESCE(scope_row.certified_preview_publication_attestation_json, '{}'::jsonb)
  INTO v_scope_attestation
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_NOT_IN_SCOPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_NOT_IN_SCOPE',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text
            )::text;
  END IF;

  v_selection_intent_mode := UPPER(BTRIM(COALESCE(
    v_session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
    CASE
      WHEN COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
        THEN 'EXPLICIT_INCLUDE'
      ELSE 'IMPLICIT_ALL'
    END
  )));
  IF v_selection_intent_mode NOT IN ('IMPLICIT_ALL', 'EXPLICIT_INCLUDE') THEN
    v_selection_intent_mode := CASE
      WHEN COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
        THEN 'EXPLICIT_INCLUDE'
      ELSE 'IMPLICIT_ALL'
    END;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_nonterminal_line_count
  FROM public.banking_pay_workbench_candidate_line_work AS line_work
  WHERE line_work.session_id = p_session_id
    AND line_work.candidate_id = p_candidate_id
    AND UPPER(BTRIM(COALESCE(line_work.status, ''))) NOT IN (
      'MATERIALISED',
      'SKIPPED',
      'ERROR',
      'FAILED',
      'CANCELLED',
      'CANCELED',
      'SUPERSEDED',
      'RETIRED'
    );

  IF COALESCE(v_nonterminal_line_count, 0) > 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'action', 'DEFERRED_UNTIL_FINAL_MATERIALISATION',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'nonterminal_line_count', v_nonterminal_line_count,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    );
  END IF;

  -- BEGIN BANKING_PAY_MODAL_NON_V3_SCOPE_FENCE_V2
  IF COALESCE(p_options_json->>'pay_channel_scope','ALL')<>'ALL' AND NOT (
    COALESCE(v_scope_attestation->>'attestation_version','')='CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
    AND COALESCE(v_scope_attestation->>'contract_version','')='3'
    AND COALESCE(v_scope_attestation->>'semantic_contract_version','')='READY_TO_PAY_SEMANTIC_V2') THEN
    RAISE EXCEPTION 'BANKING_PAY_V2_DEPENDENCY_UNAVAILABLE' USING ERRCODE='P0001';
  END IF;
  -- END BANKING_PAY_MODAL_NON_V3_SCOPE_FENCE_V2
  -- V3 keeps the certified source/preview identity immutable.  Recovery
  -- readiness is a pre-Draft selection projection: it is recalculated from
  -- positive rows the candidate has actually selected, while the physical
  -- source-backed preview section remains unchanged for exact parity.
  IF v_scope_attestation->>'attestation_version' = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
     AND v_scope_attestation->>'contract_version' = '3'
     AND v_scope_attestation->>'semantic_contract_version' = 'READY_TO_PAY_SEMANTIC_V2' THEN
    v_v3_overlay_result := private.pay_workbench_recovery_selection_overlay_apply_v1(
      p_session_id,
      p_candidate_id,
      jsonb_build_object('reason', 'SELECTION_REVALIDATION') || p_options_json
    );

    RETURN COALESCE(v_v3_overlay_result, '{}'::jsonb)
      || jsonb_build_object(
        'legacy_physical_section_revalidation_skipped', true,
        'certified_source_preview_identity_preserved', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
  END IF;

  SELECT ROUND(COALESCE(SUM(
           CASE
             WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
               THEN GREATEST((preview_row.row_json->>'amount_ex_vat')::numeric, 0)
             ELSE 0::numeric
           END
         ), 0), 2)::numeric(12,2)
  INTO v_retained_positive_headroom
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id = p_session_id
    AND preview_row.session_version = COALESCE(v_session_row.version, 1)
    AND preview_row.candidate_id = p_candidate_id
    AND LOWER(BTRIM(COALESCE(preview_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
    AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
    AND (
      v_selection_intent_mode <> 'EXPLICIT_INCLUDE'
      OR (
        COALESCE(preview_row.selected, false) IS TRUE
        AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
      )
      OR (
        LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
      )
    )
    AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'line_type', preview_row.row_json->>'item_type', ''))) NOT IN (
      'MANUAL_DEBT_RECOVERY',
      'OVERPAYMENT_RECOVERY',
      'LOAN_REPAYMENT',
      'PAYMENT_ADVANCE_REPAYMENT'
    );

  IF COALESCE(v_retained_positive_headroom, 0) > 0 THEN
    /*
     * A recovery line may have been materialised before the candidate's final
     * positive correction carrier. In that order it is correctly emitted as
     * NO_PAY_HEADROOM, but the terminal candidate view is then stale once the
     * positive carrier exists. Reconcile the other direction here as well:
     * promote only rows whose sole blocker is NO_PAY_HEADROOM, allocate against
     * retained positive pay in the same pay channel, and leave every financial
     * amount sourced from the already-materialised pre-draft authority.
     */
    DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_ready_recovery_allocation;
    CREATE TEMP TABLE _tmp_pay_wb_ready_recovery_allocation ON COMMIT DROP AS
    WITH positive_by_channel AS (
      SELECT
        UPPER(BTRIM(COALESCE(
          positive_row.row_json->>'pay_channel',
          positive_row.row_json->>'current_pay_method',
          positive_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(COALESCE(SUM(
          CASE
            WHEN COALESCE(positive_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN GREATEST((positive_row.row_json->>'amount_ex_vat')::numeric, 0)
            ELSE 0::numeric
          END
        ), 0), 2)::numeric(12,2) AS positive_headroom_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS positive_row
      WHERE positive_row.session_id = p_session_id
        AND positive_row.session_version = COALESCE(v_session_row.version, 1)
        AND positive_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(positive_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(positive_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(positive_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(positive_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(positive_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          v_selection_intent_mode <> 'EXPLICIT_INCLUDE'
          OR (
            COALESCE(positive_row.selected, false) IS TRUE
            AND UPPER(BTRIM(COALESCE(positive_row.selection_state, ''))) = 'SELECTED'
          )
          OR (
            LOWER(BTRIM(COALESCE(positive_row.row_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            AND UPPER(BTRIM(COALESCE(positive_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
          )
        )
        AND UPPER(BTRIM(COALESCE(positive_row.row_json->>'line_type', positive_row.row_json->>'item_type', ''))) NOT IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
      GROUP BY UPPER(BTRIM(COALESCE(
        positive_row.row_json->>'pay_channel',
        positive_row.row_json->>'current_pay_method',
        positive_row.row_json->>'candidate_pay_method',
        ''
      )))
    ), ready_recovery AS (
      SELECT
        ready_row.id AS ready_preview_row_id,
        ready_row.row_key,
        ready_row.row_ordinal,
        ready_row.timesheet_id,
        ready_row.key_type,
        ready_row.key_value,
        ready_row.selected,
        ready_row.selection_state,
        COALESCE(ready_row.row_json, '{}'::jsonb) AS base_row_json,
        UPPER(BTRIM(COALESCE(
          ready_row.row_json->>'pay_channel',
          ready_row.row_json->>'current_pay_method',
          ready_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(
          CASE
            -- A33 (critic finding 2): the nominal due is the row's own uncapped nominal_due_amount_ex_vat when it
            -- carries one, the same basis private.pay_workbench_recovery_selection_overlay_apply_v1 uses. The
            -- per-component preview due below is the figure ALREADY capped by the earlier running total, so an
            -- exclusion could never release headroom to it (GBP80 due stayed GBP20). Rows without the field keep
            -- the previous derivation unchanged.
            WHEN COALESCE(ready_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             AND ABS((ready_row.row_json->>'nominal_due_amount_ex_vat')::numeric) > 0
              THEN ABS((ready_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
            WHEN COALESCE((
              SELECT SUM(
                CASE
                  WHEN COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
                    THEN ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric)
                  ELSE 0::numeric
                END
              )
              FROM jsonb_array_elements(
                CASE
                  WHEN jsonb_typeof(ready_row.row_json->'case_components') = 'array'
                    THEN ready_row.row_json->'case_components'
                  ELSE '[]'::jsonb
                END
              ) AS component_row(value)
            ), 0) > 0
              THEN (
                SELECT SUM(ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric))
                FROM jsonb_array_elements(ready_row.row_json->'case_components') AS component_row(value)
                WHERE COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              )
            WHEN COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             AND ABS((ready_row.row_json->>'amount_ex_vat')::numeric) > 0
              THEN ABS((ready_row.row_json->>'amount_ex_vat')::numeric)
            WHEN COALESCE(ready_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((ready_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}')::numeric)
            WHEN COALESCE(ready_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((ready_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
            ELSE 0::numeric
          END,
          2
        )::numeric(12,2) AS nominal_due_amount_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS ready_row
      WHERE ready_row.session_id = p_session_id
        AND ready_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(ready_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND UPPER(BTRIM(COALESCE(ready_row.row_json->>'line_type', ready_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        AND COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
        AND ROUND((ready_row.row_json->>'amount_ex_vat')::numeric, 2) < 0
    ), ranked_recovery AS (
      SELECT
        ready_recovery.*,
        COALESCE(positive_by_channel.positive_headroom_ex_vat, 0)::numeric(12,2) AS positive_headroom_ex_vat,
        COALESCE(SUM(
          CASE
            -- A33 (critic finding 2; APPROVED rule, roadmap "Product behaviour that remains fixed"): on this non-V3
            -- branch too, a repayment the Office explicitly excluded consumes no headroom, exactly as A30 M1 does in
            -- private.pay_workbench_recovery_selection_overlay_apply_v1 (GBP100 headroom, first GBP80 excluded, second
            -- GBP80 included -> the second receives GBP80, not GBP20). Every A33 edit in this function is marked A33.
            WHEN UPPER(BTRIM(COALESCE(ready_recovery.base_row_json->>'selection_user_override', ''))) = 'UNSELECTED'
              THEN 0::numeric
            ELSE ready_recovery.nominal_due_amount_ex_vat
          END
        ) OVER (
          PARTITION BY ready_recovery.pay_channel
          -- A34 (user rulings 25 Q6-A and 31; Worker BT): oldest debt first -- the SAME key and tie-break as the V3
          -- overlay and the canonical builder (Stage 3 WP3): creation date and time, a loan by its payout; ties by
          -- finance case id.  Was: row_ordinal, id (effectively reference order).
          ORDER BY private.s3p_recovery_order_key_v1(CASE WHEN ready_recovery.base_row_json->>'finance_case_id'
                     ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                     THEN (ready_recovery.base_row_json->>'finance_case_id')::uuid END) NULLS LAST,
                   ready_recovery.base_row_json->>'finance_case_id', ready_recovery.row_ordinal, ready_recovery.ready_preview_row_id
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 0)::numeric(12,2) AS prior_nominal_due_amount_ex_vat
      FROM ready_recovery
      LEFT JOIN positive_by_channel
        ON positive_by_channel.pay_channel = ready_recovery.pay_channel
      WHERE ready_recovery.pay_channel IN ('PAYE', 'UMBRELLA')
        AND ready_recovery.nominal_due_amount_ex_vat > 0
    ), allocated_recovery AS (
      SELECT
        ranked_recovery.*,
        ROUND(LEAST(
          ranked_recovery.nominal_due_amount_ex_vat,
          GREATEST(
            ranked_recovery.positive_headroom_ex_vat - ranked_recovery.prior_nominal_due_amount_ex_vat,
            0
          )
        ), 2)::numeric(12,2) AS recoverable_amount_ex_vat
      FROM ranked_recovery
    )
    SELECT
      allocated_recovery.*,
      ROUND(SUM(allocated_recovery.recoverable_amount_ex_vat) OVER (
        PARTITION BY allocated_recovery.pay_channel
      ), 2)::numeric(12,2) AS channel_recoverable_amount_ex_vat
    FROM allocated_recovery;

    WITH capped_source AS (
      SELECT
        allocation.ready_preview_row_id,
        allocation.base_row_json
          || jsonb_build_object(
            'amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'preview_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'amount_display', -allocation.recoverable_amount_ex_vat,
            'section_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'section_amount_display', -allocation.recoverable_amount_ex_vat,
            'target_pay_ex_vat', -allocation.recoverable_amount_ex_vat,
            'ready_preview_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'preview_component_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'nominal_due_amount_ex_vat', allocation.nominal_due_amount_ex_vat,
            'recoverable_this_pay_run_ex_vat', allocation.recoverable_amount_ex_vat,
            'recovery_group_recoverable_this_pay_run_ex_vat', allocation.channel_recoverable_amount_ex_vat,
            'materialisation_recovery_headroom_revalidated', true,
            'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
            'retained_positive_headroom_ex_vat', allocation.positive_headroom_ex_vat,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'case_resolution_summary', CASE
              WHEN jsonb_typeof(COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
                THEN COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)
                  || jsonb_build_object('due_amount_ex_vat', allocation.recoverable_amount_ex_vat)
              ELSE jsonb_build_object('due_amount_ex_vat', allocation.recoverable_amount_ex_vat)
            END
          ) AS capped_row_json
      FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
      WHERE allocation.recoverable_amount_ex_vat > 0
    ), contracted_source AS (
      SELECT
        capped_source.ready_preview_row_id,
        capped_source.capped_row_json,
        public.pay_workbench_preview_line_contract_ok(
          p_line_json => capped_source.capped_row_json,
          p_economic_key_json => COALESCE(capped_source.capped_row_json->'economic_key', '{}'::jsonb),
          p_target_section => 'canonical_preview_lines'
        ) AS capped_contract_json
      FROM capped_source
    )
    UPDATE public.banking_pay_workbench_preview_rows AS ready_row
    SET row_json = contracted_source.capped_row_json
          || jsonb_build_object(
            'preview_contract', contracted_source.capped_contract_json,
            'selection_allowed', true
          ),
        updated_at_utc = v_now
    FROM contracted_source
    WHERE ready_row.id = contracted_source.ready_preview_row_id
      AND LOWER(BTRIM(COALESCE(contracted_source.capped_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(contracted_source.capped_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

    GET DIAGNOSTICS v_ready_recovery_capped_count = ROW_COUNT;

    INSERT INTO public.banking_pay_workbench_preview_rows (
      session_id,
      candidate_id,
      section,
      row_key,
      row_ordinal,
      row_json,
      timesheet_id,
      key_type,
      key_value,
      selected,
      selection_state,
      status,
      session_version,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      p_session_id,
      p_candidate_id,
      'blocked_for_pay',
      allocation.row_key,
      allocation.row_ordinal,
      (
        allocation.base_row_json
        - 'source_basis_json'
        - 'frozen_source_basis_json'
        - 'frozen_component_snapshot_json'
        - 'finance_component_id'
        - 'materialised_from_line_work_id'
      )
      || jsonb_build_object(
        'line_key', allocation.row_key,
        'row_key', allocation.row_key,
        'presentation_line_id', allocation.row_key,
        'section', 'blocked_for_pay',
        'target_section', 'blocked_for_pay',
        'readiness_state', 'BLOCKED_FOR_PAY',
        'presentation_section', 'BLOCKED_FOR_PAY',
        'presentation_reason', 'NO_PAY_HEADROOM',
        'amount_ex_vat', 0,
        'preview_amount_ex_vat', 0,
        'amount_display', 0,
        'section_amount_ex_vat', 0,
        'section_amount_display', 0,
        'target_pay_ex_vat', 0,
        'ready_preview_amount_ex_vat', 0,
        'preview_component_amount_ex_vat', 0,
        'recoverable_this_pay_run_ex_vat', 0,
        'nominal_due_amount_ex_vat', allocation.nominal_due_amount_ex_vat,
        'draftable', false,
        'is_ready_for_draft', false,
        'selection_allowed', false,
        'is_excluded_from_allocation', true,
        'selected', false,
        'selection_state', 'NOT_SELECTABLE',
        'blocked_reason_codes', jsonb_build_array('NO_PAY_HEADROOM'),
        'materialisation_recovery_headroom_revalidated', true,
        'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
        'retained_positive_headroom_ex_vat', allocation.positive_headroom_ex_vat,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
        'case_resolution_summary', CASE
          WHEN jsonb_typeof(COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
            THEN COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)
              || jsonb_build_object('due_amount_ex_vat', 0)
          ELSE jsonb_build_object('due_amount_ex_vat', 0)
        END
      )
      || jsonb_build_object(
        'preview_contract', COALESCE(allocation.base_row_json->'preview_contract', '{}'::jsonb)
          || jsonb_build_object(
            'line_key', allocation.row_key,
            'amount_ex_vat', 0,
            'draftable', false,
            'is_ready_for_draft', false,
            'selection_allowed', false,
            'is_excluded_from_allocation', true,
            'target_section', 'blocked_for_pay',
            'presentation_section', 'BLOCKED_FOR_PAY'
          )
      ),
      allocation.timesheet_id,
      allocation.key_type,
      allocation.key_value,
      false,
      'NOT_SELECTABLE',
      'READY',
      COALESCE(v_session_row.version, 1),
      v_now,
      v_now
    FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
    WHERE allocation.recoverable_amount_ex_vat <= 0
    ON CONFLICT (session_id, section, candidate_id, row_key)
    DO UPDATE
    SET row_ordinal = EXCLUDED.row_ordinal,
        row_json = EXCLUDED.row_json,
        timesheet_id = EXCLUDED.timesheet_id,
        key_type = EXCLUDED.key_type,
        key_value = EXCLUDED.key_value,
        selected = false,
        selection_state = 'NOT_SELECTABLE',
        status = 'READY',
        session_version = EXCLUDED.session_version,
        updated_at_utc = v_now;

    GET DIAGNOSTICS v_ready_recovery_blocked_count = ROW_COUNT;

    UPDATE public.banking_pay_workbench_preview_rows AS ready_row
    SET status = 'SUPERSEDED',
        selected = false,
        selection_state = 'SUPERSEDED',
        row_json = COALESCE(ready_row.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'selected', false,
            'selection_state', 'SUPERSEDED',
            'superseded_reason', 'RECOVERY_EXCEEDS_SELECTED_POSITIVE_HEADROOM',
            'materialisation_recovery_headroom_revalidated', true,
            'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
          ),
        updated_at_utc = v_now
    WHERE ready_row.id IN (
      SELECT allocation.ready_preview_row_id
      FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
      WHERE allocation.recoverable_amount_ex_vat <= 0
    );

    IF COALESCE(v_ready_recovery_capped_count, 0) > 0
       OR COALESCE(v_ready_recovery_blocked_count, 0) > 0 THEN
      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET result_row_json = active_row.row_json,
          updated_at_utc = v_now
      FROM (
        SELECT ready_row.row_key, ready_row.row_json
        FROM public.banking_pay_workbench_preview_rows AS ready_row
        WHERE ready_row.session_id = p_session_id
          AND ready_row.session_version = COALESCE(v_session_row.version, 1)
          AND ready_row.candidate_id = p_candidate_id
          AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
          AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
        UNION ALL
        SELECT blocked_row.row_key, blocked_row.row_json
        FROM public.banking_pay_workbench_preview_rows AS blocked_row
        WHERE blocked_row.session_id = p_session_id
          AND blocked_row.session_version = COALESCE(v_session_row.version, 1)
          AND blocked_row.candidate_id = p_candidate_id
          AND LOWER(BTRIM(COALESCE(blocked_row.section, ''))) = 'blocked_for_pay'
          AND UPPER(BTRIM(COALESCE(blocked_row.status, ''))) = 'READY'
      ) AS active_row
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = p_candidate_id
        AND line_work.line_key = active_row.row_key
        AND EXISTS (
          SELECT 1
          FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
          WHERE allocation.row_key = line_work.line_key
        );
    END IF;

    WITH repair_source AS (
      SELECT
        ready_recovery_row.id,
        ready_recovery_row.row_json
          || jsonb_build_object(
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'materialisation_recovery_headroom_revalidated', true,
            'materialisation_recovery_headroom_revalidated_at_utc', v_now::text
          ) AS repaired_row_json
      FROM public.banking_pay_workbench_preview_rows AS ready_recovery_row
      WHERE ready_recovery_row.session_id = p_session_id
        AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_recovery_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'materialisation_recovery_headroom_revalidated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'line_type', ready_recovery_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    ), contracted_repair AS (
      SELECT
        repair_source.id,
        repair_source.repaired_row_json,
        public.pay_workbench_preview_line_contract_ok(
          p_line_json => repair_source.repaired_row_json,
          p_economic_key_json => COALESCE(repair_source.repaired_row_json->'economic_key', '{}'::jsonb),
          p_target_section => 'canonical_preview_lines'
        ) AS repaired_contract_json
      FROM repair_source
    )
    UPDATE public.banking_pay_workbench_preview_rows AS ready_recovery_row
    SET row_json = contracted_repair.repaired_row_json
          || jsonb_build_object(
            'preview_contract', contracted_repair.repaired_contract_json,
            'selection_allowed', true
          ),
        updated_at_utc = v_now
    FROM contracted_repair
    WHERE ready_recovery_row.id = contracted_repair.id
      AND LOWER(BTRIM(COALESCE(contracted_repair.repaired_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(contracted_repair.repaired_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

    GET DIAGNOSTICS v_repaired_authority_scope_count = ROW_COUNT;

    IF COALESCE(v_repaired_authority_scope_count, 0) > 0 THEN
      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET result_row_json = ready_recovery_row.row_json,
          updated_at_utc = v_now
      FROM public.banking_pay_workbench_preview_rows AS ready_recovery_row
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = p_candidate_id
        AND ready_recovery_row.session_id = p_session_id
        AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_recovery_row.candidate_id = p_candidate_id
        AND ready_recovery_row.updated_at_utc = v_now
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
        AND line_work.line_key = ready_recovery_row.row_key;
    END IF;

    DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_positive_headroom_recovery;
    CREATE TEMP TABLE _tmp_pay_wb_positive_headroom_recovery ON COMMIT DROP AS
    WITH gross_positive_by_channel AS (
      SELECT
        UPPER(BTRIM(COALESCE(
          preview_row.row_json->>'pay_channel',
          preview_row.row_json->>'current_pay_method',
          preview_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(COALESCE(SUM(
          CASE
            WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN GREATEST((preview_row.row_json->>'amount_ex_vat')::numeric, 0)
            ELSE 0::numeric
          END
        ), 0), 2)::numeric(12,2) AS positive_headroom_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS preview_row
      WHERE preview_row.session_id = p_session_id
        AND preview_row.session_version = COALESCE(v_session_row.version, 1)
        AND preview_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(preview_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          v_selection_intent_mode <> 'EXPLICIT_INCLUDE'
          OR (
            COALESCE(preview_row.selected, false) IS TRUE
            AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
          )
          OR (
            LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
          )
        )
        AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'line_type', preview_row.row_json->>'item_type', ''))) NOT IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
      GROUP BY UPPER(BTRIM(COALESCE(
        preview_row.row_json->>'pay_channel',
        preview_row.row_json->>'current_pay_method',
        preview_row.row_json->>'candidate_pay_method',
        ''
      )))
    ), ready_recovery_by_channel AS (
      SELECT
        UPPER(BTRIM(COALESCE(
          ready_recovery_row.row_json->>'pay_channel',
          ready_recovery_row.row_json->>'current_pay_method',
          ready_recovery_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(COALESCE(SUM(
          CASE
            WHEN COALESCE(ready_recovery_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS(LEAST((ready_recovery_row.row_json->>'amount_ex_vat')::numeric, 0))
            ELSE 0::numeric
          END
        ), 0), 2)::numeric(12,2) AS allocated_recovery_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS ready_recovery_row
      WHERE ready_recovery_row.session_id = p_session_id
        AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_recovery_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'line_type', ready_recovery_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        -- A33 (critic finding 2): an explicitly excluded READY repayment consumes no headroom here either, so the
        -- NO_PAY_HEADROOM promotion pass below can give the released headroom to a later included repayment.
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'selection_user_override', ''))) <> 'UNSELECTED'
      GROUP BY UPPER(BTRIM(COALESCE(
        ready_recovery_row.row_json->>'pay_channel',
        ready_recovery_row.row_json->>'current_pay_method',
        ready_recovery_row.row_json->>'candidate_pay_method',
        ''
      )))
    ), positive_by_channel AS (
      SELECT
        gross_positive.pay_channel,
        ROUND(GREATEST(
          gross_positive.positive_headroom_ex_vat
            - COALESCE(ready_recovery.allocated_recovery_ex_vat, 0),
          0
        ), 2)::numeric(12,2) AS positive_headroom_ex_vat
      FROM gross_positive_by_channel AS gross_positive
      LEFT JOIN ready_recovery_by_channel AS ready_recovery
        ON ready_recovery.pay_channel = gross_positive.pay_channel
    ), blocked_recovery AS (
      SELECT
        blocked_row.id AS blocked_preview_row_id,
        blocked_row.candidate_id,
        blocked_row.row_key,
        blocked_row.row_ordinal,
        blocked_row.timesheet_id,
        blocked_row.key_type,
        blocked_row.key_value,
        blocked_row.row_json AS base_row_json,
        UPPER(BTRIM(COALESCE(
          blocked_row.row_json->>'pay_channel',
          blocked_row.row_json->>'current_pay_method',
          blocked_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(
          CASE
            -- A33 (critic finding 2): the nominal due is the row's own uncapped nominal_due_amount_ex_vat when it
            -- carries one, the same basis private.pay_workbench_recovery_selection_overlay_apply_v1 uses. The
            -- per-component preview due below is the figure ALREADY capped by the earlier running total, so an
            -- exclusion could never release headroom to it (GBP80 due stayed GBP20). Rows without the field keep
            -- the previous derivation unchanged.
            WHEN COALESCE(blocked_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             AND ABS((blocked_row.row_json->>'nominal_due_amount_ex_vat')::numeric) > 0
              THEN ABS((blocked_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
            WHEN COALESCE((
              SELECT SUM(
                CASE
                  WHEN COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
                    THEN ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric)
                  ELSE 0::numeric
                END
              )
              FROM jsonb_array_elements(
                CASE
                  WHEN jsonb_typeof(blocked_row.row_json->'case_components') = 'array'
                    THEN blocked_row.row_json->'case_components'
                  ELSE '[]'::jsonb
                END
              ) AS component_row(value)
            ), 0) > 0
              THEN (
                SELECT SUM(ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric))
                FROM jsonb_array_elements(blocked_row.row_json->'case_components') AS component_row(value)
                WHERE COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              )
            WHEN COALESCE(blocked_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             AND ABS((blocked_row.row_json->>'amount_ex_vat')::numeric) > 0
              THEN ABS((blocked_row.row_json->>'amount_ex_vat')::numeric)
            WHEN COALESCE(blocked_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((blocked_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}')::numeric)
            WHEN COALESCE(blocked_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((blocked_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
            ELSE 0::numeric
          END,
          2
        )::numeric(12,2) AS nominal_due_amount_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS blocked_row
      WHERE blocked_row.session_id = p_session_id
        AND blocked_row.session_version = COALESCE(v_session_row.version, 1)
        AND blocked_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(blocked_row.section, ''))) = 'blocked_for_pay'
        AND UPPER(BTRIM(COALESCE(blocked_row.status, ''))) = 'READY'
        AND UPPER(BTRIM(COALESCE(blocked_row.row_json->>'line_type', blocked_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        AND (
          UPPER(BTRIM(COALESCE(blocked_row.row_json->>'presentation_reason', ''))) = 'NO_PAY_HEADROOM'
          OR COALESCE(blocked_row.row_json->'blocked_reason_codes', '[]'::jsonb) @> jsonb_build_array('NO_PAY_HEADROOM')
        )
        AND LOWER(BTRIM(COALESCE(blocked_row.row_json->>'case_is_blocked', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(blocked_row.row_json->>'case_needs_resolution_now', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          LOWER(BTRIM(COALESCE(blocked_row.row_json->>'case_resolution_satisfied_now', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR UPPER(BTRIM(COALESCE(blocked_row.row_json->>'resolution_state', ''))) = 'RESOLVED'
          OR LOWER(BTRIM(COALESCE(blocked_row.row_json->>'is_case_resolution_satisfied', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        )
        AND NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(blocked_row.row_json->'blocked_reason_codes') = 'array'
                THEN blocked_row.row_json->'blocked_reason_codes'
              ELSE '[]'::jsonb
            END
          ) AS blocked_code(value)
          WHERE UPPER(BTRIM(blocked_code.value)) <> 'NO_PAY_HEADROOM'
        )
    ), ranked_recovery AS (
      SELECT
        blocked_recovery.*,
        COALESCE(positive_by_channel.positive_headroom_ex_vat, 0)::numeric(12,2) AS positive_headroom_ex_vat,
        COALESCE(SUM(
          CASE
            -- A33 (critic finding 2; APPROVED rule, roadmap "Product behaviour that remains fixed"): on this non-V3
            -- branch too, a repayment the Office explicitly excluded consumes no headroom, exactly as A30 M1 does in
            -- private.pay_workbench_recovery_selection_overlay_apply_v1 (GBP100 headroom, first GBP80 excluded, second
            -- GBP80 included -> the second receives GBP80, not GBP20). Every A33 edit in this function is marked A33.
            WHEN UPPER(BTRIM(COALESCE(blocked_recovery.base_row_json->>'selection_user_override', ''))) = 'UNSELECTED'
              THEN 0::numeric
            ELSE blocked_recovery.nominal_due_amount_ex_vat
          END
        ) OVER (
          PARTITION BY blocked_recovery.pay_channel
          -- A34 (user rulings 25 Q6-A and 31; Worker BT): oldest debt first -- the SAME key and tie-break as the V3
          -- overlay and the canonical builder (Stage 3 WP3): creation date and time, a loan by its payout; ties by
          -- finance case id.  Was: row_ordinal, id (effectively reference order).
          ORDER BY private.s3p_recovery_order_key_v1(CASE WHEN blocked_recovery.base_row_json->>'finance_case_id'
                     ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                     THEN (blocked_recovery.base_row_json->>'finance_case_id')::uuid END) NULLS LAST,
                   blocked_recovery.base_row_json->>'finance_case_id', blocked_recovery.row_ordinal, blocked_recovery.blocked_preview_row_id
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 0)::numeric(12,2) AS prior_nominal_due_amount_ex_vat
      FROM blocked_recovery
      LEFT JOIN positive_by_channel
        ON positive_by_channel.pay_channel = blocked_recovery.pay_channel
      WHERE blocked_recovery.pay_channel IN ('PAYE', 'UMBRELLA')
        AND ROUND(COALESCE(blocked_recovery.nominal_due_amount_ex_vat, 0), 2) > 0
    ), allocated_recovery AS (
      SELECT
        ranked_recovery.*,
        ROUND(LEAST(
          ranked_recovery.nominal_due_amount_ex_vat,
          GREATEST(
            ranked_recovery.positive_headroom_ex_vat - ranked_recovery.prior_nominal_due_amount_ex_vat,
            0
          )
        ), 2)::numeric(12,2) AS recoverable_amount_ex_vat
      FROM ranked_recovery
    )
    SELECT
      allocated_recovery.*,
      COALESCE(existing_ready.id, gen_random_uuid()) AS promoted_preview_row_id,
      CASE
        WHEN UPPER(BTRIM(COALESCE(
          allocated_recovery.base_row_json->>'selection_user_override',
          existing_ready.row_json->>'selection_user_override',
          ''
        ))) = 'UNSELECTED'
          THEN false
        ELSE true
      END AS promoted_selected
    FROM allocated_recovery
    LEFT JOIN public.banking_pay_workbench_preview_rows AS existing_ready
      ON existing_ready.session_id = p_session_id
     AND existing_ready.session_version = COALESCE(v_session_row.version, 1)
     AND existing_ready.candidate_id = p_candidate_id
     AND LOWER(BTRIM(COALESCE(existing_ready.section, ''))) = 'canonical_preview_lines'
     AND existing_ready.row_key = allocated_recovery.row_key
    WHERE allocated_recovery.recoverable_amount_ex_vat > 0;

    SELECT COUNT(*)::integer,
           COUNT(*) FILTER (WHERE promoted_selected)::integer
    INTO v_promoted_count,
         v_promoted_selected_count
    FROM pg_temp._tmp_pay_wb_positive_headroom_recovery;

    IF COALESCE(v_promoted_count, 0) > 0 THEN
      WITH promoted_payload AS (
        SELECT
          promotion.*,
          jsonb_strip_nulls(
            (
              promotion.base_row_json
              - 'blocked_reason_codes'
              - 'superseded_reason'
              - 'materialisation_recovery_headroom_revalidated'
              - 'materialisation_recovery_headroom_revalidated_at_utc'
            )
            || jsonb_build_object(
              'preview_row_id', promotion.promoted_preview_row_id::text,
              'line_id', promotion.promoted_preview_row_id::text,
              'section', 'canonical_preview_lines',
              'target_section', 'canonical_preview_lines',
              'readiness_state', 'READY',
              'presentation_section', 'READY_TO_PAY',
              'presentation_reason', NULL,
              'amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'preview_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'amount_display', -promotion.recoverable_amount_ex_vat,
              'section_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'section_amount_display', -promotion.recoverable_amount_ex_vat,
              'target_pay_ex_vat', -promotion.recoverable_amount_ex_vat,
              'ready_preview_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'preview_component_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'nominal_due_amount_ex_vat', promotion.nominal_due_amount_ex_vat,
              'recoverable_this_pay_run_ex_vat', promotion.recoverable_amount_ex_vat,
              'draftable', true,
              'is_ready_for_draft', true,
              'selection_allowed', true,
              'is_excluded_from_allocation', false,
              'selected', promotion.promoted_selected,
              'selection_state', CASE WHEN promotion.promoted_selected THEN 'SELECTED' ELSE 'UNSELECTED' END,
              'selection_origin', CASE
                WHEN UPPER(BTRIM(COALESCE(promotion.base_row_json->>'selection_user_override', ''))) = 'UNSELECTED'
                  THEN 'USER_EXPLICIT_DESELECT'
                ELSE 'SERVER_DEFAULT_NEWLY_ELIGIBLE'
              END,
              'materialisation_recovery_headroom_revalidated', true,
              'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
              'retained_positive_headroom_ex_vat', promotion.positive_headroom_ex_vat,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
            || jsonb_build_object(
              'case_resolution_summary', CASE
                WHEN jsonb_typeof(COALESCE(promotion.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
                  THEN COALESCE(promotion.base_row_json->'case_resolution_summary', '{}'::jsonb)
                    || jsonb_build_object('due_amount_ex_vat', promotion.recoverable_amount_ex_vat)
                ELSE jsonb_build_object('due_amount_ex_vat', promotion.recoverable_amount_ex_vat)
              END
            )
          ) AS promoted_row_json
        FROM pg_temp._tmp_pay_wb_positive_headroom_recovery AS promotion
      ), contracted_payload AS (
        SELECT
          promoted_payload.*,
          public.pay_workbench_preview_line_contract_ok(
            p_line_json => promoted_payload.promoted_row_json,
            p_economic_key_json => COALESCE(promoted_payload.promoted_row_json->'economic_key', '{}'::jsonb),
            p_target_section => 'canonical_preview_lines'
          ) AS promoted_contract_json
        FROM promoted_payload
      )
      INSERT INTO public.banking_pay_workbench_preview_rows (
        id,
        session_id,
        candidate_id,
        section,
        row_key,
        row_ordinal,
        row_json,
        timesheet_id,
        key_type,
        key_value,
        selected,
        selection_state,
        status,
        session_version,
        created_at_utc,
        updated_at_utc
      )
      SELECT
        contracted_payload.promoted_preview_row_id,
        p_session_id,
        p_candidate_id,
        'canonical_preview_lines',
        contracted_payload.row_key,
        contracted_payload.row_ordinal,
        contracted_payload.promoted_row_json
          || jsonb_build_object(
            'preview_contract', contracted_payload.promoted_contract_json,
            'selection_allowed', true
          ),
        contracted_payload.timesheet_id,
        contracted_payload.key_type,
        contracted_payload.key_value,
        contracted_payload.promoted_selected,
        CASE WHEN contracted_payload.promoted_selected THEN 'SELECTED' ELSE 'UNSELECTED' END,
        'READY',
        COALESCE(v_session_row.version, 1),
        v_now,
        v_now
      FROM contracted_payload
      WHERE LOWER(BTRIM(COALESCE(contracted_payload.promoted_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(contracted_payload.promoted_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      ON CONFLICT (session_id, section, candidate_id, row_key)
      DO UPDATE
      SET row_ordinal = EXCLUDED.row_ordinal,
          row_json = EXCLUDED.row_json,
          timesheet_id = EXCLUDED.timesheet_id,
          key_type = EXCLUDED.key_type,
          key_value = EXCLUDED.key_value,
          selected = EXCLUDED.selected,
          selection_state = EXCLUDED.selection_state,
          status = 'READY',
          session_version = EXCLUDED.session_version,
          updated_at_utc = v_now;

      UPDATE public.banking_pay_workbench_preview_rows AS blocked_row
      SET status = 'SUPERSEDED',
          selected = false,
          selection_state = 'SUPERSEDED',
          row_json = COALESCE(blocked_row.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'selected', false,
              'selection_state', 'SUPERSEDED',
              'superseded_reason', 'POSITIVE_PAY_HEADROOM_AVAILABLE_AFTER_FINAL_MATERIALISATION',
              'materialisation_recovery_headroom_revalidated', true,
              'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
            ),
          updated_at_utc = v_now
      WHERE blocked_row.id IN (
        SELECT promotion.blocked_preview_row_id
        FROM pg_temp._tmp_pay_wb_positive_headroom_recovery AS promotion
      );

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET result_row_json = ready_row.row_json,
          updated_at_utc = v_now
      FROM public.banking_pay_workbench_preview_rows AS ready_row
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = p_candidate_id
        AND ready_row.session_id = p_session_id
        AND ready_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
        AND ready_row.row_key = line_work.line_key
        AND EXISTS (
          SELECT 1
          FROM pg_temp._tmp_pay_wb_positive_headroom_recovery AS promotion
          WHERE promotion.row_key = line_work.line_key
        );

      v_progress_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id,
        true,
        'POST_MATERIALISATION_RECOVERY_HEADROOM_PROMOTION',
        false
      );

      SELECT COALESCE(jsonb_agg(to_jsonb(selected_row.id::text) ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb),
             COUNT(*)::integer
      INTO v_selected_preview_row_ids,
           v_selected_row_count
      FROM public.banking_pay_workbench_preview_rows AS selected_row
      WHERE selected_row.session_id = p_session_id
        AND selected_row.session_version = COALESCE(v_session_row.version, 1)
        AND LOWER(BTRIM(COALESCE(selected_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(selected_row.status, ''))) = 'READY'
        AND COALESCE(selected_row.selected, false) = true
        AND UPPER(BTRIM(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

      v_selection_intent_mode := UPPER(BTRIM(COALESCE(
        v_session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
        ''
      )));

      UPDATE public.banking_pay_workbench_sessions AS session_row
      SET selected_row_count = COALESCE(v_selected_row_count, 0),
          server_selected_preview_row_ids = CASE
            WHEN v_selection_intent_mode = 'EXPLICIT_INCLUDE'
              OR COALESCE(session_row.server_selected_preview_row_ids_provided, false) IS TRUE
              THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
            ELSE session_row.server_selected_preview_row_ids
          END,
          progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_recovery_headroom_revalidation_at_utc', v_now::text,
              'last_recovery_headroom_revalidation_action', 'PROMOTED_RECOVERY_WITH_RETAINED_POSITIVE_PAY',
              'last_recovery_headroom_revalidation_candidate_id', p_candidate_id::text,
              'last_recovery_headroom_revalidation_promoted_count', COALESCE(v_promoted_count, 0),
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
            ),
          updated_at_utc = v_now
      WHERE session_row.id = p_session_id;

      RETURN jsonb_build_object(
        'ok', true,
        'action', 'PROMOTED_RECOVERY_WITH_RETAINED_POSITIVE_PAY',
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
        'promoted_recovery_count', COALESCE(v_promoted_count, 0),
        'promoted_selected_count', COALESCE(v_promoted_selected_count, 0),
        'repaired_authority_scope_count', COALESCE(v_repaired_authority_scope_count, 0),
        'capped_ready_recovery_count', COALESCE(v_ready_recovery_capped_count, 0),
        'blocked_excess_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
        'selected_row_count', COALESCE(v_selected_row_count, 0),
        'progress_recomputed', COALESCE(v_progress_json, '{}'::jsonb),
        'demoted_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
        'post_draft_artifacts_touched', false,
        'payment_execution_started', false
      );
    END IF;

    IF COALESCE(v_ready_recovery_capped_count, 0) > 0
       OR COALESCE(v_ready_recovery_blocked_count, 0) > 0 THEN
      v_progress_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id,
        true,
        'POST_MATERIALISATION_RECOVERY_HEADROOM_CAP',
        false
      );

      SELECT COALESCE(jsonb_agg(to_jsonb(selected_row.id::text) ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb),
             COUNT(*)::integer
      INTO v_selected_preview_row_ids,
           v_selected_row_count
      FROM public.banking_pay_workbench_preview_rows AS selected_row
      WHERE selected_row.session_id = p_session_id
        AND selected_row.session_version = COALESCE(v_session_row.version, 1)
        AND LOWER(BTRIM(COALESCE(selected_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(selected_row.status, ''))) = 'READY'
        AND COALESCE(selected_row.selected, false) IS TRUE
        AND UPPER(BTRIM(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

      UPDATE public.banking_pay_workbench_sessions AS session_row
      SET selected_row_count = COALESCE(v_selected_row_count, 0),
          server_selected_preview_row_ids = CASE
            WHEN v_selection_intent_mode = 'EXPLICIT_INCLUDE'
              OR COALESCE(session_row.server_selected_preview_row_ids_provided, false) IS TRUE
              THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
            ELSE session_row.server_selected_preview_row_ids
          END,
          progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_recovery_headroom_revalidation_at_utc', v_now::text,
              'last_recovery_headroom_revalidation_action', 'CAPPED_READY_RECOVERY_TO_POSITIVE_HEADROOM',
              'last_recovery_headroom_revalidation_candidate_id', p_candidate_id::text,
              'last_recovery_headroom_revalidation_capped_count', COALESCE(v_ready_recovery_capped_count, 0),
              'last_recovery_headroom_revalidation_blocked_excess_count', COALESCE(v_ready_recovery_blocked_count, 0),
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
            ),
          updated_at_utc = v_now
      WHERE session_row.id = p_session_id;
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'action', CASE
        WHEN COALESCE(v_repaired_authority_scope_count, 0) > 0
          THEN 'REPAIRED_EXISTING_RECOVERY_AUTHORITY_SCOPE'
        ELSE 'RETAINED_POSITIVE_PAY_PRESENT'
      END,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
      'promoted_recovery_count', 0,
      'repaired_authority_scope_count', COALESCE(v_repaired_authority_scope_count, 0),
      'capped_ready_recovery_count', COALESCE(v_ready_recovery_capped_count, 0),
      'blocked_excess_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
      'selected_row_count', COALESCE(v_selected_row_count, 0),
      'progress_recomputed', COALESCE(v_progress_json, '{}'::jsonb),
      'demoted_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
      'post_draft_artifacts_touched', false,
      'payment_execution_started', false
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_zero_headroom_recovery;
  CREATE TEMP TABLE _tmp_pay_wb_zero_headroom_recovery ON COMMIT DROP AS
  SELECT ready_row.id AS ready_preview_row_id,
         ready_row.row_key AS ready_row_key,
         ready_row.row_json->>'finance_case_id' AS finance_case_id_text,
         UPPER(BTRIM(COALESCE(ready_row.row_json->>'line_type', ready_row.row_json->>'item_type', ''))) AS line_type,
         ready_row.row_ordinal,
         ready_row.timesheet_id,
         ready_row.key_type,
         ready_row.key_value,
         ready_row.row_key AS blocked_row_key,
         COALESCE(blocked_template.row_json, ready_row.row_json, '{}'::jsonb) AS base_row_json,
         CASE
           WHEN COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            AND ABS((ready_row.row_json->>'amount_ex_vat')::numeric) > 0
             THEN ROUND(ABS((ready_row.row_json->>'amount_ex_vat')::numeric), 2)
           WHEN COALESCE((
             SELECT SUM(
               CASE
                 WHEN COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
                   THEN ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric)
                 ELSE 0::numeric
               END
             )
             FROM jsonb_array_elements(
               CASE
                 WHEN jsonb_typeof(ready_row.row_json->'case_components') = 'array'
                   THEN ready_row.row_json->'case_components'
                 ELSE '[]'::jsonb
               END
             ) AS component_row(value)
           ), 0) > 0
             THEN ROUND((
               SELECT SUM(ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric))
               FROM jsonb_array_elements(ready_row.row_json->'case_components') AS component_row(value)
               WHERE COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             ), 2)
           WHEN COALESCE(ready_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             THEN ROUND(ABS((ready_row.row_json->>'nominal_due_amount_ex_vat')::numeric), 2)
           ELSE 0::numeric
         END::numeric(12,2) AS nominal_due_amount_ex_vat
  FROM public.banking_pay_workbench_preview_rows AS ready_row
  LEFT JOIN LATERAL (
    SELECT blocked_row.row_key,
           blocked_row.row_json
    FROM public.banking_pay_workbench_preview_rows AS blocked_row
    WHERE blocked_row.session_id = ready_row.session_id
      AND blocked_row.session_version = ready_row.session_version
      AND blocked_row.candidate_id = ready_row.candidate_id
      AND LOWER(BTRIM(COALESCE(blocked_row.section, ''))) = 'blocked_for_pay'
      AND blocked_row.row_key = ready_row.row_key
    ORDER BY CASE WHEN UPPER(BTRIM(COALESCE(blocked_row.status, ''))) = 'READY' THEN 0 ELSE 1 END,
             blocked_row.updated_at_utc DESC,
             blocked_row.id
    LIMIT 1
  ) AS blocked_template ON true
  WHERE ready_row.session_id = p_session_id
    AND ready_row.session_version = COALESCE(v_session_row.version, 1)
    AND ready_row.candidate_id = p_candidate_id
    AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
    AND ready_row.row_json->>'finance_case_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    AND UPPER(BTRIM(COALESCE(ready_row.row_json->>'line_type', ready_row.row_json->>'item_type', ''))) IN (
      'MANUAL_DEBT_RECOVERY',
      'OVERPAYMENT_RECOVERY',
      'LOAN_REPAYMENT',
      'PAYMENT_ADVANCE_REPAYMENT'
    )
    AND COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
    AND ROUND((ready_row.row_json->>'amount_ex_vat')::numeric, 2) < 0
  ORDER BY ready_row.row_ordinal,
           ready_row.id;

  SELECT COUNT(*)::integer
  INTO v_recovery_group_count
  FROM pg_temp._tmp_pay_wb_zero_headroom_recovery;

  IF COALESCE(v_recovery_group_count, 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'action', 'NO_READY_RECOVERY_TO_REVALIDATE',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
      'demoted_recovery_count', 0,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    );
  END IF;

  INSERT INTO public.banking_pay_workbench_preview_rows (
    session_id,
    candidate_id,
    section,
    row_key,
    row_ordinal,
    row_json,
    timesheet_id,
    key_type,
    key_value,
    selected,
    selection_state,
    status,
    session_version,
    created_at_utc,
    updated_at_utc
  )
  SELECT
    p_session_id,
    p_candidate_id,
    'blocked_for_pay',
    recovery_row.blocked_row_key,
    recovery_row.row_ordinal,
    (
      recovery_row.base_row_json
      - 'source_basis_json'
      - 'frozen_source_basis_json'
      - 'frozen_component_snapshot_json'
      - 'finance_component_id'
      - 'materialised_from_line_work_id'
    )
    || jsonb_build_object(
      'line_key', recovery_row.blocked_row_key,
      'row_key', recovery_row.blocked_row_key,
      'presentation_line_id', recovery_row.blocked_row_key,
      'presentation_parent_line_id', NULL,
      'section', 'blocked_for_pay',
      'target_section', 'blocked_for_pay',
      'readiness_state', 'BLOCKED_FOR_PAY',
      'presentation_section', 'BLOCKED_FOR_PAY',
      'presentation_reason', 'NO_PAY_HEADROOM',
      'amount_ex_vat', 0,
      'preview_amount_ex_vat', 0,
      'amount_display', 0,
      'section_amount_ex_vat', 0,
      'section_amount_display', 0,
      'target_pay_ex_vat', 0,
      'ready_preview_amount_ex_vat', 0,
      'preview_component_amount_ex_vat', 0,
      'source_amount_ex_vat', 0,
      'source_reservation_amount_ex_vat', 0,
      'frozen_source_amount', 0,
      'frozen_target_amount_ex_vat', 0,
      'nominal_due_amount_ex_vat', recovery_row.nominal_due_amount_ex_vat,
      'recoverable_this_pay_run_ex_vat', 0,
      'draftable', false,
      'is_ready_for_draft', false,
      'selection_allowed', false,
      'is_excluded_from_allocation', true,
      'selected', false,
      'selection_state', 'NOT_SELECTABLE',
      'blocked_reason_codes', CASE
        WHEN jsonb_typeof(COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb)) <> 'array'
          THEN jsonb_build_array('NO_PAY_HEADROOM')
        WHEN COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb) @> jsonb_build_array('NO_PAY_HEADROOM')
          THEN COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb)
        ELSE COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb) || jsonb_build_array('NO_PAY_HEADROOM')
      END,
      'materialisation_recovery_headroom_revalidated', true,
      'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
      'retained_positive_headroom_ex_vat', 0,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    )
    || jsonb_build_object(
      'preview_contract', COALESCE(recovery_row.base_row_json->'preview_contract', '{}'::jsonb)
        || jsonb_build_object(
          'line_key', recovery_row.blocked_row_key,
          'amount_ex_vat', 0,
          'draftable', false,
          'is_ready_for_draft', false,
          'selection_allowed', false,
          'is_excluded_from_allocation', true,
          'target_section', 'blocked_for_pay',
          'presentation_section', 'BLOCKED_FOR_PAY'
        ),
      'case_resolution_summary', CASE
        WHEN jsonb_typeof(COALESCE(recovery_row.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
          THEN COALESCE(recovery_row.base_row_json->'case_resolution_summary', '{}'::jsonb)
            || jsonb_build_object('due_amount_ex_vat', 0)
        ELSE jsonb_build_object('due_amount_ex_vat', 0)
      END
    ),
    recovery_row.timesheet_id,
    recovery_row.key_type,
    recovery_row.key_value,
    false,
    'NOT_SELECTABLE',
    'READY',
    COALESCE(v_session_row.version, 1),
    v_now,
    v_now
  FROM pg_temp._tmp_pay_wb_zero_headroom_recovery AS recovery_row
  ON CONFLICT (session_id, section, candidate_id, row_key)
  DO UPDATE
  SET row_ordinal = EXCLUDED.row_ordinal,
      row_json = EXCLUDED.row_json,
      timesheet_id = EXCLUDED.timesheet_id,
      key_type = EXCLUDED.key_type,
      key_value = EXCLUDED.key_value,
      selected = false,
      selection_state = 'NOT_SELECTABLE',
      status = 'READY',
      session_version = EXCLUDED.session_version,
      updated_at_utc = v_now;

  GET DIAGNOSTICS v_demoted_count = ROW_COUNT;

  UPDATE public.banking_pay_workbench_preview_rows AS ready_recovery_row
  SET status = 'SUPERSEDED',
      selected = false,
      selection_state = 'SUPERSEDED',
      row_json = COALESCE(ready_recovery_row.row_json, '{}'::jsonb)
        || jsonb_build_object(
          'selected', false,
          'selection_state', 'SUPERSEDED',
          'materialisation_recovery_headroom_revalidated', true,
          'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
          'retained_positive_headroom_ex_vat', 0,
          'superseded_reason', 'NO_PAY_HEADROOM_AFTER_FINAL_MATERIALISATION',
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
        ),
      updated_at_utc = v_now
  WHERE ready_recovery_row.session_id = p_session_id
    AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
    AND ready_recovery_row.candidate_id = p_candidate_id
    AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
    AND EXISTS (
      SELECT 1
      FROM pg_temp._tmp_pay_wb_zero_headroom_recovery AS recovery_row
      WHERE recovery_row.ready_preview_row_id = ready_recovery_row.id
    );

  GET DIAGNOSTICS v_superseded_count = ROW_COUNT;

  UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
  SET result_row_json = COALESCE(line_work.result_row_json, '{}'::jsonb)
        || jsonb_build_object(
          'section', 'blocked_for_pay',
          'target_section', 'blocked_for_pay',
          'readiness_state', 'BLOCKED_FOR_PAY',
          'presentation_section', 'BLOCKED_FOR_PAY',
          'presentation_reason', 'NO_PAY_HEADROOM',
          'amount_ex_vat', 0,
          'preview_amount_ex_vat', 0,
          'amount_display', 0,
          'target_pay_ex_vat', 0,
          'recoverable_this_pay_run_ex_vat', 0,
          'draftable', false,
          'is_ready_for_draft', false,
          'selection_allowed', false,
          'is_excluded_from_allocation', true,
          'selected', false,
          'selection_state', 'NOT_SELECTABLE',
          'blocked_reason_codes', CASE
            WHEN jsonb_typeof(COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb)) <> 'array'
              THEN jsonb_build_array('NO_PAY_HEADROOM')
            WHEN COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb) @> jsonb_build_array('NO_PAY_HEADROOM')
              THEN COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb)
            ELSE COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb) || jsonb_build_array('NO_PAY_HEADROOM')
          END,
          'materialisation_recovery_headroom_revalidated', true,
          'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
          'retained_positive_headroom_ex_vat', 0,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
        ),
      updated_at_utc = v_now
  WHERE line_work.session_id = p_session_id
    AND line_work.candidate_id = p_candidate_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp._tmp_pay_wb_zero_headroom_recovery AS recovery_row
      WHERE recovery_row.ready_row_key = line_work.line_key
    );

  GET DIAGNOSTICS v_line_work_revalidated_count = ROW_COUNT;

  v_progress_json := public.pay_workbench_session_recompute_progress_counters(
    p_session_id,
    true,
    'POST_MATERIALISATION_RECOVERY_HEADROOM_REVALIDATION',
    false
  );

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_row.id::text) ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_selected_preview_row_ids,
       v_selected_row_count
  FROM public.banking_pay_workbench_preview_rows AS selected_row
  WHERE selected_row.session_id = p_session_id
    AND selected_row.session_version = COALESCE(v_session_row.version, 1)
    AND LOWER(BTRIM(COALESCE(selected_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(selected_row.status, ''))) = 'READY'
    AND COALESCE(selected_row.selected, false) = true
    AND UPPER(BTRIM(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

  v_selection_intent_mode := UPPER(BTRIM(COALESCE(
    v_session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
    ''
  )));

  UPDATE public.banking_pay_workbench_sessions AS session_row
  SET selected_row_count = COALESCE(v_selected_row_count, 0),
      server_selected_preview_row_ids = CASE
        WHEN v_selection_intent_mode = 'EXPLICIT_INCLUDE'
          OR COALESCE(session_row.server_selected_preview_row_ids_provided, false) IS TRUE
          THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
        ELSE session_row.server_selected_preview_row_ids
      END,
      progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_recovery_headroom_revalidation_at_utc', v_now::text,
          'last_recovery_headroom_revalidation_action', 'DEMOTED_ZERO_RETAINED_HEADROOM',
          'last_recovery_headroom_revalidation_candidate_id', p_candidate_id::text,
          'last_recovery_headroom_revalidation_demoted_count', COALESCE(v_demoted_count, 0),
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
        ),
      updated_at_utc = v_now
  WHERE session_row.id = p_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'action', 'DEMOTED_ZERO_RETAINED_HEADROOM',
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
    'recovery_group_count', COALESCE(v_recovery_group_count, 0),
    'demoted_recovery_count', COALESCE(v_demoted_count, 0),
    'superseded_ready_recovery_count', COALESCE(v_superseded_count, 0),
    'line_work_revalidated_count', COALESCE(v_line_work_revalidated_count, 0),
    'selected_row_count', COALESCE(v_selected_row_count, 0),
    'progress_recomputed', COALESCE(v_progress_json, '{}'::jsonb),
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
    'post_draft_artifacts_touched', false,
    'payment_execution_started', false
  );
END;
$function$;

commit;

